local _, ns = ...
-- Simplified Chinese translations of the English narratives in Narratives.lua.
-- Machine-assisted (local Qwen3 8B, with DeepSeek rewrites of flagged entries);
-- names follow the official zhCN client terminology.
local narratives = ns.Narratives or {}
local function zh(id, text) if narratives[id] then narratives[id].zh = text end end
zh(2,"角鹰兽的利爪，便是灰谷狩猎得胜的凭据。塞娜尼要亲眼验过战利品，才认下这一环挑战所记的功绩。")
zh(5,"基特斯在荒村里躲藏数周，靠虫子和野草勉强果腹。他渴望一顿热饭，相信夜色镇的厨师格鲁奥能为他实现这个愿望。")
zh(6,"加瑞克·帕德弗特在这一带打家劫舍已有数周，农夫与商贩苦不堪言。维里副队长悬赏取他性命，可他藏身的葡萄园旁，还盘踞着一伙亡命之徒。")
zh(7,"一伙狗头人已盘踞在北郡以北的林地。玛克布莱德要先削掉它们的数目——唯有如此，日后才能把它们彻底逐出此地。")
zh(8,"一封书信必须送到瑞尼手中，布瑞尔的旅店老板。寄信人愿付酬金，并推荐这家旅店为一个温暖的避风港，其他天灾军团的受害者正试图在此重建生活。")
zh(9,"萨丁拒绝放弃他的农场，尽管强盗已迫使其他人撤离。清除看守傀儡，能帮助那些仍坚守田地的人夺回丰收的希望。")
zh(10,"斯克林尚失踪了，他当时正在勘测一片荒漠，据报那里出了古怪的虫群。菲兹杜瑟怕虫祸蔓延，要人找回这名助手，或者至少把装备取回，好查明究竟出了什么事。")
zh(11,"巡逻队无法遏制豺狼人沿着艾尔文森林边境集结。军队寻求外援，并希望用染色臂带作为证据，证明这些逐渐壮大的狼群已被击退。")
zh(12,"西部荒野的居民组建了人民民兵，守护他们的家园。协助格里安抵抗迪菲亚兄弟会，能支持那些试图让这片土地重归生机的农夫。")
zh(13,"迪菲亚盗贼仍在掠夺西部荒野的矿场与农田。格里安希望遏制他们的袭击，让剩余的居民能守护尚存的一切。")
zh(14,"逃过民兵追捕的迪菲亚盗贼继续劫掠西部荒野南部。侦察兵将据点设在山丘，剩余的强盗正策划下一次对乡村的打击。")
zh(15,"侦察兵在北方矿场附近发现狗头人，揭示了比预想中更严重的入侵。玛克布莱德需要清剿营地，并查明他们的势力范围。")
zh(16,"葛拉德·提勒口干舌燥，只盼一口清凉的泉水。在葡萄园里，这不过是举手之劳。")
zh(17,"加克想研究奥达曼发现的菌类的炼金潜力。他需要采集它们的菌盖，但警告采集时若惊扰菌群，可能释放毒孢。")
zh(18,"自称迪菲亚兄弟会的盗贼出现在河对岸。维里不知他们的意图，却愿意提供武器，供愿意协助对抗这群匪徒之人。")
zh(19,"兽人伏击威胁着通往城堡的道路。马瑞斯指认塔里尔·祖恩为逃亡者的首领，并希望阻止他，以回应其部队的袭击行动。")
zh(20,"黑石兽人占据城堡并劫掠乡间，让湖畔镇的居民不敢外出。马瑞斯希望攻击他们的部队，以减轻对城镇的压力。")
zh(21,"探报已实：狗头人钻进了矿洞深处。玛克布莱德要即刻清剿——它们每多盘踞一日，在北郡的根就扎得更深一分。")
zh(22,"萨尔玛的肉派已近完成：酥皮、香草与肉汁俱备，只差血牙野猪的肝，便可端上餐桌。")
zh(23,"乌萨苟斯的爪印表明，熊已在猎杀中被击败。那诡异的图腾尚无解释，但塞娜尼能认出这是猎物，也承认了试炼的一部分。")
zh(24,"萨杜布拉的头颅证明了在灰谷猎杀中的另一场胜利。将它献给塞娜尼，能让这次遭遇被评估，也承认了挑战的相应部分。")
zh(25,"湖中元素生物已封锁了灰谷与石爪峰之间的通道。除了遏制它们的袭击，任务还要求侦查一处能俯瞰附近联盟哨站的高地。")
zh(26,"你的德鲁伊训练已达到适合水生的动物形态。与塞纳里奥议会的德迪利特·星焰会面，将获得继续进阶的指引。")
zh(27,"你的德鲁伊训练已准备好探索适合水生的方面。塞纳里奥议会的德迪利特·星焰能在月光林地引导你进入下一阶段。")
zh(28,"第一项试炼考验速度与敏捷：从湖中取回的饰品迅速腐朽，必须及时送达神龛。塔加里监督这场德鲁伊训练的练习。")
zh(29,"迅速腐朽的湖中饰品使这项德鲁伊仪式成为专注与行动的考验。及时抵达神龛，便证明了这两种品质。")
zh(30,"水生形态结合了敏捷与耐力。两枚吊坠半块象征着这些特质，将它们在神龛合而为一，是理解平衡的一步。")
zh(31,"初步考验已结束，挂坠见证你的准备就绪。图拉克·符文图腾在雷霆崖等待，将完成你掌控水系形态的最后教导。")
zh(32,"昆虫报告需专家审阅。基尔兹宾研究艾泽拉斯特有的生命体，他的知识或许能解释威胁并找到阻止其扩散的方法。")
zh(33,"伊根讨厌北郡游荡的狼群，却爱吃它们的牛排。他愿以实用之物交换附近乡野狼群的肉。")
zh(34,"贝利格拉布再度踩毁玛蒂的花园，毁掉季节的花朵。她希望尽快阻止那只野猪，以免它再度毁家。")
zh(35,"艾尔文森林鱼人的消息，还须查实。托马斯守过东部桥梁，能把自己亲眼所见的凶险说给杜汉听。")
zh(36,"盗贼让法布隆家的农场变得太危险，一家人正准备撤离。离别前，弗娜希望将她的炖肉食谱交给邻居萨尔玛·萨丁。")
zh(37,"罗尔夫和马拉凯数日前被派去调查河流后便失踪。托马斯必须查明他们的下落，哪怕只剩残骸。")
zh(38,"萨尔玛想做西部荒野炖肉，需要当地的食材。寻找肉类、蔬菜和其他材料，助她完成食谱。")
zh(39,"罗尔夫和马拉凯的死暴露了东方威胁的严重性。托马斯需要杜汉明白，目前驻守那里的部队无法遏制鱼人的进攻。")
zh(40,"雷米亲眼目睹鱼人袭击了东部艾尔文森林的居民。你帮助将危险带到那些被其他威胁分散注意力的守卫面前，让他的警告被认真对待。")
zh(45,"被网住的脚印沿着湖岸延伸向一个鱼人村落。这条线索为揭开罗尔夫的下落提供了新机会，他的命运仍不明朗。")
zh(46,"鱼人在湖边与溪流分叉处建立了村落。暴风城的军队悬赏猎杀他们，撕裂的鱼鳍将成为证明。")
zh(47,"雷米想要金砂，他知道附近矿坑附近的狗头人常携带这种东西。他愿意从任何能找回金砂的人手中购买足够的量。")
zh(48,"葛瑞姆·雷酒需要一处隐藏的泉眼之水继续他的准备。他的诗句描述了一处南方藤蔓丛中的深井，强调他要你带来的水必须纯净。")
zh(49,"葛瑞姆·雷酒梦想酿造一种琥珀色的饮品。制作它需要多种谷物，因此他请你收集将构成他混合物基础的原料。")
zh(50,"酿造这饮品需要一座由坚固金属打造的蒸馏器。葛瑞姆·雷酒正在准备原料，需要真银来建造能推进他蒸馏计划的设备。")
zh(51,"饮品已新鲜蒸馏，但仍需过滤。葛瑞姆·雷酒想要准备木炭用于这一步骤，因此请你取来枫树枝，作为继续制作的材料。")
zh(52,"远离闪金镇的野兽愈发暴躁。狼与熊的袭击几乎不断，威胁着伐木营地，托马斯需要你协助减轻对工人的压力。")
zh(53,"葛瑞姆·雷酒解释，这酒需经年累月才能染上琥珀色。在继续前，他需要一个由焦黑橡木制成的木桶，因此请你获取适合此阶段的木材。")
zh(54,"你在北郡的服务，已赢得更广泛的职责，守护艾尔文森林的安全。玛克布莱德已为杜汉在闪金镇准备了文件，此任务的下阶段由此展开。")
zh(55,"这准备好的武器能中和摩本特·费尔的魔法防御。斯温请求你用它对付亡灵巫师，以保护森林并追索驱使他搜寻的复仇。")
zh(56,"暴风城的撤退让夜色镇只能依靠自身守卫。阿尔西娅需要协助对抗墓地的骷髅，以便夜望能守护其照护之人。")
zh(57,"报告指出祸害鼠已蔓延至森林各处墓地。阿尔西娅希望尽快减少它们的出现，以免给守护夜色镇安全的守卫带来更大压力。")
zh(58,"局势依旧严峻，阿尔西娅手头的守望者也不足。东部神殿内潜藏另一威胁，必须加以遏制，以支援夜色镇过度疲累的本地防线。")
zh(59,"为艾尔文森林效力，已赢得一件盔甲。萨拉·迪博雷恩可在收到授权令后打造它，以支持森林的持续防御。")
zh(60,"威廉正收集蜡料，为他与兄弟共营的暴风城药剂师铺子所用。附近矿坑里狗头人携带的大蜡烛，或许能提供所需材料。")
zh(61,"威廉为兄弟摩根的暴风城店铺准备了蜡烛，却无法亲自送去。你将完成兄弟间的这笔交易。")
zh(62,"矿井的麻烦远不止北郡。杜汉听闻狗头人占据了闪金镇南方的另一座矿井，亟需亲赴现场核实。")
zh(63,"祸害鼠已污染神龛，使与灵体的沟通陷入沉寂。击败被腐化的实体，将为净化水源、重续联系的仪式做好准备。")
zh(64,"法布隆一家在强盗来袭时逃离了农场，只留下一只珍爱的怀表。弗娜的父亲在婚礼当日将它赠予丈夫，如今他希望从农舍的衣柜中寻回这件遗物。")
zh(65,"格里安需要查明迪菲亚的首领是谁，以及他们藏身何处。找到他的联络人威利，将揭开一场远超遏制他们袭击的调查。")
zh(66,"一场幻象让艾娃忧心孙女的安全。斯塔文的名字是她唯一找到的线索，而镇上的记录或许能解释它的意义。")
zh(67,"登记簿显示斯塔文曾出现在一所旧校舍，但地址已显陈旧。达尔塔需要更近的资料，这或许也会将调查引向这位男子的更深层面。")
zh(68,"一封积灰的书信被遗留在旧提箱中。将它交给达尔塔，能为追寻斯塔文的过往踪迹提供另一份线索。")
zh(69,"达尔塔在第一地址下发现另一处被部分刮去的住址。闪金镇的酒馆将成为寻找那位记得斯塔文、能追踪他行踪的人的下一个线索。")
zh(70,"一名信使因恐惧逃离酒馆，留下了他的书信。其中一封来自斯塔文，其目的地暴风城或许能为调查提供另一条路径。")
zh(71,"找回的铭牌揭示了罗尔夫与马拉凯遭遇的真相。托马斯等待这些遗物，以查明派去调查河流的守卫们最终的命运。")
zh(72,"一户遭屠戮家庭的遗物正准备拍卖，看护人允许搜寻任何可能揭示斯塔文·密斯特曼托真相的线索。")
zh(74,"一张撕裂的日记残页出现在画像与家族纪念品之中，这碎片在审视与斯塔文相关的遗物时，提供了新的线索。")
zh(75,"哈迦德记得一些文件，因视力衰退未能细读。翻查他的家箱或可寻得一页，提供关于斯塔文的更多信息，推进调查。")
zh(76,"艾尔文森林一处矿坑里，狗头人已经坐实。杜汉如今要弄清：更远的东北矿脉是否也有它们盘踞。弄清了，才好掂量局势。")
zh(77,"德兰的联系人保留着饮品原包装，但要求额外瓶子作为打包报酬。要取回货品，必须闯入一座废弃的部落基地，如今被黏液与软体生物占据。")
zh(78,"哈迦德推荐斯密茨，因其对本地历史的了解。这页残纸需他解读，方能厘清其对斯塔文调查的潜在价值。")
zh(79,"斯密茨将新证据与他多年前调查的一场屠杀联系起来。阿尔西娅需要这页残纸，以及他察觉到的与斯塔文疑云之间的关联。")
zh(80,"阿尔西娅疑心斯塔文，可那一页出自何人之手还须查明。达尔特熟悉登记册，能帮着比对笔迹，看这份文书是否足以定他的罪。")
zh(81,"德兰的饮品已封入木桶，以防旅途颠簸。将它送至奥格瑞玛的店铺，并代为转交他饮酒同伴的邀请，邀请玛尔顿。")
zh(82,"昆虫正抽干巢穴的水源，但调查者对敌人知之甚少。匹斯特苏格需要森提帕尔的躯体来研究这些生物，识别沙漠中潜伏的威胁。")
zh(83,"萨拉能将艾尔文森林迪菲亚强盗所戴的红色亚麻面罩改制成实用衣物。她的提议让强盗的标志性布料成为一份切实的奖赏。")
zh(84,"比利的肉馅饼已烤好。伯妮丝交出时满面不情愿，但剩下的差事是将承诺的餐食送至葡萄园的男孩手中。")
zh(85,"伯妮丝丢失了项链，怀疑是比利·马科伦所偷。她需要有人去葡萄园询问男孩，协助找回失物。")
zh(86,"比利想先吃个饼，再透露项链的事。他认为伯妮丝可用两家人农场里野猪的肉来烤制。")
zh(87,"比利声称一只带金牙的狗头人将项链带入矿井。他的说法为寻找伯妮丝的珠宝提供了明确线索，尽管他对项链如何到手含糊其辞。")
zh(88,"公主，布拉克威尔家的巨型猪，正靠邻家农场的蔬菜发胖。斯通菲尔德妈妈希望在它再来一次饥肠辘辘的拜访前阻止它。")
zh(89,"铁器在兽人入侵期间被用于武器制造，而豺狼人抢走了补给。奥斯洛需要回收建材，以重启湖畔镇受损桥梁的修复。")
zh(90,"格鲁奥若能获得新鲜肉料，便能烹制他的狼肉特色料理。调味料已从暴风城运抵，只差所需食材供应厨房。")
zh(91,"莫甘斯借豺狼人之手扩张势力。当局视这些豺狼人为罪犯帮凶，为保湖畔镇，要对他们动手。")
zh(92,"布雷纳在兽人暴动期间耗尽了补给品喂养士兵。若能从赤脊山附近的动物身上获取新鲜食材，她便可再次烹制她的肉汤。")
zh(93,"格鲁奥的蟹肉蛋糕有个不寻常的秘密：原料是蜘蛛腿。他需在附近蜘蛛巢穴采集新鲜食材，才能再做一批。")
zh(94,"阿祖拉之眼让莫甘斯暴露在监视之下，却无法窥探他的心思。塔旁放置的符文旨在延长监视，揭露他的计划。")
zh(95,"斯温在离家期间失去了家人。他记得袭击后有人埋藏了东西，想在追查前弄清那究竟是什么。")
zh(96,"灵体赠予一块水晶，并传授守护生命、抵御腐蚀的教诲。将它带给伊斯伦，延续在圣殿开始的萨满教义。")
zh(97,"笔迹比对已坐实了对斯塔文的疑心。阿尔西娅急着要这个结果，一刻也不能耽搁——那卷取回的文书验出了什么，她要立刻知道。")
zh(98,"调查揭发了斯塔文的罪行，当局视他为夜色镇的威胁。阻止他能终结伊娃所指的危险，也需证据佐证任务。")
zh(99,"调查指向焚木村的夜间变形。寻回附魔镣铐或可揭示阿鲁高的诅咒如何控制居民，并解释他们的行为。")
zh(100,"仪式已耗尽余水，散去堕落之灵。下一场遭遇将允许与净化神龛后的显现体沟通。")
zh(101,"腐蚀在林间蔓延，伊娃觉出危险正逼近。防御图腾她备得下，只是附魔之前还缺材料，须从那些威胁此地的生物身上取。")
zh(102,"暴风城的疏离令西部荒野的农夫自组抵抗。你的巡逻守护剩余者，对抗似乎与死亡矿井强盗勾结的豺狼人。")
zh(103,"灯塔看守人一家身亡后，葛瑞森船长维持灯火以护航旅人。他需收割机提炼的油料，让海岸警示长明。")
zh(104,"老瞎眼曾使葛瑞森所需的灯塔黯淡，后又率队杀害看守人一家。他持续盘踞海岸，仍是需正视的威胁。")
zh(105,"阿拉基在安多哈尔的废墟中称王，身后是无数天灾军团的守卫。德灵顿认为驱逐他时机已到，但警告说要集结盟友才能直面巫妖并取得其败亡的证据。")
zh(106,"梅贝尔深爱托米·乔，但两家世仇使他们无法相守。一封寄给他的信，或许能维系那些敌对家庭不愿承认的联系。")
zh(107,"米莱德认为威廉·匹斯特或许有解药能助这对年轻恋人。她留下的便笺，将问题带往如今暂居闪金镇的药剂师。")
zh(109,"格里安率领人民民兵守护西部荒野的农田。因你的战斗经验，你被指引至他处，以协助这片土地的居民自保。")
zh(110,"查验斯克林尚的装备时，菲兹杜瑟怕虫子还要添更多损失。他要弄清匹斯特苏格是否已把送去的样本验完，并尽早拿到结果，好接着往下查。")
zh(111,"托米·乔信赖祖母能为他与梅贝尔找到在一起的方法。与她交谈，是他对抗家族世仇的下一个希望。")
zh(112,"威廉能调配隐形水，让梅贝尔秘密探访托米·乔。他仍需水晶海草——一种常被闪金镇附近的鱼人采集的海洋植物。")
zh(113,"匹斯特苏格认为昆虫的威胁远超加基森，希望他的研究能广泛传播。菲兹杜瑟必须接收报告，并为你准备一份副本，作为对势力的警示。")
zh(114,"隐形水已备好，交予梅贝尔。威廉期盼它能持续足够久，让她离开葡萄园，去拜访托米·乔。")
zh(115,"兽人用被恶魔污染的水晶球伤害守军，马瑞斯需将这些武器从战场移除并妥善处理，以削弱敌方优势。")
zh(116,"兽人入侵使酒馆的酒类补给延误，丹尼尔库存将尽。他需从多个聚落搜集物资，以补足日渐稀少的酒品。")
zh(117,"格里姆布兹特制啤酒需啤酒花才能酿出预期风味，他正寻觅这缺失的原料，以免酒液变成一锅杂烩。")
zh(118,"奥斯古德耗费大量铁料打造守卫装备，已无力给马厩的马钉蹄铁。他的信件请求阿古斯补给一批铁料。")
zh(119,"阿古斯已打包好奥斯古德所需的马蹄铁，这批货物须返回湖畔镇，并附上信件，指定接收的铁匠务必亲自阅读。")
zh(120,"围城之势正威胁着湖畔镇的防线，所罗门急需一封求援信送至马库斯·乔纳森手中，并期盼尽快收到回音。")
zh(121,"马库斯·乔纳森仍在等待国王的回信。与此同时，他已备好一封给所罗门的信件，须返回湖畔镇，作为他们关于防御讨论的一部分。")
zh(122,"奥斯古德需支付闪金镇寄来的马蹄铁费用。若能用黑龙雏龙的鳞片抵债，还能余下材料换取额外奖励。")
zh(123,"一张被发现的便条记载，艾尔文森林的金矿正运往一位名为收集者的人手中。将它交给杜汉，能让守卫们获得调查线索。")
zh(124,"在兽人袭击的同时，马厩还面临豺狼人掠夺，他们抢夺靠近北方山脊的马匹。奥斯古德需要协助减少这额外的威胁。")
zh(125,"奥斯洛的工具运送因破碎的桥梁受阻，随后又被兽人袭击了替代船只。他的工具箱如今沉在湖底。")
zh(126,"在犹勒的率领下，豺狼人继续在湖畔镇上空狩猎。奥斯古德希望擒获首领，以瓦解持续威胁周边山丘的狼群。")
zh(127,"巴伦的鱼货正面临短缺，湖中既是捕捞的来源，也能从当地鱼人身上获取现成的渔获。")
zh(128,"当局希望打击兽人对山地的占领。他们的报告指出，领袖是各部队的统帅，要求攻击他们以挑战入侵的军事存在。")
zh(129,"达希为帕克准备了午餐，但巡逻路线太危险，她无法亲自前往。她需要有人将食物安全送到他手中。")
zh(130,"卫兵帕克希望将花送给达希，需在湖畔镇协助获取。他叮嘱采药人对送花人与收花人皆要守口如瓶。")
zh(131,"采药人挑选了水仙花作为花束，花已备齐，只差将花送到湖畔镇的达希手中，方能完成这份心意。")
zh(132,"威利揭露迪菲亚盗贼正与其它生物勾结，自此他忧心忡忡。他留下笔记，记载所知，必须送到格里安·斯托曼手中以作进一步调查。")
zh(133,"亚伯克隆比远离城镇庇护，报告有食尸鬼袭扰。他想制作人偶驱赶它们，却需用这些生物的肋骨作为材料。")
zh(134,"巨魔袭击迫使亚伯克隆比放弃珍贵的工具与草药。他相信箱子仍近他们的营地，需协助找回逃亡途中遗失的财物。")
zh(135,"威利提及石匠，引发对迪菲亚盗贼起源的质疑。马迪亚斯·肖尔或许能借暴风城的密信，厘清这段关联。")
zh(136,"杉德斯上尉的讯息承诺，追随线索者可得其所藏宝物。第一线索指向西部荒野的残骸中，锈迹斑斑的锚旁的沿海木箱。")
zh(138,"下一条宝物线索引向内陆，指向路旁一座破败的烟囱。一个旧木桶，标记着上尉寻宝之路的下一步。")
zh(139,"木桶里的羊皮纸指引着北方的线索。海崖边一座孤零零的风车旁，空酒桶或许藏着通往宝物的下一条路。")
zh(140,"最后一封信因潮湿与威士忌损毁严重，却指明了箱子位于海岸西边。搜寻必须继续向海上，抵达船长描述的那座岛屿。")
zh(141,"肖尔将艾德温·范克里夫与暴风城的重建联系起来，也揭示了石匠们的后续不满。他的报告为斯托曼提供了理解迪菲亚盗贼及其可能起源的新视角。")
zh(142,"民兵需要找到迪菲亚的据点。一名往来于采矿路线的信使或许掌握关键情报，因此斯托曼希望截取并审阅他的书信。")
zh(143,"所罗门无法无限期等待暴风城的军队。湖畔镇危在旦夕，他转而寻求正在西部荒野成形的民众民兵，作为另一支援来源。")
zh(144,"西部荒野的民兵正孤军奋战，缺乏支援。斯托曼同情湖畔镇的处境，但他的回信必须解释为何无法提供所需援助。")
zh(145,"所罗门正寻求夜守者的帮助，以保卫湖畔镇。他的信件必须尽快送达暮色森林中危险的埃伯洛克，道路本身也成为关键。")
zh(146,"埃伯洛克无法派遣夜守者而让夜色镇暴露风险。他的回信解释，暴风城也已抛弃他们，而这些守卫是小镇存续的命脉。")
zh(147,"集魂者正将黄金从王国的矿脉中转移。杜汉希望他被阻止，并检查他的戒指，寻找那些在恢复的调度中描述的运载行动背后黑手的线索。")
zh(148,"亚伯克隆比说自己身子太弱，走不了这趟去夜色镇的路。他要用一种特别的丝线，托人去问伊娃该备何种材料，省得他亲自奔波。")
zh(149,"伊娃若能获得灵体的毛发便可织就丝线。将梳子带给玛丽，便能收集到这些毛发，但幽灵农场周围潜伏着危险。")
zh(150,"鱼人正沿岸定居，并大量捕捞。巴伦担心他们将耗尽湖中的鱼群，因此悬赏清除他们日益增长的势力。")
zh(151,"老马布兰契筋疲力尽，破损的马车使福尔布罗家陷入困境。找到燕麦能帮助他们的母马恢复元气，而一家人仍在挣扎前行。")
zh(152,"西部荒野的残骸遍布的海滩或许能为水手提供庇护。葛瑞森希望清除鱼人，让抵达岸边的人不再面临新的威胁。")
zh(153,"加里安一直在追踪迪菲亚势力的变动。他们的红色皮质面罩暴露了帮派成员身份，集结他们可作为你对抗西境幕后操控者的证据。")
zh(154,"玛丽因幻影般的容貌而拒绝梳子。收集到的毛发必须归还伊娃，好让她继续以这罕见材质织就所需的丝线。")
zh(155,"叛徒若能一路护送，便能揭露迪菲亚的藏身之处。他的旧日同伙恨不得他死，因此情报能否获得，全看能否保全这位向导的性命。")
zh(156,"若能寻得生长在骸骨间的花朵，斯密茨便可为他调制饮品。获取这些花朵，也意味着能削弱周边墓地的亡灵势力。")
zh(157,"幽灵的发丝已备妥。艾娃解释它蕴含的魔力，可束缚灵体、赋予无生命之物生命，必须送往亚伯克隆比处，以完成他的请求。")
zh(158,"亚伯克隆比需要烈酒抵御寒夜。斯密茨可在酒馆为他准备，让这位老人无需亲自踏上旅程。")
zh(159,"烈酒已备好，伴随的是它非凡威力的警告。将它送至亚伯克隆比的庇护所，便能满足他抵御寒夜的所需。")
zh(160,"亚伯克隆比递出一封书信给艾尔罗，并称镇长定会欢迎这份援助的消息。书信必须送往夜色镇，让收信人得以阅读其中内容。")
zh(161,"欣德韦尔怀疑发现的粉末是爆炸物，却需专家鉴定。斯通斯米尔克能辨识它，但前往他处需穿越湿地，旅程危险。")
zh(162,"昆虫调查需要格拉希娜对艾泽拉斯历史与奇兽的知识。将报告送至达纳苏斯的她处，或能解释威胁并找出应对之法。")
zh(163,"乌鸦岭的暗影与夜光让眼魔不安，他们的描述暗示建筑群中潜伏着未知存在，使这座城镇的诡异现象亟待调查。")
zh(164,"斯温与同伴驻扎的营地人手不足，难以分派任何人去取补给。城镇的物资能支撑他们的行动，而不会削弱那微弱的存在。")
zh(165,"一位常来购买物资的老者已不再现身。他的缺席牵动那些记得他的人，也促使人们检查他墓地旁的居所是否出了差错。")
zh(166,"斯托曼认为守护西部荒野，必须彻底终结范克里夫。尽管不愿定罪于他，却将此任务作为对迪菲亚盗贼首领的最后一击。")
zh(167,"维尔德从西部荒野的矿难中逃出生天，但弟弟仍下落不明。找到他，或找回他的探险徽章，或许能为他遭遇的变故带来些许答案。")
zh(168,"矿难让无数家庭陷入迷惘。维尔德寻找失踪矿工的记录，只为让他们的亲人在这地下悲剧后获得些许慰藉。")
zh(169,"加兹·伊尔祖格指挥兽人突袭，并藏身于被占的城堡。这份悬赏映照出他对湖畔镇的威胁，以及从这据点发动更多袭击的可能。")
zh(170,"穴居人现身山丘，已攻陷附近营地。冷脊山谷的守卫不足，巴尔林急需援助，以抵御这股新的威胁。")
zh(171,"结界对孩童周的经历心怀感激，期盼有朝一日能成为英雄。此刻该带孩子返回暴风城孤儿院，让监护人聆听你们共度的时光。")
zh(172,"孤儿院正需义工在年度庆典期间照料孩童。监护人赠予哨子，助你寻得结界并共度孩童周。")
zh(173,"卡洛尔寻求志同道合的战士协助卡尔文对抗森林的邪恶。对抗狼人，是检验实力的试炼，亦是参与更大使命的开端。")
zh(174,"维克托认为研究星辰或许能解开森林变形之谜。柯格的计划是起点，但搭建观测装置，首先需合适的工程组件。")
zh(175,"装置需能反射光线的表面。维克托忆起玛丽曾携带镜子，期盼她的协助能解决天文计划的这一环节。")
zh(176,"霍格游荡于艾尔文森林西南部，屡次逃脱捕获。军方悬赏取他性命，因其成为异常危险的豺狼人，威胁不容忽视。")
zh(177,"玛丽在改变她人生的悲剧后遗失了镜子。她相信尸鬼可能拾得，这或许能为维克托所需的组件提供线索。")
zh(178,"声音解释，吊坠将豺狼人与莫甘斯相连。塞欧克瑞图斯已成功接入通讯，需将此物交予他，以作进一步研究。")
zh(179,"斯登提供适合山谷寒气的手套，条件是用狼肉交换。这安排让他得以获取当地补给，也让冒险者拥有了更温暖的双手。")
zh(180,"范高雷统领着为莫甘斯效力的豺狼人，他们是湖畔镇的敌人。所罗门的命令旨在阻止这位指挥官，并需要可辨识的证据证明他已被击败。")
zh(181,"维克多里的装置仍需一个足够大的透镜。一个巨人的单片眼镜或许能派上用场，但获取它意味着要接近其主人居住的危险营地。")
zh(182,"格瑞林调查巨魔，而参议院则应对地穴魔。他相信南方洞穴可由能人冒险者解决，无需动用军队。")
zh(183,"当地野猪的数量与攻击性让塔林的狩猎地变得危险。他需要帮助减少它们的数量，才能更安全地恢复往日的活动。")
zh(184,"找回的契约暗示弗尔布罗家族曾被迫离开家园，文件可能被伪造。归还它，便能让流离失所的家庭重获土地的证据。")
zh(185,"虎豹狩猎始于幼兽，它们更容易追踪。导师将从父亲处习得的技艺，通过追踪与战斗的首次实战演练传给弟子。")
zh(186,"对年轻老虎的经验，让更艰难的狩猎得以展开。下一次考验针对成年老虎，以检验已掌握的技能是否足以应对更严峻的猎物。")
zh(187,"年长的老虎难以寻觅且格外凶猛。这一阶段考验更高级的技巧，为最终挑战做准备，以证明你驾驭丛林猎手的资质。")
zh(188,"数周来，辛·达尔屡屡从狩猎队眼前遁去。最后一场试炼要你追踪这只难觅踪影的猛虎，并献上战利品，证明确实过了这一关。")
zh(189,"巨魔袭击已夺走科博克的性命与财富。担忧向里维加兹交代损失，他悬赏追查威胁其丛林代理人者。")
zh(190,"加入大型猎手需展现对抗黑豹的能力。年轻个体是第一关卡，结合寻找猎物的技巧与遭遇后克服它的能力。")
zh(191,"黑豹猎杀逐步转向成年个体。它们比早期猎物更具威胁，将考验你是否已准备好与猎手团队共赴险境。")
zh(192,"此地最凶的黑豹，追踪与厮杀一样考人。降服它们，便是这些人要看的进阶证明——你既自称猎得这些猛兽，就该拿出这等手段。")
zh(193,"巴格·瑟拉已成功躲避营地猎手。追踪这头巨兽并带回战利品，是最后证明你通过黑豹猎杀试炼的契机。")
zh(194,"迅猛龙猎杀是探险前的试炼。寻找这些生物是挑战的核心，方向指引无法替代你的追踪技艺。")
zh(195,"赫米特·奈辛瓦里以在丛林中猎杀鞭尾迅猛龙为试炼，提升难度。新目标将检验你已展现的能力，是否足以应对更严峻的挑战。")
zh(196,"赫米特·奈辛瓦里提出更严苛的试炼，延续你的狩猎训练。丛林捕猎者尤为难以捕捉，直面它们将展现你的实力，再揭示更艰巨的目标。")
zh(197,"赫米特·奈辛瓦里提及泰希斯，一只狡猾至极的迅猛龙，连他都未能将其斩杀。在丛林中证明自身后，迎战此目标并取其利爪，方显真正掌控。")
zh(198,"多伦的部队仍在等待常规补给。巨魔袭击扰乱运输，急需有人能安全护送货物抵达索尔森。")
zh(199,"这异香粉末值得深入调查。采集的样本必须送达欣德韦尔，作为证据，或可解释大坝及其周边的异常状况。")
zh(200,"索尔森行动的曝光暗示叛军中潜伏间谍。后勤军官的记录或能解释机密外泄途径，并指引寻找出卖他的叛徒。")
zh(201,"报告指出奈辛瓦里现身于河畔新驻扎的猎人营地。他的关系牵动监视此地之人，他们想弄清这支狩猎队的行动与意图。")
zh(202,"多伦期盼你的能力能直面库尔森，为他的叛军指出前路。上校仍深藏洞窟之中，指挥部下与军官，运筹帷幄。")
zh(203,"叛军敌不过精通战术的敌人。尤瓦中士希望以快速突袭削弱库森的兵力，趁增援未至前将袭击者困住。")
zh(204,"库森的医者疗伤并下毒于叛军。搜集他们的解药与研究其提取物，既能救治伤者，又能削弱敌方优势。")
zh(205,"研究者钻研取回的传说时，要用巨魔巫术的器具。别族的物件能充作实物标本，把眼下这桩查证再往下推一层。")
zh(206,"尼麦兹修士认为玛伊·祖思以心灵操控魔法腐蚀了库森。他担心这个巨魔会引发更多悲剧，因此想除掉他，并夺回他控制他人的神器。")
zh(207,"研究者想弄清库尔森因何败亡，疑心是巨魔的巫术作祟。上古石板或能给出线索，供人查验这条猜想——真相如何，眼下还算不得定论。")
zh(208,"在你之前的猎捕中，赫米特·奈辛瓦里认为你展现了非凡的技巧。如今他提出最珍贵的猎物：白虎邦加拉什，其战利品将是对猎人技艺的终极考验。")
zh(209,"出口虎牙既昂贵又危险，所以科博克想用仿制品替代。裂颅者巨魔的獠牙最为接近，能让他准备下一批货物而不暴露骗局。")
zh(210,"机械锅曾为营地厨师省去不少劳作，直到它坏掉。将它送回原售者，既求修理，也盼恢复这实用的烹饪工具。")
zh(211,"阿拉基借天灾军团与强大守卫之力掌控安多哈尔，阿什拉姆欲驱逐他，需你集结盟友对抗，并取回一枚符文石作为证据。")
zh(212,"当晚的宴会需用石化蜥蜴肉，但此物难以久藏。厨师唯恐食材变质，亟需速递以备佳肴。")
zh(213,"与风险湾公司的商业竞争再度引发里维加兹的介入。他的代理人偏好偷窃，意图获取公司地质学家关注的晶石样本。")
zh(214,"迪菲亚头巾的材质彰显身份。瑞尔欲针对高层下手，极可能藏身据点，需取回他们标志性的丝绸徽章作为证据。")
zh(215,"索尔森坦言奉多伦之命执行潜入，中途需你协助。行动仍属机密，但上级可澄清事态，不致暴露任务真相。")
zh(216,"熊怪村落阻断了部落据点间的通路。镇压其居民既是领土之争，也意在阻绝联盟获得优势。")
zh(217,"斥候已探明：格劳姆格就是这股入侵穴居人的首领。拉格弗斯认定，除掉他与他的护卫，攻势便会松动，反击的时机也就有了。")
zh(218,"格瑞林的日记被巨魔夺走，他记得一个标记奇特的粗暴家伙将它带入洞穴。找回日记，就得追踪那个家伙的下落。")
zh(219,"基沙恩下士活了下来，却在战斗中受了重伤并被俘。若想活着回到湖畔镇，他需要离开洞穴时有人保护。")
zh(220,"水元素训练仍需在艾斯伦指导下完成。所提供的药瓶是继续训练的关键，必须在下一场考验开始前送到她手中。")
zh(221,"数量更多的狼人已攻占了夜色镇附近的果园。卡洛尔警告说这些敌人更为凶悍，需继续清除他们对森林的威胁。")
zh(222,"先前的成就使得最危险的森林狼人成为目标。卡洛尔指出了他们新近建立的据点，清除行动可以就此展开。")
zh(223,"卡洛尔在评估你的协助后，向卡尔文传递了一则讯息。这封信支持着一小群人，希望扩大对抗威胁森林邪恶势力的能力。")
zh(224,"由于大部分军队远征他处，洛克莫丹的守军已难以招架。穴居人正从新的缺口涌入，亟需外界援助以阻止他们的推进。")
zh(225,"摩根·拉迪莫尔的墓碑显示泥土曾被翻动。这种改变让简单的铭文变成了值得调查的线索，应带给熟悉此地历史的人。")
zh(226,"拉尔斯与斯温必须寻找食物，但归来的路上却遭遇狼群袭击。减少附近的狼群数量，将缓解这个本就脆弱营地的日常威胁。")
zh(227,"一本古籍记载了摩根的过往，但阿尔忒亚深知他近期遭遇的种种麻烦。查阅书信，能将尘封的往事与凝视者们亲身经历的事件串联起来。")
zh(228,"阿尔忒亚的斥候已在墓园小径找到了摩尔·拉迪姆。她指引的方向，将引领众人寻找那个带来困扰的身影，但她无法提供更多支援。")
zh(229,"摩根以为全家已死，却不知女儿萨拉存活至今，更成为了一名凝视者。将这个消息告诉她，能解开她对父亲死因的疑虑。")
zh(230,"一本无标题的书在斯文旧日的农场下被发现。书页内容对他而言意义重大，必须送到营地，才能继续追查那片土地发生的事。")
zh(231,"萨拉将戒指交予他人，准备安放在父亲的墓碑上。她期盼这个举动，能让他知晓自己安然无恙，也表明家族不责怪他当年的所作所为。")
zh(232,"金格认为，凯佛的研究能被更有效地利用，而非让同事白白浪费。在展开实地调查前，她需要一套测试工具，而奥雷萨多将提供它，作为她采购单的交换。")
zh(233,"邮件经由山道抵达，但斯登无暇分发。那些等待的信件，最终将交到驻扎在冰湖畔的塔林手中。")
zh(234,"一封书信仍需送达格瑞林在东南公路的营地。它的旅程将继续，由接收点传递至等待的手中。")
zh(235,"部落正在加强灰谷的据点，并邀请冒险者前来证明自己。塞娜尼·雷心正从贫瘠之地北方的一处定居点发起一场大规模猎杀行动。")
zh(237,"当地守军必须持续施压，以牵制地穴魔，直到士兵们归来。格拉维戈正依赖进一步的攻击来拖延入侵的进程。")
zh(238,"奥雷萨多已备好采样工具，深知金格急需它。将它交给她，让研究得以继续；费用将从药剂师协会账户扣除。")
zh(239,"豺狼人与盗贼的活动日益频繁，令西边要塞忧心。杜汉手头无兵可调，需有人联络瑞尼尔，协助守卫防线。")
zh(240,"格鲁奥已做好承诺的蛋糕。食物必须送到基特斯手中，完成这场始于他藏身时渴望一顿热饭的差事。")
zh(243,"金格想研究塔纳利斯生物的组织，可她那套改装过的采样器，得靠地精的动力源才转得起来。比格维兹能弄来一件——只等你动手做测试，替她凑齐合用的样本。")
zh(244,"帕克在他巡逻路线的北面与东面都发现了豺狼人营地。道路眼下还算太平，湖畔镇却该得一句提醒——附近的兵力正在聚拢。")
zh(245,"蜘蛛已攻占西部边境，远超守望者的应对能力。道茨需要远赴城外支援，因补给不足，威胁仍未被有效遏制。")
zh(246,"菲尔顿副队长手头无兵可用，难以应对南方的豺狼人。他需要一项行动，既能削弱对方势力，又能评估其数量与威胁程度。")
zh(247,"塞娜尼·雷心认可了三次灰谷狩猎中收集的证据。她的赏赐表彰了猎人展现的毅力与力量，也为这一系列遭遇画上句点。")
zh(248,"监视显示莫甘斯与兽人之间爆发冲突，却未揭示其根源。若能在附近塔楼再发现一个符文，或可进一步调查这段关系，而不惊动堡垒内的守卫。")
zh(249,"塞欧克瑞图斯认定莫甘斯在找艾露恩之镰，而且可能已经得手。他怕的是这柄镰刀能带来的力量，主张趁王国尚未受威胁先行出手。")
zh(250,"其他矮人工地接连遇袭之后，欣德韦尔担心大坝就是下一个。东侧通道附近已晃出黑铁工兵的身影——非查不可，还得拿到实实在在的凭证。")
zh(251,"原本寄给艾尔罗的信需要专业翻译。希拉·沃宁迪精通语言与古老技艺，或许能协助解读亚伯克隆比寄给市长的讯息。")
zh(252,"翻译内容包含对亚伯克隆比行动的严重警告。艾尔罗必须尽快收到此信，以评估希拉所担忧的威胁是否已悄然逼近城镇。")
zh(253,"防腐师的故事将他的力量与妻子心中放置的心脏相连。从她的坟墓中取回那颗心脏，意在摧毁这份源自黑暗尝试复活她的力量。")
zh(254,"寻找防腐师的心脏，终将引向伊莉莎的坟墓。翻土启棺，只为探明艾尔罗所信的那股力量究竟源自何处，而那力量，必须被终结。")
zh(255,"铁炉堡的援军迟迟赶不到，这一带便空了出来。执政官正在招募冒险者，去对付盘踞在湖东北的食人魔。")
zh(256,"当局怀疑乔克斯的坐标掌控着对城镇、水坝与挖掘点的袭击。这份悬赏旨在铲除这名假想的首领，而完成任务的证据，才是关键。")
zh(257,"达瑞尔自夸技艺高超，提议以限时猎杀本地秃鹫为赌注。能否在期限内完成，将是对另一名猎人能力的直接挑战。")
zh(258,"达瑞尔以先前的胜利为引，抛出更艰难的试炼：猎杀成年野猪，且时间更短。他对挑战难度的自信，让他再次提出赌约。")
zh(261,"血色十字军要求先见行动以证明忠诚，方肯接纳援助。对抗山谷中的亡灵，既是他们对抗天灾军团的战争，也是对那蔓延腐败的清算。")
zh(262,"斯温需要辨认出他家人遇害后所见的那道身影。镇上或许有人认得他农场中发现的那本书，从而揭开它的主人身份。")
zh(263,"穴居人压力未减，而守备军正奔赴前线。巡山人沃尔班希望你以名声为赌，对抗更危险的势力，守护这片日益孤立的防线。")
zh(264,"克拉莉斯对尤里夫将十字军大业置于家族之上的行为心怀怨恨。如今她本人也染上了曾誓死抵抗的亡灵诅咒，便拒绝接受他的吊坠，只求将它留在丈夫的墓前。")
zh(265,"这本书的作者是夜色镇的陌生人，但这部书却是在那里购得。这个线索需要向镇民们追问，才能将它与斯温所追寻的目标联系起来。")
zh(266,"案子还缺一个记得那陌生人的证人。客栈是条说得通的线索：在镇上逗留过的人，兴许就在酒客中间被人瞧见过。")
zh(267,"守卫不能擅离岗位，而预备队正奋战于别处。拉格弗斯上尉寻求援助，以对抗山丘巨魔，缓解剩余矮人防线的压力。")
zh(268,"基特斯将完成的日记交出，以更完整地讲述农场发生的事件。他宁愿舍弃这唯一的陪伴来源，也不愿亲自面对斯温与他可能的怒火。")
zh(269,"对抗摩本特·费尔需先寻求建议，再接受这危险。法席恩可检视基特斯的日记，为斯温提供他认为必要的指引，以应对森林状况日益恶化的局势。")
zh(270,"法席恩认为，对抗摩本特·费尔需要一把神圣铁器。一艘舰队失事的货船或许能提供这金属，而戈罗林知道从何处开始寻找。")
zh(271,"维林认为这是贬低达瑞尔傲慢的良机。那头造成他著名伤疤的熊仍在山中游荡，击败它或能终结他无休止的吹嘘。")
zh(272,"海狮吊坠象征着水下行动所需的敏捷与耐力。重聚它的两半，意味着对这两种品质的理解，正是德鲁伊训练的核心。")
zh(273,"胡达尔正与米兰和赛恩一起运送物资。他们背负的木桶减缓了前往挖掘点的行程，但沿路仍有机会追上他们。")
zh(274,"阿什兰·暗石辨识出这种粉末是海硫，遇水会变得危险。他已找到一种混合物可中和它，需要通知欣德韦尔此一威胁与对策。")
zh(275,"沼泽中崛起的生物身上出现不明疾病。雷希耶尔认为必须阻止它们，将它们送回湿地，以减轻土地的痛苦。")
zh(276,"豺狼人数量的增长打破了与沼泽间的旧有平衡。被践踏的植物与过度砍伐让雷希耶尔决定减轻湿地所承受的压力。")
zh(277,"豺狼人砍伐树木供火用，雷希耶尔对此深感痛心。收缴他们的生火工具，旨在遏制他再也无法容忍的资源掠夺。")
zh(278,"欣德韦尔需先调配能中和海硫的混合物，以防袭击。其原料来自本地生物与附近巨魔开采的稀有晶体。")
zh(279,"鱼人从沿海村庄骚扰渔夫与商人。高布勒尔则在路上袭击旅人，卡尔希望阻止他，以保护依赖此路线的人们。")
zh(280,"黑铁族正将一桶酒液运往水坝，欣德韦尔担心即将发生爆炸。拆弹剂已准备就绪，必须在炸药引爆前送达。")
zh(281,"鱼人袭击让一艘船的部分货物落入生物之手。卡尔希望夺回那尊珍贵雕像，并下令搜查村民附近被掠夺的货物。")
zh(282,"格瑞林需要将观察记录交给在卡拉诺斯的弟弟。进入地精盘踞的隧道前，旅程要求先向驻守入口的山民请教。")
zh(283,"桶里的反应说明拆弹剂起了作用。欣德韦尔要的就是这份回报，好知道那威胁大坝的炸药如今是什么光景。")
zh(284,"首次搜查未发现失踪雕像的踪迹。附近小屋提供了再次寻找被盗货物的机会，继续卡尔的请求，将它寻回。")
zh(285,"再次搜查小屋仍未找到雕像。搜寻继续向北，一些失落货物的痕迹或许仍存于北方庇护所之中。")
zh(286,"找回的木桶中藏着一尊银制雕像，似乎正是那件失物。将其交还卡尔，便完成了追踪被盗货物的旅程。")
zh(287,"森内尔找到了巨魔的藏身之所，却发现人手不足难以深入调查。他需要洞穴被探索，住民被削弱，方能完成积压已久的报告。")
zh(288,"大副菲兹莫斯忆起当年兽人控制的巨龙如何摧毁了他所效力的舰队。酒意朦胧间他中断叙述，要求再来一杯酒，再继续讲述那场灾难。")
zh(289,"一件拥有不安力量的宝物，将水手们的灵魂困在残骸之中。菲兹莫斯期盼能解救部分旧日同伴，或许能打破束缚他们的诅咒。")
zh(290,"这诅咒似乎与船舱内强箱中的某件物品有关。找回钥匙并把发现之物交给牧师，或许能找到解救被困船员的方法。")
zh(291,"森内尔的报告已备妥，等待送往铁炉堡。递送这份文件将延续实地观察的记录，不过森内尔更希望隐藏他获取资料时所受的帮助。")
zh(292,"强箱内藏有菲兹莫斯所述的诅咒之眼。戈罗林需亲自查验，以探明如何清除其腐蚀，以及如何拯救被困船员。")
zh(293,"戈罗林无法净化那双眼睛，反而认为它出自人类牧师之手。大主教本尼迪塔斯或许能解开其中秘密，因此这件物品必须送往暴风城，寻求更多帮助。")
zh(294,"骨骼的发现引来迅猛龙，杀死挖掘者并困住幸存者。奥莫尔希望直面占据挖掘场的野兽，为阵亡的同伴报仇。")
zh(295,"奥莫尔继续追查挖掘现场的屠杀真相。这次行动将针对挖掘场周边的迅猛龙，进一步回应他同伴的死亡。")
zh(296,"奥莫尔发现了一只体型更大的迅猛龙，他怀疑是它引诱其他生物来到遗址。他最后的请求锁定这只巨兽，他认为正是它引发了挖掘行动的危机。")
zh(297,"穴居人因发现了奇怪的雕像而驱逐了挖掘者。麦格玛尔想要找回这些雕像，研究它们对生物的潜在影响，并从穴居人手中夺回。")
zh(298,"挖掘行动需要汇报进展并重新申请炸药。塞尔萨玛的本地联系人吉恩必须收到这份文件，以满足这两项需求。")
zh(299,"一块残缺的石板提及神祇的计划与注定的预言。维尔加需要找回缺失的碎片才能解读信息，但遗址中的生物阻碍了他的搜寻。")
zh(301,"获取更多炸药需探险者协会批准。报告必须送达铁炉堡的雷矛，尽管他可能对挖掘行动的缓慢进展不满。")
zh(302,"雷矛已批准为铁环提供新补给，并下达了前往塞尔萨玛的指令。由于上次补给从未抵达，他现在要求亲自监督以确保安全。")
zh(303,"黑铁族摧毁了基础设施并占领了丹莫德，而许多士兵正与其他地方作战。加玛森需要发动反击，为预备队抵达争取时间。")
zh(304,"这场战斗让布莱德失去了士兵与家人。报告指出巴尔加拉斯是袭击者首领，但他仍隐匿不出；找到他，便是复仇的唯一目标。")
zh(305,"塔雷尔已有将近两周未收到妻子的书信。麦琳在挖掘现场工作，她的沉默促使他前去探访，弄清团队发生了什么。")
zh(306,"当迅猛龙袭击挖掘现场时，奥莫尔保护了麦琳，使她得以生还。如今被困的她，留下便条让塔雷尔了解她的处境，而非无端等待。")
zh(307,"狗头人占据了一座耗尽资源的矿洞，将其改造成储藏仓库。矿工联盟希望在守卫进攻前夺回工具，以免设备受损。")
zh(308,"加文守护着马莱斯想交换的木桶。用麦酒招待他，能为调换木桶的计划制造分心，让客人不知不觉尝到竞争对手的酒。")
zh(309,"米兰必须运送一船炸药至铁环。道路危险，他担心再度遭遇黑铁势力的干扰，因此沿途护卫势在必行。")
zh(310,"马莱斯想证明她的啤酒能与雷霆酒一较高下。她提议在酒窖调换一桶，让客人在不知情中品尝竞争对手的佳酿。")
zh(311,"地窖里的木桶已经换过。一桶原酿麦酒就是凭据，马莱斯见桶便知，她的安排确已照办。")
zh(312,"冰须拿走了马克格拉恩为寒冬储备的物资。他伤腿无法从洞穴取回，食物补给正面临危机。")
zh(313,"石轮嫌攻城坦克里头硬邦邦的，想添些舒坦。附近雪怪巢里的鬃毛正好能织成一张毯子——冒险者也正好借此显一显胆色。")
zh(314,"瓦加什正猎杀艾默伯石的羊群，威胁着家族生计。军队远征期间，鲁德拉需要有人挑战栖息于牧场之上的巨兽。")
zh(315,"雷杰德正尝试酿造一款非凡的黑啤酒。一种用于巨魔仪式的植物风味独特，他想在新配方中加以测试。")
zh(317,"风箱正为长途行军做准备，需要补给坦克。当地野生动物既能提供旅途食物，也能供应毛皮做铺垫。")
zh(318,"风箱想要雷杰德的一杯酒，以御寒路途。其烈性灼烧不仅能暖身，更能为坦克引擎注入爆发力。")
zh(319,"雷杰德有这杯酒，却以一个请求作为交换。减少村庄附近的野生动物，能让居民有更多时间专注手艺与酿造。")
zh(320,"艾沃沙酒桶需待猎物协助后方可获取，它仍需送往贝隆·风箱手中，而他正守在钢架补给站等待补给。")
zh(321,"神圣铁器曾随一艘加入舰队以求庇护的船只沉没，戈罗林·钢眉指出了沉船残骸，或可从中寻回所需货物。")
zh(322,"回收的铁器需一位熟悉其特殊性质的铁匠，格瑞曼德·艾尔默或可将其锻造成对抗摩本特·费尔的利器，前提是获得材料并理解任务。")
zh(323,"斯温认可你的勇气，却不会贸然派你对抗亡灵巫师，须先测试你的实力。击败他的仆从，方能证明你足以直面摩本特·费尔。")
zh(324,"水淹的箱子仅存部分货物，揭露了鱼人盗取的真相。附近劫掠者或许仍藏有完成铁器回收所需的铁锭。")
zh(325,"对抗亡灵巫师的武器已备齐，将它交给斯温，便能将此资源交付组织对抗摩本特·费尔的阵营，继续筹备最终对决。")
zh(328,"账簿未直接提及索尔森，却暗藏一把钥匙与提及安全箱的线索。找到它，或许能揭开叛军内鬼暴露的真相。")
zh(329,"一份笔记详尽记录了索尔森的巡逻与谈话，其作者必曾近距离跟随，这份文件或可指引出叛军营地中的内鬼。")
zh(330,"签名只留下姓氏，但便条透露作者曾与索尔森一同巡逻。塞斯曼掌握着排班表，能辨认出那周与他同组的人是谁。")
zh(331,"巡逻记录已备齐，可呈报多伦上尉。返回他那里，便能将结果重新纳入调查，追究是谁泄露了索尔森的秘密行动。")
zh(332,"加林纳家族正沿暴风城运河推广酒铺。传单介绍店铺，并附赠一瓶酒，可向苏泽塔领取。")
zh(333,"对衣物与护甲的需求让哈兰的毛织品告急。他需要有人将补货请求送至供应商，才能重补库存。")
zh(334,"萨尔曼仓促离家，忘了学徒所需的缝纫工具。他母亲希望有人帮忙将工具送回，好让他继续工作。")
zh(335,"维沙克公爵正施压调查术士的据点。加尔德斯正筹备让公爵分心的计划，需要一些罕见植物来调配药剂。")
zh(336,"加尔德斯打算利用维沙克对酒的喜好，反击他针对酒馆的行动。特制酒已备好，需送至贵族手中。")
zh(337,"图书馆的印章标记出一本未归还的历史书。将它送回暴风城，便能补全缺失的卷册，还清遗忘的借阅。")
zh(338,"一阵风卷走了奈辛瓦里托付给校对员的手稿。若能在丛林中找回散落的纸页，便能重新拼凑章节，修复意外的破损。")
zh(339,"第一章讲述奈辛瓦里的故事与狩猎伙伴，但缺失的纸页必须收集，才能还原风中散落的手稿开端。")
zh(340,"第二章记载了猎虎与黑豹的经历，却仍不完整。找回这些纸页，能补全校对员未能收集的章节部分。")
zh(341,"第三章回忆了初用步枪的经历，结尾悬而未决。校对员记得内容，却需散落的纸页才能重组成这一段。")
zh(342,"终章缺失三页，难以重构完整。找回它们，方能恢复书的结尾，也保全校对员最感兴趣的片段。")
zh(343,"克里斯托弗正准备演讲，需要一部冶金学论著作为支撑。米尔顿熟识图书馆，能寻到连接这门学问与灵体力量的典籍。")
zh(344,"这部论著曾借给帕克斯顿抄写，却已逾期数月未还。前往修道院，或许能解释迟延，并找回原书。")
zh(345,"帕克斯顿尚未完成抄写，因墨水干得太快。他需要矿石准备新一批墨水，才能继续这项拖延归还的工程。")
zh(346,"复制完成，原作得以重见天日。将它交给克里斯托弗修士，可助他准备一篇关于灵体坚韧的演讲。")
zh(347,"对抗兽人之际，帕克顿的墨水原料难以为继。豺狼人亦盘踞洞穴，获取材料势必要直面他们的敌意。")
zh(348,"芬病入膏肓，坚信吞食莫克的心脏方能痊愈。唯有巫医安巴格瓦能唤出那白兽，他亟需你速寻巫医。")
zh(349,"安巴格瓦愿与灵体沟通，引出莫克，但要求猩猩牙作为交换。仪式还需防范其他野兽在召唤时现身。")
zh(350,"莱斯科瓦的势力与证人失散，寻常审判难有成效。肖尔建议寻求艾林格协助，应对贵族与迪菲亚的关联。")
zh(351,"奥格索普·奥布诺提斯的机器人坠毁于塔纳利斯，他以金属装置传递求救。他悬赏寻回，并提供坐标，助你将信号灯送回机器。")
zh(353,"格瑞曼德为远在暴风城外的登山者打造武器。你助铁匠将成品送达洛克莫丹的主人。")
zh(354,"阿加曼德为躲避祸害鼠的侵袭，劝诱工人留下。如今他们效忠天灾军团，对抗他们便是亡灵防御与昔日工人的复仇结合。")
zh(355,"你对阿加曼德家动手的事，已经惊动了执政官塞弗伦。这桩私仇如今也牵动提瑞斯法的安危：磨坊一日不除，被遗忘者便一日不得安生。")
zh(356,"尽管亡灵壁垒阻隔，仍有天灾军团渗透进提瑞斯法。巡逻队守护着守卫们的补给与后方，使他们不必同时应对两线战火。")
zh(357,"一名独立的尸巫误将其他亡灵当作天灾奴仆。比索需要调查他的身份与知识，以判断他是否可能成为被遗忘者的盟友。")
zh(358,"天灾军团正在挖掘提瑞斯法的集体墓穴，为士兵们准备新的仆从。对抗腐皮豺狼人能打断这股补给，阻止瘟疫受害者再次被征用。")
zh(359,"塞弗伦需要边境哨站的情报。林内亚的报告能揭示天灾军团是否已突破亡灵壁垒，成功潜入提瑞斯法。")
zh(360,"提瑞斯法的防御依赖前线及时的情报。递送这份报告，能让执政官塞弗伦掌握应对天灾动向的关键信息。")
zh(361,"萨尔曼写给格里高·阿加曼德长子的信，本该寄给伊维特·法席恩，却从未抵达。找到真正的收件人，才能完成这趟未竟的投递。")
zh(362,"代弗林·阿加曼德染上瘟疫，仍徘徊在家族磨坊之间。收集他的遗骸，是延续这场清算，也让那些成为被遗忘者的人深感不安。")
zh(363,"你从丧钟镇苏醒，意志重归自我，不再是巫妖王的奴仆。摩尔多派遣你前往萨维斯，去理解自己在亡灵中的新身份。")
zh(364,"你重获的意志使你与仍效忠巫妖王的亡灵划清界限。对抗那些无意识的入侵者，既是在保护丧钟镇，也是你为亡灵效力的开始。")
zh(365,"从人类农场偷取南瓜，可供给药剂师乔汉。这项任务考验你对亡灵利益与手段的忠诚，而血色十字军正密切注视着你。")
zh(366,"比索认出了冈瑟尔，这位曾是肯瑞托同伴的逃亡者，也挣脱了巫妖王的桎梏。将附带魔法证明自由的书本归还他，或许能说服他加入亡灵。")
zh(367,"希尔瓦娜斯已命皇家炼金房制造比已知疾病更致命的疫病，以摧毁阿尔萨斯的军队。乔汉需要黑暗犬的血液，来测试这种疫病是否能成为新配方的关键。")
zh(368,"乔汉需要他的疫病扩散至更多受害者。鱼人样本支持着实验，旨在将致命配方转化为更广泛的瘟疫。")
zh(369,"一份旧档案将一场毁灭性瘟疫与蜘蛛毒液联系起来。乔汉想要样本，以测试这种传染性病原体是否能增强他的新疫病。")
zh(370,"截获的情报显示，一支血色十字军部队由派瑞恩统领。破坏这支队伍，将推进亡灵对迫害亡灵组织的进攻。")
zh(371,"瓦松队长在巴尼尔农场附近指挥另一处血色十字军据点。削弱他的力量有助于阻止十字军在提瑞斯法巩固存在。")
zh(372,"攻势转向麦拉其队长的血色据点。攻击其领导层，支持争夺提瑞斯法旧塔的控制权，以响应黑暗女伯爵的意志。")
zh(373,"一封尚未拆封的信件出现在范克里夫的遗物中。信件寄往暴风城的建筑师，他应收到这份文件，以了解原本打算传达给他的讯息。")
zh(374,"瓦里玛萨斯要求你提供对抗血色十字军的证据。戒指可辨识阵亡者，证明你对亡灵领导层的效忠。")
zh(375,"格雷彻感受到亡灵寒意正侵蚀她的身躯，惧怕失去心智。她需要蝙蝠皮与线，缝制一条毯子，以便继续追随希尔瓦娜斯的事业。")
zh(376,"丧钟镇必须照料伤者与装备新兵，尽管资源有限。从附近动物身上搜集物资，既能维持聚落运转，也能确保自身安全。")
zh(377,"米尔斯迪普怨恨暴风城囚禁结界，而非执行夜色镇的判决。他要求处决结界，因他向亡灵巫师出卖尸体，将当局间的争执转化为一场暴力任务。")
zh(378,"加玛森怪罪深怒策划了杀害隆布雷德族人的袭击。他被束缚于岗位，只能寻找他人代为执行对暴风城囚犯的复仇。")
zh(379,"吉罗姆·比格维兹能为你提供所需的动力源，但首先他想喝点水。他提议以沙漠游牧民的水囊交换，你的装备便成了他口渴的代价。")
zh(380,"蜘蛛占据了死亡钟镇赖以生存的金矿，清理它们将恢复这个聚落无法独自开采的资源。")
zh(381,"血色十字军追捕所有亡灵，不分自由的被遗忘者与天灾军团。阿伦希望在它袭击死亡钟镇前，削弱它的新据点。")
zh(382,"一名血色信使携带着被遗忘者急需的情报。截获他或许能揭开十字军的意图，为死亡钟镇争取优势。")
zh(383,"截获的情报必须送到塞加德执行官手中，以指引对抗十字军的行动。你在死亡钟镇的服务，将引你前往布瑞尔，那里的指挥中心正需要你的协助。")
zh(384,"拉格纳的常规供货商已参战，酒馆的肋排原料短缺。他愿分享家族秘方，换取新鲜补给。")
zh(385,"鳄鱼肉与皮革吸引买家，但从湖中岛屿获取它们充满危险。马雷克提议一场狩猎，将贸易与严峻的挑战结合在一起。")
zh(386,"塔格尔曾折磨王国的守军，处决却给搁下了。伯尔顿疑心贵族中有人插手，主张赶在囚犯因此得利之前动手。")
zh(387,"监狱被暴徒攻占，塞尔沃特忧心暴风城与自身地位。他下令动用致命武力夺回控制权，迫使暴动者屈服。")
zh(388,"尼科瓦为孙子之死复仇，他死于狱警岗位。迪菲亚的头巾标记出囚犯身份，成为她要求报复的证据。")
zh(389,"建筑师将石匠暴动与贵族拒付重建费联系。范克里夫的旧部或可在囚禁中提供更多信息。")
zh(391,"塞尔沃特准许接近斯瑞德，却对任务与访客心存疑虑。他要求处决囚犯以证明忠诚，同时试图夺回监狱控制权。")
zh(392,"斯瑞德在多年孤立后开始定期接见访客。访客证件看似有效，但其描述为追查联络者提供了线索。")
zh(393,"建筑师不认得访客，转而求助更了解城中隐秘交易之人。肖尔可分析描述，协助深入调查。")
zh(394,"莱斯科瓦的威胁已解除，肖尔需知你的角色。报告须说明事件及其与针对城市的计划关联。")
zh(395,"建筑师想谈迪菲亚盗贼的行动。肖尔建议谨慎行事，避免透露可能暴露你的细节，也彻底省略了伊林格的参与。")
zh(396,"建筑师已准备好了报告，希望由你的调查结果作为补充。这场听证会将把迪菲亚的调查呈报给风暴城的相关人士。")
zh(397,"加尔德斯认为干预行动让术士们得以继续他们的活动。他的仆从正准备奖励，以表彰在维沙克事件中提供的协助。")
zh(398,"蛆眼正在偷取尸体以扩充巫妖王的军队。布瑞尔希望切断这股供应，并找出幕后主使，使其无法继续。")
zh(399,"巴隆斯·阿历克斯顿的家被烧毁，如今落入盗贼之手。他第一块指南针仍藏在农场，找回它或许能唤醒他西部荒野的童年回忆。")
zh(400,"钢架持续运作攻城坦克，但工具损耗远超常理。他的最新订单已备好，需送往靠近卡拉诺斯的车间。")
zh(401,"希拉需要一点时间完成翻译。等待他的工作，能让亚伯克隆比的信息在调查继续前，被完整理解。")
zh(403,"这桶被守卫的木桶是酿造业的较量之一。马莱斯希望用她自己的饮品替换，以证明雷霆酒馆并非唯一选择。")
zh(404,"天灾军团已占据布瑞尔附近的旧桥。正面冲突不仅能解除对聚居地的威胁，也能向他们的死灵卫展示结果。")
zh(405,"比索·埃斯沙德需要一名证明自身价值的代理人。塞弗伦派你前往幽暗城执行一项危险任务，目标是招募一名独立的巫妖。")
zh(407,"乔汉用偷来的南瓜装载了他的配方。将它喂给一名血色僧侣囚犯，你便直接参与了武装黑暗女伯爵的实验。")
zh(408,"达高尔队长正从墓穴中唤醒阿加曼德的祖先。阻止他，或许能阻止那些亡灵家人成为被遗忘者新的助力。")
zh(409,"比索的附魔已验明：你身上没有巫妖王的束缚。冈瑟尔却仍要你证明自己的立场。与莉莉丝·奈法拉一战，便足以说明你同样与天灾军团为敌。")
zh(410,"冈瑟尔要求你证明对天灾军团的敌意。一支蜡烛能唤醒莉莉丝在祭坛前，这场对峙将决定你能否赢得他的信任。")
zh(411,"冈瑟尔交给你一颗能联系比索的宝石。将它送达，能让旧日同伴重聚，分享他们所经历与所学。")
zh(412,"诺莫瑞根的灾难让许多侏儒沦为无智之躯。拉兹与奥奇正用一台新机器试图逆转效果，但仍缺少关键零件。")
zh(413,"雷杰德希望弟弟韦尔拉特尝尝他的新啤酒。虽然巡山人并不继承家族职业，但他懂得品酒，正守着木桶等待。")
zh(414,"韦尔拉特对弟弟的啤酒赞不绝口，想让卡德雷尔也尝尝。木桶得送到那位巡山人手上，他正巡逻着塞尔萨玛的山路。")
zh(415,"雷杰德一直在等你聊聊新酒。他的请求承前启后，再度邀请你前往烈酒村的酿酒人处作客。")
zh(416,"狗头人已在泰尔萨玛西边的山脚筑巢。卡德雷尔悬赏讨伐这群害虫，并要求交出战斗证据才能领赏。")
zh(417,"希尔德维尔的笔记记载了癞爪的袭击，也留下最后复仇的遗愿。他的尸身状态暗示，那头熊重返人间，要了结未竟之事。")
zh(418,"维德拉以独门手艺供养泰尔萨玛的百姓与工人。另一批酒需采集本地野味，以一顿热饭为交换。")
zh(419,"希尔德维尔留下破损的引擎，继续徒步寻矿。他失踪数日，夜里低吼让锤足忧心同伴安危。")
zh(420,"格林的报告必须穿越隧道才能送到卡拉诺斯的森内尔。穴居人借着这条通道袭击旅人，送信需冒极大风险。")
zh(421,"阿鲁高的魔法让银松森林陷入混乱，这处战略要地对亡灵而言至关重要。达拉尔·道恩维沃尔需要能对抗他的战士，并让你在路旁的狼人身上证明实力。")
zh(422,"亡灵渴望破解阿鲁高的魔法并反制他。寻回他的手稿，将揭开这场灾难的根源，而不仅仅是消灭残存的怪物。")
zh(423,"阿鲁高的手稿显示，魔化物品增强了他的法术。新的样本将助我们解析这机制，推进对银松森林危险魔法的调查。")
zh(424,"查案还在继续，被遗忘者又要收回那座遭阿鲁高腐蚀的矿场。格瑞姆森一倒，便再没人把持这处要紧的军事据点。")
zh(425,"伊瓦在侦查任务中重创了奎因。阻止这个尸妖或许能避免下一次袭击，也让伤势未愈的毒蝎虫争取恢复时间。")
zh(426,"天灾军团企图将阿加曼德磨坊变为进攻提瑞斯法的据点。你的行动将阻止他们在布瑞尔附近建立危险的立足点。")
zh(427,"丧钟镇的情报显示血色阵营的布防。而死亡守卫中也混杂天灾军团，你的攻击将利用这情报，不牵动守军其他战线。")
zh(428,"两名死亡猎手在银松森林北境的侦察中没了音信。寻见兰妮与奎因，既能查明二人是否生还，也能取回他们记下的所见。")
zh(429,"奎因重伤，兰妮担心他无法靠自身恢复。座狼之心可为伦弗利尔提供炼制药剂的材料，必须带回给伤员。")
zh(430,"伦弗利尔配制了一种药剂，助奎因伤后复原。这剂良方必须送到北面的亡者哨兵手中，他仍停留在腐烂者据点附近，正是被袭击的地点。")
zh(431,"蜡烛能让莉莉丝现身，应冈瑟尔的考验。获取一支蜡烛是必要的准备，之后才能证明这位冒险者并非天灾军团的仆从。")
zh(432,"穴居人正毁坏采石场，摧毁炸药。石眉无力独自对抗，便出价酬谢任何能削弱入侵者存在的勇者。")
zh(433,"挖掘行动释放了穴居人，毁坏装备并驱散矿工。圣石希望采石场能被清理，以便重建设施，让开采工作重归正轨。")
zh(434,"一副伪装，一份假情报，只为让莱斯科瓦与马尔松碰头。成败在于能否听清他们与迪菲亚的密谈，并在守卫短暂离岗的间隙动手。")
zh(435,"狼群阻止了埃兰德前往兰妮·尤瑞克处报信。他需要护卫，最好有更多同伴同行，以保他在前往同僚亡者哨兵的途中安全。")
zh(436,"铁环的挖掘工作进展缓慢，尽管已获得补给。与组织者交谈或许能解释为何一位勤勉的工人遭遇阻碍。")
zh(437,"奈塔拉什的魔法屡次击退腐烂者据点的进攻。若能移除她的保护，或许能瓦解天灾军团在亡者农场据点的优势。")
zh(438,"天灾军团的豺狼人与亡灵占据了码头。调查其意义，能让被遗忘者在决定应对策略前掌握情报。")
zh(439,"尸体间有一只女子的祸害鼠印记之手。一枚戒指刻着黛莉娅之名；将它带给哈德瑞克，便能呈上在天灾占据的渡口发现的线索。")
zh(440,"你追寻黛莉娅戒指背后的身分。执政官塞弗伦的档案或许能将戒指上的铭文与某人连结，但能辨认它的存在，未必能苟活。")
zh(441,"塞弗伦在幽暗城发现黛莉娅与莱雷恩可能有某种关联。将戒指交给他，或能验证这条线索，并揪出他过往的某个人。")
zh(442,"哈德瑞克希望发动突袭，摧毁森林中的天灾据点。图勒·鸦爪是这场既危险又关键的攻势目标。")
zh(443,"在进攻芬里斯前，被遗忘者需要弄清是谁制造或掌控了腐烂者。伦弗利尔将研究维系这些天灾豺狼人的神秘液体。")
zh(444,"这液体蕴含巫术与亡灵魔法，但其源头仍不清楚。贝索尔的魔法经验，或许能协助药剂师们研究这液体样本。")
zh(445,"乔汉希望与伦弗利尔分享研究成果，以加速新祸害鼠的开发。将资料交给对方，便能串起两位研究者，共同打造瑟兰妮斯的武器。")
zh(446,"比索·埃斯沙德认出图勒·鸦爪曾是同伴，如今却效力于天灾军团。他的知识或许能助伦弗利尔找到对抗它的方法。")
zh(447,"伦弗利尔寻找一种能同时对付天灾军团与人类敌人的毒药配方。收集材料是法拉尼尔研究亡灵瘟疫武器的另一阶段。")
zh(448,"哈德瑞克希望在芬里斯进攻前见你一面。他的情报或装备，或许能助亡灵达成决定性行动。")
zh(449,"奎因正在恢复，但他的侦查报告不能再等。将它交给哈德瑞克，就能让毒蝎虫的观察落入银松森林指挥部手中。")
zh(450,"阿鲁高让药剂师博拉尔德沦为无智仆从。找回他的笔记，能保存关于湖中瘟疫的潜在知识，而非随他一同湮灭。")
zh(451,"博拉尔德的笔记提及洛丹米尔湖中生物的苔藓，以及鱼人身上罕见的肿瘤。伦弗利尔希望这些样本能交到法拉尼尔手中，研究其在新瘟疫中的用途。")
zh(452,"焚木村的议会协助阿鲁高掌控追随者。趁法师不在时发动攻击，旨在瓦解这道命令体系。")
zh(453,"这名陌生人离开夜色镇往西而去，他紧张的举止或许能助于辨认身份。但要搜寻他，也需考虑他沿途可能遭遇的危险。")
zh(454,"伏击之后，分工已然明确，米兰独自搬运火药却缺乏保护。他的同伴希望有人能陪同他护送下一批货物。")
zh(455,"兽人占领丹奥加兹，威胁着洛克莫丹与港口的联系。突破山口、直面入侵者，意在守护这条战略要道。")
zh(456,"连绵大雨助长了野猪与夜刃豹的气焰，其他动物却苦不堪言。伊尔萨莱恩希望它们的数量与森林资源相称，以维系自然平衡。")
zh(457,"初步干预未能守住森林资源。伊尔萨莱恩认为必须进一步削减过度繁衍的族群，哪怕这意味着终结林间生灵的生命。")
zh(458,"森林之魂宣告塔琳德拉归来，她数年未现身。她的现身令守护者不安，他们必须弄清这位树妖为何重返林间。")
zh(459,"熊怪们正纷纷离家，聚集的规模令人警觉。塔琳德拉怀疑是腐化的魔苔作祟，想要检查附近的格雷尔是否受其影响。")
zh(460,"泰勒曾抵御祸害鼠的侵袭，却因此被困于亡灵的折磨。将他的头颅与躯体重聚，回应了他渴求解脱的呼唤。")
zh(461,"阿尔瑞克知晓一处藏匿之所，那里有泰勒与旧日同僚珍视之物，也或许有你用得上的东西。他请你将他的躯体送至城堡内那隐秘的角落。")
zh(463,"绿守护者雷希耶尔藏身沼泽深处，与那里的生物为伍。有路人愿指点方向，却坦言此行凶险，只愿提供一条远离大路的线索。")
zh(464,"龙喉氏族在上次败北后重振旗鼓，另建营地。要塞方面欲以攻击回应其扩张之势，需以旗帜为证。")
zh(465,"龙喉氏族的投石车威胁着米奈希尔，而丹奥加兹的战斗封锁了增援。要塞必须先摧毁这攻城武器，方能正面迎战指挥进攻的酋长。")
zh(466,"石轮认为某种易爆矿石若能妥善运用，或可提升弹药威力。他需采集样本做实验，但获取它们需要采矿技巧与深入危险洞窟的勇气。")
zh(467,"石轮正寻求增强攻城坦克的火力。听说一种稀有矿石后，他求助协助寻找材料，以期实现武器改良。")
zh(468,"罗克加正招募愿意穿越丹奥加兹、深入湿地的志愿者。前往他的哨所，便可得知这项任务，再沿北方路线启程。")
zh(469,"一批兽皮需运往米奈希尔的坦纳处。其运输者希望借助另一名旅人的行程，同时延宕他急于避免的归途。")
zh(470,"塞达甩出袋子逃过黏液生物的追击，却让其中一者吞噬。她需找回袋中物品，却无法辨认是哪只墓穴中的生物吞下了她的财物。")
zh(471,"哈尔兰的学徒在采集鳄鱼蜥皮时受了重伤，生死未明。制革匠仍需补给，正寻找能面对海岸巨兽的勇者。")
zh(472,"一名受伤的士兵回忆丹莫德的陷落与他部队的撤退，担忧同伴安危，求寻布莱德·长须，却不知其首领是否生还。")
zh(473,"龙喉氏族的威胁远不止于奥加兹小径。斯托菲队长正招募志愿者，他能从驻防点说明要塞应如何应对兽人。")
zh(474,"投石车已成废木，内克罗什却仍握着他的兵马。下一步，刀锋转向这位酋长——取回凭证，才好当着守军的面证实此事。")
zh(475,"盖洛拉斯守着沉睡的德鲁伊，好让他与伊瑟拉的契约不至落空。他的回报迟迟未到，众人心里不安——须有星风村的消息，才能探明这些德鲁伊是否平安。")
zh(476,"盖洛拉斯遭腐化的熊怪袭击，如今那些怪物正洗劫村庄。他的伤势让他无法警告阿斯瑞达斯，也难以提醒沉睡的德鲁伊们即将来临的危险。")
zh(477,"达拉然支持安伯米尔的人类抵抗，但其目的仍未明朗。截获一批货物，或许能解释为何法师仍投入资源于这个偏远聚落。")
zh(478,"你从达拉然法师押运的货箱里翻出一枚奇异的吊坠。奥利斯特要拿到它，才好顺着这条线追查运往安伯米尔一带的货。")
zh(479,"达拉尔追查安伯米尔的魔法之力来源。夺取法师的吊坠能干扰他们的计划，为亡灵的反击争取时间。")
zh(480,"一位大法师正重启能量节点，奥利斯特担心已无他法。攻击他意在阻止计划，哪怕他被严密保护。")
zh(481,"找回的吊坠需魔法解读。将其交予达拉尔，让他探究它与安伯米尔法师计划的关联。")
zh(482,"达拉尔发现安伯米尔地下沉睡着一个能量节点。告知奥利斯特吊坠的下落，助他思索如何阻止重启计划。")
zh(483,"入侵者威胁着沉睡于班尼希尔的德鲁伊。若无那里的圣物，他们的冬眠仪式无法中断，恐永远困在翡翠梦境。")
zh(484,"哈洛兰将皮革卖往远方港口，却缺乏更柔软的皮料。幼鳄蜥提供他维持鞣皮生意所需的原料。")
zh(485,"奥格索普的声音从奇异装置中传来，请求协助找回坠毁的机器人。他计算出其位置在辛特兰的隐匿石附近，需你将信号灯带往那里。")
zh(486,"阿斯瑞达斯正准备唤醒德鲁伊，但仪式需击败乌萨尔。他的干涉引发危机，若不加以阻止，沉睡者恐无法苏醒。")
zh(487,"被腐化的熊怪袭击威胁着多兰纳尔与达纳苏斯之间的道路。阿玛拉必须守护这条路线，每天都有旅人、商队与重要情报经此穿越森林。")
zh(488,"赛恩承诺以非凡报酬换取从林间动物身上获取的材料。他坚持保密这项交易，却未解释这背后的真正意图。")
zh(489,"议会谴责协助赛恩，一个森林的敌人。要重获信任，必须递给他被腐化的种子，让他误以为是无害的零食。")
zh(490,"达纳苏斯议会视被腐化的熊怪为人类与野生动物的威胁。他们悬赏击杀该族，以獠牙作为证据。")
zh(491,"这支魔杖曾与三位学徒的魔杖相连，象征他们的友谊，直到图勒的背叛。归还给比索，便能重拾那段被偷走的过往。")
zh(492,"乔汉希望将他的新配方测试在一名被俘的登山者身上。递上这杯药剂，便成为炼金房研发瘟疫武器的一环。")
zh(493,"皇家炼金房正分享成果以加速新瘟疫的开发。将银松森林的研究带往林度恩，便能将合作延伸至塔伦米尔。")
zh(494,"莱什被派往监视希尔斯布莱德镇，需将紧急讯息送往高级执行官达萨利亚。她要求你成为塔伦米尔指挥部的联络桥梁，速递无误。")
zh(495,"穆格·托尔戴上了他奉命取回的王冠，也因此获得了对希尔瓦娜斯控制的抗性。她要求处以极刑，并指派梅里萨拉从塔伦米尔组织应对行动。")
zh(496,"林度恩研究能对人类造成致命伤害的物质，却苦于无暇收集。他转而向当地动物寻求成分，以继续他的化学混合物实验。")
zh(498,"克鲁斯克在辛迪加突袭任务中逃脱，同伴们却被囚禁在敦霍尔德城堡。他们需要援手，才能从击败他们的堡垒中脱身。")
zh(499,"药剂已调配完成，林度恩希望测试其效果。他的助手将成为一场实验的受试者，这场实验牵涉针对人类与天灾军团准备的物质。")
zh(500,"食人魔占据了阿尔萨拉的废墟，雷德帕斯担心他们可能进一步侵入山脚地带。他悬赏以削弱他们的存在，避免他们更直接地威胁南海镇。")
zh(501,"林度命认为狮血可助他调配新的致命混合物。他的研究目标，是以黑暗女伯爵之名，传播疾病与死亡。")
zh(502,"以血液为基的药剂需先测试，才能评估其效用。林度恩选了一只农场犬作为实验对象，并要求施以药剂。")
zh(503,"寻回的文件指向辛迪加的一处据点——戈尔迪就囚在那里，被关得太久了。克鲁斯克要你探明他的下落，把他救出来。")
zh(504,"雷德帕斯希望在初步冲突后加大对阿尔特拉克食人魔的压力。攻击他们的战士，旨在阻止他们靠近联盟守护的领地。")
zh(505,"新任官吏怀疑辛迪加雇凶杀害了他的前任。最新的线索指向一个营地，他打算亲自前往，揭开那起悬案的真相。")
zh(506,"戈尔迪得知了奥里登的奴隶计划，并目睹了统帅所追寻的吊坠。这些情报必须尽快传递给克鲁斯克，而俘虏则正设法安排自己的脱身。")
zh(507,"线索查下来，匹瑞诺德已是个非死不可的人。去洛丹米尔湖畔他的庄园，取回酋长要的那枚吊坠——先向艾丽萨问清它的下落。")
zh(508,"艾丽萨交出吊坠，请求不再被过往的回忆打扰。将它交给克鲁斯克，继续追索那件被追寻之物的归途。")
zh(509,"林度恩持续研制能传播疫病的药剂，而人类与天灾军团仍在厮杀。附近农场的花朵，正是他下一批实验药剂的关键成分。")
zh(510,"补给请求包含一项紧急任务的装备，这细节使文件成为官吏亟需评估的警告——敌人正策划着怎样的威胁。")
zh(511,"一封密文信件静卧在桌上的文件中，未显露其内容。将它交给博学者迪布斯，方能知晓作者试图掩盖的真相。")
zh(512,"官吏担忧辛迪加昔日贵族正图谋南海镇的毁灭。他希望尽快锁定这些首领，以他们佩戴的徽章为标记，阻止他们实施计划。")
zh(513,"花朵已制成化合物，但配方尚缺一环。法拉尼尔可加入其腐化制剂，唯有将此物送往幽暗城，方能推进这项工作。")
zh(514,"迪布斯需要专家协助解读这封信件。雷矛精通晦涩文字，或许能从铁炉堡的典籍中找到线索，让调查得以继续。")
zh(515,"法拉尼尔已加入其腐化制剂，并说明如何激活污染剂。林度恩需此混合物及其剩余材料，才能在塔伦米尔继续实验。")
zh(516,"情报显示亡灵正筹备攻击，但其位置尚不明确。奥利斯特希望尽快找到他们，阻止其对己方发起进攻。")
zh(517,"林度恩想将传染性混合物用于更多目标，而不仅仅是之前用过的动物。从丹加洛克取来的酒桶，正是继续实验的关键。")
zh(518,"穆格·托尔受奥特兰克的巨魔保护。梅里萨拉希望先削弱他们的力量，创造机会惩罚他，而不会面对他周围集结的全部势力。")
zh(519,"穆格·托尔有三位忠心副官支持他。梅里萨拉希望先除掉他们，并取下首级作为证据，为日后对抗巨魔首领、夺回王冠铺路。")
zh(520,"梅里萨拉已击溃穆格·托尔的部下，如今只想终结其族的抵抗。前去擒获首领，他大概正等着一场袭击，并带回他的首级与意志之冠。")
zh(521,"夺回的冠冕必须交到沙琳德拉手中，由她转交希尔瓦娜斯。梅里萨拉警告切勿心生觊觎，穆格·托尔的结局已是最有力的劝诫。")
zh(522,"一份契约下令处决马雷布镇长，且盖着独特印记。这份文件必须送达目标，以示警并协助追查幕后主使。")
zh(523,"契约上的签名指向巴隆·瓦杜斯，他是阴谋的主谋。马雷布希望他在辛迪加的避难所现身，以回应这份将镇长列为暗杀目标的命令。")
zh(524,"被俘的农夫在军事疑云被证伪后，已被交付利顿处置。他计划用污染的酒桶，将他们变成最新实验的受试者。")
zh(525,"信件已解密，但内容仍令人不安。马雷布需亲自查看，因南海镇是奥特兰克最近的聚居地，可能受其揭示的威胁波及。")
zh(526,"一块金属不足以打造所需武器。戈罗林要求更多，藏在近海的鱼人残骸附近，那可能还藏着神圣铁的余货。")
zh(527,"达萨利亚指挥对人类发动攻势，同时药剂师们研制新疫病。首波袭击针对农田与粮仓，使劳工与地主成为指定牺牲品。")
zh(528,"农夫因袭击事件被迫南迁，达萨利亚欲率军穿过果园追击，以延续攻势并阻止他们逃入城外的作物区。")
zh(529,"人类的抵抗仰赖本地铁匠提供的武器，达萨利亚意图切断这一来源，夺取铁器供己方使用，持续征战。")
zh(530,"拉林夫·安迪恩将妻子之死归咎于旧友瓦德雷，戒指的故事化作复仇的号角，不容嫌疑犯遁入格雷迈恩之墙后方。")
zh(531,"达瑞尔拒绝让血腥的战利品留在猎屋，必须将奥尔·斯图的头颅送往维林，延续猎捕行动中证据的传递。")
zh(532,"居民虽屡遭损失仍继续战斗，围绕领袖凝聚力量。达萨利亚意图摧毁这些领导核心及其象征，瓦解城镇持续的抵抗。")
zh(533,"据报，戈尔迪在几个人类看押者手里被辗转转移。近处一座营地成了搜寻的重点，那里或许握着他如今囚在何处的实情。")
zh(535,"瓦里克受了伤，预料访客会杀他，即便如此，仍以情报换取一杯酒，让这点微末补给成为继续调查的契机。")
zh(536,"法伦奉命处理鱼人，却避而不战，寻求有人代他沿海岸执行这项被忽视的职责。")
zh(537,"这封信将纳伽兹与一个陌生的辛迪加盟友团体联系起来。赫尼·马雷布认为这条线危险，下令在敌人最强大的地方寻找他们的使者。")
zh(538,"阿尔特拉克的陷落让一座重要的图书馆暴露于荒废之中。这次搜寻旨在将那里的知识带回暴风城，博学者迪布斯能从最近的幸存聚落指引探索方向。")
zh(539,"恢复的登记簿指明这座矿是联盟铁矿的重要来源。达萨利亚想要袭击那里的工人与工头，以回应这项行动仍获得的支持。")
zh(540,"食人魔占据着阿尔萨拉克的废墟，那里还留着珍贵的书籍。迪布斯希望尽可能抢救出这些典籍，尤其是一本关于巨魔传说的古籍，对他研究至关重要。")
zh(541,"矮人对人类的帮助让达萨利亚扩大了攻势。对丹加洛克的攻击旨在惩罚那场联盟，同时阻止指挥当地要塞的指挥官。")
zh(542,"迪布斯将自己需要研究的文本留下，其余恢复的书籍则送往暴风城。将它们带到米尔顿，便能将这些典籍加入促使它们被抢救的收藏之中。")
zh(543,"阿尔特拉克前统治者佩戴的冠冕在王国覆灭时遗失。传言它落入食人魔之手，为找回这件家族传家宝提供了线索。")
zh(544,"四名被遗忘者带着他们药剂师研究所需的物品逃走。达拉然的法师们将它们隔离检疫，希尔瓦娜斯要求夺回她们从她宝库中偷走的神器。")
zh(545,"结界一散，几处封存的地界露了出来，其中或藏有魔法宝物。法师与元素生物的巡逻堵住去路，须削减城周这股兵力，才好放手探寻。")
zh(546,"沙穆萨眼红参与战役的同伴，自己却只能守卫。他想扩充人类颅骨收藏，愿付酬金给战斗中集结的众人。")
zh(547,"亨伯特在丹加洛克守望时遗失装备，怀疑被矮人斥候拿走。重获佩剑需在驻军中搜寻，看谁可能带走了它。")
zh(549,"瑟兰娜斯的当局将辛迪加列为敌对势力，并悬赏缉拿。其部队正集结于敦霍尔德废墟，命令亡灵展开反击。")
zh(550,"达萨利亚为你的战功写下了嘉奖令。将其呈给瓦里玛萨斯，可向高层汇报她认为值得表彰的亡灵事迹。")
zh(551,"一道魔法让羊皮纸仅剩纳伽兹之名可辨。将它交给迪布斯，或可解读出受保护的信息及其与调查的潜在关联。")
zh(552,"赫尔库拉死于一场仪式，被人类草草掩埋。塞万德要为他报仇——动手之前，先得取回那位法师的魔棒，如今它落在雪人占据的巢穴里。")
zh(553,"魔杖须先以三道仪式烈焰充能，方能带往坟墓。塞万德意图以此仪式向南海镇复仇，那里埋着他主人的尸身。")
zh(554,"这卷魔法羊皮纸需要专业知识解读。雷矛懂得破解密文，或许能在铁炉堡提供解读，揭开文书下仍被魔法遮掩的讯息。")
zh(555,"这一带不太平了，杰森再难下海捕龟。他要肉与香料，好把那道菜重新做起来——为这一口，客人甘愿跋涉远路。")
zh(556,"达拉然的法师以符咒驾驭元素生物。伍德格莱尔希望研究这些物件，更需采集样本，最好是避开直接闯入魔法之城的危险。")
zh(557,"元素生物的臂铠与已收集的控制符咒相辅相成。贝尔瓦里想预判研究者的所需，获取那些束缚这些生物、使其为法师效力的契约样本。")
zh(558,"你的结界赞赏吉安娜，梦想成为联盟英雄。因畏惧打扰如此重要之人，孩童托你代为索取她在塞拉摩的签名。")
zh(559,"光凭一句回报，雷德帕斯不肯认账——他要的是沿岸鱼人被斩的凭证。法伦再度开口请你帮忙：去收拢残骸，好证明这活儿当真办成了。")
zh(560,"法伦宁愿避开雷德帕斯要求的头颅。既然你已携带，他请完成交付，好让上司收到他所要求的证据。")
zh(561,"雷德帕斯将法伦的行动转向东部海岸的娜迦。命令必须与报告结果的亲口陈述一同送达副官。")
zh(562,"法伦视水下之敌为重返暴风城的机会，却无力独自应对。他需借助他人之力，以成果支持自己渴望的调动。")
zh(563,"法伦期盼旧日导师能借其报告，助他重返暴风城。他需一名信使，暗中递送请求，不惊动雷德帕斯的耳目。")
zh(564,"达伦忧心马匹损失，视山地狮为最大威胁。与这些野兽搏斗，旨在守护动物免受来自奥特兰克山麓的掠食者侵袭。")
zh(565,"巴图罗向顾客自豪地推销雪人皮斗篷，其品质堪称上乘。这件委托需布料与工艺，由其他匠人协作完成。")
zh(566,"达萨利亚认定巴隆·瓦杜斯是辛迪加的头目，手上沾着亡灵的账。她悬下赏格：去奥特兰克寻他，带回他已死的凭证。")
zh(567,"达萨利亚悬赏数名希尔斯布莱德居民，指他们袭击亡灵与补给。这些人散藏在乡野各处，令上写得清楚：每一个目标的死，都要有凭证。")
zh(568,"迅猛龙阻断格罗姆高通往斯通纳德的补给线。其指挥官希望减少营地周边的威胁，以保护部落成员，并支持这场关键的后勤行动。")
zh(569,"食人魔无视先前警告，袭击商队。格罗姆高的指挥官需迅速回应，以维持斯通纳德的补给，逼迫他们撤离已占据的废墟。")
zh(570,"莫克·萨尔丁想将丛林的魔力封入一件附魔物品中。他的仪式需要保存完好的猫科生物成分，这些材料必须在他继续这项魔法工作之前取得。")
zh(571,"莫克·萨尔丁需要一条魔法锁链来捆绑他收集的材料。唯有完美无瑕的成年大猩猩肌腱才可胜任，因此他派你前往藏宝海湾以东寻找合适的样本。")
zh(572,"首批材料只是莫克·萨尔丁为部落效力所欲附魔物品的开端。他如今需要佩戴迅猛龙饰品的羽毛，与其它材料结合，完成萨满祭司的仪式。")
zh(573,"附魔最后需要一种试剂：被不同文化视为圣水的泉水。莫克·萨尔丁警告说，一条娜迦探险队已抵达此地，你必须在取水途中与其正面交锋。")
zh(574,"在削弱常规部队后，叛军需要直面库尔森最精锐的士兵。他们的残暴与忠诚使他们在情报带回多伦上尉之前，成为极其危险的对手。")
zh(575,"一项重要订单需要新鲜皮革供崔斯里克的车间使用。淡水鳄的皮毛正是打造他皮革制品系列所需材料，足以开启生产流程。")
zh(576,"独眼迪兹通过一枚附魔玻璃眼重获视力，却遭血帆海盗夺走。失去它后他再度陷入无助，需要你找回让他重见光明的物件。")
zh(577,"靴子的基本形状已成形，但内层材料尚缺。崔斯里克想要更厚且更便宜的皮革，用于隐藏部位，无需外层的精细处理。")
zh(578,"传闻里有个法师，还有一群元素生物，顺着这条线，也许能摸到海潮之石。里维加兹请你去岛上走一趟，还愿把一本书借你——那则传说，他最初就是从这书里读到的。")
zh(579,"丹亚·托瓦尔德接受了一张图书馆手稿，以换取阅读材料。这项差事让这份文件得以用于挑选他暴风城书摊上的书籍。")
zh(580,"一场风暴中，滑鳗打开的瓶子被海浪卷走。他担心船长会因丢失货物而责罚他，急需沿辛特兰海岸找回这些瓶子。")
zh(581,"耶尼库在黑暗之矛部落离开时与族人失散。尼姆布亚怀疑另有部落关押着他，正寻求协助对抗该部落，同时寻找他酋长之子的下落。")
zh(582,"尼姆布亚怕耶尼库已死，要人翻看猎头者的战利品，查一查这个可能。细看这些标本，也许能解开那桩仍搅得他部落不宁的失踪。")
zh(583,"抵达营地，有机会结识奈辛瓦里——一位经验丰富的著名猎人。他对同袍的敬重，或许能开启一段关于丛林猎大型猎物的对话。")
zh(584,"寻找耶尼库的线索仍无定论，尽管他的头颅并未在遗骸中出现。由于血顶首领不愿开口，计划是取下他们的头颅，借魔法逼问情报。")
zh(585,"内兹利奥克的灵体声称知晓耶尼库的下落，却要求献上敌人的头骨作为代价。他想用这些头骨奴役灵体，这正是获取情报的代价。")
zh(586,"甘祖拉的头颅要求鲜血与复仇，才肯伸出援手。他挑战你攻击裂颅者敌人，直面安纳特克，期盼严酷任务能将你引向死亡。")
zh(587,"迪格发现他想在港口买的鼻烟被血帆盗走。他希望你找回部分货物，以满足他航海后最喜爱的习惯。")
zh(588,"奈兹里奥克揭示赞吉尔掌控了耶尼库的身躯与灵魂。他认为唯有非凡魔法才能解救他，向金威莱寻求帮助，或许能从黑暗之矛盟友中找到援手。")
zh(589,"金威莱认为一颗传奇宝石或许能助他夺回耶尼库。他向灵体寻求宝石下落，却需石化蜥蜴碎片，以驾驭神器之力。")
zh(590,"卡尔文·蒙泰古否认欠你钱，并拒绝了随索赔信件而来的信函。他的回应引发丧钟镇的冲突，你必须击败他，以了结这笔债务之争。")
zh(591,"金威莱发现‘心灵之眼’正由玛伊·佐斯掌控，这名食人魔法师即便没有神器也已危险万分。夺回它意味着直面他的魔法，但巫医认为这是拯救耶尼库的唯一希望。")
zh(592,"金威莱已将神器重塑为一颗宝石，能令耶尼库呆滞并捕获他的灵魂。将它带到耶尼库与赞吉尔同住之处，再呈给尼姆布亚，继续营救行动。")
zh(593,"当尝试解救耶尼库时，他呆立在你面前，被赞吉尔操控。金威莱准备的宝石可捕获他的灵魂，送往尼姆布亚——这一互动正是营救行动的一部分。")
zh(594,"一瓶中封着一位被囚于孤岛之人求援的恳切祈求。海岸与远方船只的提及，是唯一能指引寻人与回应呼救的线索。")
zh(595,"血帆势力已在荆棘谷南部现身，黑水掠夺者亟需了解他们的对手。克拉兹见船员们正忙着在港口庆祝，便托你探查附近海湾的情状。")
zh(596,"金·维莱耶协助寻找耶尼库，同时亦在推进其部族的私利。敌方项圈对他而言是战利品，能借此掌控曾佩戴之人。")
zh(597,"地图标出藏宝海湾旁一处秘密营地。图上的吩咐写明：等信号一到，便动手；闯入者格杀勿论。克拉兹须听到这份证据——有人正谋划一次进攻。")
zh(598,"尽管黑暗之矛已撤离荆棘谷，但他们与裂颅者的战争仍未停息。金·维莱耶若你愿对抗敌对部族，并带回项圈作为支持的证明，便愿与你结盟。")
zh(599,"证据指向血帆对藏宝海湾的袭击。克拉兹察觉威胁远超预期，亟需你速告卡拉·海角，让舰队指挥层知晓敌方的阴谋。")
zh(600,"克兰克指控风险投资公司阻碍其他地精在荆棘谷获利。他欲取山丘中的晶石，以挑战其商业霸权，并将样本据为己有。")
zh(601,"里维加兹欲先弄清石头的诅咒，再图占有。元素生物的护腕仍残留魔力，专家或可借此分析，寻得破解之法。")
zh(602,"护腕需要专家鉴定，里维加兹信赖安斯雷姆的学识。将样本送给他，是为了探寻诅咒在达拉然重建工程中法师们身上引发的异变与魔法隐患。")
zh(603,"这块石头的力量通过祭坛被放大，而一把古旧匕首或许能扰乱此力。安斯雷姆将这件遗物赠予女儿，让她成为寻找它的下一位人选。")
zh(604,"海角需要弄清血帆的计划，他托你潜入他们的海岸指挥站，夺取地图与书面命令，以厘清对舰队的威胁。")
zh(605,"石化蜥蜴吞食珍贵晶石以强化鳞甲，菲兹巴布想将它们出售，但风险湾公司阻挠他的收集，迫使他雇人从怪物身上取回样本。")
zh(606,"麦金利想借恐吓手段收走沙基的赌债，他需要猿类遗骸伪装成更可怕之物，好让债务人想象最糟结果，提前付清欠款。")
zh(607,"沙基交出钱袋以还债，并请求停止暴力。将钱与他关于饮酒与混乱拖延付款的借口一并送交，他坚称这笔债早有偿还之意。")
zh(608,"血帆的计划已现，海角欲先发制人，不调遣整支舰队。他提议集结精锐同伴，潜入菲尔拉伦的降落点，铲除敌方首脑。")
zh(609,"麦金利仍向传闻在诅咒中游荡于废墟的债主索债，他们的厄运在他眼中毫无同情可言：他要找到欠债人，夺回他视作还款的物件。")
zh(610,"利刃凯特琳愿意出借她的匕首，但另一名海盗正握着它。从邓肯手中夺回匕首，将延续她父亲认为对抗祭坛所必需的工具的寻找。")
zh(611,"匕首被寻回，凯特琳辨认出水下遗迹可能是祭坛遗址。出借匕首可尝试切断魔法联结，前提是武器之后能归还。")
zh(613,"玛雷的战利品锁在他的脚里，麦克金利无法打开。他怀疑玛雷赌局中与巨魔打交道的对手在赶他走后留下了钥匙，因此你必须调查他们的聚居地。")
zh(614,"巨人摧毁了斯莫特的船只并杀死了他的船员。高拉什还拿走了他的箱子用来当鼻烟盒；这位残破的船长希望从帮助毁掉他生计的巨人手中夺回这件物品。")
zh(615,"斯莫特在试图报复巨人时失去了第二艘船。奈古拉什在那次灾难中偷走了他的斗士短剑；幸存的船员斯普罗格可以协助找到罪犯并夺回武器。")
zh(616,"水手的传言里有一座岛：岛上有元素生物，还据称有地精鬼魂。报信人想把这段故事说给里维加兹——他素来留心这一带的怪事。")
zh(617,"布劳兹知道娜迦手中掌握着一种利润丰厚的海蛇草贸易。他提供工作，收集一批供应，承认自己不知其用途，但知道他的联系人出价很高。")
zh(618,"斯普罗格记得在船只被袭击时，奈古拉什曾寻找酒和秃鹫的翅膀。他提议将这些食物放在旧救生艇中作为诱饵，引出巨人并创造夺回斯莫特短剑的机会。")
zh(619,"斯莫特船长的复仇号废弃救生艇成了布下诱饵的好地方。斯普罗格提议利用奈古拉什的食欲引出巨兽，夺回他被偷走的斗士短剑。")
zh(620,"找回的腰带做工精良，边缘绣着HS字样。这个标记能指引我们找到它的主人，也将指向该归还之人。")
zh(621,"赞吉尔用植物混合物压制追随者的意志，增强他们的体魄。克兰克认为这种力量对任何想要掌控他人的人来说都极具价值，他想获取样本，自行研究其用途。")
zh(622,"克拉兹克在你离开期间修好了陶罐，并加以改良。将它归还给卡雷布，就能恢复营地厨师日常烹饪所需的机械辅助。")
zh(623,"格罗伊对之前的货物满意，现在需要更多芦苇满足客户。由于布劳兹短期内不会前往塞拉摩，他便委托你送货，让生意不必等待他的旅程。")
zh(624,"谜语将你的搜索引向悲伤沼泽的一座桥。诗句暗示线索藏于桥下，挑战你解读地理描述，继续这场神秘旅程。")
zh(625,"另一条线索将谜题引向卡利姆多与尘泥沼泽的危险。讯息指向西南方向的洞穴，那是继续考验、揭开更深层秘密的下一站。")
zh(626,"最后的信息指向辛特兰海岸，承诺在壮丽瀑布脚下有宝物沉睡。寻获它需要解读线索，并穿越这片动荡之地。")
zh(627,"克拉兹克同意修复陶罐，但要求在工作期间提供血石矿。即便是最次等的矿石，对懂得其用途的人而言也价值连城，获取它或许需要矿工的帮助。")
zh(628,"靴子只需外层皮革，需一种耐磨且能接受装饰的材质。一头年长的鳄龙能提供合适的材料，但要获取它，必须接近其他鳄龙。")
zh(629,"一块沉没的石板保存着黑暗之矛的圣物传说。金·维莱想要一块碎片供奉在奥格瑞玛，但敌对的鱼人占据着遗迹，那块无法移动的石碑仍屹立其中。")
zh(630,"普巴尔仍被穆克拉的力量锁链束缚在一座孤岛上，由他的野兽守护。她需要你面对她的俘虏，夺回镣铐钥匙，若有必要，还需寻找盟友对抗如此强大的敌人。")
zh(631,"拉斯洛克被派往东部桥梁侦察，爆炸后便再未归来。围城阻止了搜寻，拉格急需帮助找到他。")
zh(632,"拉斯洛克的尸体显示遭遇了黑铁伏击。他身旁发现的信纸必须随同悲惨消息一同呈上，让拉格能查看搜寻结果，了解失踪侦察兵的下落。")
zh(633,"信纸揭示了另一处炸药储备，原本是为桥梁准备的。摧毁它，旨在阻止黑铁切断北方主补给线，不让拉斯洛克的牺牲付诸东流。")
zh(634,"守卫们等待铁炉堡的援军，却知悉北方另有盟军营地。向尼艾丝求助，或许能获得士兵夺回丹莫德并保护桥梁。")
zh(635,"碎片传递出恳求之意，映出一座晶石山峰。追随那影像，或可寻得借石言事、求助于人者。")
zh(636,"书页记载密斯莱尔被囚于高原之下，与她牢笼相连的晶石。寻得它们，或可与保存其故事的大地公主沟通。")
zh(637,"破损的信封显出一封精心书写的信件，寄往萨拉·巴鲁。将它送往铁炉堡，让战火阻隔的讯息，终达其手。")
zh(638,"沃金欲取一柄传奇之剑，以抗祖尔格拉布的巨魔。森古从落锤镇指引搜寻，亦能解说如何参与此行。")
zh(639,"剑刃仍受分裂的符文守护，散于激流堡幸存者之间。首枚落入辛迪加之手，须取回方能开启托尔贝恩守卫的遗产。")
zh(640,"守卫者分走一枚符文，以保墓穴安危。集齐残片，托尔甘可重铸其形，继而突破魔法屏障，寻剑于后。")
zh(641,"符文重归完整，终能开启墓穴。携之至森古，交予统筹取剑之人，方能继续后续的寻剑之路。")
zh(642,"密斯莱尔称巨人囚禁她，借晶石传递讯息。她求取其狗头人盟友所持的光粒，以供另一簇晶石，或可助她脱困。")
zh(643,"森古追寻着阿拉希人类所持有的符文。其中一个正由瓦罗卡尔中尉携带，他是巡视此地的骑兵统领；截获他并取回物件，才能继续拼凑所需之物。")
zh(644,"开启索拉斯墓穴所需的最后一枚符印，握在他儿子加林手中。要取回它，就得踏进激流堡设防的腹地，直面王子的护卫，还要对付加林本人不俗的武艺。")
zh(645,"四枚符文已凝聚成一，森古相信它足以破除墓穴的结界。你必须进入激流堡教堂后的密室，从托尔贝恩的安息之处取回巨魔之刃。")
zh(646,"结界已破碎，巨魔之刃从石鞘中解放。将剑刃带回森古，完成通过符文拼凑出的武器回收任务。")
zh(647,"马克里尔承诺以一船月光酒偿还债务，却因沉睡而延误了时间。他需要在期限前完成快速递送，否则便要食言于布鲁米·比格尔。")
zh(648,"奥格索普需要他的机器人移至开阔地带，以便起飞。他远程修复其隐形系统的同时，你得护送这台机器前往热砂港，并沿途守护。")
zh(649,"德兰想要一款难以寻觅的饮品，留在一处被遗弃的部落据点。玛尔顿知晓能安排运输的联系人，包括他父亲打算留作收藏的额外酒瓶。")
zh(650,"玛尔顿指引你前往基沃拉丁·猎日者，一位酿酒专家，他能为父亲准备所需饮品。在辛特兰安排他的协助，别忘了他大概率会要求分一杯酒作为交易。")
zh(651,"密斯莱尔解释说，几块石头将她困在了地下。要解开最强的那块，需要其他石头的钥匙，但守护那些封印之地的守卫让这项任务更加复杂。")
zh(652,"密斯莱尔声称最后一道锁仍困着她于石环之中。她需要弗兹鲁克守护的秩序魔棒来开启这道锁，完成她承诺以非凡感激回报的释放。")
zh(653,"密斯莱尔说她能恢复力量，瞒过囚禁她的人；只是须先把下一场召唤备妥。硬骨懂得这套法门，可指引下一回与公主接触，向她求援。")
zh(654,"装置正在运作，但其能源只能维持数据一段时间。从塔纳利斯的野生动物身上采集可接受的样本，并在数据丢失前返回，避免另寻能源。")
zh(655,"戈尔摩仍被困在囚禁的回忆与毁灭之锤陨落的阴影中。与托尔甘交谈，或许能为这位前营地老兵寻得摆脱绝望的方法。")
zh(656,"密斯莱尔可能逐渐强大到足以挑战那些锁链她的人。为防止此事，召唤并击败她，再将她的枷锁绑定在碎片上，计划在她力量增强前恢复她的囚牢。")
zh(657,"文书指向农场里的致命实验。奎艾有伤在身，不能与基恩洛同行；基恩洛须在资料送往塔伦米尔前将它取回，身边得有人护卫。")
zh(658,"对农场的观察显示有一名信使可能携带重要笔记。截取这些文件，或能解释希尔斯布莱德的事件，而非让调查依赖于怀疑。")
zh(659,"一条狗举动反常，叫费恩疑心是亡灵作祟。两名同伴去查这个可能，却再没传回消息；他放心不下，托人去看看他们是否平安。")
zh(660,"基恩洛已准备进入农场，搜寻有关实验的情报。此行需护卫同行，好让她能展开调查并安全返回奎艾，不致孤身无援。")
zh(661,"回收的物件或许能助费恩·奥德利克厘清阿拉希的调查。奎艾与基恩洛将留守观察敌情，同时需一名信使将消息送往南海镇。")
zh(662,"两艘船在潮汐突变时沉没于礁石附近。离港前，同伴们希望找回航海图与日志，以免情报落入觊觎之人之手。")
zh(663,"探险队原计划短暂停留以搜寻宝物，却损失了两艘船。与奥布瑞恩交谈，或能了解那些因意外而滞留海湾的幸存者所面临的处境。")
zh(664,"斯迪加特幸免于难，却说娜迦杀死了其余幸存者。他的请求源自对沉船的回忆，以及对自身苟活的愧疚，渴望复仇。")
zh(665,"沉没的宝石难以单凭人力寻获。目镜或许能助一臂之力，但须先在洞穴充能。教授在此工作时，需得保护。")
zh(666,"宝物沉睡海底已久，宝石已被石质包裹。充能后的目镜可助定位，成为继续完成奥布瑞恩请求的工具。")
zh(667,"娜迦正筹备进攻，沙克斯深知它们会穷追不舍。他的船员亟需他的知识返航，因此须在岸上保护他，并用火炮击退敌人。")
zh(668,"宝石须交到指挥寻宝的船长手里。他的同伙也盼着尽快脱手——他们听说，攥着海盗的财物，对性命未必有好处。")
zh(669,"潮水与那些生物的盯守，让远征队脱不了身。卡拉·海角要听寻获宝物的消息，还要一件样本——海湾里的打捞尚未停手。")
zh(670,"舰队需补给后才能出航，但卡拉·海角急需秘密信件送达。一名信使可无需等待船只准备就绪，便与奥布里保持联络。")
zh(671,"托尔·甘察觉到恶魔召唤的痕迹，扰乱自身血脉。他需要检视活跃的符文项链，却畏惧回到那片魔力激化怒意之地。")
zh(672,"关于奥格瑞玛与萨尔的传说未能重燃戈尔摩的希望，托尔·甘想尝试萨满圣物，需迅猛龙之眼为这次不同尝试做准备。")
zh(673,"托尔·甘将恶魔召唤归咎于术士使用强力遗物，夺取此物并摧毁能量源，旨在阻止魔力进一步污染此地。")
zh(674,"符文项链已准备就绪，意图重燃戈尔摩战士的意志。将它交给老将，考验托尔·甘对迅猛龙之力能否缓解他绝望的信念。")
zh(675,"戈尔摩拒绝了项链，诉说着他未能与毁灭之锤并肩而亡的悲痛。托尔甘需要这段回应，以理解为何协助的尝试未被老兵接受。")
zh(676,"落锤镇急需援助对抗袭击者，但志愿者须先证明自己的准备。阿拉希的巨魔提供考验，方能加入保卫哨站与守卫者的战斗。")
zh(677,"杜拉姆法尔认定巨魔与食人魔正联手，要把他的族人逐出阿拉希。他头一仗便打向巨魔营地，要让落锤镇在这片土地上站稳脚跟。")
zh(678,"杜拉姆法尔提高了对巨魔进攻的难度。他们的战士与法师证明了更强的对手，为协助落锤镇防御的众人提供考验。")
zh(679,"袭击落锤镇的幕后主使藏身激流堡。杜拉姆法尔认为先前的战斗已为对抗这些将领与驱逐哨站的企图打开缺口。")
zh(680,"科林相信旧敌正为丈夫布下陷阱。她隐瞒他的行动，以避免鲁莽回应，并请求协助阻止巨魔在发动攻击前将其擒获。")
zh(681,"激流堡的守卫日渐疲弱，敌军却愈发强盛。辛迪加阻挠南海镇的援助，迫使尼艾丝队长寻求缓解关键补给路线的压力。")
zh(682,"辛迪加用从死士身上取下的徽章激励战士。尼艾丝希望夺回这些徽章，让激流堡的亡者不再被敌人当作战利品。")
zh(683,"悲伤阻挡了萨拉亲自向国王申诉的路。她的信件需由第三方转交麦格尼，方能让她的诉求被听见。")
zh(684,"玛雷兹辅佐辛迪加，以处理恶魔事务闻名。民兵悬赏这名危险术士，其技艺令任何试图寻她之人不得不格外谨慎。")
zh(685,"法库雷斯特统领阿拉希的辛迪加，其护卫已杀死了众多守卫者。民兵意图瓦解其领导层，以悬赏双人的方式回应暴力。")
zh(686,"麦格尼理解苏利的失去，希望他的记忆被铭记。为打造纪念碑的委托，必须送达负责准备此致敬意的大石匠。")
zh(687,"硬骨说一位旧友携走了召唤密斯莱尔所需的卷轴。在荒芜之地流传的谣言中寻找塞尔杜林，是获取这知识的下一步。")
zh(688,"密斯莱尔说，她须先花些时日养回力量，才能面对囚禁她的人。萨鲁克知道怎样将她召上地面，也能在她准备停当时，备好她要的这次会面。")
zh(689,"麦格尼委托打造的纪念碑需选用能持久铭记的石材。玛布勒斯坦请求使用奥特兰克花岗岩，以致敬苏利与他仍被家人铭记的失去。")
zh(690,"特拉内从激流堡逃走，留下重要物品在被围攻的城市内。马林已派代理人去取回，但需进一步协助，以弥补塔楼防御的漏洞。")
zh(691,"马林派学徒去收集药料，克里汀却不知上哪儿去找。有你搭手，便能寻齐巨魔身上的部件，回去交了他们主人的差事。")
zh(692,"迷失者塞尔杜林担忧召唤密斯莱尔可能带来灾难，但意识到或许已别无选择。暴怒的元素生物撕碎了卷轴，若能找回残片，便有机会重铸这魔法器具。")
zh(693,"斯奎尔图找到了特莱纳的魔杖，而食人魔已开始利用它的力量。若能夺回，便能阻止这件遗失之物落入尚未掌握其力量之人之手。")
zh(694,"食人魔包围了塔楼，阻碍了剩余物品的回收。要重启其防御，需一枚偷来的宝石，克里汀可将其附魔成钥匙，以更稳固的方式推进计划。")
zh(695,"这枚魔法宝石可在进入塔楼时激活防御。出发前，斯奎尔图必须将剩余的指引交予马林，说明仍需回收的物品。")
zh(696,"特莱纳的遗物仍存于被占塔楼的箱中。宝石可启动防御，但单靠它无法驱散食人魔——回收物品仍需持武器潜入。")
zh(697,"斯奎尔图送来一封信，告知马林他的探子即将归来。将信送往暴风城，便能通报任务进展，以及协助回收物品的支援。")
zh(698,"海滩据点急需另一批肉食，但守卫与厨师正忙于戒备与烹饪。若能取得合适的肉块，便能补足他们无法自行收集的储备。")
zh(699,"鱼人让斯通纳德的守卫难以喘息。托克·卡尔想要一些鳄龙爪，能打造趁手的武器，他并承诺以自己的爪子表达对你的谢意。")
zh(700,"纪念碑已完工，石匠期盼它能符合王室的要求。麦格尼需要这个消息，好得知他下令为苏利所立的贡品现状。")
zh(701,"托尔·甘希望再寻一物，将迅猛龙的狡黠传达给戈尔摩。他需要的兽心将延续尝试，向这位老战士展示部落重铸后的萨满之力。")
zh(702,"这颗晶球旨在将迅猛龙的魂魄传递给戈尔摩。托尔·甘期盼这股力量能唤醒他的意志，让他愿意倾听部落已历经的蜕变。")
zh(703,"里格弗兹拥有一切材料，唯独缺秃鹫的翅膀。获取它们便能再制一批，也或许能窥见他向饥肠辘辘的旅人炫耀的秘方。")
zh(704,"阿戈莫德最后的报告提及一些古旧陶瓮，可能激怒了地穴魔。铁环长者担忧重演与雕像的遭遇，必须研究这些器物以查证这可能。")
zh(705,"里格弗兹用闪光雷吓退掠食者，却缺蓝珍珠粉末。追寻这遥远的材料，是他维持防御、求存于荒芜之地险境的必要之举。")
zh(706,"西格鲁学会了一种以火焰附魔武器的技艺，并愿展示。这个过程需要一头黑幼龙的心脏鲜血，因此他需要从莱瑟罗峡谷取得样本。")
zh(707,"铁环长者需要协助处理另一处挖掘任务。信件未提细节，唯有前往他的营地，方能知晓勘察员需要什么帮助，以及如何协助。")
zh(708,"锈蚀的箱子上刻有铁炉堡攻城兵团的标记。将它带到大厅，便能呈上这件从秃鹫腹中寻回的珍物。")
zh(709,"迷失者塞尔杜林畏惧一个连他都不敢提及的威胁。他相信一块上古石板能提供对抗它的知识，因此请求从奥达曼地底的箱子中寻回它。")
zh(710,"鲁特维尔·沃拉图斯正研发束缚更强大元素生物的法术。石块碎片能让法术与机关先行测试，而仪器的潜能仍待探索。")
zh(711,"鲁特维尔下一轮试验要用更大的石块。更强的元素生物能供上这些石头；他则腾出手来，细看先前那批较小的样本。")
zh(712,"鲁特维尔需要将自己打造的枷锁与巨型石元素所佩戴的束缚护腕作比较。数件样本能让他的发明经受考验，也能避免助手常误放的材料。")
zh(713,"油能提升束缚的魔力容量，也能冷却机械。鲁特维尔需要它来控制即将召唤的元素生物，以免危及协助他工作的同伴。")
zh(714,"装置已近完工，唯独缺少一个微小机械零件。鲁特维尔需要发条式同步协调陀螺仪，才能完成仍在借助你所收集物资组装的仪器。")
zh(715,"卢森担心洛特维尔的实验可能需要治疗与隐匿药剂。他愿以自己的配方换取这些准备，只为增添一道防范他们可能召唤之物的保险。")
zh(716,"卢森想补偿你协助洛特维尔的付出，并用剩余的矿石打造魔法臂铠。他需要铁匠打造青铜底座，才能完成这份赠予。")
zh(717,"加瑞克认为布莱克拉什与赫玛图斯已无法再被稳妥囚禁，尤其在钥匙被盗之后。他提议用符文石开启封印，并铲除巨龙以防它们最终逃脱。")
zh(718,"撤退时的矿车与物资落在了食人魔手中。没有武器，队伍连食物都无法获取，必须夺回补给才能摆脱这困境。")
zh(719,"雷杜尔逃过摧毁他挖掘点的袭击，认为雇主已死。他想夺回物资，尤其是他的镐，从如今占据遗失挖掘点的黑铁手中。")
zh(720,"地图上的讯息显示锤趾被带往奥达曼。雷杜尔需要这讯号证明生存，以重新审视他对同伴命运的信念。")
zh(721,"雷杜尔担心锤趾被俘因他知晓泰坦挖掘的秘密。寻找他既是营救，也是阻止黑铁获取情报以强化石像鬼的手段。")
zh(722,"被盗的吊坠能指引持有者找到所寻卷轴。锤趾请求夺回，以免这知识助黑铁提升石像鬼的力量。")
zh(723,"铁趾格雷兹身受重伤，将护身符托付给能将它交给雷杜尔的人。他的同伴深知这项研究，能继续努力阻止奥达曼卷轴落入黑铁之手。")
zh(724,"雷杜尔认定卡尼克是解读护身符和铁趾消息的人选。研究者的合作，为决定如何守护奥达曼的秘密提供了可能。")
zh(725,"贝尔格拉姆迫切需要事件的详细报告，以决定官方回应。密信送达前，卡尼克将向铁趾格雷兹的灵体求取情报，对抗黑铁的行动。")
zh(726,"贝尔格拉姆觉得此事非同小可，准了以国王之名还击。卡尼克须即刻领命，对黑铁在荒芜之地的勾当迅速动手。")
zh(727,"石板未能完全平息塞尔杜林的忧虑。他昔日所属的组织手中或许还有一本书，而一枚印记能让他在假身份下寻得它。")
zh(728,"塞尔杜林寻找另一部典籍，以补充石板所知。幽暗城的守护者认出印记后，或许会交出典籍，让情报不暴露此行目的。")
zh(729,"挖掘现场突然爆发傀儡，逼得霍莉求助。雷姆塔维尔似乎对危险毫无察觉，必须前往现场查明他的状况。")
zh(730,"前往黑海岸的团队已沉默数周。他们的上司忧心忡忡，前往奥伯丁寻找线索，强调他们的考古发现对大局的意义。")
zh(731,"卡尔纳·雷塔维想要找到一块化石，向探险者协会展示他的成果。他在挖掘场搜寻样本时，因心不在焉而需要保护。")
zh(732,"克拉苏斯派加瑞克解决莱瑟罗峡谷的重要问题，但巨魔偷走了关键物品。找回大地印章，他才能继续一项尚未愿公开目的的任务。")
zh(733,"营地急需金属打造防御与物资。附近的巨魔似乎拥有大量废铁，提供了原料来源，但对定居点的状况却令人忧心。")
zh(734,"鲁特维尔·沃拉图斯仍在修理枷锁，需要特定的机械零件。他托你去卢希恩那取一个五号齿轮，好继续他的工作。")
zh(735,"葛利·硬骨手中有一份你寻找的摘要，愿用三件神器换取。交易需谨慎，他写下名字以防旁人听闻他的需求。")
zh(736,"贝尔·杜古尔将你寻找摘要的行动视为他教派新篇章的准备。他愿以副本交换神器，将名字记录在案以保交易隐秘。")
zh(737,"摘要已备好，将送往迷失者塞尔杜林，随行的还有对其知识的警告。谨慎携带，继续搜寻答案，避免危险文本落入敌手。")
zh(738,"阿蒙德已数周未报消息，其挖掘场的状况成谜。铁环长者需要找到他，以获取他监督南方荒芜之地工作的最新情报。")
zh(739,"血迹显示阿格蒙德是爬行着死去的，他身旁留着莫达洛克的名字。这最后的线索指向了杀害他的凶手——那些巨魔，并为铁环带来新的消息。")
zh(741,"这化石必须送到达纳苏斯的探险者协会。不愿将雷塔维留下，他的同伴必须托付他人将标本送往首席考古学家。")
zh(742,"部落在灰谷的据点正寻找愿意展示实力的冒险者。塞娜尼提出参与一场伟大的狩猎，作为他们在北方森林扩张势力的一部分。")
zh(743,"鲁尔提议迎战鹰身人，作为前往莫高雷之外冒险的准备。与他族的敌人战斗，将有助于衡量至今所培养的实力与技巧。")
zh(744,"伊恩正为兄长制作头饰，准备在酋长面前的仪式。皮革的加工让他无暇收集完成设计所需的羽毛。")
zh(745,"豺狼人狩猎毫无节制，也拒绝任何沟通。贝恩认为他们的存在正在伤害莫高雷，必须在威胁扩大之前加以挑战。")
zh(746,"贝恩视矮人的挖掘为对土地的亵渎。他希望毁掉他们的工具，作为对一场他视为破坏莫高雷的求知行为的回应。")
zh(747,"村庄需要肉类与羽毛，而首次狩猎提供了一个展示对部落效忠的机会。格鲁尔期待这场教训也能为纳拉其补给。")
zh(748,"地精污染了圣泉。穆尔需要从当地动物身上获取材料，制作一个图腾，以便在第一个受影响的水源处举行净化仪式。")
zh(749,"袭击者以为风险投资公司商队的补给已经毁尽。打捞者随后露面，事情恐怕并非如此；摩林要人翻查剩下的木箱，看看还有什么留存。")
zh(750,"格鲁尔强调狩猎维系着社区，而非仅仅为了猎物。需要狮皮来为孩童缝制衣物，修补村庄破旧的帐篷。")
zh(751,"木箱中包含矿物与文件，进一步佐证了风险湾公司采矿的疑点。摩林需要查看这些文件，而附近山丘上仍可见持续作业的痕迹。")
zh(752,"族长的母亲取水去了，比预期时间更久。她忙于部落事务，儿子需派人去井边查看她的下落。")
zh(753,"族长的母亲仍履行着职责，只是年岁已让她的步伐迟缓。她将水罐交予年轻的手，准备返回纳拉其。")
zh(754,"净化图腾已备好，用于冬季蹄井的净化。恢复水源需在仍有敌对地精守卫的水源处举行仪式。")
zh(755,"谦逊的服务态度与求知的意愿展现了可贵的品质。鹰风如今将你的训练引向大地母亲的仪式，从一项力量的试炼开始。")
zh(756,"下一次净化需新的图腾。穆尔需要平原掠食者的利爪，以备用于污染的雷角水井仪式之器。")
zh(757,"鬃背兽侵入部落领地，伏击猎人，夜袭偷窃。力量仪式要求直面这些敌人，以展现为纳拉其效劳的勇气。")
zh(758,"新图腾已备，雷角水井即将净化。穆尔将仪式本身托付予收集所需材料的冒险者，以备神圣之器。")
zh(759,"只剩一口污染的水井，但其净化仍需最终图腾。草原狼前锋的利齿，将提供这最后一次仪式所需之物。")
zh(760,"经先前净化，最终图腾已备。雷霆崖北方的水井仍需仪式，以对抗地精引入的毒物。")
zh(761,"哈肯视俯冲捕猎为机智与决心的展现。它们的羽毛将作为技艺的证明，为猎人与部族赢得荣耀。")
zh(762,"因弗努斯受拉格纳罗斯之命，搜寻奥达曼神器，此行动已造成重大伤亡。那些圣物若被反噬铁炉堡，大使必须被清除，并证明其败亡。")
zh(763,"大地母亲的仪式仍有后续考验。霍克温德雕刻的图腾将呈报你的进展，贝恩可指引你训练的下一阶段。")
zh(764,"文件揭示了风行公司正在莫高雷扩展采矿业务。摩林拒绝牛头人土地被掠夺，希望在附近的矿场挑战公司的运作。")
zh(765,"找回的文件揭露了驱逐牛头人的计划。摩林认定菲兹普罗克主管是主谋，想要阻止他，并检查他的剪贴板以获取更多情报。")
zh(766,"茂尔被马兹拉纳其咬伤，感染急需治疗。在他病情恶化前，需要从平原动物身上寻得难以寻觅的零件。")
zh(767,"下一项仪式教导土地作为供给者的神圣意义。村里的精神领袖扎尔曼·双月，将引领众人迈向仪式的幻象。")
zh(768,"维尔伦将兽皮制成衣物与铠甲，供应雷霆崖。他愿以打造物品交换皮革，将猎人的工作与他的工艺连结。")
zh(769,"维尔伦珍视科多兽的力量，深知如何处理其皮革。他将与提供材料的人分享制作袋子的技艺。")
zh(770,"鬼嚎的皮毛仍留着与燃烧军团战斗时的伤口。血蹄村中熟悉他的人，应知晓他的死讯。")
zh(771,"扎尔曼正准备在部族营火旁的水，以引发幻象。从地貌收集的材料，蕴含着仪式此阶段所需的魔力。")
zh(772,"仪式之水已备妥。在部族营火旁饮用，将引出启示，而追随其指引，便是圣途的下一步。")
zh(773,"饮下圣水，便可寻求先祖的祝福。智慧之礼引你前往赤色石，那里有灵体继续引领你走向接纳。")
zh(775,"仪式已毕，雷霆崖上下都记下了你的名号。下一场会面在城中最高处——那座最大台地的顶上，凯恩在那里等你，他是这座城的首领。")
zh(776,"已赢得的认可召唤着持续为民众效力。凯恩提议以追踪与猎杀技能，对抗莫高雷平原上那头强大的科多兽。")
zh(777,"卢希恩提供了卢特维尔所需的齿轮，同时决定暂避锋芒。交付零件将使锁链实验继续，但助手的谨慎表明他预料到演示中将有波折。")
zh(778,"卢特维尔已完成锁链，欲展示炼金术、工程学与魔法的结合。他的召唤需要你准备迎战元素生物，并回收此次实验所用的装备。")
zh(779,"大地封印有三个凹槽，用于安置符文石。安置它们是加瑞克计划的一部分，旨在开启布莱克拉什与赫玛图斯的囚牢，直面被囚巨龙的威胁。")
zh(780,"野猪人驯出的野猪正一步步踏进部族的猎场。格鲁尔要你截住它们——肉别糟蹋，剁了下锅炖汤，给族里的孩子添一顿荤腥。")
zh(781,"发现的地图揭示了纳拉其营地长期围攻的计划。这些关于食人魔战酋意图的情报必须传给鹰风，让他知晓这场威胁。")
zh(782,"部落欲铲除两位曾与死亡之翼结盟的旧友，以重振荣誉。受雇协助的佣兵盗走了监狱的钥匙；夺回大地印章是进攻巨龙的必经之路。")
zh(783,"北郡面临诸多威胁，而众多士兵正远赴他乡作战。守卫们正招募义勇军保卫此地，治安官玛克布莱德则在修道院统筹此事。")
zh(784,"库尔提拉斯军队已夺回一座要塞，再度威胁杜隆塔尔。格塔霍克视他们的存在为对先前与吉安娜协议的侵略延续。")
zh(785,"兽人与暗矛巨魔的盟约也意味着守护彼此家园。萨尔希望森金村免受即时威胁；协助侦察员拉尔·猎齿，让这份盟约化为实际防线。")
zh(786,"半人马正筹备多阶段攻势，针对兽人与巨魔。拉尔在突袭中发现了他们的文件，希望在入侵展开前将其焚毁。")
zh(787,"伊崔格在听到萨尔关于摆脱恶魔影响、由萨满祭司引导的愿景后，重返部落。高恩将提供你训练的下一步指示。")
zh(788,"高内克希望强化新兵，却不愿让他们经历不可能的考验。附近野猪比远方猎物更适合作为首次挑战。")
zh(789,"蝎子即便对经验丰富的战士也构成威胁。它们的尾部展现着战斗实力，也储存着能制成解药的毒液，这种解药随时可供山谷中受伤的招募者使用。")
zh(790,"哈纳祖亚与萨科斯激战时身受重伤，无法独自终结这场战斗，他请求他人击杀蝎子，以维护他视作荣誉的尊严。")
zh(791,"弗恩已无法战斗，却仍通过守望与制作支持他人。若提供人类与半人马常用的帆布，他便能制作一个袋子。")
zh(792,"祖雷萨发现山谷中滋生着腐败。火刃氏族的亲友团正从洞穴中现身，制造混乱，成为他们在教派现身前必须首先面对的威胁。")
zh(793,"高恩需要大地印章打开封印石，释放囚徒。此举将促成与布莱克拉什与赫玛图斯的对峙，但他警告两者皆为强敌。")
zh(794,"祖雷萨的占卜显示，火刃氏族的庇护所内藏着一枚强大的徽章。取走它意味着要面对其防御，甚至可能遭遇比已遇亲友团更强的代理人。")
zh(795,"大地封印有三处凹槽用于嵌入符文石。这种互动将依照高恩的计划，为对抗那些必须切断与部落旧有联系的巨龙开启牢狱。")
zh(804,"哈纳祖亚单凭重拾的勇气无法独自归来，他需要通知高内克自己的伤势与位置，以便从大兽穴寻求援助。")
zh(805,"火刃氏族盘踞山谷的事，得报到谷外去。加德林要听你亲眼所见，也要弄清森金村是否被同一股腐蚀缠上了。")
zh(806,"奥戈尼尔已锁定一名火刃氏族的术士及其追随者。他希望在这一混乱之源扎根之前将其制止，以免成为杜隆塔尔更大的威胁。")
zh(808,"扎拉赞恩将敏希娜的灵魂封入颅内。加德林目睹了这种梦中囚禁，需取回魔法法阵中的残骸，以求得弟弟的解脱。")
zh(809,"项圈印证了尼鲁的猜测，这个教派正借助恶魔之力。他的助手阿克·泽洛斯可指引寻找火刃氏族所崇敬的种子。")
zh(812,"林纳格正因蝎子毒液而衰弱，认为时间所剩无几。科尔·甘恩知晓解药，但必须有人找到他并带回救治之物。")
zh(813,"科尔·甘恩可为林纳格准备解药，但需要同种蝎子的毒液。中毒令时间所剩无几，几乎无暇他顾。")
zh(815,"托尔卡需要蛋类准备明日的餐食。岛上的生物誓死守护巢穴，使这项采集食材的任务充满危险。")
zh(816,"克鲁恩曾外出猎捕鳄鱼蜥，至今未归。他的母亲担心他的骄傲引他陷入险境，恳求找到他，或寻回他命运的证据。")
zh(817,"社区急需更多兽皮，用来制作毛毯、帐篷与铠甲。维尔林将捕猎岛上的虎视为应对现实需求的行动，而非单纯的娱乐。")
zh(818,"视力衰退让沃纳尔愈发依赖炼金术。他需要沿海生物的材料，而收集这些素材，便是协助他的机会。")
zh(819,"一块小木牌将空木桶与陈·风暴烈酒的名字相连。这刻字是唯一能指引找到熟悉酒桶与起源之人线索。")
zh(821,"德罗恩通过自己的导师了解陈的配方。酿造这强力酒液需从贫瘠之地的野生动物身上获取罕见材料，且须在品鉴前完成收集。")
zh(822,"德罗恩还掌握另一道从陈处学来的配方，愿为有兴趣的冒险者酿造。需用大型贫瘠之地生物的零件，方能制成这新酒。")
zh(823,"加德林断定火刃氏族的手能伸到整片土地。奥戈尼尔专管清剿这路腐蚀——山谷里查出什么，森金村又出了什么乱子，你都得一并告诉他。")
zh(824,"这颗复原的球体需要熟悉元素与远古传说之人。杰纽属于大地之环，或许能解读此异常物件的深意。")
zh(825,"敌军舰队的残骸中仍藏有侏儒的工具。加·托克希望取回这些物件，以更深入了解联盟科技，并为自己的族群所用。")
zh(826,"扎拉赞恩占着黑暗之矛昔日栖身的海岛，又遣手下四出掳掠，把更多巨魔拖去做奴。加德林要你与他当面一战，斩断他伸出的手。")
zh(827,"教徒行仪式时，颈上套着灼热项圈。玛高兹疑心这物件能勾连恶魔之力——只是手里没有实物，非得几副样本细细拆看，才敢断言它究竟作何用。")
zh(828,"玛高兹深知火刃氏族的腐化，已找到接近奥格瑞玛的教徒。向他请教，将有助于应对他们占据的山中据点。")
zh(829,"项圈超出了玛高兹的萨满知识。探寻其起源需尼尔鲁协助，但术士声称其神秘研究服务于对抗恶魔的事业，仍存疑虑。")
zh(830,"所获文件盖有上将普罗德摩尔的印鉴。其正式现身暗示内容或与负责剃刀岭及其防御的指挥官加兹托克息息相关。")
zh(831,"文件显示普罗德摩尔的计划超越了直属指挥官。随着更多敌人可能抵达，加兹托克需纳兹格雷尔前往奥格瑞玛查阅文件及其影响。")
zh(832,"吊坠传递着本应发送给加兹祖的讯息，提及尼尔鲁并警告有袭击。这种精神沟通使它成为值得深入调查的线索。")
zh(833,"野猪人正肆虐于牛头人英灵安息之地。诺拉·暴雨图腾已无法独自驱逐他们，亟需协助守护这片圣地免遭进一步亵渎。")
zh(834,"雷兹拉克的车队遭劫，使他无法在杜隆塔尔展开工作。最近的补给被渡鸦抢走，他必须先找回物资，才能继续前进。")
zh(835,"雷兹拉克再也无法容忍车队接连失窃。他希望攻击威胁商路的渡鸦巢穴，以提升日后穿越峡谷的运输安全。")
zh(836,"机器人必须先抵达开阔地带才能启动升空。奥格索普将远程协助其隐形系统，而你则要护送它前往海岸，途中确保这台受损机器的安全。")
zh(837,"野猪人仍据守坚固的营地，即便先前已发生战斗。加·托克认为这些据点持续威胁杜隆塔尔的安全，想要在西部荆棘之地挑战他们的存在。")
zh(838,"天灾军团把通灵学院当作巢穴，躲在门后试验邪法、积蓄力量，那扇门非有对路的钥匙开不得。迪瑟斯认得那地方，对怎么弄到钥匙也已有了主意——你得去问他。")
zh(840,"卡加尔需要在贫瘠之地招募新兵。一封招募信能让你通过边境哨站加入部落的服役行列。")
zh(841,"比格维兹又提供了一种新的能量来源，无论你为何需要更换，这次他要求更多的水囊作为报酬，让你得以重新展开实地工作。")
zh(842,"招募信已签署，必须送往十字路口。瑟格拉在那里监管新来者，并将决定他们如何为当地需求贡献力量。")
zh(843,"加恩认为挖掘工程正在摧毁养育他族的土地。外交手段无果后，他号召部落与矮人开战，并夺回由其首领保管的笔记。")
zh(844,"东部的平原陆行鸟正骚扰十字路口的粮食补给。瑟格拉将应对这股滋扰视为首次试炼，借此检验你的能力成长。")
zh(845,"瑟格拉认为兹赫瓦拉比平原陆行鸟更具挑战。这场新的试炼延续你的准备，为日后在贫瘠之地面对更危险的猎物做铺垫。")
zh(846,"文件揭露挖掘工程高度依赖机械与炸药。加恩想将这份知识转为武器，却仍需物资筹备反击行动。")
zh(847,"萨满之力引起了戈尔摩的兴趣，他暂时愿意听一听托尔甘的说辞。你须将他的回应带回说服者手中，让对话得以继续。")
zh(848,"绿洲之水改变它滋养的生命。赫布瑞姆采集附近蘑菇的孢子，其特殊性质对研究此地自然资源的药剂师大有裨益。")
zh(849,"飞行器支撑着挖掘工程，亦可成为武器。加恩视其为对部落的侮辱，执意用准备好的炸药摧毁它。")
zh(850,"新领袖正在整合半人马，使他们更具威胁。雷戈萨想阻止巴拉克，削弱这种协调，以保护部落在贫瘠之地的据点。")
zh(851,"维罗戈游荡在这一带，但他的追随者或许能将他引回营地。雷戈萨提议发起袭击，敲响警钟，逼出半人马指挥官。")
zh(852,"赫兹鲁尔以力量与智谋统御贫瘠之地的科卡尔。雷戈萨认为他的覆灭将撕裂部族，削弱其对部落据点的威胁。")
zh(853,"赫布瑞姆已将孢子提炼成需进一步处理的乳剂。扎玛须在雷霆崖尽快接收，否则其效力将随时间消退。")
zh(854,"与兽人比邻而居，眼光不能只停在莫高雷。下一程去十字路口找索克——那一带麻烦不断，正缺人手。")
zh(855,"科卡尔威胁着部落在贫瘠之地的存在。雷戈萨悬赏减少其兵力，要求臂铠作为在半人马领地作战的证据。")
zh(857,"费格雷渴望夺回一件已成执念的遗物。他声称塔文布莱德因嫉妒而取走，而将军则视其为诅咒，锁于城堡之中。")
zh(858,"维兹克兰克在没有启动密钥的情况下进入了切割机，他因自己的临时应变而陷入困境，必须在尝试暴露前取得主管的密钥。")
zh(860,"在贫瘠之地更凶猛的野兽中继续猎人训练。瑟格拉可在十字路口引导这门技艺，但抵达她处，亦需谨慎护航。")
zh(861,"梅洛·石蹄可指引任何追寻猎人之路之人。携来莫高雷狡诈掠食者的利爪，将证明开启这阶段学习所需的能力与决心。")
zh(862,"格拉布愿为远行者的饥肠辘辘熬一锅汤。巴尔莫丹鼠群众多，正是他所需之料，让这冒险者的旅途多些滋味。")
zh(863,"维兹克兰克已准备好带着偷来的切割机启程，尽管仍需时间熟悉操控。他需在逃亡途中得到保护，直至抵达棘齿城的斯布特瓦夫。")
zh(864,"吉罗姆·比格维兹已移除电源并保存了套件的数据。将密封的设备带给幽暗城的金格，让她接收在塔纳利斯完成的实地研究结果。")
zh(865,"麦伯克认为当地迅猛龙的角解释了它们不寻常的智慧。他想将它们酿成可售的饮品，需完整样本以实现这个构想。")
zh(866,"绿洲的水悄然改变着此地植物。麦伯克想用本地根须样本与他处草药对比，以判断这些差异是否能被加以利用。")
zh(867,"猫头鹰群长久以来劫掠商队。达索克·快刀研究过它们的等级制度，提议先削弱低阶成员，再直面指挥袭击的主谋。")
zh(868,"科兰研究那些看似异常聪明的昆虫类生物。它们的卵或许能提供关键信息，但从土堆中采集样本，可能惊动生物并招致袭击。")
zh(869,"迅猛龙在一次银币劫案中被抓获，那批银币本是守卫们的俸禄。加兹罗格希望阻止这些不寻常的盗贼再度袭击十字路口的补给。")
zh(870,"新出现的绿洲正让这片被远古灾难摧毁的土地重获生机。图加察觉到水下潜藏的力量，需要调查这股能量的源头。")
zh(871,"野猪人正袭击从杜隆塔尔运来的补给。当斥候寻找他们的首领时，索克需要对威胁这条通往十字路口之路的营地施加压力。")
zh(872,"斥候已探明，劫商队的头目就是克里尼格。索克要你截下他，顺手折了他手下几分气力，好让这条路断个干净。")
zh(873,"玛伦视依沙瓦克为值得猎取的猎物，因其力量与震慑人心的威势。这场狩猎提议将此海中之患视为一项挑战，以印证已受的训练。")
zh(874,"猎人的训练应能追踪猎物直至海中。玛伦深知海洋生物，亦可沿岸继续教导，而此海岸亦正面临人类势力的威胁。")
zh(875,"下一次攻势将针对鹰身人副官。达索克希望瓦解他们的指挥体系，并借他们的戒指辨识本地各群落的首领。")
zh(876,"塞瑞娜为复仇发动攻势，其妹妹的死令她怒火中烧。达索克希望除掉这位首领，以其失败为警告，阻止对商队的进一步袭击。")
zh(877,"陶加怀疑裂隙维系着绿洲的生命。他将用不育的种子做实验，检验裂隙的影响，并探究这种现象是否适用于其他水源。")
zh(878,"碎牙愿为部落效力，条件是削弱他部落的敌人。攻击敌对的精神领袖，是他让钢鬃凌驾于其他牛头人之上的野心。")
zh(879,"碎牙认出三名族人是袭击的幕后主使。他要他们命偿苦楚，声称此举将减轻部落所受的侵扰。")
zh(880,"研究结果暗示绿洲拥有非凡的力量。陶加需要从饮用绿洲水的生物身上取壳，以观察水对周围动物的影响。")
zh(881,"瑟格拉提议猎杀埃其亚基，此人以隐匿与迅捷闻名。这项挑战将让猎人直面一头牛头人传统中与死亡与怜悯皆有关的生物。")
zh(882,"伊沙姆哈尔以杀戮表达本性。下一次狩猎挑战，他要以最爱的猎物引出迅猛龙，并为它的到来做好准备。")
zh(883,"拉科塔·马尼的蹄印象征着巨兽的强大力量。将它带给陶拉祖营地的乔恩，是这场平原巨兽遭遇的实物证明。")
zh(884,"奥瓦坦卡的尾巴尖触碰时会迸出火花，保留着生物的异常特质。乔恩将在陶拉祖营地收到这个蜥蜴的标本，作为遭遇的证据。")
zh(885,"瓦希塔帕恩的羽毛触碰起来极为疼痛。将这份样本带到陶拉祖营地的乔恩处，能获得在与生物交战时得到的罕见残骸。")
zh(886,"德鲁伊们察觉贫瘠之地正涌动着一股奇异的力量。图加从十字路口展开调查，但可能需要协助，以弄清绿洲周边的异动。")
zh(887,"海盗们正袭击加兹鲁维的船只，抢夺他的货物。由于贸易舰队无法提供足够保护，他寻求协助，对抗位于棘齿城南方的海盗营地。")
zh(888,"被抢走的货物包括观测站所需的透镜与一箱靴子。加兹鲁维希望从海盗营地夺回这两件特定物品，尽管其他货物已遭损失。")
zh(889,"碎牙愿以速度祝福换取血岩碎片。收集这些碎片，便能借他所提的交易，召唤风之力。")
zh(890,"加兹鲁维疑心是海盗劫了那批迟迟不到的货，只是还没拿到实据。把他的账本与码头上的记录对一遍，便知货是早已入了仓，还是半路失了踪影。")
zh(891,"船舱的炮火又击沉了明亮日轮的一艘船。船长希望揪出责任人，与要塞正面交锋，以降低对贸易舰队的威胁。")
zh(892,"码头记录中未见任何解释失踪货物的异常。加兹鲁维需要答案与账本的归还，而海盗仍可能是货物失踪的可疑因素。")
zh(893,"食人魔虽无知名匠师，却仍锻造出更强大的武器。塔特纳克·钢炉希望研究这些范例，以掌握他们的技艺，并为部落所用。")
zh(894,"斯布特瓦夫想查看风险湾公司的实验装置。先前获得的说明书或许能说明如何断开它，但须先在研究地点取得控制权。")
zh(895,"加兹鲁维悬赏通缉长滩队长，指控其领导海盗船队。领取赏金需有确凿证据，证明这名通缉指挥官已被击溃。")
zh(896,"迪兹维格听说风险湾公司矿场发现了一颗非凡的绿宝石。他熟识潜在买家，并愿与能寻回宝石之人分润所得。")
zh(897,"这昆虫般的生物似乎超脱贫瘠之地的自然秩序。它的头颅可作为样本带给乔恩·星眼，证明这片土地上曾出现如此罕见的存在。")
zh(898,"基尔萨瑞斯·火枝幸免于沉船之灾，却因联盟敌对而被囚禁。他需庇护才能逃出牢笼，重返棘齿城。")
zh(899,"曼科里克对食人魔的仇恨仍未平息。他邀人共襄暴力，并要求带来獠牙作为证据，鲜少显露复仇之心已得满足。")
zh(900,"仪表显示装置仍在运作。在移除实验设备前，须先关闭阀门，以停止整个系统的运行。")
zh(901,"装置已经停下，面板却仍锁着。得取来技工的钥匙打开控制台，才能把里面的实验器械取出来。")
zh(902,"终端开启后，组件已被移除，设备已成功回收。现在需要将它送往棘齿城的斯布特瓦夫，完成从风险湾公司的设施中移除的步骤。")
zh(903,"瑟格拉提议直面能将猎人变为猎物的掠食者。它们的狡诈与凶猛，使这一阶段的考验在草原的高草间更为危险。")
zh(905,"狩猎如今需进入猎物的领地。瑟格拉希望在存活的生物面前，将击败的迅猛龙羽毛置于它们巢穴，以此展现勇气。")
zh(906,"碎牙希望告知索克其部落首领的遭遇。洛克的头骨证明了干预的存在，但他怀疑部落是否会承认自己曾协助的过往。")
zh(907,"乔恩以巨型雷霆蜥蜴为狩猎挑战。它们的体型使每一步都充满危险，需谨慎行事，既展技艺，又避免被踩踏。")
zh(908,"暮光之锤盘踞废墟，威胁操控元素。杰纽需要一份记录其活动的核心数据，以便大地之环研究应对之法。")
zh(909,"被击败的元素生物留下一个看似提供能量的球体。其腐臭的水与抗损特性，需杰纽的知识才能辨明此物的真面目。")
zh(910,"你的监护人梦寐以求乘风破浪，参与部落的壮举。孩子想前往棘齿城码头，亲眼看看船只，感受大海，承诺全程乖巧。")
zh(911,"你的监护人幻想着成为灰谷前线的拓荒者。孩子渴望前往莫沙兰城墙，那是通往那片土地的门户，见证部落的野心与纷争。")
zh(913,"下一课要求寻找并对抗一只凶猛的雷鹰。乔恩期望见到成功的狩猎证据，才认为这段教导即将结束。")
zh(914,"原本意图治愈贫瘠之地的德鲁伊，如今却试图强加他们的扭曲梦境。纳拉将四名领袖列为目标，需用宝石回应这场腐化。")
zh(915,"你的监护人热切地回忆起曾在赛场上品尝过的草莓冰淇淋。听说如今可能在镇上买到，孩子央求你外出时买来作为奖励。")
zh(916,"基尔沙兰怀疑世界之树已改变了当地的大型蜘蛛。研究它们的毒液，可与小型同类作比较，验证他对它们成长的假说。")
zh(917,"研究如今需要活体样本，但捕捉巨型蜘蛛太过危险。一枚未孵化的卵，可先安排拘禁，待生物破壳而出。")
zh(918,"元素生物日益增长的愤怒令德纳兰忧心，他怀疑土壤与此有关。他想用他们的种子做实验，看自己的植物培育法是否能有所帮助。")
zh(919,"德纳兰认为湖边出现的豆芽已无药可救。铲除它们，是为了防止新的威胁在周围土地上生根。")
zh(920,"特纳隆一直在寻找你，如今正等待在奥达希尔的最高处。你被指引前去见他，回应他的召唤，同时被提醒不要让他久等。")
zh(921,"特纳隆希望你的旅程伊始，便能学习近期的历史。收集月亮井的水，是理解自海加尔山之战后世界如何改变的一部分。")
zh(922,"雷利亚对德纳兰与林精的实验颇感兴趣。一粒种子标本将让他在达纳苏斯继续自己的研究，延续两位学者的合作。")
zh(923,"腐化仍在调查中，但部分林精已无药可救。雷利亚希望将这危险从湖边清除，并将覆盖最严重病例的生长物收集起来焚烧。")
zh(924,"恶魔之种将火刃氏族与军团的力量相连。阿克·泽洛斯准备了能干扰这种联系的石头，但它们的能量只能维持短暂时间。")
zh(925,"你的结界对凯恩心怀敬意，希望能像他一样成为部落的英雄。因太过胆怯而不敢亲自索要纪念品，孩子希望你能在雷霆崖的访问中，替他取得凯恩的蹄印。")
zh(926,"阿克·泽洛斯准备的石头能干扰恶魔之种与军团的连接。取得一块便能实现这次干预，但它的力量必须在失效前使用。")
zh(927,"黑藓的心脏仍在暗色油滑的藓层下跳动。这种异常状态或许值得展示给德纳兰，他的研究对象正是森林中那些奇异的植物状生命体。")
zh(928,"特纳隆正将收集的水送往科瑞萨斯，以便任务与指导得以继续。前往多兰纳尔的旅程需格外小心，因林中野兽近期变得危险。")
zh(929,"德鲁伊们必须用其他水源补给达纳苏斯的月亮井。科瑞萨斯将此收集与泰达希尔的历史渐进叙述结合，阐明这项工作的意义。")
zh(930,"一串硕大的果实垂挂在发光植物的叶片之下。它的奇特外观或许正是德纳兰在湖畔营地欲仔细观察的样本。")
zh(931,"植物的叶片在林间光线下泛着脉动般的微光。采集样本将让德纳兰更近距离地研究这种林木植被的异常特征。")
zh(932,"迈雷纳斯正在附近洞穴集结格雷尔战士，塔隆凯担忧他的计划。他想低调地阻止这个山羊人，因威胁太过接近家园。")
zh(933,"下一口月亮井，在那片熊怪拦路的地界上。取水时得提防袭击——近来熊怪愈发凶横，路上片刻松不得。")
zh(934,"科瑞萨斯话里透出，泰达希尔还压着一桩他没说明的祸事。课业未完，你仍要去神谕者树下那口最老、水脉最旺的井里取水。")
zh(935,"泰达希尔在阿莱克丝塔萨与诺兹多姆的祝福缺失下生长得并不完美。科瑞萨斯将收集的水源送往范达尔，同时期盼能寻得拯救树木的办法。")
zh(936,"塞纳里奥议会正招募有经验的冒险者参与一项重要研究。虽然信使不清楚具体细节，但哈穆尔领导着这项工作，他可在雷霆崖解释你如何协助。")
zh(937,"鹰身人包围了先知之树，已有一名信使丧生。艾里妮亚需削弱威胁，以保护林间空地，并恢复与达纳苏斯的通讯可能。")
zh(938,"一只灰毛猎豹重伤倒地，但警觉的眼神暗示她仍想前行。她需要护卫护送至先知之树旁的月亮井边，找到艾里妮亚。")
zh(939,"萨瓦里克的笛声令人不安，你细察其纹路便知。其他半人马或许掌握其秘密；搜集线索并咨询艾瑞丹，或可避免误判初始的危险直觉。")
zh(940,"鹰身人的压力稍减，森林重归平静。先知之树如今将讯息托付予能安全送达树灵导师之人。")
zh(941,"德纳兰已清理了树心的青苔，但腐化仍未消散。他培育的滋养土壤或许能成为治愈之法，如今需通过种植加以验证。")
zh(942,"这化石与弗拉冈特曾认为蕴含隐秘力量的那枚极为相似。将标本展示给他，或可为理解雷姆塔维尔的考古发现提供有用参照。")
zh(943,"弗拉冈特认定，一块失落的石板能道破化石之力的来由。你从迅猛龙手里夺回它，再把两件东西摆到一处，他此行中断的考证便能接着做下去。")
zh(944,"暮光之锤的教徒们聚集在主宰之剑处，那里曾有一尊他们崇拜的远古存在陨落。你的调查能帮助奥努洞悉他们的意图。")
zh(945,"瑟瑞露尼在探索时被教徒包围，只能躲藏。她需要帮助脱困，并通知妹妹她安然无恙。")
zh(947,"巴瑞萨斯需要菌类制作药剂，但长老们担心洞穴中潜伏着邪恶的存在。你的造访既能收集材料，也能调查那潜在的威胁。")
zh(948,"奥努迫切希望得知你在峭壁之泉周边的探索情况。你的观察或许能帮助黑海岸的长老们理解那里的异常现象。")
zh(949,"暮光之锤在主宰之剑处的踪迹仍是个谜。找到证据能让奥努有所依据地行动，而非盲目对抗教团。")
zh(950,"这本古籍令人心神恍惚，仿佛在眼前扭曲了插图。只来得及找回一页，但那些潦草的字迹或能助奥努一臂之力。")
zh(951,"一份寻回的羊皮纸上写着，那个教派或许要用古精灵的魔法唤回他们的主人。玛塞斯特拉的遗物，也许能让奥努看懂这套法门，进而破它。")
zh(952,"范达尔需要与奥努及黑海岸的长老保持联系。传递他的讯息，维系着远隔重洋的守护者与盟友之间的沟通。")
zh(953,"躁动之魂阻碍了蒂夏完成亚米萨兰的石板。那里的历史仍镌刻在废墟之中，而她需要有人继续她未能完成的研究。")
zh(954,"恶魔以巴莎兰的魔力为食，却避开一座蓝光闪烁的神龛。调查这座避难所，或许能揭开压制废墟中日益强盛的生物之力的真相。")
zh(955,"阿斯特利安仍被魔法封印囚禁于灵体形态。他相信附近生物耳环中或许残留着痕迹，能助他理解自己被囚禁的方式。")
zh(956,"阿斯特利安怀疑半人马拥有维系他囚禁状态的封印。找回它将是理解，甚至打破魔法牢笼的关键一步。")
zh(957,"上层精灵的封印困住了阿斯特利安。亚米萨兰古老的蓝焰，或许能摧毁维系他囚笼的魔法。")
zh(958,"上层精灵的灵体仍保存着古旧的魔法遗物。桑迪斯希望将它们移除并摧毁，直面废墟后方危险魔法的残余。")
zh(959,"一次卸货事故让马格利什偷走了珍贵的瓶子。码头工人追踪他的踪迹来到危险的洞穴，如今需要协助找回失窃的美酒。")
zh(960,"奥努的调查需要与主宰之剑保持联系。占卜之水能让他在收集异端教徒情报时维持沟通。")
zh(961,"异端教徒的意图尚未明朗。占卜之水能让他在调查期间持续与奥努联络，而不必中断证据搜寻。")
zh(962,"扎玛正为皇家炼金房协会研究一种稀有植物。她相信若能获得更大数量，便能发掘其潜力，尽管它只生长在一处危险洞窟深处。")
zh(963,"安雅仍是亚米萨兰的痛苦灵魂。塞雷尔莱恩请求你解除她的痛苦，那是他无法直面的折磨。")
zh(964,"通灵学院的钥匙需骸骨、坚钢与权印方能启动。迪瑟斯已从安多哈尔取得骸骨碎片，这是开启要塞的第一块材料。")
zh(965,"巴苏尔尚未从调查阿尔塔拉克斯的异常事件归来。查看他的下落，或许能揭开他保护奥伯丁时遭遇的变故。")
zh(966,"巴苏尔正盯着塔里的术士，却还没看透他们的意图。他需要更多文书，才能把这桩事查到底——塔内盘踞着格外凶悍的敌人，得绕开他们。")
zh(967,"异端教派的活动必须上报净化者德尔格伦。巴苏尔信任他的老师，这位老师正协助抵御恶魔与亡灵，而威胁仍在持续增长。")
zh(968,"这本破旧的书记录着祭祀与献祭之法。书页间刻着一个铁炉堡商铺的名字，暗示了它的来历，也指出了这本令人不安的书可能的买家。")
zh(969,"马乌瑞提供用具有强大反射性质的碎片制作幸运符。这些碎片可在南方峡谷找到，或由冰巨人携带，是准备承诺之物的必要材料。")
zh(970,"德尔格伦认为一颗宝石藏着教派力量的秘密。从追随者手中夺回它，便能研究出对抗巴尔图尔信件中所述威胁的可能对策。")
zh(971,"硬骨收集能开启大门、唤醒沉睡力量的远古知识。一本遗失在水下遗迹中的手稿符合他的兴趣，也促使他追寻那些被遗忘的秘密。")
zh(972,"伊斯伦提供水之灵契，让你能继续寻找银松森林中的腐化水池。她对你完成萨满训练的这一阶段充满信心。")
zh(973,"德尔格伦认识那个兽人术士，认为他已无法再被忽视。寻找他的典籍，便是决定对抗神龛黑暗存在的行动之一环。")
zh(974,"克拉兰克想探究温泉暖意的来源。他怀疑与附近的火山有关，便借你一支温度计，让你找出最热的点，为他的理论收集证据。")
zh(975,"马乌瑞正在为你制作幸运符，并解释携带它可让你在某些生物身上找到‘艾科’。她希望你能将这些物品带回，待收到护符后，她便能协助你使用。")
zh(976,"费罗必须运送情报与补给，却担心落入敌手。他需要一支护送队穿越森林，完成净化者德尔格伦的委托，同时不暴露货物行踪。")
zh(977,"乌米已备齐遮盖造物活动部件的材料，只缺那对角。她要本地雪人身上完整的大角，破损残缺的一概不收。")
zh(978,"艾瑞拉斯在辛特兰的枭兽羽毛里寻出了天生的法力。他想知道冬泉谷的生物是否也带着同样的力量，需拾来那边的落羽，比对两者。")
zh(979,"新羽展现的附魔与先前样本相同，但其来源仍成谜。兰莎尔拉正在观察枭兽栖息地，或有新发现助益调查。")
zh(980,"冬泉谷的温泉令人费解，附近并无火山。克拉兰克建议请教多诺瓦，她正驻守泉边，或许能指引探究其热源的线索。")
zh(981,"阿特里库斯的败亡与邪教的溃散必须禀报净化者德尔格伦。返回他处，既可向协调者传递消息，也能肯定调查期间的努力。")
zh(982,"鱼人劫持了两艘船只，船长死于沉船。找回他们的文件与遗物，能助幸存船员取回沉没海底的残余。")
zh(983,"传声盒通讯装置频频失灵。搜集零件可助发明者修复机器，维持黑海岸各处的联络。")
zh(984,"特伦希斯担忧腐蚀会危害更多民众，其影响尚不明朗。但调查熊怪营地或许能察觉威胁初现的端倪。")
zh(985,"特伦希斯视南方黑木营地为奥伯丁的严重威胁。既然你已展现追踪能力，便需直接削弱这股威胁。")
zh(986,"特伦希斯愿协助寻找沃科尔，并可准备斗篷以保障搜寻安全。他需特殊皮毛来抵御黑海岸生物的侵袭。")
zh(990,"莱恩在阿斯特兰纳等待援助，对抗灰谷的腐蚀。这段旅程延续了黑海岸的行动，需沿着南方道路前往她的森林聚落。")
zh(991,"特伦伊斯曾为一件可能减少熊怪袭击的物品寻找宝石，却未归返。莱恩需在他最后线索的地点寻找这位好友。")
zh(992,"游牧民占领了水井，使加基森陷入缺水困境。菲兹杜瑟提供测绘仪器取水池样本，评估其是否可作为替代水源。")
zh(993,"斗篷已备妥，但其保护仅能维持片刻。特伦希斯建议留待锐爪现身，他能指明沃科尔可能藏身的庇护所。")
zh(994,"沃科尔同意开辟一条通往道路的通道，让锐爪等候。你的协助支持了一次突围尝试，之后特伦希斯需知晓逃亡途中发生的一切。")
zh(995,"沃科尔同意悄悄离开洞穴。待逃出生天后，你须前往奥伯丁与特伦希斯会合；沃科尔打算另寻他路，指望能更快抵达。")
zh(996,"这株植物形似风花，但病态的外观暴露了腐化。它的浆果腐烂发黑，看似剧毒；若想恢复生机，而非任其果实腐坏，它亟需照料。")
zh(997,"一船稀有金属本应运往德纳兰，却迟到了。研究者在湖畔等待这批物资，继续他的泰达希尔植物研究与实验。")
zh(998,"这株风花已显病态，浆果腐烂发黑，毒意昭然。它的状况亟需干预，方能恢复生机，而非让腐坏的果实继续蔓延。")
zh(999,"纳拉雷克斯的梦境再度催生爬行动物，威胁将他永远困在梦魇之中。唤醒仪式的第一步，是击败他的腐化仆从，阻止干预。")
zh(1000,"塞纳里奥议会需要志愿者探索塔纳利斯西部的危险地域。哈穆尔可向愿意行动的人解释任务，揭开一段鲜为人知的卡利姆多边疆秘史。")
zh(1001,"蛇颈龙的眼球是另一台破碎音箱的零件。收集它们，能维持发明家奇特通讯网络的运转。")
zh(1002,"另一台音箱需要修复，这次要用獠牙。你继续修复发明家的装置，尽管指令已越来越令人困惑。")
zh(1003,"下一个修理目标位于奥伯丁以南的隐秘信号箱，收集其零件继续完善这个日益混乱的通讯网络。")
zh(1004,"塞纳里奥议会需要志愿者探索塔纳利斯以西的危险土地。哈穆尔会向愿意行动的人解释任务，揭开一段鲜为人知的卡利姆多边疆秘辛。")
zh(1007,"一条娜迦伏击迫使旅行者弃船逃离佐拉姆沉没遗迹，途中遗失的古代雕像，正是这场危险沿海行动的唯一价值。")
zh(1008,"佐拉姆自地陷裂口后便沉入海底，但娜迦已重返其海岸。它们的意图不明，夜精灵决心将这些入侵者驱逐回深海。")
zh(1009,"古代雕像的密钥是一枚曾属于佐拉姆统治者的戒指，娜迦找到了它，从卢泽尔取回宝石才能继续调查。")
zh(1010,"孩童的病痛或许不止于身躯，更会侵扰灵体。巴斯兰鬃毛以治疗灵体疾患闻名，昔日生长的古老遗迹或许能带来慰藉。")
zh(1011,"亡灵在遗迹中的活动令夜精灵忧心，怀疑其意图是散播瘟疫。从他们营地取来一瓶器物，可先检验这威胁的真伪。")
zh(1012,"凯尼斯目睹了德鲁伊被亡灵杀害、魂魄分离的幻象，他请求追查昔日领袖，以安抚这些受苦的亡灵。")
zh(1013,"乌尔之书记录着其他世界的研究成果，被某些亡灵所珍视。书的预定接收者希望将其纳入自己的收藏，因此请求你将它从城堡中寻回。")
zh(1014,"亡灵视阿鲁高为控制银松森林这一战略要塞的障碍。你将被派往他的城堡与其交锋，而他们的指挥官则在努力清除困扰森林的魔法。")
zh(1015,"塞纳里奥议会正寻敢往塔纳利斯以西险地的冒险者。愿代议会探查卡利姆多边界的，可去达纳苏斯，范达尔会当面交代这趟差事。")
zh(1016,"若能提供一种成分聚焦魔法，卷轴便能识别元素生物的创造者。他们完好的护腕提供了占卜所需的药剂，并指引调查的下一步行动。")
zh(1017,"如此多元素生物的腐化，显然指向了萨瑞鲁斯。你必须深入敌境寻找他，直面这针对哨兵的挑衅，同时留意部落军队可能的监视。")
zh(1018,"塞纳里奥议会需要志愿者探索塔纳利斯西部的危险土地。哈穆尔可以向愿意代表议会行动的人解释任务，开启对一个鲜为人知的卡利姆多边疆的调查。")
zh(1019,"塞纳里奥议会正寻敢往塔纳利斯以西险地的冒险者。愿代议会探查卡利姆多边界的，可去达纳苏斯，范达尔会当面交代这趟差事。")
zh(1020,"奥雷迪尔准备了一种他相信可能帮助病童的药剂。你的旅程将带这种药前往阿斯特兰纳，让病童家人获得奥雷迪尔一直努力的治疗。")
zh(1021,"伊莉亚娜的姐妹前往寻找塞纳留斯的树枝，已失踪两日。她的担忧指向安妮莉亚，正是她率队深入半人马占据的遗迹。")
zh(1022,"边境神龛被狼人占据，其来历尚不清楚。神龛中保存的典籍或许能解释他们的到来，而守卫者正努力阻止费伍德的邪能渗透灰谷。")
zh(1023,"特洛尼斯的遗物保存着他的笔记，但他寻找的宝石仍下落不明。若从鱼人处寻回，便能让他的未竟之业继续延续。")
zh(1024,"特洛尼斯的笔记指向一根古杖的残片。一位树人知晓更多，而你需保管宝石，好助她重铸这件遗物。")
zh(1025,"熊怪正袭击灰谷东侧道路上的旅人。协助哨兵对抗他们的营地，既是回应暴力，也是守护无辜者免受侵害。")
zh(1026,"古杖的最后残片仍封存在锁住的箱子中。钥匙掌握在如今已腐化的树人手中，再度面对森林的衰败，是必然的遭遇。")
zh(1027,"德鲁伊们曾保管古杖的最后一块，却已遭杀害。搜寻他们的庇护所，或许能借树人的智慧，重铸这件遗物。")
zh(1028,"古杖已重铸完成，却仍需唤醒其力量。一座隐秘的山中神龛可助其复苏，你的追寻也将迈向完成这过程的最终之地。")
zh(1029,"莱恩要知道那根杖是否已经修好。回到她身边，木杖的重建便与特罗尼丝当初的追查接上了头，你也能问明这件寻回之物接下来该怎么用。")
zh(1030,"权杖似乎能改变使用者，但莱恩并不清楚具体形态。这种可能性或许能与未受腐蚀的熊怪建立联系，继续特罗尼思未竟的调查。")
zh(1031,"安妮莉亚设法辨认出持枝的萨提尔，临终前仍惦记着将它归还树灵。归还枝条满足她最后心愿，也延续了同伴们对抗遗迹住民的使命。")
zh(1032,"安妮莉亚的离去让伊莉亚娜转向复仇寻求慰藉，回忆起他们在林中嬉戏的时光。杀死负责的萨提尔并带回他们的鹿角，将证明有人回应了这份失去。")
zh(1033,"第一剂药似乎只延缓了蕾拉的病势。她父亲需要更强效的药剂，期盼奥雷迪尔描述的石头能净化仍折磨着孩子的腐败。")
zh(1034,"蕾拉的噩梦已减轻，但高烧依旧。奥雷迪尔提及遗迹中的尘土或许能缓解病状，她父亲急需它继续改善女儿的状况。")
zh(1035,"高烧已退，但蕾拉仍虚弱不堪。她父亲相信月石能恢复她的体力；这些石头如今被一位占据旧集会地的先知所囤积。")
zh(1036,"你对藏宝海湾的敌意已引起血帆的注意。菲尔拉伦正寻找有能力的冒险者执行一项特殊任务，并邀请你登船会面，了解任务详情。")
zh(1037,"维琳德·星歌在对抗恶魔的斗争逐渐失利时神秘消失。她的继任者缺乏完整线索，建议向哨兵们寻求协助，继续追查失踪的女牧师。")
zh(1038,"哨兵们保管着维琳德的遗物，坚信她终将归来。她的日记记载了职责与行动，也为调查提供了方向，同时肯定了同伴们对她的信任。")
zh(1039,"棘齿城的港口或许留有维琳德前往另一大陆的记录。向船坞主咨询，能延续线索，但通往港口的路需穿越部落战士盘踞的疆域。")
zh(1040,"记录显示维琳德预订了前往藏宝海湾的船票。她对陆路旅行的疑问，指向一位商队向导，或许能继续追踪她的足迹。")
zh(1041,"商队向导记得维琳德在分别时正朝夜色镇方向前行。镇上的记录或许能提供新线索，使搜寻继续沿着危险的丛林小径展开。")
zh(1042,"夜色镇的记录未提及维琳德，但狼人族是熟悉的麻烦。一家专猎怪物的家族或许能提供有用信息，让调查沿着另一条线索继续。")
zh(1043,"狼人族最早出现在他们如今占据的矿坑。调查此处或许能揭开他们如何抵达的谜团，而当地猎人也欢迎任何协助，对抗盘踞森林的怪物。")
zh(1044,"矿坑的发现解释了部分渗入森林的邪恶。当地猎人仍打算继续对抗，而你则需将这些发现带给需要真相的其他人。")
zh(1045,"熊怪明白，腐蚀并不能为族人的一切行径开脱。兰恩的威胁远超这种影响，阻止他也是为了保护夜精灵的子嗣。")
zh(1046,"胜利的消息必须传回那些派遣你调查的人。带回战利品作为证据，既是对自身族人的交代，也标志着与委托你的熊怪的会议落幕。")
zh(1047,"塞纳里奥议会寻找愿意探索塔纳利斯西边危险地带的冒险者。范达尔会在达纳苏斯向准备代表议会调查卡利姆多边界的勇士们解释任务。")
zh(1048,"当希尔瓦娜斯应对巫妖王的进攻时，瓦里玛萨斯希望尽快解决附近的血色威胁。他派遣你前往修道院，铲除其调查员与高层，削弱盘踞提瑞斯法的敌人。")
zh(1049,"对与被遗忘者结盟的疑虑促成了对更多知识的追寻。尽管血色狂热者行事荒谬，但其修道院中保存的研究或许能为质疑盟约的人提供参考。")
zh(1050,"理解过往或许能为未知的未来做准备。据说一本关于泰坦的书仍存于旧提瑞斯法修道院的图书馆，提供研究被遗忘历史的机会。")
zh(1051,"沃瑞尔在数周酷刑后濒临死亡，渴望向韦沙斯复仇。他的折磨者将偷来的婚戒给了南希，找回它便是对沃瑞尔要求归还给妻子莫尼卡的承诺。")
zh(1052,"你对凄凉之地亡灵的打击赢得了一封血色推荐信。信件指引你前往南海镇的莱雷恩，继续一场将洛丹伦视为祸害真正中心的行动。")
zh(1053,"一位前圣骑士发现修道院曾将无辜者当作祸害鼠的受害者加以折磨。如今他对光的忠诚驱使他摧毁曾引以为荣的狂热政权。")
zh(1054,"哨兵们担忧一支熊怪部落正逐渐壮大，可能袭击阿斯特兰纳。正面迎战其军队与酋长，旨在削弱这股威胁，以免它们获得足够信心直接攻击聚落。")
zh(1055,"木杖已修复完整，必须向曾协助重建它的树灵报告。回到她身边，让这份工作的成果被真正理解其价值与力量的人所知晓。")
zh(1056,"森林灵体称颂你的勇气与远行的决心。穿越险峻山岭的危险旅程将引你至石爪峰的守护者奥巴格姆，他要求你听从他的吩咐。")
zh(1057,"焚毁的山谷亟需重生，但渡鸦族阻挠着试图修复的人。驱散它们，为被工业贪婪与机械破坏摧毁的山丘带来治愈的可能。")
zh(1058,"金兹尔想酿造森林魔法用于对付他的精灵俘虏。他索取动植物成分的请求，将你卷入一场针对笼中生灵的实验。")
zh(1059,"渡鸦族已被制服，但山谷仍需援助以防它们重整旗鼓。一位能召唤强大森林灵体的德鲁伊，若得知这需求，或可支持其复苏。")
zh(1060,"塞瑞娜·血羽的死讯，得送到金兹尔手上——那位巫医住在鹰身人来处的山里。替友人递一封信，便要走进那片凶险的邻地。")
zh(1061,"地精的砍伐与焚烧激怒了石爪峰的灵体。希雷斯的报告指出大规模的森林砍伐，她需要那些愿意回应大地哀鸣、支持她工作的同伴协助。")
zh(1062,"风险投资公司正在摧毁石爪峰的森林，令灵体痛苦不堪。部落打算阻止这种掠夺，将直接面对地精及其帮手。")
zh(1063,"石爪峰的灵体危机亟需牛头人长老的智慧。玛加萨或许能召集援助，你必须将这片土地的危险带往雷霆崖告知她。")
zh(1064,"玛加萨认为石爪峰唯有去除病源方能痊愈。药剂师扎玛的专业知识或许能助一臂之力，而合作更可能加深牛头人与亡灵盟友间的信任。")
zh(1065,"扎玛寻求一种不流血的方式铲除风险投资公司。一封阐明她需求的信件必须送往洛丹伦海域彼岸的塔伦米尔，交给她的同僚药剂师林度恩。")
zh(1066,"一名药剂师想借毒素使风险投资公司的工人变得温顺。制备此毒需用无辜者的鲜血，由辛迪加暗影法师为他们自己的邪恶目的在城堡中收集。")
zh(1067,"毒素已备妥，但扎玛必须设计一种投递方式，方能发挥其效用。将毒素送往雷霆崖，是针对风险投资公司的计划前的关键一步。")
zh(1068,"灵体的低语让希雷斯目睹两台机器以惊人的速度砍伐树木。她希望阻止这些机器，回应石爪峰的苦难，并终结她所见的毁灭景象。")
zh(1069,"蜘蛛蛋煎蛋的风潮让藏宝海湾商机四起。石爪峰的深苔蜘蛛或许能为当地厨房提供所需原料，它们的巢穴因此成为一笔潜在财富。")
zh(1070,"凯拉奉命调查石爪峰的浩劫，却迟迟未传回消息。她的朋友忧心忡忡，更察觉到同行的侏儒法师现身，预示着更大的危机。")
zh(1071,"加克希姆想证明魔法与科技能拯救森林，却受地精势力阻挠。对抗他们，将为他争取宝贵时间，以完成所需发明。")
zh(1072,"加克希姆的新装置需要一种独家炸药，而洛玛克正是制造者。寻找洛玛克不仅可获取关键材料，更能协助他规划机器布局。")
zh(1073,"洛玛克同意准备炸药，却已用尽存货。带来正确的药剂不仅能补足原料，更可展现他要求的炼金术造诣，方能获得他的成果。")
zh(1074,"洛玛克交出所需炸药，并警告其危险性。你必须将此物送至加克希姆手中，继续这项可能致命的工程。")
zh(1075,"加克希姆打算远程引爆炸药，让你能及时撤离。装置需要马伦的法术，因此你必须前往这位法师，完成计划的最后一步。")
zh(1076,"马伦认为沟通法术能触发加克希姆的装置。将法术刻录于卷轴，需元素生物的残骸，而你必须在收集其他材料的同时获取它。")
zh(1077,"科林·马伦已备好魔法材料，交予加克希姆·尘链。将它送回，标志着他们合作的这一阶段完成，也让地精得以继续他请求协助的实验。")
zh(1078,"某些石化蜥蜴鳞片是科林·马伦法术的材料。他想要从被毁的山谷取来新鲜样本，却不知那些生物是否在毁灭之后仍存于其中。")
zh(1079,"炸药已备妥，但行动的目的是获取工程图纸。借着分散敌人注意力，可顺利接近伐木场，成败则以找回的文件为准，而非破坏程度。")
zh(1080,"第二趟行动，仍要借一场爆炸引开耳目，好偷走公司的往来信件。加克希姆只咬定一句：带着信活着回来——冒这番险，图的就是这些文书。")
zh(1081,"你的协助或许能增强石爪峰盟友的行动力。你被送往泰兰德那里，好让她认出你参与了针对那些森林中暴行的行动。")
zh(1082,"凯拉需要哨兵们知道她与加克希姆还活着。将消息带到阿斯特兰纳，能让他们的指挥层了解对抗公司的行动，以及修复土地的努力。")
zh(1083,"山谷的燃烧释放出仍被怒火吞噬的火灵与石灵。削弱它们的存在，是为了让这片土地有机会从工业破坏中恢复过来。")
zh(1084,"山谷昔日的守护者也已堕落，加克希姆疑心地精的兵器。从受伤的树人身上取回弹片，他便能先查这条线，再论他们变成这般模样的根由。")
zh(1085,"凯拉与加克希姆联手对抗一场浩劫。与这个精灵交谈，你便能加入他们的行动，而眼下尚无好消息可回报守望的哨兵们。")
zh(1086,"毒素必须达到公司运输线路的关键节点。寻找可能的机场，能通过他们的运作网络散布毒素，不过扎玛并不确定该设施是否存在。")
zh(1087,"布莱林憎恨德鲁伊，认为他们的影响束缚了她想要施展的魔法。她寻求对抗塞纳留斯盟友的帮助，以完成主子交代的任务，再返回加德纳尔。")
zh(1088,"布莱林通过预知找到了被移走的奥达努斯。她要求取下他的头颅，以一份强大礼物换取攻击森林之神之子的行动。")
zh(1089,"德鲁伊通过联结的密钥与储藏点守护着强大物品。从其中一个身上提取的信息，能入侵那些储藏点，抵达他们隐藏的宝藏。")
zh(1090,"前下属仍留在矿中调查格雷苏。他能获取所需矿石的样本，但需在采集时避开巡逻队的搜查。")
zh(1091,"找回的书信对凯拉与哨兵们至关重要。送交它们，既报告了行动结果，也提供了证明你与加克希姆并肩作战意义的文件。")
zh(1092,"矿石样本必须尽快送到齐兹。他的联系人担心事态公开后会遭报复，计划另寻逃路，只留你携带矿中搜集的物证。")
zh(1093,"齐兹需要一台巨型伐木机的设计图，供他新雇主使用。然而他与格雷苏的敌对关系让他无法靠近现场，因此必须找人代为窃取。")
zh(1094,"信封里是齐兹离开公司时带出的图纸与机密文书。送到棘齿城，东西便交到他新东家手里，追查那套机械的线也接着往下走。")
zh(1095,"格雷苏的雇佣引发了地精领袖的不满。里德尔沃克斯希望问题得到解决，将这些指示交给齐兹，或许能将商业纠纷转化为新员工的考验。")
zh(1096,"格雷苏身处险境，已将身体改造成机械装置。齐兹无法独自面对他，便出价招募能突破现场防御的人。")
zh(1097,"格瑞曼德·艾尔默需要帮忙把包裹送往北方。与他会面不仅协助了运输，也维系了人族与矮人盟友的实际联系。")
zh(1098,"两名追踪者尚未从城堡侦察归来便遭遇突袭。寻找并协助他们，或许能获取被亡灵所依赖的进攻情报。")
zh(1099,"竞速者之间的竞争也催生了赌注。一张支持地精的门票，让你的投注与他们获胜时的奖赏挂钩，是这场竞速恩怨中的一小部分。")
zh(1100,"亨里格·独眉的斑驳日记摊开在你面前。翻阅它的页面，或许能从主人留下的文字中窥见真相。")
zh(1101,"赫尔拉斯与独眉的勇气不能在卡尔加未被遏制时浪费。无暇求助达纳苏斯，需集结能踏入剃刀沼泽、直面老妇的同伴。")
zh(1102,"牛头人团结未能抹去对失落祖地的怨恨。卡尔加正在剃刀沼泽集结军队，而她的心脏正被一个铭记被夺之痛的人视为复仇的凭证。")
zh(1103,"提夫能助你再度见到纯净的水灵。他需伊斯伦的萨帕塔证明你的准备，也将延迟自己的献礼，只为促成另一次会面。")
zh(1104,"发明家寻找强力燃料为他的火箭车供能。蝎子的咸味毒液或许能完成实验性混合物，因此他需要样本，才能继续研发车辆的配方。")
zh(1105,"实验性燃料或会腐蚀火箭车的油箱。为防此害，其建造者欲用龟壳打造加固容器，并需能安全容纳新混合物的材料。")
zh(1106,"新引擎的活塞在重压下持续失灵。马特克对金属的了解或可提供解法，一封书信将你送往遥远荒芜之地的营地求援。")
zh(1107,"速度正因摩擦威胁撕裂车辆，而荒漠的盐分亦腐蚀其部件。需盐鳞鱼人的鳍制成坚韧复合涂层，以保护其活动机件。")
zh(1108,"荒芜之地的铟据说耐热耐压，但马特克需验证此说。由洞穴人携带的金属碎屑将提供样本，以判断其在费索的车中是否实用。")
zh(1109,"皇家炼金房正筹备一项雄心勃勃的炼金实验，需要一种罕见的物质。剃刀沼泽的蝙蝠会产出所需的粪便，尽管采集过程令人不快。")
zh(1110,"赛车事故让零件散落于闪光平原各处。侏儒与地精仍能将它们用于车辆，使残骸中诞生出新的交易机会。")
zh(1111,"侏儒的零件订单已在棘齿城积压一周。你的联系人无法取回，只能将订单送往码头。")
zh(1112,"克拉维尔的包裹已备好，即将从码头启程。交付同时也附带警告：若他不结清欠款，这供应商便不会再为他安排任何特殊订单。")
zh(1113,"实验旨在观察对立物质在毒剂作用下的反应。血色狂热者的心脏将提供关键成分，延续这项令人不安的炼金混合物。")
zh(1114,"菲兹尔苦等多时的零件被克拉维尔移除了部分。在中间人坚持下，将剩余部分送达，而他那小小的挪用则被要求保持沉默。")
zh(1115,"纳兹的过往或许藏着宝贵秘密，毕竟那个地精飞行员似乎改了名字。克拉兹克在藏宝海湾听闻风声，或许能将好奇转化为利益。")
zh(1116,"关于纳兹的消息需付出代价。克拉兹克查阅来源时，想要从悲伤沼泽的龙幼崽处获取梦境之尘，以补足他的鼻烟袋。")
zh(1117,"克拉兹克靠恩惠、美酒与推理，获取了关于纳兹的不利情报。他觉察此事太过危险，便将一封书信交予你，并坚持信源必须保密。")
zh(1118,"克拉维尔对你的能力与谨慎深信不疑，愿意将一项可能获利的计划交予你。第一步是将信件送往藏宝海湾的克兰克，并协助他完成计划所需。")
zh(1119,"克兰克将赞吉尔的药剂与黑啤酒混合，酿出一种威力惊人的饮品。他希望克拉维尔尽快试饮，因药剂对酵母的影响，使得饮品难以久存。")
zh(1120,"克拉维尔希望他的烈酒能被地精掘进队测试。尽快将它带给他们的老板，否则准备过程终将因未及时使用而失效。")
zh(1121,"克拉维尔要把那桶烈性黑啤拿到地精掘进队身上试。趁早送到他们头目手里——这酒再搁下去，迟早变味。")
zh(1122,"克拉维尔认为测试成功，并已下注，期待队伍的醉酒状态已影响他们的车况。克兰克需要一份报告，好决定是否未来赛事中继续使用这种啤酒。")
zh(1123,"拉比恩需要协助探索西部荒野，但达纳苏斯与塞纳里奥议会之间的紧张关系阻碍合作。前往月光林地，尝试超越种族差异，倾听议会成员的声音。")
zh(1124,"一场远古战争中被击败的邪恶，可能已在希利苏斯苏醒。拉比恩派你携信前往莱耶，他的工作正能调查议会的忧虑。")
zh(1125,"南风裂谷曾是暗夜精灵的据点，后被异种蝎占据。那些陨落的德鲁伊与哨兵在痛苦中游荡，莱耶希望探索此地，助他们灵魂解脱。")
zh(1126,"莱耶认为异种蝎会对环境变化产生反应，因此将调查重点放在南风裂谷被感染的塔楼。他希望扰动虫巢的活动，并带回任何有用的观察记录或物品。")
zh(1127,"克兰克愿用结合酒精与赞吉尔混合物的配方，酿造更多黑啤。他需要另一种原料以重复制作，毕竟这可能对赛马队伍有所用处。")
zh(1130,"梅洛听闻了你的事迹，并准备了一条道路。前往雷霆崖寻他，便可得知他为愿意追随指引之人准备的下一步。")
zh(1131,"钢齿土狼聚集鬣狗，向更温顺的生物散播恐惧。梅洛认为这场狩猎是对大地母亲祝福之外的生物的回应，而非单纯为了食物或荣誉。")
zh(1132,"一次海上旅程可能为你打开卡利姆多的新机遇。菲欧拉在塞拉摩迎接抵达者，寻她便可得知等待着愿渡海而来的冒险者的任务。")
zh(1133,"有线报称部落刺客在秘密行动中使用了飞翼毒。此请求旨在若情报属实，便切断这种供应，以维系仍脆弱的阵营和平。")
zh(1134,"线人称部落刺客在秘密行动中使用飞翼毒。此请求旨在若情报属实，便切断这种供应，以维系仍脆弱的阵营和平。")
zh(1135,"飞龙毒液的价值可能超过飞龙本身。一位对千针石林生物感兴趣的买家，提供猎捕任务以获取这种特别强烈且商业价值极高的毒液。")
zh(1136,"你的下个目标是奥特兰克，寻找霜喉雪人——一头能融入雪地的雪人。你的导师已为你准备了引诱这头隐匿猎物的方法，以检验你的狩猎能力。")
zh(1137,"测试证明了铟金属对高温的耐受力，但费索仍需要真正的矿石来打造他的活塞。将你的发现带给他，并说明这种金属的来源深藏于奥达曼。")
zh(1138,"古博对螃蟹的热情远超他边钓鱼边收集的效率。海岸上的生物们，或许能为他提供许多喜爱菜肴所需的肉。")
zh(1139,"锤趾的使命尚未完成，尽管对暗炉的战斗已取得进展。贝尔格拉姆想要一块据称蕴含泰坦魔法的石板，这种魔法能赋予自由意志，必须在他被敌对族群夺走前夺回。")
zh(1140,"伊克鲁德的记载指向夜道谷与萨提纳尔的半人马领地，那里藏有两颗灵魂晶石。任务要求你解放被囚禁的上层精灵灵魂，并带回德尔格伦，继续削弱埃瑟里克斯的势力。")
zh(1141,"鱼人打乱了古博以往的钓鱼行程。他希望你能协助延续家族的捕鱼传统，并以一条鱼换得他心爱的布拉普鱼竿。")
zh(1142,"垂死之人希望妻子能收到象征他们羁绊的吊坠。他的袭击者抢走了它，而找回它不仅能让塔莎拉重获这件信物，也能得知那些发生的一切。")
zh(1143,"收集的情报表明，现在正是行动的时机。人们相信埃瑟里克斯·纳拉辛占据着塔顶，周遭环绕着比你曾面对的术士更为危险的存在。")
zh(1144,"进口商威利克斯本以为采集块茎能轻松获利，却反被俘虏。他低估了商业机会背后的危险，如今亟需保护才能离开囚禁之地。")
zh(1145,"旅行者们关于巨人旷野昆虫的描述引发了警觉。奥格瑞玛的贝尔戈洛姆需要知晓这股威胁，因此急需一位认真对待此事的信使。")
zh(1146,"一支攻击矮人挖掘点的战团几乎被洞穴中涌出的昆虫摧毁。贝尔戈洛姆要求彻查此威胁，并指示幸存者们将情报带给驻守平原的同伴。")
zh(1147,"摩克塔的战团伤势过重，无法执行对抗昆虫的命令。必须寻求外部支援，将这些生物重新驱赶回它们在战斗中现身的深渊。")
zh(1148,"甲壳的结构异常坚固，暗示这些生物高度进化。将样本带给科兰，或许能助他查明异种蝎的来历与起源。")
zh(1149,"第一场试炼检验信仰，贯穿精神、肉体与意志的磨砺。接受它，便踏上一条揭示潜能的旅程，超越寻常文化所能衡量的范畴。")
zh(1150,"展现信仰之后，你需在猫头鹰巢穴中测试体能。挑衅它们的反应，存活至首领现身，方能证明你在压力下坚守躯体的意志。")
zh(1151,"罗克·艾利姆是少数能独自留在世间、无需助力的元素生物之一。与他交手，是对你们已向导师学成的本领的恰当考验。")
zh(1152,"知识的试炼需另一位导师。布劳格拥有审视你的智慧，因此你须寻他继续学习，这教育已超越单纯的体能考验。")
zh(1153,"旅人发现一只狗头人携带了异常矿石，却拒绝出售。再获取一份样本，可让资源被研究，延续统帅本人关注的事业。")
zh(1154,"布劳格认为单纯体能试炼不足以衡量心智。你须研读一本藏于危险遗迹中的古书，并以回答他设下的问题，证明你真正理解其内容。")
zh(1159,"试炼的第一部分已结束，但另一位导师掌握着下一题。一位前史官在祸害鼠肆虐后仍追寻知识，他设下的要求仍待你完成。")
zh(1160,"这场试炼看重知识胜过力量。修道院曾有一本古书教圣骑士对抗亡灵，寻回它将延续帕科瓦为你铺就的求知之路。")
zh(1164,"吉纳维失去了家族与庄园，指控达比里人偷走了她仅存的财宝。她不再渴望物归原主，只求以致命复仇，让那些在她受苦时兴盛的人付出代价。")
zh(1166,"莫克·莫洛克解释说巨龙焚毁了族人旧日家园，逼他逃亡。他逃命时遗落了财物，如今想从废墟与烈焰洞穴中寻回。")
zh(1167,"在直面埃瑟里克斯之前，了解塔楼的最新动态不失为明智之举。巴苏尔仍在暗中观察，或许能提供关键情报，助你根据当前局势做好应对准备。")
zh(1168,"萨尔格的妻子死于巨龙之口，他拒绝接受莫克莫洛克的撤退。他渴望复仇，渴望回家，请求协助对抗驱逐兽人族的那支军队。")
zh(1169,"德拉兹·吉尔布想查明兽人族旧家园遭袭的主因。当众人争论领导权或寻求报复时，他需要龙崽的心脏与言语，以追溯威胁的源头。")
zh(1170,"查下来，闯进村子的正是奥妮克希亚的族群；德拉兹·吉尔布却疑心背后另有主使。莫克莫洛克得听到这个消息，好让氏族应对一桩看来远超本地纷争的祸事。")
zh(1171,"莫克莫洛克不肯为巨龙的消息动身，只想让氏族留在原地。他命你把这话传给德拉兹·吉尔布——纵然眼前已探明新的威胁，他也不愿重返故土。")
zh(1172,"奥妮克希亚的族群正蔓延至沼泽，威胁任何试图夺回村庄的行动。德拉兹·吉尔布希望在更多幼龙孵化前摧毁卵，阻止此地成为新的育婴场。")
zh(1173,"莫克莫洛克轻蔑地迎接你的挑战，已准备以武力捍卫自己的立场。击败兽人族大王，将结果报告给德拉兹·吉尔布，作为族群领导权争夺战的一部分。")
zh(1174,"赛场上，各族选手争夺胜局，观战者押注各自支持的队伍。若你支持侏儒，门票将让你领取他们胜利的奖赏。")
zh(1175,"赛车与石化蜥蜴的碰撞，催生了赛道的新维护工作。减少附近动物数量，旨在防止更多庞然大物闯入比赛场地。")
zh(1176,"赛车重量的细微差异，影响着胜负。秃鹫骨轻盈而坚固，可用于调整车辆结构，团队还需更多材料以持续优化。")
zh(1177,"泥巴饥肠辘辘，向附近的鱼人索要食物。他的要求暗藏威胁：若你不予提供，他便视你为一顿美餐的可能人选。")
zh(1178,"地精团队在等待加兹鲁维承诺已久的燃料调节器。延误成事，因侏儒正步步紧逼；查明原型去向，方知究竟发生了什么。")
zh(1179,"火箭车手在测试中屡遭撞击，伤痕累累。兄弟们急需坚固头盔，然其联络人无法远行，唯有你协助将这保护送至远方赛场。")
zh(1180,"加兹鲁维始终没收到他许给普兹克的调节器。发货一事归里维加兹管，去翻藏宝海湾的货运簿子，或能查明这批货究竟有没有发出。")
zh(1181,"码头主管无法推进调节器调查。里维加兹最懂自己的生意，下一步便是前往酒馆拜访他，追查订单去向。")
zh(1182,"风险投资公司使用的切割机，搭载了新型调节器，或可助益普兹克。考兹尔将蓝图锁得严实，里维加兹需你获取信息，因其自身努力未果。")
zh(1183,"调节器蓝图已准备妥当，即将送往普兹克。里维加兹希望维持对团队的支持，期盼这份助力能助其打破纪录。")
zh(1184,"贝尔戈洛姆需要关于摩克塔行动与昆虫研究的最新消息。返回奥格瑞玛，可向他汇报命令已执行，调查也持续推进。")
zh(1185,"阿姆伯尔希望你明白在希利苏斯找回的物件对塞纳里奥议会的价值。他认定这是一本古籍，打算仔细研究，解释为何此发现值得如此关注。")
zh(1186,"团队正将调节器整合进赛车，拉泽瑞克或许仍需援助。飞行员自行改装，为这支已换第十八名车手的车队提供另一条助力之路。")
zh(1187,"拉泽瑞克希望为赛车注入更强动力，已订购特殊推进器。载有推进器的飞艇坠毁在沼泽，他需要你找回零件，以实施他的高风险改装。")
zh(1188,"推进器的安全限制了拉泽瑞克想从中汲取的功率。他对这层保护不满，遂派你前往加基森，让史瑞夫移除限制，将装置调整至他的需求。")
zh(1189,"史瑞夫已按拉泽瑞克要求改装推进器，却警告此举可能致命。将它带回时，务必带上这警告，因提升的功率已让车手在赛道上容错率极低。")
zh(1190,"普兹克怀疑侏儒们发现了一种材料，可提升车速而不改变设计。他想偷走瑞兹尔的图纸，以了解其优势，而这一切由扎米克安排的分心计划掩护。")
zh(1191,"扎米克已准备就绪，将为普兹克的计划制造所需分心。他的介入旨在将瑞兹尔引开，使你得以获取关于侏儒赛车材料的情报。")
zh(1192,"普兹克希望将铟铁融入不同赛车部件，需要大量矿石。侏儒已有自用来源，因此从奥达曼获取矿石，是保持其团队竞争力的关键。")
zh(1193,"破损的陷阱若能修复，或许可避开附近的食人魔。一张便条说明所需材料，为那些曾试图修复却失败者提供另一种可能。")
zh(1194,"计划中详述了铟铁的提炼方式，强调其耐高温特性。也指明奥达曼是矿源；将样本带给普兹克，或可解释侏儒的制胜优势。")
zh(1195,"获取半人马遗物需取月之井的水。首先须寻得合适的容器，再收集足够液体，方能尝试接近守护该神器的守卫。")
zh(1196,"收集的水须送往千针石林的拉乌。其送达是回收遗物的准备阶段，将精灵领地的搜寻与下阶段所需之人连结。")
zh(1197,"那水能暂时浇灭守着半人马遗物的火焰。要取回遗物，就得趁这水还顶用，赶在火焰重燃之前，在设防的营地深处动手。")
zh(1198,"塞尔瑞德尚未从调查庙宇下娜迦与邪教徒的传言返回。寻找他既可协助侦察员，也能获取指引银色黎明行动的讯息。")
zh(1199,"银色黎明认为暮光之锤正与纳迦密谋，以侍奉远古的主子。对抗这个邪教，旨在扰乱沉没神殿深处可能酝酿的阴谋。")
zh(1200,"古老的神殿已被腐化，一个旧神的仆从正接受无辜者的献祭。阻止克尔里斯，将挑战邪教通过这种暴力获取力量的计划。")
zh(1201,"部落与联盟的停战并未终结间谍活动。渗透者监视蕨墙村，并向塞拉摩汇报动向；铲除他们，旨在切断情报泄露并警告其上级。")
zh(1202,"两名间谍从一艘船上获取了文件，却在被发现后将它们丢入海中。那个铁箱仍沉在塞拉摩码头之下，找回它将挽回他们的渗透成果。")
zh(1203,"贾尔需要一把特定的刀具，用于切割工作，但他拒绝解释用途。一把月钢宽剑正合他心意，而他的急切让寻找变得刻不容缓。")
zh(1204,"摩根正在研发一道新菜，却无法面对沼泽的危险去采集食材。他需要叉尾海龟的舌头，以增添他汤品中独特的风味。")
zh(1205,"梅洛描述了一只古老的鳄鱼蜥，其力量犹存，但年迈的身躯带来无尽痛苦。他相信终结它的生命，将让困于其中的巨灵得到安宁。")
zh(1206,"贾尔喜爱蜘蛛眼汁的风味，想要完整的眼珠来自黑雾蜘蛛。它们众多的眼睛，使它们成为他渴求这咸味饮品的最佳来源。")
zh(1218,"贾尔想炖一锅浓汤，需要一些香料来调味。若能替他寻来，他便能开始准备，并承诺分你一些成品。")
zh(1219,"一只断掉的兽人手掌紧攥着一根管子，管里塞着张沾满泥的羊皮纸。纸卷看着要紧，写的却全是兽人语。交到塞拉摩海军上尉手上，它便归入守军的卷宗。")
zh(1220,"这份重获的报告指向塞拉摩附近潜伏的部落间谍。维米斯比多数人更懂兽人语，他需要这份文件来解读内容，查明威胁的真相。")
zh(1221,"深埋地下的珍贵块茎难以寻觅，唯有训练有素的动物才能嗅出踪迹。请求者愿以丰厚报酬，换取这稀有佳肴。")
zh(1222,"伊格纳茨为摩根的食谱寻找香叶，却陷入群兽围困。他需护送至安全地带，方能完成采集。")
zh(1238,"那张藏于断手中的纸卷，记录了数周关于塞拉摩的情报。将它交给蕨墙的间谍大师，便可重获一份遗失在尘土中的报告。")
zh(1239,"一具断头从泥土中浮现，仍带着倔强神色。这发现必须立刻禀报蕨墙的纳泽尔。")
zh(1240,"马格之死疑云未解。纳泽尔认为金维莱的魔法或许能与他的灵体沟通，需将断头带往格罗姆戈尔的巫医，查明真相。")
zh(1241,"外交官与吉安娜的会面无疾而终，迪菲亚兄弟会的嫌疑浮出水面。皇家特使彻查之际，另一条隐秘渠道正悄然展开，只待真相不再隐匿。")
zh(1242,"乔贞将一封密信交予你，叮嘱务必隐秘。信件通过他的熟人传递，收信人将自行决定是否透露这份牵涉敏感调查的讯息。")
zh(1243,"埃林将借力人脉追踪，而你需在前线搜集线索。夜色镇的凝视者熟稔本地迪菲亚动向，可指引搜寻方向，与外交官失踪的路线交织。")
zh(1244,"凝视者忆起一处农舍曾聚集异常可疑的迪菲亚成员。调查此地或可追溯数周前的事件，为外交官的失踪提供更明确的追踪方向。")
zh(1245,"发现的文件太过复杂，绝非转移视线之物。凝视者引你去找埃林解读，叮嘱勿将他的协助外泄，唯恐隐瞒情报引发祸端。")
zh(1246,"文件牵涉达舍尔与外交官失踪案。前往暴风城旧城区寻他，若他不愿开口，便以武力逼他吐露难以轻易获得的真相。")
zh(1247,"达舍尔承认知晓阿德尔庄园的密会，并牵出一个叫滑鳗的男子。将此线索交予埃林，搜寻将指向米奈希尔，那里曾是联络人的据点。")
zh(1248,"埃林在米奈希尔有旧识，或许能寻得滑鳗踪迹。米克哈尔或许能提供新线索，至于被绑架者的身份与去向，至今仍是个谜。")
zh(1249,"米克哈尔听你提问时，一名男子在出口处偷听，太过专注。若让他逃走，便可能失去关于绑架案的重要线索。")
zh(1250,"嫌疑人透露受害者是暴风城的国王，迪菲亚还有其他合作者。他的任务是将亨德尔送上王舰，米克哈尔需要这条新线索。")
zh(1251,"被熏黑的盾牌仍钉在烧毁旅店的烟囱上。从旅店仅存的残骸中取回它，就能将一件历经树荫旅店大火的物品交给克罗格。")
zh(1252,"灰烬里躺着一枚塞拉摩徽章，上面刻着帕瓦尔·雷瑟中尉的名字。把这件认明的东西交给维米斯——它落在旅店残骸里，便把守军中的一员牵了进去。")
zh(1253,"大火留下被熏黑的铁盾，嵌在树荫旅店的烟囱中。可从砖块中取出，作为一处保存在废墟中的遗物交给维米斯。")
zh(1258,"新菜的摆盘需要壳完好无损的蟹腿。本地物种不敷使用，摩根需要你前往悲伤沼泽采办他研究所需的原料。")
zh(1259,"维米斯不认得帕瓦尔·雷瑟的名字。泰索兰掌管守卫的人员与装备记录，提供了一条通过查阅他的书册，辨识与徽章关联的中尉的途径。")
zh(1260,"安古斯正在为蓝色隐士设计以沼泽为主题的菜单，派摩根去塞拉摩搜集食谱。他需要这些发现的消息，却无法亲自踏上长途跋涉。")
zh(1261,"玛格的灵体回想起曾偷走一枚过于华丽的吊坠——那士兵佩戴它时显得格格不入。返程途中，一名蟹人杀死了他；若能找回这颗宝石，他的未竟使命或许得以延续。")
zh(1262,"这枚吊坠似乎只配贵族佩戴，但玛格却在普通士兵身上发现它。佐尔懂得联盟的权谋，或许能辨明它的主人，从而解释为何它会落入如此意外之手。")
zh(1264,"库尔提拉斯水兵常在发薪日后造访米奈希尔，而亨德尔似乎属于其中一队。若你悄悄提及与埃林的关联，萨穆尔或许能协助你在塞拉摩找到他。")
zh(1265,"萨穆尔认识亨德尔，也明白埃林只会在棘手事务上寻求帮助。他指引你前往塞拉摩外的第一座塔楼，同时提醒你留意任何可能威胁他领地的动静。")
zh(1266,"亨德尔守护着一群潜伏的间谍，他们正短暂休整，以观察蕨墙村的动向。路旁的帐篷标记了他的藏身之处，而你的联系人仍可在吉安娜的塔楼中随时待命。")
zh(1267,"吉安娜承认了对塞拉摩与暴风城的帮助，但她无法公开致谢。这场会面给予了她隐秘的认可，也邀请你通过未来的访问，持续掌握事态进展。")
zh(1268,"蹄印从仍在冒烟的旅店外延伸，随后在泥泞中若隐若现。将它们报告给克罗格，这可疑的足迹便能加入树荫旅店废墟中发现的物证之中。")
zh(1269,"一枚塞拉摩徽章埋在废墟之下，被灰烬覆盖。帕瓦尔·雷瑟的名字揭示了它的归属；将它交给克罗格，便能在这批从废墟中回收的物品中找到明确线索。")
zh(1270,"麦伯克·米希瑞克斯重金雇人寻觅沼泽蕨叶，却在寻获之前遭生物围困。他需护卫协助采集此物，并寻得脱身之法。")
zh(1271,"安古斯听闻你协助摩根·匹斯特的研究并营救其同伴，斯特恩家族欲以在蓝色隐士举办的庆典，向你致以谢意。")
zh(1273,"奥格隆历经漫长搜寻终寻得雷瑟，却忧心沼泽已侵蚀其心智。陪同他赴会，或可厘清调查中仍悬而未决的真相。")
zh(1274,"主教需隐秘协助处理一件微妙事宜，遂派遣人手寻觅冒险者。与他相见，或可得知一项足以令他避嫌的重要请求。")
zh(1275,"研究者忧惧恶魔魔法或会扭曲血精灵，其风险与半人马与娜迦相较，亦无高下之分。两族生物样本，正可验证腐化之说。")
zh(1276,"从雷瑟处未得有用线索，盾牌的起源仍是唯一未解之谜。莫萨恩是雷霆崖受人敬重的铁匠，其知识或可揭示此物的过往。")
zh(1282,"吉姆曾非今日之貌，他昔日曾经营沼泽中的旅店。知晓他过往之人，皆避谈那场变故，只引你前往维米斯处寻线索。")
zh(1284,"蹄印自树荫旅店的焦土中延伸而去。虽部分痕迹隐没于泥泞，维米斯仍需知晓这在焚毁酒馆旁发现的证据。")
zh(1285,"记录显示雷瑟是一名库尔提拉斯水兵老兵，随吉安娜的招募者一同抵达。他被列为失踪，将这些发现交给维米斯，能让搜寻继续下去。")
zh(1286,"一群逃兵占据着废弃哨塔，他们的首领加科因或许知道雷瑟的下落，但维米斯警告，获取答案可能需要突破重重阻碍。")
zh(1287,"逃兵们把雷瑟赶了出去：他屡次劫掠食人魔，反叫营地陷入险境。加科因这样解释，还请你把他们的藏身处忘干净。维米斯那边，等着听你探回的实情。")
zh(1288,"吉安娜希望了解这个微妙局势的进展，维米斯也需要更新报告。你直接参与调查，正是向她汇报并回答问题的合适人选。")
zh(1301,"安古斯的生意仰赖詹姆斯·海厄尔，但他近期已许久未收到老师的音讯。搜寻从米奈希尔开始，詹姆斯和他的兄弟曾在那里的一家酒馆工作。")
zh(1302,"文森特解释说詹姆斯随吉安娜渡海，并在最后一次消息中正在筹备一家酒馆。虽然他也没有新消息，但他相信塞拉摩的办事员或许能帮你找到他的兄弟。")
zh(1318,"克罗卡斯认为真正的戈多克国王必须找回被托塞德林夺走的护腕。如今你身负此责，他请求你寻找这件遗物，完成一段击败往昔君王的旧故事。")
zh(1319,"维米克无法提供更多关于烧毁盾牌的信息，但他认识一位工匠或许能鉴定它。卡兹在塞拉摩的铁匠铺工作，或许能解释这件遗物所揭示的真相。")
zh(1320,"皮带似乎已被烧毁，但其尺寸表明，可能是某个高大之人，或许是个牛头人。将这件稀有发现带到维米斯处，但不要过早认定持有者的身份。")
zh(1321,"盾牌初看并无明显痕迹。克罗格建议让多戈尔以工匠的技艺仔细查验，但他对这件器物能否提供有用信息并不抱太大希望。")
zh(1322,"盾牌边缘的铭文被烧焦的残渣遮掩。多戈尔需要酸液来清理，他相信暗牙蜘蛛的毒液能让这段模糊的铭文变得清晰。")
zh(1323,"清理后显露的铭文难以辨识，似乎刻着莫萨恩。多戈尔不认识这个名字，但克罗格熟人众多，或许能帮找出盾牌上所指的那个人。")
zh(1324,"亨德尔对被指控与迪菲亚勾结的指控反应激烈。调查已演变为对峙：制服这名士兵，他将你的提问视作无法容忍的侮辱。")
zh(1338,"雷矛希望得到一位匠艺精湛的盔甲师打造的盾牌。弗伦远在暴风城，因此必须派信使将请求送往城中的矮人区。")
zh(1339,"巡山人雷矛寻找一位愿意承接差事的同行者。在北方卫士哨塔与他会面，便可得知他需要一名跑腿者完成的任务。")
zh(1358,"赫布瑞姆研究洛达瑞恩的毒素对卡利莫多野兽的影响。递送样本能延续这项调查，并将药剂师的研究连结至彼岸。")
zh(1359,"回收的心脏蕴含异常强烈的毒素。将样本交给金格，能让另一名药剂师调查这次意外，它甚至让最初的学者也感到惊讶。")
zh(1360,"克罗姆在奥达曼被巨魔入侵时逃了出来，却将最珍视的物品留在了箱子中。他愿为此付出报酬，因敌人环伺，尽管容器仍能安全保管它。")
zh(1361,"雷戈萨正在招募部落特工，执行一项深入凄凉之地的任务。志愿加入者应前往贫瘠之地寻找他，做好进入战火频仍、危机四伏之地的准备。")
zh(1362,"科卡尔人从凄凉之地扩张至贫瘠之地，他们本土的力量维系着威胁。费古尔正在收集情报，能引导出超越单纯遏制入侵的应对策略。")
zh(1363,"马森担心图书馆的魔法典籍落入不法之徒手中会带来灾祸。他的助手迪利斯在暴风城外犯了错，需要支持解决，因此你必须从他口中得知真相。")
zh(1364,"迪利斯在沼泽生物逼迫下逃亡时，丢失了重要论文。马森曾托付他将论文送往守望堡，找回文本并亲手交到马哈尔·巴手中，才能弥补助手的过失。")
zh(1365,"半人马各部彼此争斗，始终结不成一股合力。部落要趁局势未变先动手：头一桩便是搅乱科卡尔——杀掉他们的可汗，叫部众失了主心骨。")
zh(1366,"在震慑各部后，费古尔希望削弱他们的实力与野心。他悬赏半人马的耳朵，不论所属部落，目标是削减他们的数量与扩张的决心。")
zh(1367,"此计借半人马的内斗，从他们自己人中间摸清弱点。你若要投玛格拉姆，就得先与他们的死敌吉尔吉斯厮杀，攒下足够的敬意，才见得到代言人瓦鲁格。")
zh(1368,"与某一族群结盟，便可利用其矛盾，学习如何击败其余族群。通过与玛格拉族交战并赢得尊重，方可接近吉尔吉斯族，再向乌泰克寻求指引。")
zh(1369,"吉尔吉斯族视与瑟莱德丝相关的水晶为神圣之物。瓦鲁格意图证明他们的所谓庇护并不存在；摧毁水晶之泪，并归还碎片，便可挑战敌族的信仰。")
zh(1370,"玛格拉族储备肉类以维持战事，无需频繁狩猎。乌泰克希望窃取这些储备，她相信剥夺族群的食物，将削弱其持续战斗的能力。")
zh(1371,"瓦鲁格记得曾从一个被他杀死的精灵的车上，夺走一个机械木人。在亲手毁掉它之后，他想要一个替代品，以重拾昔日的乐趣。")
zh(1372,"一名人类间谍曾暗中观察亡灵营地，直到被兽人俘获。这次远征希望低调介入他的审讯，与法奥斯丁合作，以所谓真相药剂施加于斯通纳德的囚犯。")
zh(1373,"乌泰克听闻世上存在一种异界的水晶，可增强她的魔法。盎格库尔手中握有一片碎片，藏于悲伤沼泽之中，这便是为吉尔吉斯族取回的下一项任务。")
zh(1374,"乌泰克解读大地的讯息，认为玛格拉族正在衰弱。她相信时机已至，该对他们的可汗出手，并要求取下其首级，以证明一击之力。")
zh(1375,"你的帮助赢得瓦鲁格的好感，他如今想将与吉尔吉斯的恩怨扩大至他们的首领。他要求取沙卡的首级，好让敌人可汗的溃败尽收眼底。")
zh(1380,"乌泰克希望将对吉尔吉斯敌人的战役扩展至消灭玛洛迪可汗。号角能引出赫鲁萨，他掌握着关键碎片；你必须获得发声的手段，并取回那片碎片。")
zh(1381,"吉尔吉斯可汗倒台后，瓦鲁格想打击玛洛迪，夺取赫鲁萨的碎片。他们的号角能引发冲突，但发声需依靠只由信赖的半人马携带的吹嘴。")
zh(1382,"半人马尚未统一，这是各部族争斗的良机。攻击玛格拉可能促成与吉尔吉斯的联盟，而萨满乌泰克正是联络的桥梁。")
zh(1383,"法奥斯丁为渗透者准备了一种血清，需从多种生物身上采集材料。最难获取的原料来自凄凉之地的病态巨人，准备过程远超沼泽范围。")
zh(1384,"乌泰克轻视科卡尔的魔法，想借攻击让其声名狼藉。你找回的符咒能让她嘲弄对手的法力，并摧毁他们视若珍宝的魔法符号。")
zh(1385,"联盟担忧半人马战争的胜者终将威胁其据点。通过对抗吉尔吉斯赢得玛格拉的青睐，或许能建立联盟，研究并对抗各部族。")
zh(1386,"瓦鲁格要你展现实力，对抗他族蔑视的科卡尔。向北进攻将支持玛格拉的敌对立场，并证明你敢于直面相同敌人。")
zh(1387,"麦尔金斯认为这场战争源于半人马族群共有的暴虐。他命你去猎杀他们，带回他们的耳朵，为联盟效力，相信唯有清除这些族群，和平才会更近一步。")
zh(1388,"法奥斯丁认为准备已就绪，便将真相药剂交予你。将它带给莱度斯，他会教你如何将药剂施予被拘禁在斯通纳德的间谍，继续推进这次远征。")
zh(1389,"失落者从避难营的旧友手中偷走了圣晶石。他们的受害者因无力夺回而沮丧，又惧怕在没有他们所崇敬的德莱尼石指引下迷失方向。")
zh(1391,"莱度斯希望法奥斯丁将药剂混入麦酒，让囚犯毫无防备地饮下。速将这混合物送往斯通纳德，行事隐秘，别让亡灵的干预暴露出来。")
zh(1392,"诺博鲁已折磨避难营的德莱尼数月之久。他的木棒象征着他们所承受的暴行，将它交给他们的领袖，便是把这象征虐待的标志呈现在社群面前。")
zh(1393,"加林担心他的俘虏会吃掉他，便以宝物为代价换取逃脱。唯有他知晓开启营地保险箱的密钥，因此他必须活下来，才能将秘密公之于众。")
zh(1394,"试炼已证明你心智、身躯与灵体的平衡。返回多恩，让他认出你的进步，并给予你训练期间所付出努力应有的回报。")
zh(1395,"送往守望堡的能量石将在下一批商队出发前失去力量。一名信使必须迅速穿越危险地带，趁它们仍有价值时，将货物送交军需官。")
zh(1396,"失落者摧毁了一支商队，只留下卫兵比格斯存活。他誓要守护残余物资，但沼泽生物正步步逼近，他急需援手保卫营地。")
zh(1398,"比格斯必须修好马车才能抵达守望堡，但沼泽的木材不适用。他请求从海岸获取干燥的漂流木，足够让车辆重返大路。")
zh(1418,"荒芜之地恶劣的环境与邻近联盟领地，阻碍了与斯通纳德的通讯。抵达尼卡并带回她的报告，将重建这条联络线，也让你有机会证明自己作为信使的价值。")
zh(1419,"山狗胆敢闯入卡加斯盗取食物。尼卡希望驱除这些贼寇，视此猎捕为考验你对荒芜之地险境的熟悉程度。")
zh(1420,"尼卡已为赫格拉姆准备了新报告，需你送达斯通纳德。此趟行程考验你穿越部落哨站之间路线的导航能力与避敌技巧。")
zh(1421,"比格斯曾目睹失落者拖走一辆马车朝村庄而去，他失去意识前，那辆马车载有对守望堡法师至关重要的材料；找回它们，便能挽救这批货物的重要部分。")
zh(1422,"当托克·卡尔为你打造武器时，他希望你保持警觉，而非浪费时间饮酒。卡塔尔需要协助海岸巡逻，能提供你在海岸险境中工作的机会。")
zh(1423,"找回的木桶带着蜡封与一枚刻有军需官朗格尔斯的印记。铭文指明这些遗失物资的归属，使它们能被送回封印上所指的军官手中。")
zh(1424,"远征队抵达神殿时，发现它已被海水淹没，且由绿色巨龙守护。费尔泽鲁尔需要阿塔拉伊的神器来重现过往，弄清他们的禁忌仪式与神殿神秘状态之间的关联。")
zh(1425,"比格斯已将能带走的最重要物资打包完毕，他必须留下修理马车。他需要你将货物送往守望堡，那里始终监视着黑暗之门。")
zh(1426,"卡塔尔对鱼人恨之入骨，看到他们被部落击败便感到畅快。他挑战你与他们更强的族群对抗，将海岸巡逻变成一场战斗的考验。")
zh(1427,"卡塔尔相信托克拉在你协助海岸任务期间已打造了几件武器。他送你一件作为谢礼，并鼓励你用它对抗他憎恶的鱼人。")
zh(1428,"卡塔尔希望继续与海滩鱼人对抗，并承诺奖励坚持猎杀的人。他派你对付更多族群，欣喜地发现有人愿意与他共享对这些生物的敌意。")
zh(1429,"一份文件显示，一名阿塔拉伊牧师被流放至辛特兰。费尔泽鲁尔想借这个联系人了解回收神器的真正用途，因此派你将样本带给他。")
zh(1430,"达尔的顾客愿意为海岸巨蟹的肉付高价。如果你正前往海滩，他可提供报酬，用你捕获的蟹腿运往奥格瑞玛，满足那里的饮食需求。")
zh(1431,"萨尔对人类外交的理解不亚于部落与他们的冲突。这段对话引入了政治背景，并引导你前往科尔丹，由他继续解释他族人的需求。")
zh(1432,"部落希望阻止联盟将恶魔活动解读为某种契约的证据。其特工正筹备在凄凉之地展开干预，需在萨尔的批准下协助清除这股威胁。")
zh(1433,"玛乌林摸透了火刃氏族的路数，正主持凄凉之地剿杀其术士的战事。去向他问计，你便能入伙这场谋划；此地其余的恶魔祸患，自有他的同伴料理。")
zh(1434,"山羊人利用脆弱与痛苦传播腐蚀。他们与火刃氏族的勾结令萨尔下令进攻，你需要协助驱逐这些在东北部肆虐的恶魔。")
zh(1435,"玛乌林认为对堕入黑暗者，死亡尚不足以惩戒。当他们虚弱时，一颗宝石可提取其堕落之灵，让他以他认为合适的方式处置这些囚禁的魂魄。")
zh(1436,"对抗恶魔及其仆从的行动进展顺利。科尔丹需要了解战果，既因他重视这场斗争，也因统帅曾尊重他的关切。")
zh(1437,"瓦拉里尔受父亲委托，寻找失踪的玛雷姆商行孩童。他们最后的行踪跨越了石爪峰，找到他们的马车，便能揭开他们在凄凉之地的下落。")
zh(1438,"搜寻仍在继续，但瓦拉里尔的上司对泰拉尼斯的动机存疑。黛琳达必须安全带回，而她的哥哥则需评估后，才能决定是否送回故乡。")
zh(1439,"兽人杀害了玛雷姆的侍神者，并掳走了兄妹二人。黛琳达拒绝离开，除非弄清泰拉尼斯的下落；她认为他用对奥术的了解，试图给俘虏留下好印象。")
zh(1440,"黛琳达已准备好离开要塞，对您为她家人所做的一切心怀感激。她需要护卫离开险境，才能返回那些寻找她的人身边。")
zh(1442,"一颗科尔宝石或许能在古迹中的娜迦群中寻得。斯迪威尔的请求看似正直，但获取这材料意味着要协助对抗潜伏在地底的危险。")
zh(1444,"流亡者惧怕贾马拉恩的预言将毁灭他的族人。检视的神器无害，但他警告某些附魔可能使仪式变得危险；费尔泽鲁尔需要这个区别与潜在威胁的解释。")
zh(1445,"费尔泽鲁尔担心，那些附了邪法的图腾正是仪式的根基——贾马拉恩借此向族人许诺永生。他要细究图腾里的力量，才看得清凶险何在；样本得从神殿深处取来。")
zh(1446,"这名牧师因质疑承诺通过哈卡赐予永生的预言而被放逐。如今他想向贾马拉恩复仇，认为除去领袖或许能解救他的族人脱离他所恐惧的操控。")
zh(1447,"达舍尔以威胁回应你的现身，并引人注意他的同伴。要获得他的合作，必须先化解他在暴风城引发的冲突，那场冲突源于他抗拒调查失踪外交官的调查。")
zh(1448,"布罗哈恩从未找到他为探险者协会寻找的神殿。年岁已让他无法继续，因此他请你步行进入悲伤沼泽，解开他空降搜索未能发现的谜团。")
zh(1449,"陪同布罗哈恩的飞行员在神殿搜索时从狮鹫上坠落。由于年迈的矮人已记不起他的名字，前往鹰巢山辨认他的身份，并查明坠落后发生了何事。")
zh(1450,"弗斯塔德不清楚你调查的飞行详情，只指向狮鹫管理员沙拉克·鹰斧。他负责飞行任务，或许能辨认出与布罗哈恩一同搜寻神殿的飞行员。")
zh(1451,"沙拉克记得拉普索迪是位非凡飞行员，但与布罗哈恩的远征后，他的饮酒习惯愈发严重。被革职后，他似乎住在一处酿酒营地，那是寻找旅程真相的下一步。")
zh(1452,"拉普索迪坚持要在强酒下才肯解释沼泽发生的事。他要求从塔纳利斯与菲拉斯收集原料调制鸡尾酒，而收集这些材料，便是换取他讲述远征的代价。")
zh(1453,"公司仍愿在凄凉之地提供工作，纵使有半人马与其它威胁。克雷迪格从尼杰尔点安排任务，能为愿意踏上旅程的人提供报酬。")
zh(1454,"海巨人袭击了卡尼托尔的船，逼他丢弃一个宝箱。他与仆从靠魔法逃出生天，但财物却遗落在凄凉之地海岸，如今亟需寻回。")
zh(1455,"宝箱空无一物，且有深痕，不像武器或原袭击者留下的印记。克雷迪格需听闻这次失败的回收，以及那些让搜索更加复杂的痕迹。")
zh(1456,"箱上的痕迹指向北面水下遗迹中的娜迦。克雷迪格建议在它们最强的战士中寻找，他们或许曾率侦察队抵达沉船。")
zh(1457,"卡尼托尔的财物需送回铁炉堡，让罗顿完成委托并支付报酬。交付不可延误：主人慷慨，却也少有耐心。")
zh(1458,"公司同意为左巫获取材料，尽管人手不足。首批样本来自本地的半人马，协助收集它们将开启一项报酬丰厚的委托。")
zh(1459,"左巫的清单需要蝎子毒液与特定年岁的卡多雷兽皮。克雷迪格希望这些条件被严格遵守，以确保术士的委托能持续获得所需材料。")
zh(1462,"若要重获大地灵契，你需去找鸦羽先知，向她索取另一杯饮品。")
zh(1463,"坎纳甘·地鸣可提供另一份大地灵契。你必须返回与他交谈，以重获这杯饮品。")
zh(1464,"若你曾败于火焰化身之手，泰尔夫·祖拉姆可赐你另一份灵契，再度见证神龛灵体。更换饮品将使你得以再次挑战，继续你的萨满训练。")
zh(1465,"马车里挂着一枚吊坠，指引着一座灯火通明的堡垒。若马尔姆族尚在人世，他们或许已被送往那里；瓦拉里尔·屠魔者需要这些线索。")
zh(1466,"委托的最终阶段需要从危险的恶魔生物身上获取材料。克雷迪格·安戈尔警告你，这将比之前的采集更加艰难，也理解有人可能拒绝这场风险之旅。")
zh(1467,"左巫的包裹已备好，将送往铁炉堡的罗顿·石锤。带回它将结束这趟材料委托，并确保为公司代劳所得的报酬。")
zh(1468,"暴风城孤儿院的孩子们将在特殊周迎来庆典，需要有人陪伴。院长赠予哨子，好让你认领结界中的孩童，共度时光，共享欢乐。")
zh(1469,"拉普索迪解释他因醉酒落水，意外发现水下神殿。他逃亡时带走了一块碎片，希望将其交给布罗哈恩作为水下遗址存在的证据。")
zh(1470,"知识是驾驭黑暗之力的钥匙。收集材料，便是学习如何束缚仆从，而非被其支配。")
zh(1471,"召唤虚空行者只是开端。你的训练要求证明，意志与魔法足以征服你欲驾驭的生物。")
zh(1472,"你的导师打算用某样东西引诱魅魔，令其堕落。学习下一步，将看出恶魔的欲望如何成为控制的工具。")
zh(1473,"一名血色僧侣偷走了召唤虚空行者所需的魔典。找回它，便是进一步学习驾驭危险生物的训练。")
zh(1474,"所集材料可为魅魔开启通道。战胜它的诱惑，方显驾驭它所需的掌控之力。")
zh(1475,"布罗哈恩·铁桶希望取回沉没神庙的石板，以彰显发现的荣耀。进入阿塔拉伊神龛实属不易，因其沉没位置与不朽声名，令探险者协会的任务更为艰难。")
zh(1476,"高德瑞克·法杉挑出两名心地善良的男子，他们的仁慈足以引诱魅魔。夺取他们的心脏，将使你的术士训练依赖于那些因这份美德而被选中的牺牲品。")
zh(1477,"守望堡钻研黑暗传送门，全仗补给不断，可这条路并不太平。索里加尔要人帮忙把货物送到位——动身穿过这片敌境之前，先去领他的吩咐。")
zh(1478,"凯伦丁·哈加尔召唤你前往幽暗城。他对你的进展有所察觉，并为你开启了一个尚未接受的术士训练阶段。")
zh(1479,"你的结界已听闻那棵熊形树中栖息着达纳苏斯的银行。孩童对自然与建筑的结合充满好奇，因此想带你去看看那些激发好奇的地方。")
zh(1480,"一块剥皮的躯干上刻着红色标记，还有一枚类似签名的符号。它的质地与气味令人不安；玛乌林或许能解读这些文字，并解释这份罕见文件的意义。")
zh(1481,"玛乌林相信自己能找到恶魔领主，但必须先突破所有窥视防御。一顶怨怒巡影者的头皮将为他提供突破结界所需的特殊材料。")
zh(1482,"为了继续寻找阿兹雷索克，玛乌林需要一块由纳迦先知使用的水晶。获取它意味着要进入沿海的滑刃海岸聚居地，那里的居民会为保卫家园而对抗入侵者。")
zh(1483,"齐兹在侏儒技师抵达后离开风险投资公司，正寻找新的工作。检查他新联系人指派的任务，或许能助他完成职业的转变。")
zh(1484,"阿兹雷索克比玛乌林预想的更具威胁。塔卡塔需要了解详情并批准行动，但你协助的意愿必须以不损害他的荣誉感为前提。")
zh(1485,"对术士的不信任未曾阻断你的训练。在教授召唤术前，你的导师要求你证明自身实力，对抗东北方洞穴中栖息的邪灵劣魔。")
zh(1486,"当纳拉雷克斯沉入梦魇时，哀嚎洞穴中出现了奇异生物。它们异常的皮毛或许对制皮大有裨益，为腐化之物赋予实际用途。")
zh(1487,"纳拉雷克斯曾希望借翡翠梦境复兴贫瘠之地，却让梦境沦为噩梦。众人试图唤醒他，而你必须直面如今占据洞穴的腐化生物。")
zh(1488,"塔卡塔同意阿兹雷索克必须被阻止，尤其若他意图影响火刃氏族。他信赖你去集结盟友，对抗这位恶魔领主与侍奉他的术士。")
zh(1489,"检视过的贝壳带有陌生的污染，与绿洲之水有关。在调查洞穴前，你被派去请教年长德鲁伊哈穆尔，他已知悉这桩麻烦。")
zh(1490,"哈穆尔的梦境揭示了背弃崇高使命的德鲁伊，如今侍奉污染。纳拉在力量耗尽后仍滞留于梦境之地，成为下一位需咨询之人。")
zh(1491,"先前用迅猛龙角的实验失败。新的饮品配方将测试洞穴中的精华，其创造者怀疑这物质与贫瘠之地的奇异动植物有关。")
zh(1492,"一批药水与材料急需送往海外，但最后一趟商队已启程。将它们送往棘齿城的码头管理员处，便能顺利装船远行。")
zh(1498,"守护部落中较弱的成员，是战士的职责。对抗杜隆塔尔的雷霆野兽，将考验你能否抵御攻击，以及是否具备胜任此职的坚韧。")
zh(1499,"祖雷萨正派新手前往附近洞穴清理怪物，你的导师建议协助她积累经验，并让她知晓你先前对抗小鬼的战绩。")
zh(1500,"利牙领主已经伏诛，觉醒仪式此时可以一试。施术者要有人护住，不叫纳拉雷克斯的梦魇近身；他正筹备的那场干预，缺了你出手相抗便成不了。")
zh(1501,"下一次召唤课程，取决于火刃氏族术士偷走的石板。从他们的巢穴夺回它，便能获得铭刻虚空行者的符文。")
zh(1502,"战士手里得有件靠得住的兵刃，索恩格瑞姆正有这份手艺。这位铁匠避世而居，营帐扎在山岗上——要换更好的装备，下一步就是寻到他。")
zh(1503,"野猪人欺索恩格瑞姆眼神不济，偷走了他锻好的钢条。那只装钢条的箱子得找回来——他要的帮忙就这一桩，办成之后，你求的兵器自会到手。")
zh(1504,"找回的石板内含召唤虚空行者的符文。你必须在召唤法阵中使用它们，并击败该生物，导师才会教你如何将其束缚。")
zh(1505,"单凭力量无法成就伟大的战士，愿学习之心同样重要。尤塞克历经无数战役，能为你指点如何磨砺战斗技艺。")
zh(1506,"甘鲁尔希望你尽快前往资深术士中会面。消息未明示召唤缘由，你须前往暗影裂口，亲自听他交代。")
zh(1507,"召唤魅魔需一物象征爱与忠诚。卡祖尔渊博的学识或可助你寻得诱饵，以驯服能操控弱者心智的生物。")
zh(1508,"寻找诱饵引出魅魔的线索指向赞卡沙。卡祖尔指引你前往奥格瑞玛寻她，她正等待伴侣归来。")
zh(1509,"多格兰已失踪一周，赞卡沙仍未收到音讯。因公前往十字路口后，她托你向加兹罗格打听失踪伴侣的下落。")
zh(1510,"多格兰在对抗犀牛兽人营地时重伤，无法安全移动。从玛拉卡金处求来的药剂尚未抵达，需再度设法获取。")
zh(1511,"肯齐格拉已备好药剂，叮嘱你须谨慎施用。药剂须先送到陶拉祖营地的劳格玛手中，他知重伤战士的下落。")
zh(1512,"多格兰惧怕伤重致赞卡沙需照料自己，托你隐瞒病情。他更愿战死沙场，以得体面。将他的吊坠带给甘鲁尔，继续寻找与爱与忠诚相关的物件。")
zh(1513,"吊坠将引来魅魔现身赞卡沙的召唤法阵。这场试炼要求你战胜它，不被傲慢所困，再将吊坠带回，让导师向赞卡沙传递消息。")
zh(1514,"这株植物看似风花，却病态丛生，果实腐烂发黑，毒液暗藏。它的腐败需要治疗，唯有恢复植物原状，果实方能被使用。")
zh(1515,"多格兰仍被困在食人魔营地，伤势未愈。援军无法抽调，你必须独自寻找，否则他的俘虏或伤势将终结他的性命。")
zh(1516,"你的萨满训练即将直面大地本身。在获得进一步指引前，你须展现准备就绪，从北方聚落的地狱捕猎者身上收集所需材料。")
zh(1517,"灵契让你的灵体感知饮品所系之元素。你须在指定的圣地饮用，尊重仪式，让大地与你建立连结。")
zh(1518,"灵体的石英证明了你的会面，将成为图腾之心。将它带给坎纳甘，延续这堂以耐心、坚韧与对大地敬意为基的课程。")
zh(1519,"大地指引着牛头人族群，不久后也将与你对话。你的第一项试炼，是采集食人魔的仪式药膏，为这场启蒙仪式准备药剂。")
zh(1520,"灵契将灵体与元素相连，让其以新方式被感知。你须在萨满圣地饮用，尊崇这场相遇的神圣本质。")
zh(1521,"水晶印证了你与大地的交融，将成为图腾的核心。鸦羽先知需要它来延续一堂围绕耐心、坚韧与追求智慧的课程。")
zh(1522,"你对大地的掌控昭示着学习火焰的时机已至。卡纳尔深谙元素之道，可从他位于十字路口北方的居所继续你的训练。")
zh(1523,"作为萨满祭司的成长，使你得以踏入火焰的课程。卡纳尔栖身贫瘠之地，将引导你理解一个蕴含毁灭与混乱之力的元素。")
zh(1524,"拥有驾驭火焰图腾的力量，并不意味着已准备好。你须携火炬前往特尔的神龛，待它燃尽而归，方能证明你的领悟。")
zh(1525,"下一步，你需要准备一份萨塔。它的炼成依赖于奎博兽与火刃氏族所持的材料，这些你须在仪式前寻得。")
zh(1526,"萨塔已备，使你得以窥见火焰的显现。你须直面它的力量，以防它愈发壮大，再用它的余烬点燃火盆中的火炬。")
zh(1527,"火炬在手，正是离开神龛之时。返回卡纳尔，将你与火焰的邂逅作为证据，呈给这位启蒙你训练的导师。")
zh(1528,"经历火焰的课程后，你的训练将转向水域。伊斯伦可从她位于棘齿城南方、贫瘠之地海岸的居所，教你认识水的本质。")
zh(1529,"火的课程结束后，你的训练转向水。伊斯伦能在贫瘠之地海岸的居所中，教你认识水的本性，那座海岸位于棘齿城以南。")
zh(1530,"水唯有保持纯净，才能象征新生；一旦被污染，便会摧毁它触及的一切。你将继续跟随布瑞恩学习，理解这区别，并朝向水之灵契所需的仪式迈进。")
zh(1531,"你的进步使你得以寻求下一项萨满试炼，关乎空气图腾。普拉特知晓这训练的延续，也期待你以应有的敬意接受她的指引。")
zh(1532,"你的萨满修行已能让你开始学习空气，这元素难以驾驭。普拉特能在千针石林引导你，并解释如何迈向空气图腾的修行。")
zh(1534,"最后一份水样必须来自灰谷的圣泉。取得它，便完成了老师所需的所有组件，随后你将返回伊斯伦，继续下一段训练。")
zh(1535,"理解水，需观察它如何维系生命，又如何在生物间引发冲突。从附近池塘取的第一份水样，便开启了关于纯净、影响与对水源敬畏的课程。")
zh(1536,"塔伦米尔的井水在腐化土地中依旧纯净。你的老师希望你能在旅途中发现这对比，延续对洁净水源在意外环境中的研究。")
zh(1558,"关于矮人建造的巨大水坝的故事，激起了你结界的好奇。孩子渴望前往洛克莫丹，亲眼看看水坝结构下的瀑布，承诺外出时不会探身太远。")
zh(1559,"里格弗兹为工程师送来闪光雷的配方，以表谢意。配方交付之时，知识如约而至，却也伴随着一条警告——使用时切勿自盲。")
zh(1560,"图加为妻子取迪娜时迷了路，回不得家。他需要你带他前往托尔塔，那人在热砂港附近等着他。")
zh(1578,"洛克莫丹的登山者急需装备守护家园。将你的锻造品送到索瓦尔德·深炉手中，既能支援他们，或可习得炉火淬炼的技艺。")
zh(1579,"一位发明家前往奥伯丁途中，将零件箱掉入海中。他急需那些零件继续工作，沿岸垂钓或许能找回失落的箱子。")
zh(1580,"一夜发明与饮酒，让发明家发了狂，发丝焦黑，零件尽失。他以为导电器落入水中，如今急需你帮他打捞回来。")
zh(1581,"布莱德利夫的店铺生意兴隆，两人难有私会。若能提供成品药剂，便能减轻制药之苦，他们愿以珍稀草药交换这份助力。")
zh(1582,"达纳苏斯的工匠正为踏入荒野的冒险者赶制皮具。协助完成订单，既可支援他们，或能习得更精深的制皮技艺。")
zh(1598,"一名昔日学徒盗取修道院典籍，加入迪菲亚兄弟会。你的导师想要那本书，将寻回它作为你成为一名术士的试炼。")
zh(1599,"要学召唤小鬼，先得证明你的法力与身手都过得去。从巨魔新手身上取来的护符便是凭证——替你开术士头一课的那位，要看的正是这个。")
zh(1618,"黑石兽人的袭击让赤脊山的物资供应吃紧。协助人类守军不仅可支援盟军，或许还能从铁匠弗纳·奥斯古那里学到锻造技艺。")
zh(1638,"你的导师将你引荐给老练的哈里·伯加德。从他的经验中学习，能掌握超越当前训练的战场生存技巧。")
zh(1639,"向巴特莱比索要他的酒杯，是蓄意挑衅。导师期待这位老兵有所抵抗，将这场冲突化作对你能力的考验。")
zh(1640,"巴特莱比拒绝交出酒杯，并以挑战回应。这场对峙正是导师想测试的战斗能力。")
zh(1641,"达索瑞恩为你提供一门圣骑士美德与职责的课程。圣洁之书将引导你理解光之意志，待你展现准备就绪，方能习得更深层的能力。")
zh(1642,"圣骑士的训练要求你理解光如何透过行动显现。仁慈与耐心须与勇气并存，因帮助他人与对抗邪恶，同样构成这份使命的核心。")
zh(1643,"下一次课程要求你寻找暴风城中意图善良且需要援助之人。以善意回应真实需求，才是进一步探讨光之道路的起点。")
zh(1644,"孤儿院收留那些因天灾军团而失去家庭的孩子。照料他们的生计已让监护人疲于奔命，若能添些亚麻布，便能为孩子们缝制所需衣裳。")
zh(1645,"蒂萨赠你一本指引你研习光明的书卷。阅读它，将助你理解圣骑士的美德与职责，为日后接受更深层的力量做好准备。")
zh(1646,"圣骑士的训练要求你理解光明如何透过行动显现。仁爱与耐心须与勇气并肩而行，因助人之责，与对抗邪恶同样重要。")
zh(1647,"你须在铁炉堡寻得一位心怀善意、依赖他人善意之人。这实际的援助行为，正是学习何为光明服务的必修课。")
zh(1648,"约翰正在铁炉堡为他与妻子共管的暴风城孤儿院收集物资，但收获寥寥。若能添些亚麻布，便能寄回衣料，为孩子们缝制衣裳。")
zh(1649,"勇气与信念须经考验方能更加强大。你的导师将训练视作磨砺过程，圣骑士的美德须在真实困境中屹立不倒。")
zh(1650,"达芙妮丈夫远行时，她独自留守，而迪菲亚暴徒盘踞四周。寻找她，将你的勇气试炼，转化为保护她免受强盗侵害的行动。")
zh(1651,"达芙妮料定还会有人来犯，只怕这回人更多。她自己也披挂上阵，但屋旁这道防线，还得你与她并肩守——那些人折回来，冲的正是她。")
zh(1652,"达芙妮希望达索瑞恩知晓她目前安然无恙。这消息也必须传给她的丈夫，将你提供的保护与仍为她担忧的民众联系起来。")
zh(1653,"乔丹需要知道妻子平安，或许还想要感谢你。带着消息前往一位与圣骑士与信仰密切相关的铁匠，是他与你的相遇。")
zh(1654,"乔丹愿为你锻造一件象征圣骑士功绩的武器。奖励需要你协助收集难以获取的材料，让铁匠的锻造成为你勇气与实践能力的又一考验。")
zh(1655,"食人魔伏击了运送矿石的商队，幸存的守卫后来也死了。找回货物意味着深入他们的领地，将被盗的材料送回锻造炉旁的工作。")
zh(1656,"年轻牛头人难以兼顾父亲的送货任务与力量仪式。背负皮革让他能专心应对试炼。")
zh(1657,"被遗忘者在寒霜节庆祝他们的解放，想要骚扰南海镇的敌人。雅恩卡提供臭弹投掷至城镇中心，警告先遣营地可能引发与联盟的冲突。")
zh(1658,"南海镇需要了解被遗忘者庆祝的规模与可能的挑衅行动。哈特曼寻求侦察兵调查提瑞斯法的庆典，尽管那里的守卫格外凶猛。")
zh(1661,"达索瑞恩认可你作为圣骑士的奉献，愿赠予你一份礼物。目前他不设其他考验，再次与他交谈便可接受他选择赐予的援助。")
zh(1665,"巴特莱比喝完酒后同意交出他的酒杯。将它交给哈里·伯加德，以证明你已履行他先前的要求，方可继续战士训练。")
zh(1666,"你的战斗技巧有所提升，但仍需一把合适的武器。治安官哈迦德保留着职业生涯中获得的装备，若前往艾尔文森林的退休居所拜访，或许能获得帮助。")
zh(1667,"哈迦德将他的旧徽章交给了伪装成同僚的强盗。在提供武器前，他希望你从蛀牙杰克的营地夺回那件失物。")
zh(1678,"你的导师要求你先证明能对抗真正的敌人，方能教授更高深的技巧。维吉雷克是位以坚韧著称的巨魔，他将作为你战士身份的试炼对手。")
zh(1679,"作为战士的承诺，需要一位经验丰富的导师指引。铁炉堡的穆伦能教你更深层的技艺，并助你理解投身战斗生涯的代价。")
zh(1680,"训练必须与合适的武器相匹配。你被送往大锻炉的托姆斯处，他的锻造技艺将助你提升随身装备。")
zh(1681,"袭击铁环营地的事件前，曾有一批奇异矿石运抵。他的弟子渴望复仇，如今希望从被黑铁矮人占据的营地夺回那批矿石。")
zh(1682,"托姆斯提供由铁环营地矿石打造的武器。这场会面让你得以在匠人先前的订单中，挑选一件适合自己的兵器。")
zh(1683,"一个萨特正玷污着一处隐秘的月亮井。终结这个威胁，既可守护水源，也能证明你老师要求的意志，为战士训练的更高阶段做好准备。")
zh(1684,"你的战士之路已走到需要新导师的阶段。艾兰娜瑞能在达纳苏斯为你授课，指引你继续精进专业技能。")
zh(1685,"加科因召你前去继续修习。你须往暴风城一间酒馆的地下室走一趟，地点与行踪都要守口——术士们借用这处地方，本不该叫外人知晓。")
zh(1686,"打造武器需要从沉船中取得艾露尼特。那艘船的前船长因诅咒仍守护着货物，故而获取矿石，需先击败她的幽魂。")
zh(1687,"女管事的故事里说，西部荒野的灯塔有幽灵出没。你照看的孩子想去看看那位船长是否真在那里，请你带他走一趟，还答应一路上都守在你身旁。")
zh(1688,"找回项圈证明了你的能力，但驾驭虚空行者还需另一考验。它的魔法能召唤出怪物，你必须先将其制服，方能学习掌控之术。")
zh(1689,"夺回项圈证明了你的能力，但驾驭虚空行者还需另一考验。它的魔法能召唤出怪物，你必须先将其制服，方能学习掌控之术。")
zh(1690,"游牧民几乎占领了所有水井，威胁着加基森的补给。比格维兹需要他们撤离以恢复水源，将此次行动包装成公司紧急任务。")
zh(1691,"如今夺回水井的关键在于削弱游牧民中更具威胁的势力。比格维兹派你去对付他们的专家，以降低公司日后夺回水源时所面临的阻力。")
zh(1692,"收集的月光石已打包妥当，正等待玛希尔的处理。他的技艺能让回收的矿石化为武器，使你先前的努力在改善装备上获得实际价值。")
zh(1693,"玛希尔为你准备了多种武器，皆以交付的月光石打造。这是一场锻造的交换，核心在于挑选最适合你的装备。")
zh(1698,"犹鲁斯向愿意接受他试炼的联盟战士发出了挑战。你被指引前往湖畔镇的酒馆，了解这场试炼与他承诺的奖励。")
zh(1699,"犹鲁斯的试炼结合了穿越被污染的洞穴与他家族酿造的烈酒效果。完成时限意味着你必须同时承受沿途的豺狼人威胁与他刻意增添的复杂考验。")
zh(1700,"你在打造护甲时学到的技巧或许会引起格瑞曼德的兴趣。将笔记交给他，便是让铁匠们共享知识，尽管他的骄傲可能让他难以接受同僚的教导。")
zh(1701,"弗伦掌握一项打造异常坚硬锁甲的技艺，但需要稀有材料。主动替他获取这些材料，便能为你尝试打造一件装备，延续他已提供的护具。")
zh(1702,"你在街巷中的成功赢得了一项奖励，必须在暴风城获取。一桶麦酒随同请求一并送达，由盾匠完成犹鲁斯的承诺。")
zh(1703,"关于你铠甲锻造的笔记，必须送往达纳苏斯的玛希尔手中。这段旅程不仅传递知识，也让另一位铁匠得以观摩并掌握这门技艺。")
zh(1704,"你锻造铠甲的经验已被记录，交予科罗莫特·钢尺研究。交付笔记，让这位侏儒铁匠知晓新发现，延续匠人之间技艺的交流。")
zh(1705,"格瑞曼德想用弗伦的技法测试另一件铠甲。以狼人部件熔炼实验，他愿将成果赠予协助获取材料之人。")
zh(1706,"格瑞曼德以弗伦技法打造的铠甲，作为委托交付。这场聚会将提供承诺的装备，作为获取实验所需材料的回报。")
zh(1707,"水务公司认为游牧民的补给是偷取自水井。操作员鲁格伦克愿以补给包换取找回的布袋，鼓励冒险者为加基森的水源贡献力量。")
zh(1708,"科罗莫特需要特殊珊瑚来验证弗伦分享的技法。收集它，让实验继续，也让你的协助成为铁匠成果的一部分。")
zh(1709,"科罗莫特以委托所得的护手回报，作为特殊珊瑚实验的成果。这份交接，让收集的材料有了实际用途。")
zh(1710,"玛希尔相信弗伦的技法能提升自己的铠甲研究。用双足飞龙蛋壳作为实验材料，他愿为你额外打造一件成品。")
zh(1711,"玛希尔呈上以翼龙材料打造的护甲，这是他提议与协助提供物资的冒险者共享研究成果后的交换。")
zh(1712,"巴特拉早已等待着能击败塞克隆尼亚的人。收集召唤材料将展现你的战士之力，并尝试获取一颗他承诺锻造成武器的心脏。")
zh(1713,"巴特拉已准备好召唤塞克隆尼亚。直面风之君王，夺取其心脏，因仪式旨在将这股力量用于你战士试炼中承诺的武器。")
zh(1714,"巴特拉的大锅提供了召唤塞克隆尼亚所需的精魄。元素流亡者所赠的阿魅亦是准备之一，将此交换与战士试炼及所求武器紧密相连。")
zh(1715,"诺莫瑞根的主宰被驱逐，麦格尼的审视使术士训练复杂化。你须前往暴风城寻访加科因，他能提供如今在卡兹莫丹难以获得的教导。")
zh(1716,"魅魔需要爱情的标志才能引诱它入世。在尝试掌控之前，你必须向塔卡尔请教，寻找一件适合此目的的物件。")
zh(1717,"加科因在暴风城等你，要接着传你术法。传话的人受命留意你的行踪，也捎来一句提醒：下一课术士的功课，该到时候了。")
zh(1718,"作为战士的声誉让你得以与同途者较量。克兰诺克·马克雷德在岛上集结战士，若他判定你值得，便能继续你的训练。")
zh(1719,"从克兰诺克·马克雷德处学习，需接连战胜对手，最终挑战冠军。这座岛屿的试炼，将考验年轻战士的自信能否经受战斗与时限的考验。")
zh(1738,"两段恋人曾在古战中同死于此树之下，它所承载的爱情或许会引来魅魔，先知塔卡尔指引你前往灰谷遗迹，寻找这棵树的木材。")
zh(1739,"同心树之核可为魅魔开启传送门，你须在召唤法阵中直面这生物，证明心智能抵御它，方能学会如何驾驭它。")
zh(1740,"这颗水晶的碎片仍封存着其中恶魔的力量，收集散落在邪教徒与法师手中的残片，便可重铸此物，恢复其残余之力。")
zh(1758,"召唤地狱猎犬需更复杂的仪式与一部遗失的古籍，克罗姆·粗臂搜集着远古典籍，或许能指引你寻得老师与助祭们所需的知识。")
zh(1778,"约翰正筹划重返暴风城，期盼早日见到斯蒂芬妮。协助他为孤儿院筹备物资后，返回蒂萨继续在光之侍奉中的修行。")
zh(1779,"你下一阶段的试炼，始于生命符记。穆里顿·热炉曾与黑铁矮人激战，险些丧命，他或许能教你如何协助处理此事。")
zh(1780,"斯蒂芬妮将你收集的亚麻布带给孩子们做衣物，她感谢你展现了圣骑士对有需要之人的承诺，返回达索瑞恩继续你的修行。")
zh(1781,"你已展现耐心与慷慨，现在要考验你驾驭圣光的能力。贾森·坦诺姆在对抗迪菲亚兄弟会后受了伤，他会说明需要生命符记的帮助。")
zh(1782,"弗伦承诺以盔甲作为回报，只要你收集到稀有材料。这份交接完成委托，让铁匠的技艺与知识拓展战士的装备。")
zh(1783,"穆里顿与纳姆在调查黑铁矮人时陷入苦战。穆里顿逃走寻求支援，同伴却留了下来。将生命符记带到纳姆处，尝试复活他，实践你对圣光的训练。")
zh(1784,"部分议会成员怀疑黑铁矮人在丹莫罗的势力。书面命令能证明他们的行动，也提供线索揭露他们的计划，这些文件是重要证据。")
zh(1785,"穆里顿指引你回到妻子身边，她以骄傲的目光见证你的行动。与她交谈，延续你对圣光的领悟，感谢你对家族的帮助。")
zh(1786,"贾森从迪菲亚的伏击中脱身，亨兹留下断后，替他挡住了追兵。趁贾森养伤，把生命符记送到岛上他那同伴手中，试着将他唤回人世——这也是你试炼的一环。")
zh(1787,"迪菲亚的文件可能证明他们渗透艾尔文森林，并揭露他们的计划。亨兹无法战斗，因此请你取回文件，并告知贾森他安然无恙。")
zh(1788,"贾森希望达索瑞恩先查看文件，再呈交给国王的谋士。安排这一步骤时，他派你去找指导你训练的导师。")
zh(1789,"蒂萨能提供另一枚生命符记，继续协助穆里顿与纳姆。替换它能确保关键物品在生死攸关的试炼中始终可用。")
zh(1790,"达索瑞恩可提供另一枚生命符记，让你继续协助贾森与亨兹。这件物品能重启一项紧急任务，将你的准备转化为实际力量。")
zh(1791,"你新的战斗姿态需要一把合适的武器。巴特拉精通武器锻造与萨满魔法，拜访这位隐士将助你提升随身装备。")
zh(1792,"巴特拉已握有塞克隆尼亚的心脏，只等把这份力量封进兵刃。交接之时由你挑容器，你为战士修行接下的这桩委托，也到此收尾。")
zh(1793,"你与光的羁绊，需以勇气、守护弱者与坚定信仰来回应。下一项课程将检验这些美德，面对威胁你所守护之地的危险。")
zh(1794,"你与光的羁绊，需以勇气、守护弱者与坚定信仰来回应。下一项课程将检验这些美德，面对威胁你所守护之地的危险。")
zh(1795,"仪式需要协调的召唤法阵与失而复得的书籍内容。你的导师与助祭们已为地狱猎犬准备好了经文，你须谨慎面对。")
zh(1796,"梅纳拉愿协助打造一件强化你的法袍。她首先需要一件裁缝制作的衣物，作为你们合作的基础，再逐步满足后续要求。")
zh(1798,"你的导师想教你召唤地狱猎犬，却缺少必要材料。斯坦哈德可在棘齿城继续授课，你将前往那里开启训练的新阶段。")
zh(1799,"你的训练需选择助祭之路，并获取地狱火宝珠。塔贝萨可助你净化它，因她与梅纳拉有旧日渊源，待你从凄凉之地的术士手中取回后便可。")
zh(1800,"关于洛丹伦覆灭的故事，令你的结界思考荣誉与背叛。孩童渴望前往旧日王座厅，亲眼看看阿尔萨斯杀死父亲的场所。")
zh(1801,"召唤地狱猎犬的仪式需要一本失落之书与多位召唤师协助。约拉精通古籍，可引导你寻找，尽管他如今在幽暗城担任地图绘制者。")
zh(1802,"那本书的唯一副本被分割，各部分散落各地。线索指向半人马与一艘遗失的沿海货船，为继续召唤研究提供一条路径。")
zh(1803,"书页近半已被撕毁，余下部分在运输途中消失无踪。半人马与遗失货船的传闻，为搜集所需文本提供了两条路线。")
zh(1804,"书本已寻回，但仪式还需为斯坦哈德的助祭准备法杖。关于龙喉兽人的线索指引下一次搜寻，学者则请求获得书籍副本。")
zh(1805,"地图绘制者已研究过那本书，并转达斯坦哈德的另一要求。从龙喉兽人处获取导引法杖，将为助祭们参与召唤仪式做好准备。")
zh(1806,"乔丹已备好材料，准备在熔炉前开始锻造。他的技艺旨在助你守护圣光，以他所选之道支持你的冒险。")
zh(1818,"迪林格尔寻觅一位愿在黑暗女爵麾下证明勇气的战士。他的召唤开启了一场与布瑞尔亡灵卫兵的新试炼。")
zh(1819,"被遗忘者未能挣脱切割者奥拉格的巫妖王桎梏。开启他的囚牢并直面他，终结了这场失败的解放尝试。")
zh(1820,"库勒曼·法席恩在你展现勇气后，寻觅一位战士。他的请求将你卷入对抗亡灵的战斗，也寄托着个人的复仇之志。")
zh(1821,"库勒曼将阿加曼德家族视为害死他的元凶。他想夺走他们的家传武器，以剥夺他们最后的荣誉象征。从他们的墓穴夺回遗物，是他复仇的延伸，也将踏入天灾军团的领地。")
zh(1822,"库勒曼保留部分阿加曼德武器，作为苦难的印记，并将另一件交予你。这选择将夺回的遗物与他对家族的怨恨紧紧相连。")
zh(1823,"你作为战士的声望日益增长，或许已准备好接受鲁迦的试炼。你须前往陶拉祖营地寻他，回应他的召唤，以了解他为你准备的挑战。")
zh(1824,"鲁迦对贫瘠之地新出现的昆虫心存疑虑。他的试炼要求你交出仍会颤动的触须，将战斗与速度结合，让样本在他之前抵达，否则将错过时限。")
zh(1825,"你为部落立下的功绩已传至桑德格里姆耳中。这位赫赫有名的铁匠欲为你打造战甲，特命你速赴贫瘠之地的营地。")
zh(1838,"你的声望促使桑德格里姆提出一套战甲。然而打造它需众匠人协作，首件甲胄的材料仍需另派队伍远征寻获。")
zh(1839,"乌拉艾莱克能打你新甲上的那副护手。去森金找他——图恩格里姆的活计，正缺一位愿出手的巨魔铁匠的经验。")
zh(1840,"奥姆的技艺使他成为为你打造头盔的匠人。前往雷霆崖，继续这场为打造新战甲而展开的匠人协作。")
zh(1841,"维罗拉·奈特雷身入亡者之列，手艺却没丢——当年在洛丹伦，她正是凭这本事立身的铠甲匠。找到她，护腿便有了着落，你这一身新甲也就齐了。")
zh(1842,"萨特的蹄足承载着从灰谷抽取的魔力，它们使森林腐化。乌拉埃莱克需这力量打造护手，命你从囤积魔力者手中夺回。")
zh(1843,"乌拉埃莱克将用从萨特身上抽取的魔力打造护手。接受它们，便让搜集的材料与一位视此为荣誉之匠人的工作相连。")
zh(1844,"山谷废墟中一头奇美拉在痛苦与绝望中苟活。直面她，旨在终结这苦难，并向奥姆证明你配得上他答应打造的头盔。")
zh(1845,"奥姆提供与奇美拉试炼相关的头盔。这份交接完成了一项委托，该委托要求在将此件装备交付战士前，需先展示能力。")
zh(1846,"维罗拉需要异常坚固的骨骼来打造你的护腿。龙喉兽人可提供材料，但其强度须先测试，方能交予无法使用脆弱物品的铁匠。")
zh(1847,"维罗拉提供来自委托的护腿，该委托要求坚固的骨骼。此次会面涉及接收此件并检查合身程度，亦可能要求调整铁匠的工作。")
zh(1848,"吞格里姆提供来自一项提案的锁甲，该提案是在听闻你的声望后提出的。这份交接回应了他列明材料的收集努力，以装备一名部落战士。")
zh(1858,"塔赞的帆布袋内物品被复杂锁具保护。他的助手加摩尔或许持有钥匙，悄然取得便可查看内容，而不必强行开启机关。")
zh(1859,"你的战斗与隐秘行动能力已引起注意。瑟祖克在奥格瑞玛有一份邀约，而讯息要求你静默前往，聆听其中内容。")
zh(1860,"法师们需要协助处理关乎暴风城与艾尔文森林安全的任务。詹妮亚掌握详情，正等候你在密室中说明所需协助。")
zh(1861,"魔法冲突已扰乱原本稳定的能量流动。一份明镜湖样本让詹妮亚得以调查，这些变化是否污染了暴风城附近的水源。")
zh(1878,"鲁格伦克仍在以物资包裹交换游牧民族的水囊，这份交接让你能持续为加基森的补给出力，只需将旅途所得的物资交由他处理。")
zh(1879,"彬克有一项任务，她只愿托付给另一名法师。前往铁炉堡拜访她，便可得知这项任务需要你的专业技能，并回应她所下的请求。")
zh(1880,"诺莫瑞根出逃时遗落了一件装置，里头封着浩繁的魔法知识。那处地界已被麻疯侏儒盘踞；若能寻回此物，便为魔法研习保住一件难得的器具。")
zh(1881,"安娜斯塔西娅·哈特威尔有一项任务，正适合你的魔法能力。前往幽暗城与她会面，将开启一段尚未揭晓的使命，继续为她的目标效力。")
zh(1882,"亡灵法师们需测量提瑞斯法的腐化程度。巴尼尔农场的花朵可提供样本，用以研究破坏魔法对当地生命的影响。")
zh(1883,"乌图瓦察觉到杜隆塔尔的魔法流动出现异常。他需要协助解决这个问题，前往他的村庄，既能支持这项工作，也能继续你的魔法训练。")
zh(1884,"扎拉赞恩的仪式扰乱了杜隆塔尔的魔法，腐化了野生动物，并强化了危险生物。摧毁这些仪式，意在阻止其影响，以免魔法的自然流动被永久改变。")
zh(1885,"米奈特·卡加德要求召见。回应他的召唤，将引你走向一项细节尚未揭晓的使命，而此人实在难以忽视。")
zh(1886,"加入死亡猎手需要通过一项危险的任务证明自己。你必须取得信使的个人物品，而你的上司却故意隐瞒了行动的全部缘由。")
zh(1898,"瓦里玛萨斯怀疑安德隆正协助另一组织，想要证据。一封书信能让你伪装成预期的信使，调查那些联系，而不暴露真正目的。")
zh(1899,"安德隆交出了上级们寻找的账本。将它交给米奈特，便能传递收集到的信息，而联系人则建议你处理他们日后安排的任何事务。")
zh(1918,"被击败的元素生物留下泛着光、污浊的水，或许含着湖水污染的线索。将它交给马斯托克，便能找到能解读此线索的人。")
zh(1919,"你对魔法的掌控日益精进，通往更深层的奥秘之路也逐渐展开。詹妮亚有一项任务，能开启这段训练，正等待你在暴风城的法师圣所中。")
zh(1920,"隐形的生物正在酒馆游荡，引发人们担忧法力裂隙已开启。你必须揭露并捕捉它们，调查这场魔法异动，回应詹妮亚的关切。")
zh(1921,"维恩能为你制作法师长袍，但需要合适的材料。亚麻随手可得；带电的宝石则需在洛克莫丹矿坑中矿工留下的箱子中寻找。")
zh(1938,"一位被放逐的法师离别时带走了一部强大的论著。暴风城的法师们希望在他沉迷黑暗魔法、与旧日同伴决裂后，从他的图书馆中取回这部典籍。")
zh(1939,"高阶巫师安多玛斯请求在暴风城的圣所召开会议。回应他的召唤，你将获得一位经验丰富的法师的建议，并了解他此刻能提供的指引。")
zh(1940,"你的功劳，配得上一身与高阶法师相称的衣袍。上等丝线能让维恩裁成此袍，只是丝线得往一片凶险地界的蜘蛛身上去取。")
zh(1941,"维恩将用你收集的材料制成长袍。这件衣物完成你法师训练的裁缝委托，而制作者希望这件衣服能为她的店铺带来名声。")
zh(1942,"维恩为委托提供多款精致丝绸衣物。这场会议将授予你所需的装备，以表彰你在法师训练中提供的协助。")
zh(1943,"迪诺是奥格瑞玛的术士，需要你的协助。她的召唤将引你至她的居所，让你得知她需要完成的使命。")
zh(1944,"萨维亚的水域据说蕴藏强大的魔法之力。从源头取样研究，虽能揭示奥秘，但萨特瑞占据废墟，对外来者充满敌意。")
zh(1945,"你新制的长袍需要灰谷的树灵发丝。将它带到十字路口的裁缝处，让这件衣物成为对你服务与所用材料的表彰。")
zh(1946,"基拉拉将用树灵发丝制成的长袍交付你。这件交付完成迪诺的约定，也保留了所用材料的魔法之力。")
zh(1947,"时机已至，你该获得法师法杖。塔贝萨掌握着指引这项工作的知识，前往塞拉摩西边尘泥沼泽中的隐秘小屋，开始你的旅程。")
zh(1948,"法杖需要稀有材料与能承载强大魔法能量的容器。塔贝萨提供了精确的采集指引，遵循这些步骤是为了避免制造过程中的危险后果。")
zh(1949,"塔贝萨需要《能量仪祭》的篇章来打造你的法杖。因无任何大图书馆藏有此书，你得去找它的作者——他如今只知在赛马场饮酒赌博度日。")
zh(1950,"你寻觅的书卷被一道魔法锁封存，而那句开启咒语已被遗忘。寻找失踪的学徒，或能找回那把钥匙，进而取得继续前行所需的文字。")
zh(1951,"提尔斯将最后一本抄本售出，只为偿还赌债。血色僧侣买下了它，由此指引你前往提瑞斯法修道院的图书馆——那便是它最后的去处。")
zh(1952,"塔贝萨已准备就绪，开始打造法杖。等待她完成仪式，再与她交谈，继续交接后续步骤。")
zh(1953,"你的训练继续以一件强大的魔法器具展开。塔贝萨可为你讲解其制作方式，她正等待在尘泥海湾的小屋中，你须前往取得指引。")
zh(1954,"塔贝萨需要一颗强大的水晶作为起点，尽管火刃氏族的水晶内封印着恶魔。从召唤者手中取来一颗，便能奠定她相信可被净化的基石。")
zh(1955,"塔贝萨能将恶魔从苍穹宝珠中驱逐，但你必须在它重返牢笼前将其摧毁。若不想重复此仪式，准备与速度是关键。")
zh(1956,"苍穹宝珠已摆脱恶魔，但仍需能量来源。塔贝萨指出奥达曼的黑曜石哨兵持有足够强大的能量，但获取它需面对一头强大的生物。")
zh(1957,"塔贝萨将开启法力裂隙，收集充能所需的能量。在裂隙关闭前击败涌出的生物，好让她收集它们释放的力量。")
zh(1958,"塔贝萨呈上完成的苍穹宝珠，并提出另一种选择：将其装上法杖。这件魔法器具如何归属，将由你决定，作为共同工作的终点。")
zh(1959,"幽暗城的法师们察觉到城内有魔法扰动，已请求部落法师协助。安娜斯塔西娅·哈特威尔能解释发生了什么，以及你如何参与调查。")
zh(1960,"隐形的魔法生物正在骚扰奥格诺恩的店铺。让它们现身并捕捉它们，是调查异常活动的一种方式。")
zh(1961,"你的第一件魔法长袍应象征地位与学识。收集充能材料，让裁缝将你的进展转化为可见之物。")
zh(1962,"裁缝们已为你第一套法师装束准备好了长袍。这份交接延续了将衣物作为训练象征的委托。")
zh(1963,"碎手高地意图借暗中行动壮大部落。你的试炼，是取回塔赞的行囊——一位与海盗勾结的商人，他掌握着组织亟需的情报。")
zh(1978,"现已查明，安德隆的接头人是辛迪加。此事须报与瓦里玛萨斯；既然是你揭开了内情，由你送这趟信也最合适。")
zh(1998,"瓦里玛萨斯认为芬维克领导着盘踞森林的亡灵，威胁着被遗忘者。你被指派铲除他，利用死亡追踪者的最新报告，锁定他藏身于湖畔的踪迹。")
zh(1999,"死亡追踪者必须取回肯瑞托关于达拉然的文件。出发前，你需要工具与开锁技巧；艾斯特蕾能提供完成行动所需的装备。")
zh(2038,"宾格斯在坠机后，工具与炸药也被袭击的托格怪夺走。少了这些装备，他为诺莫瑞根的工程无法继续，而你需要找回被偷走的物品。")
zh(2039,"宾格斯尚未从诺莫瑞根的侦查任务中返回。他最后被目击在洛克湖上空，你必须调查这位失踪一周的飞行员究竟遭遇了什么。")
zh(2040,"对诺莫瑞根的地下突袭计划需要更多动力支持挖掘机械。一台地精切割机完整的电源系统，或许能助他们打通周围岩石的通道。")
zh(2041,"舒尼正筹备对诺莫瑞根的地下突袭，需要协助她的挖掘机械。在暴风城的矮人中找到她，你将学会如何支持这场行动。")
zh(2078,"找回的钥匙本可让基尔卡克·旋杆的船副重归效力。船长希望取回他的副手，并打算借这股力量对抗沿岸的鱼人。")
zh(2098,"一艘沉船让基尔卡克失去了船只，也弄断了他的船副钥匙。动物与鱼人将碎片席卷一空，唯有找回这些残片，才能让他的助手重拾运作。")
zh(2118,"一种蔓延的疫病让黑海岸的熊变得狂暴躁动。设下陷阱可暂时安抚它们，让你带回样本，用于研究可能的治愈之法。")
zh(2138,"萨纳瑞恩的疗法失败，病熊依旧伤害森林。他无奈请求摧毁它们，以减少痛苦，却未妄称此举能根治疫病。")
zh(2139,"萨纳瑞恩承认，杀死病兽仅能暂时缓解森林的苦难。他请求你最后一次行动，前往东北方洞穴对付雌蓟熊，希望不必再让你动手。")
zh(2158,"法利的酒馆是旅途休憩的安稳之所。与他相见，便能知晓闪金镇为冒险者提供的补给与支援。")
zh(2159,"黑影谷德鲁伊的职责使送信人无法离开。将草药送至多兰纳尔酒馆，可避免这些义务干扰重要物资的运输。")
zh(2160,"送信人独自穿越山口有危险，而卡拉诺斯正等待补给。将包裹带入你的旅程，可避免漫长延误。")
zh(2161,"乌克尔的食物在试炼谷并无用处，但危险野兽令他不敢重返故地。将食物安全送往剃刀岭，能重新引导补给路线。")
zh(2178,"若你能驯服陆行鸟，便能获得炖陆行鸟的食谱。带回它们的肉，既是能力的证明，也是料理的原料。")
zh(2198,"这串残缺的项链仍显出珍贵的魔法工艺，三颗宝石虽失，却难掩其价值。铁炉堡的印记与刻字，或可指引其创作者与真谛。")
zh(2199,"塔瓦斯德·基瑟尔将财务危机归咎于竞争对手的谣言，他急需银币完成订单。若你能搜集可能助他重振事业的材料，他将透露项链的秘密。")
zh(2200,"塔瓦斯德想修复项链，证明自己的作品并非诅咒所致。缺失的宝石需在奥达曼寻得，那里曾有最后一位佩戴者陨落；一盏魔药瓶将助他与之联系。")
zh(2201,"圣骑士的笔记揭示了散落在奥达曼矮人与地穴人之间的宝石线索。循迹而寻，便可集齐项链组件，并借魔药瓶向塔瓦斯德汇报进展。")
zh(2202,"加卡尔想探究奥达曼新发现的菌类是否具有炼金用途。他需要菌盖作为样本，却警告采集时若惊扰菌群，可能释放致命孢子。")
zh(2203,"若你能用魔法容器采集龙血，加卡尔愿传授他的配方。但提取过程会激怒生物，交换需付出格外危险的代价。")
zh(2204,"修复项链需要一个能量源来恢复其魔力。塔瓦斯德·基瑟尔认为奥达曼最强大的造物或许能提供这个，他需要先找回这件组件才能完成工作。")
zh(2205,"你必须将一个包裹送到军情七处的马迪亚斯手中。指派这项任务的人对你经验存疑，但完成它或许能为你开启与组织合作的第一步。")
zh(2206,"迪菲亚借艾尔文森林的一处渡口，在各境之间转运私货。军情七处要他们的船期，派你混进去取。万一露了行藏，没人会出面认你。")
zh(2218,"你的求职之路引向铁炉堡的盗贼公会。霍格拉尔建议你去找霍夫丹·黑须，他或许能为仍在寻找有用方向的人提供指引与工作。")
zh(2238,"隐秘法阵希望分得为国王开采的财富。奥宁正在诺莫瑞根附近搜集情报，他的报告是这项计划推进的必要条件。")
zh(2239,"奥宁记录下了一辆运货坦克的行驶路线。将他的报告交给霍夫丹，就能掌握下一步行动所需的情报。")
zh(2240,"卡兹穆尔大厅被一道巨大的锁门阻挡。巴尔洛戈知道如何开启它，但他的团队无法继续前行；他的笔记将指引你的探索，之后再向探险者协会汇报。")
zh(2241,"詹诺克无法让塞尤娜接收他的讯息，因此请你送一朵花。你作为潜行者的身份，或许能以其他使者未能达成的方式，尝试与她沟通。")
zh(2242,"塞希尔或许掌握森林异变的线索，但接近他无异于送死。不如潜入搜寻他的遗物，避开已告失败的强攻与谈判。")
zh(2258,"加卡尔急需从荒芜之地的生物身上获取材料，以补足他的炼金储备。他愿付酬金以换取材料，并建议若狩猎过于艰难，不妨带上同伴。")
zh(2259,"艾瑞安·影语需要你立刻前往塞纳里奥区。他急切地催促你行动，至于他想谈何事，留待你亲自到场方知。")
zh(2260,"你的所作所为已引起暴风城情报部门的注意。要加入军情七处的训练，必须踏上艰难旅程，前往城中总部与雷吉克会面。")
zh(2278,"密室中的圆盘记载着泰坦创造土灵的过往。触碰它们时，守卫现身，指引你聆听这段历史，再激活那非凡的记录。")
zh(2279,"再度与圆盘互动，竟在你背包中生成一个微缩复制品。探险者协会研究艾泽拉斯的远古历史，或许能利用这份意外的传承。")
zh(2280,"圆盘生成一个微小复制品，出现在你的物品中。雷霆崖的智者研究艾泽拉斯的历史，他们正是解读这古老知识的合适人选。")
zh(2281,"雷吉克认为你尚未准备好实地作业。卢修斯可助你磨练技艺，因此你被派往湖畔镇码头，与他相见。")
zh(2282,"卢修斯在磨坊设下一只箱子，演练实际的偷窃技巧。取回箱中令牌，将证明你拥有赢得他认可的偷窃技艺。")
zh(2283,"德兰想要一条被圣骑士带往奥达曼的珍贵项链。即便破损，他仍愿支付报酬，因他看重项链上的三颗宝石，确信任何瑕疵都能修复。")
zh(2284,"德兰认为遗失的宝石仍存于奥达曼，遂派你寻找。若圣骑士的遗体尚有线索未被掠夺者察觉，或许能指引宝石的下落。")
zh(2298,"麦格尼的守卫拘捕了隐秘法阵的成员，你的名字在冲突中被提及。霍夫丹建议你离开铁炉堡，前往暴风城的熟人剃刀·雷吉克处寻求协助。")
zh(2299,"霍夫丹一直在寻找你，担心国王可能已将你拘捕。他托人送来讯息，催你返回铁炉堡，听他交代接下来的安排。")
zh(2300,"剃刀·雷吉克在寻找你，而他在军情七处的职位使你尽快回应更为明智。你必须与他会面，方知他为何邀你前来。")
zh(2318,"这本笔记或许藏着你需要的答案，但你无法读懂其中文字。附近卡加斯的居民最可能提供翻译，因此调查必须继续在那里，才能追踪线索。")
zh(2338,"加卡尔想研究项链以复刻其魔力，认为杜佛斯家族无法修复它。他愿为你翻译笔记，若你借出项链碎片协助寻找宝石，二人将保守这份约定的秘密。")
zh(2339,"译文指向宝石，但加卡尔警告项链还需力量。收集碎片，前往奥达曼最强大的构造体处寻找来源，再带着所有修复所需之物返回。")
zh(2340,"加卡尔想测试这股力量，若成功便用宝石换你的项链。他工作时，务必履行与杜佛斯家族的约定，别泄露你与他的私下交易。")
zh(2341,"杜佛斯家族已为交付的战利品争执不休，而你另一桩交易仍在卡加斯未竟。返回加卡尔处，看看他的工作是否成功，以及承诺的报酬是否已备妥。")
zh(2342,"帕特里克想清理家族声望下的蝙蝠窝，也想夺回继承之物。那武器仍存于奥达曼的箱子中，取得它，是他翻身的契机。")
zh(2359,"一批被非人生物守护的货物已抵达塔楼。调查需取得钥匙、查验箱子，让马迪亚斯知晓那些奇特守卫守护的是什么。")
zh(2360,"军情七处侦测到西部荒野废弃塔楼内有大量迪菲亚活动。吉尔妮正监视此地，需向你简报针对这新走私基地的行动。")
zh(2361,"塔瓦斯德为感谢你的帮助，愿以项链换取声誉。他请你散布其制作者之名，并强调此物并无诅咒。")
zh(2378,"你为死亡追猎者效力时展露了欺骗的天赋，但还需更深入的训练。他们的盟友在碎手高地，可通过奥格瑞玛的申苏尔助你精进。")
zh(2379,"单凭决心无法战胜潜伏的危机。赞多赞兹要求你从潜行与偷窃开始训练，这些技能是你承担更大责任前必须掌握的。")
zh(2380,"申苏尔听说你的能力后，已召唤你前往。尽管你的潜行与欺骗仍需磨练，但这趟旅程将带你进入奥格瑞玛的暗影裂口，接受更深层的教导。")
zh(2381,"海盗的宝物是一场危险的试炼，先前的尝试都以失败告终。或许船上的训练区能为你提供练习，再尝试夺取这颗珍宝。")
zh(2382,"赞多赞兹因一些不安的言论，派遣你前往棘齿城寻找维尼克斯。你的任务是见他，弄清他是否能为你安排新的差事。")
zh(2383,"你离家期间，法兰寄来了一张纸条。阅读它并拜访训练师，便能回应他邀请你探讨如何在山谷中成为战士的邀约。")
zh(2398,"黑铁矮人突袭奥达曼的行动来得太突然，部分矮人可能仍被困在通道中。巴尔洛戈带领一队人进入其中，你得查明他们是否还活着。")
zh(2399,"德纳兰种下的蕨类已在花园中生长。靠近它们，或许能采集到他照料已久的这株罕见植物的样本。")
zh(2418,"里格弗兹在奥格瑞姆被矮人囚禁期间，学会了稳定奥达曼的石头。他们取得秘密后将他驱逐，如今他愿为此付出报酬，只要你替他找回两种石头。")
zh(2438,"一枚能汲取翡翠梦境能量的护身符，遗落在星风村的某户人家。熊怪的侵蚀让夺回它变得危险，因此需要你的协助。")
zh(2439,"这些圆盘或许能揭示矮人的魔法起源，值得深入研究。探险者协会开始这项调查的同时，也提供凭证，以奖励将此类发现呈报给协会之人。")
zh(2440,"智者将专注解读这些圆盘，并打算奖励它们的回收。本娜保管着承诺的物品与药剂，当你带着凭证前往雷霆崖找她时便可取用。")
zh(2458,"一名卧底传回了风险投资公司的大动作。接头须对暗号验明你的身份——如此你才拿得到他的情报，又不至于坏了他在组织里多年经营。")
zh(2459,"找回的梦境捕梦者缺少了宝石。菲罗斯塔佩戴着一颗绿光闪烁的项链，或许藏有那颗宝石，因此你必须调查被腐化的神秘学者，并从他们手中夺回被盗的部件。")
zh(2460,"碎手组织以敬礼识别成员。学习并正确复述这一礼节，是成为其暗中行动成员、确立身份的必要准备。")
zh(2478,"毒药已削弱了这座塔楼，为攻占其驻守者制造了机会。目标是夺回赞吉尔的配方，清除加里维克斯，再将证据交予申苏尔，以完成他所监督的行动。")
zh(2479,"影响你的毒药需由希诺特检验，以寻找解药。若你能及时找到他，他的帮助或许还能让你学到制作与使用毒药的技艺。")
zh(2480,"瑟尔格·希诺特对影响你的毒药充满兴趣。研究它或许能帮助他找到解药，同时也能教你如何运用这类毒素。")
zh(2498,"德纳兰自认摸到了林精身上肿物的来由。你得即刻赶回他那里——这场病正啃噬森林，他还需人搭手，才能把根底往下查。")
zh(2499,"一头被巨大肿瘤折磨的冬狼正在湖边扩散腐化。德纳兰需要你清除这处危险源，并回收正在毒害生物的生长物。")
zh(2500,"加克需要荒芜之地的材料来补给他的炼金术品。猎杀那里的野兽与元素生物可获得报酬，若危险超出你的承受范围，建议带上同伴。")
zh(2501,"加克愿分享他的药剂配方，只要你能用魔法容器取得龙血。但这个过程会激怒生物，采集样本将成为一项危险的考验，他才会透露他的知识。")
zh(2518,"萨丝拉曾织出蕴含治愈露珠的丝线，如今却陷入疯狂。她的痛苦不仅威胁着当下，也危及未来世代，女牧师们请求终结她的折磨，并取回她的纺丝器。")
zh(2519,"一头昔日辉煌的森林生物亟需援助，而任务本身充满挑战。阿莫拉能解释该做什么，因此你被指引前去月神神殿与她交谈。")
zh(2520,"萨丝拉的纺丝器必须献给艾露恩，投入神殿的圣水之中。这项仪式旨在净化使她疯狂的腐化，并安息那只巨蜘蛛。")
zh(2521,"库姆·伊沙寻求无暇的德莱尼水晶球，这种水晶如此稀有，德莱尼为此耗费了无数岁月。他在诅咒之地的旅程中，凡能寻获的样本皆可换取丰厚回报。")
zh(2522,"传送门的召唤已然失败，但库姆·伊沙仍抱持希望。他需要另一颗无暇水晶，以延续他的计划，并再次提供赏金，以奖励获取这稀有晶石之人。")
zh(2523,"这朵花已显病态，散发出刺鼻的腐臭，昭示着它的腐化。它亟需照料以恢复常态，毕竟你所发现的植株显然已非健康之躯。")
zh(2541,"一名德鲁伊被熊怪的魔法剥离了肉身。他的躯体仍在攻击探险者，而被囚禁的灵体需检视一枚仪式法器，以探寻如何挣脱束缚。")
zh(2561,"法器揭示了囚徒德鲁伊痛苦的解脱之道。你必须摧毁他的活动躯体，并以仪式物品打破熊怪对他的控制。")
zh(2581,"德拉吉亚曾目睹当地野犬咬穿异常坚固的金属。他想采集多只野犬的样本，以分析其强度，开启对诅咒之地野生动物非凡特性的研究。")
zh(2582,"德拉吉亚提供更多源自野犬的制剂，但警告其增强力量的效力可能影响心智与精神。若你执意再度尝试，他仍需更多原料。")
zh(2583,"德拉吉亚相信当地野猪的耐力使它们免于其他捕食者。他想研究它们的器官与其他材料，以炼制药剂，并由你作为这项研究的第一位实验对象。")
zh(2584,"德拉吉亚声称他的药剂具有成瘾性，以为你再度归来是为了再取一剂。若你能寻得所需材料，他愿继续制作，延续着用动物材料换取药剂的交易。")
zh(2585,"蝎尾兽的敏捷引起了德拉吉亚的注意，他开始思索若能将其捕获用于药剂，或许能发挥某种价值。他需要几种药剂来稳定样本，并承诺让你试用最终成果。")
zh(2586,"德拉吉亚欣喜你安然无恙，以为你仍想获取他的蝎尾兽药剂。他派你去收集另一批材料，好让配方得以再次制作，并再次测试其效果。")
zh(2601,"莱诺雷观察到石化蜥蜴的行为，认为它们拥有非凡的智慧。她需要研究它们的大脑，以及其它材料以寻找解法，意图了解这个在荒芜之地繁衍生息的种族的能力。")
zh(2602,"莱诺雷将你注意力的下降视为进一步研究的契机。她延续之前的交易：更多石化蜥蜴的大脑与秃鹫的砂囊，将能再次制备她的药剂样本。")
zh(2603,"莱诺雷疑惑鱼人如何能在腐尸中觅食而存活。她想分析它们的砂囊，并与其他药剂结合，研究它们对诅咒之地瘟疫的抵抗力。")
zh(2604,"莱诺雷询问药剂的灵体效果持续多久，并允诺若你有兴趣，可再提供一剂。她需要新鲜的砂囊与下巴肉，以继续制作你一同测试的药剂。")
zh(2605,"马林认为沙漠生物的储水腺或许能缓解他的干渴。他需要一份露水收集者的样本，尝试制作能解决他困境的饮品。")
zh(2606,"露水苦得难以入口，马林几乎放弃这个念头。他决定向斯普琳科请教，这位厨师或许能改善风味，于是请你带样本去见她，好让这饮品变得可饮。")
zh(2607,"你的归来不仅带来有用的情报，也牵出一个意外的难题。为寻找解药，你被送往楼下，找一位可能了解你状况的医生，寻求治疗。")
zh(2608,"医生需要你的血液样本才能协助治疗。你必须做好准备，这是判断你虚弱原因的第一步。")
zh(2609,"诊断结果指向一项需要多种材料的疗法。收集这些物品，医生便能准备治疗，同时他建议你在痊愈前避免接触他人。")
zh(2621,"英雄之魂因擅自行动而自责，他迫切想知道上级的指示内容。鲁尔格负责传递密令，询问他或许能解开困扰老兵的谜团。")
zh(2622,"鲁尔格声称鱼人伏击了信使，只留下本戈尔重伤存活。为查明失踪的密令去向，你得听这位幸存者讲述，尽管指挥官警告勿再深入调查。")
zh(2623,"本戈尔记得一名叫沼泽空谈者的鱼人，在伏击中抢走了密令。他的叙述指向东方洞穴；找回文件，英雄之魂便能得到他亟需的答案。")
zh(2641,"斯普琳科知晓一种能改善苦涩的菌菇。要让马林的饮品可口，必须加入这种生长在辛特兰小湖水下的食材。")
zh(2661,"斯普琳科提供了能让麦琳·刀翼饮品更佳的粉末，他认为这是莫大的恩情。将这材料带去，好让他继续调配解渴的药剂。")
zh(2662,"麦琳已准备好将粉末与晨露融合，完善他的魔药。他要求你暂且等待，待他完成调配再继续交谈。")
zh(2681,"英雄之魂的部下被折磨束缚于污染者拉瑟莱克的势力之下。要解救他们，需摧毁支撑他们囚禁的石块，他警告此任务需同伴协助，对抗敌方仆从。")
zh(2701,"旧日英雄们以一件不再需要的遗物，向你表达谢意。他们希望你从箱中取走，用于持续对抗军团的斗争，赋予遗物新的意义。")
zh(2702,"英雄之魂认为你的行为已为他与同伴带来荣耀。他指引你前往桑德，让那些认同你高贵血统的旧日战士们给予你认可。")
zh(2721,"基利斯在与英雄之魂一同被囚禁后仍下落不明。所有人最后听到的，是奥利斯塔实验的惨叫；调查这位意志在酷刑下崩溃的副官，究竟遭遇了什么。")
zh(2741,"克格尔的机器在控制台旁发出嘶嘶声。它接受角鹰兽的蛋，换取一箱货物，这是工程师机械发明中一项特定的交易。")
zh(2742,"林吉失去了武器并被俘虏，无法脱身。他虽料到你们会敌视他，仍乞求援助，并承诺若能安全救出他，便透露藏于悬崖的秘密。")
zh(2743,"基利斯解释说，拉瑟莱克的庇护依赖于三名仆从携带一枚护符的碎片。这些碎片也让他能够被召唤；英雄之魂需要这一发现，为下一步对抗恶魔做好准备。")
zh(2744,"护符碎片使持有者在诅咒之地停留时获得永生。英雄认为洛拉姆斯能帮助突破这层保护，因此派你去找恶魔猎手。")
zh(2745,"调查已牵涉到莱斯科瓦与马尔松，但解决此事需突破法律的桎梏。泰里恩一直在暗中观察城堡中的贵族，或许能协助提亚斯筹备这场行动。")
zh(2746,"泰里恩需加快计划，准备一套能让间谍机器人混入的伪装。丝绸与克拉拉的苹果将提供所需材料，待潜入行动正式启动。")
zh(2747,"克格尔认为在菲拉斯找到如此完好蛋实属罕见。她愿以交换换取这异常的样本，深知极少有回收的蛋能保持这般品质。")
zh(2748,"克格尔说明，在理想条件下，优质蛋可摆脱巨魔的邪恶附魔顺利孵化。她提供交换，让你以这样本换取报酬，而她则负责照料它。")
zh(2749,"普通蛋未必能孵化，尽管克格尔总会悉心照料。她接受回收的样本以换取物资，期盼着关注与好运能给它一线生机。")
zh(2750,"克格尔认定这蛋已无救，注定无法破壳。她仍愿提供补偿，以区别其状态与其他可能存活的样本。")
zh(2751,"奥罗克担忧二十代的配方将随他无嗣而消逝。他渴望传授一位能承继火炉技艺的继承者，而你的青铜锻造，正是延续这匠艺传统的试炼。")
zh(2752,"奥罗克看穿你求知的热忱，却仍需你锤炼更多铁器方能教授铁肩甲。打造青铜武器，将成为你获得家族锻造技艺下阶段课程的必修课。")
zh(2753,"奥罗克的学徒之路仍在继续，纵使熔炉劳作令他疲惫。如今他要求你锻造绿色铁甲，以证明你仍能坚持，方能获得他计划中的最后两课。")
zh(2754,"奥罗克宣布最终的锻造课程，再度要求你以实物证明技艺。铁锤与银饰青铜件，将让家族的锻造技艺得以延续与升华。")
zh(2755,"奥罗克被传承延续的愿景所打动。他仍保留着家族的一段秘密，欲在分享铁拳技艺前，先教你跳一段奥罗克的喜悦之舞。")
zh(2756,"铁砧阿图尔克怀念旧日部族之战，却仍须尊重萨尔所定的和平。你的学习仍在熔炉中延续：他要求你锻造钢甲，方能窥见他战争技艺的奥秘。")
zh(2757,"若要超越基础技艺，前往藏宝海湾寻觅马克迦文。他的徽记将证明你对这位能指引你探索秘银与锻造之道的联系人的承诺。")
zh(2758,"汉克曾承诺教导任何展现渴望与决心之人。如今他要求你打造金鳞护腕，方能传授锻造技艺的起源，以及你所追寻的匠艺真谛。")
zh(2759,"尽管加尔文多年前已离开藏宝海湾，他门派的成员仍在寻找值得收留的学徒。将徽记带到马克迦文处，将证明你的决心，也让寻找那位导师的旅程得以延续。")
zh(2760,"许多新兵从未抵达藏宝海湾，被徽记的价值所诱惑。抵达此处则展现你的诚意，马克迦文便将你送往加尔文，让导师认出信物，你的修行也能继续。")
zh(2761,"加尔文认为采矿与锻造密不可分：一位好匠人必须懂得原材料的本质。他需要一批金属，以验证你的能力，方能教你打造精制秘银短裤。")
zh(2762,"加尔文承认真银的耐用性，却热情捍卫秘银的高贵。他的下一课将两者结合，需提前准备材料，方能揭开精制秘银手套的秘密。")
zh(2763,"加尔文解释黄水晶能增强附魔效果。将它与秘银结合，便是一堂魔法宝石学的课，也让你得以学习精制肩甲的打造。")
zh(2764,"加尔文提议继续由特伦顿指导你的修行，他认为特伦顿是他最出色的弟子。若你已准备好离开他的教导，加基森的铁匠将助你深入精制秘银技艺。")
zh(2765,"加尔文认可你的技艺与为见他而交出珍宝的诚意。他相信对匠艺的信念值得回报，想为你肯定这段成长。")
zh(2766,"另一台机器人坠毁后，装置接收到奥格索普的呼唤。发明家计算出它位于菲拉斯洞穴中，需将信号灯带往那里，才能开始修复机器。")
zh(2767,"奥格索普·奥布诺提斯需要将机器人带到沿海码头，才能让它起飞。他远程操控着它的隐形装置，你得护送它到一处开阔安全之地，让程序开始运作。")
zh(2768,"比格维兹需要他的杆子来寻找新水源，但布莱假借借用之名将它拿走了。他的远征原本在祖尔法拉克寻宝，找回工具意味着找到军士并面对可能的抵抗。")
zh(2769,"铜栓兄弟虽已击败地精，但仍想为他们的车寻求改进。维兹尔需要一种稀有零件用于下一次实验，或许正忙于获取它。")
zh(2770,"维兹尔想将加兹瑞拉鳞片中迸发的能量用于他的赛车。他需要样本，但要面对这头巨兽，得先揭开图尔兹族从圣池召唤它的秘密。")
zh(2771,"特伦顿意识到加尔文曾教每位学徒不同技巧，好让他们共享知识。他提议以你的秘银技艺换取教一顶精制头盔，完成两份学徒的课程。")
zh(2772,"特伦顿归功于结实的靴子赢得先前胜利，如今想为更危险的对手做准备。他需要你的秘银长裤技艺，愿以教他的靴子交换。")
zh(2773,"特伦顿以秘银工艺闻名，却暗中缺少制作某些手套的技巧。他想从你这里学来，愿以最先进知识交换：一套精制秘银胸甲。")
zh(2781,"水公司指控游牧领袖杀害员工并掠夺资源与财产，悬赏其首级以招募冒险者对抗他的袭击。")
zh(2782,"林·吉的石板上刻着尚未能确定价值的符号。奥兰深知枯木之事，或许能解读其中含义，厘清囚犯承诺的秘密是否真值得如此关注。")
zh(2783,"对抗部落只会转移你对诅咒之地潜藏更大威胁的注意。你被要求暂时放下那场纷争，聆听这位部落英雄，他知晓军团在此地的真正力量。")
zh(2784,"这位部落英雄请求你倾听他的故事，从他口中了解自己的过往。")
zh(2801,"在你们的合作能继续之前，这位部落英雄希望你听他讲述，明白他想传达的一切。")
zh(2821,"普拉特坚持皮革品质绝不能妥协。他发现了菲拉斯雪熊厚毛皮的价值，并愿以一件自己的作品，换取这种材料的供应。")
zh(2822,"杉多尔认为自己的工艺需要最高品质的材料。菲拉斯雪熊的厚毛皮尤其令他感兴趣，他愿以任选一件皮革制品，换取任何提供这种材料的人。")
zh(2841,"诺格担心新的侏儒装置已超越他所有切割机的性能。他想要那装置的蓝图，但它们被锁在只有瑟玛普拉格才知密码的保险箱中；若能取得两者，便能揭露对手的技术。")
zh(2842,"新装置的消息促使了直达诺莫瑞根的直接运输计划。斯库提如今能在藏宝海湾接载乘客，为穿越地精山脉的危险旅程提供了另一种选择。")
zh(2843,"前往诺莫瑞根需要一个根据你的体型和重量调整的信号器。斯库提将为你校准设备，使你能在两个方向使用传送平台，不过他仍警告可能会有副作用。")
zh(2844,"沙恩在遗迹中走散了，担心发生了什么。他行动不便，需要你去找回他本该保护的姑娘。")
zh(2845,"沙恩想回到罗克比特，但好奇心让她不断偏离。她总被一个特制铃铛吸引；携带它能帮助你在护送她回朋友的路上保持距离。")
zh(2846,"塔贝萨的宝冠被维蕾萨派来的盗贼夺走。她希望找回这颗宝石，并指引你前往祖尔法拉克，寻找下令偷窃的水占师。")
zh(2847,"普拉特愿教你野葡萄藤的用法，那东西性子霸道，谁也说不准会出什么岔子。细节他暂且不谈，先要一份厚皮作头一笔束脩；往后的功课，还有得你跑。")
zh(2848,"普拉特解释说，蛮皮护肩结合了防护与野葡萄藤的不可预测附魔。他需要一套盔甲组件和植物，作为分享这套工艺的报酬。")
zh(2849,"蛮皮外衣结合了防护框架与野葡萄藤编织的魔力。普拉特要求龟壳装甲组件和一根藤蔓，作为这套装核心部分的工艺图。")
zh(2850,"普拉特描述了一款保护头部却不牺牲舒适度的头盔，同时从野葡萄藤获得可变附魔。传授这套工艺需要其他设计的衣物，以及提供蛮皮力量的植物。")
zh(2851,"普拉特的下堂课讲的是舒适且防护性佳的靴子，柔软的鞋底适合静默移动。他要求完成的衣物与更多野葡萄藤后，才会分享这套野皮制式。")
zh(2852,"普拉特认为你已准备好更复杂的技法：以野葡萄藤魔力强化的坚固裤装。他要求龟壳碎片与更多藤蔓作为交换，才能传授进阶训练的制式。")
zh(2853,"普拉特察觉你已掌握他的课程，理应获得最终制式而无需再劳作。然而他的导师泰龙尼斯必须认可，一封书信将让这位导师在达纳苏斯知晓你的成就。")
zh(2854,"杉多尔愿教导野皮工艺，运用野葡萄藤强大而不可预测的特性。在详解细节前，他需要厚皮作为第一笔学费，以换取后续任务的训练。")
zh(2855,"杉多尔解释野皮护肩结合防护与野葡萄藤的不可预测魔力。他要求一套盔甲与植物作为交换，才能传授利用这些特性的制式。")
zh(2856,"野皮外衣将防护框架与编织野葡萄藤的魔力结合。杉多尔要求龟壳装甲碎片与一根藤蔓，作为这套装束基础制式的交换。")
zh(2857,"杉多尔描述一顶保护头部却不牺牲舒适的头盔，借野葡萄藤获得可变魔力。传授这制式需另一套衣物与提供野皮魔力的植物。")
zh(2858,"杉多尔的下堂课讲的是舒适且防护性佳的靴子，柔软的鞋底适合静默移动。他要求完成的衣物与更多野葡萄藤后，才会分享这套野皮制式。")
zh(2859,"贾恩德认为你已准备好学习更复杂的技巧：由野葡萄藤魔法强化的结实腿铠。他需要龟壳碎片与更多藤蔓，作为换取进阶纹样的交换。")
zh(2860,"贾恩德承认你已掌握他的教导，理应获得最终纹样，无需再费力。不过他的导师乌娜必须同意，一封书信足以让她在雷霆崖承认你的成就。")
zh(2861,"塔贝萨似乎对祖尔法拉克的巨魔心存不满。去找她了解问题所在，若任务牵涉到城市，不妨带些同伴，毕竟这样的行动不应孤军奋战。")
zh(2862,"莫沙彻营地的豺狼人袭击愈演愈烈，哈杜肯担心他们可能迫使居民撤离菲拉斯。他愿以报酬换取你削弱敌军、夺回鬃毛，证明你对营地的守护。")
zh(2863,"哈杜肯要在豺狼人中间掀起乱子：接连除掉它们几个头目。时机须掐得准——几刀要连着落，快得让豺狼人尝到进犯的代价。")
zh(2864,"特兰瑞克迟迟未将承诺的贝壳交付给他的表亲。前往加基森提醒他此事，别让拖延引发的不满，将商业纠纷演变为家族暴力。")
zh(2865,"圣甲虫贝壳对建造如此有用，几乎榨干了当地族群。特兰瑞克知晓祖尔法拉克有座族群，希望你取回完整样本，以维持他的生意。")
zh(2866,"一支庞大的娜迦军团占据古索兰萨尔，却无明确目的。尽管可能预示进攻，珊蒂斯怀疑另有隐情，需要探查废墟，寻找解释他们出现的线索。")
zh(2867,"探索揭示索兰萨尔中心竟有座异样的掺望台。珊蒂斯需要了解这一发现，才能继续调查娜迦的占领，并弄清那些曾被认为毫无意义的废墟中究竟发生了什么。")
zh(2869,"拉托尼库斯担心娜迦终将觊觎这座岛屿，不论他们当前的意图为何。他希望在他们扎根之前削弱其存在，并请求用保存完整的鳞片作为对娜迦发动攻击的证据。")
zh(2870,"斥候探明，沙尔扎鲁是驱使娜迦的贵族之一。他在挖掘中起出了一件古物。拉托尼库斯要掐断他的动作，把物件夺回来，再细究它究竟要紧在何处。")
zh(2871,"拉托尼库斯无法理解这件遗物，便信任维斯提亚的学识来辨识。将物件带给女牧师，她丰富的学术经验或许能解释娜迦当年挖掘时所追寻之物。")
zh(2872,"麦金利等待斯杜雷承诺的那瓶酒，以证明卡利姆多朗姆酒更胜一筹。延迟让他怀疑好友是否畏惧输掉赌注，因此他需要你前去催促交货。")
zh(2873,"斯杜雷的赌局收不了场：库尔戈劫走了他最后一船朗姆。他得从海盗窝里把货夺回，才送得出那瓶许诺的酒，也才能证明他酿的比藏宝海湾的强。")
zh(2874,"斯杜雷提供一瓶朗姆酒以了结与麦金利的争执。将酒瓶带到藏宝海湾，让接收者亲自评判卡利姆多酒的主张。")
zh(2875,"当局通缉安德雷，因其涉嫌危害塔纳利斯的两个地精聚居地。通告授权使用致命武力，并悬赏其首级，允许追捕这名海盗及其同伙。")
zh(2876,"这份文件记载了船只与货物的行踪，以及关于战利品与抵抗的笔记。信息似乎与海上贸易遭袭有关；港口当局需要它来评估路线的危险程度。")
zh(2877,"蛮锤氏族对废弃的隐匿石哨所另有一番打算——那里如今已被淤泥与软泥占满。弗拉加尔要先把这片地方清干净；他也把出手相助看作一道门槛：让族人看清你有几分本事。")
zh(2878,"这朵花蔫头耷脑，散出的味道又冲又臭，腐坏已写在它身上。它需要有人照拂，才有一线回返本来模样的机会：你找到的这株，衰败的痕迹再明白不过。")
zh(2879,"这根法杖可能是开启艾奎尼克斯石碑的关键。测试需用被毁遗址的火焰精魄为其充能；若正确识别，应可通往其中供奉的圣物。")
zh(2880,"弗拉加尔把话说得很硬：蛮锤人只认做出来的事，不认说出口的话。去和这一带的巨魔交手，把他们的项链带回来——你的诚意，得落在这上面。")
zh(2881,"蛮锤人照旧收取项链，拿它当作对抗巨魔的凭据。弗拉加尔把每一次送到都看作交情更近一步；他也替族人把话放下：谁替他们上阵，他们便站在谁一边。")
zh(2882,"一首诗体地图指向热砂港南方海滩埋藏的宝物。它警告需要一把钥匙，而守卫者要求以鲜血为代价，使这场寻宝比单纯的挖掘更加凶险。")
zh(2902,"哈杜肯认为狗头人袭击的协调性暗示存在书面计划。从他们的营地夺回这些计划，或许能解释他们近期的躁动，并据此展开更精准的反击。")
zh(2903,"豺狼人布下的作战计划已被发现。哈杜肯需要这份文件在莫沙彻营地，好让其本人或同伴解读，更清楚地了解威胁营地的活动。")
zh(2904,"克努比挨了一顿打，被黑铁矮人丢在穴居人中间关着。他想逃出去，警告旁人黑铁矮人在那些机械上插了手；你要做的，是把他的一举一动报给藏宝海湾的接头人。")
zh(2922,"尖端机器人从协助侏儒转为在他们的城市中失控游荡。恢复它的记忆核心，或许能让创造者研究被篡改的大脑，找到修复的方法。")
zh(2923,"欧沃斯巴克对尖端机器人出现的故障感到忧心。寻找他将助你尝试修复他的造物，并理解城市陷入灾难时发生了什么。")
zh(2924,"逃离诺莫瑞根时遗落的零件被其工匠广泛使用。新的工作需要大量供应，这将带你进入城市，去回收深藏于设施中的设备。")
zh(2925,"科罗莫特需要协助执行一项危险任务进入诺莫瑞根。他的朋友无法离开职责，因此托你代劳，承诺在污染的旧城中提供对抗危险的帮助。")
zh(2926,"两位发明家认定诺莫瑞根的病害快有解药，只差验证自己的推想。受辐射的穴居人身上落下的尘灰，正好让他们看清自己究竟造出了什么东西。")
zh(2927,"辐射给诺莫瑞根的幸存者带来了个人与集体的后果。诺恩仍希望拯救这座城市，因此派你前往那些正在研究可能应对方式的发明家那里。")
zh(2928,"挖掘舰队缺乏足够的零件抵达丹莫罗。诺莫瑞根的机器人或许能提供所需配件，因此回收它们，便成为将这些机器送往目的地的重要助力。")
zh(2929,"瑟玛普拉格的背叛使侏儒们无家可归，也让他成为废墟之城的统治者。梅卡托克意图夺回诺莫瑞根，并要你铲除这个叛徒，作为这场斗争的一部分。")
zh(2930,"撤离时，关键数据仍留在高安全终端内。要取回它，必须重新获得访问权限，通过卡片与低阶系统，拯救那些侏儒们无法带走的信息。")
zh(2931,"卡斯派普正组织队伍，从诺莫瑞根回收重要信息。与他会面，便能加入一项高安全任务，营救仍被这座充满致命危险的城市所困的数据。")
zh(2932,"尼姆布亚指控枯木背叛了部落，要求以公开警示来惩罚他们。他希望在他们的村庄展示骷髅，插在长矛上，昭示背叛的代价。")
zh(2933,"成堆的绿毒液瓶子说明，这东西对枯木巨魔要紧得很。取一份样，塔伦米尔的药剂师或许会动心；顺着它查下去，也能弄明白巨魔为何囤着这么多。")
zh(2934,"林度恩需要新鲜毒液继续研究。他相信这种毒液来自辛特兰的蜘蛛，且需要完整腺囊尽快送达，否则材料会失去用于研究的鲜度。")
zh(2935,"检测后的蜘蛛毒液比原始样本弱。林度恩希望咨询加德林，因他的知识或许能辨识出另一种生物，正是它提供了他所追寻的物质。")
zh(2936,"加德林解释，最强烈的毒液源自枯木信徒所崇拜的蜘蛛神。召唤她需要她的真名，而这个名字被刻在祖尔法拉克的一块石板上，你必须找到并解读它。")
zh(2937,"羊皮纸让沙德拉能在枯木祭坛被召唤。获取林度恩的样本意味着要直面蜘蛛神并取回她的毒液，继续调查这种异常强大的物质。")
zh(2938,"林度恩的试验查实了一件事：沙德拉的毒液烈得惊人。他要送一份样本去幽暗城，交到法拉尼尔手上——让上司亲自验看它的性味，也把协会的活计接着做下去。")
zh(2939,"特洛亚斯发现了一根看似普通的法杖，但他怀疑其中隐藏着他的书本无法解释的东西。达纳苏斯的一位同僚或许能辨识它，并揭示菲拉斯遗迹中保存的历史。")
zh(2940,"一本旧书似乎包含了特洛亚斯所需的所有信息。在取走之前，先向达蕾恩请示，这样他才能在不侵占他人著作的前提下查阅书页。")
zh(2941,"达蕾恩研究沿海海龟，想观察加莫里塔，但研究工作使她无法远行。克格尔制造了一台影像捕捉装置，为学者提供了无需亲自前往的替代方案。")
zh(2942,"将神器从石碑上移除会让法杖的能量消散。将这两件物品带回特洛亚斯，让艾奎尼克斯的调查得以继续，结合回收的碎片与激活过程中的证据。")
zh(2943,"达蕾恩允许她的书被带到特洛亚斯手中，并嘱咐在途中要小心对待。交付它将把收集到的信息交到那位试图解开法杖之谜的调查者手中。")
zh(2944,"克格尔提供了能捕捉加莫里塔影像的装置，无需移动生物本身。寻找那只巨龟，用相机为达蕾恩带来她研究所需的观察记录。")
zh(2945,"在黑铁矮人身上找到的戒指被污垢覆盖，难以佩戴。珍贵金属与或许一颗宝石在污渍下隐隐发亮；清理它，便能揭晓你所寻回之物。")
zh(2946,"探险者协会怀疑这些圆盘与奥丹姆的城门存在关联，但不知将它们合二为一会引发何事。在那处测试物件，带回观察结果，做好迎接意外反应或无事发生的准备。")
zh(2947,"清理后显现出一枚刻有铁炉堡印记与刻字的魔法戒指。它或许能揭示前任主人或制作者的身份，由你决定是留下它，还是追寻那人。")
zh(2948,"塔瓦斯德认为这戒指设计简单，愿以当前技艺加以改良。他需要银料、绿玉髓与报酬，才能添上一道装饰纹路，因他的材料已告罄。")
zh(2949,"清理后的戒指蕴含魔力，旁侧刻有奥格瑞玛的印记与未完成的铭文。铭文或许能指向主人或工匠；你可以保留宝石，或选择追寻那线索。")
zh(2950,"诺格赞赏有关黑铁矮人的信息，愿无偿改良戒指却不声称所有权。若以银料与绿玉髓为材料，便能增强戒指的魔力，换你提供物资与报酬。")
zh(2951,"一台机器承诺以小额报酬恢复污垢物件的光泽。它的说明提供了一个机会，让你在抵抗诺莫瑞根周边疯狂与毁灭的幸存者中，尝试这项服务。")
zh(2952,"机器在处理完脏物后，送出一个裹着的盒子。拾取它，便能检视清洁服务的结果，却还不知盒中藏了什么。")
zh(2953,"机器等待下一个沾满污垢的物件与报酬，才肯开始运作。再次使用它的服务，或许能揭开尘土下隐藏的秘密。")
zh(2954,"守卫者拒绝没有缺失护甲的访客。他的现身是对奥丹姆实验的回应，但你得先弄清他的用途，才能继续调查祭坛。")
zh(2962,"第一份样本不够纯净，实验仍需更强烈辐射的尘埃。从其他生物身上获取它，才能继续测试，但容器或难承受这材料。")
zh(2963,"探险者协会正在研究奥达曼回收的圆盘，认为已有进展。卡尼克发现了守卫之谷的线索，需将它们与最初发现联系起来。")
zh(2964,"唯有找到奥丹姆的护甲，调查才能继续。在追寻新线索的同时，麦格拉斯需要一份报告，并感谢你的协助，维持合作直到制定出具体计划。")
zh(2965,"奥达曼的发现让纳拉的经历显得与下一步息息相关。智者希望你向德鲁伊请教她前往守卫之谷的旅程，探索与圆盘可能的关联。")
zh(2966,"纳拉与智者想测试圆盘是否与奥丹姆的门有关。他们不知是否会有反应，也不知如何触发。调查时务必谨慎，带回所知的一切。")
zh(2967,"与凝视者交手后，祭坛会将圆盘归还给你。纳拉需要知晓所学内容，以便雷霆崖的调查能在奥丹姆新设的进入条件中继续推进。")
zh(2968,"若不知晓奥丹姆圣殿的位置，调查已陷入僵局。纳拉将继续寻找突破口，并希望智者知晓此事；他亦想向你致谢，肯定你在发现中的作用。")
zh(2969,"恐怖图腾囚禁着发光龙，用途尚不可知。辛达尔无法独自解救，需同伴协助打开囚笼，护送它们逃亡，以免掠夺者部队被迫撤退。")
zh(2970,"杰尔·凯与辛达尔希望在营救后主动出击，对恐怖图腾营地发起联合攻击，造成更多损失，再返回他们的据点重整。")
zh(2972,"两名侦察员难以给予丰厚回报，却不愿你的协助被忽视。杰尔·凯以一枚戒指为证，呈给泰兰德，让她知晓他们安然无恙，并在你的名下记上一笔。")
zh(2973,"克鲁伊格想为伴侣织制一件缀满发光龙羽翼的斗篷。他需在莫沙彻附近搜集材料，为柯林准备一件符合她爱穿新衣品味的衣物。")
zh(2974,"克鲁伊格对恐怖图腾的出现感兴趣，因贝尔戈洛姆曾悬赏通缉他们。他请你重返族群，带回龙角作为证据，并警告你这些敌人不可轻视。")
zh(2975,"罗克认定戈杜尼人盘踞菲拉斯是一桩祸事，更怕他们再往外伸手。她要先挫掉北面那处据点，截住这股势头，也把话挑明：这片土地不认他们的号令。")
zh(2976,"克鲁伊格承认提及赏金，并决定以报酬回报你的付出。他将角送至贝尔戈洛姆，对方渴望你的观察记录，并愿为恐怖图腾的踪迹提供奖励。")
zh(2977,"与奥丹姆凝视者交手后，石台归还了圆盘。将所获情报带回卡尼克，让探险者协会解读发现，继续追查古老遗迹的入口。")
zh(2978,"一份沾污的卷轴似乎描绘了戈杜尼的集会或仪式。罗克或许能理解其对食人魔的意义，因此将文件交予她，莫要过早下定论。")
zh(2979,"罗克解读卷轴，认为这是由法师领主主导的黑暗仪式筹备。她需要一枚他们的宝珠，以研究其中蕴含的力量，并更深入理解仪式与戈杜尼魔法。")
zh(2980,"罗克如今派你对抗占据暗夜精灵遗迹的戈杜尼。她希望减少这些食人魔对受损土地的侵占，并警告你，这些巨魔比以往面对的更为强大。")
zh(2981,"戈杜尼在菲拉斯势力日益壮大，贝尔戈洛姆担忧他们将威胁部落的据点。罗克从莫沙彻获知局势，能说明如何阻止他们的扩张。")
zh(2982,"安吉拉斯为特洛亚斯揪着心——他独自闯进食人魔盘踞的废墟。她要把那一带清得安稳些，好让同伴接着查探；挡他路的那些东西，还得你出手。")
zh(2983,"你在训练中的耐心，已为你做好面对元素试炼的准备。卡纳尔能在贫瘠之地教你火的奥秘，你须在他现身前，直面那股力量的召唤。")
zh(2984,"你历经磨练的耐心，已为你准备好另一场元素试炼。卡纳尔能在贫瘠之地教你掌控火焰，你须先找到他，方能直面这股力量的召唤。")
zh(2985,"你的萨满学识已进入水元素的新阶段。伊斯伦能指引你理解水之奥秘，你须前往贫瘠之地海岸，寻访她的钓鱼小屋。")
zh(2986,"你的萨满学识已进入水元素的新阶段。伊斯伦能指引你理解水之奥秘，你须前往贫瘠之地海岸，寻访她的钓鱼小屋。")
zh(2987,"奥尔文听闻戈杜尼族将矿石埋藏以作守护。他借你一把铁锹，前往他们的据点搜寻钴矿，蓝光将揭示隐藏的矿脉。")
zh(2988,"沙普比克在与父母狩猎时失踪，沙拉克·鹰斧怀疑是巨魔所为。前往枯木村的笼子中搜寻，看看是否关押着这位最强狮鹫的继承者。")
zh(2989,"沙普比克未在枯木村现身。沙拉克·鹰斧如今怀疑是邪枝族所掳，他遣你前往祖尔祭坛，搜寻那头年轻的狮鹫。")
zh(2990,"沙拉克·鹰斧希望萨迪斯用魔法，以沙普比克巢穴的羽毛寻得他。将羽毛带往守望堡，那里有占星师在离开鹰巢山追寻黑暗知识后定居。")
zh(2991,"萨迪斯同意寻找狮鹫，但首先要求一枚徽章供他研究。耐克鲁姆在祖尔法拉克持有它；取回它，方能换取占星师协助寻觅沙普比克。")
zh(2992,"萨迪斯要借占卜牵出羽毛与它主人之间那根线。仪式需要一片空场；他也提醒你：万一出了岔子，最好别睁眼看。")
zh(2993,"占卜将沙普比克关入金塔拉·阿洛笼中，并识别出海克斯是钥匙的保管者。沙拉克·鹰斧需要这些信息，好为营救做好准备。")
zh(2994,"沙普比克必须从邪枝领地的笼中被释放。沙拉克·鹰斧请你前往金塔拉·阿洛的山巅，从海克斯手中取走钥匙，救出这只幼年狮鹫。")
zh(2995,"奥兰要断了这一带高等精灵结盟的路子，也不许他们把巨魔的底细互通。他们的信札都收在奎尔丹尼尔；烧掉那些文书，正要结起的那张网便散了。")
zh(2996,"你的召唤术学习现在需要另一位导师。斯坦哈德掌握更高级的知识，住在棘齿城；寻找他能让训练继续，而他的实力不应仅凭外表判断。")
zh(2997,"蒂萨·热炉引导年轻圣骑士深入了解光之恩赐与他们的责任。前往铁炉堡寻她，能让你的训练超越现有服务的范畴。")
zh(2998,"达索瑞恩对你的进境颇为称许，说是考验你的时候到了。去大教堂见他，圣骑士接下来的功课就在那里。")
zh(2999,"蒂萨·热炉引导年轻圣骑士深入了解光之恩赐与他们的责任。前往铁炉堡寻她，能让你的训练超越现有服务的范畴。")
zh(3000,"蒂萨·热炉教导年轻圣骑士们关于圣光与职责的知识。在铁炉堡寻找她，能使你的训练延续至你已奉献给他人之外的领域。")
zh(3001,"你的召唤术研究如今需要另一位导师。斯坦哈德·法尔杉掌握更深入的知识，他住在棘齿城；寻找他，能使你的训练继续由一位不以外表评判实力的人引导。")
zh(3002,"罗克知晓她的敌人，却缺乏理解戈杜尼宝珠的魔法知识。将它带到奥格瑞玛的乌特尔奈，调查它的力量与它与仪式的关联。")
zh(3022,"克格尔需要送往艾瑞拉斯·琥珀的蛋，由这位德鲁伊照料至孵化，并训练年轻的角鹰兽幼崽。将木箱带到鲁特瑟兰，便能将它们交予负责照料之人。")
zh(3042,"特伦顿能使用巨魔的淬炼剂，且知晓行家视其为珍品。他愿以报酬换取由沙怒在祖尔法拉克产出的这种材料。")
zh(3062,"塔罗称艾丹娜为被仇恨吞噬的鹰身人女王，想要她的真心。他听说号角能引她至遗迹中的石块，使你得以与旧敌首领正面交锋。")
zh(3063,"一次鹰身人伏击彻底改变了塔罗的一生，他险些丧命。那记忆仍萦绕心头，如今他托你袭击北泉，以偿多年积怨。")
zh(3065,"你处理第一项职责时，法兰的邀请已抵达。召唤你前往试炼谷，继续你的战士训练。")
zh(3082,"你初入行时，詹·沙恩送来邀请。召唤你前往试炼谷，接受猎人训练。")
zh(3083,"你初入行时，鲁瓦格送来邀请。召唤你前往试炼谷，接受潜行者训练。")
zh(3084,"你初入行时，史克里克送来邀请。召唤你前往试炼谷，接受萨满祭司训练。")
zh(3085,"你初入行时，肯·佳伊送来邀请。召唤你前往试炼谷，接受牧师训练。")
zh(3086,"你初入行时，梅·艾赫送来邀请。召唤你前往试炼谷，接受法师训练。")
zh(3087,"你初入行时，詹·沙恩送来邀请。召唤你前往试炼谷，接受猎人训练。")
zh(3088,"你初入行时，鲁瓦格送来邀请。召唤你前往试炼谷，接受潜行者训练。")
zh(3089,"你初入行时，史克里克送来邀请。召唤你前往试炼谷，接受萨满祭司训练。")
zh(3090,"你初入行时，纳托克送来邀请。召唤你前往试炼谷，开启术士的修行。")
zh(3091,"有人带着哈鲁特的信物寻你而来。召唤你前往纳拉其营地，踏上战士的征途。")
zh(3092,"有人带着兰卡的信物寻你而来。召唤你前往红云台地，踏上猎人的征途。")
zh(3093,"有人带着米拉的信物寻你而来。召唤你前往纳拉其营地，踏上萨满的修行。")
zh(3094,"有人带着加尔特的信物寻你而来。召唤你前往纳拉其营地，踏上德鲁伊的修行。")
zh(3095,"达纳尔的讯息将你初战天灾的战绩与战士训练相连。回应他的召唤，开启专属你的修行之路。")
zh(3096,"大卫·提亚斯召唤你现身。与他会面，学习潜行术，助你初入亡灵阵营时游刃有余。")
zh(3097,"杜斯坦的讯息指引你的牧师修行。完成对天灾的首次战斗后，他将助你掌握精神之力。")
zh(3098,"伊莎贝拉希望开始你的法师训练。她的信件将你早年在丧钟镇的经历，与掌控魔法所需的纪律联系在一起。")
zh(3099,"马克希米林希望引导你的术士训练。他的信件将课程指导与你作为亡灵的第一项任务并行展开。")
zh(3100,"莱尼·拜舍尔的信在等你从狗头人营地归来。召唤令将你引向北郡修道院，开始战士的训练。")
zh(3101,"萨缪尔修士的信在等你从狗头人营地归来。召唤令将你引向北郡修道院，开始圣骑士的训练。")
zh(3102,"乔里克的信在等你从狗头人营地归来。召唤令将你引向北郡修道院，开始潜行者的训练。")
zh(3103,"女牧师安妮塔的信在等你从狗头人营地归来。召唤令将你引向北郡修道院，开始牧师的训练。")
zh(3104,"凯尔登的信在等你从狗头人营地归来。召唤令将你引向北郡修道院，开始法师的训练。")
zh(3105,"杜希拉的信在等你从狗头人营地归来。召唤令将你引向北郡修道院，开始术士的训练。")
zh(3106,"初入行时，索兰·库尔曼捎来讯息，召唤你前往安威玛尔，接受战士的训练。")
zh(3107,"初入行时，布罗姆斯·墨菲捎来讯息，召唤你前往安威玛尔，接受圣骑士的训练。")
zh(3108,"初入行时，索加斯·格瑞姆森捎来讯息，召唤你前往安威玛尔，接受猎人的训练。")
zh(3109,"初入行时，索姆·哈格林捎来讯息，召唤你前往安威玛尔，接受潜行者的训练。")
zh(3110,"初入行时，布兰斯托克·卡德尔捎来讯息，召唤你前往安威玛尔，接受牧师的训练。")
zh(3111,"符文指引你前往安威玛尔，继续与玛瑞克·斯托纳尔研习魔法。他将魔法视作工具与武器，却也强调正道不可偏移：学习需兼具判断与力量。")
zh(3112,"初入行时，索兰·库尔曼捎来讯息，召唤你前往安威玛尔，接受战士的训练。")
zh(3113,"初入行时，索姆·哈格林捎来讯息，召唤你前往安威玛尔，接受潜行者的训练。")
zh(3114,"玛瑞克·斯托纳尔在你初入行时送来讯息，召唤你前往安威玛尔，接受法师的训练。")
zh(3115,"阿拉玛尔·格里姆在你初入行时送来讯息，召唤你前往安威玛尔，接受术士的训练。")
zh(3116,"奥莉希亚送来邀请，召唤你前往幽影谷，接受战士的训练。")
zh(3117,"阿亚娜·远途送来邀请，召唤你前往奥达希尔，接受猎人的训练。")
zh(3118,"弗拉胡恩·影语者送来邀请，召唤你前往幽影谷，接受潜行者的训练。")
zh(3119,"珊达送来邀请，召唤你前往奥达希尔，接受牧师的训练。")
zh(3120,"玛丹特·硬木送来邀请，召唤你前往奥达希尔，接受德鲁伊的训练。")
zh(3121,"乌策尔·伊需要尼尔鲁·火刃准备药材，而他尚未愿解释用途。他以皱缩的头颅作为报酬，并派你前往奥格瑞玛完成交易。")
zh(3122,"尼尔鲁·火刃接受皱缩的头颅作为报酬，并提供了约定的草药。将它们带到菲拉斯的乌泽里处，让他能开始交换材料与仪式物品的工作。")
zh(3123,"乌泽里想测试他的仪式与你使用灵魂精华容器的能力。他让你去捕捉即将消散的野性兽人，以此检验准备好的物品之力。")
zh(3124,"乌泽里认为你已能捕捉角鹰兽灵体，这些曾是暗夜精灵的忠实伙伴。他想借灵魂精华容器保存它们的坚定本性，必须在灵体消散前使用。")
zh(3125,"精灵龙脆弱的外表下，藏着乌泽里想驾驭的强大灵体。捕捉它，让部落能借助曾作为暗夜精灵盟友的生物之力。")
zh(3126,"乌泽里将树人视为暗夜精灵对抗部落的守护者。他想捕捉它们的灵魂精华，借其力量延续仪式，延续对灵体的保存工作。")
zh(3127,"乌泽里的最终目标是山岭巨人，他们以协助暗夜精灵对抗军团而闻名。他想借灵魂精华驾驭他们的巨大力量，这需要你面对庞然大物。")
zh(3128,"乌泽里的计划不仅需要灵体，也需实物材料。这些可在同一场猎捕中获取，从多种生物身上取得木材、矿石等材料，完成他的仪式。")
zh(3129,"乌泽里已备齐材料与灵体，准备为武器施加魔力。这个过程艰难，你需等待他将捕捉到的生物之力融入他正在准备的装备之中。")
zh(3130,"珊蒂斯必须在不暴露要塞的情况下评估纳迦的威胁。拉托尼库斯密切注视着他们的兵力，能在她权衡应对之策时引导你的协助，以保障更广泛的防御。")
zh(3141,"洛拉姆斯认为若你打算对抗恶魔，了解他的故事或许能助你一臂之力。在继续之前，他邀请你亲自聆听他的亲身经历。")
zh(3161,"玛尔冯渴望更多以古巨魔为模样的饰品，供研究之用。他发明了一种探测器，将科学好奇与寻宝热情结合，助他完成搜寻。")
zh(3181,"玛尔戈的角上挂着一把断掉的斧头，刻着贝波蒂蒂的名字，但当你试图取下时，金属却碎裂了。将这件战利品带给她，即使失去了辨识的证据，也要呈现你的发现。")
zh(3182,"贝波蒂不信那角是真货——她的斧子至今不见踪影。索里奥斯馆长能验它，也能为你的事迹作证；凭这份凭证，她才肯交出开启灼热峡谷的钥匙。")
zh(3201,"索里奥斯馆长接受这角作为珍贵的博物馆展品，并准备一份认证你事迹的文件。将它带给贝波蒂蒂，以解除她对战利品的疑虑，并获得她所需的认可。")
zh(3221,"伦弗利尔想与你讨论你送来的狼心。在协助死亡猎手后，调查仍在继续，尽管他的信息尚未透露调查结果。")
zh(3261,"你当前的指导阶段已结束，必须由另一位导师继续。乔恩·星眼在陶拉祖营地等待，将引导你进入这初步教学阶段之后的学习。")
zh(3281,"迅猛龙仍紧握着他们偷来的银币，即便此前曾与他们交战。报告指出它们的巢穴位于棘齿城以南，你必须在那里寻找失踪的货物。")
zh(3301,"茉拉一边替垂死的森林续命，一边为被遗忘者奔走。贫瘠之地那些奇形怪状的贝壳或许藏着线索，她要一份样本细看。")
zh(3321,"特伦顿认为你的坚持证明你属于锻造之序。他想以一件与你训练开端有关的物品作为奖励，只是需要一点时间来完成，以表彰你的努力。")
zh(3341,"奎尔博尔与天灾军团结盟，听从巫妖王亚门纳尔的命令。安德鲁想切断他与奈祖尔的精神联系，唯有消灭这位统治者，才能阻止他操控新仆从的行动。")
zh(3361,"辐射散落，侏儒们四散奔逃，一名难民连随身家当也丢了个干净。巨魔顺走了他的工具，他孤身一人讨不回来——他本就不是冒险者。")
zh(3362,"特兰’瑞克想进入山谷，却不愿在植物生物如此众多时冒险。他需要减少它们的出现，才能考虑重返，你的帮助便是开辟险地的途径。")
zh(3363,"歌花病恹恹的，散发出刺鼻的异味。腐化侵蚀了这株植物，若想恢复自然状态，它亟需照料。")
zh(3364,"滚烫的饮品必须在冷却前送到德南手中。往常的送递者因另一趟运送延误，你需要迅速完成这段路程，以挽救这场时间紧迫的差事。")
zh(3365,"这杯酒已为你带来温暖，如今空杯需物归原主。德南请你将容器带回主人诺里斯手中，完成这最后的善举。")
zh(3366,"一块绿色碎片在你眼前浮现，表面似有烟雾流动，却令人心生不安。前往棘齿城寻求建议，是理解这神秘发现的第一步。")
zh(3367,"杜瑞奥斯伤得很重，只怕已经内出血。他头晕目眩，浑身发软，想回铁炉堡却挪不动脚——眼下这副身子，撑不起这趟路，得有人搭把手。")
zh(3368,"杜瑞奥斯的信件请求他的兄弟释放被苏塔拉石奴役的挖掘者。信中描述了被迫劳作以完成奥比斯顿的惨状，将这讯息带给索里奥斯馆长，便是考古学家最后的遗愿。")
zh(3369,"碎片中蕴含翡翠梦境的本源，但幻象却如梦魇般令人不安。将它交给哈穆尔，让这位智者解读这令人困扰的发现。")
zh(3370,"碎片的幻象展现的尽是噩梦，而非梦境。一位经验丰富的德鲁伊需解读这令人不安的本源，因此你将前往达纳苏斯，将发现托付给玛斯雷·驭熊者。")
zh(3371,"杜瑞奥斯的死令索里奥斯下定决心完成他的最后心愿。返回灼热峡谷，寻找被囚禁的考古学家，并寻求解救他们的方式。")
zh(3372,"那些石头迫使考古学家即便在死后仍要劳作。祭坛或许能带来解脱，但需夺取被暮光之锤守护的圣物。找回它，便有机会终结这些囚徒的枷锁。")
zh(3373,"伊兰尼库斯寻求援助，因腐化正扭曲他与梦境的联结。他将自身的一部分封入宝石，希望将它带到巢穴的泉眼，以净化心灵、寻得安宁。")
zh(3374,"誓言石传递了伊萨里奥斯协助绿色巨龙时代救赎伊兰尼库斯的提议。第一项承诺要求交出封存他自由意志的宝石，并接受将付出更多代价的工作。")
zh(3375,"塔瓦斯德手头没有多余的窥视药水，需材料制作替代品。获取这些材料将恢复维持联络的工具，以延续你们未竟调查的联系。")
zh(3376,"昆比兽族持续在峡谷的首领指挥下对牛头人故土发动战争。对抗他们的领袖，旨在终结此前努力未能阻止的威胁。")
zh(3377,"萨麦尔请求你的帮助，想向你讲述自己的故事。倾听，是了解他所求的第一步。")
zh(3378,"萨麦尔希望找回刻有祈祷文的黄金圣物，并带往阿斯塔利。尽管他行过残酷之事，信仰已回归，他仍渴望让祈祷被听见，哪怕不期待宽恕。")
zh(3379,"尼莉丝担忧盗猎者会摧毁为她工艺提供珍贵丝线的蜘蛛族群。她希望在造成永久伤害前制止他们的滥杀，并派你前往峡谷寻找这群人。")
zh(3380,"关于一座被驱逐至地下的神殿的传说，提及了被远古邪恶腐化的孤立灵体。玛尔冯研究过许多遗迹，或许能提供调查那片知之甚少之地的线索。")
zh(3381,"萨纳斯掌控着通往主人的道路，对未经考验的访客嗤之以鼻。他要求提供角鹰兽羽毛，方能接纳会面，遵循指示，只接纳值得信赖的冒险者。")
zh(3382,"水妖在船员寻找安全锚地时发动袭击，他们已成功撤离一次。梵妮莎不清楚他们意图，但需要保护船员与乘客，同时派出斥候以防再次突袭。")
zh(3385,"尼莉丝谴责在峡谷内与黑铁勾结的商人。她希望摧毁他们的行动，除掉考维克与科朗克，并找回商人的布袋，作为警告上级的证据。")
zh(3402,"尼莉丝希望亲自将考维克的失败告知维兹格里克。她认为此举足以让黑铁领主对商人痛下杀手，并奖励你的介入，因此派你前往加基森传达消息。")
zh(3421,"尼瑞尔在你拜访塔楼后，提供返程的协助。他的解释是，营地侍神者的粗鲁是习惯，而非针对你个人。")
zh(3441,"卡拉然邀请你聆听他的故事，亲自从他口中了解他想讲述的一切。")
zh(3442,"卡拉然希望焚毁瞭望塔，以开启攻势，趁守卫尚未反应。他需要由石像鬼与元素生物打造的火炬，其火焰将协调这场突袭。")
zh(3443,"火炬需要一根能承载特殊火焰的杆子。卡拉然计划重铸黑铁奴隶贩子使用的魔能武器，借合金的强度打造这把工具。")
zh(3444,"玛尔冯记得神殿里有一间毒蛇雕像的密室，还发现了一块刻着相似符号的石头。若能从他的车间找回这块石头，就能与记忆比对，进一步探索那危险之地。")
zh(3445,"安吉拉斯听闻一座神殿曾被非凡力量沉入水底，认为玛尔冯能讲述它的历史。这位学者前往塔纳利斯的遗迹，你须寻他继续调查那地下的神龛。")
zh(3446,"玛尔冯在一组雕像的密室下发现了一座祭坛，触发了陷阱。他相信这祭坛藏着谜题的关键，需要将找回的石头带往那里，探究它在神殿中的作用。")
zh(3447,"玛尔冯怀疑祭坛的灯光揭示了雕像密室中的秘密。他想弄清这些灯光的含义，却警告说任何神殿珍宝，都可能被那里的邪恶力量守护。")
zh(3448,"探险者协会要到艾萨拉去，从精灵的遗迹里翻找他们失落的过往——那片土地如今凶险得很。泰摩尔愿意相助，也会指点你如何接着探下去，在这文明的残骸里寻一个答案。")
zh(3449,"艾尔达拉特的遗迹保存着古代法师用符文传递奥术发现的痕迹。泰摩尔想要拓印研究，并提供必要装备，同时警告说其他人也对这个遗址的知识感兴趣。")
zh(3450,"泰摩尔希望将符文拓印空运，而非一路携带至他的塔楼。希格斯可以安排收集，并在艾萨拉的作业完成后，提供信号枪协助寻找你。")
zh(3451,"希格斯同意协助泰摩尔，并在艾萨拉的岛屿上设有一处降落点。他提供了一种信号方式，用于收集探险队的物资，待一切准备就绪后协调运输。")
zh(3452,"火炬需要魔法外壳来封印火焰。卡拉然认为暮光锤的宗教图腾或许能提供合适的附魔，他打算从供奉拉格纳罗斯的图腾上提取。")
zh(3453,"卡拉然已备齐所需部件，必须结合附魔完成火炬。他请你稍等，他正完成这件旨在焚毁黑铁防御的工具。")
zh(3454,"火炬已备妥，但仍需与使用者绑定。卡拉然请你接过它，完成这道契约，再继续对望塔的计划。")
zh(3461,"西格斯并未支付报酬，反叫你去找铁炉堡的泰摩尔。归程也容你将探险所得的拓印送回，重置绘图工具包。")
zh(3462,"卡拉然希望使者说明火炬的使用方式。玛特拉克能提供指引，将魔法工具转化为攻击望塔的下一步。")
zh(3463,"望塔无法摧毁，但不灭之火可阻其占据。玛特拉克希望以这种方式瘫痪第一道防线，需你进入每个哨所，以火炬点燃。")
zh(3481,"箱子看似锁着。尝试开启或可窥探箱内所藏。")
zh(3483,"西格斯可再提供一具信号枪，供你在艾萨拉收集。他提醒你用它轰击南方小岛——如今已改作降落点，保持运输协调的通道。")
zh(3501,"库姆·伊莎承认，残缺的碎片恐怕难以助他重返家园，但它们仍可能为德拉诺人所用。他悬赏那些在诅咒之地探索中发现的较不特别的碎片。")
zh(3502,"库姆·伊莎继续接受残缺的碎片，以换取他存货中的物品。他认为这对他而言是减少无用之物，对你而言则是获得奖励，双方皆有所得。")
zh(3503,"萨纳斯奉命允许访客见他的主人，但不需再施加旧日的限制。尽管他抱怨嘲讽，却仍愿载你前往塔楼，只要你愿接受这次拜访。")
zh(3504,"贝尔戈洛姆指控一名血精灵杀害了前来保护她的战士，他渴望复仇，却无法再派士兵；阿格·托尔知晓内情，必须将书信交予他。")
zh(3505,"阿格·托尔指控雷姆托里摧毁了前来保护她的远征队。他希望同伴们由你手刃血精灵营地，并寻得足以引出法师的证据。")
zh(3506,"这本书将一块水晶与雷姆托里相连，其他则与更危险的力量有关。摧毁正确的那块，或许能引出她的回应，创造与被指控杀害兽人战士的法师对峙的机会。")
zh(3507,"阿格·托尔希望贝尔戈洛姆亲眼见到雷姆托里的头颅，了解事情的真相。他派你返回奥格瑞玛，结束对法师的行动，而幸存者则准备自己的归途。")
zh(3508,"洛拉姆斯答应帮你破掉护住拉瑟莱克仆从的屏障，只是他觉得你这趟太过鲁莽。他先要行一场仪式，求取所需的知识，之后才谈得上寻找神器、锻造能伤到它们的兵器。")
zh(3509,"一柄刻有恶魔真名的武器或可令拉瑟莱克及其仆从暴露破绽。洛拉姆斯派你去见亚考罗克，警告他的追随者危险万分，这知识恐怕要付出代价。")
zh(3510,"亚考罗克指控赫塔拉杀害了他的子嗣，并拒绝她统治海洋的宣称。他提供你追寻的真名与另一项关键援助，条件是你消灭她并带回她的头颅。")
zh(3511,"亚考罗克揭示了拉瑟莱克的真名，并准备血液以淬炼武器。将二者带回洛拉姆斯，融合所需知识与材料，打造一件对抗恶魔与守护者的利器。")
zh(3512,"伊兰尼库斯介于沉睡与死亡之间，困于梦魇之中。伊萨里奥斯希望借宝石建立联系，认为冬泉谷的灵语者阿姆布兰希或许能协助，尽管巨龙并未真正死去。")
zh(3513,"这卷轴看似官方文件，或许会吸引那些在精灵边境附近窥视的目光。将它送往哨站，可先解读其中信息，待其含义或重要性揭晓前便有所准备。")
zh(3514,"卷轴指出一名树妖正通过部落领地派遣斥候。你被指派阻止她，并插上旗帜作为警告，确立其守卫者未来希望尊重的边界。")
zh(3517,"杰迪加利用她在艾萨拉的职位，在废墟中搜寻有价值之物。她需要与古代上层精灵法师有关的石板在解释下阶段交易前被寻回。")
zh(3518,"玛加萨声称一块石板或许能帮助亡灵恢复人性。作为联盟支持者，她希望其中知识能建立有用联系；杰迪加则希望得到这件物品以延续他们的交易。")
zh(3519,"埃沃隆被蜘蛛咬伤，毒液侵体，头晕目眩。他需要你去通知迪兰妮亚·月光，她或许能提供他无法亲自寻觅的帮助。")
zh(3520,"耶赫金亚追寻他视为与远古神祇有关的鸟类灵体。他提供一根法杖，可揭示亡者本质，并承诺在你带回样本后，进一步解释其中的关联。")
zh(3521,"迪兰妮亚知晓一种解毒剂，或许能救埃沃隆，但所需材料仍未齐全。必须采集植物与来自毒蜘蛛的物质，方能配制良药。")
zh(3522,"埃沃隆的解毒剂已备齐，但效力只能维持数分钟。你下一项任务必须迅速完成，好让他在毒液侵蚀前饮下。")
zh(3523,"奔尼斯特拉兹解释，天灾军团与奎尔博尔达成了交易，他的囚禁正是这场噩梦的一部分。他不愿只逃亡，而是希望你承诺行动，对抗正在发生的邪恶。")
zh(3524,"黑海岸沿岸越来越多的海洋生物搁浅而亡。温尼斯为月光神殿调查此事，但鱼人阻碍她的研究。她需要一具搁浅生物的骸骨，才能继续研究。")
zh(3525,"奎尔博尔用雕像吞噬俘虏。奔尼斯特拉兹可通过仪式使其失效，但届时他将毫无防备。你需护送并保护他，直到他阻止雕像的进一步使用。")
zh(3526,"地精工程学专精爆炸物与非凡机械。手册指引你前往尼克斯·踢轮学习，但警告你，加入后将永久归属此门派，无法再涉足其他领域，抉择需谨慎。")
zh(3527,"摩什·阿鲁的预言记载了如何封印哈卡的本源，分刻在两块石板上。耶赫·金雅需要从祖尔·法拉克取回这两块石板，以实现其目的，而守护者们则各自保管着其中一部分。")
zh(3528,"耶赫·金雅希望将哈卡的化身本源封入一枚准备好的蛋中。仪式需要诱使它现身于神殿，击败其仆从，熄灭束缚之焰，方能直面化身。")
zh(3541,"杰迪加有一位隐秘买家，愿出高价收购一块石板。杰斯·里蒙在奥格瑞玛等待这笔交易，但买卖必须保密；泄露任何一方的行踪都会损害双方的利益。")
zh(3542,"幽暗城的法师们想通过召唤术士的石板研究上层精灵的法术。安德隆是杰迪加交付石板的联系人，必须在他返回领取报酬前收到石板。")
zh(3561,"杰迪加认为克希雷姆是个危险人物，不敢询问他最终石板的用途。将石板交给他的塔楼，借助萨纳斯的帮助，以他声名所要求的谨慎态度接近买家。")
zh(3562,"玛加萨对石板感到满意，会在杰迪加返回时准备好报酬。她留下一封信传达此意，标志着这件遗物交付完毕，并请求中介尽快前来。")
zh(3563,"杰斯·里蒙觉得这笔买卖划算，要杰迪加回奥格瑞玛领赏。把这封信带给她，信上写明她这份活计已经了结——买卖还得做下去，往后兴许还用得上你。")
zh(3564,"安德隆在收到石板后，为杰迪加留下一封信。将买家的讯息带给艾萨拉，继续完成中介安排的交易流程。")
zh(3565,"大法师克希雷姆回应了杰迪加的报酬问题。将信件带回艾萨拉，结束塔楼之行，却未窥见大法师对石板的意图。")
zh(3566,"解救俘虏的尝试落入圈套。最后的请求是除掉黑衣拉索里克与奥比斯顿，并带证据给索里奥斯馆长，回应那些摧毁他兄弟远征的人。")
zh(3567,"玛里提供搭乘巨型雕像前往顶端的交通工具，只为一览众山小。旅程只到登顶，至于如何下来，还得你自行思量。")
zh(3568,"瑟尔萨·风歌在与娜迦战斗后饮用海岸水池，不料染病。科雷想查明水中所含之物，需采集数个水池样本，查明病因。")
zh(3569,"科雷为瑟尔萨配制了药剂，却不知能否缓解她的病痛。将药剂带给她，唯有她服下后，方知疗效如何。")
zh(3570,"科雷感谢你的协助，准备继续研究收集的样本。他期盼这项研究能为希尔瓦娜斯与亡灵带来帮助，剩余材料仍待进一步分析。")
zh(3601,"金杰尔指责雇佣他的血精灵背叛他，企图杀害他。他逃出生天，却遗失了装备，需从他们的营地取回，以弥补部分背叛之痛。")
zh(3602,"洛拉姆斯需要艾萨拉石打造武器本体，并说明巨人们在吞食岩石后会产出此石。他的猎犬能寻得隐藏矿脉，协助获取这种强韧晶体，尽管其生产者力大无穷。")
zh(3621,"准备就绪的艾萨拉石需要一位能驾驭恶魔能量的铁匠，将其锻造成武器。洛拉姆斯派遣你前往荆棘谷的加尔文处，那里能依照你的需求打造装备，并完成对恶魔的准备。")
zh(3625,"加尔文已准备好打造武器，但其削弱之力需精准时机方能发挥。他需要时间完成锻造，并警告你此武器对拉瑟莱克及其仆从的效力时长可能不一。")
zh(3626,"武器准备妥当，返回英雄之魂获取下一项任务。此次拜访将协调新获力量在对抗拉瑟莱克及其仆从的战役中的运用。")
zh(3627,"率先抵达拉瑟莱克处，需先破除其三名仆从之力，并取回他们的项链。这加持过的武器可削弱他们，使必要部件得以组装，以对抗守护他们的恶魔。")
zh(3628,"项链可通往拉瑟莱克的巢穴，并借其祭坛召唤出他。英雄命你直面恶魔，带回象征希望的证据，同时取回结界以防止其被滥用。")
zh(3629,"导师半信半疑地展示地精专精，侧重爆炸物。他仍提供前往尼克斯的指引，警告你加入后将永久归属，且无法学习其他工程学分支。")
zh(3630,"侏儒专精主张建造改善生活的装置。指引你前往欧沃斯巴克学习，警告你加入后将永久归属，且无法接触地精分支。")
zh(3631,"斯坦哈德认为你已准备好与他对话，尽管你的导师对此判决持异议。召唤令要求你尽快前往棘齿城上方的塔楼，聆听他托付之事。")
zh(3632,"侏儒的专精在于打造改善生活的装置。手册指引你前往欧沃斯巴克学习，但提醒你一旦加入便不可逆转，将永久失去地精专精。")
zh(3633,"地精工程学提供爆炸与奇械的专精方向。手册指引你前往尼克斯学习，但警告你一旦加入便无法再回归其他专精，抉择需谨慎。")
zh(3634,"导师轻视侏儒的发明，却将他们的专精视为另一种选择。若你选择，欧沃斯巴克可引导你入门；手册警告，一旦加入便无法再回归地精专精。")
zh(3635,"导师轻视侏儒的发明，却将他们的专精视为另一种选择。若你选择，奥格索普可引导你入门；手册警告，一旦加入便无法再回归地精专精。")
zh(3636,"本尼迪塔斯认为，昆莱兽与天灾军团的结盟已使亚门纳尔成为联盟的威胁。他希望终结这股力量，先消灭如今统治此地的尸妖，再引导他的新盟友。")
zh(3637,"导师轻视侏儒的发明，却将他们的专精视为另一种选择。若你选择，奥格索普可引导你入门；手册警告，一旦加入便无法再回归地精专精。")
zh(3638,"尼克斯说，地精的学问由一道终身守密的誓言护着。要走这条路，先想清楚：应下这份誓，舍掉另一门专精，再落笔签名，把话定死。")
zh(3639,"尼克斯希望检视你的作品，借以调整你的技巧，使之符合地精工程学。一组爆炸物将展示你的能力，随后他将发放通往专精导师的通行证。")
zh(3640,"欧沃斯巴克解释，侏儒工程学通过永久保密誓言守护其技术蓝图。签署即表明你选择遵循这门技艺，摒弃地精的替代方案，因此他劝你慎重考虑后再做决定。")
zh(3641,"欧沃斯巴克希望分析你的作品样本，以引导你的技艺朝侏儒工程学发展。提供装置与零件，可展现你的能力，待你获得通行卡后，方能接触专精训练师。")
zh(3642,"奥格索普·奥布诺提斯解释，侏儒工程学通过永久保密誓言守护其技术蓝图。签署即表明你选择遵循这门技艺，摒弃地精的替代方案，因此他劝你慎重考虑后再做决定。")
zh(3643,"奥格索普·奥布诺提斯希望分析你的作品样本，以引导你的技艺朝侏儒工程学发展。提供装置与零件，可展现你的能力，待你获得通行卡后，方能接触专精训练师。")
zh(3644,"尼克斯愿在支付费用后，为你更新地精工程学通行卡。新卡延续对训练师技术蓝图的访问权限，延续你已在专精领域建立的会员身份。")
zh(3645,"奥格索普·奥布诺提斯愿在支付费用后，为你更新侏儒工程学通行卡。新卡延续对训练师技术蓝图的访问权限，延续你已在专精领域建立的会员身份。")
zh(3646,"瓦萨里奥·林克格雷斯愿在支付费用后，为你更新地精工程学通行卡。新卡延续对训练师技术蓝图的访问权限，延续你已在专精领域建立的会员身份。")
zh(3647,"欧沃斯巴克愿在支付费用后，为你更新侏儒工程学通行卡。新卡延续对训练师技术蓝图的访问权限，延续你已在专精领域建立的会员身份。")
zh(3661,"艾瑞拉斯想调查一个传说：艾露恩创造了野性之灵。它们的天性兼具温顺与狂暴，而辛特兰的羽毛或许能证明这些传言是否属实。")
zh(3681,"暴风城召唤圣骑士继续修行。你的进展暗示该是研读典籍的时候了，达索瑞恩正等待在大教堂，指引你下一步。")
zh(3701,"索瑞森的遗迹藏有揭示其历史的遗物。阿克瑟努斯需要你将它们检视，并带回发现，尽管暗杀者仍守护着埋藏在遗址中的秘密。")
zh(3702,"阿克瑟努斯讲述黑铁矮人的简史。聆听这段内容，便能透过皇家历史学家的研究，了解索瑞森的过往。")
zh(3721,"奥格索普想以一个迷你版的机器人，感谢你找回他的三个机器人。他赠予你一只战斗与归巢机制皆被禁用的机械小鸡，作为你救援的纪念。")
zh(3741,"希拉里在钓鱼时弄丢了项链，朋友们认为它掉入湖中。他们的父母禁止在湖中游泳，因那里潜伏着危险的生物，所以他们需要你的帮助。")
zh(3761,"塞纳里奥议会听说乌特加德的土壤蕴含强大魔力。他们需要足够数量继续研究，因此派遣你采集地面与生物身上的样本。")
zh(3762,"塞纳里奥议会寻求有经验的冒险者参与一项重要研究。尽管信使不知详情，但哈穆尔领导这项工作，他将在雷霆崖解释你如何协助。")
zh(3763,"达纳苏斯的塞纳里奥议会正寻找有经验的冒险者参与重要研究。范达尔主持这项计划，若你想贡献更多，不妨去找他详谈。")
zh(3764,"范达尔想验证关于乌戈罗土壤魔力的传言。他需要高质量的样本继续研究，便指派耶纳尔接收，认为采集是研究不可或缺的一环。")
zh(3765,"戈沙拉在黑海岸需要援助，他的兄弟已前往暴风城寻找能提供帮助的冒险者。前往奥伯丁的长途旅程，需要有人愿意承担。")
zh(3781,"在乌戈罗土壤中种植的种子能产出强大草药，其中一种的特性仍成谜。范达尔想深入调查，便赐你种子凭证，好让你参与研究。")
zh(3782,"在乌戈罗土壤中培育的作物产出了一种神秘草药，哈穆尔希望塞纳里奥议会能理解其奥秘。他的女儿巴珊娜将提供种子凭证，让你协助培育研究样本。")
zh(3783,"尤米想给朋友一个机械雪人惊喜，证明她也能发明非凡之物。她需要当地雪人的厚毛，以开始塑造她的秘密计划。")
zh(3784,"塞纳里奥议会正寻找有经验的冒险者参与一项重要研究。虽然信使不知详情，但哈穆尔主持这项工作，他可在雷霆崖说明你如何协助。")
zh(3785,"玛斯雷准备了一个布袋，用乌戈罗土壤作肥料培育种子。他需要将产出的草药带回继续研究，亲自处理运送，以免打扰忙碌的高等精灵大德鲁伊。")
zh(3786,"巴珊娜·符文图腾备好一个布袋，用乌特加德的土壤作肥料，培育种子。她需要将产出的草药带回继续研究，亲自处理交付，以免打扰忙碌的鹿盔大德鲁伊。")
zh(3787,"奎恩提斯希望与你讨论为塞纳里奥议会培育的草药。他特别叮嘱，谈话内容须对鹿盔大德鲁伊保密，以强调他的研究需要同事间罕见的谨慎。")
zh(3788,"奎恩提斯希望与你讨论为塞纳里奥议会培育的草药。他特别叮嘱，谈话内容须对鹿盔大德鲁伊保密，以强调他的研究需要同事间罕见的谨慎。")
zh(3789,"达纳苏斯的塞纳里奥议会正寻找有经验的冒险者参与重要研究。范达尔·鹿盔主持这项计划，若你有意提供进一步协助，可向他咨询具体需求。")
zh(3790,"达纳苏斯的塞纳里奥议会正寻找有经验的冒险者参与重要研究。范达尔·鹿盔主持这项计划，若你有意提供进一步协助，可向他咨询具体需求。")
zh(3791,"奎恩提斯疑心范达尔借议会之力另有所图。他专研诅咒，早听说这草药在某些情形下会生出古怪的性气，眼下正缺样本，好再往下查。")
zh(3792,"奎恩提斯尽管对草药的存在感到不安，仍继续调查。他接受更多样本以维持研究，决心厘清其特性，哪怕过程日益令人不适。")
zh(3801,"弗兰克罗恩·铸铁，这位石建筑巨匠，正急需协助他的诅咒之城。他以一把通往地底的钥匙为报酬，并邀请你聆听获得此奖励所需完成的工程。")
zh(3802,"弗兰克罗恩希望夺回他的重型钉锤，交还至达纳苏斯为他竖立的雕像。将钉锤置于雕像之上，便可开启暗格，使武器免受他人觊觎。")
zh(3803,"森林之灵需要更多草药供法阵研究使用。玛斯雷·驭熊者维持着物资交换，让研究能持续获得你培育的成果。")
zh(3804,"哈穆尔的乌戈罗计划仍需更多培育草药。巴珊娜·符文图腾接受物资交换，协调样本采集，让研究得以继续。")
zh(3821,"莎妮与小队在调查食人魔仪式时失踪。她的丈夫无法离岗，拒绝在真相不明前放弃她，唯有你前往燃烧平原查明究竟。")
zh(3822,"莎妮的灵体描述了克罗姆·格鲁尔对她的折磨与婚戒的掠夺。她渴望惩罚食人魔，将珠宝归还塔尔·特拉克，寄托着来生重逢的希望。")
zh(3823,"奥拉留斯认为食人魔通过守护矿脉与补给线支持黑石兽人。他希望在敌人之前发动突袭，削弱联盟的本地力量。")
zh(3824,"奥拉留，想借食人魔撤退之机，对戈尔·特什发动决定性打击。他需要首领的头颅推进下一步计划，警告你那头目正藏身于兽人盟友的据点中。")
zh(3825,"奥拉留斯已将戈尔·特什的头颅悬于长矛之上，欲展示于巨槌石。他相信此举能让食人魔退却，尽管他的举动暗示期望未必可靠。")
zh(3841,"侦察兵救下了巢穴，却未能挽救母兽。他们将一枚精龙的蛋托付予你照料，奎恩丁此刻可向你解释这枚蛋即将破壳所需的一切。")
zh(3842,"奎恩丁认为蛋已近破壳，希望在继续前确保它的安全。他需要一些药水完成一个小法术，而所需材料已齐备，足以照料这未来的小宠物。")
zh(3843,"蛋还脆得很，孵出来之前得懂行的人照看。奎恩丁打发你去鹰巢山找阿格纳，催你脚程快些——幼崽离了妥帖照料，撑不了多久。")
zh(3844,"池塘边的残破木筏藏着谜团：水量似乎不足以造成事故。探索它或许能揭开主人的身份，以及船只为何会在此处。")
zh(3845,"从水中打捞出的包裹或许藏有线索。检查其中物品，并向避难所的旅人打听，能继续调查木筏之谜，找到失主的财物。")
zh(3861,"一只鸡正用爪子在泥土上刻画熟悉的地名，它的异常举动引人探究其需求，尽管讯息尚未完全明了。")
zh(3881,"威利德的远征低估了乌格罗的危险，逃亡途中遗失物资。找回食物与装备，能让这个屡遭灾祸的项目在更严酷的环境中得以延续。")
zh(3882,"远征队要恐龙骨头做研究，可挖掘场里活物成群。斯巴克提议直接从那些活物身上取骨，省去在凶险地里刨土的工夫。")
zh(3883,"远征队想弄清楚格里什虫族为何似乎与乌特加德的生态格格不入。霍兰妮需要从它们孵化地附近采集样本，即便灾难中断了先前的研究，也要继续这项调查。")
zh(3884,"破损的日记指认威尔利德是主人，记载了他远征队撤往高地的情景。若记载属实，前往陨石坑北方搜寻，或许能找回他遗失的页数。")
zh(3901,"最初的任务已展现你的潜力。如今面对更强大的天灾敌人，将考验你在压力下的应对能力，同时削弱威胁丧钟镇的势力。")
zh(3902,"丧钟镇预期会有更多亡灵苏醒，亟需装备他们。回收被遗弃的物资，能为新加入的成员提供保护，让他们顺利融入社群。")
zh(3903,"你的可靠表现赢得了一项推荐，协助米莉解决工作上的困难。在她马车旁找到她，便能了解现状，提供她所需的支持。")
zh(3904,"迪菲亚的占领威胁着米莉的葡萄，即便守卫赶走了强盗，损失仍难以挽回。从葡萄园回收容器，旨在阻止收成被偷或践踏。")
zh(3905,"收成已得保无虞，需在北郡的物资中如实登记。将货物清单带给尼尔斯修士，让他知晓葡萄已可供应修道院的储藏。")
zh(3906,"长老们察觉到由黑铁召唤的灵体引发的元素异动，担忧无尽干旱的来临。他们希望铲除派隆，以终结威胁家园的失衡。")
zh(3907,"腐化之力如今指向黑石深处的伊森迪奥斯，但元素之力却认定他不过是另一股力量的使者。找到他，获取可能揭示其主子藏身之处的信息。")
zh(3908,"林克不记得自己是如何抵达火山口的，但他清楚自己的剑需要淬炼。他知道多诺瓦·雪山能在温泉中锻造它，因此托你将剑送去，而他则努力回忆自己的使命。")
zh(3909,"多诺瓦·雪山能推动剑的锻造，但完成它需要联系一位难以接近之人。一种特殊药剂是关键；格雷甘·山酒知晓如何获取，必须前往菲拉斯寻找。")
zh(3911,"报告指出黑铁地精巨人之力源自独特能量源。研究旨在获取这种本质，用于制造憎恶，提供报酬以换取从深渊中回收的样本。")
zh(3912,"药剂将让加里杨以不可能的方式现身并被交谈。多诺瓦·雪山托你携剑前往加基森墓地，用它施展仪式，寻找能完成锻造的联系人。")
zh(3913,"加里杨指向一座奇特墓碑，暗示其下埋藏秘密。返回墓地查验，顺着这条线索继续追寻与林克之剑相连的旅程。")
zh(3914,"一道闪光改变了剑的形态，使其再次可被取用。将剑带回火山口，完成这场锻造之旅，帮助林克重拾被遗忘的使命。")
zh(3921,"回收的装置似乎在其他地精对其产生兴趣前就已经损坏。温妮·布特巴克拥有好奇与技艺，若将它带到她的营地，或许能尝试修复。")
zh(3922,"维妮想要修复机器，却已用尽精华材料。风险投资公司藏有合适的零件，你必须先取来，才能让她继续工作。")
zh(3923,"修复尝试失败，添加零件反而可能让装置更糟。雷里熟稔风险投资公司的技术，提出另一种恢复其运作的可能。")
zh(3924,"雷里需要装置的说明书才能动手修理。一位旧日对手曾守护其中秘密，并将资料分发给亲信，因此恢复所需知识，或许意味着收集散落的片段。")
zh(3941,"林克仍在回想为何来到无畏山。他相信自己曾向珍妮·D透露过什么，因此请你就此查探，看她是否还记得关于他旅程的线索。")
zh(3942,"珍妮·D记得林克曾提及制作图腾，并向费伍德的艾瑞丹请教。如今他难以解释，寻求德鲁伊的帮助，或许能还原项目的初衷。")
zh(3961,"珍妮·D意识到林克前来是为了对抗火焰使者，她希望图腾能唤醒他的记忆。将它带给他，尝试恢复那些因失忆而未竟的使命。")
zh(3962,"林克忆起自己的任务：阻止火焰使者，并夺取一件威力惊人的神器。他相信你如今必须完成它，借助图腾，寻找盟友，对抗掌管邪恶之力的守护者。")
zh(3981,"一封信被人硬塞过来，画着戈尔·沙克身陷牢笼的模样，落款是他的签名。这或许是圈套，贾拉玛弗仍要搜一搜黑石的牢狱，探明那位指挥官是否还活着。")
zh(3982,"戈什卡声称自己被捕是为了收集情报，他透露铁炉堡的公主正在城中。守卫打断了谈话，你必须在调查继续前为指挥官辩护。")
zh(4001,"戈什卡希望审问卡兰，以获取更多关于公主及其俘虏者的情报。萨尔希望将她安全送回铁炉堡，并需要一份能让他提前准备干预的报告。")
zh(4002,"萨尔认为帮助矮人是一次改善部落未来关系的机会。他想解释一项他视为对联盟以及其后果世代至关重要的任务。")
zh(4003,"萨尔相信索瑞森用法术控制了公主，要求处决皇帝以救出她。他警告她将在对峙中发动攻击，但下令确保预定的营救目标安然无恙。")
zh(4004,"茉艾拉指控你们的远征杀了她丈夫，并宣称她的孩子将继承铁炉堡。在你质疑那道法术的余波时，萨尔需要她的回应以理解干预带来的意外结果。")
zh(4005,"唯有亚奎门塔斯才能将收集的材料转化为对抗火焰使者的图腾。从塔纳利斯的石环召唤他，并在过程中留在其中，尽管元素生物会引发敌意反应。")
zh(4021,"科卡尔已派出增援部队为他们的失败复仇，正向部落防线推进。抵抗这场突袭并对抗他们的战酋，旨在终结这片贫瘠之地的威胁。")
zh(4022,"赛勒斯知道你在峡谷的所作所为，要求查看从卡拉然处得到的蜕躯。呈上它将回应他的要求，延续通过具体证据证明你先前参与的飞行联系。")
zh(4023,"赛勒斯要求你证明自身价值，才能继续接触这个族群。他对你的态度透露出不信任，若想继续与他打交道，就必须接受这场考验。")
zh(4024,"赛勒斯渴望黑石的烈焰，想要一部分巴尔·加尔的内核之火。若能改变他的蜕皮，便能从遗骸中提取精华，而巨人的败亡，便是满足这份渴望的代价。")
zh(4041,"若你能为格雷甘寻得他所需的根茎，他便能炼制视灵药剂。这份提议提供了一条继续推进剑之工作的途径，借助他引以为傲的草药与炼金知识。")
zh(4061,"峡谷里那些机械，多半是从燃烧平原或黑石运来的。西多拉要取它们元素造物的碎片，顺藤摸出打造之处，好弄清这新祸患的来路。")
zh(4062,"这些残片带有初号和军阶标记，或许能辨识创作者身份。鲁特维尔专精元素科学，需要样本解读这些符号，继续追查机械的来历。")
zh(4063,"鲁特维尔担心阿格曼奇幸存下来，继续扭曲他的研究。他需要造物样本，并想在黑石处除掉其制造者，试图阻止他认定与旧敌相关的生产。")
zh(4081,"高图斯指控怒炉的部队屠杀了一支远征军。他提供赏金，只要摧毁黑石防线的首批守军，警告这些士兵的残暴，令攻击必须格外谨慎。")
zh(4082,"斥候已探明黑铁头目的落脚处——他们在黑石深处操练兵马，矛头直指卡加斯。高图斯下令攻打这些据点，凡能削弱敌军臂膀的，皆有赏。")
zh(4083,"鬼魂之杯缓缓浮起，动作缓慢如心跳。献祭需要收集红宝石与珍贵金属，放入悬空的容器之中。")
zh(4084,"艾瑞丹识破火焰使者是被邪恶庇护的存在，需特殊力量才能战胜。她可教你如何面对他，但首先需要费伍德生物的材料来准备所需援助。")
zh(4101,"阿拉珊蒂丝懂得如何净化植物，但须见你以行动证明决心，方能分享她的帮助。她需要元素生物的树液，那些她视为无救的生物，以研究腐蚀并寻找拯救费伍德生命的方法。")
zh(4102,"梅贝丝懂得如何净化植物，但须见你以行动证明决心，方能分享她的帮助。她需要元素生物的树液，那些她视为无救的生物，以研究腐蚀并寻找拯救费伍德生命的方法。")
zh(4103,"信号灯揭示了被污染的灵魂碎片，散落在死去的野兽身上。这些残骸可提炼成塞纳里奥植物药膏的材料，交出它们将获得用于恢复病株的药剂。")
zh(4104,"信号灯揭示费伍德矿脉中被污染的硫酸盐。净化可将部分腐蚀转化为有用的药膏原料，换取用于救治森林病株的准备材料。")
zh(4105,"携带信号灯的采药人能识别污染费伍德植物的魔藤。研究可净化其毒素，使其成为药膏原料，收集便是为受感染植被准备治疗的一部分。")
zh(4106,"信号灯揭示在费伍德剥皮时发现的被污染皮毛。看似无用，却可制成塞纳里奥植物药膏的原料，交出它们将获得用于救治病株的准备材料。")
zh(4107,"提炼物品所得的精华可作为植物药膏的原料。无需信号灯：少量精华便足以炼制多份药剂，持续净化工作。")
zh(4108,"信号灯可揭示被击杀野兽体内被污染的灵魂碎片。这些残骸可提炼成植物药膏原料，交出后将获得用于救治病株的药剂。")
zh(4109,"信号灯可揭示费伍德矿脉中被污染的硫酸盐。净化可将部分腐蚀转化为有用的药剂原料，换取用于救治病株的药剂。")
zh(4110,"携带信号灯的采药人可识别魔藤污染的费伍德植物。研究可将其净化成药膏原料，收集此物便是救治病株治疗的一部分。")
zh(4111,"信号灯可揭示剥皮时被污染的兽皮。看似无用，却可制成植物药膏的糊剂，交出后将获得用于救治病株的药剂。")
zh(4112,"提炼物品所得的精华可作为植物药膏的原料。无需信号灯：少量精华便足以炼制多份药剂，持续净化工作。")
zh(4113,"歌花病恹恹的，散发出刺鼻的异味。腐败侵蚀着这株植物，若要恢复自然状态，它亟需照料。")
zh(4114,"歌花病恹恹的，散发出刺鼻的异味。腐败侵蚀着这株植物，若要恢复自然状态，它亟需照料。")
zh(4115,"风花病恹恹的，果实腐烂发毒，若要它重归自然，须得照料。")
zh(4116,"歌花气息恶臭，病态明显，腐化已侵染植株，唯有照料方能恢复原状。")
zh(4117,"根系干硬如皮，病株表面还挂着黏腻的膜，若要逆转腐化，需得细心照料。")
zh(4118,"歌花气息恶臭，病态明显，腐化已侵染植株，唯有照料方能恢复原状。")
zh(4119,"植株病态，果实腐烂发毒，唯有照料方能逆转腐化，重归自然。")
zh(4120,"塔罗认为腐化之力不仅强化了费伍德的熊与狼，还令它们陷入疯狂。他希望你直面这些野兽，亲身感受敌人的力量，从猎物身上学习。")
zh(4121,"格拉克·洛克鲁布认为从黑石要塞逃逸而不惊动守卫绝无可能。尽管他威胁重重，你仍需护送囚犯前往山那头等待的士兵，将他押送拘捕。")
zh(4122,"雷克斯洛特指控格拉克·洛克鲁布向黑石或克提供情报。他提供枷锁，要你将他拘捕于其藏身之处，引他至峡谷，那里有他所谓的叛徒等待受审。")
zh(4123,"麦克斯沃特苦寻多年的一颗宝石，黑铁族拒不售出。如今他动用武力，亟需黑石小径的秘库被攻破，方能夺回这颗深藏心间的珍宝。")
zh(4124,"一名信使与他的包裹已失踪一周，尽管堡垒已展开搜寻。基恩诺亟需协助寻找他，能提供最后的线索，另寻解决同伴忧虑的契机。")
zh(4125,"拉斯卡尔原计划沿海岸而行，穿越菲拉斯南方以避开部落。基恩诺找不到他的船，亟需搜寻，不知是被藏匿、沉没，还是掩藏着另一条线索。")
zh(4126,"霍尔雷与盟友盗取了雷酒配方，私自酿造啤酒。拉格纳希望夺回配方，毁掉黑石小径的酒桶，终结他们对家族秘方的剥削。")
zh(4127,"一把保养得宜的小刀躺在船边泥泞中，或属船中之人。基恩诺需检视它，作为寻找失踪信使的线索，而附近潜伏的动静，使发现变得令人不安。")
zh(4128,"拉格纳寻求冒险者解决一件令他愤怒的盗窃案，愿付重酬。前往卡拉诺斯酒厂，了解如何协助夺回家族失物。")
zh(4129,"奎恩提斯能借触碰揭示物件过往。基恩诺希望他施展此术于找回的小刀，愿以免除德鲁伊债务为交换，换取可能助寻信使的幻象。")
zh(4130,"幻象显示拉斯卡尔担忧豺狼人，却不知元素生物正从他身后凝聚。画面戛然而止。奎恩提斯需休憩，拜托你告知基恩诺所见，使搜寻得以继续。")
zh(4131,"基恩诺怀疑狗头人无法解释一切，但认为他们的营地是最佳线索。他们或许曾翻遍奎恩提斯梦境中的背包，搜查这些行囊，或许能发现失物，或找到失踪的信使。")
zh(4132,"高图斯认为该是惩罚那位发动袭击的将军之时。攻击安格弗将是这次行动中最艰难的任务，而为死去的士兵复仇，将获得丰厚回报。")
zh(4133,"维维安追踪着一种由黑铁酿造的饮品的传闻，需要协助调查。前往卡加斯找她，了解为何她对这道配方感兴趣，以及她需要什么帮助。")
zh(4134,"维维安想研究一种据说能赋予力量与勇气的啤酒。她认为这或许能达成亡灵的目标，因此需要夺回霍尔雷偷走的配方，必要时威胁他的酒桶以激怒他。")
zh(4135,"拉斯卡尔的笔记描述了他视为菲拉斯威胁的昆虫。他选择前往狗头人南方的深处调查，这为寻找信使或了解他的下落，指明了下一个目的地。")
zh(4136,"尤卡冷眼旁观因弟弟欠债与失败计划而引发的赏金。她希望找到他，带到自己面前，无论生死，以证明赏金能够兑现。")
zh(4141,"穆尔金想在拉瑞安因争执而彼此沉默时打扰他们。他相信陨石坑中的植物生物能被驯服，需要样本研究它们是否能听从命令。")
zh(4142,"样本显示这些植物似乎具备某种智慧，但穆尔金无法解读。格雷甘了解这类事，或许能指导这个项目，因此带一朵血瓣花向他求助。")
zh(4143,"格雷甘认为从神殿获取的物质能让穆尔金掌控那些有趣的植物。前往神龛获取该物质，再返回火山口，准备另一种方式延续同伴们的争执。")
zh(4144,"穆尔金需要幼嫩的豆芽来测试从神殿获得的物质。他想用这些豆芽恶作剧拉瑞安，决心继续这场争执，直到同伴承认自己错了。")
zh(4145,"拉瑞安怪罪穆尔金带他迷路，并派出训练有素的植物来骚扰自己。他不愿与穆尔金对话，提议减少可使用的生物，作为限制同伴恶作剧的第一步尝试。")
zh(4146,"车间有一台原型装置，只需稍作调整就能消灭那些麻烦的植物。它需要来自神殿的燃料，因此获取燃料并把装置带给拉瑞安，以应对他与穆尔金的争执。")
zh(4147,"拉瑞安发现穆尔金正在培育用来骚扰自己的植物。他拒绝通过对话解决，而是让你前往玛尔冯的车间，寻找反击恶作剧的装置。")
zh(4148,"这装置得有一份目标生物的样本才能校准。拉瑞安要一株嫩芽，好把装置调准了对付穆尔金的草木——这两人斗了许久，谁也不肯坐下来把话说开。")
zh(4161,"卡多雷传统的第一课，是从自然中只取所需。采集有限数量的材料，展现这种平衡应如何指引你的训练。")
zh(4181,"导师不信任地展示地精专精，专注于爆炸物。但他仍提供咨询尼克斯的手册，警告你加入后将永久生效，且无法学习另一门工程学分支。")
zh(4182,"龙人盘踞燃烧平原，周遭不得安宁。赫林迪斯要人帮他把它们赶回去，请你先削减它们的数目，其余的事以后再谈。")
zh(4183,"赫林迪、斯认为黑龙族操控着黑石兽人，并助长他们的敌意。这指向一个比想象中更可怕的敌人；所罗门需要这封信来判断该关系需要怎样的回应。")
zh(4184,"所罗门担心兽人与龙族联手的攻击会摧毁湖畔镇，并威胁其他聚落。伯瓦尔必须立刻得知这危险，希望能以报告的严重性换取暴风城的援助。")
zh(4185,"伯瓦尔不能仅凭怀疑就调动有限的兵力。他需要证据，并建议你向普瑞斯托请教龙族的知识，寻求解释以指导他对湖畔镇请求的回应。")
zh(4186,"伯瓦尔授予你暴风城副官的临时权力。将诏令带给所罗门，正式传达这项决定，并继续处理湖畔镇的威胁。")
zh(4201,"娜玛拉无法吸引罗克诺特的注意，她想要一瓶药剂来克服他的冷漠。她需要从遥远的地方收集材料，依靠你来搜集制备这配方的原料，希望能扭转她的爱情运势。")
zh(4221,"风花草病恹恹的，它的果实看起来腐烂且有毒。若要让这植物恢复自然状态，必须及时加以照料。")
zh(4222,"风花草病恹恹的，它的果实看起来腐烂且有毒。若要让这植物恢复自然状态，必须及时加以照料。")
zh(4223,"诏令要求你返回燃烧平原，担任暴风城的副官。所罗门派你前往麦克斯韦尔处获取进一步指示，延续对斥候所描述威胁的官方应对。")
zh(4224,"麦克斯韦尔称黑石的情报在温德索尔遭伏击时一同消失。狼狈不堪的约翰当时在场，或许能解释他的下落，也提供通往缺失文件的路线，以确保暴风城的介入。")
zh(4241,"温德索尔可能还在人世的消息传来，麦克斯韦尔当即下令搜黑石的牢狱。找到元帅，查明他的生死——活着就带他回来，死了就取一件凭据。")
zh(4242,"温德索尔认为证据已毁，对治理暴风城的掌权者深感不信任。他不认为数据能被找回；麦克斯韦尔需先知此坏消息，才能决定如何继续这场行动。")
zh(4243,"卡尔纳打造了一只机械猿，观察大猩猩却不惊动它们，却在抵达它们巢穴后失去联系。她需要找到A-Me，因最后影像显示一名男子正朝她靠近。")
zh(4244,"A-Me的控制面板仅有简单指令，用于更换零件并重启电源。获取秘银外壳将能尝试修复，不过唯有测试才能确定是否足以让她回归卡尔纳。")
zh(4245,"A-Me的重启已备妥，但要将她送回卡尔纳，需带她离开大猩猩领地。恢复供电并开始护送前，务必确保你已准备好保护这台机器。")
zh(4261,"艾雷即便化为灵体，仍被困在费伍德的苦难之中。军团的腐蚀令他无法安息，他请求被带离此地，之后凯尼斯将得知所发生的一切。")
zh(4262,"派隆焚毁了多名探险者，并封锁了黑石深处的入口。加琳达需要消灭守卫采石场的元素生物，好让她的队伍能顺利进入，避免更多伤亡。")
zh(4263,"加琳达担心伊森迪奥斯——这位据说是拉格纳罗斯仆从的怪物——会从灰烬中再度复活派隆。要开启探险队的通道，必须找到并摧毁维持入口守卫运作的力量。")
zh(4264,"信中提及黑铁氏族破解了温德索尔的文件。尽管文字残损，但或许能证明他的证据并未遗失；元帅需要亲自查看，评估这新的希望。")
zh(4265,"舱体显示拉斯卡尔尚在，却因虫群袭击而昏迷瘫痪。协助他恢复意识后，通知基恩诺查明信使失踪事件，并揭露他被囚禁的虫巢之险。")
zh(4266,"珊蒂斯希望表彰你的贡献，同时也想讨论在菲拉斯南部发现的虫群。拉斯卡尔的报告令人不安，这场对话将让这威胁超越信使的营救，被认真对待。")
zh(4267,"珊蒂斯希望格拉希娜研究一份菲拉斯虫害的副本。她对类似生物的知识，或许能帮助解读威胁，并补充达纳苏斯已整理的信息。")
zh(4281,"在犬人族中寻回的包裹，因信使失踪而未能送达。手写收件人姓名指向萨兰纳尔的法芬德尔，使这项任务可独立完成，无需依赖搜寻。")
zh(4282,"温德索尔认定，这张字条已足以为凭——他的文件仍在安格弗与阿格曼奇手中。他要你把文件夺回，并取那两个看守的性命：他清楚，他们不会自己交出他所需的证据。")
zh(4283,"奥拉留斯渴望收集兽人徽章，遂派你前往燃烧平原搜集。他声称自己神志清醒，并与隐形伙伴交谈，这些行为暴露了他古怪的个性。")
zh(4284,"J.D. 疑心散落在陨石坑里的水晶暗藏力量，只是试验至今未能证实。她要更多颜色各异的水晶样本，好接着试下去，也查明这些东西为何会出现在这里。")
zh(4285,"关于北部水晶塔的传闻占据着J.D.的思绪，她从未见过这种结构。她希望找到它以验证存在，并开辟水晶研究的新方向。")
zh(4286,"奥拉留斯相信地底的黑铁族拥有珍贵物品，想获取他们的行囊作为样本。他托你去取，理由来自他那奇特的想象伙伴所提出的主张。")
zh(4287,"J.D. 猜那些水晶塔与陨石坑各处收来的水晶相通。传闻说东边还有一座塔，她要你找到它，以验真假，也好让她走出洞穴里的那些试验。")
zh(4288,"J.D.的实验仍无结果，但她希望水晶塔能给出答案。先找到西方的塔，再尝试颜色组合，先找到能测试新想法的结构。")
zh(4289,"托瓦认为乌戈罗的野生动物是大地之母的体现，狩猎是向她表达敬意的方式。北方的猿族为寻求挑战者提供了一场力量的试炼。")
zh(4290,"托瓦记得当年他偷取猎物后，拉尔科瑞追杀并杀害了他的兄弟。他提议重演挑衅，偷取部分新鲜尸体，再带回来。")
zh(4291,"拉尔·科尔维未有回应，托瓦正准备另一种引诱手段。他需收集掠食者配偶的腺体，因它们的气味暗示着繁殖的意愿，他期望借此气味引诱支配雄兽现身。")
zh(4292,"托瓦希望将偷来的肉与上次见过拉尔·科尔维时的信息素混合，他相信这两种诱饵结合，最有可能引出这生物，迎来猎杀的决胜时刻。")
zh(4293,"弗雷想通过费伍德黏液作为参照组，比较不同生物体内的腐蚀现象。他需要你用他的设备检验样本，挑选最被污染的作为后续实验的基础。")
zh(4294,"报告称乌格罗沼泽仍未受到外界影响。弗雷想测试那里的黏液是否依然纯净，并研究其发展过程，用测试仪器挑选合适的火山口样本。")
zh(4295,"罗克诺特渴望更多黑铁啤酒，他找人带几杯来。这请求只反映他当下想要在酒馆继续畅饮的念头。")
zh(4296,"麦克斯沃特希望通过古七的智慧获取财富。一块索瑞森石板或许能保存他们的秘密，他需要你抄录文字，探究他们的学识，并在传说中寻找机会。")
zh(4297,"阿格纳希望为精龙宝宝准备合适的食物。在照料蛋的过程中，他请你获取优质肉料，若幼龙能成功孵化，便能获得足够的养分。")
zh(4298,"阿格纳认为是时候将蛋交托于你，让幼龙与你建立羁绊。交接仪式将你先前的努力转化为养育新伙伴的责任。")
zh(4300,"黑手的客户对某些迅猛龙的白爪所制武器颇感兴趣。杰斯里蒙愿为获取这些白爪支付丰厚报酬，若任务能迅速完成，甚至可能考虑提供进一步协助。")
zh(4301,"托瓦在北方洞穴中见过一头非凡的猿类，视其为大地之母的杰出子嗣。击败乌查并带回其皮毛，将证明托瓦愿予认可的狩猎技艺。")
zh(4321,"水晶塔上的讯息为 J.D. 指了条新路，通向水晶之谜的答案。她要先算上一阵，才肯说出结论——那些结论，正与你探坑时所见一一相连。")
zh(4322,"温德索尔渴望逃离监狱，但首先需取回装备并解救同伴。协助越狱行动，若能共克黑石守卫，将使此事回归麦克斯韦尔的掌控。")
zh(4324,"家族希望领取雷布里的赏金，尤卡已追踪他至燃烧平原。她需雇佣冒险者完成搜寻，前往她的庇护所，了解这项任务的详情。")
zh(4341,"麦格尼因女儿失踪而焦急万分，向本该守护她的人索要答案。卡兰似乎被囚于深地；寻获他，或可查明公主是否在彼处，以及发生了何事。")
zh(4342,"卡兰要求你先听他陈述，再评判他对于公主失踪的责任。他的证词将解释他所声称的经过。")
zh(4343,"风花正在衰败，其果实看似腐烂有毒。若要使这株植物重归自然状态，腐化之势必须加以遏制。")
zh(4361,"卡兰需要将关于公主的情报告知麦格尼。返回铁炉堡将向国王报告坏消息，国王必须决定如何应对威胁到女儿与王国的危险。")
zh(4362,"麦格尼认为索瑞森用魔法控制着茉艾拉，认为皇帝之死是释放她的必要条件。他要求救出女儿时确保她毫发无损，坚持任何抵抗都应归咎于那所谓的咒语。")
zh(4363,"茉艾拉拒绝父亲对索瑞森的看法，宣称继承人将是一位黑铁矮人。将这消息带给麦格尼，迎接一个与国王预期截然不同的回应。")
zh(4381,"石柱台融合了绿色与黄色水晶。J.D.的手册指出这对组合具有治疗效果，为这些材料提供了实际用途，既助己亦利同伴。")
zh(4382,"石柱台融合绿色与蓝色水晶，依照J.D.研究的指示。她的手册解释这种组合可提升灵体，赋予这些陨石材料特定的力量。")
zh(4383,"融合绿色与红色水晶利用石柱台准备防护。据J.D.手册所述，其效果可增强对物理伤害的抗性，为研究陨石的能源提供防御用途。")
zh(4384,"石柱台允许红色与蓝色水晶结合，用于不同的攻击用途。J.D.解释它们的力量可削弱敌人防御，将收集的材料转化为战场上的助力。")
zh(4385,"红色与黄色水晶可通过石柱台结合。J.D.说明这种组合能制造大爆炸，伤害敌人，使这些材料的能量发挥进攻性作用。")
zh(4386,"祭坛上的水晶融合蓝黄二色，以达成特定防御效果。据J.D.所述，其能量能形成护盾，同时伤害敌人，借陨石坑的材质，将防护与攻击融为一体。")
zh(4401,"歌花病恹恹的，散发出浓烈的异味。腐败侵蚀着植株，若想恢复自然状态，它需要悉心照料。")
zh(4402,"山谷的炎热让戈加尔的甜点格外诱人。收集仙人掌果，他便能制作出清凉的特制点心，之后你也能带上分食，用于自己的冒险。")
zh(4403,"风花草病恹恹的，浆果腐烂发黑，毒药已悄然渗入。若要让植物恢复原状，必须及时施以救治。")
zh(4421,"艾瑞丹想拯救费伍德，却指责半人马在其中散播腐败。她需要击败萨瓦瑟拉斯及其追随者，以保卫这片因他们而无法复苏的土地。")
zh(4441,"艾瑞丹认出笛子是古树守护者所制，其灵体仍被束缚折磨。她想尝试净化它，需从艾露恩神殿取来祝福之水，以对抗维持其痛苦的腐败。")
zh(4442,"艾瑞丹准备以艾露恩之水净化笛子。她请你稍等，待她尝试终结被困灵体的痛苦，期盼女神能指引她的双手。")
zh(4443,"可见的根系坚韧如皮革，病态植株上还挂着滑腻的薄膜。若要逆转侵蚀它的腐败，它需要被妥善照料。")
zh(4444,"可见的根系坚韧如皮革，病态的植物上还挂着一层黏腻的薄膜。若要逆转腐蚀的侵蚀，它亟需照料。")
zh(4445,"可见的根系坚韧如皮革，病态的植物上还挂着一层黏腻的薄膜。若要逆转腐蚀的侵蚀，它亟需照料。")
zh(4446,"可见的根系坚韧如皮革，病态的植物上还挂着一层黏腻的薄膜。若要逆转腐蚀的侵蚀，它亟需照料。")
zh(4447,"植物病态不堪，果实腐烂且有毒。若要逆转腐蚀、恢复其自然状态，它亟需照料。")
zh(4448,"植物病态不堪，果实腐烂且有毒。若要逆转腐蚀、恢复其自然状态，它亟需照料。")
zh(4449,"有人躲进厕所避难，逃亡途中却被黑铁的地质学家锁了进去。他想给这些人上一课，还想要丝绸——至于为何，他不愿多说。")
zh(4450,"囚犯愿将未完成的活计转交克林科，由加基森接手。他的账本列明所需材料，从峡谷到别处，收集并交付便可完成他未竟的差事。")
zh(4451,"钥匙上刻着与黑铁厕所相关的铭文，但其用途仍是个谜。探索灼热峡谷，或许能找到能匹配这看似简单物件的锁。")
zh(4461,"可见的根系坚硬如革，一層黏膩的薄膜覆蓋在病態的植株上。若要逆轉這腐蝕的侵擾，它亟需照料。")
zh(4462,"植株病態枯萎，果實腐爛且帶毒。若要逆轉腐蝕、恢復自然狀態，它亟需照料。")
zh(4463,"瑪瑟迪斯·火芒要求報酬與轉化法典為低階法術所需的材料。這交易將魔法與煉金材料結合，用以創造特定物品。")
zh(4464,"歌花病態衰敗，散發出濃烈的不健康氣味。腐蝕侵襲這株植物，若要恢復自然狀態，亟需照料。")
zh(4465,"歌花病態衰敗，散發出濃烈的不健康氣味。腐蝕侵襲這株植物，若要恢復自然狀態，亟需照料。")
zh(4466,"風花病態枯萎，果實腐爛且帶毒。腐蝕侵襲這株植物，若要恢移自然狀態，亟需照料。")
zh(4467,"風花病態枯萎，果實腐爛且帶毒。腐蝕侵襲這株植物，若要恢復自然狀態，亟需照料。")
zh(4481,"瑪瑟迪斯·火芒收取費用以製造法術，並警告他將保留大部分材料。攜帶法典與材料，即可在匠人的條件下兌換所承諾的物品。")
zh(4482,"玛瑟迪斯愿以创造一个低阶法术作为交换，条件是你交出典籍、魔法材料与一笔费用。他要求先将这些材料准备齐全，再完成那些寻求他知识之人才想得到的物品。")
zh(4483,"玛瑟迪斯将法术的创造条件设定为付款与材料。典籍与材料提供了完成这项魔法工作的所需之物，聚焦于他愿为你准备的物品。")
zh(4484,"玛瑟迪斯要求尽快交出典籍、材料与费用。这笔交易让你能选择他提供的法术版本，用收集的材料完成那项魔法造物。")
zh(4485,"你的信仰与坚持，让你得以继续向达索瑞恩学习圣骑士的技艺。前往暴风城寻他，别让成功蒙蔽了你一路走来的谦逊。")
zh(4486,"达索瑞恩已发出召唤，邀请你前往光之大教堂。尽管你的联系人承认羡慕你的成就，但这讯息似乎重要，值得回应。")
zh(4487,"你日益增长的力量已让导师确信你值得更多帮助。前往棘齿城上方的塔楼寻斯坦哈德，以继续认可你作为术士所展现的能力。")
zh(4488,"你日益增长的力量尚未等于理解，导师警告你腐化可能吞噬你。斯坦哈德想在塔楼与你交谈，速去以继续学习。")
zh(4489,"你作为术士的力量已获得认可，值得新的奖励。前往棘齿城上方的塔楼寻斯坦哈德，了解他提供的报酬，别让召唤你的人久等。")
zh(4490,"你苦心孤诣的训练终得回报，如今可召唤地狱战马。斯坦哈德将此奖励赠予你，以拓展资源，但也提醒你，驾驭这类生物的技艺，未必总能轻而易举。")
zh(4491,"林格中暑严重，亟需返回斯普拉格身边。他可随行，却惧怕途中昏厥；若能用水壶中的水唤醒他，便能继续向火山进发。")
zh(4492,"斯普拉格忧心林格离开探索火山已太久。她将水壶交予你，相信若寻得好友，这水或许能派上用场。")
zh(4493,"研究指出异种蝎对生态之外的生命构成威胁。它们的力量或许源自乌格罗；匹斯特苏格需要这个理论，以追踪感染源的踪迹。")
zh(4494,"研究指出异种蝎对生态之外的生命构成威胁。它们的力量或许源自乌格罗；匹斯特苏格需要这个理论，以追踪感染源的踪迹。")
zh(4495,"埃沃隆迟迟未至，已比平常晚数小时。他的友人忧心忡忡，因他常往蜘蛛成群的洞穴附近游荡，嘱你留意他的下落。")
zh(4496,"匹斯特苏格认为，若能除掉蚁后，便能瓦解虫巢，如同蜜蜂一般。他需要一种信息素与乌格罗的泥土，制作诱饵，确保你不会贸然闯入巢穴。")
zh(4501,"悬赏告示：翼手龙日渐增多，已成陨石坑行旅的心头之患。告示征一名好手，杀减其数，事成有赏。")
zh(4502,"导师不在，莉芙便想自己动手试验。乌纳戈罗的火山叫她着迷，她要元素灰烬，好查明坑心那一带不寻常的动静。")
zh(4503,"希兹尔困在原地，担心骑乘巨兽会带他抵达加基森。他选择打造飞行器，但机翼需要来自危险生物的鳞片，而他却不敢面对这些生物。")
zh(4504,"特兰瑞克寻求一种利润丰厚的生意，使用比普通种类更黏稠的焦油。坑洞附近的生物将它与叶绿素混合，制成他发展计划所需的材料，他也愿与他人分享利润。")
zh(4505,"温娜希望利用被腐蚀的月亮井为部落谋利。她请求提供一处样本，那是半人马曾用以测试她豢养的小猫与月亮井水关系的地点。")
zh(4506,"温娜的第一次实验使她的小猫体型增大，似乎也增强了它的力量。她想再做一次实验，将动物释放至月亮井水边，再带回评估腐蚀之力的用途。")
zh(4507,"匹斯特苏格认为虫巢水晶能协调异种蝎，甚至召唤出它们的女王。前往虫巢使用诱饵，面对守卫，取回女王的大脑——这是他视为急需的研究。")
zh(4508,"加基森无法独自应对研究揭示的威胁。匹斯特苏格希望格拉希娜获得乌纳戈罗的报告，期待她与联盟领袖的联系能争取到更广泛的支持。")
zh(4509,"加基森无法独自应对研究揭示的威胁。匹斯特苏格希望基尔兹宾获得乌纳戈罗的报告，期待他与部落领袖的联系能争取到更广泛的支持。")
zh(4510,"格拉希娜担心乌格罗不是异种蝎的起源，更担忧某种更强大的存在潜伏其中。思索之际，她递给你一张凭证，感谢你为研究付出的努力，并承诺从她的宝库中赠予一份礼物。")
zh(4511,"基尔兹宾担心乌格罗并非异种蝎的起源，更担忧某种更强大的存在潜伏其中。思索之际，他递给你一张凭证，感谢你为研究付出的努力，并承诺从他的宝库中赠予一份礼物。")
zh(4512,"拉里斯见过许多地方的黏液生物，想弄清它们的起源，以及药剂师为何对它们感兴趣。他需要费伍德的样本，以拓展研究，回应他与这些生物相遇的启发。")
zh(4513,"拉里斯·空轮猜想软泥怪会沾染周遭之物的脾性，要拿未受污染的样本作个比对。容器由他备下，只差一处干净的来处——先前那些被腐蚀的样本，验不出他这番猜想。")
zh(4521,"特鲁尔相信野性种族守护着冬泉谷的暗夜精灵秘密。他想削弱他们的存在，以获取进入的权限，探寻守护者可能隐藏的真相，依据传闻行事。")
zh(4542,"半人马的袭击愈演愈烈，乱风岗急需警示。将消息送往长角氏族，避开附近可疑的恐怖图腾，他们的举动也变得令人不安。")
zh(4561,"乌格罗的样本接受纯度检测，过程为弗雷利的比对做准备，延续对可能未受费伍德腐化影响的生物的研究。")
zh(4581,"凯尼斯怀疑腐化正蔓延至灰谷，需要来自海岸与阿斯特兰纳森林的情报。你所携带的报告将把这些观察传递给林歌神殿的德鲁伊。")
zh(4601,"在侏儒们坚守的房间里，矗立着一台清洁贵重物品的机器。它的铭牌承诺，只要插入物件并支付三枚银币，便能去除污垢与残留。")
zh(4602,"沾满污渍的贵重物品可送入超级清洁器5200型。这台机器安装在房间内避难的侏儒们中间，只收小额清洁费，便能重焕光采。")
zh(4603,"超级清洁器已空待用，随时准备下一次清洁。若你仍带着脏兮兮的东西，插入一件并支付三枚银币，便可启动清洁程序。")
zh(4604,"清洁机器可再次接受覆盖残留的物件。它只需你想要清洁的物件与三枚银币，便能再度履行设备上所承诺的服务。")
zh(4605,"清洁周期已结束，机器内留下一个系着蝴蝶结的小盒子。是否彻底去除了污垢尚不可知，唯有拆开包裹才能揭晓物件的真容。")
zh(4606,"一声轻响，报知清洁器已停了工，一只彩饰包裹正等人来取。机器看来会把它处理过的东西裹好；至于有没有洗净，只有拆开才见分晓。")
zh(4621,"菲尔拉伦视藏宝海湾的领袖为血帆自由劫掠的阻碍。若你能除掉卡拉·海角与里维加兹，他将授予你名誉上将之位，使对港口的攻击成为海盗忠诚度的试金石。")
zh(4641,"你已年长足以为部落效力，但适切的挑战应先于一切。高内克可在你尝试涉及更大危险的壮举前，指派符合你经验的任务。")
zh(4642,"弗雷想观察费伍德黏液与未受污染的乌戈罗样本之间的接触。他提供了一只封闭的生物，要求在目标附近释放，并希望获取实验后残留物的样本。")
zh(4661,"这套设备把费伍德的样本过上一道，令其形貌改易。此乃弗雷腐蚀研究的一环，也为与其他地界生物的比对备下材料。")
zh(4681,"黑海岸的搁浅现象呈现出某种规律，尚待进一步调查。若能再检查一艘沉船附近的尸体，或许能获取理解这些生物为何持续出现在海岸的有用样本。")
zh(4701,"黑石兽人的座狼折损再多也不见少——塔里还在不断配种，成批往外送。赫林迪斯要的是找到祸根、一并铲除，而不是一头头去打新放出来的狼群。")
zh(4721,"据报，又有野性生物聚在洞穴附近——那些洞里兴许藏着值钱的东西。特鲁尔·法贝恩要清空这一带好做探查，却也提醒：这些生物发狂，恰恰像是被它们守着的那件东西所害。")
zh(4722,"一只海龟在黑海岸搁了浅，就此死去，鱼人已来啃食过它的残骸。温尼斯·布莱葛要查这接连搁浅的缘由，所幸还剩下合用的样本。")
zh(4723,"一只体型异常巨大的锯齿鲨搁浅在岸上，鱼人似乎并未杀死它。样本让温尼斯得以调查其死亡的可能原因。")
zh(4724,"座狼的数量源自哈雷肯与她的伴侣，而非恶魔起源。贾拉玛弗希望从源头着手，消灭那只巨大的雌蓟熊，同时留意她鲜为人知的伴侣。")
zh(4725,"一只海龟的骸骨搁浅在海滩，壳上仍拴着一辆马车，暗示有人曾驾车将它送上岸。一只标记诡异的箱子，或许能为温尼斯的调查提供线索。")
zh(4726,"丁奇相信新发明的装置能捕捉巨龙幼兽的精魄。他计划在燃烧平原测试，若成功便采集样本，将未经验证的设想付诸实践。")
zh(4727,"海龟的骸骨搁浅在海滩，鱼人似乎并未利用它们。残存的骨骼足以采集样本，供温尼斯送往神殿进一步研究。")
zh(4728,"一只海洋生物的尸体半截被啃食，散落的工具与推车显示有人试图研究它。尽管鱼人已搜刮殆尽，仍有可用样本可供温尼斯调查。")
zh(4729,"基布雷尔以训练的珍稀动物换取财富。他要求你交出一只座狼幼崽，并承诺为你驯养，提供囚笼以确保小掠食者安然无恙。")
zh(4730,"一只体型庞大的海洋哺乳动物的残骸，被异常强壮的鱼人啃食殆尽。残存的骨骼仍能为温尼斯提供样本，协助调查沿岸搁浅的尸体。")
zh(4731,"一只海龟的骸骨搁浅在海滩，壳上仍拴着一辆马车，暗示有人曾驾车将它送上岸。一只标记诡异的箱子，或许能为温尼斯的调查提供线索。")
zh(4732,"鱼人围绕一只几乎被吃光的海龟扎营。尽管大部分尸骸已被消耗，仍留有可用样本，或可支持对沿岸搁浅事件的调查。")
zh(4733,"一艘巨大的绞肉机残骸被冲进海湾，体型表明它并非黑海岸原生生物。温尼斯需要取样分析，以查明这究竟是什么。")
zh(4734,"丁奇·斯迪波尔造出一台原型机，专为冻住龙蛋，要拿到黑石的育雏地去试。回来告诉她机器如何。照发明者的算法，冻住的蛋便无害——没冻住的才是祸患。")
zh(4735,"丁奇需要真正的龙蛋继续研究，并提供一个用于运输的装置。采集前先冻结，以防孵化，才能获得安全的样本。")
zh(4736,"你的进展与抗腐蚀能力证明你值得获得奖励。梅纳拉是棘齿城塔楼中的专家，她能提供帮助，但她的严厉态度意味着你需要付出努力，而非期待称赞。")
zh(4737,"泽弗洛斯特不信任你对力量的追求，担心腐蚀会奴役你。梅纳拉却持不同意见，她想创造强化你的工具。前往棘齿城找她，考虑她的提议。")
zh(4738,"你的导师认为你尚未准备好创造强大物品，但其他人已给予机会。若想了解更多，可前往棘齿城找梅纳拉。")
zh(4739,"你日益增长的信心表明，你已能从梅纳拉那里学到更多。她教导年轻学员，通过考验者将获得奖励。前往她的塔楼，是训练的下一步。")
zh(4740,"一名鱼人被指认为哨兵的死因，并涉嫌袭击商船。奥伯丁的议会悬赏缉拿他，以消除他沿岸带来的威胁。")
zh(4741,"特鲁尔希望进一步清理野兽人领地，如今目标转向北方更凶猛的族群。这场狩猎将让他们得以探索土地，也延伸了寻找他们所守护秘密的范围。")
zh(4742,"维埃兰解释，封印需要象征堡垒统御的宝石。从将领手中夺回它们，将为日后以黑龙之焰熔铸做好准备，但寻找这些碎片需要坚持。")
zh(4743,"封印需要龙焰，但维姆萨拉克无法被控制。维埃兰提议改用埃博斯塔夫：削弱他的意志，短暂引导他，或许能借黑龙之焰完成熔铸。")
zh(4761,"你对熊怪的观察必须传达给奥伯丁的长老。桑迪斯对他们的腐化有想法，或许能将收集到的信息转化为恢复森林平衡的计划。")
zh(4762,"壁泉河水日渐浑浊，桑迪斯·织风怕它早晚要祸及奥伯丁。他疑心是上游的熊怪作祟，却也认定这腐蚀另有更深的根由。他要一份水样，好查个明白。")
zh(4763,"半人马通过符咒控制熊怪。一种净化剂或许能暂时中断这种影响，引出腐化劣魔并正面交锋，给受影响的熊怪一线生机。")
zh(4764,"玛亚拉·布莱特文相信，一座旧日宝库的废墟里还留着矮人的遗物。她要寻一枚以宝石闻名的胸针，提议往黑石走一趟，把那件埋入尘土的东西取回来。")
zh(4765,"玛亚拉已将胸针打包运往暴风城，只差最后一步交付。雷明顿·瑞治维尔伯爵正等待这件遗物，将它交给伯爵，便完成从黑石回收的物件移交。")
zh(4766,"瑞治维尔伯爵派玛亚拉·布莱特文寻找文物以充实家族博物馆。她的研究如今指向黑石一处物件，需协助取回；若想展开超越最初遗迹的远征，可向她咨询。")
zh(4767,"风骑手的需求正以远超训练速度增长。为满足风骑手的需要，需从风巢收集卵，那里的成年风龙会激烈抵御入侵者。")
zh(4768,"维维安寻找一位炼金师的笔记，他被斥为疯子后仍用石板记录研究。她相信黑石仍存其遗作，愿以报酬换取作者从未公开的智慧。")
zh(4769,"维维安认为一部古老的黑石文献或许能助药剂师们研究。她需要人取回并验证其价值，因此在卡加斯找她商量，再展开这场危险的搜寻。")
zh(4770,"一名风龙研究者过于接近巢穴，仓皇逃窜后迷失在风巢。数日躲藏后，他需要护卫送至白沙岗哨，以免缺席引发更多麻烦。")
zh(4771,"贝蒂娜想要一种对抗通灵学院亡灵学者的药剂。将它带到他们的密室或许能削弱维克图斯的势力，进而攻击法师，不过效果仍取决于反应是否奏效。")
zh(4781,"这件衣物需要金线，唯有少数裁缝掌握此技艺。希兹克·古斯提知晓这门手艺，并支持你阵营中崛起者；将金属带给他，让他准备刺绣。")
zh(4782,"希兹克需要时间织线，但承诺完成委托。告诉梅纳拉，并在他完成衣物部分的同时，继续收集其他材料。")
zh(4783,"这件长袍需要萨特之血与凄凉之地的地狱火石。寻找这两样材料，意味着要在憎恨你的生物与恶魔之间展现你的力量与机智，借他们的力量完成梅纳拉准备的衣物。")
zh(4784,"唯有你创造的成品线、元素煤块与灵魂碎片尚缺。梅纳拉需要这些最终材料，才能完成一件融合精湛工艺与你术士之力的长袍。")
zh(4785,"希兹克与他的兄弟比预期更早完成线材，已备妥待用。收集这种特殊材料，继续这项依赖他们裁缝技艺的委托。")
zh(4786,"收集的材料如今让梅纳拉得以缝制长袍。她需要片刻时间，也请你留在附近，待她完成你先前任务所准备的衣物。")
zh(4787,"耶赫金亚寻找预言中提及的蛋，据说能容纳哈卡的本源。他认为这是对抗神明的可能手段，需将这件圣物从金塔哈洛尔的高处寻回。")
zh(4788,"在研究先前石板时，詹斯·铁靴需要补全摩什·阿鲁的收藏。剩下的两件由黑石巨魔保管，继续研究意味着必须深入一处格外危险之地。")
zh(4801,"毛阿瑞提供霜刃豹的寒水魂精，以换取部分他们的速度。携带她的护身符狩猎，辨识样本并带回给巫医，换取动物之力。")
zh(4802,"毛阿瑞认为冬泉巨熊怪拥有强大的力量，借由他们的寒水魂精提供通向这力量的途径。携带护身符，辨识所需样本，寻求她认定的潜能。")
zh(4803,"玛乌阿里将厚皮熊的抵抗之力与她的‘艾科’联系起来。她为样本提供防火保护，但唯有在她魅力引导下狩猎时才能辨识。")
zh(4804,"冬泉谷的飞翼生物掌握霜火魔法，玛乌阿里借‘艾科’之力抵御其威。携带魅力之证，辨识样本并交予她完成交换。")
zh(4805,"玛乌阿里想借雪熊的闪避能力，弥补其行动迟缓之短。她的‘艾科’可提升闪避，但需携魅力之证寻觅样本。")
zh(4806,"冰巨人的力量令玛乌阿里动心，她愿传递部分威能。需借‘艾,科’准备援助，战斗中魅力之证是辨识样本的关键。")
zh(4807,"玛乌阿里认为野性种族天生蕴含魔力，可益心智。她愿借‘艾科’提升智慧，但样本须在携魅力之证狩猎时方能辨识。")
zh(4808,"研究本质后，丁奇推测龙卵可借冷冻保存。需特殊组件验证理论，她便致信菲诺克，后者可在冬泉谷制作。")
zh(4809,"菲诺克已备齐大部分材料，唯缺能凝聚奇美拉寒气的角。须完整样本方能完成组件，助丁奇推进冷冻龙卵实验。")
zh(4810,"菲诺克已备妥丁奇所需组件。携包裹前往燃烧平原，让她的龙卵实验继续，也传达她同僚仍视此为恩情。")
zh(4811,"月夜枭兽性情暴烈，却似乎被一块神秘的红色水晶勾住了。吉尔娜要你查实水晶确有其实，并带回足够的消息，好判断它会给奥伯丁招来什么祸患。")
zh(4812,"月亮井的水或许能揭示这块奇异水晶的成分。然而实验需谨慎，因它可能与费伍德森林存在某种联系，足以让这物件成为危险之物。")
zh(4813,"检视已发现水晶内藏有白骨碎片，但将其击碎似乎几乎不可能。你必须将发现上报哨兵，让调查能借着这线索继续推进。")
zh(4821,"传言有一枚怪异的蛋，蛇群守着它，如同守着自家幼崽。至今无人凑近看过。从蛇巢里把它取回，才好细细剖验。")
zh(4822,"你的结界热情地忆起曾在赛场上品尝过的草莓冰淇淋。得知它可能已在镇上出售，孩童央求你外出时买下最爱的品牌，作为一份小礼物。")
zh(4841,"复仇的渴望驱使另一波对半人马的攻击。前往乱风岗北方袭击他们的营地，以回应那些你联络人所负责的过往罪行。")
zh(4842,"多诺瓦怀疑温泉的暖意源自比火山更危险的存在。她希望你向南而行，观察天象变化，亲眼见证她相信能解释这现象的地方。")
zh(4861,"枭兽驱逐了加隆，因他靠近了它们守护之物。他急需补给与新近出土的护身符，担忧那被遗弃的伙伴或许仍未离去。")
zh(4862,"基布雷尔为顾客寻觅蜘蛛蛋，因比修尚未从冰冠之塔归来，他需另寻一名收集者，承诺以金钱与驯服生物为酬。")
zh(4863,"破损的木箱暗示野性之民曾刻意搜寻加隆营地中的某样东西。东面废弃的马车或许能指引找到他的物品，继续追寻护符的线索。")
zh(4864,"回收的物资或可助加隆一臂之力，但护符仍下落不明。附近的野性之民成为搜寻的下一个目标，他们之中或许藏着那失落的碎片。")
zh(4865,"千针石林中出现一股复仇之力，令哈加尔忧心忡忡。他将冰冠之塔的线索托付给白沙岗哨的莫特加·火鬃，因他相信此人知如何应对。")
zh(4866,"狼狈不堪的约翰渴望一种他认定极其强大的蜘蛛毒液。他不接受腺体，而是要求你与毒物同体而归，待你中毒时他方能抽取。")
zh(4867,"瓦罗什几乎开不了口，只塞给你一张字条，托你找回他的魔精。字条上写明该往何处去寻，寻得了再回来见他。")
zh(4881,"一则密信揭露了暗杀卡纳提及其猎营的计划，连同追随者一并清除。须将此阴谋告知卡纳提，让他知晓身陷险境。")
zh(4882,"野性之民的项链泛着异光，却意义不明。特鲁尔熟识这些生物，或许能解释这发现，故在解读物件之力前，应先请教他。")
zh(4883,"特鲁尔熟悉野性族群，却坦言不理解他们的魔法。娜拉专精此道，或许能查验项链，借由专业之手延续调查。")
zh(4901,"兰莎尔拉认为火把与古老铭文能通往艾露恩的祭坛。她需要协助吟诵咒语，也需要保护，若成功，所得将与艾瑞拉斯共享。")
zh(4902,"艾瑞拉斯认为发现必须立刻告知范达尔。他希望详述祭坛所见，好让大德鲁伊评估对野性族群认知的重要性。")
zh(4903,"高图斯下令处决三位黑石塔首领，并夺取战略文件。行动旨在打击敌方指挥官，获取情报，完成者将获表彰。")
zh(4904,"阿纳克曾强娶一名女子，遭拒后更杀害了试图阻止他的兄长。如今她需逃离黑云峰，返回萨利亚处，等待她的消息。")
zh(4906,"艾瑞丹发现另一处营地，正利用先前半人马培育的腐败。萨瓦里克领导这场扩张，必须阻止他与追随者，方能完成净化费伍德的使命。")
zh(4907,"丁奇再度请求协助，似乎与她的龙类研究有关。前往燃烧平原找她，看看新的研究阶段需要你做什么。")
zh(4921,"一场战斗让战士与妻子分离，他身受重伤。一位德鲁伊救了他，但那女子至今下落不明，他需要你寻找她留下的踪迹。")
zh(4941,"雷德尚在人世的消息，颠覆了数十年来的认知。伊崔格深知黑石之力，必须在你向萨尔禀报前，先听你呈上证据。")
zh(4961,"水晶的腐蚀源自其中封印的恶魔。驱魔仪式将释放它，但你必须速战速决，否则它重返水晶，迫使你再度面对。备好最强法术与补给，必要时寻求援手。")
zh(4962,"你选择将地狱巨犬的魂魄封入新造的法器。当生物虚弱时，红宝石可将其禁锢；梅纳拉便能以宝石与灵体继续她的造物之工。")
zh(4963,"选定的魂魄属于凄凉之地的地狱火爪牙。绿宝石可在其临终之际捕获其灵体，为梅纳拉提供所需的恶魔成分，以延续造物之业。")
zh(4964,"梅纳拉已准备好铸造水晶，并以你所得恶魔注入其中。她愿让其形态契合你的战斗风格，待完工后，可选择法杖或水晶形态。")
zh(4965,"你的力量已足以寻求专精之士，协助你将恶魔封入符合作用的器物。梅纳拉驻守棘齿城，可助你打造这新资源，以供术士研习。")
zh(4966,"卡纳提担忧涉事的半人马远超他最初所料。随着暗杀威胁暴露，他请求你并肩作战，迎战那些前来取他性命之人。")
zh(4967,"你的导师依旧轻视你的野心，但他人认为你配得上更强大的力量。梅纳拉愿在棘齿城与你交易；寻她，可知这机会的详情。")
zh(4968,"你已超越导师预期，未被腐蚀侵蚀。下一步的考验将借梅纳拉之手，进一步锤炼你的能力，从棘齿城上方的塔楼指引下展开。")
zh(4969,"纵然你的野心指向统御巨魔，仍需依赖凡人之手打造的武器。梅纳拉认为你已准备好迎接另一件强大造物，正于棘齿城塔楼附近等待，欲与你详谈。")
zh(4970,"雷沃驯养霜刃豹，眼下缺的是肉。这一带的奇美拉与熊身上都有，猎来即可。差事不难，却是头一件——他要看你肯不肯为这活计下力。")
zh(4971,"克罗米正尝试修复安多哈尔的时间扰动，但寄生虫啃食着损害，阻碍她的预兆。用她的装置揭示它们，消灭它们，让她得以无扰继续工作。")
zh(4972,"克罗米从另一条时间线运作，修复安多哈尔，避免进一步污染其历史。她需要在祸害鼠爆发时捕获的怀表，以遗迹之物维系她的干预行动。")
zh(4973,"克罗米仍需安多哈尔怀表，以维持对抗篡改历史之力的平衡。她又提供另一件物品，换取新鲜样本，延续时间修复所需的物质支持。")
zh(4974,"萨尔认为黑龙时代赋予雷德对部落的指控正当性。他命你穿越冰冠之塔的防御，铲除那名敌对战帅，以他的首级作为值得荣耀的功绩证明。")
zh(4975,"梅纳拉已取得恶魔，如今可着手打造你的新物品。其最终形态可随你喜好而定，保留你以法杖或水晶掌控这股力量的选择。")
zh(4976,"净化之后的宝珠须送回梅纳拉手中，她的活计才接得下去。你的盟友盼你抵得住路上的引诱：除掉这一处腐蚀，并不等于往后的修行再无凶险。")
zh(4981,"雷克斯洛特指控比修在为私商效力期间挪用部落资金。他希望她能活着从黑石塔被救出，并警告你不要被那个狡猾的特工的借口所迷惑。")
zh(4982,"比修称自己触发警报后逃走，丢失了侦察装备。巡逻队加强后，已无法找回；她愿和平归还，只要你能救出她逃亡时藏匿的文件与物品。")
zh(4983,"比修希望这份报告能送回雷克斯洛特手中，以恢复她的声誉并获得战略优势。因仍有事务未了，她拒绝同行，只留下你去传递她上司所需的情报。")
zh(4984,"穆格雷斯前来治愈疫病的伤害，却未能完成工作。他相信染病的狼群已无救赎之望，请求你以慈悲终结它们的痛苦，以慰藉这片被摧毁的自然。")
zh(4985,"熊群也难逃疫病之苦，它们游荡时肌肉僵硬、皮肉腐烂。穆格雷斯认为唯有速死才是它们唯一的解脱，请求你对这些昔日威武的生灵施以慈悲。")
zh(4986,"死去的德鲁伊枝条仍保留着温度，触碰时浮现达纳苏斯的符文。它的魔法似乎将塞纳里奥议会视为归宿，指引你寻找援助，继续未竟的使命。")
zh(4987,"死去的德鲁伊枝条仍保留着温度，触碰时浮现雷霆崖的符文。它的魔法似乎将塞纳里奥议会视为归宿，指引你寻找援助，继续未竟的使命。")
zh(5001,"比修认为黑石威胁影响着联盟，尽管她忠于部落。若能找回她的物品，她愿提供有用情报，促成敌对双方为共同敌人而合作。")
zh(5002,"比修将奈法利安识别为兽人的真正领袖，并在地图上标记他的爪牙。麦克斯韦尔需要这份情报，以了解敌人组织，采取超越肉眼可见兽人力量的行动。")
zh(5021,"一位女子的幻影坚持必须送完包裹，否则她将被困住。她混乱的记忆将包裹放在马旁，虽对当下认知有限，却仍能提供线索。")
zh(5022,"包裹多年未送，艾玛的下落成谜。暴风城的档案或许能寻得她的踪迹，故在尝试完成逾期投递前，先查阅人口普查。")
zh(5023,"包裹多年未送，杰雷米亚的下落成谜。幽暗城的档案或许能寻得他的踪迹，故在尝试完成逾期投递前，先查阅人口普查。")
zh(5041,"一支商队遭袭，十字路口陷入物资短缺。在对抗奎尔博尔的过程中，若能搜集散落在他们营地的补给，便能缓解定居点居民的困境。")
zh(5042,"血岩碎片可换取与阿伽玛甘力量相关的祝福。这份馈赠赋予的战斗之力，恰如奎尔博尔族人所称的部落最强战士在战场上的威能。")
zh(5043,"献上血岩碎片，可获得敏捷祝福。这份馈赠汲取的是奎尔博尔族侦察兵所拥有的速度与精准，源自其族系的传统。")
zh(5044,"野猪人萨满召唤阿迦玛甘之力，以强化法术与仪式。献上血岩碎片，便可祈求与这力量相关的祝福，作为自身魔力准备的一部分。")
zh(5045,"野猪人的精神传统认为，内心的坚定能在最艰难时刻支撑战士。血岩碎片是祈求祝福的祭品，此祝福旨在强化战斗中的意志。")
zh(5046,"出征之前，先求阿迦玛甘的庇护。你也能用血岩碎片换得同样的祝福——那位通晓野猪人旧俗的人，愿意与你做这桩交易。")
zh(5047,"皮普希望玛雷弗斯得知他生还，且他的装备运作如常。他并提供了一块取自巨兽的样本，让工匠评估能从这类生物身上制成何物。")
zh(5048,"户籍册上，包裹最可能落到艾玛手里。她说话糊里糊涂，仍要寻到她，问明姓氏——詹妮丝托付这些东西，究竟是不是给她。")
zh(5049,"簿册上另有一个名字：幽暗城卖蟑螂的杰雷米亚。去银行附近寻他，核对包裹上的姓名，了结詹妮丝这桩拖了太久的事。")
zh(5050,"包裹已抵达收件人，但詹妮丝似乎仍与农场牵连。她的亲属希望归还半枚符咒，让她知悉物品安然无恙，期盼这讯息能助她安息。")
zh(5051,"詹妮丝呼唤丈夫，请求在瘟疫来临前重聚符咒。她混乱的记忆暗示寻回另一半、重聚符咒，或能回应使她魂魄不宁的执念。")
zh(5052,"赤红碎片源于阿伽玛甘之血，被食人魔用作图腾。碎牙知晓其魔力，愿以祝福换取你将这些石头带来。")
zh(5054,"尤西乌斯是一头技艺超群的熊，连猎人也成了它的猎物。风暴要你在他察觉你的意图前找到他，并以谨慎应对这狡黠敏捷的对手为考验。")
zh(5055,"布鲁米兰的优雅下隐藏着致命危险，曾让横渡她路径者命丧黄泉。风暴要你在这片雪原上寻得奇美拉，并以你的速度与机智与之较量。")
zh(5056,"风暴认为击败霜刃豹女王将赢得极大的狩猎声望。他提议用她亲族的肉引诱她，激怒希洛塔姆的怒火，再与之正面交锋。")
zh(5057,"风暴认定你的胜利印证了他所听闻的你的决心与能力。他送你一枚信物，梅洛·石蹄能听见你最近的成就，并认可你自上次狩猎以来的进步。")
zh(5058,"日记里写着哈洛德·李格斯变形后被关押的日子，也写下一个想逃出去的人如何挣扎。钥匙、藏钱，这些字句都给探查农场的锁闭之处留下线索。")
zh(5059,"门从内侧锁死，且有反复强行打开的痕迹。门内传来令人不安的呻吟声；要进入这处居所，需一把钥匙，而屋内之人似乎并不欢迎访客。")
zh(5060,"柜子被强力锁闭，且有激烈撬开的痕迹。找到钥匙，便可无须重蹈覆辙，直接开启这处曾难逃锁具的密室。")
zh(5061,"你已修完接纳水之形态前的所有课程。这枚吊坠可证明你已准备好接受玛斯雷·驭熊者的考验，他必须完成这一阶段的训练，方能适应水中的生活。")
zh(5062,"召唤阿利卡拉需要点燃生命圣火。火岩龙舌兰能让玛加萨·野性图腾准备魔化粉末；在寻求萨满祭司协助前，先采集这种植物。")
zh(5063,"玛雷弗斯提供了一顶由巨兽纯净皮毛与其他魔幻材料制成的非凡头盔。他需要这些材料与丰厚报酬，才能让工匠打造一件对法师而言尤为珍贵的物品。")
zh(5064,"三位来历不明的访客已引起恐怖图腾的疑虑。他们的讯息分别藏在黑云峰的三只箱子中；获取它们，便可揭开那些秘密会议的真相。")
zh(5065,"詹斯·铁靴发现摩什·阿鲁的预言刻在六块石板上，而非此前找回的两块。他担忧剩余部分所隐藏的秘密，亟需瘟疫之地的巨魔提供下一批碎片以揭开完整传说。")
zh(5066,"暴风城召唤所有能对抗天灾军团的战士。关于北方遗迹中新威胁的传闻，使拜访阿什拉姆变得刻不容缓，他的营地正协调愿意应征的冒险者。")
zh(5067,"玛雷弗斯提议打造一条蕴含强大力量的护腿，但他承认这种创造从未完成。收集非凡材料并支付报酬，将使他相信在合适条件下，这项尝试是可行的。")
zh(5068,"传说中唯一一件此类胸甲归功于迦罗娜。玛雷弗斯的工匠声称，他们能用非凡材料复刻它，但需要难以获取的组件与丰厚报酬才能完成这项工作。")
zh(5081,"麦克斯韦尔元帅意图瓦解黑石势力，方法是铲除其高层领导。每一次袭击都针对不同的指挥职能，从战斗筹划到食人魔领导，再到要塞整体的协调运作。")
zh(5082,"熊怪死死守着泉水，多诺瓦的研究因此搁了下来。她要这股压力松一松，才好查那水里的古怪——源头至今不明。")
zh(5083,"这个瓶子仍残留着一种绿色液体，几乎像是在发光。其重要性尚不明确，但多诺瓦知道泉水的特性，或许能借此研究它的内容，以及熊怪如何使用它。")
zh(5084,"这种液体让多诺瓦联想到费伍德的腐蚀现象，而她曾见过冬泉信使穿越木喉要塞。她怀疑两者之间存在关联，想要搜查死木营地，寻找两个部族勾结的证据。")
zh(5085,"大锅里盛着一种与瓶子内容物相似的物质，引发了关于腐蚀的疑问。多诺瓦需要样本和发现过程的记录，以调查冬泉是否使用了与死木相同的材料。")
zh(5086,"多诺瓦疑心那混合物里掺了腐化生物的毒，却缺一份对照。林中的恐怖生物或许就是来处——取它们的体液来验，正好试她那个还说不准的猜想。")
zh(5087,"多诺瓦发现泉水能去除物质的毒性，却保留其短暂效果。她认为这解释了冬泉为何要守护泉水，想要切断他们的补给线，攻击运送这种物质的信使。")
zh(5088,"玛加萨担心阿利卡拉正在追踪凯恩，因牛头人传统发生了变化而愤怒。魔法粉末将召唤她前往恐怖图腾的墓地，以便应对这个威胁。")
zh(5089,"找回的信件记载了达基萨斯将军对一名下属的指示。内容似乎至关重要，麦克斯韦尔或许能解读其中玄机，将这份文件交予他，获取关于黑石氏族组织的新情报。")
zh(5090,"暴风城号召所有能对抗天灾军团的战士前往北方疆域。关于遗迹中新威胁的传闻让拜访阿什拉姆变得刻不容缓，他的营地正协调愿意应征的冒险者。")
zh(5091,"暴风城号召所有能对抗天灾军团的战士前往北方疆域。关于遗迹中新威胁的传闻让拜访阿什拉姆变得刻不容缓，他的营地正协调愿意应征的冒险者。")
zh(5092,"阿什拉姆计划经由防守薄弱的东侧道路进攻安多哈尔。他首先需要清除山丘上盘踞的骷髅与食尸鬼，这些亡灵正是天灾军团的防御屏障。")
zh(5093,"部落号召冒险者对抗天灾军团在幽暗城以东的新威胁。德灵顿从亡灵壁垒协调应对，静待愿意协助之人，以免北方遗迹的危机加剧。")
zh(5094,"部落号召冒险者对抗天灾军团在幽暗城以东的新威胁。德灵顿从亡灵壁垒协调应对，静待愿意协助之人，以免北方遗迹的危机加剧。")
zh(5095,"部落号召冒险者对抗天灾军团在幽暗城以东的新威胁。德灵顿从亡灵壁垒协调应对，静待愿意协助之人，以免北方遗迹的危机加剧。")
zh(5096,"德灵顿担忧同时面对天灾军团与银色北伐军的战事。他希望焚毁血色阵营的指挥帐篷，并留下一面假旗，期盼他们将矛头指向亡灵，避开己方军队。")
zh(5097,"安多哈尔的塔楼或许在协调天灾军团的行动。阿什拉姆需要在它们上标记魔法信号灯，为日后行动做准备，因此你必须突破防御，并谨慎使用装置的有限电量。")
zh(5098,"安多哈尔的塔楼或许在协调天灾军团的行动。德灵顿需要在它们上标记魔法信号灯，为日后行动做准备，因此你必须突破防御，并谨慎使用装置的有限电量。")
zh(5102,"麦克斯韦尔认为对抗巨龙需要暴风城与本土的行动。他下令消灭达基萨斯将军，以对袭击他人民家园与家族的敌人作出决定性回应。")
zh(5103,"焦黑的骸骨躺在那名死者的手中，他似乎正试图触及那些护腕。取回骸骨并逃离烈焰，你便能寻找一个懂得如何处理未完成锻造工作的人。")
zh(5121,"多诺瓦怀疑族长下令饮用某种药剂，使冬泉变得狂暴。她希望在事态恶化前阻止他，但也承认部落已遭受的伤害或许已无法挽回。")
zh(5122,"奥里克斯在教堂庇护下抵抗腐蚀，但若离开则惧怕成为死亡骑士。一枚徽章或许能让他安全离去，因此他需要从血色狂热者手中夺回它。")
zh(5123,"族长的日记内容详尽，但潦草的字迹难以辨认。多诺瓦或许能解读它，从而了解它对熊怪行动的描述，推动对它们准备工作的调查。")
zh(5124,"玛雷弗斯想研究未完成的手套，以还原其配方。若你能提供手套并收集材料，他愿教你打造一套，甚至亲自提供部分金属。")
zh(5125,"奥里克斯病入膏肓，却想用言语表达他对援手的感激之情。他赠予一件物品，希望你继续战斗，愿你的道路超越他的生命终点。")
zh(5126,"罗拉克斯边走边喃喃自语，向你提出提问的机会。倾听这个山羊人，能听他讲述过往，再决定如何应对。")
zh(5127,"罗拉克斯要求古拉鲁克承诺的魂魄与偷来的胸甲。他提供一把恶魔长矛，可用来追捕债务人，并以铁匠寻觅的知识作为交换，让这场交易成为与山羊人谈判的筹码。")
zh(5128,"多诺瓦不再直面冬泉的威胁，但那块木头或许仍能揭示他们的动机。科雷克熟识熊怪，或许能解读其中含义，协助调查他们为何开始制造并食用这种物质。")
zh(5141,"彼得愿教你龙鳞铠甲，只要你能展示技艺与获取材料的能力。选择这条路意味着放弃其他制皮专精，需付出承诺与精良作品与鳞片作为代价。")
zh(5142,"玛莱恩的灵体仍为帕米拉担忧，自达隆郡之战爆发后便隐匿身形。她不知侄女遭遇何事，需你去寻找她，终结生死之外的迷惘。")
zh(5143,"凯雷希亚认为你对野兽皮革的掌控，是迈向部落技艺的关键。她要求你献出最精良的作品作为样本，并警告你，选择这条路意味着放弃其他两种制皮专精。")
zh(5144,"萨拉向那些愿接纳自然之力者传授元素制皮。她需要纯净的精华作为亲和力的证明，并要求你选择一门专精，放弃龙鳞与部落的其他选择。")
zh(5145,"索卡夫·龙眼愿教你打造龙鳞铠甲，只要你展现技艺并能寻得所需材料。选择这条路便舍弃了其他制皮专精，需付出承诺与精良作品与鳞片作为代价。")
zh(5146,"布鲁姆·白蹄向那些愿接纳自然之力者传授元素制皮。他需纯净的精华证明你与自然的亲和，并要求你选定一项专精，放弃龙鳞与部落技法。")
zh(5147,"阿纳克·恐怖图腾被通缉，罪名是谋杀与绑架。赏金要求你将他带到黑云峰附近，并向乱风岗的崖望者呈上证据。")
zh(5148,"塞吉布相信你对野性皮革的掌控，是迈向部落技法的契机。他要求你献上最精良的作品作为样本，并警告你选择这条路便须舍弃其他两项专精。")
zh(5149,"帕米拉·雷德帕斯在家中等待父亲，不安的访客正逼近屋舍。她想念夜晚玩耍的娃娃，请求你帮她在镇上寻回，以缓解她孤独的心绪。")
zh(5150,"达丹加·雷德帕斯似乎期待你带来食物。一头如此体型的草食动物需大量植被，而陨石豆芽正是满足她饥饿的途径。")
zh(5151,"一队遭袭的商队唯一幸存者，遗失了他最珍贵的装置在半人马群中。一只被囚的老虎正佩戴着它，你须面对那头野兽以夺回超导电容器。")
zh(5152,"帕米拉·雷德帕斯不知家人与父亲的下落，仍固执地守在家门前。她相信玛莱恩或许知晓真相，请求你前往安多哈尔探访她的姑姑，以解答他们的失踪之谜。")
zh(5153,"玛莱恩认为天灾军团已腐化了约瑟夫的灵魂，但仍寄望他的命运尚有转机。他的婚戒必须交到克罗米手中，她的力量或许能揭开那些看似不可逆转的真相。")
zh(5154,"克罗米必须先了解约瑟夫的过往，才有可能拯救他。达隆郡的典籍将这段历史封存在安多哈尔，找回那本书便能研究他的命运，并寻找扭转悲剧的方法。")
zh(5155,"格雷塔需要证据证明你反对暗影议会，才会信任你协助她的调查。对抗其加德纳尔势力，揭露他们与军团的密谋，以证明你对费伍德的守护之心。")
zh(5156,"当年有地狱火爪牙在此受召，坑洞至今还在。塔诺恩想知道，里面是否仍有元素生物与被腐化的水。走一趟，他才能看清那场大战留给山谷的创痛还有多深。")
zh(5157,"暗影议会的火盆阻碍了格雷塔窥视其要塞。她需要加德纳尔的月亮井之水，以破解那些魔法防御，进而查明暗影堡中敌方的首领是谁。")
zh(5158,"格雷塔相信伊斯伦与水灵的羁绊能净化样本。将它带到萨满祭司处，请求精神之力协助，这趟任务在她眼中值得他们的支持。")
zh(5159,"伊斯伦归功于水灵净化了水，并请求将它交还格雷塔。这份交付让对抗暗影议会的行动得以继续，同时提醒不要低估该组织的力量。")
zh(5160,"奥比需要哈尔琳知晓被囚禁时所见所感。一片鳞片能让那段经历通过窥视共享，亦可获得飞行队伍守护者的协助，寻求冬泉谷冰洞中的支援。")
zh(5161,"蓝翼知晓死亡之翼的族群有何图谋，但黑石的守护让干预举步维艰。哈尔琳愿以力量助你行动，只待你权衡风险后，方可接受她的援助。")
zh(5162,"哈尔琳将运用她的奥术之力，将你送往咨询耶兹巴。她视他为极富智慧且耐心的智者，能引导她的族群对抗死亡之翼的阴谋。")
zh(5163,"乌米已完成雪怪的打造，渴望用她的发明惊喜朋友。将它带到几个聚居地，于附近启动，再携机器归来，告诉她众人反应如何。")
zh(5164,"耶兹巴邀你查阅目录，了解协助哈尔琳所需之物。其页中记载的皆是危险而值得表彰的使命，若你坚持，终将获得认可。")
zh(5165,"净化之水可用来浇灭火盆——正是它们挡住了格雷塔的目光。趁防御短暂失灵，她便能窥见堡垒内部，认出议会之首是谁。")
zh(5166,"抵御多彩翼族的防护需以所战之物制成胸甲。目录要求非凡的材料与英雄之血，托付耶兹巴打造，以抵御那威胁的攻势。")
zh(5167,"目录描述了一种结合多彩龙鳞、大鳞与英雄之血的铠甲。收集这些材料与特殊衬里，便能委托耶兹巴打造专为对抗多彩飞行者而设的护甲。")
zh(5168,"编年史记载了达隆郡英雄遗落的圣物，散落于战后。卡林寻觅达维的典籍与兄弟破碎的盾牌，二者皆被悲剧所环绕，正是调查所要厘清的真相。")
zh(5181,"典籍亦记载达隆郡的敌人与他们残骸与武器的结局。卡林寻求霍古斯的颅骨与马杜克的断剑，坚信这些遗物与你的工作有所关联。")
zh(5201,"雷沃目睹熊怪杀害仅路过其路径的生物。他对他们的暴戾习以为常，亟需将他们隔绝于他训练霜刃豹的岩石之地，守护自己的成果，而无需激怒他们的敌意。")
zh(5202,"那把红钥匙看似由骨制成，奇重且易碎。在主教议会成员中发现它，令人费解：探索加德纳尔或许能揭开为何其中一名仆从携带它的谜团。")
zh(5203,"阿尔科·纳林要逃出去向上峰复命，得先取回自己的装备与特里的剑。她求你护她突围，事成之后再去知会杰希尔——同伴正在灰谷附近等消息。")
zh(5204,"杰希尔担忧特里的酷刑与死亡会持续纠缠阿尔科·纳林，即使她试图掩盖痛苦。她希望处决施刑者，并取回其残骸，让好友在哀悼时获得些许安宁。")
zh(5206,"克罗米需要来自达隆郡战士的颅骨作为另一道法术材料。水晶能辨识他们于天灾勇士之中，补全了通过英雄与敌人遗物收集的材料。")
zh(5210,"克罗米的魔法为典籍添页，将达隆郡的历史延伸至战役之外。卡林幸存于这场悲剧，或许能协助继续调查，因此请将扩充后的书卷带给他。")
zh(5211,"许多达隆郡的守卫者如今以亡灵之姿重生为天灾的仆从。卡林希望摧毁那些禁锢他们灵魂的亡灵形态，终结这场战役后仍在延续的苦难，释放昔日的镇民。")
zh(5212,"种种迹象让贝蒂娜看出，这场瘟疫非但没有减弱，反倒更凶了。她要用斯坦索姆新近染病者的血肉再做几番检验，好证实钻研多年的疫病出了什么可怕的变故。")
zh(5213,"贝蒂娜希望将调查延伸至斯坦索姆的阶梯神殿，这些建筑是天灾军团汲取力量的源泉。她渴望获取其中情报，以更清楚地了解敌人如何维持其强盛。")
zh(5214,"当艾兹拉拒绝在斯坦索姆沦陷时放弃店铺，黑烟便离开了他。他以为店主死于烈焰，却仍期盼珍藏的烟草幸存，嘱托你前去搜寻残骸。")
zh(5215,"天灾军团的瘟疫之锅正向昔日的洛丹伦散播毒药。凯尔·萨鲁斯的力量使它们无法被直接关闭，但玛多妮尔能解释如何利用其内容物对抗疾病，她需要你的协助。")
zh(5216,"玛多妮尔认为费尔斯通的瘟疫之锅是调查的最便捷入口。她需要守卫的钥匙与一份毒药样本，以研究如何制备对抗瘟疫的解药。")
zh(5217,"费尔斯通的样本已收集于瓶中。带它去见玛多妮尔，研究瘟疫之锅的混合物，继续准备对抗天灾军团释放毒气的对策。")
zh(5218,"瘟疫之锅仍在释放毒素，但已回收的钥匙可开启其机制。加入适当的药剂，便能利用敌人的设施对抗它所传播的疾病。")
zh(5219,"每个瘟疫之锅使用的毒药配方各异，因此调查仍需另一份达尔松之泪的样本。玛多妮尔请求你击败守卫并开启装置，以扩展对抗瘟疫扩散所需的知识。")
zh(5220,"瓶子中已装入达尔松大锅的样本。将它交给玛多妮尔，便能继续研究天灾军团的混合物，寻找能对抗其毒药的解药。")
zh(5221,"大锅仍在释放毒气，但找回的钥匙可开启其机关。加入合适的药剂，便能制备对抗瘟疫的解药，以敌制敌。")
zh(5222,"开启更多大锅将提供更多机会，引入对抗瘟疫的解药。玛多妮尔如今锁定安多哈尔附近的大锅，需要钥匙与样本，扩大行动范围。")
zh(5223,"第三口大锅的物质已采集完毕，随时可运往研究处。玛多妮尔需要它继续研究天灾混合物，扩充情报，为干预西部设施做准备。")
zh(5224,"大锅仍在释放毒气，但找回的钥匙可开启其机关。加入合适的药剂，便能制备对抗瘟疫的解药，以敌制敌。")
zh(5225,"最后一口大锅由更危险的敌人守护，包括幽魂与鬼魂。玛多妮尔需要开启它并采集样本，完成对西部设施的渗透，即使那片农场防御更严。")
zh(5226,"最后一口大锅的样本已封存于瓶中。将其交给玛多妮尔，完成采集工作，为调查提供西部农场所用毒药的样本。")
zh(5227,"大锅仍在释放毒气，但找回的钥匙可开启其机关。加入合适的药剂，便能制备对抗瘟疫的解药，以敌制敌。")
zh(5228,"瘟疫之锅在昔日洛丹伦散播毒药。凯尔·萨鲁斯的力量阻止它们被直接关闭，但范蒂丝能解释一个计划，将它们的内容物转为对抗疾病的武器，她需要你的协助。")
zh(5229,"范蒂丝认为费尔斯通的熔炉是最容易入手的调查起点。她需要其守护者的钥匙与一份毒药样本，以研究如何制备对抗瘟疫的解药。")
zh(5230,"费尔斯通的样本已被装入瓶中。将它带给范蒂丝，研究熔炉的混合物，继续准备对抗天灾军团释放毒气的对策。")
zh(5231,"每个熔炉使用的毒药配方各不相同，因此调查还需另一份达尔松之泪的样本。范蒂丝请求击败其守护者并开启装置，以获取对抗瘟疫扩散所需的知识。")
zh(5232,"瓶子现在装有达尔松熔炉的样本。将它带给范蒂丝，便可研究另一种天灾混合物，继续寻找能对抗其毒药的解药。")
zh(5233,"开启更多熔炉将提供更多机会引入瘟疫解药。范蒂丝现在将目标锁定安多哈尔附近的熔炉，需要其钥匙与样本，扩展行动范围，超越最初的两个入口。")
zh(5234,"第三座熔炉的物质已被收集并准备运输。范蒂丝需要它继续研究天灾的混合物，扩大可用信息，为干预西部装置做准备。")
zh(5235,"最后一座熔炉由更危险的敌人守护，包括幽魂与鬼魂。范蒂丝需要开启它并采集其混合物，完成对西部装置的访问，尽管那座农场的防御更为顽强。")
zh(5236,"最后一口大锅的样本已封入瓶中。将它带给范蒂丝，以完成收集工作，也为调查提供西部农场所用毒药的证据。")
zh(5237,"阿什拉姆想公开表彰你对抗大锅的功绩，并承认在联盟服役所面对的危险。他赠送嘉奖与赏金，以表对你协助对抗祸害鼠行动的感谢。")
zh(5238,"重造大锅之举赢得亡灵的赞誉。高级执行官提供赏金，并公开肯定你为他族与部落所付出的服务。")
zh(5241,"帕米拉听闻古卡尔在哭泣，担心他的悲伤是为她而起。找到他，解释她安然无恙，正等待听她最爱的故事。")
zh(5242,"费尔丹与军团缔结盟约，操控暗影堡下的威胁。别无他途，须正面突袭他与两名仆从。")
zh(5243,"莱尼德将不死之力用于银色黎明，而非天灾军团。他需从斯坦索姆的补给箱中取回圣水，重获城中尚存的储备。")
zh(5244,"凯尔·瑟里尔的上层精灵曾试图夺取遗物之力，因而与遗迹结界。加隆近日造访现场，可解释那场灾难仪式的过往。")
zh(5245,"灵体仍在寻找诅咒他们的遗物残片。寻回冰层下的碎片，让极光得以审视一件比加隆更易理解的物件。")
zh(5246,"极光相信这些碎片属于辛玛洛水晶，它能封存强大的奥术之力。水晶神殿的典籍或许能提供研究这件遗物、修复远古伤痕所需的知识。")
zh(5247,"重新凝聚水晶需要具备强大魔力的材料。极光研究如何修复水晶的同时，你需要收集能填补其裂痕的组件，包括厄运之槌池塘中的水。")
zh(5248,"修复后的水晶提供了一个机会，去承认并弥补过往的部分伤痕。极光希望它被带到凯尔·瑟里尔，并展示给一个能识别其原主人错误的灵体。")
zh(5249,"冬泉谷藏有精灵遗迹与秘密，但你的联系人正忙于费伍德森林无法探索。维恩德熟悉这片严酷之地，若你前往坠星村，他可为你引路。")
zh(5250,"你的研习可在冬泉谷的废墟间继续。老师无暇同行，将你引荐给维恩德——你只须自称学生，他自会指点。")
zh(5251,"血色狂热已让无辜者在光之名下蒙受苦难。加尔福特守护着水晶最珍视的典籍，而你的联系人却要求处死档案管理员，并焚毁那些典籍。")
zh(5252,"一个灵体承认了上层精灵的错误，并在水晶的修复中找到慰藉。它坚持这件遗物必须归还；维恩德或许能指出它该被送往何方。")
zh(5253,"水晶的神殿已无法再接收它，它的力量需要有责任心的手来守护，而非滥用。维恩德建议将它送往达纳苏斯的范达尔，作为这件修复遗物的妥善归宿。")
zh(5261,"北郡狼群数量日益增多，恰与埃根寻找猎人不谋而合。拜访他，可得知如何协助应对山谷当前的局势。")
zh(5262,"十字军统领的陨落揭开了与瓦里玛萨斯有关的恐惧魔王。瑟伦霍夫公爵需要听闻这一发现，恶魔的头颅将作为真相的铁证，否则难以置信。")
zh(5263,"瑟伦霍夫公爵视你的纪律与破坏力为神罚的工具。他希望你在对抗斯坦索姆的领主时证明自身价值，将他的头颅带回作为凭证。")
zh(5264,"麦克斯韦尔元帅欲以非同寻常的方式表彰你对银色黎明的贡献。前往教堂，见一位多年未曾接待外客的领袖。")
zh(5265,"银色黎明的赏金箱多年未曾开启。如今因你的价值被认可，得以开启，让你获得组织专为值得信赖的盟友保留的力量。")
zh(5281,"许多斯坦索姆的居民试图逃避成为天灾军团的仆从，却仍徘徊于无尽的痛苦中。埃根正在调查如何帮助这些灵魂，找到他，了解他的方法。")
zh(5282,"埃根能分辨无辜的灵魂与他憎恶的敌人。他的武器专为解放斯坦索姆的痛苦灵体而设，在他人眼中只是亡灵的残骸，他却以怜悯对待。")
zh(5283,"防御是你技艺的根基。你的导师希望你在精工秘银中展现天赋，再磨砺技艺，方能被接纳为锻造师，与偏重武器制造者一较高下。")
zh(5284,"武器锻造为英雄与冒险者提供生计，你的导师要求你以实践证明，你足以承担这份严苛而有利可图的技艺。")
zh(5301,"你的导师以见证部落战士身披铁甲为荣，他愿开始教导，但须先完成一项任务，以证明你已准备好踏上锻造之路。")
zh(5302,"你的导师渴望打造一柄配得上战酋的重锤，他看见你潜质，将借一项任务展现你的能力，再开启专精训练。")
zh(5305,"锤匠专精需直面守卫平静配方的铁匠，他的围裙将证明你的胜利，换取教导，也封存其他专精之路。")
zh(5306,"基尔拉姆曾被沃什·加金所伤，渴望复仇。取回她的蛇石，将证明你击败了猎手，换取打造斧头的专精技艺。")
zh(5307,"黑卫盗走了腐蚀的计划，其剑匠守护于斯坦索姆。你的导师要求你摧毁这位男爵的仆从，并带回证据，方可开启剑匠专精。")
zh(5321,"一位旅人从翡翠梦境中苏醒后便不断昏睡，他需要护卫送他抵达目的地，还需一只号角唤醒他，以防旅途无助。")
zh(5341,"阿莱克斯与他的人类兄弟争夺巴罗夫家产，其地产契约仍存于通灵学院。率先取回，便可让赞助人抢先一步，胜过觊觎继承的对手。")
zh(5342,"阿莱克斯视活着的弟弟为家族财富的持续威胁。他执意要除掉对方，即便有联盟的保护，你承诺的赏金也取决于你是否参与这场致命的继承之争。")
zh(5343,"维尔顿懊悔当初放过亡灵弟弟，如今对方觊觎同样的继承权。他必须在阿莱克斯之前取回通灵学院的文件，确保这笔财富归自己独享。")
zh(5344,"文件已取回，但维尔顿担心阿莱克斯可能派雇佣兵对付他。他要彻底解决家族纷争，让受部落保护的弟弟命丧黄泉，并要取其首级。")
zh(5361,"一年前两兄弟最后一次通信，如今半人马的行动已悄然改变。将报告送至纳塔卡手中，既更新凄凉之地的战况，也维系那份血脉相连的情谊。")
zh(5381,"火刃氏族借助埃鲁索斯之手开启传送门，招来更多恶魔。进入堡垒夺取那件法器，遏制他们的渗透与扩张。")
zh(5382,"艾娃将千人命案归咎于瑟尔林·卡斯迪诺夫，要求为受害者讨回公道。阻止医生之后，焚毁她的遗骸与卢森的尸身，将残余化为灰烬。")
zh(5384,"无辜者的鲜血安抚了基尔图诺斯，如今能引他至火盆。艾娃想借同样的联系与他抗衡，为他手下的亡魂复仇。")
zh(5385,"特雷的遗骸终将归还杰希尔与同伴。将麻袋交予他，愿他们能妥善照料，让这位圣骑士得到他应得的尊重。")
zh(5386,"半人马的活动让你的联络人无法前往他最爱的渔场。金扎林·吉伦能为葬影村提供补给，将渔获送至村中，是驻守此地的日常所需。")
zh(5401,"银色黎明委任徽章让你能代表其战斗并收集天灾军团档案。组织认可你的付出，并以勇气勋章奖励你对抗亡灵的证据。")
zh(5402,"爪牙的天灾军团档案能识别普通军团士兵，即便他们地位不高，仍具威胁。银色黎明以勇气勋章奖励收集其徽章的行动。")
zh(5403,"精英军团士兵携带的档案标记着尤为艰难的战斗。收集这些石块，可换取银色黎明的勇气勋章，表彰你对抗敌人的决心。")
zh(5404,"军团领袖掌有象征权威的档案石。击败这些强敌是对组织的重大打击，银色黎明亦以勇气勋章奖励其徽章。")
zh(5405,"银色黎明委任徽章记下你在这场战事中的身份，也准你捡取天灾石。上交之后，军需官便取出为效力之人留存的赏赐。")
zh(5406,"银色黎明凭那独特的石头，辨认被击杀的天灾首领。取回一枚，即意味着直面一名强敌——此人一倒，维系其部众的指挥便随之松动。")
zh(5407,"入侵者档案来自特别强大的军团士兵。交出这些石块，展现你对抗精英的行动，可换取银色黎明的勇气勋章。")
zh(5408,"银色黎明也重视对抗普通士兵。天灾军团爪牙所携带的石头象征着他们的贡献，可换取英勇勋章，但绝不可低估这些敌人仍具的威胁。")
zh(5421,"你的联系人不愿亲自从码头下的陷阱中搜集贝壳。每带来五颗贝壳，便可换取一条血肚鱼，作为替他完成这项工作的回报。")
zh(5441,"工人们午睡打乱了山谷中的木材采集。他们的工头给了你一把黑杰克，用来唤醒睡着的工人，待他们复工后再将工具归还。")
zh(5461,"让拉斯成为凡人，需要一件与他过往生活相连的物品。许多亡灵会摧毁这类提醒，因此前往他昔日的斯坦索姆故居，寻找仍存留的遗物。")
zh(5462,"这件遗物必须与拉斯向巫妖王献出生命的地点产生共鸣。据说此事发生在斯坦索姆，莱尼德或许能辨认出仪式所需的地点。")
zh(5463,"莱尼德目击了拉斯的转变，清楚他向巫妖王献祭的地点。将遗物置于那里，可延续一项旨在连接亡灵与人类过往的仪式。")
zh(5464,"与过往生活的联系已使遗物产生变化，将沉睡的灵魂吸引至其上。将这件物品带回莱尼德处，以这建立的精神纽带继续仪式。")
zh(5465,"马杜克需要这件灵魂绑定的遗物，好向他解释其用途。返回凯尔达隆，可继续筹备，待向亡灵展示与他过往相连的物品。")
zh(5466,"这枚信物可通过仪式恢复拉斯的凡人之躯，仪式要求你承受他的攻击。唯有如此，这位前法师才能被击杀，人类对其失败的见证也将随之重现。")
zh(5481,"葛尔多的手无法为霍兰德仔细采集所需草药。协助收集，能支援布瑞尔日常补给的实际需求。")
zh(5482,"霍兰德收到的植物有误。在大量墓穴附近寻得正确草药，即便豺狼人游荡其间，他的工作仍可继续。")
zh(5501,"科多兽骨有买家将其制成家具、乐器，甚至爆破粉末。你的联系人想为商队换取更多，愿以报酬换取你在南方墓地采集的兽骨。")
zh(5502,"你的结界享受了儿童周，如今想返回孤儿院讲述这段经历。陪同他回家，既结束拜访，也延续你榜样的希望。")
zh(5503,"银色黎明向愿意以它的名义对抗天灾军团的人提供任务。佩戴它，可收集敌方石像鬼，换取认可与补给物资的准入。")
zh(5504,"银色黎明认可你的奉献，提供可提升肩甲魔抗的披风。所需勇气徽章将证明持续服务，方能完成购买。")
zh(5505,"钥匙已铸成，只等你在通灵学院一试。你的盟友信得过这手艺，可门是否真会开启，只有亲手用过才见分晓——那之后你才能继续往里走。")
zh(5507,"银色黎明认可你的付出，赐予你可提升肩甲魔抗的护腕。所需勇气勋章将证明你的持续效忠，方能解锁这项装备。")
zh(5508,"天灾领袖佩戴的石印象征其权威。击败这类强大存在将重创其组织，银色黎明为此授予勇气勋章。")
zh(5509,"精英天灾部队佩戴的石印标志殊死搏斗。收集这些印记，可换取银色黎明的勇气勋章，以表彰你在瘟疫之地对抗敌人的贡献。")
zh(5510,"爪牙石印标记着普通天灾士兵，尽管地位低微，仍具威胁。收集这些印记，银色黎明将授予勇气勋章，以表彰你对抗其势力的努力。")
zh(5511,"德灵顿将完成的钥匙交予你手。他相信钥匙能开启大门，却敦促你亲自试用，让对门内藏匿敌人的讨伐行动得以持续。")
zh(5513,"银色黎明认可你的付出，赐予你可提升肩甲魔抗的护腕。所需勇气勋章将证明你的持续效忠，方能解锁这项装备。")
zh(5514,"这模具需克林科在加基森的技艺与不菲报酬。带上准备好的碎片，支付所需费用，方能继续打造钥匙。")
zh(5515,"基尔图诺斯尚在人世，而召唤他的方法正被迫切需要。詹迪斯据说携有无辜者之血献给主上；搜寻她的物品，或能找到对抗他的手段。")
zh(5517,"银色黎明的卓越服务，可解锁一件能同时抵御多种魔法的披风。所需英勇勋章象征着获取这份专属奖励所需的代价。")
zh(5518,"破绳结能制作一套奥格兽皮面具，可混入克罗卡斯而不必杀他。他需要不稳定材质，仅能短暂生效，以应对戈多克大王的对峙。")
zh(5519,"奥格面具可能失效，破绳结仍可随时重制。重新收集材料，便能继续使用这套能短暂骗过戈多克的伪装。")
zh(5521,"银色黎明的卓越服务，可解锁一件能同时抵御多种魔法的披风。所需英勇勋章象征着获取这份专属奖励所需的代价。")
zh(5522,"莱尼德的讯息声称传达了维克图斯的指令，要将龙蛋送往指定地点。收件人虽存疑虑，仍接受任务，需你将龙蛋送至圣光之愿号礼拜堂。")
zh(5524,"银色黎明的卓越服务，可解锁一件能同时抵御多种魔法的披命。所需英勇勋章象征着获取这份专属奖励所需的代价。")
zh(5525,"破绳结仍被戈多克囚禁，需钥匙才能脱困。奥格们或许携有此物，尤以守卫为然；若能取得，便有机会在他沦为盘中餐前将其释放。")
zh(5526,"奥兹恩的腐化势力笼罩东部艾尔德雷萨拉斯，那里的丰饶之果仍存。收集其精魄，封入骸骨室，使携带者在运输途中免受其害。")
zh(5527,"魔藤样本需盛装于容器之中，以保护携带者。净化之匣或许可以盛放，但你必须在南风裂谷的遗迹中寻找那枚多年前曾在此处的容器。")
zh(5528,"克雷格将为如今认作上司的你提供免费试饮，品尝他最上乘的饮品。这些酒浆承诺会带来强化效果，同时带来愉悦的醉意。")
zh(5529,"天灾军团正在通灵学院培育祸害鼠龙，银色黎明忧心他们的扩张。阻止这些幼龙成长，别让这研究成为席卷艾泽拉斯的灾祸。")
zh(5531,"这些回收的龙卵本可加速天灾军团对祸害鼠龙的实验。贝蒂娜拥有科学与炼金知识，可为对抗这项研究提供支援，将卵带给她继续努力。")
zh(5533,"一扇锁门阻隔了通灵学院核心的亡灵之地。阿尔比顿熟悉此地，他掌握了一种获取钥匙的方法，使天灾军团的活动得以调查与抗衡。")
zh(5534,"金吉亚尔的报酬取决于你能否在另一任务中证明自己的价值。他想要一枚被血精灵追寻、如今藏于艾尔达拉斯遗迹中娜迦手中的符文。")
zh(5535,"上层精灵的灵体被奥术腐蚀缚在它们盘桓的土地上，不得脱身。洛哈图答应助哨兵解开这道束缚，并在影歌神殿附近出钱雇人从旁协助。")
zh(5536,"萨特们亵渎了塞纳留斯曾踏足的圣域。洛哈图向大地母亲起誓，将协助精灵驱逐他们；对抗哈达尔便是履行此誓的一部分。")
zh(5537,"通灵学院的钥匙融合了骨骸、坚金属与一枚强大力量的徽记。第一步是收集安多哈尔骷髅的碎片，以备锻造之需。")
zh(5538,"模具需要克林科·古德斯迪尔在加基森的技艺，以及一笔可观的报酬。带上准备好的碎片，并支付所需费用，继续打造钥匙。")
zh(5541,"一名信使在逃亡雪怪时遗落了弹药。供应本地步枪手的商人正等待这批货物，找回木箱能避免附近部队训练的弹药短缺。")
zh(5542,"提里奥请求你若打算留下，帮忙清除周围的威胁。首要敌人是瘟疫犬，他愿以食物与交谈为酬劳，换取你与它们一战。")
zh(5543,"瘟疫之地的野生动物也变得凶残，威胁着旅人。提里奥希望减少从天而降的蝙蝠袭击，这些危险已主宰了森林。")
zh(5544,"提里猛的粮食储备日渐见底，急需冬季补给。腐肉虫肉耐储存，且与其他野兽不同，它们未受瘟疫侵蚀。")
zh(5545,"森林动物已驱赶工人离开已砍伐的木材。找回那些捆包，可趁守卫应对野兽威胁之际，完成一项紧急订单。")
zh(5561,"商队依赖你联系人设备控制的复生驮兽。带回年迈或濒死的动物，以维系这桩贸易，利用那台让它们跟随你前往目的地的机器。")
zh(5581,"埃鲁索斯之手能关闭加固曼诺洛克恶魔的传送门。威胁正在加剧，将神器带到此处可切断那股涌动，但须留意守护传送门的守卫。")
zh(5582,"健康鳞片在瘟疫龙崽的病态纹路中格外显眼。贝蒂娜想研究这处例外，这枚样本或许能成为她调查生物的重要证据。")
zh(5601,"一位洛丹伦幸存者担心家人死于达隆郡之战。寻找妹妹帕米拉，或许能揭开她留下的亲人究竟遭遇何事。")
zh(5621,"莎恩雅在多兰纳尔附近巡逻时受了伤，你的导师无法离开其他学生。治愈并强化她，便是直接帮助一名哨兵，践行对艾露恩的承诺。")
zh(5622,"劳尔娜能继续你的艾露恩之道研究，并助你获得第一套牧师圣袍。她的邀请将带你前往多兰纳尔，待你完成附近的职责后。")
zh(5623,"你在光之中的进步，让北郡的课程得以拓展。洁塞塔在闪金镇等待，待你完成仍需处理的职责后，继续你的宗教修行。")
zh(5624,"罗伯兹在湖边受了伤，亟需援助。治愈并强化他，将取代以往的试炼，证明你配得上代表你在教会中地位的圣袍。")
zh(5625,"一名受伤的巡山人亟需帮助，近卡拉诺斯处。以牧师之礼相助多尔夫，既回应那迫切需求，也展现你配得上圣袍的资格。")
zh(5626,"马克萨恩·安沃尔可助你在卡拉诺斯继续光之训练。若你证明己经准备就绪，还将获得第一件圣袍，象征你作为牧师的职责与使命。")
zh(5627,"阿兰希雅认为你已具备学习月神追随者独特教义的资格。她以与女神及你族传统相关的礼物，延续你的牧师训练。")
zh(5628,"阿兰希雅已遣信使召你回月光神殿。你的牧师修行还需在达纳苏斯再谈一次——届时她会说明这道急召的缘由。")
zh(5629,"你的进步已引起长老们的注意，他们认为你已准备好迎接更大的挑战。阿兰希雅派人寻找你，务请抽空完成自身训练，并前往达纳苏斯的月光神殿寻她。")
zh(5630,"阿兰希雅已遣信使召你回月光神殿。你的牧师修行还需在达纳苏斯再谈一次——届时她会说明这道急召的缘由。")
zh(5631,"阿兰希雅已遣信使召你回月光神殿。你的牧师修行还需在达纳苏斯再谈一次——届时她会说明这道急召的缘由。")
zh(5632,"阿兰希雅已遣信使召你回月光神殿。你的牧师修行还需在达纳苏斯再谈一次——届时她会说明这道急召的缘由。")
zh(5633,"阿兰希雅已遣信使召你回月光神殿。你的牧师修行还需在达纳苏斯再谈一次——届时她会说明这道急召的缘由。")
zh(5634,"洛汗已遣人召你重返秘法区。信中催促你尽快赴约，由高阶牧师亲自阐明下一步的指引。")
zh(5635,"暴风城的召唤将你引向大教堂，继续接受牧师的修行。你须返回与劳瑞娜相见，她将指引你服务光明的下一阶段。")
zh(5636,"暴风城的召唤将你引向大教堂，继续接受牧师的修行。你须返回与劳瑞娜相见，她将指引你服务光明的下一阶段。")
zh(5637,"暴风城的召唤将你引向大教堂，继续接受牧师的修行。你须返回与劳瑞娜相见，她将指引你服务光明的下一阶段。")
zh(5638,"暴风城的召唤将你引向大教堂，继续接受牧师的修行。你须返回与劳瑞娜相见，她将指引你服务光明的下一阶段。")
zh(5639,"暴风城的召唤将你引向大教堂，继续接受牧师的修行。你须返回与劳瑞娜相见，她将指引你服务光明的下一阶段。")
zh(5640,"正如艾露恩的追随者学习各自信仰的独特恩赐，你的教派亦有专属的教诲。你该向高阶女牧师请教，继续精进修行。")
zh(5641,"洛汗邀你前往铁炉堡，因你的牧师传统中另有一场试炼即将展开。速往秘法区，了解属于你族的仪式与教义。")
zh(5642,"传讯者急切寻觅兽人牧师，你须返回精神谷，探听奥格瑞玛近况，并回应师长的召唤。")
zh(5643,"导师认定你已具备在牧师传统中践行仪式的资格。乌尔基奥将引导你学习一门助你走过灵性之路的课程。")
zh(5644,"你的进展要求你重返艾萨莱斯特，学习亡灵特有的教诲。某些知识唯有她能传授，你必须与她相见，方能继续牧师训练。")
zh(5645,"洛汉召唤你前往铁炉堡，传授你族特有的教义。回应他的召唤，将助你了解即将迈入的牧师训练阶段前的试炼。")
zh(5646,"你的进展要求你重返艾萨莱斯特，学习亡灵特有的教诲。某些知识唯有她能传授，你必须与她相见，方能继续牧师训练。")
zh(5647,"盟友认可你族的强盛与进步。铁炉堡传来讯息，召唤你前往秘法区的洛汉，继续你的牧师之路。")
zh(5648,"柯尔贾曾与普罗德摩尔旧部交战受创。治愈她并献上祖先的祝福，既可提供迫切援助，亦是检验你是否具备继续族中牧师传统的准备。")
zh(5649,"与部落结盟，并未抹去你族旧日的规矩。泰金在剃刀岭传授族史与习俗——只是有些传统，仍需暗中操持。")
zh(5650,"你的导师希望你理解治疗与黑影的平衡。协助伤员凯尔，便是将这种平衡应用于守护布瑞尔的百姓。")
zh(5651,"被遗忘者牧师的训练强调光明与黑影的结合。在贝里尔的经历，延续了这种教诲，展现了一个族群在腐化后重拾意志的历程。")
zh(5652,"一名信使已先行召回你，以免你走得太远。乌库里想在奥格瑞玛的精神谷与你相见，你的训练仍需与族中的牧师继续。")
zh(5654,"乌库里要求你前往奥格瑞玛，接受专属于你族群的教导。你必须回到精神谷，向能引导你成长的牧师学习。")
zh(5655,"乌库里要求你前往奥格瑞玛，接受专属于你族群的教导。你必须回到精神谷，向能引导你成长的牧师学习。")
zh(5656,"乌库里要求你前往奥格瑞玛，接受专属于你族群的教导。你必须回到精神谷，向能引导你成长的牧师学习。")
zh(5657,"乌库里希望检视你的精神进展。他的召唤将你引向奥格瑞玛，继续与你的牧师传统相连的教导。")
zh(5658,"艾萨莱斯特需要你返回幽暗城，接受唯有她能传授的教导。速往军事区，继续你牧师传统的专属训练。")
zh(5660,"艾萨莱斯特召唤年轻被遗忘者牧师归家。前往幽暗城寻她，可获得唯有她能传授的信仰教义，旅途之中亦可延续修行。")
zh(5661,"艾萨莱斯特召唤年轻被遗忘者牧师归家。前往幽暗城寻她，可获得唯有她能传授的信仰教义，旅途之中亦可延续修行。")
zh(5662,"艾萨莱斯特召唤年轻被遗忘者牧师归家。前往幽暗城寻她，可获得唯有她能传授的信仰教义，旅途之中亦可延续修行。")
zh(5663,"艾萨莱斯特召唤年轻被遗忘者牧师归家。前往幽暗城寻她，可获得唯有她能传授的信仰教义，旅途之中亦可延续修行。")
zh(5672,"暗夜精灵牧师已至学习专属能力之龄。阿兰希雅须先试你是否准备就绪，方能传授艾露恩之恩赐；你的修行，引你前往月光神殿。")
zh(5673,"你的下堂课，关乎侍奉艾露恩者独有的馈赠。阿兰希雅在月光神殿静候，试你是否已准备好，继续传授唯有她能给予的教义。")
zh(5674,"你的下堂课，关乎侍奉艾露恩者独有的馈赠。阿兰希雅在月光神殿静候，试你是否已准备好，继续传授唯有她能给予的教义。")
zh(5675,"你的下堂课，关乎侍奉艾露恩者独有的馈赠。阿兰希雅在月光神殿静候，试你是否已准备好，继续传授唯有她能给予的教义。")
zh(5676,"你的上级召唤你前往暴风城接受进一步训练。你的联络人虽不信任魔法，却尊重你们族群间的联盟。劳瑞娜将在光明大教堂等候，向你讲述新的教义。")
zh(5677,"你的族人召唤你重返暴风城，继续接受牧师的训练。劳瑞娜能传授专属于你教派的教义，其中包括一些知识，令其他文化背景的导师心生疑虑。")
zh(5678,"你的族人召唤你重返暴风城，继续接受牧师的训练。劳瑞娜能传授专属于你教派的教义，其中包括一些知识，令其他文化背景的导师心生疑虑。")
zh(5679,"艾萨莱斯特尊重盟友的传统，将他们的牧师送回各自的导师处。如今轮到你重返幽暗城，她将教你更多关于你们族群与战争区的过往。")
zh(5680,"你的导师察觉，你族的成年礼已近在眼前。他们的教诲或许关乎存亡。返回奥格瑞玛的精神谷，与乌尔基奥交谈。")
zh(5713,"一名使者在熊怪袭击中被毒伤，几乎站立不起。保护她直至她调配解药，或许能让她继续将重要情报传递至奥伯丁。")
zh(5721,"这些圣物可唤醒达隆郡的灵体，重现昔日之战。在关键时刻介入，设法拯救约瑟夫的灵魂，让他的盟友存活至他身上的腐化被彻底面对。")
zh(5722,"玛加萨的仆从在洞穴中发现异样，从此再未归来。寻找他的遗骸与任何有价值之物，或许能厘清他试图接触地穴族时发生了什么。")
zh(5723,"穴居人从奥格瑞玛地底现身，杀死了前来谈判的牛头人使节。玛加萨视他们为威胁整个部落的隐患，要求尽快将其制服，以免洞穴被彻底占据。")
zh(5724,"死去的牛头人被穴居人围攻时仍紧握着一个帆布袋。将它带出洞穴交给拉哈罗，能揭示他试图守护的秘密。")
zh(5725,"希尔瓦娜斯想要两本由灼热之刃派系保管的法术书，该派系隶属暗影议会。你被派去从奥格瑞玛地底的洞穴取回，亲手交到她手中。")
zh(5726,"萨尔希望揪出叛徒，却不惊动整个网络。你的冒险者身份能让你获取火刃氏族的徽记，为秘密调查提供掩护。")
zh(5727,"萨尔知道尼尔鲁不忠，却要先用尽他的门路再动手。寻回的徽记或许能让你扮作那术士的同党，探出他把什么消息递了出去。")
zh(5728,"收集到的情报锁定两名灼热之刃首领为首要目标。你必须在尼尔鲁察觉你的介入前将他们清除，维持秘密身份以延续调查。")
zh(5729,"尼尔鲁的焦躁或许会让他更愿意信任你。萨尔希望你加深这段联系，以探知火刃氏族，甚至暗影议会的更多真相。")
zh(5730,"尼尔鲁视你为副官，说起洞窟出事之后要重整手下。这份信任正是你必须维系的一线联系——他的图谋正伸向别处。")
zh(5741,"火刃氏族或许已获得一根传说中能沉没整座城市的娜迦权杖。从他们的先知手中夺回它，将阻止这个团体保有这件足以造成毁灭性影响的武器。")
zh(5742,"提里奥认可你所付出的努力，也愿意给予片刻休憩。他想借这个间隙正式向你自我介绍，并与你交谈。")
zh(5761,"奥格瑞玛地底的恶魔势力牵动着守护这座城池的人们。铲除率领灼热之刃的恶魔守卫，旨在阻止这个团体腐蚀部落无辜的成员。")
zh(5762,"包裹辗转数周才抵达，而赫米特早已前往荆棘谷。商人想维持与这位富裕客户的良好关系，必须在他新设的狩猎营地完成交付。")
zh(5763,"狩猎让你的联系人与赫米特暂时忘却了彼此族群的仇恨。一根科多兽角承载着重修旧好、再度在凄凉之地共度狩猎时光的邀请。")
zh(5781,"提里尼希望泰兰能重拾一段童年回忆。他的玩具重型钉锤被埋在父亲的假墓中，寻回它将是弥补他所失去之物的第一步。")
zh(5801,"这种霉菌需要火山的高温才能将骨头与钍融合成钥匙的柄部。在乌纳戈的熔岩中加热后，再返回阿尔比顿完成最后的工序。")
zh(5802,"打造钥匙需要在极端高温下将骨头与钍熔合。模具可在乌纳戈火山的顶峰使用；之后，迪瑟斯必须继续加工成品。")
zh(5803,"阿拉基的徽记将补全钥匙，因其主人曾知晓如何进入通灵学院。在安多哈尔阻止召唤者，也将切断他对城市的控制，同时获得所需组件。")
zh(5804,"完成钥匙需取得通灵学院前领袖的徽记。阿拉基藏身安多哈尔，与他交锋既能掌控那股力量，也挑战他对遗迹的统治。")
zh(5805,"礼物兑换券可让你获得一位旅途伙伴。将它交给北郡山谷的梅里萨·斯蒂维尔，便是领取珍藏版礼物的一步。")
zh(5821,"半人马战鼓已中断商队的常规行程。商队主人愿付酬金，以保他们的驮兽能安然通过科尔卡村，使生意不受损失。")
zh(5841,"礼物兑换券可让你获得一位旅途伙伴。将它交给寒脊山谷的尤里·碎盔，便是领取珍藏版礼物的一步。")
zh(5842,"礼物兑换券可让你获得一位旅途伙伴。将它交给幽影谷的奥雷希尔·语风，便是领取珍藏版礼物的一步。")
zh(5843,"礼物兑换券可让你获得一位旅途伙伴。将它交给试炼谷的玛卡尔，便是领取珍藏版礼物的一步。")
zh(5844,"礼物兑换券可让你获得一位旅途伙伴。将它交给纳拉其营地的沃恩·星眼，便是领取珍藏版礼物的一步。")
zh(5845,"泰兰在乌瑟尔死后，因认为银手军团已失其本义而放弃旗帜。从北谷取回它，将唤醒他舍弃的荣誉记忆。")
zh(5846,"瑞弗蕾的画作保存着提里奥最珍贵的妻儿回忆。前往凯尔达隆搜寻，或许能重拾那份家族羁绊，若画作或画家尚在其中。")
zh(5847,"欢迎券可让你获得一位旅途伙伴。你必须将它交给夜色镇的克莱尔·韦洛，才能获得与典藏版相连的礼物。")
zh(5848,"瑞弗蕾在提里奥受审后，将家族画像藏于另一幅画下。前往如今位于血色堡垒内的旧工坊，可寻回她守护的影像。")
zh(5861,"纪念品必须送达泰兰，但他的十字军会攻击外来者。麦兰达可助你伪装，提供一条不正面冲突守卫的送信途径。")
zh(5862,"麦兰达提供幻象，助你潜入壁炉谷并送交泰兰的礼物。她的魔法短暂且远离该区即失效，机会须谨慎使用。")
zh(5863,"砂槌食人魔已占下沙漠一角，成股的人马散布在废墟之间。截住戈尔玛洛克、削其营地，为的是不让更大的兵力在塔纳利斯站稳脚跟。")
zh(5881,"瑞什早已期盼能回乡探亲。一封书信宣告有后备战士将接替他在升降梯的守望；送交这消息，方能让那段休憩成真。")
zh(5882,"塞纳里奥信标可探测被腐蚀的野兽体内蕴含的灵魂碎片。这些碎片能制成药膏，治愈病态植物，而你的联系人则以成批制成品交换这些碎片。")
zh(5883,"采矿费伍德矿石时，信标可发现被污染的硫酸盐。净化之后，它将成为塞纳里奥药膏的原料，将腐败之物转化为植物修复的助力。")
zh(5884,"持信标采集草药，可发现费伍德残留的恶魔腐化痕迹。你的联系人能将它们提炼成药膏原料，并以成剂量交换，助力受感染植物的复苏。")
zh(5885,"剥皮费伍德野兽时，信标可察觉其皮毛中的污染痕迹。提炼处理后，它将成为塞纳里奥药膏的原料，交出这些材料可换取用于植物修复的成品。")
zh(5886,"从解除魔法的物品中提取的魔法本质，可成为塞纳里奥药膏的强力原料。无需信标：提供合适的魔法本质，即可换取已制备的药膏，助益受感染植物的修复。")
zh(5887,"塞纳里奥信标可探测被腐蚀的野兽体内蕴含的灵魂碎片。这些碎片能制成药膏，治愈病态植物，而你的联系人则以成批制成品交换这些碎片。")
zh(5888,"采矿费伍德矿石时，信标可发现被污染的硫酸盐。净化之后，它将成为塞纳里奥药膏的原料，将腐败之物转化为植物修复的助力。")
zh(5889,"持信标采集草药，可发现费伍德残留的恶魔腐化痕迹。你的联系人能将它们提炼成药膏原料，并以成剂量交换，助力受感染植物的复苏。")
zh(5890,"在剥皮费伍德的动物时，信号灯揭示了被污染的皮毛。处理这些皮毛可提炼出塞纳里奥药膏的原料，交出它们则能换取用于恢复植物的配方。")
zh(5891,"从被解除魔法的物品中提炼出的魔力，可成为塞纳里奥药膏的强效成分。无需信号灯：提供合适的魔力精华，便可换取用于修复受害植物的药膏。")
zh(5892,"战争让丹巴达尔的物资仓库守卫寥寥。需从驮兽与敌对势力手中夺回储备，让联盟的补给得以延续。")
zh(5893,"战斗让冷齿矿洞难以持续守卫，而部落的补给仍存于此。夺回它们，需进入一处常在联盟与地下生物之间易主的险地。")
zh(5901,"米克希望削弱血色十字军的伐木场，以阻碍其防御与重建。病木林的白蚁能达成此目的，但必须先收集足够数量，才能制造出这场瘟疫。")
zh(5902,"加固的木桶装着白蚁，它们将破坏血色十字军的伐木场。将木桶置于设施中心，便能释放虫群，侵蚀关键资源。")
zh(5903,"武力无法驱逐血色十字军，纳撒尼尔提议破坏其伐木场。他需要抗病白蚁，以准备一场扰乱敌人运作与补给的虫灾。")
zh(5904,"白蚁已备好，可用来毁掉伐木场。把木桶带进里面，便能让血色十字军赖以运转的作坊瘫掉——断其资用，胜过硬碰它的防线。")
zh(5921,"月光林地欢迎所有追寻知识的德鲁伊。你的爪之研究将从德迪利特开始，他将引领你踏上这条新路径的第一步。")
zh(5922,"月光林地欢迎所有追寻知识的德鲁伊。你的爪之研究将从德迪利特开始，他将引领你踏上这条新路径的第一步。")
zh(5923,"玛斯雷召你前去，他将亲自引导你进入训练的新阶段。作为大德鲁伊助手的经验，能为此刻的成长指明方向。")
zh(5924,"玛斯雷召你前去，他将亲自引导你进入训练的新阶段。作为大德鲁伊助手的经验，能为此刻的成长指明方向。")
zh(5925,"玛斯雷召你前去，他将亲自引导你进入训练的新阶段。作为大德鲁伊助手的经验，能为此刻的成长指明方向。")
zh(5926,"图拉克希望亲自引导你进入德鲁伊训练的新阶段。你必须前往雷霆崖，在那里他的智慧与耐心，将助你拓展所学。")
zh(5927,"图拉克希望亲自引导你进入德鲁伊训练的新阶段。你必须前往雷霆崖，在那里他的智慧与耐心，将助你拓展所学。")
zh(5928,"图拉克希望亲自引导你进入德鲁伊训练的新阶段。你必须前往雷霆崖，在那里他的智慧与耐心，将助你拓展所学。")
zh(5929,"巨熊之灵教德鲁伊领悟熊的真谛。唯有在领悟并内化这份智慧后，你才能向德迪利特证明自己的成长，这是必修的一步。")
zh(5930,"巨熊之灵教德鲁伊领悟熊的真谛。唯有在领悟并内化这份智慧后，你才能向德迪利特证明自己的成长，这是必修的一步。")
zh(5931,"将所学付诸实践，你再度回到玛斯雷·驭熊者身边。他的指引将完善你作为德鲁伊守护自然平衡的初阶教诲。")
zh(5932,"将所学付诸实践，你再度回到图拉克·符文图腾处。他与自然的平衡，将指引你作为德鲁伊守护者的最终教诲。")
zh(5941,"达隆郡的遗物重燃了守护人民的信念。克罗米说你仍可助她一臂之力，只需将收集的物件送至安多哈尔，以备她计划中的干预行动。")
zh(5942,"约瑟夫借帕米拉之手送来了谢礼。屋后木箱中藏着他赠予你的礼物，以表彰你对家族的贡献。")
zh(5943,"玛诺洛克附近的卡多斯显得不安，但恶魔通常无视商队。里格尔与考克需要护卫通过这段路程，以免独自面对突如其来的危险。")
zh(5944,"泰兰回忆起父亲，支撑他继续效忠已不再相信的十字军。他渴望重逢不只是梦，需要护卫带他离开壁炉谷。")
zh(5961,"希尔瓦娜斯认可你的资历，将你引荐给纳萨诺斯——她最忠诚的追随者之一。在瘟疫之地寻得他，是你在亡灵阵营中证明实力的机会。")
zh(5981,"曾威胁霜刃豹的巨兽，至今仍盘踞在附近山谷。为它们的女王而战，将展现你对与精灵结盟的生物的忠诚。")
zh(6000,"你被寻来，是为了继续你的训练。前往暴风城的法师区，向加科因报告，他正等待你重启这段学习。")
zh(6001,"一块圣石能让月爪枭兽借塞纳里奥尘土被召唤。面对它的守护者，将考验你前行路上所需的身体与意志。")
zh(6002,"一块圣石能让月爪枭兽借塞纳里奥尘土被召唤。面对它的守护者，将考验你前行路上所需的身体与意志。")
zh(6004,"科尔斯塔在侦查血色防御时受了伤，需休息后才能继续。削弱他们外围营地的兵力，将助她一臂之力，也证明你能协助更大规模的行动。")
zh(6021,"泽达尔的亡灵巨魔夜间偷取尸体，运往墓室。奥林希望你阻止这些袭击，直面幕后主使，遏制墓地的危机。")
zh(6022,"纳萨诺斯要求这场猎杀有实际用途：喂养他的猎犬。必须迅速收集并处理天灾军团的腐质，以保存他所需的材料。")
zh(6023,"科尔斯塔要查壁炉谷，先得剪除外围的兵力。莱德雷与杜尔根正是那道防线的两根支柱——除掉二人，事情便向前推进；她伤重未愈，还无法亲自动手。")
zh(6024,"哈米亚深知感染正在侵蚀他的意志，驱使他感染其他巨魔。他的信件请求你杀他，以阻止这一目的达成，同时提供宝物作为报酬。")
zh(6025,"科尔斯塔仍需查明有多少血色士兵驻守壁炉谷。进入城镇并从高处观察将完成侦察，但她无法提供情报或保护你免受城镇的威胁。")
zh(6026,"黑烟为银色黎明承接爆破工作，并愿分润报酬。他在标记天灾建筑时，你需要收集制作炸弹所需的材料。")
zh(6027,"上古之书保存着娜迦的秘密，历经数百年。一颗宝石可在拉纳加尔岛召唤其守护者；找回这卷书，将获得对抗仍不甚了解的敌人所需的知识。")
zh(6028,"永望镇的银色黎明代表需要一份报告送达普尔哈特。将它送至她的岗位，既可维持联系，也可能引荐你认识一位有更多任务的上级。")
zh(6029,"永望镇的银色黎明代表必须向加鲁什汇报进展。完成前往亡灵壁垒的旅程，将维持这一联系，并引荐你认识监督这项工作的军官。")
zh(6030,"一位术士提供了一部灵体论著，其语言令你的联络人困惑。尼古拉斯·瑟伦霍夫精通语言学，或许能研究这卷书，所以将它带到圣光之愿号礼拜堂。")
zh(6031,"木喉族对外来者心存戒备，物资难以获取。一位访客的斗篷引发了他们对符文布的兴趣；提供梅罗什所需，可换取类似衣物与报酬。")
zh(6032,"月布对木喉族而言具有神圣意义，超越了他们对其他衣物的欣赏。梅罗什愿传授一项秘技，以换取一小批这种材料。")
zh(6041,"天灾军团的建筑将被拆除。黑烟提供了他的特制化合物，用于在这些建筑内安置炸药，执行银色黎明委托的任务。")
zh(6042,"每当纳萨诺斯带猎犬出猎天灾时，蝙蝠便不断骚扰他。他轻视这项工作，将其视为训练，命令你减少它们的数量。")
zh(6061,"驯服动物能让你在牛头人传统中更贴近自然。一头成年平原陆行鸟将是你最初的练习伙伴，之后才学习挑选并训练属于自己的坐骑。")
zh(6062,"学习与动物协作需要决心与练习。剃刀岭附近一头野猪将是你最初的临时伙伴，用以培养猎人所需的战斗技巧。")
zh(6063,"在获得动物伙伴前，你必须展现对自然的尊重。用练习用的驯兽棒驯服一只蜘蛛，将开启一场关于猎人力量责任的课程。")
zh(6064,"选择宠物需体验不同动物的特质。你的导师建议从一头结实的野猪开始，用驯兽棒探索这种伙伴关系能带来什么。")
zh(6065,"你的猎杀技巧表明，你已准备好与动物伙伴并肩作战。索塔尔在血蹄村等待你，那里是开启这段旅程的起点。")
zh(6066,"你的猎杀技巧表明，你已准备好与动物伙伴并肩作战。索塔尔在血蹄村等待你，那里是开启这段旅程的起点。")
zh(6067,"你的猎杀技巧表明，你已准备好与动物伙伴并肩作战。索塔尔在血蹄村等待你，那里是开启这段旅程的起点。")
zh(6068,"你的成长意味着，你已踏上驯服之路。索塔尔在剃刀岭指引方向，为你准备通往猎人之伴的试炼。")
zh(6069,"你的成长意味着，你已踏上驯服之路。索塔尔在剃刀岭指引方向，为你准备通往猎人之伴的试炼。")
zh(6070,"你的成长意味着，你已踏上驯服之路。索塔尔在剃刀岭指引方向，为你准备通往猎人之伴的试炼。")
zh(6071,"你所掌握的技巧表明，驯服之路已然开启。达扎拉在多兰纳尔传授技艺，引领你走向拥有动物伙伴的未来。")
zh(6072,"你所掌握的技巧表明，驯服之路已然开启。达扎拉在多兰纳尔传授技艺，引领你走向拥有动物伙伴的未来。")
zh(6073,"你已具备驯服的资质，可开始学习驯养之道。达扎拉在多兰纳尔为你提供指导，助你踏上获得伙伴的旅程。")
zh(6074,"身为猎人的你，已具备驯养宠物的基础。格瑞夫在卡拉诺斯为你指引方向，教你如何将野兽化为旅途中的伙伴。")
zh(6075,"身为猎人的你，已具备驯养宠物的基础。格瑞夫在卡拉诺斯为你指引方向，教你如何将野兽化为旅途中的伙伴。")
zh(6076,"身为猎人的你，已具备驯养宠物的基础。格瑞夫在卡拉诺斯为你指引方向，教你如何将野兽化为旅途中的伙伴。")
zh(6081,"你已能驯服动物，但仍需学习如何训练它们。奥玛克在奥格瑞玛传授技艺，令你新得的伙伴能与你一同成长。")
zh(6082,"最终的驯服试炼，关乎硬甲蝎的自信与速度。理解它作为伙伴的意义，将助你学会召唤、命令与遣散自己的坐骑。")
zh(6083,"你的宠物必须成为你能力的延伸。与沿海螃蟹的实战，拓展你的驯养经验，并教你如何将他者之力融入己身。")
zh(6084,"体验过野猪的力量后，是时候尝试更敏捷的猎物。驯服雪豹，可对比不同的战斗风格，再择一真正契合的伙伴。")
zh(6085,"最终试炼以熊的力量拓展你与宠物的默契，完成它将助你学会如何挑选一位能与你并肩作战、回应召唤的伙伴。")
zh(6086,"单凭驯服宠物的技巧不足以激发它的潜力，贝莉亚·雷岩能在铁炉堡教导宠物训练，助你掌握引导新伙伴迎接未来冒险的技能。")
zh(6087,"草原狼教会你速度与勇气，这是团队狩猎的关键。驯服它并并肩作战，能让你练习猎人与宠物间的默契配合。")
zh(6088,"最终试炼从陆地跃向天空，以鸟类为伴。它的攻击与存在拓宽了你的经验，为日后选择并掌控一位长期伙伴做准备。")
zh(6089,"驯服已触手可及，但你仍需学会训练宠物。浩特·雷角在雷霆崖提供这段经历，并能判断你是否已准备好接受他的教导。")
zh(6101,"自然的多样性需要你与不同动物互动。夜刃豹将成为你的下一位练习伙伴，助你理解它与其他野兽共通的特质，以及它独特的个性。")
zh(6102,"在陆地生物后，你需与飞禽并肩学习。驯服猫头鹰完成必要的练习，为选择自己的伙伴、与你一同面对挑战积累经验。")
zh(6103,"你新掌握的驯服能力需匹配动物训练。祖卡斯特能在达纳苏斯教导这项技能，并为你的发展提供指引，助你培养一位可长期相伴的伙伴。")
zh(6121,"师长希望你理解塞纳留斯赐予的净化毒药之力。德纳特的教导直面中毒之患，不急于依赖魔法，彰显这赐予的真正价值。")
zh(6122,"德鲁伊怀疑峭壁之泉的水正在毒害鹿群。取一份水样交与奥兰达利亚，她便能查清水源——这一带生灵的性命，多半系于此处。")
zh(6123,"调配治鹿的药膏，需采得带疗愈之效的草药与菌类。这些东西长在月夜枭兽的地盘上，近来它们格外暴躁。")
zh(6124,"调配好的药膏已足以开始治疗病鹿。村中筹措更多剂量时，你可将它涂抹于黑海岸，之后向塞纳里奥议会汇报成果。")
zh(6125,"你已明白不依赖灵体之力净化毒药所需付出的辛劳。重返玛斯雷，将这份体悟带入新的课程，铭记那些无德鲁伊天赋者所面临的艰难。")
zh(6126,"净化毒药的德鲁伊之力，需理解其价值。你的课程从以无此天赋之人的视角出发，于月光林地的圣域，在德纳特里导师指导下直面问题。")
zh(6127,"高山之巅的水源或正通过天气扩散毒害。一份样本将助图加调查疑似火刃氏族污染，并与你共同应对这场疫病。")
zh(6128,"瞪羚的药膏需疗愈之根与科多兽角以增强效力。获取这些成分，方能调配出维系周边土地平衡的治疗之物。")
zh(6129,"药膏已够救治那些患病的瞪羚。趁余下的药还在熬制，你的援手能让我们在贫瘠之地先行出手，事后再向塞纳里奥议会复命。")
zh(6130,"没有灵体恩赐的毒药战斗经验，已为你接下来的课程做好准备。图拉克见你理解他人为缓解这种痛苦所付出的努力，便可继续你的训练。")
zh(6131,"木喉岗哨逃过了腐化，但其他种族却不分敌我地攻击它们。对抗死木湾的敌人，能展现你的意图，打破他们因猜忌而封闭的关系。")
zh(6132,"前往玛洛迪的贸易访问以被俘虏告终，还引发了对成为他们盘中餐的恐惧。梅丽萨急需紧急逃亡，并承诺她兄长会以科多兽坟场营地的协助作为回报。")
zh(6133,"纳萨诺斯希望恢复他凡人生命的记录，从高等精灵手中夺回。他拒绝透露内容，并在取回途中下令毁掉一切，让其对保管者的敌意昭然若揭。")
zh(6134,"白骨之谷的半人马幽灵或许能提供获利的商品。你的联系人怀疑玛格拉姆势力，便准备磁铁吸引灵体，收集用于出售的幽灵电浆。")
zh(6135,"纳萨诺斯认为你已准备好迎接更艰难的猎物。暗翼蝠便是目标，而一片白毛将证明你已克服挑战。")
zh(6136,"淤血虫吞噬了整支军团，且越吃越大。纳萨诺斯希望阻止瘟疫之地的怪物，建议集结盟友，以免重蹈那些攻击者覆辙。")
zh(6141,"安东修士听闻凄凉之地出现亡灵瘟疫，便前往调查。他寻找足以直面这威胁的同伴；在尼耶尔前哨站与他会面，便能加入这场抗争。")
zh(6142,"软壳蚌肉是鱼儿无法抗拒的饵料。你的联系人需要从沉船附近采集蚌肉，他愿以高价换取一位老渔夫珍视的原料。")
zh(6143,"一名渔夫在纳迦袭击中幸存，全队皆死。懊悔取代了垂钓的念头，他托你为同伴复仇，驱逐占据他们旧渔场的入侵者。")
zh(6144,"瓦里玛萨斯要办一桩机密的军务，需得力的人手。纳萨诺斯遣你去幽暗城听令，话里也点明：你的成败，同样记在举荐你的人账上。")
zh(6145,"血色指挥防御工事难以突破，但他们的通讯提供了另一条路径。截获信使，便可获取送往提瑞斯法之手的密令，让纳萨诺斯提前布防。")
zh(6146,"纳萨诺斯篡改密令，引诱神谕者现身。一枚魔法苹果将让你伪装成血色阵营，将文件送至瓦德玛尔手中，不露破绽。")
zh(6147,"瓦德玛尔接受请求，为神谕者的旅程准备特殊保护。将行动情报报告给纳萨诺斯，让他知晓通过伪造命令获得的回应。")
zh(6148,"这场骗局揭穿了德米提雅的身份，她是大十字军击败天灾军团的幕后智囊。她可能拥有心灵力量，察觉危险；在她返回藏身之处前，务必截断她的行程。")
zh(6161,"拉克莫尔将宝物藏起，只为挡开觊觎它的海盗。航海日志指向拉纳加尔岛，但寻获宝箱只是开始：两把遗失的钥匙也必须找回。")
zh(6162,"德雷卡·苏尔的丈夫在协助对抗被腐化的熊怪后失踪。她欲向罗尔寻仇，要求他交出利爪，以证明你曾与她所怨的怪物正面交锋。")
zh(6163,"纳萨诺斯记得拉姆斯登是导致他家园覆灭、化身天灾军团的一员。如今意志重燃，他誓要向夺走他生命的憎恶复仇。")
zh(6164,"奥古斯图斯想开张店铺，却因缺少账本无法记账。他坚信账本遗落在镇上的酒馆，交易前必须找回。")
zh(6181,"西部荒野的守卫者盔甲告急，支援寥寥。刘易斯亟需奥斯里克协助，确保守护者们能持续装备上阵。")
zh(6182,"纳萨诺斯曾是守护洛丹伦的人类游侠领主，被认为在保卫洛丹伦时阵亡。他的遗体从未寻获，马迪亚斯·肖尔的调查或能揭开他失踪的真相。")
zh(6183,"马迪亚斯调查案让五名特工丧命，仅剩两个字可辨。肖尔缺乏支援，只能向你求援，至少为阵亡者家属寻得答案。")
zh(6184,"调查人员怀疑凋零使徒杀害了纳萨诺斯与失踪特工。弗林特在瘟疫之地的营地中运作，可提供信息与任务，追查这条线索。")
zh(6185,"侦察行动旨在寻找凋零使徒与失踪特工的线索。他们的徽记能辨识遗骸并为弗林特提供证据，证明这场行动的结局仍悬而未决。")
zh(6186,"弗林特惊恐地得知纳萨诺斯与凋零使徒实为一人。伯瓦尔必须知晓这位前游侠领主的下场——如今他成了亡灵的爪牙，对抗曾敬重他的旧识。")
zh(6187,"伯瓦尔难以容忍如此重要的联盟战略家竟效忠亡灵。他下令集结军队，深知纳萨诺斯的才能使他成为极其危险的对手。")
zh(6261,"奥斯瑞克已备齐了刘易斯所需的装备。借狮鹫传送木箱，可避免物资短缺削弱西部荒野的守卫力量。")
zh(6281,"物资请求必须送达暴风城的奥斯瑞克。借助狮鹫的联系，刘易斯的讯息能抵达能准备所需装备的人手中。")
zh(6282,"日益增多的猫头鹰令那些视守护土地为己任之人忧心忡忡。血怒在石爪峰蔓延，限制其他生物的行动；减少它们的数量，能缓解这股压力。")
zh(6283,"仅减少猫头鹰数量尚不足以解决问题，只要它们的首领尚在，威胁便不会终结。前往焦炭谷寻找血怒撕裂者，阻止她以根除族群扩张的源头。")
zh(6284,"贝瑟莱斯与她的子嗣已将希塞尔山谷变为蛛网遍布的巢穴。马格兰悬赏取其性命，并要求以蜘蛛的死证明威胁已除。")
zh(6285,"将奥斯里克的货物送回刘易斯，完成补给任务。狮鹫航线将装备送往哨兵岭的守卫者手中。")
zh(6301,"石爪峰已因战火与工业而伤痕累累。盖亚之种或许能重焕生机：你的联系人希望以萨满之力赋予它们生命。")
zh(6321,"墓地的守卫者必须补足失散的武器。前往幽暗城的供应商处接洽，能确保死亡守卫们应对银松森林的威胁。")
zh(6322,"墓地所需的武器已打包妥当。借蝙蝠运送，完成守卫者们的补给行动。")
zh(6323,"蝙蝠航线将你送往幽暗城，高顿·温德哈姆可处理武器订单。这段旅程串联起墓地的需求与供应商的联系。")
zh(6324,"知晓墓地的蝙蝠管理员，才让归途成为可能。这条航线完成幽暗城补给与前线据点的连接。")
zh(6341,"泰达希尔的鱼产丰饶，值得与大陆的鱼作比较。一袋鱼骨与鳞片必须送往另一名商人手中，借飞行服务安排运输。")
zh(6342,"内萨的收藏必须送往奥伯丁比较。角鹰兽大师提供运输，也愿传授一次飞行路线的联系，值得在每座城镇的本地大师处建立。")
zh(6343,"大陆的鱼与泰达希尔的截然不同，莱尔德怀疑世界之树影响了附近生态。他希望尼莎能收到他的观察记录。请借角鹰兽或渡轮将他的回信带回去。")
zh(6344,"尼莎需要帮忙将包裹从她的渔场送往大陆。在鲁瑟兰寻找她，不仅能完成这项差事，更能了解岛屿与黑海岸之间的物资往来。")
zh(6361,"一批贫瘠之地的兽皮必须送到雷霆崖的匠人手中。与迪弗拉克安排运输，能让这些原料更接近成为皮革制品的终途。")
zh(6362,"本该送到安哈努的兽皮，借驭风者能快速抵达。这段旅程将生皮送往匠人手中，而他的车间就位于你飞行路线的终点附近。")
zh(6363,"安哈努已备好皮革制品，准备在十字路口出售。拜访驭风者大师，你便能安排返程，并将这些商品送到需要的商人手中。")
zh(6364,"这些皮革制品必须送到十字路口的贾汉手中。既然你已认识驭风者大师，便可借这联系，从雷霆崖完成整趟运输。")
zh(6365,"扎尔夫想将一些肉块送给在奥格瑞玛经营酒馆的朋友。十字路口的驭风者大师能安排最快捷的运输方式，让这份礼物准时送达。")
zh(6381,"这些魔法种子必须种在焦炭谷废墟的核心处。助它们扎根，便能重启生命的循环，尽管巨魔与元素生物仍威胁着这片伤痕累累的土地。")
zh(6382,"你愿意狩猎，说明已准备好迎接更大的挑战。塞娜尼·雷心在灰谷等待指引，那里是部落建立据点之地，也是你试炼力量的战场。")
zh(6383,"塞娜尼提议你挑战灰谷的传奇生物，从它们的强大力量与狡黠智慧中学习。这场狩猎需要你的功绩作为凭证，也可能需要协助对抗异常危险的野兽。")
zh(6384,"飞往奥格瑞玛的航程能让扎尔夫的肉抵达格雷什卡的酒馆。驭风者大师会教你如何在旅程的终点附近完成交付。")
zh(6385,"格雷什卡已写信致谢扎尔夫。你必须将信件交给奥格瑞玛的驭风者大师，并安排返程，让她的回信能送达送肉之人。")
zh(6386,"你已掌握的飞行航线，可助你带着格雷什卡的信件返回十字路口。完成这段旅程，将她的谢意送达扎尔夫，也意味着这场始于送肉的交易就此终结。")
zh(6387,"杰出的采矿学徒已赢得荣誉锄。一份名单必须送往铁炉堡的匠人，好让他为他们准备工具，而狮鹫服务能协助你递送这份请求。")
zh(6388,"荣誉锄已备好，供布洛克的学徒使用。铁炉堡的狮鹫大师可协助他们带着这些工具返回塞尔萨玛，以表彰他们在采矿与学习中的成就。")
zh(6389,"撬棍能打开血色伐木场内的木桶。释放白蚁完成破坏，撤离前务必确保虫害不会波及带来木桶之人。")
zh(6390,"木桶已就位，你找到了开启它的工具。释放白蚁将启动伐木场的破坏，但要避开被你打算释放的虫群困住。")
zh(6391,"布洛克的清单得送到铁炉堡的采矿公会，学生的奖品才好置办。一封急信送去，落在供应矿镐之人每日做工的街区。")
zh(6392,"准备好的矿镐必须送回布洛克，以供他的学生使用。已建立的狮鹫航线让这项运送得以完成，也凸显了在旅途中拜访飞行大师的价值。")
zh(6393,"潮汐议会为耐普图隆之命与火元素作战。你的联系人寻求其青睐，并提供报酬，以换取摧毁火元素与收集它们遗落的焚火余烬。")
zh(6394,"塔兹利尔在勘察洞穴时留下了他的最爱矿镐，如今危险的生物阻碍了它的回收。它的附魔让它在黑暗中可见，但周围的野兽仍是障碍。")
zh(6395,"萨缪尔被天灾军团侵蚀，杀害了玛拉。玛拉仍希望与他合葬。终结他的漂泊，将他的遗骸带往她的墓地，完成这个最后的请求。")
zh(6401,"凯雅的生还为她村庄遭袭后的消息带来了转机。她姨妈需要知道她还活着，所以你带着讯息前往休息营地，让她能及时收到。")
zh(6402,"温德索尔手中握着足以撼动王国的真相，正待揭开。到暴风城城门与他会合，且要带上同伴——单凭一个冒险者，撑不起这场聚会。")
zh(6403,"温德索尔识破普瑞斯托的真实身份，认定他是奥妮克希亚。他意图瓦解她对王国与领袖的操控，随他穿越暴风城，将助他在揭露这场骗局的对峙中全身而退。")
zh(6421,"狗头人正在洞里昼夜赶挖一种异样的晶体。深入洞底取回样本，方能弄清它们在石爪山底下这番动静，究竟藏着什么令人不安的东西。")
zh(6441,"萨特的角在棘齿城备受追捧，你的联系人察觉到其中商机。因无法与主人抗衡，旅行者愿以报酬换取你从灰谷的萨特聚落收集角类。")
zh(6442,"纳迦重返古老佐拉姆沉没的海岸。部落不知他们的意图，但认为唯有迎战，才能守护这片已占为己有的土地。")
zh(6461,"蜘蛛趁夜袭扰玛拉卡金的营地，抢走猎物。压住这股祸患，巨魔们的口粮与生计才保得住——他们就靠这片土地过活。")
zh(6462,"蓟皮熊怪杀害了携带神圣符咒前往佐拉姆加的旅行者。尽管族人期待死后重逢，但他们不能让这些具有精神意义的物件落入袭击者之手。")
zh(6481,"共鸣桶内沉睡着一名被视作威胁的土灵。一块经萨满魔法改造的水晶，可令他以虚弱状态苏醒，使你得以立刻与他正面交锋。")
zh(6482,"熊怪误将鲁尔当作熊，将他捕获并囚禁，如今他正挨饿。他必须在体力耗尽前逃出生天，并将消息传给妹妹雅玛。")
zh(6501,"破碎的徽章已无法开启奥妮克希亚的巢穴。寻找一位有龙血的个体，修复它——只知某些巨龙隐匿于类人种族之中。")
zh(6502,"修复碎片需取自黑龙时代战士的鲜血。达基萨斯统御奈法利安的龙族军团，取得其血液将使尝试对奥妮克希亚巢穴的钥匙施以魔咒成为可能。")
zh(6503,"联盟的斥候已撤离银翼哨站，隐匿于部落领地附近。须阻止他们，以免他们搜集到有关部落军事防御的情报。")
zh(6504,"一阵风散落了从棘齿城新收缴的碎纸机说明书。操作者必须返回木材营地，却无法使用机器，需找回这些说明书。")
zh(6521,"马尔辛的存在似乎解释了奎布拉兽的强大力量与瘟疫迹象。阻止使节，以防他表面的协议让巫妖王的影响力渗透此地。")
zh(6522,"马尔辛的书信以权力与领土为饵，换取在贫瘠之地自由行动的权力。它揭示了一项令人不安的合作提议，并将使节安置于剃刀高地，以作进一步磋商。")
zh(6523,"卡雅必须在俘虏发现她已逃走前离开。护送她前往熟悉之地，能延续她的逃亡，或许也能安抚等待她消息的父亲。")
zh(6541,"部落正寻求增援以守卫其在灰谷的新据点。卡德拉克统御此役，可下达具体指令，你须向他报告，协助守卫这些新前线。")
zh(6542,"部落正为灰谷的新哨站寻求支援。卡德拉克统率这场行动，下达具体指令，你必须前往他处协助守卫这些新前线。")
zh(6543,"分散在灰谷的侦察兵亟需指令与情报。你若充当信使，便能串联多个哨站，让卡德拉克掌握他们所守之地的最新动态。")
zh(6544,"托雷克正筹备对银翼哨站统领杜瑞尔·月火的突袭。守备森严，他邀你加入劫掠队，共担进攻的风险。")
zh(6545,"在击退娜迦数波进攻后，信使将接收你的指令。威胁持续扩大，交换情报能确保卡德拉克掌握哨站的防御状况。")
zh(6546,"哨兵守望着一条被联盟、萨特与娜迦觊觎的通路。传递指令与情报，能让部落掌握这条东部前线的威胁。")
zh(6547,"精灵潜伏于暗影之中，企图夺回部落所占的土地。侦察兵静候卡德拉克的新令，同时维持警惕以守护这片争议之地。")
zh(6548,"一名格里姆图腾袭击的幸存者，目睹村庄被屠后仓皇逃命。他的请求源于复仇，将你引向仍在附近作恶的元凶。")
zh(6561,"一座月神殿被远古神灵的邪能侵蚀。克尔里斯领导着崇拜者献祭无辜者给阿库·迈，你必须阻止他，以正此等亵渎。")
zh(6562,"灰谷西岸的佐拉姆加前哨站，杰努正等人相助。你的联系人把你引荐给他，并提醒：此去要穿过一片地界，那里的势力见了外人，只会拔刀相向。")
zh(6563,"纳迦正在从黑暗深渊采集蕴含强大元素之力的晶体。杰努担心这些晶体可能成为危险的奥术组件，希望在弄清它们的计划前阻止其使用。")
zh(6564,"一封密信要求收集的晶体用于强化水系术士的召唤之力。信的作者意图借这股力量安抚阿库迈，重归旧神对世界的统治。")
zh(6565,"洛格斯的计划将自然之灵献给一个崇拜混沌的邪教。杰努力量不足，无法阻止他，必须在计划推进前潜入深渊。")
zh(6566,"萨尔从东部王国得到消息，邀请你前来聆听。这场对话将让你直接听到风所传递给战酋的重要讯息。")
zh(6567,"萨尔得知或许能进入巨龙巢穴。雷克萨知晓这个可能性，必须在凄凉之地的旅程中找到他，以得知下一步行动。")
zh(6568,"绕过黑龙时代防御需要一场幻象。雷克萨认识麦兰达，她曾因认为部落的事业值得而协助过部落；他的信件将把任务交托给她。")
zh(6569,"麦兰达能让你假扮黑龙时代的一员，但她需要难以获取的材料。龙裔之眼将提供雷克萨与萨尔委托的欺骗计划所需的组件。")
zh(6570,"徽章能维持一个适合接近埃博斯塔夫的幻象。这位看门者考验着未来对抗奥妮克希亚的战士，伪装潜入则能踏上她为追随者准备的征途。")
zh(6571,"木材营地急需锯片与斧头，还有被熊怪偷走的绳索，以及被山羊族仪式拿走的油料。收集这些物资，能一举解决多处短缺。")
zh(6581,"皮克希尔手握锯片运输，却不会轻易交出。她想要一把致命短枪自保，提议以武器换你所需的补给。")
zh(6582,"埃博斯塔夫要求证明黑色巨龙族凌驾于其对手之上。冬泉谷的蓝龙勇士斯克利尔是目标，他的头骨将证明这场晋升试炼的完成。")
zh(6583,"下一阶段的试炼需攻击绿龙族，以证明对死亡之翼子女的忠诚。索姆努斯是被选中的勇士，他的头骨将证明你战胜了埃博斯塔夫的对手。")
zh(6584,"埃博斯塔夫希望对诺兹多姆的子嗣——时光之穴的守卫者发起进攻。克鲁纳里斯是此试炼的目标，意在证明你可战胜青铜龙族的勇士。")
zh(6585,"红龙族守护着格瑞姆巴托，埃博斯塔夫要求以死亡之翼之名惩罚其中一位勇士。找回埃克托兹的头骨，将延续这场龙族欺诈的晋升试炼。")
zh(6601,"徽章需要达基萨斯最终的附魔，但你的伪装在冰冠之塔内失效。先向雷克萨请教对策，再向将军现身。")
zh(6602,"雷克萨解释，只要达基萨斯的鲜血，这枚护符便可激活。不再需要伪装成黑龙军团，直面将军才是打开奥妮克希亚巢穴的关键。")
zh(6603,"冬泉谷的异动牵动了多方关注，而多诺瓦·雪山始终驻守温泉附近，她能为探索此地的冒险者厘清问题所在。")
zh(6604,"一处废弃营地似乎遭狂怒的野兽摧毁，幸存者据称藏身坠星村。寻找加隆·石矛，或许能揭开那场袭击的真相。")
zh(6605,"一位费伍德访客建议你去找温娜·哈萨德，她对某件事的执着显得格外不同。前往驿站，听听她究竟追寻什么，是否需要协助。")
zh(6606,"玛乌阿里送你的幸运符让联络人相信好运的价值。你或许也该拥有一个，但得去找永望镇的萨满，而非借用他们的。")
zh(6607,"纳特认为毅力比数十年的垂钓经验更重要。捕捉稀有鱼类，将证明你的耐心，也让你获得超越旧师的进阶知识。")
zh(6608,"鲁玛克已无法再教你更多钓鱼技巧，他的朋友纳特能接续教导。前往塞拉摩南方的海岛，寻得能指引你的老师。")
zh(6609,"你的导师已将所有钓鱼知识倾囊相授，他熟识纳特，便送你去找他，让学习能继续在更有经验者手中延续。")
zh(6610,"迪尔格想准备他的最新特餐，却已用尽食材。提供给他，你将获得一场异域烹饪课，并尝到他厨艺的巅峰之作。")
zh(6611,"扎姆沙已将所有烹饪技艺倾囊相授。迪尔格可助你在加基森更进一步，而你的导师期盼你终将带着新知归来。")
zh(6612,"你的烹饪技艺已超越这位导师所能传授。他推荐你去找迪尔格，这位地精厨师，认为他能引领你进入下一阶段的训练。")
zh(6621,"腐林的狂暴被视为未来威胁。在他们村落插上旗帜，旨在向其首领展示力量；盟友的支援，是抵御部落反击的关键。")
zh(6622,"部落的医疗考核，考验你优先处理伤者的能力。先救治最危急的病人，以挽救足够生命，证明你已具备创伤救治的准备。")
zh(6623,"格雷戈里·维克多亲自召你前往落锤镇。这道传唤，是与部落首席创伤医师学习、并加入其团队的契机。")
zh(6624,"联盟的创伤考核，要求你辨识哪些伤者亟需救治。若能救活足够人数，将证明你的判断，方有资格加入医疗体系与其中的行列。")
zh(6625,"古斯塔夫·范沃森希望你前往塞拉摩，商讨加入联盟创伤救治服务的事宜。你的联系人认为向这位医师学习是难得的机会，敦促你把握良机。")
zh(6626,"一位外交官现身，将追随者转化为亡灵，引发对天灾军团的疑虑。其势力日益壮大，你的联系人亟需协助对抗，以免其人数失控。")
zh(6627,"递出书籍引出另一道关于知识的考题。老师允许你从容作答，专注展现所学，而非仓促应答。")
zh(6628,"你坚持完成任务，得以继续研习知识。老师如今提出问题，并给予充分思考时间。")
zh(6629,"格鲁迪格率众摧毁村庄，如今驻守附近据点。幸存者希望你设法揪出他，他是那场屠杀的主谋，至今仍令他魂牵梦萦。")
zh(6641,"沃尔沙屡次无端袭击佐拉姆加前哨站。熄灭娜迦为她保留的火盆，或可引出她，借盟友之力终结海德拉。")
zh(6642,"黑铁虽在深渊中多有产出，却仍受瑟银兄弟会重视。提供矿石支持其事业，亦可借与拉格纳罗斯兵器相关的材料赢得好感。")
zh(6643,"搜寻熔火之心的炽热之核，已令兄弟会损失无数生命。其代表以一份恩惠为交换，换取这种难以获取且危险的材料。")
zh(6644,"洛克斯受瑟银兄弟会之托出面议价。他提出以一枚熔岩之核换一份人情；这份献礼对方肯收，两家的交情便又添一分。")
zh(6645,"兄弟会的圣典配方需要熔火之心的猎犬皮毛。从拉格纳罗斯的猛兽身上获取皮革，既可提升工艺，也能在重视这类材料的成员中赢得声望。")
zh(6646,"山脉之血是兄弟会珍视的稀有贡品。提供它，便能借由这罕见材料，换取代表所接受的珍贵认可。")
zh(6661,"鼠患需要更多人手在缆车底下处理。用笛声引诱鼠群，活捉它们，省去在运输设施中追捕每只老鼠的麻烦。")
zh(6662,"尼普希在缆车另一端的生意中使用老鼠。在货物变质前送一箱过去，便能完成这趟简短的地下补给任务。")
zh(6681,"拉文霍德观察了你的能力，愿收你为大师的弟子。在加入刺客湾前，证明你的机智，找到藏匿于希尔斯布莱德丘陵中的庄园。")
zh(6701,"辛迪加依靠人数维持实力。拉文霍德提议偷取徽章：羞辱会促使被抢者自罚，借组织自身规则削弱其力量，而非单纯依靠伤亡。")
zh(6721,"达扎拉可开始你驯服专属坐骑的训练。你的狩猎能力显示你已准备好前往多兰纳尔，接受责任所需的考验。")
zh(6722,"达扎拉可开始你驯服专属坐骑的训练。你的狩猎能力显示你已准备好前往多兰纳尔，接受责任所需的考验。")
zh(6741,"铁匠雷格萨需要更多护甲碎片来装备他的士兵。收集敌方残骸不仅维持着熔炉运转，更将战场上的残骸转化为守护战友的盾牌。")
zh(6761,"范达尔将月光林地的求援委托给了玛斯雷。此时他正与塞纳里奥议会的长老争论，坚持自己的精灵未来蓝图。")
zh(6762,"拉比恩需要协助探索塔纳利斯与乌尔加罗斯之外的荒漠。这项任务或许能带来更大回报，但达纳苏斯与月光林地的矛盾正考验着你的立场。")
zh(6781,"士兵们需要更多护甲碎片来维持装备补给。战场上的物资能填补铁炉堡无法提供的缺口，维系着前线的战斗力。")
zh(6801,"瑟鲁加奉命通过元素仪式协助霜狼氏族。敌人的鲜血将唤醒洛克霍拉的召唤，最终化为对抗雷矛军团的强大力量。")
zh(6804,"瘟疫侵染了水元素斥候。海达克西斯交下海神之水，用以对抗这腐蚀；可净化一旦动手，会激起它骨子里的狂怒，那一关你也得闯过去。")
zh(6805,"水元素领主们与其它元素为敌，他们要求你证明忠诚。攻击守卫希利苏斯强大遗物的风与土元素仆从，将打乱他们的计划。")
zh(6821,"耐普图隆想看看你能否击败一位强大的火元素仆从。在击败兽人俘虏与囚禁其中的元素后，艾博希尔之眼将见证你的能力。")
zh(6822,"下一场试炼需闯入最强大火仆的要塞。海达克西斯建议集结军队，以彰显对抗占据熔火之心敌人的决心与意志。")
zh(6823,"与水元素结盟需在元素战争中展现毅力。对抗他们的空、地、火敌人，将削弱其立足之地，也证明对事业的坚定承诺。")
zh(6824,"海达克西斯可能失去一位重要代理人，但需对熔火之心的统领发起一击。他们的手将证明这场行动旨在重创火势。")
zh(6825,"古斯正为突袭战场中心准备骑手。喂食雷矛士兵的肉可激发他们的食欲，为即将到来的空袭做好准备。")
zh(6826,"杰斯托的舰队将面对更强的敌人，需让坐骑熟悉目标。雷矛副官的肉将助他们精准打击特定敌人。")
zh(6827,"穆维里克借突袭重要目标为被俘复仇。他的坐骑需雷矛指挥官的肉来准备进攻，但获取它需深入敌后。")
zh(6844,"异种蝎的物体下可能藏有笔记，其甲壳之下。阿姆伯尔可修复严重破损的书页，交付它将决定法阵能否借由发现洞悉过往。")
zh(6845,"阿姆伯尔需些工夫，才能弄清那物件里是否封着一本书、又能救回多少。此间，也该把近来的所作所为告知拉比恩，让月光林地营中的主事者心里有数。")
zh(6846,"部队已补给充足，随时可发起进攻。唯独诺雷格·雷矛的指令尚未下达，指挥官便无法将准备转为攻势。")
zh(6847,"辛迪加并不认同你的战争目标，但若能夺回瑞森之眼，他们愿提供协助。冰斧巨魔夺走了它，归还神器将换取这份条件性的支持。")
zh(6848,"辛迪加并不认同你的战争目标，但若能夺回瑞森之眼，他们愿提供协助。冰斧巨魔夺走了它，归还神器将换取这份条件性的支持。")
zh(6861,"斯菲莱克斯需要大量金属打造便携式切割机，还有一台蒸汽锯。锯子据说在雷矛木材营，这些物资是组装套件的必需品。")
zh(6862,"便携式切割机仍需金属与蒸汽锯才能组装。斯菲莱克斯在被捕前曾在霜狼木材营见过锯子，这些材料必须设法取得。")
zh(6881,"保护霜狼的元素能量牵涉到法阵。士兵们携带的水晶将让伊弗斯现身，寻求他对抗超出掌控的破坏之力。")
zh(6901,"战士们已整装待发，渴望进攻。但指挥官仍需下达突袭指令。交付这些命令，将让部队等待已久的攻势正式开始。")
zh(6921,"暮光之锤盘踞在黑暗深渊的废墟里，恐已胁迫此地的元素听命。若能取得一枚记录元素动静的核心，杰努与大地之环或可寻出斩断这股操控之法。")
zh(6922,"元素倒下后留下一枚圆球，看来正是它供给能量。球中的水浑浊发臭，外壳又挡得住刀兵；这古怪东西究竟是什么，杰努或许说得出缘由。")
zh(6941,"精英霜狼部队必须先被削弱，才能承受维波里的空袭。从副官与军团士兵处获得的勋章，将证明你已击破阻碍舰队部署的阻力。")
zh(6942,"斯里多尔的狮鹫无法在敌方前排尚未削弱时发动攻击。回收守军的勋章，将展现为空袭铺路所需的代价。")
zh(6943,"上次进攻失败后，艾克曼的狮鹫不愿再飞上天空。从敌方指挥官与守卫者处获得的勋章，将重振它们的士气，为下一次突袭做好准备。")
zh(6961,"这场庆典邀请你前往冬天爷爷处，讲述你期待收到的礼物。商贩们也准备了甜点，与一年来友善的人们一同分享。")
zh(6962,"冬天爷爷一整天都在庆祝活动中忙碌，此刻渴望一份甜蜜的休息。姜饼与冷牛奶，正是他托你带来的点心。")
zh(6963,"一批重要物资神秘失踪，追踪其下落的调查员至今未归。最后的报告指向奥特兰克，找到这名特工，或许能揭开季节物资去向之谜。")
zh(6964,"据你的线人透露，礼品促销掩盖了节日真正的意义。萨格尼深知其根源在于新生，他能解释这场庆典背后的传统，远不止交换礼物与甜点。")
zh(6981,"那块绿宝石吸引着你的目光，可它表面下似乎流动的烟雾却令人不安。若能在棘齿城找到认识它的家伙，或许能揭开它的来历。")
zh(6982,"冷齿矿洞藏着部落的补给，联盟士兵正需要这些物资。夺回它们，既可补给一方，也令敌方失去持续战斗的关键装备。")
zh(6983,"探员查明：格林奇既偷走了那批糖果，也是他一身冰雪的祸首。取回失货，再回报一句——此人困在冰封里，需人搭救才能脱身。")
zh(6984,"夺回甜点已赢得烟林牧场的感激。冬天爷爷将亲自送来礼物，以表彰你协助守护他们季节货物的功绩。")
zh(6985,"部落需要装备，也想削弱敌方储备。突袭深铁矿洞可夺取雷矛的补给，但其位于敌境深处，行动充满风险。")
zh(7001,"战争的代价让骑兵们马匹不足。捕捉森林狼能重补兽栏，也令骑兵团得以重返前线。")
zh(7002,"被俘的狼群需要装备鞍具才能载人。雷矛骑兵所用山羊皮可制成鞍具，为霜狼骑兵提供装备，助他们重返战场。")
zh(7003,"巨人威胁着索尔宾的生意，他想用缩小装置对付它们。为避免风险，他将实验交给你，只求你带回缩小后留下的残余物。")
zh(7021,"庆典邀请你拜访冬天爷爷，向他诉说你渴望收到的礼物。商贩们也准备了甜点，赠予那些整年善待他人的朋友。")
zh(7022,"庆典邀请你拜访冬天爷爷，向他诉说你渴望收到的礼物。商贩们也准备了甜点，赠予那些整年善待他人的朋友。")
zh(7023,"庆典邀请你拜访冬天爷爷，向他诉说你渴望收到的礼物。商贩们也准备了甜点，赠予那些整年善待他人的朋友。")
zh(7024,"庆典邀请你拜访冬天爷爷，向他诉说你渴望收到的礼物。商贩们也准备了甜点，赠予那些整年善待他人的朋友。")
zh(7025,"冬天爷爷一整天都在庆典中忙碌，渴望来点甜食歇歇。姜饼与冷牛奶，正是他托你带来的慰藉。")
zh(7026,"雷矛骑兵需要缰具，但杀掉自己的公羊会损耗战马。从敌方狼群身上取皮，能获得装备而不伤及战马储备。")
zh(7027,"雷矛兽栏空无一物，骑兵难以作战。驯服野公羊将带来新坐骑，为重振战力铺路，弥补山谷战力缺失的缺口。")
zh(7028,"维洛在玛拉顿的洞穴中寻找远古神祇的遗物。她以水晶雕刻为酬劳，渴望研究那些她认为沉睡已久的力量。")
zh(7029,"维利塔恩的腐蚀让玛拉顿的植物枯萎。一瓶净化药剂可将毒水转化为疗愈之物，但藤蔓仍受半人半兽的控制，可能对你发起攻击。")
zh(7041,"玛拉顿的植物正遭受维利塔恩毒素的侵害。净化水源可助治疗，但即便腐蚀被清除，藤蔓仍受其控制，随时可能反噬。")
zh(7042,"一批重要补给消失无踪，负责调查的探员也再未归来。最后的线索指向奥特兰克，找到这名探员，方知季节性物资的下落。")
zh(7043,"探员已认出，格林奇不单是偷糖的贼，更是把他冻成雪人的元凶。寻回那批货物，并回报：这名探员身陷冰封，急需援手。")
zh(7044,"维利塔恩与诺克赛恩盗取了塞雷布拉斯的权杖碎片，如今他游荡在洞穴中，被诅咒所困。找回碎片，或可尝试与他对话，协助对抗侵蚀他的腐化。")
zh(7045,"找回补给赢得烟林牧场的感激。冬天爷爷将亲自送来象征认可的礼物，以表彰你拯救季节性物资的贡献。")
zh(7046,"塞雷布拉斯需要帮助重铸权杖的杖身与钻石。仪式将复原通往洞穴的法器，也将这份使命托付于你，助他叔父的灵体重归完整。")
zh(7061,"此书收录了冬日庆典的多种传统，供有兴趣者参详。研读之后，将它交给凯恩，分享你对部族传说与历史的好奇。")
zh(7062,"你的联络人拒绝礼物，认为这违背了节庆的本意。卡尼克能解释这节日源自新生的寓意，从地精推动的贸易角度提供历史视角。")
zh(7063,"一本书记录了冬幕节与旧日传说。之后将它交给麦格尼，便能让国王知晓，也有其他人渴望了解那段过往。")
zh(7064,"瑟拉德拉斯与扎塔尔诞下了半人马，他们杀害了父亲并留存其遗骸。瑟琳德拉需要能击败公主的盟友，前往玛拉顿尝试夺回遗骸。")
zh(7065,"半人马杀死了扎塔尔，瑟拉德拉斯将遗骸藏于玛拉顿。玛兰迪斯需要协助对抗这元素之力，先夺回塞纳留斯之子，再返回石爪峰。")
zh(7066,"扎塔尔选择与半人马共存，因遗骸滋养的生命给予他们希望。一粒种子将传递雷姆洛斯的消息，让他知晓兄弟仍在，缓解他的忧虑。")
zh(7067,"被放逐者需要外人进入玛拉顿的圣地殿堂。他的指引将引导寻找联合坠饰的旅程，也支持着他被放逐的信念。")
zh(7068,"乌特尔奈想要玛拉顿岩怪的紫色晶石，因那里的魔法令他神往。他提供报酬，并建议结伴同行，以对抗半人马守护的洞穴危险。")
zh(7070,"特沃什研究晶石的奥术特性，需要从玛拉顿元素生物身上采集样本。吉安娜支持他的研究，他承诺将部分材料制成奖励，赠予寻得之人。")
zh(7081,"奥特兰克山谷的墓地是双方争夺的圣域。攻击敌方据点便加入对控制权的争夺，或许能守住直到援军抵达。")
zh(7082,"墓地是山谷里厮杀最烈的地方。攻打联盟据守的墓地，便是争夺那片地盘；守得够久，部落的援军就能开到。")
zh(7101,"部落视敌方的塔楼与工事为掌控山谷的关键。更换其旗帜便意味着争夺该据点，持久防御或许能将其摧毁，待联盟夺回前便终结战事。")
zh(7102,"塔楼与工事支撑着敌方的防御。攻击其旗帜便意味着将其纳入联盟争夺，若部落无法及时恢复，便有机会彻底摧毁这些据点。")
zh(7121,"雷矛军需官亟需招募人员，以夺回存放在矿坑中的储备物资。找到他，便能了解那些维持联盟部队装备的补给任务。")
zh(7122,"矿坑中既有矿石也有补给，但控制权并不稳固。攻占敌方据点，便可为雷矛部队在援军抵达前守住这些资源。")
zh(7123,"霜狼军需官正招募人员执行矿坑任务。向他报告，便能知晓如何维持部落在山谷中的补给，以支撑战斗所需。")
zh(7124,"部落争夺矿坑，为的是矿石与储备物资。击败矿坑首领，便可将其据为己有，并派遣部队保护这关键资源。")
zh(7141,"探险者协会意图调查山谷中可能存在的神器，却将责任归咎于霜狼氏族。击败德雷克·沙尔旨在削弱其抵抗，为联盟的调查铺路。")
zh(7142,"部落视雷矛氏族为奥特兰克的入侵者，意图将其驱逐。范达尔·雷矛在丹巴达尔指挥部队；直面将军，旨在通过打击敌方领导层决定战局。")
zh(7161,"新成员须先证明战斗意志，方能获得霜狼氏族的徽记。从豺狼人洞穴夺回旗帜，便是加入他们行列的入门仪式。")
zh(7162,"入战前，须赢得雷矛氏族的认可。冰翼洞穴的旗帜将证明你的价值，亦可换取专属新成员的徽记。")
zh(7163,"霜狼氏族认为你已超越普通士兵的职责。呈上入门徽记，将获得晋升，以表彰你所建立的友谊。")
zh(7164,"你勇敢而荣誉的举止，值得新的霜狼军阶。呈上现有徽记，氏族将正式认可你日益稳固的地位。")
zh(7165,"坚持与重创下的胜利，值得更高阶位。氏族要求你交出徽记，以表彰那些历经战役仍存活的士兵。")
zh(7166,"霜狼氏族视你为英雄，欲表彰你展现的权威。呈上徽记，将获得正式认可，彰显你在氏族守卫者中的特殊地位。")
zh(7167,"德雷克·沙尔与统帅褶裙赞誉你的族群守护。指挥之眼认可这份功勋，呈上你的徽记，便可正式晋升为指挥官。")
zh(7168,"你卓越的战功，令无数士兵难以企及。呈上徽记，便可获得雷矛卫队的荣誉认证，彰显你在战士群中的非凡表现。")
zh(7169,"你的战斗事迹已传至雷矛基地。军官们认为你削弱了敌军士气，请求你呈上徽记，以表彰你在守卫中的崇高地位。")
zh(7170,"你的努力令雷矛卫队敬仰。指挥官希望重铸你的徽记，以表彰你战功所赢得的声誉，以及你对敌军造成的震慑。")
zh(7171,"哈格丁视你的现身，为士卒们重燃希望的火种。呈上徽记，便可获得少数雷矛英雄方能拥有的荣誉头衔。")
zh(7172,"雷矛帐下有意承认你的指挥官身份。交上你现佩的徽记，便可受领这份尊荣——这一阶衔所系的，正是全军之力。")
zh(7181,"部落正面对雷矛入侵与冰斧巨魔的威胁。科尔拉克率军对抗，击败他，便能击溃维系这场战争第二战线的敌军主力。")
zh(7201,"黑铁族以一种能量赋予石像鬼强大威力。你的联络人渴望获取这种能量，用于制造憎恶，借此破解敌方工程学的秘密。")
zh(7202,"洞穴中起出的文书查明，科尔拉克就是冰斧的头领。等他走出藏身处，正面迎击，便是痛打这个被联盟视作凶悍大患的氏族。")
zh(7221,"雷矛卫队亟需更多战士加入战役。丹巴达尔的塔雷·石镐正招募人员执行深入敌境的重要任务，他能解释如何参与其中。")
zh(7222,"霜狼族欢迎志在对抗入侵山谷势力的志愿者。沃加正筹备一项针对联盟据点的行动，需要能参与其中的特工。")
zh(7223,"从铁炉堡运来的物资无法完全武装奥特兰克的部队。回收战场上的护甲碎片将缓解短缺，为战争提供更多资源。")
zh(7224,"雷格萨能将敌方护甲碎片转化为保护己方士兵的装备。战斗中回收这些材料，可将战利品用于持续装备霜狼军队。")
zh(7241,"霜狼族需要对抗雷矛卫队的战士。你的战斗经验足以让你寻找拉格隆德，与酋长偏爱的氏族并肩作战。")
zh(7261,"联盟将奥特兰克的征服视为铁炉堡王国的要务。哈格丁招募战士对抗巨魔与霜狼族，同时接收希望加入卫队的人员。")
zh(7281,"刘易斯希望杀死敌方指挥官兄弟，他相信希尔瓦娜斯或许也会将他转化。这项任务需要盟友，对抗他视作最危险的雷矛指挥官。")
zh(7282,"卡尔认为他的兄弟是被希尔瓦娜斯操控，没有自由意志，如今只想结束折磨。他派你潜入霜狼领地，将他击杀，宣称这是从亡灵中解脱。")
zh(7301,"最优秀的飞行员损失殆尽，联盟的空中支援陷入困境。调查他们最后的踪迹，揭开反攻时究竟发生了什么。")
zh(7302,"飞行指挥官被击落于敌方领地，部落的空战陷入混乱。找到他们最后的位置，才能确定他们的命运，也才有机会展开营救。")
zh(7321,"工作让他的联系人无法猎取海龟，制作他那道秘制浓汤。收集肉和香料，让他重拾配方，作为厨艺的证明。")
zh(7341,"考拉克箭矢充足，却缺枪弹。他提出等价交换，将箭矢换作弹壳，补足他耗尽的弹药。")
zh(7342,"误送的箭矢被当作瑟银弹使用，收件人愿以等价交换，将无用的库存转化为真正可用的补给。")
zh(7361,"纳亚克视精灵袭击为黑暗之矛的威胁，要求报复。敌人的头颅将证明你在他的战役中的作用，换取他在族中的地位。")
zh(7362,"玛加萨希望研究精灵活力，派学者前往前线。收集几缕头发作为样本，换取在牛头人中获得的认可。")
zh(7363,"刘易斯将人类的骨头与军务并行收集，献给暗药剂师。他轻蔑地称这项工作为‘治愈活人的良方’，却将搜集任务交由他人执行。")
zh(7364,"侏儒们得知牛头人猎杀并残害他们以取得样本。他们的代表要求报复，要求你以蹄子为证，证明你有能力击溃那些敌人。")
zh(7365,"鹿盔下令攻击战场上的食人魔，却驳回他们关于精灵起源的说法。重拾食人魔的气势，将为传递此命令的代表提供证据。")
zh(7366,"大主教宣称对亡灵施以永久死亡是仁慈。卡尔则要求取他们的心脏，于大教堂中焚化，将这教义转化为一项针对奥特兰克亡灵的行动。")
zh(7367,"霜狼矿场使攻击其据点变得危险。阻止供应他们武器的专家，便可解除武装而无需替换，待该军官行动受阻时便可实现。")
zh(7368,"雷矛的地雷依赖其爆破专家。若能除掉他，便可阻止替换被解除的炸药，创造在进军敌境前瓦解这道防线的机会。")
zh(7381,"拉格隆德担心食人魔的魔法可能让科尔拉克复活。若他归来，你须再度面对他，夺回他的头骨，对抗一个或许无法彻底击败的威胁。")
zh(7382,"哈格丁怀疑冰斧将试图复活他们的领袖。若科尔拉克归来，他要再度处决，并毁掉尸体，以头骨为证，待遗骸焚毁前确保证据留存。")
zh(7383,"泰达希尔的困境需借助其最强大的月亮井之水探查。你须前往最后一处井泉，带回样本，让调查得以继续。")
zh(7385,"瑟鲁加更愿接收霜狼氏族敌人的鲜血。大量收集将支撑她施法助盟友的仪式准备。")
zh(7386,"持久战常能收获成簇风暴水晶。法阵接受这些馈赠，用战场所得物资推进元素之力。")
zh(7401,"亚兹拉下令袭击敌方矮人，带回脊椎作为证据。她亦需残骸震慑挑战霜狼的山谷来者。")
zh(7402,"诺雷格要求雷矛士兵对抗敌方兽人。獠牙或牙齿将证明你遵从了他下达的指令。")
zh(7421,"纳亚克坚持以黑暗之矛之名继续攻击精灵。带回的头颅将证明你延续了他先前的复仇行动。")
zh(7422,"侏儒对残肢的报复令玛加萨的研究更趋紧迫。她的代理人需更多发丝，研究如今更狡诈的对手。")
zh(7423,"人类收集骨骸仍以所谓治愈为名。提供更多碎片，将延续路易斯部分服务的药剂师计划。")
zh(7424,"侏儒对牛头人的反击仍在继续。获取更多牛蹄，将证明你对那些认为针对他们子民的威胁不可容忍的代表而言，持续的敌意回应。")
zh(7425,"鹿盔认为对巨魔的战役尚未结束，要求继续推进。他的代表需要更多魔力，作为进一步伤亡的证明，以压制那些敌人。")
zh(7426,"卡尔持续宣扬被遗忘者之死是大主教仁慈的体现。他需要更多心脏用于仪式焚烧，维持这场宗教行动，以证明他的袭击正当。")
zh(7427,"亚扎拉希望将敌人的遗骸投掷过丹巴达尔，以在暴风怒骑中散播恐惧。在投石车装载恐怖弹药前，仍需更多脊椎。")
zh(7428,"诺雷格要求继续攻击为霜狼氏族而战的兽人。回收的牙齿将作为持续服务的证明，以支持他宣称能造福盟友的战役。")
zh(7429,"柯特需要一把戈多克镣铐钥匙才能逃出囚禁。他怀疑守卫可能携带，但任何食人魔都有可能是来源；交出一把，或许能挣脱锁链。")
zh(7441,"普希林在逃亡时偷走了阿兹·托林的法术书。尽管他不再希望钥匙也被夺走，但对以永生换自由的他而言，找回这本典籍仍是当务之急。")
zh(7461,"艾尔德’萨拉斯的疯狂依赖于伊莫尔’萨拉与王子的权势。削弱他们的防御，或许能终结这一切，解救仍被控制的城中灵体。")
zh(7462,"古物令你得以取走藏于图书馆台阶下的宝物。返回图书馆，领取这份古老储藏如今为你开启的馈赠。")
zh(7463,"艾尔德·萨拉斯出现水元素，必须记录其踪迹。莱德罗斯需要一些它的精魄，以一个实用的小法术交换你调查东翼异常现象的协助。")
zh(7478,"莱德罗斯可用急速圣典与材料制作装备附魔。集齐典籍与材料，便可请求他施展这番奥术造诣。")
zh(7479,"专注圣典与材料可令莱德罗斯召唤奥术。集齐典籍与材料，便可向图书馆的学者请求这项委托。")
zh(7480,"莱德罗斯获得防护圣典与重制其奥术所需的材料。这交易让他得以施展这本古籍与材料所载的知识。")
zh(7481,"泰尔米乌斯携着古精灵神器逃走，线索指向艾尔德·萨拉斯。找到他，无论生死，都可能重获他带走的知识。")
zh(7482,"寻找泰尔米乌斯的足迹从奎尔萨拉斯延伸至菲拉斯。他据称躲入厄运之槌，调查那里或许能查明他的下落，并寻回他携带的神器知识。")
zh(7483,"莱德罗斯可用失传的圣典制作微弱加速附魔。他需要这本典籍与材料，让原本不被看好的古籍发挥实际效用。")
zh(7484,"这本失落的典籍或许会吸引对魔法感兴趣的旅人。博学者莱德罗斯需要这本典籍与特定材料，以重现其中的奥秘，他怀疑上层精灵的灵体仍守护着这本书。")
zh(7485,"博学者莱德罗斯愿意重现一本失落典籍的奥秘，尽管他对它评价不高。只要你在北方翼厅找回典籍并提供材料，他便答应完成这项工作。")
zh(7486,"海达克西斯公爵认可了超出预期的贡献，尽管水元素族通常不像凡人般奖励。岛屿旁沉没的宝箱中，藏着他如今授权你取走的礼物。")
zh(7487,"一道裂隙通往火焰之王的领域，但你的本质必须调和。找回熔火碎片，将助洛索斯准备通往你无法察觉的传送门的连接。")
zh(7488,"蕾瑟塔蒂丝编织了一张网，困住厄运之槌的能量，却可能造成不可挽回的伤害。找回这装置，将能安全释放其力量，以免法师继续利用它。")
zh(7489,"蕾瑟塔蒂丝计划利用她网中被污染的能量对抗敌人。塔罗·刺蹄希望她停止，并将装置送往其他血精灵处研究，避免其创造者的鲁莽。")
zh(7490,"奥妮克希亚已陨落，她的头颅必须送至统帅处。将它送交萨尔，便是证明黑龙时代母龙已被击败的铁证。")
zh(7491,"伦萨克等待你的到来，以继续公开表彰你的成就。萨尔指引你前往力量谷，那里聚集了迎接你的人。")
zh(7492,"塔罗·刺蹄在菲拉斯请求协助处理一件隐秘事务，却未透露详情。若能在营地找到他，便能得知他托付给部落密探的使命。")
zh(7493,"你的制皮技艺可习得一件由奥妮克希亚鳞片织成的斗篷。伦萨克愿传授此技，以抵御奈法利安的吐息，并为对抗残余的黑龙时代做好准备。")
zh(7494,"蕾瑟塔蒂丝携一件蕴含危险能量的物品逃往厄运之槌。拉托尼库斯需要密探取回，前往菲拉斯寻他，方知如何遏制这股威胁。")
zh(7495,"奥妮克希亚的头颅证明了黑龙时代的母巢已被击溃。将其呈交伯瓦尔，让他通过确凿证据知晓战果，以向联盟呈堂证供。")
zh(7496,"玛丁雷少校在英雄谷等待你。呈上奥妮克希亚的头颅后，与他会面，继续这场为联盟与伯瓦尔传递战果的追认仪式。")
zh(7497,"玛丁雷少校传授一堂制皮技艺，以奥妮克希亚鳞片织成的斗篷可抵御奈法利安吐息，将所学化为对抗黑龙时代余孽的准备。")
zh(7498,"这卷书上有图书馆的印记，证明它本应归属那座典籍殿堂。归还给基尔达斯，便能重归其列。")
zh(7499,"这卷书上有图书馆的印记，证明它本应归属那座典籍殿堂。归还给基尔达斯，便能重归其列。")
zh(7500,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给基尔达斯，便能重归其所属的典籍群。")
zh(7501,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给麦库斯，便能重归其所属的典籍群。")
zh(7502,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给麦库斯，便能重归其所属的典籍群。")
zh(7503,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给麦库斯，便能重归其所属的典籍群。")
zh(7504,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给亚沃，便能重归其所属的典籍群。")
zh(7505,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给亚沃，便能重归其所属的典籍群。")
zh(7506,"这本典籍带着图书馆的印记，证明它本应属于那座藏书阁。归还给亚沃，便能重归其所属的典籍群。")
zh(7507,"图书馆的印记已破碎，典籍上的文字也难以辨认。它的价值值得归还给藏书阁，让这非凡的发现重归其主。")
zh(7508,"博学者莱德罗斯需要那把迟钝的精灵短剑继续锻造。交出武器，便是正式接下任务，开启淬炼奎尔萨拉尔的仪式。")
zh(7509,"古剑需要奥妮克希亚的呼吸来加热，她的尸身则用于后续淬炼。任务要求你直面巨龙，用她的烈焰在金属失去必要温度前完成锻造。")
zh(7541,"交付的吊坠需要深入研究，但佐尔希望此刻便认可你的贡献。他赠予的小礼物，既是对部落的谢意，也暗示学者们仍在调查这发现。")
zh(7562,"你对异界生灵的掌控，使恐惧战马成为可能。摩兹祖尔知晓召唤仪式，却需足够资源与力量，才能尝试驯服这般危险的坐骑。")
zh(7563,"束缚克索诺斯恐惧战马所需的符文，需要特殊墨水。狂暴猫头鹰兽的鲜血，正是摩兹祖尔需要的成分，用以书写召唤符文。")
zh(7564,"收集的鲜血必须化为墨水，供摩兹祖尔书写符文。戈瑟奇·邪眼具备必要的炼金术造诣，需尽快运送，方能开始准备仪式所需材料。")
zh(7581,"末日守卫的囚牢需要一种结合水晶并赋予其力量的束缚。来自厄运之槌半人马的凝固腐质，正是完成这些锁链所需的材料。")
zh(7582,"赫达琳恶魔的毒液凝结成抗魔水晶。戴奥需要这种材料打造能困住末日守卫的牢笼，而它正藏于暗语峡谷之中。")
zh(7583,"牢笼已备，但擒获末日守卫指挥官需活过它的暴烈反噬。戴奥建议带上能护你周全的同伴，协助你承受仪式中恶魔怒火的洗礼。")
zh(7601,"尼比将地狱火召唤术的课程，条件设定为寻回克罗苏斯的核心。因地狱火已近枯竭，须先收集组件以重燃其魂，伊普斯将详解筹备之法。")
zh(7602,"魔火可助克罗苏斯重燃，但伊普斯需来自三地的恶魔精魄。收集它们，方能炼出唤醒地狱火的火焰，继而寻回核心。")
zh(7603,"准备妥当的火焰，可在山谷残骸中重燃克罗苏斯。唤醒他需做好战斗准备，唯有击败他，方能将核心交予尼比，完成你的训练。")
zh(7604,"兄弟会的契约要先验明萨弗隆铁锭的真伪。接下条款，你便可索要那份图纸；至于萨弗拉斯日后如何动用，兄弟会一概不担干系。")
zh(7621,"艾瑞斯警告，试炼将考验你所有能力，必须独自完成，不得借助外力。聆听她的故事，将助你应对牧师试炼中任何外来援助的代价。")
zh(7622,"逃离斯坦索姆途中丧生的农夫，仍需机会活命。艾瑞斯要求你尽展全力保护他们，以阻止亡灵诅咒因拖延而持续蔓延。")
zh(7623,"通往克索诺斯的传送门，需一种艾泽拉斯罕见的尘土。贝恩霍勒或许拥有，但接近他须借助药剂，方能混入暗影议会仆从之中而不露痕迹。")
zh(7624,"魔王贝恩霍勒指控乌拉泰克为敌对势力窃取力量。他要求交出叛徒的心脏以证明忠诚，唯有介入这场纷争，方能获得他的恩典。")
zh(7625,"贝恩霍勒允诺可向他的仆从购买克索诺斯星尘，只要你能支付代价。将它带给戈瑟奇·邪眼，将助其筹备开启克索诺斯愤怒战马传送门的仪式。")
zh(7626,"钟铃是引导召唤法阵力量的工具之一。戈瑟奇可用特定药剂打造它，为轮盘与蜡烛的调和准备关键部件。")
zh(7627,"轮盘需承载并引导召唤法阵的狂暴能量。戈瑟奇需矿石与附魔碎片打造此仪器，方能用于克索诺斯的仪式筹备。")
zh(7628,"蜡烛将储存火焰以抵御干扰恶魔的侵扰。黑龙鳞片提供蕴含力量，使烈焰得以封存于法阵仪器之中。")
zh(7629,"羊皮纸需浸染克索诺斯星尘，但戈瑟奇缺少相应器具。若将其带往通灵学院实验室释放，恶魔仆从可代为完成。")
zh(7630,"仪式器具若在召唤时失灵，将需维护。戈瑟奇可准备黑色磁石以支撑它们，但需先获取秘银才能打造此辅助工具。")
zh(7631,"筹备已就绪，可尝试通过召唤法阵开启克索诺斯的传送门。研读指引，精确完成每一步，直面恐惧战马，将其灵体束缚。")
zh(7632,"这枚石化叶片散发着古老而强大的能量光芒。寻得它的主人，或许能解开它来历之谜，以及为何叶片表面布满深纹与褶皱，显得如此与众不同。")
zh(7633,"古树们曾在军团手中失去实体，但他们的灵体依旧守护着这片森林。他们通过任务揭示自身秘密，并教导如何召唤他们。")
zh(7634,"哈斯塔特能将一片叶子转化为非凡的箭囊，只需合适的绑定材料。成年蓝龙的肌腱，正是打造这件远古造物的原料。")
zh(7635,"古树们的长弓需要一条斯托玛能加持的弓弦。成年黑龙的肌腱，为完成这把武器提供了坚实的基础，与瓦特鲁斯提供的杖身相辅相成。")
zh(7636,"军团的爪牙仍在侵蚀自然，必须将其寻出。瓦特鲁斯提供了独自追踪的线索，因他人在场只会惊走敌人，而非与你正面交锋。")
zh(7637,"获取洛汉的香炉需付出牺牲与审判。即便用于正当用途，以捐赠弥补其损失，亦是你必须完成的试炼之一。")
zh(7638,"时候到了，该学习如何获得圣骑士的坐骑。葛瑞森深知其意义与所需试炼，将引导你从大教堂出发，筹备这匹坐骑。")
zh(7639,"洛汉将香炉交予你，期盼它能助你应对即将到来的驱魔试炼。将它带给葛瑞森，他将引领下一阶段的训练，而香炉正是他继续前行的关键。")
zh(7640,"香炉中盛着恐惧谷的土壤，可探测其灵体异动。将它置于异象出现之处，能驱散纠缠的灵体，使其现身接受审判的考验。")
zh(7641,"战马的护甲需用上等材料与灵界共鸣。格瑞曼德拥有这门手艺，先委托他打造，再为坐骑准备防护。")
zh(7642,"格瑞曼德需要材料打造护甲，并赋予其灵体亲和力，同时需支付工钱。收集齐全，便能完成包含手工鞍具与脚蹬的防护。")
zh(7643,"护甲需由特迪斯所持的灵体赐福，先获取特制饲料，再释放它。单凭释放无法安抚灵体，难以获得所需防护。")
zh(7644,"护甲已被灵体祝福，现已回到你手中。葛瑞森需它继续完成这项需要灵体防护的委托。")
zh(7645,"梅丽德丝能为灵体马匹准备饲料，她希望银手认可她的成果。她需要特制饼干与报酬，以弥补过往被嘲笑的屈辱。")
zh(7646,"香炉将催化出能刺破阴影的装置。两颗对比鲜明的金刚钻将完成信号灯，随后开始那场旨在救赎堕落战马的试炼。")
zh(7647,"装置将召唤灵体接受审判，再与死亡骑士对决。找回战马的魂魄，便能尝试用为此准备的护甲完成它的救赎。")
zh(7648,"格瑞曼德自豪地呈上完工的铠甲，并感谢你对他的手艺信任。葛瑞森船长需先查验，才能继续为需要精密防护的坐骑做准备。")
zh(7649,"图书馆的印记能辨明这本锻造书籍的主人。将它交给莱德罗斯，便能归还书籍，也让遗失的典籍重回典籍库。")
zh(7650,"图书馆的印记能辨明这本锻造书籍的主人。将它交给莱德罗斯，便能归还书籍，也让遗失的典籍重回典籍库。")
zh(7651,"图书馆的印记能辨明这本锻造书籍的主人。将它交给莱德罗斯，便能归还书籍，也让遗失的典籍重回典籍库。")
zh(7652,"德罗泰恩想交换帝国铠甲的配方，提议一个简单交易。提供瑟银锭，便可获得他提供的锻造设计。")
zh(7653,"德罗泰恩提供一套打造帝国重甲护腰的图纸，以瑟银锭交换。收集金属，便可获得这份锻造技艺。")
zh(7654,"德罗泰恩提供一套打造帝国重甲靴子的图纸，以瑟银锭交换。收集金属，便可获得这份锻造技艺。")
zh(7655,"德罗泰恩提供一套打造帝国重甲臂甲的图纸，以瑟银锭交换。收集金属，便可获得这份锻造技艺。")
zh(7656,"德罗泰恩愿以钍换你一套帝王铠甲的打造图纸，集齐金属便能获得这副盔甲的工艺配方。")
zh(7657,"德罗泰恩愿以钍换你一套帝王头盔的打造图纸，集齐金属便能获得这副头盔的工艺配方。")
zh(7658,"德罗泰恩愿以钍换你一套帝王护腿的打造图纸，集齐金属便能获得这副护腿的工艺配方。")
zh(7659,"德罗泰恩愿以钍换你一套帝王肩甲的打造图纸，集齐金属便能获得这副肩甲的工艺配方。")
zh(7660,"奥古纳罗愿为你更换你的冰霜狼坐骑，新坐骑速度不变，只是外观不同，你可先查看替换选项再做决定。")
zh(7661,"奥古纳罗愿为你更换你的红狼坐骑，新坐骑速度不变，只是外观不同，你可先查看替换选项再做决定。")
zh(7662,"哈布·爪蹄愿为你更换你的蓝科多兽坐骑，新坐骑速度不变，只是外观不同，你可先查看替换选项再做决定。")
zh(7663,"哈布·爪蹄愿为你更换你的绿科多兽坐骑，新坐骑速度不变，只是外观不同，你可先查看替换选项再做决定。")
zh(7664,"祖尼尔为你提供一头白色迅猛龙的替代品。新坐骑速度不变，只是外观不同。你可在决定前查看可供选择的替代品。")
zh(7665,"祖尼尔为你提供一头红色迅猛龙的替代品。新坐骑速度不变，只是外观不同。你可在决定前查看可供选择的替代品。")
zh(7666,"葛瑞森若你重返通灵学院，将再赠你一个预言水晶球。他已知你为取得它所付出的努力，并提供一个替代品，以应对再度面对埋骨地的危险。")
zh(7667,"萨格尼需完成一件穿透埋骨地阴影的器具。他缺乏最后所需的金刚钻，请求物资支援，以完成一件用于灵体工作的工具。")
zh(7668,"达克雷尔意图从通灵学院操控灵体领域。这件器具将召唤他的仆从，引他现身，意图阻止死亡骑士并逆转已造成的伤害。")
zh(7669,"萨格尼为重返通灵学院的试炼者提供另一个水晶球。这项供给承认你已为使用它付出的代价，并允许你再度面对埋骨地的危险。")
zh(7670,"训练的下一阶段将引导你追寻属于自己的坐骑。葛瑞森将在大教堂向你解释试炼与准备，指引你获取圣骑士信赖的坐骑。")
zh(7671,"莱兰奈为你提供一头霜刃豹的替代品。新坐骑速度不变，只是外观不同。你可在决定前查看可供选择的替代品。")
zh(7672,"莱兰奈愿为你换乘夜刃豹。新坐骑速度不变，外观却有所不同。你可先查看可选的替代品再做决定。")
zh(7673,"维隆·冻石愿为你换乘霜山羊。新坐骑速度不变，外观却有所不同。你可先查看可选的替代品再做决定。")
zh(7674,"维隆·冻石愿为你换乘黑山羊。新坐骑速度不变，外观却有所不同。你可先查看可选的替代品再做决定。")
zh(7675,"米利·羽哨愿为你换乘蓝色机械陆行鸟。新坐骑速度不变，外观却有所不同。你可先查看可选的替代品再做决定。")
zh(7676,"米利·羽哨愿为你换乘白色机械陆行鸟。新坐骑速度不变，外观却有所不同。你可先查看可选的替代品再做决定。")
zh(7677,"凯蒂愿用另一群新马中的一匹，换你的白马。换来的马模样不同，脚程一样；代价是交出坐骑，再付她要的那笔钱。")
zh(7678,"凯蒂·亨特愿为你换乘棕马。新坐骑速度不变，外观却有所不同。你可先查看可选的替代品再做决定。")
zh(7701,"迪菲亚兄弟会悬赏通缉玛托留斯，因他投靠了黑铁阵营。他的头颅将成为一场惩罚背叛的猎杀，地点在灼热峡谷。")
zh(7703,"克罗卡斯希望新王找回托塞德林盗走的远古神器。传说这件神器与真正的戈多克统治者有关，归还它将重获先王未能取回的东西。")
zh(7704,"女仆留下了一只巨大的雕花枕头，或许会引起艾沃奈斯的兴趣。将这个发现带给她，便可判断她是否愿意为如此罕见之物提供赏金。")
zh(7721,"元素生物阻碍了索尔宾的生意，却也能为他的机器提供动力。它们的核心将助力缩小装置的升级，而你则要对付他视为烦扰的生物。")
zh(7722,"玛托留斯叛逃时带走了秘密配方，或许作为与新盟友的交易条件。找回这些图纸，便能将珍贵的锻造知识归还原主。")
zh(7723,"汉瑟尔的手指肿胀，已无法如从前般战斗。他需要你代他执行任务，对付峡谷的作战傀儡，因身体问题已无法继续工作。")
zh(7724,"熔岩蜘蛛制造了不少麻烦，它们炽热的攻击也让奥菲斯特忧心。汉瑟尔希望将清理工作交给你，好让他得以休息，处理他所担忧的威胁。")
zh(7725,"索尔宾仍需缩小后的巨人的残留物来完成他的工作。他提供的报酬比从前少，但承诺若试炼继续，会向地精联系人传颂你的帮助。")
zh(7726,"索尔宾的生意仍需更多元素核心来维持机器运转。虽无法重提先前的报酬，但他愿在黑市联系人中为你增添声望，以换取更多物资。")
zh(7727,"探险队需要接近熔岩池，但熏火龙阻碍了探索。汉瑟尔的脚疾让他无法参与任务，因此请求你先减少数量，好让研究人员顺利进入。")
zh(7728,"兄弟会丢失了一件锻造工具和一个哨兵用的望远镜。他们相信是黑铁人偷走了，因此悬赏寻找这两件对工作至关重要的器具。")
zh(7729,"斯克兰格提供对抗黑铁工头和奴隶贩子的任务。这项工作旨在通过愿意参与血腥战役的战士，削弱兄弟会在峡谷中的竞争势力。")
zh(7730,"侦察兵认为祖克·阿什激怒了豺狼人的狂鱼，威胁到营地。深入他们的领地可减少数量并获取情报，甲壳则能证明他们曾经历的战斗。")
zh(7731,"一只巨大的昆虫散发出与同伴不同的气息。它的腺体或许能帮助研究这一特性，并指引对祖克·阿什的应对策略，需要从毒刺鞭笞者身上采集样本。")
zh(7732,"祖克·阿什的威胁仍在持续，尽管当地取得了一些进展。将报告交给基尔兹宾，可与一位研究异常生物的专家分享发现，寻求更有效的保护方案。")
zh(7733,"北地的雪人皮毛更好，筋骨也更硬。你的接头人愿出好价收这种料子，只提醒一句：这趟猎捕比从前更难。")
zh(7734,"北境雪人的皮子更厚，可对手也更凶悍。接头人出价不低，要你取回这等材料，同时警告：新的猎场，险过从前。")
zh(7735,"雪人的皮毛以厚实坚韧见长。普拉特正寻这种料子，若比怒痕一带所得更胜一筹，他尤其看重。")
zh(7736,"黑铁兄弟会的炽热助熔剂日渐枯竭。收集鳞片、煤炭与皇血草，可重新调配混合物，以换取与铁匠们关系的提升。")
zh(7737,"兄弟会认可你的进展，给予更高敬意。黑铁残油能提炼炽热助熔剂，故从深渊回收更多残油，将助益铁匠们的工艺。")
zh(7738,"雪人皮毛若厚实坚韧兼备，便是上佳样本。杉多尔正在收皮子，比寻常怒痕货色更好的，他尤其看重。")
zh(7761,"一封信揭示，指挥水晶仅能传送佩戴达基萨斯印记之人。获取它需调查守卫印记的将军，设法绕过黑翼之巢入口的防护。")
zh(7781,"奈法利安已被击败，其头颅成为胜利的明证。将之献给伯瓦尔，报告与黑石山领主的对决结果。")
zh(7782,"石桥已在英雄谷等待你。头颅呈上后，会议将继续认可这场胜利，由联盟军官见证。")
zh(7783,"奈法利安的头颅再度证明对黑龙时代的胜利。将之献予统帅，让萨尔直接听取对决结果，见证巨龙的败亡。")
zh(7784,"萨鲁法尔大王在力量谷静候，待奈法利安的头颅送达。此行不仅是对胜利的肯定，更是对部落顶尖将领的礼遇。")
zh(7785,"德米提恩命你查验那艘承载风觅者重生的器物。研究并归还它，是释放元素之力的筹备之一环。")
zh(7786,"要解开桑德兰的束缚，须备齐他的枷锁、源质，以及火焰之王的精魄。德米提恩要先毁掉拉格纳罗斯的肉身，收齐这些物事，才谈得上还这元素生物自由。")
zh(7787,"风觅者的败北留下一柄沉眠的利刃，也揭穿德米提恩的背叛。命他以所供材料唤醒雷霆之怒，让此武器重归战场。")
zh(7788,"部落的伐木行动正毁坏银翼视作圣地的森林。助他们守卫要塞，获取象征你对抗入侵者功绩的印记。")
zh(7789,"部落视灰谷为己有，拒绝银翼阻止其采伐。对抗哨兵，便是证明你在这场森林争夺战中的贡献。")
zh(7791,"暴风城的羊毛储备靠全民支持集资。你的捐赠将助力建设这储备，与他人同获慷慨之誉。")
zh(7792,"达纳苏斯的羊毛采集行动依靠社区支持。你的捐赠将助力建立储备，与他人贡献并肩，赢得慷慨的赞誉。")
zh(7793,"丝绸储备已告急，风暴城正急需补给。你的贡献将缓解短缺，也令你在风暴城的声望水涨船高。")
zh(7794,"风暴城的魔法织物所剩无几，唯有依靠社区捐赠方能补足库存，而你的付出将被铭记于共同目标之中。")
zh(7795,"在你先前的捐赠之后，符文布仍是最迫切的需求。率先贡献此物，将延续风暴城恢复储备的行动。")
zh(7796,"符文布的需求持续未减。继续提供材料，不仅可维持储备，也将赢得风暴城对你持续支持的肯定。")
zh(7798,"丝绸储备已告急，风暴城正急需补给。你的贡献将缓解短缺，也令你在达纳苏斯的声望水涨船高。")
zh(7799,"达纳苏斯的魔法织物所剩无几，唯有依靠社区捐赠方能补足库存，而你的付出将被铭记于共同目标之中。")
