zh(7801,"符文布的需求持续未减。继续提供材料，不仅可维持储备，也将赢得达纳苏斯对你持续支持的肯定。")
zh(7802,"铁炉堡的羊毛储备依靠社区支持逐步累积。你的捐赠将与其他人的贡献共同充实储备，赢得认可。")
zh(7803,"丝绸储备已接近枯竭，亟需补给。提供布料将缓解短缺，提升你在铁炉堡社区中的声望。")
zh(7804,"铁炉堡正面临法术织物短缺。社区捐赠是补足库存的关键，助人者将获得认可。")
zh(7805,"在初步捐赠之后，符文布仍是迫切需求。率先贡献此物，将延续铁炉堡社区恢复储备的行动。")
zh(7806,"符文布的需求持续未减。提供更多材料将维系储备，赢得铁炉堡对你持续支持的认可。")
zh(7807,"诺莫瑞根流亡者正依靠社区支持收集羊毛。你的捐赠将与其他人的努力共同充实储备，彰显你的慷慨。")
zh(7808,"丝绸储备已接近枯竭，急需补给。提供布料将缓解短缺，提升你在诺莫瑞根流亡者社区中的声望。")
zh(7809,"诺莫瑞根流亡者正面临法术织物短缺。社区捐赠是补足库存的关键，助人者将获得认可。")
zh(7810,"竞技场高手的技艺似乎还藏着更深的秘密。那个组织古拉巴什赛事的海盗或许能解释一切，去找短剑约翰继续探查这份认可究竟意味着什么。")
zh(7811,"在你之前的捐赠之后，符文布仍是迫切所需。提供最初的材料将延续恢复储备的行动，支持诺莫瑞根流亡者社群的重建。")
zh(7812,"符文布的需求在初始捐赠后依然持续。提供更多材料将维持储备，并赢得诺莫瑞根流亡者对你持续支持的认可。")
zh(7813,"幽暗城的行动正通过社区支持收集羊毛。你的捐赠将与他人的贡献共同建立储备，赢得众人对你的慷慨赞誉。")
zh(7814,"丝绸储备见底，这场征募正等人填补。交上布料，可解一时之缺，也能让幽暗城的人对你另眼相看。")
zh(7815,"海龟偷走了钓鱼者卡图姆的诱饵，扯断了他的鱼线，扰乱了村庄的捕鱼。减少它们的数量，能解决这个影响钓鱼者与恶齿部族的烦恼。")
zh(7816,"加莫里塔吞下了卡图姆最好的诱饵，自那之后渔获便一落千丈。去对抗那只异常的海龟，找回钓鱼者视作恢复渔获关键的装备。")
zh(7817,"幽暗城正面临魔法织物短缺。行动依赖社区捐赠来补足库存，那些协助达成目标的人将获得认可。")
zh(7818,"先前的捐赠已缓解燃眉之急，但符文布仍属紧要物资。首批物资的贡献将延续行动，助力幽暗城社区恢复储备。")
zh(7819,"符文布的需求持续存在，后续的捐赠将维系储备，并赢得幽暗城对您持续支持的认可。")
zh(7820,"雷霆崖的行动依靠社区支持收集羊毛。您的捐赠将与他人的贡献共同建立储备，并赢得社群对您慷慨的肯定。")
zh(7821,"丝绸储备已接近枯竭，行动亟需援助以补充库存。提供布料将缓解短缺，并提升您在雷霆崖社群中的声望。")
zh(7822,"雷霆崖正面临魔法织物短缺。行动依赖社区捐赠以补充库存，协助达成此共同目标者将获认可。")
zh(7823,"先前的捐赠已缓解燃眉之急，但符文布仍属紧要物资。首批物资的贡献将延续行动，助力雷霆崖社区恢复储备。")
zh(7824,"先前的捐赠已缓解燃眉之急，但符文布仍属紧要物资。首批物资的贡献将延续行动，助力奥格瑞玛社区恢复储备。")
zh(7825,"符文布的需求持续存在，后续的捐赠将维系储备，并赢得雷霆崖对您持续支持的认可。")
zh(7826,"奥格瑞玛的羊毛收集行动依靠社群支持。你的捐赠将助力储备建设，与他人共襄盛举，赢得赞誉。")
zh(7827,"丝绸储备已近枯竭，行动亟需补给。提供布料可缓解短缺，亦能提升你在奥格瑞玛社群中的声望。")
zh(7828,"银鬃狼潜伏伏击恶齿猎人，造成惨重伤亡。马克霍尔希望扭转局势，先发制人追踪掠食者，以防他们再度袭击族群。")
zh(7829,"野蛮枭兽以利爪与喙刃杀戮恶齿战士，马克霍尔要求在辛特兰削减此威胁，待猎季结束便评估你的贡献。")
zh(7830,"猎户马克霍尔指控蛮锤部族训练狮鹫猎杀巨魔。他希望针对最古老的个体下手，并取下翎羽，作为报复敌对生物的证据。")
zh(7831,"奥格瑞玛正面临魔织布短缺，行动依赖社群捐赠补足库存，助人者将获赞誉与认可。")
zh(7832,"符文布的需求持续不减，需更多物资维持储备，你的持续支持将赢得奥格瑞玛的赞誉。")
zh(7833,"黑暗之矛的羊毛收集行动依靠社群支持，你的捐赠将助力储备建设，与他人共襄盛举，赢得赞誉。")
zh(7834,"丝绸储备已所剩无几，补给行动亟需援助。提供布料将缓解短缺，同时提升你在黑暗之矛社群中的声望。")
zh(7835,"黑暗之矛正面临魔织布短缺，补给行动依赖社群捐赠来补充库存，那些协助达成目标者将获得认可。")
zh(7836,"在你先前的捐赠后，符文布仍是迫切需求。率先贡献此材料，将延续补给行动，协助黑暗之矛社群恢复储备。")
zh(7837,"符文布的需求在初始贡献后仍未缓解。提供更多材料将维持储备，也让你赢得黑暗之矛对持续支持的肯定。")
zh(7838,"短约翰只在收集数件大师级饰品后，才承认你的竞技场大师地位。这项任务将证明你对古拉巴什赛事的掌控，超越单一成就。")
zh(7839,"邪枝窃取了一只地精在救下斯拉提性命后赠予他的工具。虽有替代品，但他渴望找回那件具有纪念意义的物品。")
zh(7840,"邪枝的袭击迫使拉尔德在外出时丢弃食物。饥饿却不敢返回，他急需将北岛上的午餐寻回。")
zh(7841,"奥索希望惩罚野锤与高等精灵的协议。攻击精灵，旨在警告他们的矮人盟友，用伤亡作为震慑该联盟的讯息。")
zh(7842,"奥索认为矮人与狮鹫的羁绊是另一种威慑手段。从他们的坐骑身上取回羽毛，便能传递一则针对蛮锤部族珍视之物的信息。")
zh(7843,"染血的羽矛已准备就绪，作为警告之用。奥索要求将其插在鹰巢山的水井旁，将威胁直接送达蛮锤部族的核心。")
zh(7844,"邪枝族吞噬其他巨魔与人形生物，这种行径令邻近族群难以容忍。在祖尔·金缺席之际，亚约·金不愿等待新领袖解决威胁，转而寻求协助对抗他们。")
zh(7845,"托恩图斯在一次夜间突袭中被俘，至今仍被囚禁在金塔拉洛尔。他的伴侣担心海克斯会将他献祭给哈卡，因此迫切需要救援，以免村庄遭受毁灭性打击。")
zh(7846,"托恩图斯需要击塔雅手中的钥匙，藏于附近洞穴之中。从守卫森严的保管者手中夺走它，将解开他的枷锁，并为长者的归乡铺路。")
zh(7847,"托恩图斯如今得以返回，他希望妻子能听到这个好消息。传递消息将提前报告救援行动，也为你的协助赢得感激。")
zh(7848,"一道裂隙通往火焰之王的领域，但你的本质必须调和。找回一块熔火碎片，将使洛索斯能准备通往你无法察觉的传送门的连接。")
zh(7849,"马克霍尔失去了双胞胎兄弟，被邪枝族处决并喂给他们的生物。找回遗骸无法挽救他的生命，却为他的灵魂提供一丝帮助的可能。")
zh(7850,"染血的器皿助长邪枝的腐化，借哈卡的魔力催动他们的狂乱。夺取这些器皿，是净化尝试，亦能削弱血神对部族的掌控。")
zh(7861,"断齿族长下令将海克斯与她的精锐卫队绳之以法。悬赏寻求能直面金塔哈洛尔领导层、阻止其权力延续的战士。")
zh(7862,"马尔科尔的死使恶齿守卫的统领空缺。申请人须先证明自身能对抗邪枝，方能向断齿族长申请此职。")
zh(7863,"银翼认可你的贡献，赠予补给与绷带，支援战歌峡谷。这份物资专为持续战役而备，助你维持战线。")
zh(7864,"你的服务赢得银翼支援包。其中干粮与绷带仅限战歌峡谷使用，为战役持续提供补给。")
zh(7865,"你的服务赢得银翼支援包。其中干粮与绷带仅限战歌峡谷使用，为战役持续提供补给。")
zh(7866,"你的服务赢得战歌氏族的认可。他们赠予干粮与绷带，供你在峡谷内持续奋战，物资专为战役而备。")
zh(7867,"你的服务赢得战歌的支援包。其中干粮与绷带仅限战歌峡谷使用，为战役持续提供补给。")
zh(7868,"部落的行动赢得了一套支援物资，其中干粮与绷带只能在战歌峡谷使用，为持续的战役提供补给。")
zh(7871,"部落的伐木行动摧毁了银翼视作圣地的森林。守护他们的要塞，既可击退入侵者，也能获得象征你贡献的徽记。")
zh(7872,"部落砍伐了银翼视为圣地的森林，以供战争机器使用。守护要塞，便是对抗这场入侵的证明。")
zh(7873,"部落砍伐了银翼视为圣地的森林，以供战争机器使用。守护要塞，便是对抗这场入侵的证明。")
zh(7874,"部落宣称灰谷的资源归其所有，视银翼为阻碍。对抗他们的哨兵，以信物证明你参与这场森林争夺战。")
zh(7875,"部落宣称灰谷的资源归其所有，并指控银翼阻挠利用。击败哨兵，捍卫这一主张，以荣誉印记彰显你的贡献。")
zh(7876,"部落宣称灰谷的资源归其所有，并指控银翼阻挠利用。击败哨兵，捍卫这一主张，以荣誉印记彰显你的贡献。")
zh(7877,"古树允许你寻获藏于图书馆台阶下的宝物。返回图书馆，领取这古物所赐予你的新奖励。")
zh(7881,"暗月马戏团的工作人员在巡演途中磨破了不少靴子。克洛诺斯需要兼具耐用与时尚的鞋履，为此提供雕花皮靴门票，以确保巡演人员的足部供应。")
zh(7882,"马戏团在巡演期间也需要守卫，因此他们需要坚固的防护装备。克洛诺斯正在收集韧化皮甲，凡能协助供应者皆可获得门票。")
zh(7883,"亚布正在寻找世界上最大的地精加入他的演出。克洛诺斯希望在那位表演者现身前就准备好戏服，同时需要野人背心作为巨型服装的基础。")
zh(7884,"亚布的演出计划包括为被鳄龟抚养长大的男孩打造湿地环境，或许还会有鱼人。克洛诺斯需要龟甲腿铠，以防工作人员在搭建与拆除这些设施时被淋湿。")
zh(7885,"巡演的频繁使用让经营成本居高不下。克洛诺斯发现了一种廉价用途：用皮甲套件修补破损的帐篷。他需要更多套件，以维持这些反复维修的支出。")
zh(7886,"你在战歌峡谷的协助已获认可。银翼功勋奖章表彰了你的贡献，而进一步的支持则能加深阵营对你的信任。")
zh(7887,"你的贡献已为银翼要塞带来价值，但冲突仍未结束。更多奖章将证明你持续的协助，进而提升代表们对你的信赖。")
zh(7888,"你在战歌峡谷的协助已获认可。银翼功勋奖章表彰了你的贡献，而进一步的支持则能加深阵营对你的信任。")
zh(7889,"克莉·希克斯已超越训练套装中的重量限制。要维持‘世上最强女性’的称号，她需要更重的阻力，因此以暗月马戏团门票换取粗制平衡石，用于增强训练。")
zh(7890,"克莉·希克斯练力，举的是一根挂满重砂轮的长杆。砂轮耗损，她得添新的才能接着练；谁能凑齐这套家什，她便以暗月马戏团的门票相赠。")
zh(7891,"克莉·希克斯正为自己的展位准备服装，她希望拥有绿铁护腕，既增添色彩又不遮盖肌肉。为此，她以暗月马戏团门票换取制作材料。")
zh(7892,"克莉·希克斯计划在表演中砸毁观众提供的物品，她需要一把巨型黑色锤来展现力量。她正寻找能打造此锤的人。")
zh(7893,"克莉·希克斯一路行走，一路收集练力的法门，如今操练的功夫，非极密的砂轮不能胜任。她要再添几件这样的重物，才撑得住那身惊人力气背后的苦功。")
zh(7894,"亚布·尼比盖尔正为他的动物园打造新奇项目，但建设需要大量材料。瑞林在收集铜质调节器用于机械组件，凡能协助者均可获得暗月马戏团门票。")
zh(7895,"瑞林构想一个让访客测试技能的展位，他需要高速青铜齿轮推进建造，凡能提供材料者皆可获得暗月马戏团门票。")
zh(7896,"瑞林希望在展位开幕时以焰火宣传。尽管项目尚未完成，他已开始收集绿色焰火，凡能提供物资者皆可获得暗月马戏团门票。")
zh(7897,"瑞林的摊位因机械故障无法营业，他急需机械修理包来修复设备，愿意以暗月马戏团门票换取所需工具。")
zh(7898,"亚布需要瑟银零件打造未来景点，瑞林代他收集，凡能提供零件者皆可换取马戏团门票。")
zh(7899,"亚布想以小奖品吸引游客，他需要贫瘠之地或黑海岸的猫爪作为赠品材料，愿以门票换取。")
zh(7900,"亚布打算用熊皮制作软玩具，接受灰谷或希尔斯布莱德熊的撕裂皮毛，以门票交换所需材料。")
zh(7901,"亚布深知，精巧的呈现能让平凡之物化为珍品，他正收集凄凉之地与荒芜之地的狼尾，用于制作嘉年华小饰品。")
zh(7902,"暗月马戏团以想象力为舞台，亚布需鲜艳羽毛打造其中一项表演，愿以门票换取艾泽拉斯危险地带的鸟羽。")
zh(7903,"亚布设计一款令人惊惧的装置，认为蝙蝠眼睛最能营造诡异氛围，他需东瘟疫之地蝙蝠的眼珠作为材料。")
zh(7905,"暗月马戏团设于闪金镇外，正广而告之。持宣传券至马戏团内格瓦斯·格里加特处，可换得免费奖票。")
zh(7907,"当比斯巨兽的卡牌凑成完整牌组，一张神秘的第九张卡随之显现。其铭文召唤你将这套收藏带往暗月马戏团，它在莫高雷与闪金镇之间巡回驻扎。")
zh(7908,"成为竞技场高手的称号，似乎蕴含着更深的意味。桑德所举办的活动，或许能解释其中的差别，以及这场挑战还有哪些值得探索之处。")
zh(7921,"你在战歌峡谷的贡献已被认可，但这场战役仍在继续。更多功勋符文将证明你的持续付出，并赢得协调战争行动者的进一步信任。")
zh(7922,"你在战歌峡谷的付出已证明价值，对抗银翼要塞的战斗仍在持续。荣誉印记将进一步肯定你对战歌事业的贡献。")
zh(7923,"你在战歌峡谷的付出已证明价值，对抗银翼要塞的战斗仍在持续。荣誉印记将进一步肯定你对战歌事业的贡献。")
zh(7924,"战歌阵营已认可你的帮助，但仍需持续对抗银翼要塞。更多荣誉印记将证明你持续的贡献，直至峡谷的争夺仍未结束。")
zh(7925,"你的努力已证明你对战歌阵营的价值。他们的代表呼吁继续对抗银翼要塞，并以更多荣誉印记作为服务的证明。")
zh(7926,"暗月马戏团现正驻扎在莫高雷，雷霆崖外的旷野。它正大肆宣传自己的亮点，一张宣传券可带入游乐园内的吉瓦斯·格里加特处，换取免费奖券。")
zh(7927,"当入口套牌凑成完整牌组，一张神秘的第九张卡牌浮现。其铭文指引你将这套牌送往暗月马戏团，它在莫高雷与闪金镇之间巡回驻扎。")
zh(7928,"当督军套牌凑成完整牌组，一张神秘的第九张卡牌浮现。其铭文指引你将这套牌送往暗月马戏团，它在莫高雷与闪金镇之间巡回驻扎。")
zh(7929,"当元素套牌凑成完整牌组，一张神秘的第九张卡牌浮现。其铭文指引你将这套牌送往暗月马戏团，它在莫高雷与闪金镇之间巡回驻扎。")
zh(7930,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票五张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7931,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票五张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7932,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票十二张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7933,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票四十张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7934,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票五十张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7935,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票十张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7936,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票五十张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7937,"塞格赠予你的运势牌触感异样温热，映出东谷伐木场的画面。画面聚焦于马厩旁的草垛，暗示着你命运的下落。")
zh(7938,"塞格的运势牌揭示了月溪镇下方死亡矿井的曲折通道。幻象中一道传送门通往矿井，一个奇怪的箱子浮现，指引你深入探索。")
zh(7939,"你的投递减轻了克莉·希克斯对致密砂轮的需求。即便如此，她仍接受额外的砂轮，并以暗月马戏团门票交换。")
zh(7940,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票一千二百张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(7941,"克洛诺斯因你的协助而物资充足。虽然需求已减，他仍愿以暗月马戏团门票交换更多护甲组件。")
zh(7942,"你送去的瑟银零件，补上了亚布那处展台的缺口。瑞林记着这份情；需求虽已不如先前急切，他仍愿用暗月马戏团的门票换你余下的零件。")
zh(7943,"亚布的可怕魅力已因你的协助而收集了不少素材。他的需求如今更小了，但仍接受来自东瘟疫之地的邪恶蝙蝠眼，换取暗月马戏团的入场券。")
zh(7944,"塞格的占卜显示，西南方向的十字路口附近有一座洞穴，通往哀嚎洞穴的深处。洞中出现的箱子，暗示着一个值得探查的地方。")
zh(7945,"塞格的占卜显现出莫高雷的白鬃石。画面聚焦于洞穴入口附近的树桩，指向你该寻找承诺之财的所在。")
zh(7946,"加布加布与摩尔亚重聚，后者不愿再让对方逃去寻酒。带来黑铁啤酒可补足她的库存，并换取青蛙卵。")
zh(7962,"乔恩·莱克拉夫特认定，剥取狡猾兔子的皮毛是件要紧事，便托你供上皮子。")
zh(7981,"吉瓦斯以暗月马戏团赚得的门票换取奖品。此项要票一千二百张——马戏团驻留此地期间，可兑的买卖不止这一桩。")
zh(8021,"宠物兑换券对应的是白色鱼人卵的兑换。出示此券，即可领取与之关联的专属奖励。")
zh(8022,"宠物兑换券对应的是白色鱼人卵的兑换。出示此券，即可领取与之关联的专属奖励。")
zh(8023,"宠物兑换券可兑换白色鱼人卵。出示此券，即可领取对应奖励。")
zh(8024,"宠物兑换券可兑换白色鱼人卵。出示此券，即可领取对应奖励。")
zh(8025,"宠物兑换，可换白色鱼人卵。出示此券，便是领取对应奖励。")
zh(8026,"宠物兑换券可兑换白色鱼人卵。出示此券，便是领取对应奖励。")
zh(8041,"金罗克认可你的坚韧与意志之力，代表赞达拉向你致意。他以穆贾巴山之力所铸的符咒，作为对你抗争敌人的肯定。")
zh(8042,"金罗克认为将哈卡困于祖尔格鲁布，是维系世界安全的关键。为支持这场斗争，他愿强化你的穆贾巴符咒，延续你与赞达拉的羁绊。")
zh(8043,"莫托尔已将你的事迹禀报国王，你的名号正传遍祖尔格鲁布之外。金罗克承蒙你的效劳，特此请求你的符咒，以作进一步加持。")
zh(8044,"拉斯塔哈的问候，是对一位外族人非凡荣耀的承认。金罗克再度强化你的穆贾巴符咒，并述说其力量已悄然与你的灵魂相连。")
zh(8045,"灾厄让赞达拉与盟友走到了一起，而这些盟友的信念对他们而言仍属陌生。金罗克提供一枚象征与部族友谊并警告敌人的印记，进一步服务将开启强化它的可能。")
zh(8046,"在你的服务之后，金罗克重新审视了你对光的信仰。为承认这份转变，他请求你交出已拥有的印记，以便增强它的力量。")
zh(8047,"你的决心已超越金罗克最初的疑虑，如今赞达拉视你为无价盟友。这份认可促使他再度强化你所携带的印记。")
zh(8048,"拉斯塔哈如今认定你是赞达拉真正的盟友。金罗克要求你交出印记，作为这份认可的象征，并以最终的强化表达对你的敬意。")
zh(8049,"阿尔塔比姆因你作为牧师的服务，赠予祖达萨之眼以表谢意。这枚符咒与你与赞达拉的关系相连，他愿随这份羁绊的加深而赋予宝石力量。")
zh(8050,"祖达萨之眼已开始涌动能量，阿尔塔比姆认为你已准备好迎接下一步。他请求你交出符咒，以便再度灌注能量，继续它的成长。")
zh(8051,"你对抗古拉巴什的战事传闻，甚至已传入王室耳中。阿尔塔比姆认为是时候再度灌注祖达萨之眼，请求你交出符咒以完成这项服务。")
zh(8052,"阿尔塔比姆珍视你对抗哈卡大军的贡献，认为祖达萨之眼已准备好实现其全部潜能。他请求你交出宝石，以便完成这场强化。")
zh(8053,"赞达拉自由思想者敬重那些为信念抗争压迫者的决心。金洛克提供一个展现这种决心的机会：击败哈卡的追随者，夺回祖尔格鲁布中的强力圣贤。")
zh(8054,"赞达拉铭记那些古时的异见者，他们曾不顾迫害挑战哈卡的祭司。金洛克邀请你延续这份传统，前往祖尔格鲁布对抗他的追随者，获取他所需的强力圣贤。")
zh(8055,"自由思想者的胸甲象征着以强力魔精为后盾的坚定意志。金洛克要求你证明价值，并与部族建立稳固联系后，才会交付这件装备，而强力圣贤正是他所寻求的。")
zh(8056,"赞达拉占卜者通过占卜指引而非诅咒来提供指导。梅维克以那传统中珍视的护腕为交换，换取你从祖尔格鲁布带回的强力圣贤，作为你对部族忠诚的证明。")
zh(8057,"占卜者通过与动物和灵体的关系寻求神谕。梅维克忆起他们在对抗古拉巴什战争中的价值，如今请求你从祖尔格鲁布带回强力圣贤，以证明你对赞达拉的价值。")
zh(8058,"赞达拉复仇者惩罚对部族的冒犯。金洛克邀请你执行这份复仇，前往祖尔格鲁布对付哈卡的追随者，带回强力圣贤作为你效忠的证明。")
zh(8059,"赞达拉恶魔信徒施行危险仪式：将恶魔囚禁于体内，借其力量。阿尔塔宾在提供关于这一部族传统的见解前，请求你从祖尔格鲁布带回强力圣贤。")
zh(8060,"赞达拉幻术师以魔精混淆敌人的视线。阿尔塔宾借那些法师所用的臂饰，向你展示他们的技艺，而他所寻求的，正是从祖尔格鲁布带回的强力圣贤。")
zh(8061,"赞达拉的忏悔者兼任审判者，既清剿部族深处的腐化，也抵挡哈卡这等外来的威胁。阿尔塔比姆请来古拉巴什的圣贤，要他们把守护部族、抵御邪恶的担子交到你肩上。")
zh(8062,"在古拉巴什帝国衰落后，赞达拉的猎手凭借狩猎技艺维系着部族的生存。法希尔提议在祖尔·格鲁布展开狩猎，以此衡量你的能力是否承袭那传统，并取回他所求的圣贤。")
zh(8063,"赞达拉的疯帽客以混乱与诡计扰乱敌人，这策略曾助部族存活。法希尔愿以他们珍视的盔甲第一片为代价，换取祖尔·格鲁布的魂能圣贤。")
zh(8064,"尽管赞达拉不遵循德鲁伊传统，他们的占卜者仍与自然与生灵保持紧密联系。梅维克请求以祖尔·格鲁布的魂能圣贤为证，展现你的决心，并赠予一条源自那传统的腰带。")
zh(8065,"占卜者的束腰象征与神圣智慧的连结，也忆起他们仪式中献祭的动物。梅维克愿以这件衣物表彰你的价值，条件是你献上祖尔·格鲁布的魂能圣贤。")
zh(8066,"法希尔认为真正的猎手必须精通潜行与突袭。他请你于祖尔·格鲁布展现这两种技艺，取回他追寻的圣贤之力，以一条赞达拉猎手的腰带为交换。")
zh(8067,"赞达拉猎手的披风象征他们的成就，以及隐藏或显露身形的能力。法希尔愿以这件衣物为代价，换取他所需的魂能圣贤。")
zh(8068,"赞达拉的幻术师揉弄魂能，以假象迎敌。阿尔塔比姆要你从祖尔格拉布带回圣贤，作为效力的凭证；他则赠你一件披风——此道中最好的好手曾披过它。")
zh(8069,"赞达拉的服饰彰显穿戴者的地位与权势。阿尔塔比姆提供一件幻术师传统的长袍，但要求你赢得部族的敬重，并从祖尔格鲁布取回他追寻的圣贤。")
zh(8070,"忏悔者曾护住赞达拉，不让腐化从部族深处蔓延。如今阿尔塔比姆要你前往祖尔格拉布，直面哈卡与古拉巴什的堕落，夺下他们手中的圣贤。")
zh(8071,"忏悔者的披风象征守护部族与审判威胁之人。阿尔塔比姆提供一件来自该传统的服饰，作为你对抗哈卡追随者并取回圣贤的报酬。")
zh(8072,"赞达拉的疯癫传说记载了一件织入疯狂与混乱的披风。法希尔提供这件来自该传统的披风，作为你从祖尔格鲁布取回圣贤的报酬。")
zh(8073,"对法希尔而言，赞达拉服饰的力量远超肉眼所见。他提供一件与混乱之力相关的疯癫斗篷，作为你从祖尔格鲁布取回圣贤的报酬。")
zh(8074,"占星者引导赞达拉前往南海避难，后又重返祖尔格鲁布的威胁之地。梅维克要求你献上圣贤证明价值，并提供一件占星者的腰带。")
zh(8075,"占星者的锁甲象征他们的权威与与灵体的联系。梅维克提供一件此类服饰，作为你献上来自祖尔格鲁布的圣贤以证明对部族忠诚的报酬。")
zh(8076,"恶魔使徒以生命为代价驾驭恶魔，这种牺牲被赞达拉接受以对抗如祖尔格鲁布般的威胁。阿尔塔比姆要你取回必要的圣贤，并提供一件他们的装备。")
zh(8077,"恶魔教派的长袍融合符文布与强力魂能，象征他们在赞达拉的地位。阿尔塔比姆需从祖尔格鲁布获取特定圣贤，方能赐予你一袭此类长袍。")
zh(8078,"金洛克归咎哈卡导致古拉巴什的覆灭，要求对其追随者展开报复。入侵祖尔格鲁布的行动旨在获取象征复仇的圣贤之力，以能量腰带作为认可。")
zh(8079,"复仇者的胸甲象征赞达拉的怒火，只赐予极受尊敬的盟友。金洛克要求你通过祖尔格鲁布的圣贤之力夺回被窃取的魂能，并直面哈卡的追随者。")
zh(8080,"士兵需要食物、武器与物资才能作战。阿拉希盆地蕴藏这些关键资源，玛克里尔中士请你夺取据点，并带回一箱补给至避难谷地。")
zh(8081,"阿拉索联军持续在阿拉希盆地搜寻资源。玛克里尔请你重返战场，再带回一箱补给，以支援前线将士。")
zh(8101,"阿尔塔比姆赐予一枚镶嵌卡亚罗之石的护身符，此山以狂暴的魔法爆发闻名。其力量与你与赞达拉的羁绊相连，用于对抗共同敌人。")
zh(8102,"阿尔塔比姆注意到卡亚罗之石的磨损，认可你对抗部落敌人的战功。他认为是时候强化这块石头，因此请求你交出护身符。")
zh(8103,"阿尔塔比姆报告哈卡莱如今畏惧你与卡亚罗展现的力量。为支持你持续的斗争，他再度强化石头，并请求你交出护身符。")
zh(8104,"阿尔塔比姆请你交出卡亚罗徽章，好让他向你展示与之相关的东西。这简短的邀约延续了此前对那颗宝石的研究。")
zh(8105,"阿拉希盆地的据点为士兵们提供所需物资。奥斯莱特元帅请你攻占农场、矿场、伐木场与铁匠铺，敌军仍占据这些地方，争夺关键补给。")
zh(8106,"阿尔塔比姆展示一枚徽章，唤起赞达拉昔日驻守科赞的记忆，那时地精贸易王子将他们驱逐。此岛对部族而言仍属圣地，而宝石则支撑着对抗共同敌人的斗争。")
zh(8107,"阿尔塔比姆认为，荣誉可赢得友谊与盟约的回馈。为表彰这段关系，他请求你交出科赞徽章，好让他增强它的力量。")
zh(8108,"阿尔塔比姆愿再度强化科赞徽章，并请你继续对抗哈卡及其追随者。这增幅是赞达拉对这场斗争的支持之一。")
zh(8109,"阿尔塔比姆认为该将最终增幅施加于科赞徽章。他请你交出徽章，并鼓励你与恶魔联手，将它的能量用于对抗部族的敌人。")
zh(8110,"梅维克将南海海藻以魔法与奇术转化，制成一枚徽章。此徽章已准备就绪，可赋予佩戴者相应属性，将赞达拉故乡的材质与你对自然的亲和力连接起来。")
zh(8111,"部族里正议论你与哈卡莱的交手。莫托尔已准了对海藻护符的增补。梅维克要你把护符交来，添些魂能——算是记下这份功劳。")
zh(8112,"梅维克认为这枚符咒的叶片需要更多魔法与灵巧来焕发生机，他请求你交出这枚被施了法的海藻以完成这项工作。")
zh(8113,"拉斯塔哈亲自下令，为海藻符咒做最后一重强化。梅维克为这份看重而欢喜，请你为它添上国王钦准的最后一道魔法与巫力。")
zh(8114,"你在阿拉希盆地的贡献赢得了奥斯莱特的信任，他委以更艰巨的任务。同时掌控四个据点，旨在确保关键资源并展现联盟对部落的压倒性力量。")
zh(8115,"阿拉索联军希望发起决定性攻势，驱逐污染者的占领。奥斯莱特要求你同时掌控五个阿拉希盆地据点，将敌人逐出战场上的每个战略要地。")
zh(8116,"梅维克认可你与萨满教的深厚联系，赠予你一枚可佩戴的水晶球。球中封存着巫毒幻象，那是南海村落的影像，作为鼓舞人心的提醒。")
zh(8117,"梅维克认可你以灵体与元素对抗祖尔格鲁布敌人之举。为表彰此功，他愿点亮巫毒幻象，并请求你交出能量宝珠。")
zh(8118,"莫托尔称赞你的贡献，视你为赞达拉的新兴英雄。他亦要求梅维克进一步改良巫毒幻象水晶球，使其中的影像更加清晰明亮。")
zh(8119,"巫毒幻象水晶球已似活物，灵体环绕其周。梅维克指出这变化，并请求符咒做出最后一次调整。")
zh(8120,"阿拉索联军正派兵夺取盆地的粮食与资源。杜维尔希望你趁联盟占据据点时，袭击矿场、伐木场、铁匠铺与兽栏，阻挠他们的推进。")
zh(8121,"你在阿拉希盆地的行动赢得了污染者的敬意。杜维尔提议同时占领四个据点，向阿拉索联军展示他们对这片土地的控制有多脆弱。")
zh(8122,"情报显示阿拉索联军的意志正在动摇。杜维尔想趁此机会发动攻势，同时夺下盆地内所有五座据点，彻底击溃敌人。")
zh(8123,"联盟计划从避难谷地扩张，利用阿拉希的资源。莫提斯想阻止他们的步伐，夺取补给，为此需要你掌控盆地据点后获得的资源箱。")
zh(8124,"污染者已扰乱敌方补给，但联盟仍持续争夺阿拉希盆地。莫提斯请求你再度突袭，获取更多资源箱，持续施压敌方后勤线。")
zh(8141,"法希尔引荐了死亡之手——为赞达拉效力的刺客传统。随着哈卡莱势力壮大，他赠予你一枚暗影符文，助你在对抗哈卡的斗争中更进一步。")
zh(8142,"法希尔察觉到哈卡莱的邪祟缠绕着你，承认你与他们的斗争。他请求你交出暗影符文，以增强其力量，继续为赞达拉效力。")
zh(8143,"你为赞达拉的奉献连莫托尔都注意到了。法希尔认为你的能力值得更高层次的认可，请求你交出暗影符文，让他再度强化它的力量。")
zh(8144,"盲眼法希尔解释，这枚黑影符咒因你在祖尔格拉布的战斗而积聚了力量。他认为它已准备好最终的强化，请求你交出它。")
zh(8145,"赞达拉的猎人们在大漩涡附近采集海藻，以此证明他们的决心。法希尔赠予一枚由这种材料编织并施有咒语的符咒，能提升精准与力量，而进一步的编织则与你与部族的羁绊有关。")
zh(8146,"法希尔已知晓你压在哈卡大军身上的份量。念及这份战功，他认定你配得上再为大漩涡符咒添一道编织，请你前去完成强化。")
zh(8147,"赞达拉知晓你对他们的敌人所作之事，并感激你的支持。法希尔请求你交出大漩涡符咒，好为你的贡献再添一道编织。")
zh(8148,"莫托尔带来消息，拉斯塔哈及其朝廷认可你对抗哈卡莱的斗争。法希尔奉命将最终的编织施加于大漩涡符咒，请求你交出它。")
zh(8149,"收获节追念艾泽拉斯诸英雄的牺牲。庆典未散，瓦格纳请你去西瘟疫之地，在乌瑟尔的雕像前献上一份祭品。")
zh(8150,"收获节颂扬英雄的牺牲，部落尤其不忘格罗姆·地狱咆哮。庆典尚在进行，亚尼请你把祭品送到灰谷的纪念碑前。")
zh(8151,"奥汀克离开部族，协助塞纳里奥议会，现正寻找有经验的猎人，将他的技艺传授给他们。他在艾萨拉的教导旨在加深他们对猎人技艺的理解，并促进平衡。")
zh(8153,"奥汀克认为完好无损的鹿角是动物灵体格外自信的象征。为了诠释这种自信，他向苔蹄快步者索取完美无瑕的鹿角——这些生物在防御时往往会让角尖受损。")
zh(8154,"士兵需要食物、武器和物资才能作战。阿拉希盆地蕴藏着这些关键资源，玛克里尔中士希望你占领其据点，并带回一箱补给送回避难谷地。")
zh(8155,"士兵需要食物和装备才能作战。阿拉希拥有矿场、农田和车间，足以供应军需；掌控其据点，便能确保阿拉索联军战争所需的资源。")
zh(8156,"军队需要装备和补给，而不仅仅是愿意战斗的士兵。阿拉希的据点藏有这些物资；掌控它们，便能维持战事所需，避免部队因缺粮少械而战力受损。")
zh(8157,"阿拉索联军持续执行一项获取阿拉希盆地资源的任务。玛克里尔希望你重返战场，带回另一箱补给，以支援前线部队。")
zh(8158,"阿拉索联军持续执行一项获取阿拉希资源的任务。返回盆地再取一箱物资，让前线部队在战火中维持战力。")
zh(8159,"阿拉索联军持续请求从盆地获取更多资源。重返该地并带回更多补给，以维持仍投入战事的部队的物资需求。")
zh(8160,"联盟计划从避难谷地出发，借助阿拉希的资源扩张势力。莫提斯希望阻碍这种扩张，他要求你夺取盆地据点的补给箱，以截断敌方资源。")
zh(8161,"联盟正派遣部队夺回阿拉希盆地，而部落选择以控制矿场、农田与车间来阻断其攻势。")
zh(8162,"阿拉索联军正集结兵马，要夺回这片故土。部落要挡下这路攻势：只要拿下盆地各处的据点，便能从矿场、农田与车间里截走补给。")
zh(8163,"污染者已扰乱敌方补给，但联盟仍持续争夺阿拉希盆地。莫提斯请求进一步深入，获取更多资源箱，持续施压敌方补给线。")
zh(8164,"尽管补给线受损，联盟仍据守阿拉希。污染者需要更多远征获取资源，持续对不愿放弃此地的对手施加压力。")
zh(8165,"对补给线的袭击未能让联盟退缩。污染者必须持续派兵深入阿拉希，带回更多资源，以维持对敌方的压力。")
zh(8166,"阿拉希的基地提供着部队所需物资。奥斯莱特元帅要你突袭农田、矿场、伐木场与铁匠铺，即便敌方仍控制着它们，争夺这些关键补给。")
zh(8167,"掌控阿拉希意味着哪一方能获得原材料。你需攻占基地外的据点，摧毁敌方旗帜，争夺维持其军队运作的生产中心。")
zh(8168,"阿拉希的战局，全系于那些能出产补给的领地。你的任务落在离本阵最远的几处据点：扯下敌方的旗帜，那些要地的归属便会动摇。")
zh(8169,"阿拉索联军正派兵夺取盆地的粮食与资源。屠杀者杜维尔希望你趁联盟控制这些据点时，袭击矿场、伐木场、铁匠铺与兽栏。")
zh(8170,"阿拉索联军为联盟寻求资源与领土，但部落拒绝其回归。攻击据点并拔除旗帜，便可夺取该地并阻断那些部队的补给。")
zh(8171,"部落意图阻止阿拉索联军获取盆地的粮食与物资。攻击其据点并拔除敌方旗帜，便可占领该地，遏制联盟的推进。")
zh(8181,"对摩沙拉石板的研究显示，那颗蛋并不如耶赫金娅所言蕴含哈卡。它反而可能助其复活，这骗局使得与巨魔对峙并夺回蛋成为当务之急。")
zh(8182,"哈卡若重掌权，其统治之势恐将蔓延至远古巨魔世界之外。尤亚姆巴岛上的赞达拉部队或可协助对抗他；其首领莫托尔，正是寻求回应的关键人物。")
zh(8183,"尽管哈卡已被击败，他残存的力量仍使心脏燃烧不止。那颗被诅咒的器官仍是隐患，必须送往尤亚姆巴岛的莫托尔处。")
zh(8184,"赞扎精通远古巨魔附魔之术，却仍需材料方可施展。准备过程需从金多或血领主处取得哈卡莱神像，以及从厄运巫毒堆中寻得的巫毒娃娃。")
zh(8185,"赞扎精通远古巨魔附魔之术，却仍需材料方可施展。准备过程需从金多或血领主处取得哈卡莱神像，以及从厄运巫毒堆中寻得的巫毒娃娃。")
zh(8186,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8187,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8188,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8189,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8190,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8191,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8192,"赞扎通晓巨魔的远古附魔，却缺了施术所需的材料。备料须得两样：金多或血领主手中的哈卡莱神像，还有厄运巫毒堆里翻出的巫毒娃娃。")
zh(8193,"周日钓鱼竞赛以迅速送达新鲜渔获表彰技艺高超的钓手。荆棘谷沿岸的鱼群鲜美，但鱼肉极易腐坏，故拖延至下周再送，恐难参与竞争。")
zh(8194,"虽然钓鱼比赛已有胜者，贾恩仍愿以美味鱼肉换得佳肴。这场交易为赛事剩余的渔获提供买家，待头名争夺结束便能派上用场。")
zh(8195,"祖尔格鲁布的部落硬币蕴含魔力，位列能量圣贤之列。温卡萨接受备用硬币组换赞达拉荣誉勋章，而林·沃肖则用勋章换取特殊物品。")
zh(8196,"南海的美味芒果以清凉身心闻名。岛上储备让少量芒果可换得赞达拉荣誉勋章。")
zh(8201,"被奴役的高阶牧师正把巨魔诸神的能量灌入哈卡体内。伊克萨尔要截断这股力量的源头，交给你一条神圣之索——取回那些牧师的头颅，便是事成的凭据。")
zh(8221,"蓝腮鱼王正收集稀有鱼类以作记录。他请求提供基佛天使鱼作为贡献，并承诺奖励能寻得该标本之人。")
zh(8222,"亚布发现发光物件吸引马戏团访客。为打造这些饰品，他需从希利苏斯、诅咒之地或燃烧平原获取发光蝎血。")
zh(8223,"蝎血已让普通物件化为访客喜爱的饰品。尽管亚布所需材料减少，仍以门票换取更多发光血液的供应。")
zh(8224,"蓝腮鱼王正收集稀有鱼类以作记录。他请求提供迪森皇后鱼作为贡献，并承诺奖励能寻得该标本之人。")
zh(8225,"鱼王蓝腮正在收集稀有鱼类以作记录。他要求提供一条布隆奈尔蓝鳞蛇作为贡献，并承诺给予能获取该标本之人奖励。")
zh(8227,"一条丝质卷尺散落在破碎的渔具之中，上面刻着纳特·帕格的名字。尘泥沼泽的地址指明了该工具应归还之人。")
zh(8228,"格林克在藏宝海湾张贴告示，宣布周日的钓鱼比赛。一张传单揭示了比赛规则，让你在参与前知悉条件。")
zh(8229,"巴鲁斯在藏宝海湾张贴告示，宣布周日的钓鱼比赛。一张传单揭示了比赛规则，让你在参与前知悉条件。")
zh(8231,"奥汀克以碎浪多头怪坚韧反光的鳞片象征猎人的力量。他的课程要求你追踪这些两栖生物沿艾萨拉海岸，并获取它们的鳞片。")
zh(8232,"奥汀克的下堂课讲的是同伴协作的力量。在阿塔拉哈克神殿的摩弗拉斯太过危险，无法独自面对；他的牙齿象征着通过合作寻求的教训。")
zh(8233,"拉文霍德的约拉奇·拉文霍德召你前來，事关一项他信使无法解释的秘密。传唤指引你前往拉文霍德庄园，位于敦霍尔德城堡西北的山径尽头。")
zh(8234,"拉文霍德失窃的蓝布袋落入了木喉萨满祭司之手，盗贼未能打开它，他们便将其当作圣物买下。它必须在艾萨拉找回，并交予克希雷姆，而袋中之物仍需保密。")
zh(8235,"克希雷姆需要解除袋子上的附魔，但他的解咒书籍被盗并焚毁。那些密文碎片仍可拼凑还原，而艾萨拉的森林软泥怪或许已收集了部分残余。")
zh(8236,"克希雷姆正在处理附魔，袋子的钥匙仍下落不明。据说摩弗拉斯将它藏在阿塔拉·哈卡的神殿中，需同伴取回并送往拉文霍德。")
zh(8238,"用于祖尔格鲁布的部落硬币蕴含魂能，位列魂能圣贤之列。温卡萨接受备用硬币组换取荣誉信物，而林沃肖则用这些信物换取特殊的赞达拉物品。")
zh(8239,"祖尔格鲁布所用的部落硬币蕴含魂能，位列虚空之光圣贤之列。温卡萨接受备用硬币组换取荣誉徽章，而林·沃肖则以之换得赞达拉特制物品。")
zh(8240,"摧毁哈卡莱魂瓶对赞达拉而言意义重大，他们甚至欢迎外来盟友参与。温卡萨提议带一枚前往赞扎的祭坛，见证他的祝福，为此还额外提供一枚信物作为首次演示。")
zh(8241,"迪菲亚兄弟会的炽热助熔剂日渐枯竭。这项补给协议结合熏火龙鳞片、铁锭与煤炭，既可补充物资，也能继续赢得组织的信任。")
zh(8242,"迪菲亚兄弟会的炽热助熔剂日渐枯竭。这项补给协议结合熏火龙鳞片、重皮与煤炭，既可补充物资，也能继续赢得组织的信任。")
zh(8243,"你在赞达拉的声望可换取由赞扎祝福的烈酒。这项优惠允许你选择一种换取荣誉信物，但这些酒酿的效果不可叠加。")
zh(8246,"南海的徽记可强化肩甲，只赐予受赞达拉族敬重之人。此交易可换取附魔，代价是十五枚荣誉徽章。")
zh(8249,"潜行学徒需要更难的锁具磨练技艺。重垃圾箱正合用途，只要箱内仍有硬币，学生便有理由开启它们。")
zh(8250,"克希雷姆寻觅有你经验之人，他在艾萨拉的塔楼接待访客。抵达此处须先寻得萨纳斯，从法师仆从处取得魔法通行。")
zh(8251,"艾萨拉的血精灵产出的尘埃异于寻常解谜材料。学徒被杀后，克希雷姆下令强取此物，并严惩责任人。")
zh(8252,"恶鞭海妖已搜集了克希雷姆所需的大半魔化珊瑚。随着海湾所剩无几，他命你从守护者手中取回这材料。")
zh(8253,"摩弗拉斯吞食了携带稀有奥术碎片的学徒。大法师欲从暗影哈卡神殿的龙口中夺回碎片，请求强力盟友共赴险境。")
zh(8254,"塞纳里奥议会亟需援助，你被要求履行职责，助人于危难。奥汀克在艾萨拉悬崖，是了解需求的联络人。")
zh(8255,"苔蹄快步者曾抵抗费伍德的腐蚀，后离开此地。奥汀克需它们健康的腺体，作为复原药膏的首味药材，以助此地疗伤。")
zh(8256,"药膏需毒药与治愈之物调和。奥汀克已获其中一味，如今亟需亡灵腐液——这种浓稠物质藏于艾达尔遗迹中徘徊的上层精灵之间。")
zh(8257,"摩弗拉斯的血液是药膏最后的治愈之物，因其对毒与疾病有天然抗性。奥汀克请你集结盟友，在神殿中获取此物，并送至费伍德的格雷塔手中。")
zh(8258,"死亡骑士达克雷尔意图操控灵界，其据点在通灵学院。已备好的预言水晶球可召唤其爪牙，直面强敌，阻止他造成的灾厄。")
zh(8259,"你在通灵学院对达克雷尔的奋战值得额外嘉奖。此头盔是对此服务的酬谢，认可此前所获奖励尚显不足。")
zh(8260,"阿拉索联军以补给品表彰你的协助。包裹中的干粮与绷带，将送往阿拉希盆地，支援那里的资源争夺战。")
zh(8261,"你在阿拉希盆地的贡献赢得盟友认可。为支持后续行动，他们提供专属战场的补给包，内含干粮与绷带。")
zh(8262,"你在阿拉希盆地的贡献赢得盟友认可。为支持后续行动，他们提供专属战场的补给包，内含干粮与绷带。")
zh(8263,"污染者以干粮与绷带表彰你的贡献。这些物资将用于阿拉希，为继续争夺盆地资源的战士们提供物质支援。")
zh(8264,"你在阿拉希盆地的付出赢得了盟友的赞誉。为继续支援那里的行动，他们送来了包含补给与绷带的物资包，专供那片战场使用。")
zh(8265,"你在阿拉希盆地的付出赢得了盟友的赞誉。为继续支援那里的行动，他们送来了包含补给与绷带的物资包，专供那片战场使用。")
zh(8266,"即便战歌峡谷的奋战未获胜利，你的努力仍被铭记。牺牲之书表彰你的参与，肯定你为这场斗争所付出的一切。")
zh(8267,"战歌峡谷的牺牲之书仍在继续接受提交。这份认可持续表彰那些参与冲突的战士，即使他们未能赢得胜利。")
zh(8268,"即便战歌峡谷的奋战未获胜利，你的努力仍被铭记。牺牲之书表彰你的参与，肯定你为这场斗争所付出的一切。")
zh(8269,"战歌峡谷的牺牲之书仍在继续接受提交。这份认可持续表彰那些参与冲突的战士，即使他们未能赢得胜利。")
zh(8271,"你在奥特兰克山的效忠赢得了霜狼的敬重。矿工为你寻回的宝物提供了选择，以表对这份贡献的感激。")
zh(8272,"沃加·死爪认可你的胜利与对霜狼的效忠。他的馈赠奖励了这份英雄壮举，并表达对你突破敌阵的感激。")
zh(8273,"奥兰对在望海崖附近荒岛上发现的石板颇感兴趣。这份谢意认可了寻回此物的努力，并感谢将其带回。")
zh(8275,"异种蝎们已做好扩张的准备，而威胁却未被遏制。塞纳里奥议会正在希利苏斯集结力量，号召冒险者协助保卫艾泽拉斯，相关指引可在塞纳里奥要塞找到。")
zh(8276,"蜂巢附近的震动预示着大规模异种蝎的行动，可能引发扩张。塞纳里奥议会召唤部落勇士前往希利苏斯应对这场威胁，阻止其进一步蔓延。")
zh(8277,"诺格采集草药归来，却发现毒药比预期更难制服。为配制解药，她需要北方沙漠蝎子与蜘蛛的样本，这些生物或许曾对他发动过攻击。")
zh(8278,"第一剂解药失败，比提克斯怀疑诺格遭更强的生物所伤，地点更偏南。她需收集多种毒液样本，以应对这种可能性。")
zh(8279,"奥泰尔需要暮光之锤书吏使用的词典，以解读石板。这三卷内容由不同守卫者分别保管，这是个防范措施，意味着必须在邪教营地中寻找。")
zh(8280,"塞纳里奥要塞依赖于保持补给路线畅通。沙漠蠕虫已摧毁一队货物，梅恩·长角请求你削弱掘泥打击者，以保护商队。")
zh(8281,"削弱掘泥打击者未必能确保商队安全。梅恩·长角担忧它们南方更大的同类会趁虚而入，请求你先将掘泥摧毁者驱离，以免威胁路线。")
zh(8282,"诺格在逃亡途中丢失了药剂袋，至今仍虚弱无法取回。少了这些稀有材料，他和比提克斯无法为塞纳里奥要塞制作所需药剂。")
zh(8283,"据信死亡弯钩已退入南面的山中，巡逻队与远征队屡受其扰。塞纳里奥要塞悬赏除此祸患，凭一只钳子来领赏。")
zh(8284,"一座昔日的暮光营地已成废墟，被元素生物占据。在那里找到的石板碎片或许能解释该教派为何现身希利苏斯，但还需更多拼图才能还原有用信息。")
zh(8285,"传言奥泰尔已脱离暮光之锤，如今隐居于南风村南方。他对教派的了解，或许能帮助解读修复后的石板。")
zh(8286,"凝视者记得自己曾被人从死里救回，此后便与这份职守绑在一处。第二场战争逼近，他要先得到一个准信——阿纳克洛斯是否已回到时光之穴，才肯迈出下一步。")
zh(8287,"解读后的石板包含可能对抗暮光之锤的信息。奥泰尔请你将羊皮纸送交玛拉利斯指挥官，以支持塞纳里奥议会对抗仍追踪他的教派。")
zh(8288,"巴里斯托尔斯寻求能承担与诺兹多姆子嗣结盟重任之人。第一场试炼要求集结力量对抗勒什雷尔，他守卫着奈法利安的内殿之路。")
zh(8289,"你在战歌峡谷的表现证明了你对银翼的价值。他们的代表请求你再取几枚功勋符文，以表彰你的持续服务，并加深对你的信任。")
zh(8290,"部落的伐木行动威胁着一片圣林，也迫使银翼哨兵奋起抵抗。参与这场冲突并获得徽记，便是对抵抗入侵者最直接的支持。")
zh(8291,"部落的伐木行动正为战争机器提供燃料，而圣林正面临危机。哨兵们希望你在战歌峡谷守护银翼要塞，将入侵者击退。")
zh(8292,"你在战歌峡谷的贡献已获认可。银翼功勋奖章表彰了你的付出，而进一步的支援将加深阵营对你的信任。")
zh(8293,"你在战歌峡谷的付出已证明价值。对抗银翼哨兵的斗争仍在继续，荣誉印记则进一步肯定你对战歌事业的贡献。")
zh(8294,"部落视银翼哨兵为阻碍其在灰谷采伐的障碍。碎颅中士希望你在战歌峡谷与他们交战，打破抵抗，以印记证明你的参与。")
zh(8295,"部落将银翼视为阻碍其在灰谷采伐的障碍。与他们交战并交出印记，便是参与争夺森林与资源控制权的证明。")
zh(8296,"战歌势力已认可你在峡谷的贡献。他们仍在与银翼哨兵对抗，而进一步的荣誉印记则将成为你付出的明证。")
zh(8297,"士兵们需要食物、武器与物资才能战斗。阿拉希盆地蕴藏着这些关键资源，玛克里尔中士希望你守住据点，并带回一箱补给至避难谷地。")
zh(8298,"阿拉索联军持续执行一项任务，意图从阿拉希盆地获取更多资源。玛克里尔中士希望你重返战场，带回一箱补给，以支援其军队。")
zh(8299,"联盟计划从避难谷地向外扩张，利用阿拉希的资源。莫提斯希望阻止这种扩张，便要求你夺取控制盆地据点所得的资源箱。")
zh(8300,"污染者已扰乱敌方补给，但联盟仍持续争夺阿拉希盆地。莫提斯要求进一步突袭，获取更多资源箱，以持续施压敌方补给线。")
zh(8301,"诺兹多姆的子嗣对其他种族心存疑虑，要求以行动证明盟友身份。巴里斯托尔斯希望你深入三处异种蝎巢穴，收集甲壳碎片，以示对抗此威胁的决心。")
zh(8302,"巴里斯托尔斯需要更多甲壳碎片，以继续对抗异种蝎的行动。每完成一次交付，便可任命一名副官，因此他希望你谨慎选择，谁来分担这项任务。")
zh(8303,"敌人的存在迫使巴里斯托尔斯隐瞒了许多秘密，但他如今认为是时候分享这些知识了。他提供一本典籍，助你准备前往时光之穴，寻找阿纳克洛斯。")
zh(8304,"娜塔莉亚在数周异样行为后神秘失踪，坚持继续她的研究。马拉利思缺乏士兵搜寻她，因此希望你前往铜须营地，那是她最后已知的去向。")
zh(8305,"在希利苏斯屏障附近，一颗水晶之泪铭记着流沙之战的惨烈牺牲。凝视其深处，便能窥见那段过往，理解其深远意义。")
zh(8306,"线索把娜塔莉亚的踪迹引向雷加尔虫巢，也引向一个不妙的猜想：她怕是已经失了心智。玛拉利思请你带上同伴前去查探，并劝你先去请教矮人——虫巢里的门道，他们懂得最多。")
zh(8307,"荒漠有限的粮食让塞纳里奥要塞的生存艰难。暮光教徒吞食苦涩的沙虫，他们的烹饪方式或许能拓展定居点的饮食范围。")
zh(8308,"布莱恩的信件提及远征中伤亡惨重，并发现一条通往安其拉的隧道，与他的研究相关。他希望消息能传回旧营地，他的猴子也需妥善照料。")
zh(8309,"自初始远征与娜塔莉亚的疯狂以来，异种蝎活动频繁。鲁特加尔怀疑这与刻印水晶有关，需要三座虫巢的符文拓印以验证推测。")
zh(8310,"弗兰卡认为一种药剂或许能解读异种蝎与其拉的语句与符文。他需要各虫巢生物的脑浆推进研究，并延续鲁特加尔的工作。")
zh(8311,"耶斯帕尔病重，无法亲自去万圣节讨糖。他托你代为收集各城邦与塔瓦斯德的糖果，承诺以自己的特制甜点相赠。")
zh(8312,"斯波普斯病倒，无法参加万圣节的讨糖活动。请求你代为收集各大城邦与卡利·雷米克的糖果，以换取他已备好的特制甜点。")
zh(8313,"沙虫食谱虽可辨识，却提及陌生的香料与草药。卡兰德拉斯对沙漠植物的了解，或许能助人解读食谱，并应用于塞纳里奥要塞。")
zh(8314,"拓印让那些符文得以重现，它们看来正是用来向异种蝎传讯的。水晶里的东西仍旧读不出来，鲁特加尔·雕石请你把棱镜送到拉克斯班手上，求她相助。")
zh(8315,"符文中描绘了一场与其拉使者在巨龙骸骨旁的会面。拉克斯班认为复制这段讯息或许能引出他，进而获取开启水晶所需的装置。")
zh(8316,"拉克斯班肯定了你在调查中的贡献，却对预言的预兆感到忧虑。她提供武器装备，以应对即将来临的战争。")
zh(8317,"重获的食谱让卡兰德拉斯得以准备一日三餐。现在需要协助制作一批沙漠肉丸子，将这新添的厨房技艺付诸实践。")
zh(8318,"暮光之锤使用加密文字在各据点间传递讯息。波尔无需解读便知其重要：若能从流通中移除，或可削弱其在希利苏斯的协调能力。")
zh(8319,"波尔持续要求加密文字，以维持对暮光之锤的压力。后续的送达将持续削弱其通讯网络，支援对抗教派的行动。")
zh(8320,"希利苏斯的暮光仪式仍是个谜，但其威胁不容忽视。霍姆认定地主是西部据点的领袖，嘱咐你攻击其指挥体系。")
zh(8321,"另一处暮光之锤据点被发现于希利苏斯东北部的洞穴中。霍姆请你前去对抗当地首领邪恶的维拉尔，并取回他的戒指作为证据。")
zh(8322,"寒暮节为破坏南海镇珍藏的麦酒提供了机会。计划是往酒馆主酿造桶里放入烂鸡蛋，借节庆的混乱达成目标。")
zh(8323,"奥泰尔可用这本词典破译邪教的秘密通告，弄清自己是否仍在被追捕。他要求用加密文本交换，以换取其他有用情报。")
zh(8324,"奥泰尔持续破译暮光文献，因工作耗时需分批接收情报。交易仍维持以邪教文件换他能提取的信息。")
zh(8331,"突袭行动显示深渊议会透过风石操控暮光锤。奥蕾尔·金叶拥有制作下一轮行动所需道具的技艺。")
zh(8332,"引诱深渊公爵穿越风石需伪装成暮光领袖。若提供材料复刻身份徽记，奥蕾尔可打造所需徽章。")
zh(8333,"奥蕾尔还在打造身份徽章，好让更多人扮作暮光教徒潜入敌营。每换一枚，都得再交一批明亮碎片与深渊纹章，供她继续开工。")
zh(8341,"深渊领主仅接见最高阶领袖，通过强力风石传递讯息。奥蕾尔提议升级伪装，需材料复刻那受限制的徽记。")
zh(8342,"另一次针对深渊高层议会的行动需更换伪装的领主徽章。奥蕾尔愿打造新徽章，若你提供更多碎片与印信。")
zh(8343,"奥蕾尔相信她已找到方法，可召唤并对抗深渊魔议会的执政成员。塞纳里奥议会赋予你的地位，使你成为了解这项危险计划的首选之人。")
zh(8348,"召唤深渊魔公爵的能力，为直接打击议会提供了机会。波尔希望击败一位公爵，以震慑其下属，并要求其徽章作为交锋的证据。")
zh(8349,"徽章如今已为召唤深渊魔公爵做好准备。下一步是向波尔请教，他正筹划针对议会的行动，并能说明如何利用这个机会。")
zh(8351,"你如今顶着暮光执政者的名头，正好为一场更凶险的行动铺路。奥蕾尔让你去找波尔谈谈——他想借这重身份，对深渊议会动手。")
zh(8352,"波尔提议正面迎战一位深渊魔领主，并警告你需做好充分准备。他要求一根权杖作为证据，并承诺对敢于面对这场危险的人给予特别表彰。")
zh(8353,"为生病的孩子收集糖果，仍需遵循表演恶作剧的传统。铁炉堡的客栈老板要求你模仿一只鸡，才能换取一块薄荷糖。")
zh(8354,"为生病的孩子收集糖果，仍需遵循表演恶作剧的传统。幽暗城的客栈老板要求你模仿一只鸡，才能换取一块薄荷糖。")
zh(8355,"塔瓦斯德欣赏你为生病的孩子收集糖果，但仍坚持要求完成恶作剧的传统。他以诺莫瑞根橡皮糖交换你对火车的模仿。")
zh(8356,"艾莉森遵循传统，即便为病童送糖果，也先要求一个把戏。她提供的暴风城杏仁糖，需以肌肉展示为交换。")
zh(8357,"为病童收集糖果，也牵涉达纳苏斯的节日传统。塞琳尼以杏仁蜜为赏，换你跳支小舞，延续这古老习俗。")
zh(8358,"卡利·雷米克欣赏你为病童收集糖果的举动，却坚持要求一个把戏。她提供的暗矛橡皮糖，需以模仿火车为交换。")
zh(8359,"格雷什卡遵循传统，即便为病童送糖果，也先要求一个把戏。她提供的奥格瑞玛软糖，需以肌肉展示为交换。")
zh(8360,"为病童收集糖果，也带你来到雷霆崖。帕拉以杏仁蜜为赏，换你跳支小舞，延续这古老传统。")
zh(8361,"暮光之锤召唤的元素生物，已向邪教下达指令。波尔欲扰乱其指挥链，命你联络并击败深渊魔骑士，再带回交锋的证据。")
zh(8362,"波尔认可你对抗深渊魔骑士的能力，命你持续施压邪教。更多战斗延续对首领的围攻，徽记成为他认可的凭证。")
zh(8363,"你已证明能对抗深渊公爵。波尔继续以新徽记为赏，激励你持续打击邪教首领。")
zh(8364,"对抗暮光教派及其统治者，这场战斗远超博尔的预料。为支持后续交锋，他持续悬赏深渊节杖，以表彰那些努力。")
zh(8365,"傲慢的店主为艾泽拉斯的权贵们提供时尚服饰。她最新请求来自落帆海湾的海盗，要为生意备足帽子存货。")
zh(8366,"南海海盗们无视卡特尔的保护费。比格维兹必须留在港口维持秩序，还需委派他人率队前往落帆海湾执行惩戒行动。")
zh(8367,"部落希望展开一场协调一致的战争，而非零散冲突。这项任务表彰你在阿拉希、奥特兰克与战歌峡谷三线的贡献，展现你的实战经验。")
zh(8368,"阿拉希的战斗已演变为资源争夺的全面战争。污染者需要这条补给线维持部落运转，防止联盟将其用于对抗。")
zh(8369,"部落视雷矛远征为对霜狼领地的入侵。其号召你挺身奥特兰克，驱逐入侵者，并以荣誉印记表彰你在那场防御战中的贡献。")
zh(8370,"阿拉希的战火已演变为资源争夺的全面战争。污染者需维持这条补给线以维系部落，防止联盟将其用于对抗。")
zh(8371,"联盟视各条战线为相互关联的整体：一处得失，牵动全局。它寻求具备这种认知的老兵，要求你在所有活跃战场对抗部落。")
zh(8372,"灰谷的森林既是天然屏障，也承载着生态价值。联盟号召抵抗伐木，以守护阿斯特兰纳，荣誉印记则见证着战士们的参与。")
zh(8373,"亡灵臭气弹在寒霜节期间污染了南海镇。哈特曼中士提供松木基清洁剂去除气味，并请求协助维持村庄的清新。")
zh(8374,"制造武器的能力，往往能决定一场战争的走向，如同战场上的技艺。联盟需要阿拉希的资源补给军队，防止敌手借此武装。")
zh(8375,"联盟铭记着风暴矛远征军抵达奥特兰克后，那些被杀害的矮人。如今的号召，是为缅怀逝者，以荣誉印记延续他们的牺牲。")
zh(8376,"拉克斯班认可你在调查中的贡献，却忧虑预言所预示的未来。她提供军备，以支持你面对战争威胁的沙漠远征。")
zh(8377,"拉克斯班认可你在调查中的贡献，却忧虑预言所预示的未来。她提供军备，以支持你面对战争威胁的沙漠远征。")
zh(8378,"拉克斯班认可你在调查中的贡献，却忧虑预言所预示的未来。她提供军备，以支持你面对战争威胁的沙漠远征。")
zh(8379,"拉克斯班认可你在调查中的贡献，却忧虑预言所预示的未来。她提供军备，以支持你面对战争威胁的沙漠远征。")
zh(8380,"拉克斯班认可你在调查中的贡献，却对预言的警示忧心忡忡。她提供武器装备，助你在这场迫在眉睫的战争中展开沙漠远征。")
zh(8381,"拉克斯班认可你在调查中的贡献，却对预言的警示忧心忡忡。她提供武器装备，助你在这场迫在眉睫的战争中展开沙漠远征。")
zh(8382,"拉克斯班认可你在调查中的贡献，却对预言的警示忧心忡忡。她提供武器装备，助你在这场迫在眉睫的战争中展开沙漠远征。")
zh(8383,"奥特兰克山谷的战火未息，联盟再度召唤你重返战场。这份邀约提醒着，唯有持续投入，方能守住这关键战线。")
zh(8384,"战争正迅速吞噬联盟的补给，守住阿拉希至关重要，以重振资源流动。荣誉印记见证你对守护这条生命线的贡献。")
zh(8385,"联盟期盼你继续在各战线贡献经验。老兵以身作则，这份认可延续着对持续参战者的嘉勉。")
zh(8386,"灰谷的森林既是天然屏障，亦具生态价值。联盟呼吁抵抗伐木，守护阿斯特兰纳，荣誉印记记录你参与战斗的付出。")
zh(8387,"奥特兰克的冲突仍未终结，部落邀你重返山谷。目的依旧——驱逐他们视作入侵者之敌，守护霜狼领地。")
zh(8388,"你的战斗为部落其他战士树立了榜样，这份赏金表彰你持续对抗联盟的贡献，并请求你汇报前线的参与情况。")
zh(8389,"银翼的战火仍未熄灭，部落号召持续投入。荣誉印记记录你的功绩，而代表则要求将敌人彻底驱逐出这片土地。")
zh(8390,"部落担忧在对抗联盟的战争中物资将告罄，代表们呼吁继续争夺阿拉希盆地，以确保资源持续供应部队。")
zh(8391,"对抗部落的战争正消耗联盟的储备，守住阿拉希至关重要，代表们需要你证明你在守护补给线上的协助。")
zh(8392,"对抗部落的战争正迅速消耗联盟的资源，维持对阿拉希盆地的控制是关键，因此前线持续支持尤为迫切。")
zh(8393,"武器生产与战术技能同样决定战局，联盟需要阿拉希的资源装备部队，同时防止这些材料被敌方转化为武器。")
zh(8394,"阿拉希的资源可支援任一军队，联盟请求你守住盆地，装备己方部队，防止敌方借机壮大。")
zh(8395,"阿拉希的资源可支援任一军队，联盟请求你守住盆地，装备己方部队，防止敌方借机壮大。")
zh(8396,"阿拉希盆地的资源足以支撑两军。联盟请求你掌控盆地，为己方军队提供补给，防止敌军获得增强。")
zh(8397,"部落对联盟的战争正快速消耗着物资。掌控阿拉希盆地是维持资源流动的关键，因此需要你在前线持续支援。")
zh(8398,"部落对联盟的战争正快速消耗着物资。掌控阿拉希盆地是维持资源流动的关键，因此需要你在前线持续支援。")
zh(8399,"守护森林也意味着守护灰谷与贫瘠之地间的天然屏障。若伐木破坏它，阿斯特兰纳将面临入侵；你的协助旨在阻止这场战略危机。")
zh(8400,"守护森林也意味着维持对抗贫瘠之地的战略屏障。联盟担忧伐木会令阿斯特兰纳暴露于入侵，因此需要战争之歌的伐木队与军队予以对抗。")
zh(8401,"被部落伐木威胁的森林，亦是灰谷的防御屏障。联盟请求你支持银翼要塞，以守护阿斯特兰纳的战略安全。")
zh(8402,"被部落伐木威胁的森林，亦是灰谷的防御屏障。联盟请求你支持银翼要塞，以守护阿斯特兰纳的战略安全。")
zh(8403,"被部落伐木威胁的森林，亦是灰谷的防御屏障。联盟请求你支持银翼要塞，以守护阿斯特兰纳的战略安全。")
zh(8404,"守护林木便是守护灰谷与贫瘠之地间的战略屏障。若伐木推进，阿斯特兰纳或将面临大规模入侵；联盟需要你的协助，阻止这场危机。")
zh(8405,"战歌峡谷的冲突也牵动着阿斯特兰纳的安全。若失去森林屏障，大批敌军或可从贫瘠之地南下；你的协助旨在守护这道天然防线，而双方战火仍将持续。")
zh(8406,"部落伐木威胁的森林，亦是灰谷的防御屏障。联盟请求你支持银翼要塞，以维系这道战略防线，守护阿斯特兰纳。")
zh(8407,"战歌峡谷的防御仍与灰谷与贫瘠之地间的天然屏障息息相关。联盟希望得知你参与这场持续战略行动的讯息。")
zh(8408,"部落伐木威胁的森林，亦是灰谷的防御屏障。联盟请求你支持银翼要塞，以维系这道战略防线，守护阿斯特兰纳。")
zh(8409,"腐烂的鸡蛋已装入南海镇的陶罐。破坏行动已完成，现在必须将此事上报至提瑞斯法的稻草人节庆，告知黑暗召唤者雅恩卡。")
zh(8410,"捕风者巴斯拉召唤了一位与你经验相符的萨满祭司，并要求你提供四元素样本，以证明己备。召唤指引你前往塔伦米尔北方的河畔遗迹。")
zh(8411,"巴斯拉要求你先交付土、风、火、水四元素，以证明准备就绪。交付将展现他召唤中所要求的元素力量，也为继续与捕风者对话奠定基础。")
zh(8412,"本地的元素精灵已对巴特拉赫产生敌意。他需要灵魂图腾来守护自己，并请求从西瘟疫之地获取动物材料，以注入更原始的力量。")
zh(8413,"灵魂图腾还缺魔力，无法照巴特拉的心意起效。沉没的神庙里，巨魔守卫身上的羽毛带着他所需的那种巫毒，凑齐了，图腾才算备成。")
zh(8414,"对抗亡灵的斗争需要你的协助，以及将天灾石送交高等祭司塞尔·丹尼斯。银色黎明委任徽章能助你收集，而牧师正等待在乌瑟尔墓地。")
zh(8415,"阿什拉姆·瓦罗菲斯特寻求一位勇者圣骑士，支持他为光之事业。他的召唤指引你前往南方西瘟疫之地的寒风营地。")
zh(8416,"石块早已洗去邪恶。塞尔·丹尼斯知晓阿什拉姆的计划，他要求你带一块无害的石头，支持其对天灾军团的进攻准备。")
zh(8417,"诅咒之地的躁动灵体曾是部落的伟大英雄。他战士的荣誉超越生死，如今邀请你与他对话，了解他的处境。")
zh(8418,"阿什拉姆要把这些死石头变成对付亡灵的兵器。备料需一种能让邪恶反噬自身的魔力，它就藏在沉没的神庙巨魔守卫的羽毛里。")
zh(8419,"伊普斯要求你前往费伍德森林，并以恶魔布作为诚意象征。他的请求指向血毒瀑布附近的恶魔，那里有当地半人马携带的材料。")
zh(8420,"伊普斯想要一只宠物，不一定要活的。他要开始制作它，首先需要从费伍德森林的半人马那里获取恶魔布作为材料。")
zh(8421,"伊普斯现在可以开始制作他的恶魔布宠物了，但还需要眼睛和合适的味道。他要你提供腐烂的木头雕刻眼睛，以及从附近黏液池获取的血毒精华来赋予它恶魔的气息。")
zh(8422,"伊普斯的宠物即将完成，只差填充。他想要用沉没神庙守卫者的巫毒羽毛，为此愿意用尼比的一件物品来换取。")
zh(8423,"英雄之魂希望将一项光荣的任务托付于你，但必须先测试你的实力。诅咒之地的地狱野猪将作为试炼，正如雷克萨当年所做。")
zh(8424,"魔誓者的仪式持续折磨着英雄之魂。他无法直接回应那些伤害他的人，因此请求你代为行动，在诅咒之地传达他的怒火。")
zh(8425,"你的服务为英雄之魂带来些许安宁，他愿将昔日的装备赠予你。他需要能够短暂恢复肉身的巫毒羽毛，从沉没神庙的守卫者处获取。")
zh(8426,"部落认为银翼正试图剥夺其最大的木材来源。它号召你参与，并以服务证明协助守护此资源。")
zh(8427,"部落视银翼的抵抗为试图剥夺其木材资源。它需要维持这一重要资源，并向在森林战斗中证明自己价值的人给予认可。")
zh(8428,"部落认为银翼要塞正试图切断其重要的木材来源。它号召你在战歌峡谷作战，守护这股补给，并获取荣誉徽章。")
zh(8429,"部落认为银翼要塞正试图切断其重要的木材来源。它号召你在战歌峡谷作战，守护这股补给，并获取荣誉徽章。")
zh(8430,"部落认为银翼要塞正试图切断其重要的木材来源。它号召你在战歌峡谷作战，守护这股补给，并获取荣誉徽章。")
zh(8431,"战歌峡谷的战斗仍在持续。部落希望你继续协助驱逐银翼要塞，并提交你参与这场行动的证据。")
zh(8432,"战歌峡谷的战斗尚未结束。部落号召你持续对抗银翼要塞，并以荣誉徽章证明你对这场驱逐行动的贡献。")
zh(8433,"战歌峡谷的战斗仍在持续。部落希望你维持对银翼要塞的攻势，将其驱逐出所宣称的领地，并持续参与这场行动。")
zh(8434,"战歌峡谷的战斗仍在持续。部落希望你维持对银翼要塞的攻势，将其驱逐出所宣称的领地，并持续参与这场行动。")
zh(8435,"战歌峡谷的战斗仍在持续。部落希望你维持对银翼要塞的攻势，将其驱逐出所宣称的领地，并持续参与这场行动。")
zh(8436,"公开战争让阿拉希成为资源争夺的前线。污染者必须掌控这里的补给，以维持部落的运作，并阻止联盟利用这些物资对抗部落。")
zh(8437,"公开战争使阿拉希的资源对双方都至关重要。部落请求你协助污染者确保这条补给线，防止联盟将其用于对抗。")
zh(8438,"公开战争使阿拉希的资源对双方都至关重要。部落请求你协助污染者确保这条补给线，防止联盟将其用于对抗。")
zh(8439,"公开战争使阿拉希的资源对双方都至关重要。部落请求你协助污染者确保这条补给线，防止联盟将其用于对抗。")
zh(8440,"部落无法在战争中耗尽储备。掌控阿拉希意味着维持战力，其代表请求你继续奋战，以守护这条补给线。")
zh(8441,"部落需要资源以防储备枯竭。掌控阿拉希盆地仍是重中之重，前线需要你再度投入战斗。")
zh(8442,"部落需要资源以防储备枯竭。掌控阿拉希盆地仍是重中之重，前线需要你再度投入战斗。")
zh(8443,"部落需要资源以防储备枯竭。掌控阿拉希盆地仍是重中之重，前线需要你再度投入战斗。")
zh(8446,"此物散发着腐化之气，或许与从梦境中苏醒的巨龙有关。有人需解读它的含义；月光林地或塞纳里奥要塞的德鲁伊或许是联络对象。")
zh(8447,"雷姆洛斯认为伊露恩·艾拉拉湖的湖水可化解吞噬此物的梦魇。他的干预需等待，待他净化之后，方能窥见其隐藏之物。")
zh(8460,"木喉族对其他种族心存戒备，因许多种族无差别地攻击熊怪，不分敌我。格拉兹提供了一条表明善意的途径：驱逐威胁费伍德森林的腐化死木。")
zh(8461,"纳菲恩担心近旁的死木营地会危及自己的族人。他把那边的敌意归到邪能腐蚀头上，也不愿与同族熊怪刀兵相见，可还是请你去除了这桩祸患。")
zh(8462,"格拉兹认可你的协助，认为你足以面对更大的威胁。他指引你前往纳菲恩，他守卫着塞纳里奥要塞入口，位于北方道路上，正需要支援以抵御危害家园的势力。")
zh(8464,"冬泉族对木喉族的敌意日益加深，被恐惧与愤怒驱使。萨尔法请求你降低其东部村庄的威胁，以保护一个倾向于独来独往的族群。")
zh(8465,"腐化也从冬泉谷威胁着木喉族。萨尔法协调援助，对抗持有要塞另一侧的冬泉族，但穿越要塞需避开冲突，以免加深族群的猜忌。")
zh(8466,"单个木喉族的信任无法消除整个族群的疑虑。死木头饰的羽毛可作为你协助他们的证明，亦是继续赢得认可的方式。")
zh(8467,"一只木喉族的信任难消全族疑虑。死木头饰的羽毛可作你助他们一臂之力的明证，亦是持续赢得认可的途径。")
zh(8469,"萨尔法已对你信任有加，但族中仍有疑心者。冬泉遗骸的灵珠可作你抗腐之战的见证，亦是赢得更广泛认可的契机。")
zh(8470,"死木图腾散发出的绝望气息，映照出承载者内心的腐化。若你赢得足够信任，木喉要塞内的一只熊怪或许会找到这个不安物件的用处。")
zh(8471,"冬泉图腾弥漫着恐惧与绝望，或许暗示着族群的处境。若木喉族愿与你对话，其成员或许会为这个发现找到用处。")
zh(8481,"木喉族已想出方法引出支配冬泉的恶魔。将火把置于酋长洞窟，可借此机会直面它，寻其本源，是疗愈的第一步。")
zh(8484,"你的行动已说服木喉族寻求与联盟和平。他们请你携贡品前往铁炉堡的麦格尼，回应他早前的接触，承认你作为中间人的角色。")
zh(8485,"你的行动已说服木喉族寻求与部落和平。他们请你携贡品前往奥格瑞玛的萨尔，回应他早前的接触，承认你作为中间人的角色。")
zh(8492,"阿什兰战争所需物资浩繁。石眉负责收集铜材，请求你贡献资源，以支援联盟的战事。")
zh(8493,"安其拉战役仍需铜矿，尽管此前已有所补给。石眉持续收集物资，并请求进一步捐助，以维持联盟的战争行动。")
zh(8494,"联盟正为安其拉战争做准备，急需大量铁矿。卡恩斯组织物资收集，并请求运送铁条，以筹措战役所需材料。")
zh(8495,"铁矿仍不足以制造武器、盔甲与蒸汽坦克。卡恩斯再度请求捐助，以维持联盟对抗安其拉的生产需求。")
zh(8496,"近期伤亡严重消耗了战场绷带储备。后勤指令请求急救物资，供傲角长者补给前线战士的医疗资源。")
zh(8497,"塞纳里奥要塞的新招募者缺乏沙漠经验，面临脱水与毒物威胁。求生包内含饮水、抗毒药剂与食物，以维持新兵生命。")
zh(8498,"暮光预言者正重兵护送下发新作战指令。截取这些文件并送往马拉利斯，可获取有关教派势力行动的机密情报。")
zh(8499,"联盟几处战备都缺瑟银，尤其是一队要开赴希利苏斯的蒸汽坦克。达米在张罗收集瑟银锭，好供上这场铸造。")
zh(8500,"安其拉战争仍需钍矿支援。达米持续收集物资，并请求所有能贡献的人士提供额外铁条，以支持联盟行动。")
zh(8501,"异种蝎的威胁日益加剧，影响着战争行动。此次任务将集中火力，攻击蓝玉虫巢的空中刺虫，以减轻塞纳里奥要塞驻军的压力。")
zh(8502,"异种蝎的威胁日益加剧，影响着战争行动。此次任务将集中力量，打击蓝玉虫巢的工虫，作为应对这股增长威胁的军事行动之一。")
zh(8503,"德拉里格正在为联盟收集荆棘藻，并强调其多种用途。尽管这意味着要舍弃一些能用这种草药制作的东西，但仍需你的贡献。")
zh(8504,"荆棘藻还差一批。德拉里格确认那边仍要货，请再送一趟，好让联盟的补给不断线。")
zh(8505,"联盟已指派夜歌负责保存收集到的紫莲花，并确保有足够的储备以应对多种用途。更多花朵仍需采集，以满足战争中计划使用的角色。")
zh(8506,"紫莲花储备渐增，仍难满足联盟所需。夜歌请求你继续采集此草，并递送更多花朵以补足收集量。")
zh(8507,"在接受更复杂的任务前，你必须与铁炉堡军团在蓝玉苏尔拉的驻地完成野外勤务。卡尔东要求你报到并取得签名，避免因与奥格瑞玛军团的紧张关系而卷入冲突。")
zh(8508,"你到铁炉堡军团的驻地走了一趟，便能在勤务文书上讨一个签押。这道签押是外勤规矩里的一环——有了它，你才好向卡尔东报明自己出过力。")
zh(8509,"戈麦恩奉命收集大量阿尔萨斯之泪，以支援安其拉战争。他不清楚这些药材的具体用途，但必须贡献草药，以完成联盟赋予他的物资收集任务。")
zh(8510,"戈麦恩仍需阿尔萨斯之泪来补足战备物资。他请求再次收集，认为尽早储备将有助于加快对安其拉的进攻准备。")
zh(8511,"碎石家族以剥皮鞣皮技艺支援战争。波尼需监督轻皮的准备，同时需要他人采集兽皮以支持这项工作。")
zh(8512,"制造战争物资仍需大量轻皮。波尼维持着收集进度，请求再次运送，以持续供应安其拉战役的各项准备。")
zh(8513,"波特负责收集并追踪中皮，以支援战争。需要协助获取这种材料，以完成波特监督下的物资收集。")
zh(8514,"中皮的配额尚未达成。波特请求更多贡献，以减少缺口，继续收集联盟战争所需的储备物资。")
zh(8515,"玛尔塔追踪厚皮的运送，以支援安其拉战争。这种材料用途广泛，需提前储备，因此她请求协助收集，以便投入生产。")
zh(8516,"厚皮的配额尚未达成。玛尔塔需要更多贡献，以备制作装备、护甲与组件，满足战役各项战争用途。")
zh(8517,"一场漫长而血腥的战争迫在眉睫，战前储备物资刻不容缓。银空组织起亚麻绷带的储备，并请求协助筹备士兵的医疗物资。")
zh(8518,"亚麻绷带的储备仍未齐全，尽管早前已有贡献。银空感激这份支持，并再次请求补给，以完成战备物资的收集。")
zh(8519,"水晶深处暗流涌动，显露出过往的片段。此刻唯有静心观察，尽可能汲取信息，待时光之穴的阿纳克洛斯再度现身时，方能有所交代。")
zh(8520,"阿曼尼·基拉战争即将来临，确保士兵们装备齐全势在必行。斯通菲尔德组织起丝质绷带的收集，并请求协助完善这些储备，以保障他们的医护需求。")
zh(8521,"丝质绷带的收集仍需更多助力。斯通菲尔德感激你再度伸出援手，并维持补给安排，以扩充士兵们的物资储备。")
zh(8522,"月影认为战争已无可避免，转而专注提升涉事者生存几率。符文布绷带的收集便是其中一环。")
zh(8523,"医疗物资的筹备仍需继续。月影感激你早前的贡献，并请求更多符文布绷带，以持续强化这场战役的储备。")
zh(8524,"斯里克正为士兵筹备食物，急需彩鳍鱼即刻食用。这份贡献需先捕获并烹煮，再交付，以助联盟的补给行动。")
zh(8525,"食物补给仍在继续，斯里克需要另一批彩鳍鱼。你先前的帮助为再次贡献力量提供了契机，让士兵们不至于断粮。")
zh(8526,"萨拉自愿协助备战，尽管她并不热衷士兵们对肉食的偏好。她的岗位负责收集烤迅猛龙肉，以满足士兵们的口粮需求。")
zh(8527,"烤迅猛龙肉的收集仍在继续，为战役中的士兵提供补给。萨拉接受了另一批物资，你的贡献也持续支持着联盟的粮食储备。")
zh(8528,"急流强调，准备食物同样维系着一场军事行动。她收集斑点黄尾鱼，因其易于储存且适合多种料理，希望在阿什奎拉战争前喂饱士兵们。")
zh(8529,"急流需要另一批斑点黄尾鱼，以持续充实粮食储备。她希望借助你首次贡献的经验，再次为士兵的补给提供支持。")
zh(8530,"联盟的铁匠与工程师需要熔火之心的熔火之石，用于阿什奎拉战争。获取这些物资需组织一支队伍，深入那片危险之地。")
zh(8532,"克罗威尔要的是铜锭，不是没炼过的矿石——部落腾不出人手，也没那个工夫去冶炼。这一趟的活计就含了这道工序，炼好了，才好把料送上战场。")
zh(8533,"对铜锭的需求持续不断。克罗威尔希望你重复采矿与冶炼的工作，提供即用材料，维持部落无法自行处理的物资供应。")
zh(8534,"艾泽奈尔在苏尔拉虫巢里伏了数日，盯着异种蝎的动静。她写下的那份报告必须送到梅恩·长角手上，塞纳里奥要塞的兵马才好依着这些情报尽快出手。")
zh(8535,"安其拉城里的威胁，不容人对墙外的敌人视而不见。暮光之锤与其元素贵族为祸当前，这趟差事便是召来一名苍白圣殿骑士，与它一战。")
zh(8536,"安其拉城里的威胁，不容人对墙外的敌人视而不见。暮光之锤与其元素贵族为祸当前，这趟差事便是召来一名土色圣殿骑士，与它一战。")
zh(8537,"安其拉城里的威胁再重，也压不住墙外的敌人。暮光之锤与其元素贵族已露凶相——这道差事，要你召来一名赤红圣殿骑士，与他交手。")
zh(8538,"深渊议会似乎是暮光教派的核心组织。玛尔利斯意图摧毁这一结构，诱使四位公爵现身现实世界，这项任务交由你的经验完成。")
zh(8539,"攻击佐拉虫巢需要增援以削弱虫后数量。你的任务支援了玛尔利斯从塞纳里奥要塞协调的攻势。")
zh(8540,"塞纳里奥要塞的骑兵缺乏精制秘银战靴。紧急补给将协助其守卫装备齐全，由维斯·库鲁兹上尉统筹的物资行动。")
zh(8541,"塞纳里奥要塞的守卫需要多种等级的磨石。收集一批物资可缓解短缺，支援由维斯·库鲁兹上尉统辖的部队。")
zh(8542,"玛乌格为部落在安其拉的备战收集锡料。尽管他更愿直接参与武器与盔甲的打造，但战争开始前，他仍需协助建立金属储备。")
zh(8543,"锡料储备仍显不足，玛乌格对等待愈发焦躁。后续补给将支撑部落攻势前的关键物资筹备。")
zh(8544,"安多葛斯欲将基里阿领袖的命令符文改铸为威慑性肩甲。回收的组件将把敌方印记转化为凡人盟友的庇护。")
zh(8545,"特凯拉为战争所需物资组织秘银采集。熔炼的条块与踊跃的贡献者，方能充实仍显不足的储备。")
zh(8546,"安其拉所需的武器与盔甲仍需秘银支撑。特凯拉请求更多条块，直至配额达成，延续部落的战备进程。")
zh(8548,"瓦古斯为忠于塞纳里奥议会者预留装备。通过战斗、后勤与战术任务赢得的徽章，可确保专属盟友的战利品。")
zh(8549,"波德·飞羽欲为安其拉战争所需的药剂提供宁神花。你的协助将提升支持部落备战的草药储备。")
zh(8550,"为即将到来的战事准备药剂与药水，更需宁神花。波德·飞羽请求再度贡献，以维持生产直至战争持续。")
zh(8551,"海巨人摧毁了斯莫特的船只，杀死了他的船员。其中一名巨人高拉什，将船长的胸甲拿去当烟斗使用。失去船只与生计的斯莫特，只想夺回这件物品。")
zh(8552,"一条精工织就的腰带，边缘绣着HS的字样。这印记是寻找主人、归还衣物的唯一线索。")
zh(8553,"巨人们也摧毁了斯莫特的第二艘船，奈古拉什抢走了他的短剑。幸存的厨师能帮你找到巨人，从而尝试夺回船长的另一件物品。")
zh(8554,"斯普罗格记得奈古拉什在船毁时曾寻酒与秃鹫翅膀。将这些诱饵放在废弃的救生艇中，能引出他，夺回斯莫特的短剑。")
zh(8555,"围绕伊兰尼库斯、瓦拉斯塔兹与艾索雷葛斯的悲剧，加深了阿纳克洛斯对凡人的不信任。他的任务要求你寻找那些守护者，面对他们所受背叛的后果。")
zh(8556,"其拉戒指内含被腐蚀的宝石，或许能以更纯净的石料替代。耶萨德拉提议将这些材料重铸成无腐的强力戒指。")
zh(8557,"凯伊愿将一件其拉披风改良，助你进攻安其拉。他需要这件衣物与配件，为新穿戴者打造一枚合适的扣饰。")
zh(8558,"其拉神器使用非凡骨骼、宝石与金属，正合哈罗手工艺之选。若你对法阵忠诚，他愿将敌方材料铸成武器。")
zh(8559,"远古安其拉魔法赋予器物足以令巨龙折服的力量。坎多斯特拉兹愿将你们的指挥绑定与其他组件转化为对抗敌人的战靴。")
zh(8560,"奥罗的鳞片兼具非凡韧性与灵活度。坎多斯特拉兹请求提供样本，打造具备这些特质的护腿，借此机会向他的种族展示你的价值。")
zh(8561,"双子帝王折磨着安多葛斯，而亚雷戈斯却始终遥不可及。他想要将那两顶王冠转化为盟友的装备，把安其拉的象征化作复仇的利器。")
zh(8562,"一位古神在安其拉之下苏醒，威胁着所有生灵。温瑟拉请求你阻止他，作为回报，他要求你提供一部分他的甲壳，以换取非凡的铠甲。")
zh(8565,"一件阿拉希资源箱象征着过往胜利的认可。你必须呈上它，以完成与那场战役记录相关的交易。")
zh(8566,"一件阿拉希资源箱象征着过往胜利的认可。你必须呈上它，以完成与那场战役记录相关的交易。")
zh(8567,"银翼功勋奖章与战歌峡谷的过往胜利紧密相连。你必须呈上它，以完成对那段参与经历的认可。")
zh(8568,"战歌荣誉奖章记录着过往的胜利。呈上它，便可完成与战场上部队奋战相关的交易。")
zh(8569,"牺牲的丝带象征着战歌峡谷昔日的奋战。你需携此信物，完成与你参与这场冲突相关的交易。")
zh(8570,"牺牲的丝带象征着战歌峡谷昔日的奋战。你需携此信物，完成与你参与这场冲突相关的交易。")
zh(8572,"塞纳里奥议会希望其忠诚的贡献者装备齐全。瓦古斯接受服务徽章与荣誉声望，作为获取专属老兵装备的凭证。")
zh(8573,"塞纳里奥议会的信任，为最杰出的盟友开启装备之门。瓦古斯要求服务徽章与塞纳留斯印记，以证明所需贡献。")
zh(8574,"战斗、补给与战术服务可向瓦古斯证明。专属尊贵盟友的装备，需徽章与雷姆洛斯印记，将奖励与对议会的忠诚相连。")
zh(8575,"艾索雷葛斯的魔法账本，用你无法辨识的语言书写。携它去找纳瑞安，寻求解读这份内容仍完全不可触及的文件。")
zh(8576,"纳瑞安需用目镜翻译艾索雷葛斯所称的奥金鱼漂蓝图。他的尝试需要占卜目镜、龙人手册，以及一只异常巨大的鸡。")
zh(8577,"纳瑞安需要目镜翻译账本，却说斯图沃尔偷走了它们。水晶球的幻象提供矛盾线索，追踪他昔日的友人。")
zh(8578,"斯图沃尔承认在探索熔火之心时弄丢了纳瑞安的目镜。要找回这件矮人翻译工作所需的器具，搜寻仍需继续。")
zh(8579,"巨龙们若想接近克苏恩，势必会重蹈兄长们被奴役的覆辙。凡人或许另辟蹊径，但必须先赢得青铜巨龙的信赖。")
zh(8580,"佩莱基基为安其拉的战争收集火焰花，却不知其确切用途。他需增加部落所需的草药补给。")
zh(8581,"佩莱基基急需更多火焰花，甚至考虑用它制成炸弹对付安其拉的虫群。另一批运送，是他幻想从蝙蝠身上发起突袭的铺垫。")
zh(8582,"耶泽尔需要紫莲花来制作药剂、药水与油类，支援战争。他也想探索其他用途，但两项计划都需要大量花类原料。")
zh(8583,"耶泽尔的研究尚未发现紫莲花的新用途。研究仍在继续，他仍需更多样本以维持现有用途的战争准备。")
zh(8584,"纳瑞安坚持他的工作需要一只五百磅的鸡，却只字不提缘由。加基森的迪尔格是他推荐的联系人，可帮忙寻得合适的样本。")
zh(8585,"迪尔格提议用拉克玛兰的尸体代替纳瑞安那巨大的鸡。他同时想要恐怖之岛奇美洛克的肉，传说中那可是品质非凡的食材。")
zh(8586,"迪尔格完成了配方，却仍需火箭燃料与石中盐。这些材料能让那奇特的鸡继续烹制，再送往纳瑞安手中。")
zh(8587,"迪尔格如约交出那只巨大的鸡，却对纳瑞安的意图一头雾水。这举动满足了矮人一项奇特的要求，关乎账本的整理。")
zh(8588,"部落将重皮用于铠甲、加固与军用帆布。亚曼尼亟需更多皮革以备战事，恳请协助维持供应。")
zh(8589,"将军、军需官与飞艇长的订单让重皮供不应求。亚曼尼迫切需要更多补给，以满足部落的预期配额。")
zh(8590,"乌玛拉为安其拉的战备收集厚皮，部落的准备已渐入佳境，但她仍需更多贡献者提供所需的皮革。")
zh(8591,"乌玛拉尚未完成厚皮的储备，另一批补给支持着余下的战备，也向那些协助部落的人致意。")
zh(8592,"安多葛斯在双子帝王的嘲笑中苦熬，却无力救出亚雷戈斯。他渴望夺下他们的王冠，将那些基尔贾符号化作盟友的护盾。")
zh(8593,"奥罗的皮毛几乎坚不可摧，却让蠕虫得以灵活穿梭。坎多斯特拉兹愿将这结合了坚韧与柔韧的材质制成护甲。")
zh(8594,"安多葛斯将凡人肩甲比作巨龙翅膀的仿制品。他提议用其拉命令锁链打造一件震慑敌人的战甲。")
zh(8595,"其拉领主众多，击败一个并不足够。巨龙要求你继续战斗，以证明你足以胜任他们的冠军之位。")
zh(8596,"其拉遗物蕴含远古魔法，连巨龙也心存敬畏。坎多斯特拉兹愿将命令锁链与其他回收材料炼成作战用的战靴。")
zh(8597,"纳瑞安将龙人手册藏于一处仅能由旋翼机抵达的偏远之地。他坠机的残骸，成了寻回手册的起点。")
zh(8598,"勒索信声称有人夺走了纳瑞安的手册。作者要求金钱与独处交付，使寻找手册的行动演变为对地精的威胁。")
zh(8599,"米莉蒂丝仍怀念当年从坠毁飞行器中救出的地精。她希望纳瑞安收到一封情书，需一名信使将它送达。")
zh(8600,"塞拉图斯需要硬甲皮筹备安其拉的行动。他的任务将皮革加工与部落的后勤补给与战争储备紧密相连。")
zh(8601,"塞拉图斯担心硬甲皮短缺会拖延安其拉的筹备。他急切要求再送一批，以确保后勤与战事同步推进。")
zh(8602,"安多葛斯将凡人的肩甲比作巨龙之翼的仿制品。他提议使用其拉统御腕轮打造一件威慑敌人的战甲。")
zh(8603,"旧神在其拉教派之下苏醒，威胁所有生命。温瑟拉请求你阻止他，以换取他尸骸的一部分，铸成非凡的铠甲。")
zh(8604,"战事一起，士兵身边未必总有医师。朗兰纳收集绒线绷带，充实急救包——孤身无援时，包扎伤口的活儿只能靠自己。")
zh(8605,"远行者记得太多早前战场上的逝者。更多绒线绷带将助士兵们自保，避免因无援而再添伤亡。")
zh(8606,"纳瑞安想擒获那些勒索他书本的人。伪装与一袋石头将助你假扮他，现身于交易处，直面幕后黑手。")
zh(8607,"卡隆下令收集魔纹绷带，任何手段皆可。她承诺以报酬奖励那些增加她管辖物资的运送者。")
zh(8608,"卡隆为其拉战争所筹的物资仍需魔纹绷带。她要求另一批补给，以扩充她被指派收集的储备。")
zh(8609,"部落与联盟联手对抗异种蝎，而非彼此厮杀。陶蹄需要符文布绷带，分发给参与战斗的士兵。")
zh(8610,"安其拉的虫群与主子正面临围攻，需精锐部队应对。尼根·陶蹄请求再提供一批符文布绷带，以支援那些将直面危险的战士。")
zh(8611,"拉尔塔必须将狼排腌制保存以供战事之需，因此无法亲自收集。他需要有人送熟肉前来，以维持士兵的体力。")
zh(8612,"士兵的粮食储备尚未完备。拉尔塔再度请求送来瘦狼排，他知道战场上的艰辛，饥饿将如影随形。")
zh(8613,"部落命林·多收集大量斑点黄尾鱼以供安其拉使用。所需数量远超他个人所能获取，故需你协助钓鱼。")
zh(8614,"安其拉的战士们需要充足的食物补给。林多再度请求送来熟制的斑点黄尾鱼，以完成部落托付的鱼类储备。")
zh(8615,"锋爪深知饥饿的士兵无法挥动战斧。他收集烤鲑鱼，不仅因其滋养之效，更因它易于保存，适合作战前的储备。")
zh(8616,"锋爪尚未完成战争所需的烤鲑鱼配额，再送一批将助他完善为部落准备的粮食储备。")
zh(8617,"部落所需之贡献，需集结足以进入熔火之心的强大力量。那里的居民持有大量熔火之石，正是安其拉计划所急需。")
zh(8619,"黎明长者以朝拜古人的姿态迎接你的到来。这位长者将象征物赠予那些仍铭记并敬重其遗志之人。")
zh(8620,"维维尔博士摧毁了唯一已知的巨龙手册副本，并将残章散落四方。纳瑞安提供魔法绑定，助你重铸译书所需之本。")
zh(8621,"其拉遗物中蕴含的古老魔力，连巨龙也心存敬畏。坎多斯特拉兹愿将这些支配之缚与其他回收材料炼成战靴，用于对抗其拉族群。")
zh(8622,"旧神在安其拉之下蠢动，威胁万物生灵。温瑟拉请求你阻止他，以换取其残躯，铸就非凡铠甲。")
zh(8623,"安多葛斯在双子帝王的嘲弄中忍辱负重，却无力拯救亚雷戈斯。他欲夺走王冠，将其拉符文转化为盟友的护盾。")
zh(8624,"奥罗的鳞甲近乎坚不可摧，却赋予虫群敏捷之姿。坎多斯特拉兹愿将此韧性与柔韧结合，炼成护甲。")
zh(8625,"安多葛斯将凡人肩甲比作龙翼的仿制品。他提议用其拉统御腕轮铸成威慑之器，以战敌军。")
zh(8626,"其拉遗物中蕴含的古老魔力，连巨龙也心存敬畏。坎多斯特拉津愿将这些命令之缚与其他回收材料炼成战靴，用于对抗其拉族群。")
zh(8627,"远古之神在其拉之泉下苏醒，危及万物生灵。温瑟拉请求你阻止他，以换取非凡的护甲，作为代价，她要取下他的尸骸一角。")
zh(8628,"安多葛斯在双子帝王的嘲弄中忍辱负重，却无法救出亚雷戈斯。他渴望夺下他们的王冠，将那些其拉图腾转化为庇护盟友的屏障。")
zh(8629,"奥罗的甲壳几乎坚不可摧，却让蠕虫能灵活移动。坎多斯特拉兹愿以这结合了坚韧与柔韧的特质，打造一件守护之物。")
zh(8630,"安多葛斯将凡人的肩甲比作龙翼的仿制品。他提议用其拉统御腕轮，打造一件震慑敌人的战甲。")
