zh(8728,"纳瑞安相信自己能打造记载于账簿中的奥金鱼漂。阻碍在于收集所需稀有金属与宝石，方能动工。")
zh(8729,"鱼漂必须沉入风暴海湾的漩涡附近。纳瑞安警告，巨齿鲨——那头庞然巨物——将使碎片的回收成为众人的任务。")
zh(8730,"瓦拉斯塔兹不再守护碎片：奈法里奥斯已夺走它，并计划摧毁它。他的警告，将搜寻化作一场守护权杖残片的竞速。")
zh(8731,"在接手更复杂的任务前，你必须与奥格瑞玛军团并肩作战。这项任务要求你证明参与度，同时避免与联盟志愿者产生新的摩擦。")
zh(8732,"野外勤务的规矩，先得把文书呈到队长面前。他一脸困惑；要让他点头认下你曾随他的兵马出征，这一面总归要见。")
zh(8733,"玛法里奥希望清除伊兰尼库斯身上的旧神腐化，并夺回那枚绿晶。一位驻扎在达纳苏斯的特工可向泰兰德传递消息，而不惊动鹿盔。")
zh(8734,"泰兰德将得知玛法里奥的计划。月光林地的雷姆洛斯知晓召唤伊兰尼库斯的下一步，以及继续尝试拯救他的行动。")
zh(8735,"雷姆洛斯正准备召唤伊兰尼库斯，需要来自四个梦境传送门的梦魇腐化碎片。那些传送门附近的龙裔手中，掌握着这些准备所需的样本。")
zh(8736,"目标是拯救伊兰尼库斯，因此他不能被摧毁。当泰兰德前来协助时，你的盟友必须抵挡他的攻击，保护永夜港。")
zh(8737,"暮光之锤及其元素贵族正威胁着希利苏斯的行动。在安其拉内战斗不能成为忽视外部威胁的借口，而一位碧蓝圣殿骑士正是这项任务的目标。")
zh(8738,"兰迪奥数日来密切观察雷戈虫巢的动向。获取他的书面报告，将能迅速回应侦察兵从虫巢搜集到的情报。")
zh(8739,"佳莉亚已盯了亚什虫巢数日。她写下的笔录须呈上来——那些亲眼所见，才能化作希利苏斯兵马即刻出兵的凭据。")
zh(8740,"骑乘的暮光异教徒袭击着塞纳里奥要塞势力范围外的商队与小规模巡逻队。击败他们与莫娜，旨在阻止这些威胁军队行动的突袭。")
zh(8741,"那枚绿色碎片如今可呈递给阿纳克洛斯，于时光之穴中。它的守护者正等待着这一片，作为重获流沙节杖工作的关键一步。")
zh(8742,"阿纳克洛斯把你的到来，看作挑战克苏恩预言的一个机会。待你答允，他便将流沙节杖交到你手里，让这桩事接着做下去。")
zh(8743,"敲响铜锣将开启安其拉的门扉，也将你的族群暴露于其中的混乱。这场遭遇要求你做好准备，以抵御那扇门开启后的后果。")
zh(8744,"那件精心包裹的礼物上刻着你的名字，正等待着被认领。冬季庆典提供了一个小型的节日遭遇，围绕着收礼与共享节日氛围展开。")
zh(8745,"乔纳森守护着铜锣，留意着青铜飞行的动静。永恒之灵已授权他从自己的宝库中提供一件物品，以协助你对抗克苏恩的战斗。")
zh(8746,"驯鹿梅森，是冬天爷爷座下的一头驯鹿，被绑架了。两伙人索要赎金，他们的书信或许能指引寻人之路，而特殊粉末可解除他的束缚。")
zh(8747,"对青铜飞翼的忠诚使你得以选择一条防御之路。这枚戒指旨在强化你的防护，以表彰你所赢得的恩典。")
zh(8748,"你对卡利姆多子民的持续守护已获认可。交出戒指，其力量将因你对威胁的警觉而更胜一筹。")
zh(8749,"你守护卡利姆多对抗掠夺者的行为已再获嘉许。戒指可再度增强，以助你对抗那些敌人。")
zh(8750,"你对世界的守望展现了值得嘉奖的坚定。戒指将接受更强的附魔，以表彰你一贯的忠诚。")
zh(8751,"你所展现的坚韧已赢得最终的附魔。这枚戒指的强化源自永恒之灵亲自请求，以表彰你的服务。")
zh(8752,"青铜飞翼认可你的努力，赐予征服者之路。这枚戒指强化物理攻击，将你从巨龙处赢得的恩典引向特定方向。")
zh(8753,"你对卡利姆多子民的持续守护已获认可。交出戒指，其力量将因你对威胁的警觉而更胜一筹。")
zh(8754,"你守护卡利姆多对抗掠夺者的行为已再获嘉许。戒指可再度增强，以助你对抗那些敌人。")
zh(8755,"你守护世界的意志彰显了值得嘉奖的坚韧。这枚戒指将接受更强大的附魔，以表彰你持续的奉献。")
zh(8756,"你展现的毅力理应获得最终的附魔，由青铜飞翼赐予。这枚戒指的强化源自永恒之灵本人的请求，以肯定你的服务。")
zh(8757,"你为赢得青铜飞翼青睐所付出的努力，使你得以选择召唤者的道路。这枚戒指将增强持有者的魔法与自然之力。")
zh(8758,"你持续守护卡利姆多子民的行动已被铭记。交出戒指，让其力量因你对威胁的警觉而更进一步。")
zh(8759,"你对抗掠夺卡利姆多土地之敌的奋战，赢得了更多认可。这枚戒指将再度强化，以支持你对抗那些敌人。")
zh(8760,"你守护世界的意志彰显了值得嘉奖的坚韧。这枚戒指将接受更强大的附魔，以表彰你持续的奉献。")
zh(8761,"你展现的毅力理应获得最终的附魔，由青铜飞翼赐予。这枚戒指的强化源自永恒之灵本人的请求，以肯定你的服务。")
zh(8762,"梅森在节日期间遭人绑架，烟林收到了两封赎金信。调查书信并使用解救尘，或许能救出这头驯鹿。")
zh(8763,"新鲜冬青树易腐，唯有机器可使其永存。此物赠予技艺精湛的厨师，只需以石中盐与自身长久之需为代价。")
zh(8764,"改换道路需交出印戒，并献上大量其拉甲虫。此物允你以安其拉敌人的材料重思抉择。")
zh(8765,"改换道路需交出印戒，并献上大量其拉甲虫。此物允你以安其拉敌人的材料重思抉择。")
zh(8766,"改换道路需交出印戒，并献如山的其拉甲虫。此物允你以安其拉敌人的材料重思抉择。")
zh(8767,"一盒看似被摇晃过的礼物，专为你而设。靠近包裹，便能参与这场节日赠礼，却不知内中藏有何物。")
zh(8768,"华丽包裹上刻着你的名字，位列节日礼物之中。盒内似有动静，然仍需靠近方知准备了何物。")
zh(8769,"烟林牧场献上一份祝愿，愿你欢度冬日佳节。集齐为‘伟大冬日盛宴’准备的礼物。")
zh(8770,"异种蝎的威胁日益逼近战事。对亚什虫巢的突袭，将你派往迎战其守卫，并向指挥官玛尔利斯汇报战果。")
zh(8771,"硅虫威胁日益加剧，玛尔利斯下令袭击亚什虫巢的沙虫，以支援针对该巢的有组织进攻。")
zh(8772,"对佐拉虫巢的进攻亟需增援，你的任务目标是其守望者，协助由玛尔利斯从塞纳里奥要塞指挥的攻势。")
zh(8773,"佐拉虫巢正遭围攻，急需增援以延续攻势。对抗其掠夺者，正是玛尔利斯在该行动中所指派的特定任务。")
zh(8774,"硅虫威胁随战争推进愈发严重，袭击雷戈虫巢的伏击者，是玛尔利斯试图保护己方行动的进攻一部分。")
zh(8775,"硅虫部队威胁战争行动，此次对雷戈虫巢的进攻目标是其空中突袭者，战果将上报玛尔利斯于塞纳里奥要塞。")
zh(8776,"异种蝎的势头一日盛过一日，雷戈虫巢非清剿不可。这一战先拿它的奴隶主开刀，好教战事少受几分威胁。")
zh(8777,"对雷戈虫巢的进攻回应了硅虫日益增长的威胁。玛尔利斯指派你对抗其巢穴挖掘者，作为对该虫巢的进攻行动之一。")
zh(8778,"铁炉堡军团急需特殊材料，收集并送至诺斯宾，可解决其在希利苏斯的异常物资请求。")
zh(8779,"拉克斯贝恩的研究对希利苏斯的行动大有裨益，但需要占卜材料。收集并送至地质学家手中，便能让她继续为塞纳里奥要塞的研究添砖加瓦。")
zh(8780,"铁炉堡军团的前线装甲补给已濒临枯竭。珍妮拉急需在佐拉虫巢据点再获补给，以维持部署部队的装备运转。")
zh(8781,"铁炉堡军团曾在希利苏斯协助作战，但途中损耗了不少物资。将武器送至珍妮拉手中，可为盟友补足部分装备缺口。")
zh(8782,"更多志愿者的加入使统一制服的补给告急。傲角长者亟需物资以替换旧装，并为新加入塞纳里奥要塞的战士们提供装备。")
zh(8783,"瓦古斯需要魔能材料打造强力武器，以支援塞纳里奥要塞的战力。直接送至铁匠手中，可确保部队装备不落人后。")
zh(8784,"你发现了一件上古其拉神器，其潜在价值尚不可知。庙宇入口处的巨龙或许能认出这件重获的遗物用途。")
zh(8785,"奥格瑞玛军团在希利苏斯的出色表现鼓舞了士气，促使其请求迅速响应。沙艾正等待几种罕见的材料，以完成这项补给任务。")
zh(8786,"奥格瑞玛军团尚缺一批尚未送达的武器。将它们送至希利苏斯雷戈虫巢附近的梅洛克手中，可缓解部队装备短缺之困。")
zh(8787,"部落军团的志愿者抵达希利苏斯，却在途中遗失了装备箱。梅洛克需要补给，以支持塞纳里奥议会的行动。")
zh(8788,"一份看似被摇晃过的礼物，特别寄予你。靠近包裹，便能参与这场节日赠礼，而不必事先知晓它藏了什么。")
zh(8789,"巨龙们观察其拉族的暴行与弱点已逾数世纪。它们的仪式性武器，可结合源自神祇暴躁本性的元素，反制其拉族。")
zh(8790,"亚雷戈斯相信，源质能要上古之神与其仆从的命。把它掺进其拉帝王徽记，正可顺着这道软肋，让兵器多添几分凶性。")
zh(8791,"无疤者奥斯里安已陨落，这消息或能安抚卡利姆多的居民。将他的头颅献给玛尔利斯，既报捷讯，也证明威胁已被肃清。")
zh(8792,"部落急需人力收集资源，以支持安其拉战役。格尔库克统辖筹备，可指引有意协助官方采集者之人。")
zh(8793,"部落急需人力收集资源，以支持安其拉战役。格尔库克统辖筹备，可指引有意协助官方采集者之人。")
zh(8794,"部落急需人力收集资源，以支持安其拉战役。格尔库克统辖筹备，可指引有意协助官方采集者之人。")
zh(8795,"联盟官方采集者无法独自为安其拉筹措资源。雪落统筹筹备，亟需志士协助，共赴战争目标。")
zh(8796,"联盟官方采集者无法独自为安其拉筹措资源。雪落统筹筹备，亟需志士协助，共赴战争目标。")
zh(8797,"联盟官方采集者无法独自为安其拉筹措资源。雪,落统筹筹备，亟需志士协助，共赴战争目标。")
zh(8798,"你的协助换来传授机械雪人建造之术。工程学知识助你实践，但零件仍需采集方能成形。")
zh(8799,"新鲜冬青易腐，然机器可使其永存。此物赠予精于烹饪之士，需以石中盐与自身永续供给为交换。")
zh(8800,"战时任务所得徽章，彰显你对瓦古斯的忠诚。咨询铁匠，可依贡献换取塞纳里奥要塞所备装备。")
zh(8801,"克苏恩残骸仍透出诡异邪恶，取其眼珠献予龙族，呈交下层密室等待之人。")
zh(8802,"阿纳克洛斯在时光之穴等待克苏恩的眼珠。呈上此物，可纳入其主收藏的宝物之中。")
zh(8803,"节日礼物承载着冬天爷爷的美好祝愿。领取它，是为艾泽拉斯各地的人们传递温暖与节日喜气的庆典之一。")
zh(8804,"塞纳里奥要塞的新兵对沙漠的危险尚不熟悉。卡兰德拉斯需要补给品，以应对脱水与众多毒虫对新手志愿者的威胁。")
zh(8805,"塞纳里奥要塞的骑马卫士急需精制秘银战靴。将这批物资送往维斯·库鲁兹，能缓解装备短缺，完成补给任务。")
zh(8806,"塞纳里奥要塞的守卫缺乏磨石。将一批货物送至维斯·库鲁兹，可补足他麾下部队所需的物资。")
zh(8807,"拉克布莱恩的研究对希利苏斯的行动颇具价值，但需占卜材料。搜集并送至地质学家，便能让她继续为塞纳里奥要塞的研究贡献力量。")
zh(8808,"新加入的志愿者使制服补给告急。傲角长者需要材料，以替换旧物并装备这些新加入塞纳里奥要塞的战士。")
zh(8809,"瓦古斯需要附魔材料，以打造强力武器装备塞纳里奥要塞的部队。直接送往铁匠，能支持这项维持战力的工程。")
zh(8810,"近期的伤亡使前线绷带严重短缺。傲角长者需要急救物资，以补充塞纳里奥要塞部队所消耗的储备。")
zh(8811,"达纳苏斯允许尚未拥有十枚勋章的个体提交一枚勋章徽章。此贡献虽获认可度较低，但仍能体现对城市的微小贡献。")
zh(8812,"诺莫瑞根流亡者对单枚勋章徽章给予适度认可。个人递送方式便于尚未集齐十枚者表达服务之意。")
zh(8813,"铁炉堡允许未集齐十枚勋章者提交一枚徽章。此服务虽认可度有限，但完整集齐将更彰显努力。")
zh(8814,"暴风城同样承认单枚勋章徽章所代表的服务。其认可度不及十枚合集，却让未集齐者也能参与其中。")
zh(8815,"奥格瑞玛允许未集齐十枚勋章者提交一枚徽章。此服务给予适度认可，同时鼓励更大贡献以换取更高评价。")
zh(8816,"黑暗之矛允许以单枚勋章徽章认可服务。递送虽获有限认可，但十枚合集仍是更受推崇的选择。")
zh(8817,"幽暗城接受一枚勋章徽章以认可未集齐十枚者的贡献。此选项认可度较低，但让微小贡献也能被看见。")
zh(8818,"雷霆崖接受单枚勋章徽章以表彰较小服务。未集齐十枚者可提交一枚，但完整集齐将更受重视。")
zh(8819,"达纳苏斯认可通过勋章徽记记录的功绩。十枚一同呈交比单独贡献更受重视，但小规模的善举仍会被铭记。")
zh(8820,"诺莫瑞根流亡者接受勋章徽记作为功绩证明。十枚一同呈交可获更高认可，但个别徽记也会被用于肯定微小贡献。")
zh(8821,"铁炉堡视勋章徽记为功绩凭证。十枚一同呈交比单独递送更能彰显价值，但个别贡献仍会被记录。")
zh(8822,"暴风城重视勋章徽记所记录的功绩。十枚一同呈交比单独递交更受重视，但个别递送也依然有效。")
zh(8823,"奥格瑞玛对通过勋章徽记展现的功绩给予认可。十枚一同呈交更受青睐，但个别贡献亦不会被忽视。")
zh(8824,"黑暗之矛部落认可勋章徽记所记录的功绩。十枚一同呈交比单枚更受重视，但两种形式皆被接受。")
zh(8825,"雷霆崖授予呈交勋章徽记者应得的荣誉。十枚一同呈交价值更高，但任何贡献都不会被排除在外。")
zh(8826,"幽暗城接受勋章徽记作为功绩证明。十枚一同呈交比单独递交更受重视，但小规模贡献也依然被认可。")
zh(8827,"冬天爷爷在铁炉堡的树下放置了礼物，得力于一家节日商铺的支持。你被鼓励在操作者仍在照料节日机械时前去拜访他。")
zh(8828,"冬天爷爷的礼物静静躺在奥格瑞玛的树下。节日机械的操作者无法离开岗位，却仍鼓励你前来参与那里的庆典。")
zh(8829,"暮光之锤的秘密似乎指向一处难以抵达之地。奥蕾尔需要一名使者长袍的精确复制品，才能尝试借他们的召唤石作为进入的通道。")
zh(8830,"达纳苏斯接受那些尚未拥有十枚徽记者所提交的一枚徽记。此举虽认可度较低，却仍为小规模贡献提供了一种肯定方式。")
zh(8831,"达纳苏斯认可通过徽记记录的贡献。十枚徽记一同呈上，可获得比单个贡献更高的认可，但小规模善行亦被铭记。")
zh(8832,"幽暗城接受一枚徽记，以表彰那些尚未集齐十枚者的服务。此选项认可度较低，但让微小贡献也能被记录。")
zh(8833,"幽暗城接受徽记作为服务的证明。十枚徽记一同呈上，可获得比单独提交更高的认可，但小规模贡献亦被纳入考量。")
zh(8834,"铁炉堡允许尚未集齐十枚徽记者提交一枚徽，以认可其微小贡献。虽不及完整套装的认可度，但至少让努力被看见。")
zh(8835,"铁炉堡接受徽记作为服务的证明。十枚徽记一次呈上，可获得比单独提交给代表更高的认可。")
zh(8836,"暴风城亦认可单枚徽记所代表的服务。虽不及十枚共同提交的认可度，却让未集齐者也能参与其中。")
zh(8837,"暴风城重视通过勋章徽章记录的服务。集齐十枚可获得更高认可，但城市也保留单独提交的选项。")
zh(8838,"诺莫瑞根流亡者对单枚勋章徽章给予适度认可。无法集齐十枚者，可单独提交以获得肯定。")
zh(8839,"诺莫瑞根流亡者接受勋章徽章作为服务证明。代表认可十枚合集，但也接纳单枚以表彰微小贡献。")
zh(8840,"奥格瑞玛允许无十枚者提交单枚勋章徽章。此服务给予适度认可，同时鼓励更大贡献。")
zh(8841,"奥格瑞玛认可通过勋章徽章展现的服务。代表偏爱十枚合集，但也接纳单枚以确保无服务被忽视。")
zh(8842,"雷霆崖接受单枚勋章徽章以表彰较小服务。无十枚者可提交一枚，但完整合集将获得更高认可。")
zh(8843,"雷霆崖认可那些呈交奖状徽记以表功绩的勇士。十枚徽记的交出比单枚更具价值，但任何贡献都不会被忽视。")
zh(8844,"黑暗之矛允许以一枚奖状徽记表彰功绩。交出徽记可得适度认可，但十枚仍是更受重视的选择。")
zh(8845,"黑暗之矛部落认可通过奖状徽记记录的功绩。交出十枚徽记可得更高赞誉，尽管单枚与十枚皆被接受。")
zh(8846,"奖状徽记可兑换个人战备物资。此交易重在获取生存装备，而非换取交出徽记的认可。")
zh(8847,"奖状徽记可兑换个人战备物资。以装备换取徽记，意味着放弃功绩的认可，换取战场上的生路。")
zh(8848,"奖状徽记也可兑换个人战备物资。此安排以装备换取生存，牺牲了原本交出徽记可得的认可。")
zh(8849,"逼近的战斗让额外物资尤为珍贵。你可用奖状徽记换取实用的生存装备，但如此花费将不被视作功绩。")
zh(8850,"逼近的战斗让额外物资尤为珍贵。你可用奖状徽记换取实用的生存装备，但如此花费将不被视作功绩。")
zh(8851,"奖状徽记可换得个人战争物资。这项优惠着重于获取实用装备以应对战斗，而非因上交所获徽记而获得表彰。")
zh(8852,"对额外装备的需求使奖状徽记可换物资。如此上交并无表彰，但所得物品或能强化你的战备。")
zh(8853,"对额外物资的需求使徽记可换战争物资。如此上交无表彰，但其价值或能化为装备，强化战前准备。")
zh(8854,"迫近的战斗让额外物资愈发珍贵。你可用奖状徽记换取实用生存装备，但如此花费将无功可表。")
zh(8855,"迫近的战斗让额外物资愈发珍贵。你可用奖状徽记换取实用生存装备，但如此花费将无功可表。")
zh(8856,"塞纳里奥要塞的新兵不谙沙漠险境。卡兰德拉斯需物资制作防脱水与毒物的生存装备，以护那些经验不足的志愿者。")
zh(8857,"奥格索普需要阿希陨落巨像的新鲜样本。挑战已非采集，而是尽快运送可用样本，以防其腐烂。")
zh(8858,"从瑞格尔巨像采集样本让采集者忙碌不已。奥菲斯特支付新鲜样本，因此急需一名迅捷信使，将样本送至灼热峡谷。")
zh(8859,"玛克斯韦尔·泰罗索斯男爵认为苏尔拉的巨像或许藏着对抗天灾军团的秘密。那批冒着极大风险收集的样本必须在尚且新鲜时送往圣光之愿礼拜堂。")
zh(8860,"暴风城的新年庆典需要招待宾客的美食。艾莉森在旅店里等待烟林牧场的佳肴送达，好让参加庆典的宾客们饱餐一顿。")
zh(8861,"帕拉的旅店需要补给以应对雷霆崖的新年庆典。送烟林牧场的美食能帮助宴请前来参加城市节日庆祝的宾客们。")
zh(8862,"艾露恩的蜡烛蕴含真月之光，那是月圆节最受尊崇的象征。尽管对多数生物无害，但它的光芒却能灼伤并炫目年兽及其爪牙。")
zh(8863,"饺子自月圆节首次庆祝起便成为传统食物。一枚先祖硬币可让你通过向尊崇长者的人们提供的交换品，品尝那道美食。")
zh(8864,"月圆节的服饰承袭过往庆典的风尚。先祖硬币让你能挑选一件手工制作的衣裳，以自己的装扮参与这段传统。")
zh(8865,"特制的节日长袍是特别打造的庆典服饰。先祖硬币让你能挑选其中一种款式，穿着它参与庆典。")
zh(8866,"铜须长者欢迎人们对这片土地上古老民族的敬意。这场邂逅以一枚象征性物品赠予那些守护他们记忆的人，以示敬意。")
zh(8867,"德鲁伊们以月光林地的古老胜利为荣，举国欢庆，宴饮烟花齐飞。购买火箭并使用发射器，便可加入这场致敬先贤智慧的盛典。")
zh(8868,"年兽曾是英雄，却在恶魔魔法的侵蚀下背弃盟友。每逢银月节，他便在安息之地苏醒，召唤愿意直面他的同伴。")
zh(8869,"成为一名铁匠需重拾血色铁匠守护的银月外衣，以证明你对这门技艺的专注，而非流于其他路径。")
zh(8870,"塞纳里奥议会邀约艾泽拉斯所有生灵共赴银月节。那立于月光法阵中的使者，可为有意参与的众人讲述庆典的意义。")
zh(8871,"塞纳里奥议会邀约艾泽拉斯所有生灵共赴银月节。那立于月光法阵中的使者，可为有意参与的众人讲述庆典的意义。")
zh(8872,"塞纳里奥议会邀约艾泽拉斯所有生灵共赴银月节。那立于月光法阵中的使者，可为有意参与的众人讲述庆典的意义。")
zh(8873,"塞纳里奥议会邀约艾泽拉斯所有生灵共赴银月节。那立于月光法阵中的使者，可为有意参与的众人讲述庆典的意义。")
zh(8874,"塞纳里奥议会邀约艾泽拉斯所有生灵共赴银月节。那立于月光法阵中的使者，可为有意参与的众人讲述庆典的意义。")
zh(8875,"塞纳里奥议会邀请艾泽拉斯所有生灵共赴月光节。月光中伫立的先知，将为有意参与庆典者讲述其中奥义。")
zh(8876,"关于月光节小火箭的知识，已赠予受尊崇者。献上先祖硬币，便可习得配方，将你的创作融入庆典。")
zh(8877,"火箭需借助发射器方能点亮庆典。献上先祖硬币，便可习得制作技艺，与友人共谱盛景。")
zh(8878,"传统服饰与礼服致敬旧日风习与故去亲朋。先祖硬币助你习得制衣纹样，织就追思之衣。")
zh(8879,"大型月光节火箭以璀璨光芒点亮夜空，其辉煌更胜卵囊火箭群。献上先祖硬币，便可习得其工艺，为庆典添彩。")
zh(8880,"卵囊火箭将单枚火箭汇聚成共享盛景。其配方以先祖硬币为代价，任人习得，自创庆典新章。")
zh(8881,"大型卵囊火箭需丰沛材料与精湛技艺，然其华美值得付出。先祖硬币可助你习得秘技，缔造庆典烟火。")
zh(8882,"卵囊火箭需专属发射器方能成就壮丽盛景。献上先祖硬币，便可习得制作技艺，为月光节庆典添砖加瓦。")
zh(8883,"春节邀请函可借月光通往月光林地。瓦拉达尔与法蕾尔欢迎所有愿参与庆典并探寻其馈赠之人。")
zh(8893,"克格尔的超级测蛋器以角鹰兽蛋换取蛋箱。机器旁的控制面板旁，你可将蛋放入其中完成交换。")
zh(8897,"守卫职责无暇拜访科兰拉。她的追求者担心被更有财力的男子抢去，故托你将他写下的信言转达。")
zh(8898,"前往暴风城的商务之旅令访客爱上了科兰拉。他反复修改信件，渴望亲自递送以避开邮差人潮。")
zh(8899,"科兰拉的追求者难以道尽她之美。惧怕他人分其注意力，他盼信件在反复修改后才交付。")
zh(8900,"同伴的讥笑令他与艾琳娜无话可说，尽管他心中理解她。如今他思念她，需亲手将信交到她手中。")
zh(8901,"对艾琳娜的情愫令某人意外。他写信邀来自幽暗城的少女来莫高雷，并期盼她能接受这份邀约。")
zh(8902,"一位旧日未婚夫在多年别离后，再度思念艾琳娜。他期盼仍有余地重拾旧爱，却需他人代递信件，因惧亲自送达。")
zh(8903,"这场痴迷浪潮看似异常，或会动摇联盟的防线。调查暴风城守卫是否受影响，揭开这番疑云的序幕。")
zh(8904,"这股奇特的爱之瘟疫或会削弱受影响者的防御。查明连守护者是否也被感染，探询他们不可能做出之事。")
zh(8905,"普通臂铠换作上等装备，需取冬泉谷熊与霜刃豹之血。其特性对提升者至关重要，另需些许酬劳。")
zh(8906,"普通臂铠换作上等装备，需取冬泉谷熊与霜刃豹之血。其特性对提升者至关重要，另需些许酬劳。")
zh(8907,"普通臂铠换作上等装备，需取冬泉谷熊与霜刃豹之血。其特性对提升者至关重要，另需些许酬劳。")
zh(8908,"普通臂铠换作上等装备，需取冬泉谷熊与霜刃豹之血。其特性对提升者至关重要，另需些许酬劳。")
zh(8909,"普通臂铠换作上等装备，需取冬泉谷熊与霜刃豹之血。其特性对提升者至关重要，另需些许酬劳。")
zh(8910,"普通臂铠换作上等装备，需取冬泉谷熊与霜刃豹之血。其特性对提升者至关重要，另需些许酬劳。")
zh(8911,"将普通护腕升级为超强护腕，需取自冬泉谷熊与霜刃豹的鲜血。这些血液的特性，是施加改良者所必需，同时也要支付小额代价。")
zh(8912,"将普通护腕升级为超强护腕，需取自冬泉谷熊与霜刃豹的鲜血。这些血液的特性，是施加改良者所必需，同时也要支付小额代价。")
zh(8913,"希利苏斯的蜘蛛与蝎子，提供着用于改良护腕的毒液。收集足够样本，便可交换普通护腕与小额代价。")
zh(8914,"希利苏斯的蜘蛛与蝎子，提供着用于改良护腕的毒液。收集足够样本，便可交换普通护腕与小额代价。")
zh(8915,"希利苏斯的蜘蛛与蝎子，提供着用于改良护腕的毒液。收集足够样本，便可交换普通护腕与小额代价。")
zh(8916,"希利苏斯的蜘蛛与蝎子，提供着用于改良护腕的毒液。收集足够样本，便可交换普通护腕与小额代价。")
zh(8917,"希利苏斯的蜘蛛与蝎子，提供着用于改良护腕的毒液。收集足够样本，便可交换普通护腕与小额代价。")
zh(8918,"希利苏斯的蜘蛛与蝎子，提供着用于改良护腕的毒液。收集足够样本，便可交换普通护腕与小额代价。")
zh(8919,"希利苏斯的蜘蛛与蝎子，为锻造超强护腕之人提供毒液。采集足够样本，便可与普通护腕及报酬一同交换。")
zh(8920,"希利苏斯的蜘蛛与蝎子，为锻造超强护腕之人提供毒液。采集足够样本，便可与普通护腕及报酬一同交换。")
zh(8921,"莫克瓦尔需要打造一台提炼亡者灵体的蒸馏器。然而资金与人力匮乏，需魔法组件、油料与火山灰作为滤芯。")
zh(8922,"最后的希望，是与安泰恩的幽灵对话。加基森的工程师称可制造所需机器，并以收集的血液作为报酬。")
zh(8923,"联系安泰恩或能揭开莫克瓦尔的困境。这些毒液样本是为莫克瓦尔准备的，他的超自然计划，或许能让人与亡者对话。")
zh(8924,"气候改变灵体物质的质地。炼金师需从希利苏斯、冬泉谷与东瘟疫之地收集灵体精华，以获取不同种类。")
zh(8925,"灵体需稳定、便携的能量来源才能维持活性。博克之心形成的岩浆核心，或许能为亡灵探测器提供持续的热能。")
zh(8926,"将莫克瓦尔打造的装置交出，你已履行协议。所赠报酬，将你的腰带与手套替换为超强装备，以激励你继续协助。")
zh(8927,"你的援手已换得足够的信任，还能再换一回装备。腰带与手套眼下便可改得更好；余下的几件，要看你是否还肯接着出力。")
zh(8928,"核心的能量需要一根能引导而不融化它的杆状物。冬泉谷的一只地精出售合适的零件，而穆克斯希望维持先前报价。")
zh(8929,"安泰恩·哈尔蒙被认为是在试图进入斯坦索姆时丧生。在那测试地精的发明，或许能与他的亡灵之灵沟通，得知他所知的一切。")
zh(8930,"安泰恩·哈尔蒙据称是被斯坦索姆的亡灵在城门附近所杀。使用探测器测试此处，或可验证机器是否能与逝者建立你所需的联系。")
zh(8931,"完成穆克斯所造设备的交付，即可获得约定的报酬。一副普通的腰带与手套，可换得因你的协助而提供的升级装备。")
zh(8932,"完成穆克斯所造设备的交付，即可获得约定的报酬。一副普通的腰带与手套，可换得因你的协助而提供的升级装备。")
zh(8933,"穆克斯的设备已交付，你的协助理应获得回报。手套与腰带可换得更优装备，以激励你继续协助。")
zh(8934,"交付穆克斯所造设备已履行你的协议部分。所获报酬将替换你的腰带与手套，以鼓励你持续协助。")
zh(8935,"将穆克斯打造的装置送至指定地点，你已履行了协议中的一环。所赠奖励将替换你的腰带与手套，以激励你持续协助。")
zh(8936,"将穆克斯打造的装置送至指定地点，你已履行了协议中的一环。所赠奖励将替换你的腰带与手套，以激励你持续协助。")
zh(8937,"穆克斯的装置已送达，你的协助理应获得回报。腰带与护腕可换取更精良的装备，以鼓励你继续提供帮助。")
zh(8938,"你的援手已换得足够的信任，还能再换一回装备。腰带与手套眼下便可改得更好；余下的几件，要看你是否还肯接着出力。")
zh(8939,"你的援手已换得足够的信任，还能再换一回装备。腰带与手套眼下便可改得更好；余下的几件，要看你是否还肯接着出力。")
zh(8940,"你的援手已换得足够的信任，还能再换一回装备。腰带与手套眼下便可改得更好；余下的几件，要看你是否还肯接着出力。")
zh(8941,"你的援手已换得足够的信任，还能再换一回装备。腰带与手套眼下便可改得更好；余下的几件，要看你是否还肯接着出力。")
zh(8942,"你所建立的信任已具实体回报。腰带与护腕可随时置换，其余部件则需你持续解决共同困境方可获得。")
zh(8943,"你的援手已换得足够的信任，还能再换一回装备。腰带与手套眼下便可改得更好；余下的几件，要看你是否还肯接着出力。")
zh(8944,"你的协助赢得的信任值得实体回报。腰带与护手现已可交换，其余部件的获取则取决于继续解决共同困境。")
zh(8945,"安泰恩愿提供情报，但妻子被囚更迫在眉睫。他需要你完成他未能做到的营救，将伊思达从瑞文戴尔男爵的势力下解救出来。")
zh(8946,"伊思达希望安泰恩知她安然无恙，并停止滞留此世。她将用怀表作为证据，证明那位为救她而死的丈夫。")
zh(8947,"塞尔德林收到瓦尔塔拉克徽章的一块，却激烈拒绝归还。他新的人生作为角斗士，需筹备一场战斗并夺回碎片。")
zh(8948,"旗帜上绘有塞尔德林家族的徽记，只为引发回应。法尔林知晓能强化挑衅的附魔，可迫使角斗士应战。")
zh(8949,"法尔林知晓所需附魔，但首先要求偿还他对食人魔的仇恨。他们的珠子将作为证据，他才会同意商议你的请求。")
zh(8950,"引发挑衅的附魔对法尔林而言简单易行，但其材料稀有难得。需幽灵之灵、符文与璀璨碎片，方能将魔法施加于旗帜。")
zh(8951,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8952,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8953,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8954,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8955,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8956,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8957,"瓦尔塔拉克的灵魂被护符分割，引发无法逆转的诅咒。莫克瓦尔需知伯德雷可助他寻得残缺之物，唯有重聚方能终结这灾厄。")
zh(8958,"瓦尔塔拉克的护符被分割，释放出与他灵魂相连的诅咒。德莉亚娜需知伯德雷可助她寻得残缺之物，唯有重聚方能终结这魔咒。")
zh(8959,"瓦塔拉克的项链碎片被分割后，释放出与他灵魂相连的诅咒。德莉亚娜必须知晓伯德雷能协助寻获残缺部分，唯有将它们重聚，才能终结这道魔咒。")
zh(8960,"伯德雷重返黑石山，踏入黑石塔后便再未归来。寻找剩余碎片时，最好带上幽灵探测器，以防最坏的情况已然发生。")
zh(8961,"召唤瓦塔拉克需找回另外两枚项链碎片。首先，需从三位火焰贵族手中获取特殊炭火，以及一个圣洁火盆，方能筹备这次尝试。")
zh(8962,"火盆需要一个足够强烈的焦点，才能吸引莫尔·灰蹄的灵体。他那些被异种蝎所杀的德鲁伊同伴的遗骸，或许能提供那份个人的联结。")
zh(8963,"召唤伊萨莉恩需一个与她童年在星风村相连的焦点。一个被冬泉谷巨人的盗贼夺走的村落遗物，或可将火盆与她的灵体相联。")
zh(8964,"亚雷恩与索托斯曾渴望成为血色骑士。一把来自提尔之手的执政官之剑，可作为焦点，引导这对兄妹穿越火盆。")
zh(8965,"库尔莫克乐于召唤赎罪岛被放逐者的亡魂。他们的灰烬，或许能成为火盆所需的焦点，吸引那位昔日的同伴。")
zh(8966,"莫尔·灰蹄坠入黑石塔下层时，曾携带瓦塔拉克项链的腐化碎片。他的被捕与遇害，直接引导搜寻方向——那正是他逃亡终结之地。")
zh(8967,"伊萨莉恩为私事与求知前往厄运之槌，取走了一枚符文护符。她在艾尔德雷哈尔神龛遭伏击的消息，指引着寻找遗失碎片的方向。")
zh(8968,"亚雷恩与索托斯加入血色十字军时，取走了符文护符。他们在入会仪式中丧生，如今唯有寻至当年失败之处，方能寻回碎片。")
zh(8969,"库尔莫克投身亡灵法术后，将符文护符带往通灵学院。鬼灵刺客在他死前取走了碎片，如今唯有与那位已故的同伴联络，方能寻回。")
zh(8970,"伯德雷精通占卜之术，能寻得最后一枚碎片与伴随的灵体。他需从阿卡兹的娜迦处取得血藻，方能施展那场魔法搜寻。")
zh(8977,"穆克斯已完成德尔丽安娜所需的幽灵探测器，助其尝试联络安泰恩·哈尔蒙。将装置送往铁炉堡，工程学徒还请你代为推荐他的服务。")
zh(8978,"穆克斯已完成莫克瓦尔所需的幽灵探测器，助其尝试联络安泰恩·哈尔蒙。将装置送往奥格瑞玛，工程学徒还请你代为推荐他的服务。")
zh(8979,"芬斯塔怀疑时尚香氛正借炼金术改变人心。将样本送至金格，可验证这些气息是否解释了城市中蔓延的异常行为。")
zh(8980,"金格在香氛中发现了用于精神控制药剂的成分。混合物的复杂程度指向一位炼金术大师，报告此事的严重性势在必行。")
zh(8981,"这次拜访是一次表达敬意的机会，将爱与崇敬献给一位领袖。这场邂逅的核心，是通过你随身携带的礼物，传递这份情感。")
zh(8982,"卡崔娜从旅店老板诺曼处买下了那瓶可疑的香水。与他交谈，能顺着供应链追溯，找出分销这些香水的幕后人物。")
zh(8983,"诺曼指认玛拉·雷尼克是向他出售香水的商人。她计划交付给裁缝的货物，为调查这款异常受欢迎的产品提供了线索。")
zh(8984,"香水的线索最终指向了拉文霍德外隐居的药剂师斯塔弗隆·雷伦特。调查他，或可验证其产品是否暗中削弱了城市的防御。")
zh(8985,"最后一块碎片已寻获，但召唤伊萨莉恩还需唤醒她的童年记忆。星风村的遗迹若在巨人的手中，或可为火盆建立必要的联系。")
zh(8986,"找到碎片并不足以令莫尔·灰蹄现身。火盆需要他那些被异种蝎杀害的德鲁伊同伴的遗骸，以塑造与他灵魂相连的焦点。")
zh(8987,"火盆需要一个具象的焦点，才能召唤亚雷恩与索托斯。他们对血色骑士的渴望，使提尔之手的百夫长之剑成为合宜之选。")
zh(8988,"召唤库尔莫克，需将火盆与他昔日的亡灵术连接。从赎罪岛放逐者遗骸中取来的灰烬，能唤起他曾经乐于召唤的灵魂。")
zh(8989,"莫尔·灰蹄坠入黑石塔底层时，随身携带了瓦塔拉克公爵项链的残片。他的被捕与遇害，将搜寻方向引向他逃亡终结之处。")
zh(8990,"伊萨莉恩为私心与探究秘密，将项链残片带往厄运之槌。她在伊德雷塔尔神龛遭伏击的消息，指引着失踪残片的下落。")
zh(8991,"亚雷恩与索托斯在寻求血色十字军入会时，仍保有瓦塔拉克公爵项链的残片。他们在入会仪式中的死亡，暗示了那片残片的去向。")
zh(8992,"库尔莫克在通灵学院被鬼灵刺客击杀时，手中仍握着项链残片。再次召唤他，只为寻回他离队时带走的那部分。")
zh(8993,"这次拜访，是献上爱与敬意的良机。邂逅的核心，是你所携之物所传达的情谊。")
zh(8994,"火盆仍需黑石塔兽人臂铠中的稀有金属。搭配超级能量合剂，方能调和召唤瓦塔拉克。")
zh(8995,"瓦塔拉克必须在生前居所被召唤，待他重获实体后加以击败。随后将项链置于其身，试图重聚被窃取的灵体。")
zh(8996,"瓦塔拉克承认其余被窃取的灵体已归位。他允许你告知昔日敌人他们已安好，然而他的警告，使这份安全仍存变数。")
zh(8997,"伯德雷在你的协助后道别，并请你返回铁炉堡的德莉亚娜处。汇报事件将把期待的消息带回最初发起行动的人。")
zh(8998,"伯德雷仍可随时交谈，但报告须送回莫克瓦尔。返回奥格瑞玛则会告知他解决困境期间发生的事。")
zh(8999,"你的介入缓解了困境相关人员的忧虑。他们的感激如今化作奖励，待听完你努力的叙述后方才呈现。")
