zh(9015,"旗帜必须立于律法之环的中心，其挑衅之意旨在迫使对手交战，以夺回安泰恩所需之物。")
zh(9016,"瓦尔萨拉克的灵魂被符咒分割，引发诅咒，唯有重聚方能终结。莫克瓦尔需知伯德雷可协助寻得残缺之物。")
