zh(9021,"瓦尔萨拉克的灵魂被项链分裂，引发诅咒，唯有重聚方能终结。莫克瓦尔需知伯德雷可协助寻得残缺之物。")
zh(9022,"瓦尔萨拉克的灵魂被项链分裂，引发诅咒，唯有重聚方能终结。莫克瓦尔需知伯德雷可协助寻得残缺之物。")
zh(9023,"拉文霍德欲寻取自祖尔格拉布与安其拉生物的毒液，以制备特别毒药。库林纳克斯与高阶祭司温诺希斯或可提供所需毒囊。")
zh(9024,"阿瑞斯坦怀疑新香料影响守卫的职责表现。取样送至摩根·匹斯特，或可验证是否某种炼金混合物令其神志不清。")
zh(9025,"摩根发现爱之药水与心智药剂的成分，印证阿瑞斯坦的猜测，亦需报告香料中所含之物。")
zh(9026,"镶金玫瑰近日访客众多，包括守卫。若艾莉森出售香料，便可追溯其来源，协助追踪可疑物品。")
zh(9027,"艾莉森从埃文特·索里萨姆手里买过香料，也想知道是不是出了岔子。原定送往裁缝那儿的一批货，兴许能顺着摸到那商人的下落。")
zh(9028,"埃文特否认有害意图，并指认斯塔弗隆·雷伦特为供货商。其地精中间人提供的情报，指向隐居于拉文霍德山丘的药剂师。")
zh(9029,"对可疑香气的调查，最终引向一口芬芳四溢的大锅。探查它，是追踪那些与城市诡异痴情相连的香料源头的继续。")
zh(9030,"贪婪撕裂了封存瓦塔拉克灵魂的项链，终结诅咒需重聚碎片。德莉亚娜需知伯德雷能助她寻回余下残片。")
zh(9032,"这枚徽章封存着瓦塔拉克的灵魂，解释了其强大诅咒的由来。伯德雷在准备返回黑石塔前神秘消失，因担忧他可能已死，你的联系人建议使用幽灵探测器寻找他。")
zh(9033,"天灾军团的威胁并未随上次战争终结，克尔苏加德正集结力量发动新一轮攻势。在纳克萨玛斯战斗，将证明你愿协助拂晓与银色北伐军对抗它的决心。")
zh(9034,"在纳克萨玛斯与天灾军团交战，可获得亵渎的铠甲与金属碎片。收集这些材料，匠人便能打造如英雄所穿般守护你的护甲。")
zh(9036,"在纳克萨玛斯与天灾军团交战，可获得亵渎的铠甲与金属碎片。收集这些材料，匠人便能打造如英雄所穿般守护你的护甲。")
