zh(9039,"在纳克萨玛斯与天灾军团的战斗中，可获得亵渎的盔甲与板甲碎片。收集这些材料，匠人便能打造出英雄们曾披挂的守护之铠。")
zh(9040,"在纳克萨玛斯与天灾军团的战斗中，可获得亵渎的盔甲与板甲碎片。收集这些材料，匠人便能打造出英雄们曾披挂的守护之铠。")
