zh(9051,"魔暴龙威胁着火山口的生存，击杀它们只会让其他同类占据空缺。托瓦·霜心想尝试一种能安抚它们的毒素，只是其效果尚不可知。")
zh(9052,"托瓦·霜心想要一种能安抚巨兽而不致其死亡的毒素。他需要血帽菌与格里什钉刺，这些材料他托付给德鲁伊的洞察。")
zh(9053,"第一剂毒素对那生物太过微弱。托瓦·霜心需要从阿塔哈卡克神殿守护者手中获取腐烂藤蔓，以调制更强的混合剂，而那处地方最适合与同伴一同探索。")
zh(9054,"地穴恶魔的甲壳提供了一种轻盈致命的材料。将它们的碎片与纳克萨玛斯的亵渎魔法残片结合，或许能尝试打造兼具两者特性的防护装备。")
