zh(9111,"蒙托耶神父追寻那些在战场上被屠杀、尊严尽失者的亵渎圣袍。他需要这些残骸与净化药剂，为你打造新的护甲。")
zh(9112,"蒙托耶神父追寻那些在战场上被屠杀、尊严尽失者的亵渎圣袍。他需要这些残骸与净化药剂，为你打造新的护甲。")
zh(9113,"蒙托耶神父追寻那些在战场上被屠杀、尊严尽失者的亵渎圣袍。他需要这些残骸与净化药剂，为你打造新的护甲。")
