zh(9117,"蒙托耶追寻那些在战场上被杀害、尊严尽失者的亵渎衣袍。他需要这些残骸与净化材料，为你打造新的护甲。")
zh(9118,"蒙托耶追寻那些在战场上被杀害、尊严尽失者的亵渎衣袍。他需要这些残骸与净化材料，为你打造新的护甲。")
zh(9120,"封印瓶保有克尔苏加德重归人形的可能性。与其摧毁它，不如将其送往圣光之愿号，或许有人愿为它付出代价。")
zh(9121,"肯瑞托魔法的一种变体可绕过纳克萨玛斯的结界。此过程代价高昂，而你与拂晓的声望尚不足以获得更优的折扣。")
zh(9122,"进入纳克萨玛斯需避开传送门的结界。你对拂晓的忠诚已足以部分覆盖必要附魔的费用。")
zh(9123,"传送门周围的结界阻止了进入纳克萨玛斯。一种改良的肯瑞托法术可让你隐匿于其中，而你对银色黎明的奉献足以免除此程序的费用。")
zh(9124,"雷奥普德为进入纳克萨玛斯的勇士打造地穴追猎者护甲，却屡缺地穴恶魔的残肢。他以徽记换取收集这些材料的协助。")
zh(9125,"雷奥普德验过第一批货，往后的零件便肯照收。每多送一捆，便多换一枚徽记——供养他打造护甲，做的还是同一桩营生。")
zh(9126,"唐·朱利奥的骨镰纹路吞噬了大量白骨碎片。收集这些碎片不仅能为天灾军团补给打造护甲的材料，还能削弱那些提供这些残骸的敌人。")
zh(9127,"洛汗仍需白骨碎片来完成他的锻造。你可以将收集到的多余碎片交给他，换取一枚徽记，以维持护甲材料的供应。")
zh(9128,"收集元素核心可换取军需官提供的徽记。世界各地的元素生物正为这项补给任务提供所需材料。")
zh(9129,"元素核心被用来打造霜火长袍，这是在纳克萨玛斯中战斗的法师们所穿戴的护甲。进一步的补给能持续这项工作，并换取更多徽记以表彰贡献。")
zh(9131,"为冠军打造无畏铠甲需要大量黑铁碎片。获取这些材料能支持持续生产，并获得补给工作的报酬。")
zh(9132,"黑铁碎片仍是无畏铠甲不可或缺的原料。每一批碎片都能换取一枚徽记，以维持打造冠军装备所需的供应。")
zh(9136,"打造踏梦者护甲必须使用蛮荒之叶，即便穿戴者提供了其他材料。收集它们能维持这项工作，并换取拂晓或十字军的徽记。")
zh(9137,"每一批蛮荒之叶都能换取拂晓或十字军的徽记。这项选择让补给报酬能用于军需官提供的奖励。")
zh(9141,"前线锻造合约吸引着全球工匠前来应征。要获得合约，你需出示一枚勇气徽章，证明你愿为这场斗争而战。")
zh(9142,"工匠文书的获取仍需勇气徽章。交出徽章后，你将获得另一份工作令，以表彰你在战场上的贡献。")
zh(9153,"漂浮的浮空城威胁着部落与联盟的领土。它们的魔法法阵依赖于防御，而击败周围的军团便是突破防线的关键。")
zh(9154,"天灾军团以空前之势回归，银色黎明正招募能征善战的守卫者。将文件交予圣光之愿号的记录员，便可加入这场共同抵抗。")
zh(9165,"商队一路得你相助，抵御天灾，终于抵达终点。钱伯斯须在安全通行文书上落笔，向梅兹具明这趟护送已了；迪迪尔却在一旁提醒你，治安官的脾气可不好惹。")
zh(9178,"银色黎明的合约BS-091要求120枚致密平衡石。石锤将在圣光之愿号接收货物，以你选择的徽章作为报酬。")
zh(9179,"银色黎明的合约BS-428要求3件君王板甲护胸。石锤将在圣光之愿号接收货物，以你选择的徽章作为报酬。")
zh(9181,"银色黎明的合约BS-697要求3把火山战锤。石锤将在圣光之愿号接收货物，以你选择的徽章作为报酬。")
zh(9182,"银色黎明的合约BS-6020要求交付三把巨型瑟银战斧。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9183,"银色黎明的合约BS-80要求交付三枚辐光头饰。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9184,"银色黎明的合约LW-971要求交付十枚邪恶皮甲头环。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9185,"银色黎明的合约LW-448要求交付二十五套毛皮护甲片。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9186,"银色黎明的合约LW-736要求交付九条邪恶皮甲腰带。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9187,"银色黎明的合约LW-8485要求交付四条符文皮甲短裤。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9188,"银色黎明的合约TR-95要求交付六条亮布短裤。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9190,"银色黎明的合约TR-635要求交付八双符文布靴。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽记。")
zh(9191,"银色黎明的委托TR-9999需要8个符文布背包。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9194,"银色黎明的委托TR-7229需要8件符文布袍。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9195,"银色黎明的委托EN-11需要20枚地精工兵炸药。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9196,"银色黎明的委托EN-7需要20枚瑟银手榴弹。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9197,"银色黎明的委托EN-0需要4只侏儒作战小鸡。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9198,"银色黎明的委托EN-558需要14个瑟银管。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9200,"银色黎明的委托AL-473需要10瓶特效法力药水。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9201,"银色黎明的委托AL-1420需要15瓶强效奥术防护药水。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9202,"银色黎明的合约AL-169110要求交付二十瓶特效治疗药水。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9203,"银色黎明的合约AL-90要求交付一瓶化石合剂。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9204,"银色黎明的合约FS-5要求交付四十条石鳞鳗。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9205,"银色黎明的合约FS-12要求交付三十条板鳞鱼。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9206,"银色黎明的合约FS-9要求交付三十条电鳗。布鲁斯·石锤将在圣光之愿号接收货物，报酬可选一枚徽章。")
zh(9208,"赞扎看不上精灵的附魔，只肯以巨魔世代相传的庇护相授。他要你先毁掉一件精灵打造的奥术造物，才肯赐下野性戒卫。")
zh(9209,"赞扎蔑视精灵的附魔，转而以远古巨魔的庇护取而代之。他要求摧毁一件精灵打造的奥术法器，方能授予野性戒卫之位。")
zh(9210,"赞扎蔑视精灵的附魔，转而以远古巨魔的庇护取而代之。他要求摧毁一件精灵打造的奥术法器，方能授予野性戒卫之位。")
zh(9211,"寒冰戒卫为部分装备镀上一层防护魔法，能抵御冰系生物的侵袭。然而愤怒者玛塔乌斯索取的代价毫不妥协。")
zh(9213,"愤怒者玛塔乌斯将暗影戒卫作为另一层防护魔法赠予装备，与寒冰戒卫相辅相成，但需付出高昂代价。")
zh(9221,"拂晓与北伐军的徽记可以换购装备，只是在拂晓名望浅薄的人，得多付一笔重金。军需官劝你先与那边结些情分，再谈买卖。")
zh(9222,"更强大的装备可凭徽记购得，但黎明对新盟友收取格外高昂的附加费。赢得更深信任或可减轻这笔开销。")
zh(9223,"享有声誉者可凭徽记换取黎明装备，但附加费依旧不菲。军需官建议先赢得更深信任再动用资源。")
zh(9224,"即便被黎明所敬重，顶级装备依旧昂贵。徽记可购得，但更稳固的关系或能减免部分附加费。")
zh(9225,"黎明为受尊崇的盟友提供强力装备，代价依旧高昂。以徽记交换时，需权衡是否等待更稳固的关系。")
zh(9226,"被尊为盟友者，黎明装备已具合理价格。为正义而战所得的徽记，如今可换取军需官提供的资源。")
zh(9227,"黎明的最高信任赋予你购置装备的折扣。交换徽记象征着这份关系，也意味着你已为麾下将士证明了自身价值。")
zh(9228,"最强大的装备，给予持有黎明最高信任者的折扣最为丰厚。你的徽记可在这些有利条件下使用，以表彰这段关系。")
zh(9229,"莫格莱尼的死让拉玛兰迪燃起了仇恨，驱使他潜入纳克萨玛斯复仇。他再未归来，有人必须查明这位旧弟子的下落。")
zh(9230,"拉玛兰迪的戒指由天灾建筑内的符文熔铸而成。重铸它需要更多冰冻符文与其它材料，方能恢复往昔品质。")
zh(9232,"维尔海姆对你在纳克萨玛斯的胜算存疑，却仍决定协助完成奥玛里恩留下的那条纹路。若你能提供材料，他能打造多种版本的那条裤子。")
zh(9233,"奥玛里恩的手册中记载了其余配方，还有一封致维尔海姆的信件。将它送达，便将他本该使用的知识交予你手。")
zh(9234,"奥玛里恩的配方如今让维尔海姆得以打造破冰护手。这份重拾的知识化作委托，需材料与报酬方能完成。")
zh(9235,"维尔海姆可借助奥玛里恩的知识打造破冰护腕，而你曾协助重拾这份知识。他需要材料与制作报酬，才能完成这份新委托。")
zh(9236,"奥玛里恩的知识让破冰胸甲得以打造。维尔海姆·斯图恩愿亲自操刀，只要你收集材料并支付他的工费。")
zh(9237,"维尔海姆·斯图恩能用奥玛里恩的配方打造冰川披风。你协助找回的这份知识，如今可用来委托制作，只需提供材料与工费。")
zh(9238,"奥玛里恩的知识让维尔海姆·斯图恩得以打造冰川护腕。这份重获的技艺，如今化作你提供的材料与工费所换来的装备。")
zh(9239,"维尔海姆·斯图恩能用奥玛里恩的配方打造冰川手套。提供材料与工费，便可将这份知识转化为新的装备。")
zh(9240,"找回奥玛里恩的配方，冰川外衣便可委托打造。维尔海姆·斯图恩愿以材料与工费为代价，将这份传承的知识付诸实践。")
zh(9241,"维尔海姆·斯图恩能用奥玛里恩的配方打造北极护腕，这多亏你协助找回了配方。材料与工费将这份知识转化为新的装备。")
zh(9242,"奥玛里恩的配方让北极手套得以打造。维尔海姆·斯图恩愿将这份知识用于委托，只要你提供材料并支付工费。")
zh(9243,"多亏奥玛里恩，维尔海姆·斯图恩如今知晓如何打造北极外套。他的邀约让你得以用收集的材料与工费，将这份重获的知识化为装备。")
zh(9244,"寒鳞护腕属于大工匠奥玛里恩留下的知识遗产，维尔海姆·斯图恩曾受其惠。你的协助使他得以用材料与报酬打造这副护腕。")
zh(9245,"维尔海姆·斯图恩能运用奥玛里恩的配方制作寒鳞护手。集齐材料并支付工钱，便能将这份复苏的知识付诸实践。")
zh(9246,"寒鳞胸甲是另一件受益于奥玛里恩知识的委托之作。维尔海姆需要材料与报酬，才能完成这项如今能提供的工艺。")
zh(9247,"银色黎明再度召唤那些曾为它效力之人。在最危急的时刻，圣光之愿号的记录员迎来了愿意再度相助的盟友。")
zh(9248,"击败深渊魔议会领主的证据可换取奖赏。这份礼物象征着胜利，也是一把助你对抗基尔加迪的利器。")
zh(9249,"四十张奖券可换得蒸汽车控制器的图纸。这种交换让工程学的奥秘透过奖券奖励得以流传。")
zh(9250,"埃提耶什已近完整，但两端仍缺，且仍受萨格拉斯邪恶之力影响。你需要找到缺失之物，将这股腐化驱逐出法杖。")
zh(9251,"克尔苏加德掌控着埃提耶什的一部分，也觊觎你所携带的残片。布莱恩曾造访安其拉，基地仍留于彼处，重聚法杖需找回两段。")
zh(9257,"一个恶魔实体操控着权杖，必须将其驱逐。将它带到斯坦索姆的圣洁之地，或许能尝试释放这存在，并直面腐蚀它的邪恶力量。")
zh(9259,"雷维格兹的宽恕需要假意背叛血帆。一位前海盗提议用假绑带代替杀害同袍，但你与血帆的合作态度，将影响他们对你的看法。")
zh(9260,"天灾军团已驻扎在城门前，符文法阵正共享着他们的诡异能量。调查这些标记的同时削弱入侵者，旨在理解并应对这威胁。")
zh(9261,"天灾军团已驻扎在城门前，符文法阵正共享着他们的诡异能量。调查这些标记的同时削弱入侵者，旨在理解并应对这威胁。")
