zh(9265,"天灾军团已在幽暗城外扎营。研究他们的符文法阵，或许能窥见其备战意图，同时协助遏制城中即时的威胁。")
zh(9266,"地精愿以协助对抗冬泉谷的寒意，修复受损的关系。符文布与煤炭可为新来者带来温暖，换得一份有利的推荐。")
zh(9267,"那些在血帆遭遇中受伤的冒险者，有机会与棘齿城和解。布料可制绷带，药剂瓶可炼药水，助那些被船只带来的人们。")
zh(9268,"塔纳利斯的地精亟需帆布与火炮对抗血帆。提供魔法织物与强效助熔剂，是守护他们信任的第一步。")
zh(9269,"恶魔实体操控着法杖，必须被驱逐。将其带往斯坦索姆的圣洁之地，尝试释放其中的生灵，直面腐蚀它的邪恶之力。")
zh(9270,"恶魔实体操控着法杖，必须被驱逐。将其带往斯坦索姆的圣洁之地，尝试释放其中的生灵，直面腐蚀它的邪恶之力。")
zh(9271,"恶魔实体操控着法杖，必须被驱逐。将其带往斯坦索姆的圣洁之地，尝试释放其中的生灵，直面腐蚀它的邪恶之力。")
zh(9272,"老水手们要求合适的衣裳才肯接纳你的陪伴。红眼本在风暴中失利后留下的衣物，如今可由你骄傲地穿戴。")
zh(9273,"宠物兑换券可换得北极熊项圈。这项优惠将你手上的凭证，转化为对应救赎的专属奖励。")
zh(9292,"一具憎恶的残骸中，仍闪烁着腐化能量的碎晶。将这发现带往暴风城外的奥林中尉处。")
zh(9295,"从天灾仆从身上寻得的书信，透露出长期滞留亡灵之地的痕迹。送往圣光之愿礼拜堂，或能找到能解读它的人。")
zh(9299,"从天灾仆从身上寻得的书信，透露出长期滞留亡灵之地的痕迹。送往圣光之愿礼拜堂，或能找到能解读它的人。")
zh(9300,"从天灾仆从身上寻得的书信，透露出长期滞留亡灵之地的痕迹。送往圣光之愿礼拜堂，或能找到能解读它的人。")
zh(9301,"从天灾仆从身上寻得的书信，透露出长期滞留亡灵之地的痕迹。送往圣光之愿礼拜堂，或能找到能解读它的人。")
zh(9302,"从天灾仆从身上寻得的书信，透露出长期滞留亡灵之地的痕迹。送往圣光之愿礼拜堂，或能找到能解读它的人。")
zh(9304,"从天灾仆从身上寻得的书信，透露出长期滞留亡灵之地的痕迹。送往圣光之愿礼拜堂，或能找到能解读它的人。")
zh(9310,"一具亡灵的残骸中，仍散发微弱腐化能量的晶石。将这发现带往幽暗城庭院的卢卡中尉处。")
zh(9317,"天灾入侵者留下的符文可换取神圣磨刀石。银色黎明提供此资源，助你对抗巫妖王的爪牙。")
zh(9318,"银色黎明接受入侵者的死灵符文，换取神圣巫师之油。这项交易将敌人的残余化为你的战利品。")
zh(9319,"仲夏之火燃烧于最黑暗之处。探访斯坦索姆、通灵学院、厄运之槌与黑石塔的篝火，可见庆典的广度。")
zh(9320,"银色黎明的补给包含特效法力药水，以死灵符文换取。十五枚回收的符文，可换得一瓶药水。")
zh(9321,"银色黎明的补给包含特效治疗药水，以死灵符文换取。十五枚回收的符文，可换得一瓶药水。")
zh(9322,"火焰节的蓝焰也蔓延至卡利姆多的大地。探访其蓝色篝火，可见庆典从冬泉谷的寒意，至南方的沙漠与丛林。")
zh(9323,"最明亮的蓝色火焰，是东部王国各处庆典的标志。你要循着它们走遍四方，去见识这场燃遍诸国的节日。")
zh(9324,"从奥格瑞玛偷来的火焰释放出你未曾认知的力量。向博学者请教，方能理解那能量与温暖的来源。")
zh(9325,"雷霆崖萨满祭司的火焰点燃你，带来陌生的温暖。拂晓诗人或许能解释这团火中蕴藏的力量。")
zh(9326,"来自幽暗城废墟的火焰释放出你从未体验过的能量。将它交给拂晓诗人，或许能找到这团火的真相。")
zh(9330,"暴风城之心被窃取的火焰散发出充满未知力量的温暖。诗人或许能为你揭示这火焰的意义。")
zh(9331,"从铁炉堡核心窃取的火焰蕴含着你无法理解的力量。向诗人请教，或许能揭开这温暖背后的秘密。")
zh(9332,"从泰达希尔海岸夺来的火焰包围着你，带着陌生的温暖与能量。诗人或许能解释这团火的本质。")
zh(9333,"银色黎明以手套换取你的死灵符文，以表彰你的贡献，并提供战斗时的防护选择。")
zh(9334,"从入侵者手中夺回的死灵符文可换取神圣巫师之油。银色黎明将你的贡献转化为新的战斗资源。")
zh(9335,"拂晓提供神圣磨刀石，用于对抗天灾军团的死灵符文。这物资旨在支援对抗巫妖王的战斗。")
zh(9336,"银色黎明的补给中有特效治疗药水，可凭死灵符文换取。此交易允许你以十五枚回收的符文，换取其中一瓶药水。")
zh(9337,"银色黎明的补给中有特效法力药水，可凭死灵符文换取。此交易允许你以十五枚回收的符文，换取其中一瓶药水。")
zh(9338,"塞纳里奥徽章即便无需装备，仍具价值，因其象征信任。将其呈上，意味着你已超越寻常职责，为法阵效力。")
zh(9339,"从暴风城心脏偷来的火焰，蕴含陌生而强大的能量。将其交给懂得庆典之火的人，或许能揭开这股力量的真相。")
zh(9341,"银色黎明认可你的贡献，赠予你的披风。这布料象征着它对盟友的接纳与欢迎。")
zh(9343,"银色黎明认可你的贡献，赠予你的披风。这布料象征着它对盟友的接纳与欢迎。")
zh(9353,"夏日礼包兑换券可换得夏日礼包。将它呈上，便可领取附带的奖励。")
zh(9362,"占卜术锁定了克雷利安所持的魔法源。因寻觅者无法离开塔楼，需协助夺回被娜迦军阀守护的虹彩贝壳。")
zh(9364,"虹彩贝壳能暂时将恶鞭海妖分裂成多个复制品。击败这些克隆体可收集其精魄，验证研究中发现的应用。")
zh(9365,"一缕暴风城之心的火焰，蕴含陌生而炽热的力量。将其交给懂得庆典之火的人，或许能揭开这股能量的奥秘。")
zh(9367,"仲夏时节，火焰守护者须让各主城的篝火长明不熄。眼下还没有人逐一回报各处火堆的光景——你走这一趟，正好替他们验一验炉火还暖不暖。")
zh(9368,"仲夏时节，火焰守护者须让各主城的篝火长明不熄。眼下还没有人逐一回报各处火堆的光景——你走这一趟，正好替他们验一验炉火还暖不暖。")
zh(9378,"传送门周围的结界封锁了纳克萨玛斯。一套改良的肯瑞托法术可让你避开它们，而你对银色黎明的奉献，足以免除这项手续的代价。")
zh(9386,"搜寻篝火的行动仍在危险之地持续，如斯坦索姆与通灵学院。重访那些火堆，既是加入庆典的机会，也是旅程的奖赏。")
zh(9388,"庆典的绿色火焰极易熄灭，故需持续照看。请检查卡利姆多的火堆，协助火焰守护者延续这节日的光辉。")
zh(9389,"绿色火焰在火节中格外醒目，因其色彩与维持之难。请检查东部王国的火堆，让它们继续照亮庆典的每个角落。")
zh(9415,"布鲁沃尔元帅在等待新兵，而他的士兵却在沙漠中死去。向元帅报告，你将加入这支队伍，并接受关于希利苏斯危险的指示。")
zh(9416,"沙漠的损失削弱了基里卡的军力，而矮人则每日获得增援。向将军报告，你将协助维持对希利苏斯资源的争夺。")
zh(9419,"联盟低估了部落从希利苏斯夺取的资源。如今必须通过收集硅石并送往新行动指挥点，来弥补落后的差距。")
zh(9422,"部落在联盟察觉其价值前，已利用希利苏斯的晶石。如今需更多人手采集这些资源，以防敌对势力掌控矿脉。")
zh(9556,"守护瘟疫之地的塔楼值得嘉奖，但你必须先了解其中的悲剧。恢复斯坦索姆的水源，证明你的旅程，待胜利之时，方可面见洛丹伦法师。")
zh(9664,"联盟意图占领并重建旧洛丹伦的塔楼，作为新的据点。那东部的存在，旨在对占据西部土地的亡灵施加更大压力。")
zh(9665,"亡灵间谍发现了联盟在废弃塔楼建立据点的计划。你必须驱逐占据者，控制东部边境，阻止这种存在。")
zh(65593,"引诱夜魔，需一件盛满爱意的信物。占卜已指明艾薇琳娜与艾萨克：两人相隔万里，心却系在一处。凯伦丁要取这两颗心，才能备下召唤之仪。")
zh(65597,"凝聚的心脏可召唤夜魔并考验你制服它的能力。经历这场对峙后，须将它们归还凯伦丁，作为召唤仪式的一部分。")
zh(65601,"卡祖尔寻觅一件象征爱与忠诚的物件，以引诱夜魔。玛加尔思念他的伴侣克里尔格，或许会托你寻找某件珍贵之物；那失落的线索，正是甘鲁尔所需的诱饵。")
zh(65602,"一枚数千年前情侣拥有的木雕，仍存着他们爱情的联结。占卜之术认定它可作为引诱夜魔的材料；在灰谷寻回它，以供加科因的仪式使用。")
zh(65603,"这木雕能召唤并制服夜魔。这项训练考验你的掌控力，最终仍需将它归还加科因，由他引导你完成这阶段的磨炼。")
zh(65604,"甘鲁尔察觉丝巾中仍缠绕着爱意，意图借此引诱夜魔。于尼尔鲁的法阵中召唤它，展现你的战斗掌控力，切勿低估恶魔的抵抗。")
zh(65610,"克里尔格为保护灰谷平民而失踪，被定性为逃兵。有知他的人不愿接受这判决，托你前往他们常相会的湖畔寻觅。")
zh(76156,"博阿顿认为你潜藏着操控人心的天赋。他提供面具，助你潜入风险投资公司的矿场盗取物资，考验你的欺骗与分散守卫的能力。")
zh(76160,"波阿顿疑惑你的天赋是毒药还是伪装。北方的渡鸦栖息于有毒树脂的树木，碾碎它们掉落的果壳，可制成刀刃的药膏，另一次考验你的能力。")
zh(76240,"博顿仍坚信你暗藏天赋，想用更隐晦的方式激发它。他让你用匕首清理并剖开一条鱼，信任你自然行动，而非过度思虑。")
zh(78088,"一个阴森的球体引发恐惧，仿佛在你心中低语着恶魔的语言。即使圣骑士的训练也无法解释这现象，应寻找更熟悉卡利姆多的专家。")
zh(78089,"德尔格伦察觉球体中蕴含恶魔的黑暗，却无法理解它的目的。他需向暴风城的圣骑士求教，便派你去找凯瑟琳继续调查。")
zh(78090,"凯瑟琳无法解释这球体，只得转向令她教团不安的专家。尽管术士被官方排斥，但他们对恶魔的知识或许能为圣骑士提供答案。")
zh(78091,"厄苏拉愿研究球体，条件是换取用于黑石召唤仪式的特殊盐分。这笔交易延续调查，也确保了她视为珍贵的材料。")
zh(78092,"球体散发的意志甚至令厄苏拉难以承受。为摧毁那近乎无坚不摧的外壳，她提议使用玛诺洛斯的武器，并收集制造尝试所需的恶魔本质。")
zh(78093,"球体破碎后，碎片散落你脚下。德尔格伦需证明这危险之物已被摧毁，便将残骸交予他，以报告调查结果。")
zh(78124,"《纳萨拉斯年鉴，第七十四卷》必须送到欧文或加里昂手中。你寻找这本书的旅程，终将它送到为图书馆收集典籍的人手中。")
zh(78127,"《达拉然笔记》第二十三卷必须送到欧文或加里昂手中。你寻找这份文字的旅程，终将引它抵达那些为图书馆收集书籍的人手中。")
zh(78132,"阿尔诺索追寻一顶曾属于一位战死将领的头盔。据说那位指挥官的被折磨灵魂仍徘徊于他陨落之处，或许能指引他寻回缺失的碎片。")
zh(78133,"阿尔诺索追寻的盾牌，据称是在一次人类聚居地的突袭中被偷走。传言它落入了一位兽人战酋之手，或许能成为找回缺失碎片的线索。")
zh(78134,"那支长矛辗转易主，如今现身于非法军火交易之中。它的现任主人或许愿意交易，阿尔诺索需循着黑市的传闻找回缺失的碎片。")
zh(78142,"《巫术与幻术》一书必须送到欧文或加里昂手中。你寻找这份文字的旅程，终将引它抵达那些为图书馆收集书籍的人手中。")
zh(78143,"《梦游者秘录》一书必须送到欧文或加里昂手中。你寻找这份文字的旅程，终将引它抵达那些为图书馆收集书籍的人手中。")
zh(78145,"《魔法体系手册》一书必须送到欧文或加里昂手中。你寻找这份文字的旅程，终将引它抵达那些为图书馆收集书籍的人手中。")
zh(78146,"《高扎卷轴》一书必须送到欧文或加里昂手中。你寻找这份文字的旅程，终将引它抵达那些为图书馆收集书籍的人手中。")
zh(78147,"《解剖学罪行》一书需送达欧文或加里昂。你的追寻终将引它至那些为图书馆收集典籍之人之手。")
zh(78148,"《法师王符文》一书需送达欧文或加里昂。你的追寻终将引它至那些为图书馆收集典籍之人之手。")
zh(78149,"《大地之怒》一书需送达欧文或加里昂。你的追寻终将引它至那些为图书馆收集典籍之人之手。")
zh(78150,"你与图书馆的联系，仍需通过与欧文或加里昂的会面延续。你须与接收这些典籍之人当面交涉。")
zh(78261,"一位神秘委托人悬赏寻回席尔索斯之角，地点在影牙城堡。为保秘密，你须独自行动；维尼克斯或可协助开启大门，其余全凭你自身技艺。")
zh(78270,"寻回席尔索斯之角的任务要求你在影牙城堡内隐匿行动。委托人指引你前往石爪峰找维尼克斯，协助开启庭院大门，之后你须独自继续。")
zh(78307,"寻回席尔索命之角的任务终将引你回到C的情报传递点。一封致你的信随报酬一同送达，允许你无需直接面对神秘委托人即可领取约定补偿。")
zh(78676,"C欲取回布霍斯卡之眼，地点在血色修道院，且要求你独自潜入。若能伪装得体，或可减轻任务难度；将神器归还情报传递点，即可领取约定报酬。")
zh(78699,"返回C的情报传递点，可领取「布霍斯卡之眼」任务的报酬。一封附带的私人信件，既是对过往行动的回顾，也维系着与仍在关注你潜入能力之人的一线联系。")
zh(78823,"一幅粗略的素描描绘出一只令画师心生敬畏的猛禽。熟悉大型动物的专家或许能辨认出它，进而指出是何种生物激发了这幅画作，为你的调查提供线索。")
zh(79007,"一片焦黑的纸片躺在近日余烬旁，字迹模糊却隐约透露，未被焚毁的并非全无价值。唯一留下的线索，是关于另一片土地的神秘暗示。")
zh(79008,"余烬中残存的纸片因高温受损，其讯息暗示某物仍可寻回，并指向另一片土地，却尚未道明你该前往何方。")
zh(79091,"《大法师安东尼达斯：未删节自传》必须送达欧文或加里昂。你追寻这本著作的旅程，终将引领它抵达为图书馆收集书籍的人手中。")
zh(79092,"《塞欧克瑞图斯研究日记》必须送达欧文或加里昂。你追寻这本著作的旅程，终将引领它抵达为图书馆收集书籍的人手中。")
zh(79093,"《诺莫瑞根的鲁米：全集》必须送达欧文或加里昂。你追寻这本著作的旅程，终将引领它抵达为图书馆收集书籍的人手中。")
zh(79094,"《塔佐的教诲》必须送达欧文或加里昂。你追寻这本著作的旅程，终将引领它抵达为图书馆收集书籍的人手中。")
zh(79095,"《药剂师形而上学入门》必须送到欧文或加里昂手中。你寻找这本书的旅程，终将引领它抵达为图书馆收集典籍的人们手中。")
zh(79096,"《阿塔瑞克：关于奥术奇闻》必须送到欧文或加里昂手中。你寻找这本书的旅程，终将引领它抵达为图书馆收集典籍的人们手中。")
zh(79097,"《巴克坦：关于破坏性魔法》必须送到欧文或加里昂手中。你寻找这本书的旅程，终将引领它抵达为图书馆收集典籍的人们手中。")
zh(79192,"一张纸条将两起涉及新祸害鼠的交付案联系起来，不过书写者怀疑只是寻常炼金事故。贫瘠之地与凄凉之地交界处的隐秘据点，是继续调查的安全之地。")
zh(79229,"劫掠一空的营地里，留着两个人类与一个矮人的遗骸。伤口不像是半人马的武器所致，而盗窃行为也排除了寻常野兽的可能；一位经验丰富的拾荒者或许能辨明袭击者身份。")
zh(79358,"千针石林面临洪水威胁，显示奎尔博尔正扭曲自然之力。准备反制仪式需研习其他萨满传统，并借手中之书，理解那些被篡改的力量。")
zh(79360,"野猪人扭曲元素，以剃刀沼泽为巢，把势力向外伸展。你身为萨满祭司，与这些力量结有纽带；它们曾助你，你便欠着一份回护之责。探明野猪人的图谋，正是守住那些将被他们祸害的土地。")
zh(79361,"蓄意淹没千针石林的计划迫使你暂时搁置日常训练。你的导师提供了一本研习之书，或许能驱散风暴，守护所有受奎尔博尔仪式威胁的生灵。")
zh(79362,"格兰特的盾牌暗示他的灵魂仍在与亡灵抗争。他或许需要完成与伤害他的生物的斗争，那生物身上仍嵌着战锤。")
zh(79363,"西莉娅生前守护平民与家园，如今她的灵魂仍萦绕农田。她的剑暗示未竟之事可能涉及驱逐占据乌鸦岭南方农场的迪菲亚暴徒。")
zh(79364,"寻回的信件指向千针石林中的石化蜥蜴仪式，牵涉足以淹没峡谷的风暴与潮汐。面对威胁者缺乏手段阻止，你须向萨满盟友求取可能的答案。")
zh(79366,"扭曲的图腾可召唤维持石化蜥蜴仪式的腐化元素生物。在元素力量充沛之地与它们对峙，尝试中断仪式，同时阻止其组织者的计划。")
zh(79442,"泰匹斯特之眼或许对懂得风暴元素魔法之人有用。盟友无法加以利用，但他们知晓奥特兰克山脉的萨满或许能为你打造些东西。")
zh(79535,"研究笔记中提及‘石化蜥蜴：是否该畏惧石化？’这抄本将由欧文·塔德或加里昂·温德尔在他们的文集中收到，保存你所发现的文献。")
zh(79536,"与书商的合作在首次与图书馆建立联系后继续。欧文·塔德或加里昂·温德尔是下阶段的联系人，需要另一次会面以延续这段关系。")
zh(79624,"这配方看似描述一道肉菜，但语言对你而言陌生。其起源暗示是用食人魔语书写。找到对烹饪有兴趣的食人魔，或许能找到能翻译的人。")
zh(79947,"卷轴之中藏着《占星术：石心真言》，本是为欧文·沃弗恩或加里昂·温德尔准备的典籍。寻回这本抄本，将它送往他们手中，作为他们收藏中的一部分。")
zh(79948,"《防御魔法101》是另一本被欧文·沃弗恩或加里昂·温德尔所得的典籍。集齐这本卷册，将其送至这些联系人处，以获取所需的内容。")
zh(79949,"卷轴中藏着《谎言之网：揭穿神话与传说》，这本典籍本应归属欧文·沃弗恩或加里昂·温德尔。将这发现带去他们面前，与其他典籍一同呈现在他们眼前。")
zh(79950,"《恶魔与你》是那本神秘之书，你必须为欧文·沃弗恩或加里昂·温德尔寻得。这本抄本应归属那些联系人所收集的典籍之中。")
zh(79951,"《木乃伊：不讨喜的亡灵指南》以卷轴形式保存至今。找回它，便可将副本带给欧文·塔德或加里昂·温德尔，他们正是这份文件的接收者。")
zh(79952,"一本被水泡烂的书里，还夹着一册题为《RwlRwlRwlRwl!》的抄本。取回它，交给欧文·萨达或加里昂·温德尔，让它并入你寻书途中为他们收拢的那些卷册。")
zh(79953,"《反科技养魔指南》必须送达欧文·沃弗恩或加里昂·温德尔手中。你的搜寻需从那些联系人所收集的典籍中寻得这本特定的抄本。")
zh(79974,"信件作者暗中备有应急物资，以备仓促逃离。线索指向一座被瀑布雕琢的山崖，以及鹰巢，这些地标将指引你寻得隐秘的藏匿之处。")
zh(79975,"一封藏在工具箱里的信件，揭示了从远处效忠鹰与拳的使命。一处老路障与适合滑翔起飞的地点，是作者留下的下一条线索。")
zh(79976,"信中提到作者再度转入地下以求自保。简短的讯息与未固定的睡袋，让人难以判断是另寻藏身之所，还是线索已告终结。")
zh(79980,"信上写明：那处窖藏还没被人取走，并应下旅途所需的补给。按它指的方向北行百步，另附一句告诫——那道崖坡险得很，下去要当心。")
zh(80001,"这处熄灭的火坑木材已干，足以让你重新点燃。")
zh(81947,"欧文与加里昂所关注的典籍，正寻找《血色魔法》一书。寻回此书，便又添一卷他们需处理的典籍请求。")
zh(81949,"欧文与加里昂所关注的典籍，正寻找《潮裔传说》一书。寻回此书，便又添一卷他们需处理的典籍请求。")
zh(81951,"欧文与加里昂所关注的典籍，正寻找《临界与魔法》一书。寻回此书，便又添一卷他们需处理的典籍请求。")
zh(81952,"欧文与加里昂所关注的典籍，正寻找《日常礼仪》一书。寻回此书，便又添一卷他们需处理的典籍请求。")
zh(81953,"欧文与加里昂所追寻的典籍，正寻找《巨石水坝设计》。寻获此书，便为他们整理的书目再添一卷。")
zh(81954,"欧文与加里昂所追寻的典籍，正寻找《毒水崖漫游录》。寻获此书，便为他们整理的书目再添一卷。")
zh(81955,"欧文与加里昂所追寻的典籍，正寻找《金属之心》。寻获此书，便为他们整理的书目再添一卷。")
zh(81956,"欧文与加里昂所追寻的典籍，正寻找《咒术师圣典》。寻获此书，便为他们整理的书目再添一卷。")
zh(82208,"图书馆接受单本书籍的捐赠，待凑齐二十五册便告完成。这项任务允许通过逐步送书，为典籍馆添砖加瓦。")
zh(84395,"詹妮亚或奥兰寻觅《亡灵马铃薯》一书。寻获此书，便完成他们的请求，也将书卷送至两位收书人之一。")
zh(84396,"詹妮亚或奥兰寻觅《岩浆或熔岩？》一书。寻获此书，便完成他们的请求，也将书卷送至两位收书人之一。")
zh(84397,"詹妮亚或奥兰寻觅《北卡利姆多——全面指南》一书。寻获此书，便完成他们的请求，也将书卷送至两位收书人之一。")
zh(84398,"詹妮亚或奥兰寻回《光之研究》一书。取回此书即可完成委托，将书送至两位收件人之一。")
zh(84399,"詹妮亚或奥兰寻回《轰隆隆！》一书。取回此书即可完成委托，将书送至两位收件人之一。")
zh(84400,"詹妮亚或奥兰寻回《骑士与女士》一书。取回此书即可完成委托，将书送至两位收件人之一。")
zh(84401,"詹妮亚或奥兰寻回《天灾：亡灵威胁还是误解？》一书。取回此书即可完成委托，将书送至两位收件人之一。")
zh(84402,"詹妮亚或奥兰寻回《亡灵魔法入门》一书。取回此书即可完成委托，将书送至两位收件人之一。")
zh(86574,"一名信使遭巨翼双足飞龙袭击身亡，原本送往法拉莉亚的货物散落一地。这些包裹似乎被带往了巢穴，寻回它们便能完成中断的运输。")
zh(86576,"血怒鹰身人囤积着闪亮的宝物，包括装饰用的太阳石。莫洛加尔对这些宝石颇感兴趣；在与鹰身人战斗中收集它们，终将派上用场。")
zh(86585,"一名落难的登山者倒卧在踏毁的铁炉堡旗帜旁。杀害她的巨魔或许仍在附近，仍记得那面旗帜；重新竖起它，便能引出凶手，正面交锋。")
zh(86613,"矮人撤离时遗落了工具，这些装备似乎未遭损坏。将它们交还给挖掘者，就能恢复他们工作的必要工具。")
zh(86614,"一枚刻有徽章的银发夹与主人失散。这件物品的归属，正是这次发现的意义，顺着渔具中发现的个人物品线索追寻而至。")
zh(86667,"诺里克需要一罐雪来施行萨满仪式。格伦希尔无法离开研究本地元素生物的书房，因此需你前往山口采集雪块，送往她昔日的导师，以免融化。")
zh(86757,"兽人巡逻使东部森林对精灵而言不再安全。珊蒂瑞亚希望夺回土地，并建议回收敌方武器，让防御行动同时为可再利用的资源。")
zh(86758,"马雷克曾用匕首刺穿鳄鱼蜥的下颚才得以脱身。如今他想要找回工具，并铲除那头他唤作“匕首獠牙”的巨兽，保护沿湖猎人免受威胁。")
zh(86776,"塞尔萨玛缺少铁炉堡的完整资源，摩汉则正面临日常用具的青铜短缺。你的锻造经验能协助他维持生产，提供新冶炼的金属条。")
zh(86784,"埃利亚诺需要柴火维持荒野营地的运作。协助这位经验丰富的旅行者，将让你了解远离聚居地生存的实用知识。")
zh(87288,"多兰纳尔的商人需要夜刃豹皮，并愿以物易物。虽然她赞叹这些生物的美丽，但也指出当地野兽性情凶暴，可能迫使旅人自卫。")
zh(87318,"柯玛在萨多尔大桥逃离黑铁势力时与搭档埃森失散。她不知埃森是被俘、坠入河中，还是成功脱身，只盼得到一丝他尚在人世的讯息。")
zh(87491,"黑铁召唤出火灵后将其囚禁，如今它要求自由，并渴望用烈焰焚毁囚禁者、他们的粉末与堡垒。释放它，便是终结这场强加的囚禁。")
zh(87760,"样本研究显示娜迦奴役海洋生物，弃用之后便丢弃。对抗兽群驯养者并夺取她的工具，是对这种暴行的回应。")
zh(88756,"黑铁从建筑工地偷走了炸药并运往营地。找回那些红色标记的木桶，能在这群窃贼造成更大麻烦之前夺回这危险物资。")
zh(88757,"埃森在逃离黑铁势力时遗失了数件物品。她喘息片刻、重新整理行囊之际，亟需找回项链、法术书与水囊，好继续她的旅程。")
zh(88758,"埃森正准备启程，她希望柯玛知道她还活着，且已踏上归途。带着她的信笺，便能将这消息送达，而她也正收拾着最后的行装。")
zh(90902,"你的自由意志已回归，但如今引导光明会对你的亡灵躯体造成伤害。阿拉米斯希望你练习治疗术，以适应这截然不同的存在。")
zh(91208,"一些复活的圣骑士仍难以接受自己曾战斗过的人民。阿拉米斯请你向一位惊恐的圣骑士伸出友谊之手，他尚未调和信仰与亡灵的矛盾。")
zh(91209,"阿拉米斯派你前往布瑞尔的沙里，继续学习。洛丹伦仍需守卫，尽管许多亡灵对圣骑士及其与光的联系心存疑虑。")
zh(91282,"提瑞斯法的圣骑士们正围绕共同信仰与改变后的生活建立社群。沙里邀请你前往他们的修道院，寻找训练、同伴与理解。")
zh(91285,"这个社群迁入了鱼人曾用作产卵地的城堡，将他们驱逐。如今鱼人的袭击威胁着居民，你协助平息这场源于占领的冲突。")
zh(91294,"随着眼前危机已解，布雷顿邀你见见城堡的居民。向丹妮莎自我介绍，助你融入仍在筑造家园的社群。")
zh(91316,"此地远离幽暗城，修堡一事格外艰难，木石砖瓦也所剩无几。乔林请你去黑影谷的废墟里翻找还能用的材料，好让大伙把修缮接着做下去。")
zh(91317,"一些复活的圣骑士仍保留旧日仇恨，攻击其他亡灵。丹妮莎希望在更多人受害前阻止他们的罪行，以免不信任蔓延至整个教团。")
zh(91723,"似乎源自狗头人的能量波动，让哈米什的法术器具失衡。他需降低他们的魔法活动，才能校准设备，继续工作。")
zh(91724,"尽管先前已尝试，哈米什仍无法校准仪器。湖畔强盗练习魔法的传言，为干扰他工作的神秘力量提供了新解释。")
zh(91725,"豺狼人伏击了布利克斯，迫使她丢弃塞欧克瑞图斯托付的附魔材料。她希望在归来前找回这些东西，否则若空手而归，恐怕要花上数周收拾变形实验的残局。")
zh(91732,"战争让优质钢材稀缺，工具也多已破损。哈加尔想从玉石矿洞取回铁锹，好重新熔炼出金属。")
zh(91733,"奥尔明翻倒的货车将工具与物资遗失在河道中。野兽与鱼人阻断了他的寻回之路，你的协助将化解这场意外带来的后果。")
zh(91736,"浓郁的苹果香气暗示着酒窖的用途。一颗鲜红的苹果，正是炼制这种奇特酿造装置产出的苹果饮料的关键原料。")
zh(91738,"德·维里斯中士一见到雷霆苹果酒便喜形于色。递上这杯饮品，便是一次围绕他日常喜好展开的小差事。")
zh(91740,"克罗基在附近道路横行霸道已久。他的头颅能让守夜人得知鱼人死亡的消息，并获得确凿的证据。")
zh(91741,"一只狗头人丢下一本被啃食的书，书页上留有被吞食的痕迹。帕克斯顿修道院的图书馆似乎最有可能是来源，为这本受损的书找到归处。")
zh(91743,"狗头人不仅偷走了书籍，更在啃食它们。帕克斯顿必须尽快找回这些书，否则他的藏书将一一消失在它们的獠牙之间。")
zh(91745,"凯尔希在矿洞附近工作，或许见过狗头人所作所为。向她咨询可推进寻找书籍的线索；她也懂采矿。")
zh(91746,"这件战利品展现了战胜艾尔普爪的胜利，也讲述了一段可能吸引本地猎人或剥皮者的往事。赫莉涅可能是这段狩猎证据的接收者。")
zh(91751,"赫莉涅需要更多兽皮才能完成当前订单。她丈夫本该协助猎狼，却因事在修道院附近，只得另寻帮手。")
zh(91752,"狗头人将书籍送往一个叫纳夫的人手中，或许是个深藏矿洞的首领。替玛克布莱德取回那个布袋；守卫或许会需要同伴协助。")
zh(91753,"基塔认为法师需实践与学术并重。解开狗头人蜡像上的法术，可窥见他们简单却高效的天赋魔法。")
zh(91758,"凯尔希看见一只狗头人带着装满书籍的大布袋离开矿洞。玛克布莱德希望借助猎人导师托德林的追踪术，找回帕克斯顿失窃的书籍。")
zh(91772,"托德林怀疑书籍失窃之事不限于北郡。他的工具将助你追踪狗头人，并将发现带给杜汉，你在闪金镇少不了他的帮助。")
zh(91775,"帕克斯顿担心被盗的书籍可能让狗头人召唤元素仆从。与其它书籍一同在法戈第矿洞找回，返程途中也要护好这些典籍。")
zh(91777,"帕克斯顿·冈特尔的书籍中，仅两本下落不明，据信已被带往玉石矿洞。狗头人的魔法让寻回充满危险：若学徒召唤元素生物，导师恐怕会更糟。")
zh(91858,"两名土灵环的代表在银松森林途中失踪。丹妮莎视他们的营救为帮助部落的机会，也想证明她的组织值得信赖。")
zh(91859,"两名所谓的重要人物引起注意：一名牛头人与一名高等精灵同行。这对罕见组合穿越了部落领地，巴尔德伦或许知道他们如何通行。")
zh(91860,"巡逻队目睹豺狼人将一具庞大尸体抛上芬里斯的火堆，却不见随行的精灵踪影。尽管你的线人称搜索无望，你仍可查清两名旅行者的下落。")
zh(91861,"仅有一具遗体被发现，留下高等精灵生还的可能性。附近的要塞，正是寻找失踪同伴的下一站。")
zh(91862,"露米娜解释说，她并非高等精灵，而是申纳多瑞族的风塑者。她原本前往研究元素交汇，却遭俘虏；她需要豺狼人的钥匙才能重获自由。")
zh(91899,"一封密封的学徒货箱可作为货物交付给收集这批货物的人员。这项提议为你安排将货箱送至接收点的报酬提供了途径。")
zh(91900,"一封密封的学徒货箱可作为货物交付给收集这批货物的人员。这项提议为你安排将货命送至接收点的报酬提供了途径。")
zh(91901,"一封封存的专家级箱子可作为货物递交给收件员。这项提议为将箱子送达指定地点提供了补偿安排。")
zh(91904,"一封封存的学徒级箱子可作为货物递交给收件员。这项提议为将箱子送达指定地点提供了补偿安排。")
zh(91905,"一封封存的工匠级箱子可作为货物递交给收件员。这项提议为将箱子送达指定地点提供了补偿安排。")
zh(91920,"奎因对伦弗雷尔的药剂毫无改善，甚至害怕再次死去。他提议将鱼人眼球带给炼金术士，冒着冒犯的风险，尝试另一种治疗方式。")
zh(91921,"伦弗利尔准备了另一种药剂支持奎因的康复。这剂药必须送达仍需治疗的病人，而药剂师则需将注意力转回其他事务。")
zh(92109,"一个少年梦想学习炼金术，但父亲因危险禁止他使用草药。他请求获得自己的物资，开始实践。")
zh(92110,"年轻学徒享受了他的第一剂药剂，但想尝试比花更丰富的材料。他的热情让他选择了鱼人眼球作为新实验的原料。")
zh(92124,"帕克斯顿需要知道缺少多少本书。丹尼尔可以清点库存，但他对职业的痴迷让他分心；让他专注于图书馆。")
zh(92401,"爱德华仍在洛丹伦搜寻那个在阿尔萨斯摧毁城市时失去的儿子。他失踪已有数日，妻子需在亡灵横行的废墟中知晓他的下落。")
zh(92415,"残破的信件在亡灵盘踞的墓园里勉强留存。信中提起一个失踪的心织者家的孩子。暴风城的孤儿院嬷嬷或许知道些什么，能让搜寻接着走下去。")
zh(92421,"被遗忘者夺回故土时力量日渐衰弱，腐烂的躯体亟需替换。莫尔宾提议对抗废墟中的天灾军团，收集完整肢体以照料族人，同时效忠其君主。")
zh(92422,"不洁迷雾遮蔽了洛丹伦废墟附近的天灾军团势力。斥候将矛头指向拉兹玛尔，一名亡灵巫师，其隐匿身份让危险势力得以在幽暗城附近活动。")
zh(92432,"达拉然的灵脉遭破坏，使造物变得狂暴。议会试图掩盖危机，但城市已陷入混乱，茉德拉亟需外界援助，对抗一个再也无法隐藏的威胁。")
zh(92434,"结界崩塌令达拉然陷入动荡。巡逻力量削弱之际，一枚重获的钥匙提供了经由下水道进入城市的途径，揭开一座曾被封锁之城的秘密。")
zh(92456,"达拉然的魔能植被吸引着超越肯瑞托的植物学关注。你的联系人想要一份中央花园的样本，认为你进入不受欢迎之地的能力，或许能助他达成目标。")
zh(92457,"释放的奥术能量吸引元素生物前来饱和自身，加剧对防御的破坏。肯瑞托需减少其数量，同时法师们维持结界并应对更严重的紧急事件。")
zh(92458,"动荡始于紫罗兰城堡，如今已席卷达拉然，释放出强大的魔法能量。法师们勉强维持着结界，一枚钥匙可助你悄然潜入，与联络人会面，直面这场危机的源头。")
zh(92459,"达拉然逐渐平静，结界也渐趋缓和，但议会或许会对秘密获得的帮助心存不满。带着好消息，将一颗光粒带给赛琳德拉，证明外来援助的必要性。")
zh(92460,"腾达尔急需援助，而你正值成年。艾莉送你前往罗里安，村庄领袖，由他引导你迈出冒险者的第一步。")
zh(92461,"维德尔伦的族群数量增长失控，正威胁腾达尔林地的平衡。罗里安希望减少它们的数量，同时承认这些生物在生态中举足轻重的地位。")
zh(92462,"一名游侠报告了丝绒飞虫的入侵。若放任不管，虫群或将成为威胁，你需前往东侧腾达尔林地介入此事。")
zh(92463,"仅消灭工虫无法遏制虫潮。深入森林，直面蜂后，她受更激进的士兵护卫，藏身于虫巢之中。")
zh(92464,"风之具象因民众元素恩赐者的离去而躁动不安。伊拉雅正研究这些生物，它们对周遭力量与情绪反应敏锐，以探寻动荡的根源。")
zh(92465,"阿尔·阿凯思被怀疑煽动了风灵精灵的暴动。驱散危险的风势，直面这个邪教，以阻止有人因此受伤。")
zh(92466,"萨满祭司的试炼需回应四方元素，即便世人欠风之情。大地试炼前，博罗要求你以直面入侵的邪教徒，证明决心。")
zh(92467,"萨帕塔将饮者的精神与元素相连，使其感知不同。试炼需在圣地饮下，以确立与大地的羁绊。")
zh(92468,"石英见证你与大地的相遇，将成为博罗为你打造图腾的核心。其朴素的形制，暗含对耐心、力量与细微之物的敬意。")
zh(92469,"盟友留守应对残余敌人，罗里安需知晓邪教现身。将此警告带回村庄，便能让村长察觉新的威胁。")
zh(92470,"意志的考验将你引向西方洞穴。击败乌瑟拉及其母后乌萨娜，以证明你敢于直面危险。")
zh(92471,"完成的试炼已检验你应对泽弗拉斯艰险的准备。艾瑟恩，岛上的领袖之一，见证你的进展，愿将更严峻的挑战托付于你。")
zh(92472,"阿卡斯的威胁笼罩申达尔，亟需援助抵御。你的道路向南，需与治安官奥娜达会面，以明你来自何方。")
zh(92473,"饥饿的乌瑟拉曾险些杀死村旁树下的男孩。西南洞穴正成威胁，须在另一孩童遭袭前将其削弱。")
zh(92474,"一个游戏邀请你从塔顶跃下，借助天赋之能漂浮而行。试着在罗里安之前落地，惊扰他并练习如何减缓下坠。")
zh(92479,"一封猎人导师封印的书信在你与狗头人交战时抵达。玛克布莱德希望这封信能在修道院的其他事务开始前得到关注。")
zh(92481,"多莉在你与兽人交战时留下了一颗传讯水晶。法师导师期待你先查看它，再去找她继续学习。")
zh(92482,"泰瑞在你与兽人交战时留下了一张便条。村庄的猎人导师希望见面，借这封私人信件开启下一轮训练的对话。")
zh(92483,"阿基里在你对抗兽人之后请求会面。他的便条引荐了潜行者导师，他的技艺深藏于村庄的阴影之中。")
zh(92484,"博罗在你处理兽人问题时留下了一颗传讯水晶。查看它，便能回应萨满导师的召唤，再赴他所求的村庄会面。")
zh(92485,"席顿在你与兽人交战时留下了一封信。德鲁伊导师愿提供指导与建议，他的召唤正是继续探索此条道路的机会。")
zh(92489,"达拉然在毁灭后正在重建，却正面临失控的奥术能量暴走。联盟无法失去这样一位强援，亟需协助法师们遏制这场危机。")
zh(92514,"在接手沈达尔的事务前，先去见风塑者长老伊莉亚。柯莉埃拉也能提供帮助：她的客栈为到访村庄的旅人提供住宿与补给。")
zh(92515,"傲爪族正逼近村庄，可能掳走孩童或宠物。减少他们的数量或许能阻止悲剧发生，而他们的皮毛也能制成村民所需的物资。")
zh(92516,"一群角鹰兽在沈达尔东南方筑巢，并开始骚扰旅人。减少它们的数量，是为了缓解道路上日益增长的威胁。")
zh(92517,"瀑布后方洞穴里的强盗愈发危险。阿诺达无法再派出更多人手，只能请你去对付本尼克和他的手下。")
zh(92519,"结界仍缺少乔瑞尔数日前本该送达的解药与药剂。你的联系人对药剂师的可靠性存疑，需要你取回准备好的补给，以补足缺失的物资。")
zh(92528,"贾萨安吹嘘阿尔阿克瑟的力量增长，却阻止一名招募者接近重要访客。调查村庄，弄清这个教派的意图。")
zh(92529,"萨尼娅视灵体的离去为族人骄傲的惩罚。她将你视为招募者，并派你前往贾萨安，接近阿尔阿基尔的信徒。")
zh(92532,"伦在你返回后已等候多时，并留下了一封私人信件。阅读它，将助你准备与战士导师的会面，他正守在塔楼中继续你的训练。")
zh(92544,"马尔杜科在神殿废墟中领导着教徒，威胁旅人并强征追随者。你的盟友需守卫道路，而你则要直面这群人。")
zh(92550,"申达尔预感到会有教派袭击，想要先发制人。攻击法拉萨的势力，同时擒获他们的指挥官，趁村庄布防之际行动。")
zh(92551,"阿尔·阿凯斯族人已数月来偷窃食物、风石与商队货物。若能从法拉萨取回物资，村庄便能弥补这些掠夺造成的损失。")
zh(92553,"日益增长的威胁让猎捕与采集变得困难。村庄急需新鲜鸡蛋与陆行鸟肉，以维持居民的口粮，而寻常的觅食活动已被中断。")
zh(92579,"申达尔与它的法阵暂时安然无恙，但教派仍在扩张。阿奥娜将情报传往瓦兰尼亚，以便瓦兰达尔做好战斗准备。")
zh(92595,"伊利雅感知到你对高空视野的亲和力，即使没有萨满训练。她想向你解释风塑者的使命，以及他们族人在泽弗拉斯所面临的困境。")
zh(92596,"拉希里察觉到你与奥术魔法的联结，哪怕你并非法师。他邀请你了解他的教团、泽弗拉斯的能量，以及他族人所承受的苦难。")
zh(92597,"浮现的灵能脉络提供了更直接通往泽弗拉斯奥术能量的途径。法洛恩提议你与立石为伴，练习你继承的亲和力，学习如何汲取这股力量。")
zh(92598,"天空之眼是元素灵体赐予的礼物，在交汇之地愈发强大。在立石旁修炼，可探寻这份亲和力，以及这些地方可能蕴含的智慧。")
zh(92640,"在开阔地正面迎战教派并不可行。另一种选择是突袭神龛，阻止洛瑟塔娜完成她的计划；瓦伦妮亚已有对策。")
zh(92642,"守卫者正艰难地抵御阿卡瑟特的进攻。敌方治疗者持续维持攻势；干扰他们与战士，或许能给防守者喘息之机。")
zh(92643,"一名叛逃者声称知晓教派的真正计划，但要求保护后才肯透露。悄悄前往瓦兰达尔西北方向寻找他，不过这提议或许是个陷阱。")
zh(92644,"一名死掉的叛逃者身旁躺着一块受损的蓝水晶，仍可能至关重要。将发现带回影歌处，好让其查验。")
zh(92645,"贝尔吉洛斯指挥官率军进攻，威胁压倒守卫者。这位前和平守护者位于山下别墅；阻止她，是坚守防线的关键。")
zh(92646,"洛瑟塔娜已借传送门逃往冰冠之塔，被艾耶莎与艾拉德林追击。你的盟友受了伤，如今只能由你追去，协助阻止她。")
zh(92679,"阿尔瓦里昂为求救自家农场而带着伤痛来到瓦兰达尔。他将你送往低地果园，去找他的妻子艾梅莉亚。")
zh(92682,"艾梅莉亚期盼费拉乌来分得丰收的果实。在此之前，她让你采集苹果并对抗藏身树丛中的强盗。")
zh(92683,"振翼尘虽制造混乱，却也有实用的居家用途。用拍打工具可将它从田间昆虫身上抖落，不过有些昆虫对此扰动会反应激烈。")
zh(92684,"风行者正在偷窃本就贫瘠的苹果收成。减少它们的数量；它们的肉也能让艾梅莉亚为果园守卫准备一顿热饭。")
zh(92685,"强盗们在果园北方设下据点。艾梅莉的计划是趁他们尚未分得收成前突袭，以提升农场防卫的渺茫希望。")
zh(92693,"艾梅莉亚明白，对抗强盗首领可能让她丧命。虽有准备能增加战斗胜算，但加入她仍意味着接受果园垂死挣扎的防卫。")
zh(92698,"有关目的与功能的零散话语不断在机械的装甲下重复。附近有人，比如艾梅莉亚，或许能理解这台机器，并解释它诡异的行为。")
zh(92699,"艾拉丁率领高等精灵的玄夜会，驻守在瓦兰达尔的会所。介绍时须尊重与风塑者脆弱的共存关系，因他们的敌意可能加剧教派危机。")
zh(92700,"大星眼统领瓦兰达尔的风塑者，驻守在本地会所。介绍时须避免激化与高等精灵的对立，因城市本已面临教派的威胁。")
zh(92701,"申达尔与它的方尖碑暂时安然无恙，但教派的扩张意味着必须未雨绸缪。阿诺达的报告必须警告瓦伦尼亚——岛上的和平守护者。")
zh(92703,"阿梅莉亚希望告知丈夫果园发生的变故，并请他带来一位风塑者检验那座构造体。她怀孕的事想暂时保密，因此家族安全格外重要。")
zh(92706,"一条巨鲨在码头盘旋，袭击水手与小船。加兹鲁维悬赏缉拿布鲁兹，须用它的鳍作为捕获的证据。")
zh(92707,"从巨人身上剥下的巨大腕甲，足见其体型之骇人。把这副腕甲送到落锤镇，便是给杜拉姆法尔提个醒：他面对的凶险有多重——这物件，正是那一带所受威胁的凭据。")
zh(92708,"寻找失踪灵体的行动为风塑者带来了新线索。艾耶莎想解释一项拯救岛屿的计划，需要年轻冒险者的协助。")
zh(92709,"艾拉德林认出了你的血统，相信年轻一代能助其拯救家园。他想说明高等秩序的使命，以及超越泽弗拉斯本身的计划。")
zh(92727,"菲利昂前往高地研究风系魔法，至今未归。高等秩序担忧他途中遭遇不测，必须找到这位失踪的学者。")
zh(92741,"尖啸幼兽越繁殖越多，已经窜出惯常的林地向四处蔓延。伊亚达里亚要你削减它们的数目——走这一趟，既是对祸患的回应，也顺带为她取些利爪，好探明其中的炼金之性。")
zh(92742,"一种未知毒药正侵蚀西部荒野的农田。检测井水，揭开毒源如何渗透土壤，以及如何阻止这场污染。")
zh(92743,"瓦鲁格渴望一顶象征征服力量的王冠，而玛格拉姆的传说中，一件合适的宝物正埋藏在荒芜之地的墓穴之中。寻获它，或许能窥见族群的秘密。")
zh(92744,"西部荒野的污染可能已蔓延至海域，威胁暴风城的粮食安全。鱼人鳃部样本，将揭示水体毒素的扩散范围。")
zh(92745,"井水样本中含有的有毒金属，足以让西部荒野的农田荒废数十年。迪菲亚掌控矿脉，以其他生物为劳工；破坏这一体系，是应对污染的当务之急。")
zh(92747,"调查的矿井似乎无法解释农田的毒害。唯一未排除的线索，是死亡矿井再度活跃的可能，而月溪镇或许藏有证据。")
zh(92748,"回收的物资指向一场大规模工业污染，阿尔巴需要足以摧毁污染源的炸药，并派遣你寻访暴风城的工程师。")
zh(92749,"破坏行动需要足以摧毁污染设施的炸药。精灵同意协助，并提议以硝化甘油作为起爆药的核心原料。")
zh(92750,"精准引爆需从安全距离触发。精灵缺乏远程引信，提议向暴风城情报部门寻求支援，以确保行动参与者的安全。")
zh(92751,"军情七处早已知晓月溪镇的行动，并提供了一枚原型引爆器。从洞穴外触发爆炸能保持更安全的距离，不过这份协助需保持低调。")
zh(92752,"炸弹已准备就绪，引爆器需谨慎操作。返回阿尔巴，将针对污染西部荒野农田的产业计划推进至下一阶段准备。")
zh(92753,"阿尔巴认为一处大型地下熔炉是毒药源头。在那处布置炸药，旨在清除污染源，而她则在外协调远程引爆。")
zh(92754,"部族的远征正逼近白骨之谷，但他们的目的仍对你隐藏。成员们需要黑影保护，并愿以能助他们存活的药剂作为回报。")
zh(92755,"拾荒者带回的魔法装备更少，因冒险者的遗物已所剩无几。海莱亚需要精华来附魔下一次掠夺队的武器，弥补因分解所得减少的损失。")
zh(92811,"半人马族群即便在战争中也交换雕刻着功绩的图腾。收集这些图腾，可增强玛格拉姆在你货币一文不值的经济中议价能力。")
zh(92812,"吉尔吉斯人即便在冲突中仍延续着交换雕刻故事的贸易传统。从其他半人马处回收的图腾可增强议价能力，并向可汗展示你的协助。")
zh(92814,"莫克拉想为妻子海莱亚准备简单的衣物，好练习附魔。他需要像旅行者在沙暴中佩戴的面具，希望借此支持那个负责魔法强化部族装备的人。")
zh(92817,"吉尔吉斯人拒绝穿戴他们认为不舒服的铠甲，即便已遭受重创。他们的武器匠人想要一件防护背心，并需要合适的腰带，以便研究技艺而不浪费稀有皮革。")
zh(92818,"玛格拉姆族要求更多武器对抗吉尔吉斯人，想看看外来者能打造出什么。大型铁斧将展示你的技艺，同时支援他们对敌人的战役。")
zh(92819,"破坏计划已进入引爆时刻。引爆装置将启动针对污染西部荒野农田的设施的干预行动。")
zh(92834,"一次对话尝试以残酷的讯息告终，使者被派往邪教时遭到了折磨。他的朋友已放弃与他们讲理的希望，转而要求以暴制暴。")
zh(92840,"菲利翁被派来收集的数据仍需使用。利用秘典索引测量风石构造，但风塑者可能阻碍研究。")
zh(92841,"交付王冠将开启了解玛格拉姆重大发现的机会，但瓦鲁格不会亲自透露。去找奥格鲁尔，他会决定你是否配得上这被严密守护的知识。")
zh(92844,"妖术的能量弥漫白骨之谷，新近学会驱使这股力量的人想从中榨取好处。你头一件差事是收集骸骨，之后才谈得上用它做更繁难的活计。")
zh(92846,"一些被放逐的吉尔吉斯人跟随玛格拉姆进入峡谷，尝试接触亡灵魔法。奥格鲁尔不知他们是要加入还是推翻他的族群，但视他们为干涉力量的入侵者，下令处决。")
zh(92847,"吉尔吉斯亡灵巫师的武器展现了一种令敌人感兴趣的技艺。被诅咒的木材与瓦鲁格的水晶，或许能借他们的力量引导方式打造出法杖。")
zh(92849,"证据显示菲利安遭遇了麻烦，可能需要援助。北方的洞穴将成为继续寻找他的下一处据点。")
zh(92850,"菲利昂如今可独自折返，只是尖啸幼崽的巢已筑到瓦兰达尔近旁，凶险得很。他要你去会那条主母，自己则去向艾拉德林复命。")
zh(92860,"教派的敌意与大规模行动的传闻让回避冲突变得不可能。玄夜会承诺支持瓦兰达尔，对抗教派即将发动的任何攻势。")
zh(92867,"激流堡不只是废墟，它的支持者希望保护雕像、墓穴与隐藏的资源。击退石拳与辛迪加，旨在夺回地盘而不暴露仍被守护的秘密。")
zh(92871,"教派调动的风声越来越大，风塑者为此不安。他们要在下一场攻势成形之前，再向瓦伦尼亚和守岛的卫士们把话说明：援手不会断。")
zh(92872,"墓穴的守卫者通过世界的循环，以仪式纪念逝者。将葬尘带到海中，便能参与这场象征性的重生，再重返阳光照耀之地。")
zh(92873,"水晶可引导亡灵魔法，正如吉尔吉斯所展示的。奥格鲁尔用收集的骸骨组装了两具骷髅，希望你测试新法杖，再决定是否掌握这门技艺。")
zh(92880,"守军如今应付余下的来敌，把握比先前大了许多。瓦兰达尔要一份回报，写明塔楼那边援手之后，局势已然稳住。")
zh(92881,"两座瞭望塔的袭击似乎有预谋，指向锚状尖塔。影歌提供了一条值得深究的线索，揭示了邪教的意图。")
zh(92893,"吉尔吉斯俘虏被当作骨蠕虫的食物，但这些生物对活体猎物毫无兴趣。玛格拉的行动要求它们死去，以完成那残酷的目的。")
zh(92894,"奥格鲁尔希望你的亡灵术更加精进，族中的军队也得以扩充。他已强化你的法杖，以便在山谷中召唤更多亡灵，而所有试图抵抗他控制的失败尝试，都必须被摧毁。")
zh(92909,"奥兹温从铁炉堡赶来，本意是修复西部荒野的危险收割机，却陷入困境。修复出的零件或许能助他制造逃生装置，完成这场本该成功的任务。")
zh(92910,"一块异常完整的收割机零件对奥兹温或许有特殊价值。将它交给专家，他便能研究其用途，而不必预设他会发现什么。")
zh(92911,"奥兹温认为自己或许能短暂地控制那些敌对机器。在研究回收的组件时，他仍需更多零件，以验证自己的想法。")
zh(92947,"守备军从正面进攻以牵制敌人，主力则从侧翼包抄。突破神龛守卫，与希尤萨会合。")
zh(93034,"斥候查实，玛格拉姆在白骨之谷挖出了邪物。吉尔吉斯人要此事传开，你得先去寻内尔洛克；想跟着查这一趟，恐怕还得先攒下几分信任。")
zh(93035,"谷中的骷髅直立行走，非半人马一族。这说明玛格拉姆正在亵渎古墓；你的盟友希望这些亡灵安息，拒绝违背他信念的仪式。")
zh(93036,"阿翁达担心与阿卡瑟特族的和平即将破裂。因你身份未明，她派你去招募者桑雅渗透教派，查明他们对村庄的计划。")
zh(93037,"内尔洛克心里存着疑虑，却还说不出口。那些道行浅的亡灵巫师，身上的祭服或许能验明身份；小心取回祭服，便能试出他在谷中所见的异状是真是假。")
zh(93041,"这项发现深深影响了部族，唯有能行动者方能知晓。智者乌泰克需要身份证据与一枚新诅咒的头骨，以理解涉事者与他们所行的亡灵术。")
zh(93044,"瑟莱德丝之泪稀少却对对抗玛格拉姆亡灵术最为有效。趁盟友准备仪式制造武器之际，从穆拉拉处获取它们，以干扰敌方法术。")
zh(93058,"失踪的吉尔吉斯人并非全都叛逃——内尔洛克查出有族人被押在白骨之谷。一名强悍的玛格拉姆挡住了后续的探路，他要你帮手把人救出来，不肯丢下自己的族人。")
zh(93062,"被埋藏于土壤下的骷髅似乎是被放逐的亡灵巫师失败的召唤。一根能驱散黑暗魔法的法杖，可助你安息它们，支援吉尔吉斯人的事业。")
zh(93065,"和平卫士正集结待命，准备发动攻势。一条沿途的集合点让所有人完成最后准备，统一行动前，部队将离开城镇奔赴战场。")
zh(93066,"刺背族已占据通往新哨站的路线，并以神殿神器封锁敌军行动。削弱这股势力，将为哈吉亚的营地开辟通路。")
zh(93072,"西南方向的另一座吉尔吉斯村庄，成为玛格拉的新目标。这项任务要求你对当地居民发起攻击，以证明你对他们的忠诚。")
zh(93089,"高等精灵远征艾泽拉斯，获得了岛主的祝福。借助肯瑞托的帮助，他们以奥术之力，试图恢复泽弗拉斯失去的稳定。")
zh(93090,"萨满的远征也获得岛主的许可，并得到大地之环的协助。他们深入泽弗拉斯的探索，旨在寻找解决其动荡的长久之计。")
zh(93122,"玛格拉族在山谷集结兵力，或许已使他们的村庄暴露于风险。深入侦查，评估防御工事，试探他们的布防是否能成为对抗可汗的契机。")
zh(93125,"一名吉尔吉斯人被承诺安全引诱至藏身处，却遭亲族威胁。他拒绝了他们以亡灵术加入玛格拉的企图，如今亟需协助脱身。")
zh(93128,"玛格拉在白骨之谷的布防似乎让杰恩可汗防御薄弱。然而机会转瞬即逝，来不及向吉尔吉斯首领请示，直面他仍属险境。")
zh(93129,"玛格拉族企图利用流亡者据点遭袭的机会，夺取其物资。这将助他们巩固占领，也为对抗其他部族做准备。")
zh(93159,"头戴斗篷的隐士在长期孤立后，开口说话显得局促不安。他结结巴巴的问候，仿佛在向一个几乎遗忘如何与人交谈的人致意。")
zh(93160,"隐士想准备食物，但附近橡果已收集完毕。大型飞禽使深入森林变得危险，他亟需帮助采集更多补给。")
zh(93165,"教派的暴行给夜爪部族带来了悲剧。瓦因提供报酬给阵亡敌人，同时将部族秘辛保留给证明忠诚之人。")
zh(93172,"幽灵在废墟间唱着哀歌。隐士怀疑一场悲剧使它们被困，请求协助解救，却不知究竟发生了何事。")
zh(93176,"研究这些小生物包括其解剖、食性与社交习性。你的联系人想分享这份爱好，提供笔记与材料供你观察，却警告你若遗失包裹需额外付费。")
zh(93188,"玛格拉族的势力已壮大，认为你的战斗贡献足够。向奥格鲁尔汇报，可传达待增援部队的状况，为占领流亡者营地做准备。")
zh(93196,"奥格鲁报告称，外族效忠吉尔吉斯的势力在玛格拉分神之际，暗杀了杰恩可汗。他赐予你一把强化的武器，用于一场亡灵仪式，意图让族长重归人世。")
zh(93224,"半人马对异族心存戒备，却与雕刻木料有贸易往来。若能获取样本，便可比对设计图，或许借此获得部族的青睐，以交易跨越仅凭善意难以跨越的隔阂。")
zh(93225,"跨部族贸易的观察显示，雕刻图腾已成为一种货币。你的联系人希望运送一批图腾，以改善与吉尔吉斯或玛格拉的关系，其中混入真伪结合的物件。")
zh(93226,"玛格拉当前实力最强，是降低风险的最佳选择。将礼物送至他们的军需官手中，是借安全之名缔结联盟的尝试。")
zh(93227,"尽管吉尔吉斯看似人数较少，但他们的生存证明了部族中仍存强大力量。送上一袋图腾，是寻求和平并赢得他们合作的途径。")
zh(93317,"湖中的螃蟹每年仅能采收数周。邪教活动已阻断了常规的采集，而季候将尽，外界援助变得尤为迫切。")
zh(93318,"治安官奥娜达悬赏通缉伏尔加拉，这只盘踞高地的危险飞禽正带来恐惧。唯有它的首级能证明那头被通缉的生物已被击败，送往丹纳里。")
zh(93319,"风石储备维系着日常与应急所需。疑似盗匪所为的盗窃正耗尽这项宝贵资源，其恢复对村庄的存续至关重要。")
zh(93320,"邪教正攻击灯塔守卫塔，可调遣的援军寥寥无几。瓦伦尼亚亟需援助，以解守卫之围，他们的存亡或系于额外支援之上。")
zh(93429,"失落者曾与他们同属一族，如今却以暴力与仇恨行事。你的联系人认为救赎已无可能，唯有终结他们的苦难，才能守护仍在沼泽中保持理智的生灵。")
zh(93430,"一条失落者偷走了你联系人随身携带的幸运鱼饵。鱼群的供应依赖于找回它，前往东部河岸的渔夫中寻找那个窃贼吧。")
zh(93459,"德鲁伊渴望在森林的传说背后过上平静的生活。然而这个邪教威胁着他们的庇护所，瓦恩提供赏金，鼓励协助对抗令他社区惶恐的危险。")
zh(93461,"在协助申达尔之前，你需要与高等秩序在当地的长老见个面。酒馆老板也提供住宿与补给，支持外来者在村庄的停留与工作。")
zh(93464,"德莱尼水晶维系着避难营居民的理智，然而无人真正理解它的力量。一位因恐惧其威力而被驱逐的法师，或许知晓某些关键之处；找到阿佐尔，将重新审视曾被拒绝的警告。")
zh(93465,"火刃氏族的术士研究德莱尼水晶，或许觊觎它的力量以行黑暗之事。吉马希的笔记能揭示他们的研究，提供答案，而无需让危险知识独占于他们手中。")
zh(93552,"元素生物的离去，使维系泽弗拉斯的魔法逐渐消退。风石仍是集中能量的重要来源，其开采对社区持续的能源供应至关重要。")
zh(93585,"圣光教会的使者寻求与避难营德莱尼的外交接触。然而他们的敌对族裔封锁了道路，需保护这段通往和平的旅程，或许也能为联盟带来助力。")
zh(93663,"德莱尼渔民的交易陷入僵局，一名信使带着货物失踪。你的联系人担心声誉受损，必须尽快在水边找回货物，完成交付以维系这桩生意。")
zh(93678,"笔记暗示纯净的德莱尼石球蕴含远超碎片的力量。关于传送门与召唤的提及仍存疑虑；将誊录带往避难营，分享发现而不妄下定论。")
zh(93680,"达拉然的重建令亡灵不安，因其邻近希尔瓦娜斯且与联盟关系密切。搜寻其营地，寻找隐秘通道，以便暗中调查城市而不暴露行踪。")
zh(93735,"风塑者维护着灵体留下的装置，但多数已失灵。瓦兰纳尔现存的运作机械体受损，修复者或许需要协助。")
zh(93736,"风塑者正在调查为何风灵离去。其后空洞出现，散去这些存在并收集其本质，或可助其理解真相。")
zh(93737,"机械师在受损装置内工作，待所需协助抵达。他需先完成机制检查，才能判断如何让经验不足者参与。")
zh(93738,"移除的零件显示高等秩序曾干预风塑者视作己任的装置。艾耶莎需要这些发现，以决定如何应对这明显入侵。")
zh(93739,"部落汇聚了截然不同的种族与文化。造访这些城市，或能理解那些热情接待新来者的艾泽拉斯社群。")
zh(93740,"数名风塑学徒死于非命，疑似与奥拉基尔有关。任务要求攻击其教派成员，并带回风石符文作为证据。")
zh(93746,"风塑派认定贝拉萨已越界而行，尽管此前已有警告。他们意图在途中震慑此人，令其狼狈返回，以警告高等秩序的干涉。")
zh(93791,"你的魔法造诣已开启一段古老的高等秩序传统：打造专属法术核心。贝尔南精通杖与法杖的制作，可为你指导这门实用技艺。")
zh(93797,"最古老树干仍存有元素风的余韵，贝尔南以这木材教导年轻法师制作第一件法术核心，延续既有的传统。")
zh(93835,"洛瑟娜借传送门逃往上层尖塔，正被艾耶莎与艾拉德林追击。另一名盟友已受重伤，且无援军可援，亟需协助阻止她。")
zh(93836,"破碎的结界使泽弗拉斯暴露于奥拉基尔领域之中。影歌必须得知此危机，并执行前往艾泽拉斯的使命，寻找拯救家园的方法。")
zh(93862,"可将公证过的货箱归还以换取声望认可。此提议需货箱作为交换，并可提升两个阵营的声望。")
zh(93926,"西塔不值得牺牲守卫者。命令是撤出和平维持者，集中兵力于村庄，以更有效地保护居民。")
zh(93927,"一截染血的纸条从一名死者的手中滑落。细读或许能揭开真相，也为后续行动提供指引。")
zh(93928,"一只老鼠向你讨要曲奇。若能找到它渴望的点心，便是助它一臂之力。")
zh(93948,"这枚徽章属于影歌家族，必须送回高等精灵长老手中。它的送达也捎带了对长老侄儿命运的通报与哀悼。")
zh(93949,"一只携带监听附魔的昆虫，揭发了异端崇拜的间谍活动。因附魔样本无法以目辨识，回应手段只能针对定居点的季节性虫害展开。")
zh(93951,"柔软鲜艳的角鹰兽羽毛深受空灵生物喜爱。它们的巢穴是收集落羽的好机会，但靠近领地生物需格外谨慎。")
zh(93958,"瓦伦尼亚的部众已攻破内殿，厮杀声却化作一片叫人心慌的死寂。得寻到他们的下落，才知道还有没有人能救。")
zh(93963,"联盟的主要城市汇聚了多元文化。作为艾泽拉斯的访客，游览这些首都可深入了解当地人民，而兰达尔能为你开启这段旅程。")
zh(94003,"最后的破天号既哀悼被谋杀的家人，也痛惜祖传盾牌落入邪教之手。从札尔手中夺回它，便是重拾一段传奇的守护传承。")
zh(94004,"一份可转让的委托要求智慧药剂。其内容明确交付与报酬，让其他工匠得以接手完成契约。")
zh(94006,"德鲁伊训练如今允许与传授食人魔形态的灵体相见。他的领域也在泽弗拉斯的影响下衰退，这门课与此岛的处境息息相关。")
zh(94007,"在高地的历练已让猎人准备好寻找动物伙伴。奎尔安娜精通驯兽之道，能教导如何与野兽建立羁绊。")
zh(94013,"完成两次驯兽后，最终的试炼仍待完成，以证明掌控。兽群之王提出更大挑战，方能进入猎人之道的深层教诲。")
zh(94050,"驯服生物只是培养伙伴的开端。奎尔多拉能传授训练新宠物的技巧，并持续深化这段伙伴关系。")
zh(94212,"一份可转让的委托要求智慧药剂。其内容明确交付与报酬，让其他工匠得以接手完成契约。")
zh(94213,"一份可转让的委托要求次级法力药水。其内容明确交付与报酬，让其他工匠得以接手完成契约。")
zh(94214,"一份可转让的委托要求暗影防护药水。其内容明确交付与报酬，让其他工匠得以接手完成契约。")
zh(94215,"一份可转让的委托单要求交付自由行动药剂。其说明明确指定了交货与付款方式，使其他工匠得以接手完成契约。")
zh(94216,"一份可转让的委托单要求交付次级敏捷药剂。其说明明确指定了交货与付款方式，使其他工匠得以接手完成契约。")
zh(94217,"一份可转让的委托单要求交付小巨魔之血药剂。其说明明确指定了交货与付款方式，使其他工匠得以接手完成契约。")
zh(94218,"一份可转让的委托单要求交付防御药剂。其说明明确指定了交货与付款方式，使其他工匠得以接手完成契约。")
