zh(94343,"一份可转让的委托单要求制作邪恶皮甲短裤。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94344,"一份可转让的委托单要求制作戈多克食人魔装。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94345,"一份可转让的委托单要求制作火山胸甲。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94346,"一份可转让的委托单要求制作符文皮甲头环。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94347,"一份可转让的委托单要求制作邪恶皮甲护腕。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94348,"一份可转让的委托单要求制作奇美拉外衣。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94349,"一份可转让的委托单要求制作重型蝎壳头盔。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94350,"一份可转让的委托单要求制作符文皮甲护腕。其内容明确交付与付款方式，使其他工匠得以承接此契约。")
zh(94351,"一份可转让的委托单要求制作霜刃长靴。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94352,"一份可转让的委托单要求制作巫纹头巾。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94353,"一份可转让的委托单要求制作符文布背包。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94354,"一份可转让的委托单要求制作符文布靴。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94355,"一份可转让的委托单要求制作礼服夹克。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94356,"一份可转让的委托单要求制作恶魔布靴。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94357,"一份可转让的委托单要求制作塞纳里奥草药包。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94358,"一份可转让的委托单要求制作暗纹面罩。指令明确交付与付款方式，让其他工匠也能承接这份契约。")
zh(94359,"一份可转让的委托任务要求制作鬼纹外衣。任务说明明确了交付与报酬，让其他工匠也能承接这份契约。")
zh(94360,"一份可转让的委托任务要求制作灵魂袋。任务说明明确了交付与报酬，让其他工匠也能承接这份契约。")
zh(94369,"若没有结界遮掩泽弗拉斯，奥拉基尔便能在自己的领地发动攻击。影歌必须了解这个弱点，并参与前往艾泽拉斯的远征以寻找解决之道。")
zh(94373,"特奥认为时机已到，该回应大地的召唤。在继续萨满教诲之前，他要求与附近的巨魔及其挂坠正面交锋，以证明自身实力。")
zh(94374,"萨普塔建立了一种灵性联结，使元素之力得以以少数人能感知的方式呈现。在圣石旁饮用它，为大地即将揭示的秘密做好准备。")
zh(94375,"水晶证明了与大地的交融，终将成为图腾之心。将它带给提奥，便是一堂关于耐心、坚韧与微小之物价值的课。")
zh(94411,"风塑者认为高等秩序正侵犯神圣之地，尽管屡次警告仍不改其行。他们希望将学徒驱逐，以捍卫这些边界，同时又不愿造成流血冲突。")
zh(94413,"高等秩序视新兴的灵脉为研究魔法的机会。风塑者却视之为大地的伤痕，而拉希里尔则试图守护通往那能量的通道。")
zh(94414,"古老方尖碑维系着这座岛屿，但它们的魔法正变得不稳定，却未见明显损伤。哈兰愿分享他的视野，以便检视其中一种元素赐予。")
zh(94427,"丹妮莎希望你以自由给予的善意表达信仰。协助坦尼斯潜入幽暗城，是你学习如何在悲剧中仍为他人服务的第一课。")
zh(94434,"坦尼斯惊讶你愿助他一臂之力，但他妻子的躯体正逐渐崩坏，急需布料包裹。药剂师们忙碌不堪，一块布料或许能替她撑到援手到来。")
zh(94435,"协助坦尼斯后，你返回丹妮莎处继续修行。对另一名被遗忘者施以同情，已超越单纯掌控圣光之力，成为你训练的一部分。")
zh(94436,"丹妮莎将生命符记交托予你，助比尔穆思一臂之力。使用这份痛苦的恩赐，可证明一名被遗忘者圣骑士仍能为族人效命。")
zh(94438,"比尔穆思逃过血色巡逻队，坚信法尔甘留下掩护他。他请求你寻找他的同伴，若能相助，便将你的圣光训练化作一次营救行动。")
zh(94440,"巡逻队发现了血色军团袭击布瑞尔的计划。找回这些密令，可警告守军布防，让他们在村落遭袭前设下埋伏。")
zh(94441,"比尔穆斯希望你将丹妮塔的谢意带给彼拉迪昂的圣骑士，他亦承诺会向其他死亡骑士提及你们的帮助，并为能与你并肩而感到自豪。")
zh(94449,"下一次萨满教义课，将涉及火焰、毁灭与力量代价。布雷格斯将判断你是否已做好迎接元素召唤的准备。")
zh(94465,"单凭力量不足以赢得火焰图腾。火把象征着接受试炼的意愿，而布拉尔迪尔守护着神龛，教义课必须在此继续。")
zh(94466,"接近永恒之火需大地灵契将灵体与火焰绑定。布拉尔迪尔知晓如何准备，却需从周边敌对势力手中夺取材料。")
zh(94467,"灵契使神龛上方的灵体得以显现。直面它，并将余烬投入火盆，是寻求火焰恩典的试炼之一，而试炼正愈发危险。")
zh(94468,"燃烧的火把伴随从神龛归返，点燃新的期待。布雷格斯将在试炼后等待它，延续自火焰召唤开始的教导。")
zh(94472,"大地灵契使萨满试炼中灵体得以显现。特欧可提供另一份灵契，以防失手饮下而中断神圣的邂逅。")
zh(94473,"对抗显现的失败不必终结试炼。布拉尔迪尔提供另一份灵契，恢复观灵能力，使你得以重返神龛之上。")
zh(94484,"德鲁伊议会的沉默令等待回音之人忧心。近期遗迹与动荡令人不安，前往艾格莱尔调查，看是否发生过严重之事。")
zh(94485,"受伤的德鲁伊需要药膏。埃莱加尔需要雷蒂的泪苔，这种具有抗菌作用的汁液能帮助他们在情况恶化前治疗并包扎伤口。")
zh(94486,"幼狼的绝缘羽绒可覆盖药膏，防止抗菌汁液干涸。埃莱加尔需要这些羽绒救治伤者，但那些生物已变得极度敌对。")
zh(94487,"埃莱加尔寻求对阿尔凯斯残酷伏击的回应。他们的动机尚不清楚，但他要求击溃邪教徒，并夺回他们的传家宝。")
zh(94488,"埃莱加尔嗅到哈莱恩的气息，一个失踪数月的德鲁伊，混在邪教徒之中。他似乎亲手洒下同伴的鲜血，将回应化为对背叛的审判。")
zh(94489,"药膏已备齐，受伤的德鲁伊可能无法自救。埃莱加尔请求紧急救治，尤其担忧他受伤的伴侣乔蕾尔，他离开时她伤势严重。")
zh(94490,"藏在哈莱恩护腕后的纸条似乎解释了袭击德鲁伊巢穴的动机。埃莱加尔需要它被查验，以了解暴力对社区造成的伤害。")
zh(94491,"种种迹象指向瓦兰达尔城里一名教派的眼线。埃莱加尔伤重难行，要人把这份猜疑、连同大兽穴那边的折损，一并报给洛瑟鲁姆。")
zh(94493,"埃莱加尔本期待援军，却发现求援从未抵达瓦兰达尔。伤者危在旦夕，又无组织支援，回应只能依靠尚存的资源。")
zh(94494,"训练中展现的耐心，将引你进入关于水之纯净的新课。诺里克位于洛克莫丹湖畔，将继续萨满祭司的教导。")
zh(94495,"纯净之水能疗愈与新生，而受污染之水则毁坏所及之处。诺里克派你前往湿地的赫尔文达，学习这课后，方可获得萨普塔。")
zh(94497,"赫尔文达希望你借观察水的不同形态与所孕育的生命，理解水的本质。第一份样本取自瀑布底部，淡水与咸水交汇之处。")
zh(94499,"石堡下的水流已被污染，附近鱼人也呈现出异常扭曲。取样调查将助你查明是魔法、毒药，或是某种未知之力所致。")
zh(94500,"阿斯特兰纳的湖水仿佛未受腐蚀侵扰，甚至可能蕴含魔法。赫尔文达需最后一份样本完成比对，再送你返回诺里克。")
zh(94501,"你仍需完成与诺里克的最后一项试炼，方能接受水之图腾的仪式。赫尔文达赐予你所需药瓶，送你返回继续试炼。")
zh(94502,"斯特登的池塘曾纯净无瑕，黑暗之力却已使其灵体沉寂。萨普塔与赫尔文达的准备，将助你直面腐蚀，尝试恢复其清澈。")
zh(94503,"净化仪式的光芒与水化为雾气，伴随堕落灵体的瓦解。留意水之显现，延续这场由净化开启的遭遇。")
zh(94505,"显现托付你一块碎片与一个启示：水维系生命，而腐化终结生命。将它带给诺里克，继续以守护与赋予生命为核心的力量训练。")
zh(94568,"叛逃者因恐惧教派的计划而寻求庇护，却在解释前便已死去。影歌需要讨论遗失的信息，并决定调查该如何继续。")
zh(94616,"诺里克再添一份水之灵契，给那个早已配得此物的人。换上新的饮剂，与此元素相关的萨满法事才能接着做下去。")
zh(94638,"风之魔法的消逝令乌伦德拉陷入疯狂，连自己族人都难逃威胁。她的伴侣要求终结她的痛苦，作为一场痛苦的强韧与仁慈的试炼。")
zh(94773,"劳瑞娜愿教导人类牧师神圣恩典。造访大教堂，可借由这堂课继续在光中修行。")
zh(94774,"你的进展已引起教团的注意。上级认为你已准备好接受更深层的训练，遂派遣你前往暴风城光明大教堂的高阶牧师劳瑞娜。")
zh(94775,"一位牧师前来寻你，请求你返回光明大教堂。你的工作已引起劳瑞娜的注意，族人亦需你回应她的召唤。")
zh(94776,"劳瑞娜欲在光明大教堂与你相见。高阶牧师的私人召见似是对你进展的肯定，你该尽快前往。")
zh(94777,"一位牧师留下了一封紧急信件，指引你前往光之大教堂。他神情透露出好消息，但与劳瑞娜的会面不可拖延。")
zh(94778,"时候到了，该让你证明自己值得在修行中更进一步。劳瑞娜召唤你前往光之大教堂，以展现你作为牧师的虔诚。")
zh(94779,"艾露恩的牧师学会新的能力，反映他们的信仰，而你的教派被认为走的是相似的道路。去找劳瑞娜，继续你的修行。")
zh(94789,"你的萨满修行已到能理解风的阶段，这是难以掌控的元素。雷霆·维因可引导你踏上这新阶段，你须前往阿拉希之末寻他求教。")
zh(94792,"动物伙伴能助猎人存活，但赢得这份羁绊需对自然怀有敬意。约瑟芬借你一根鱼竿，让你练习驯服石皮野猪。")
zh(94793,"你已能驯服宠物，但仍需学习如何训练它们。约瑟芬派你去找伊萨克·钱，一位经验丰富的护林者，教你这门技艺。")
zh(94817,"米姆向侏儒牧师传授一道新技，以闪光扰乱敌人。前往铁炉堡，学习这项新能力。")
zh(94818,"侏儒牧师的训练包括准备防御性回应。米姆在铁炉堡传授这新课，好让你在面对危险时能拓展防护手段。")
zh(94819,"你作为牧师的下一场考验即将来临。米姆召唤你前往铁炉堡，继续你族的仪式，他在秘法区等待你。")
zh(94820,"诺莫瑞根的流放令侏儒牧师备受煎熬，他们守护家人，却渴望重返故土。来自铁炉堡的讯息召唤你回到米姆身边，继续你的修行。")
zh(94821,"一位牧师在长廊中寻找你，他的讯息指引你回到铁炉堡的秘法大厅。米姆会告诉你为何你需要现身。")
zh(94822,"你的长官认为你已证明自己足以进阶。他们派遣你前往铁炉堡秘法大厅，向米姆请教，继续你的修行。")
zh(94823,"你的奉献已引起牧师们的注意，有人前来寻你。返回铁炉堡找米姆——你的族人需要你回应召唤。")
zh(94824,"米姆命令你前往秘法大厅与她相见。这道召唤似乎认可了你的进步，切莫让她久候。")
zh(94825,"一位牧师留下重要讯息，指引你前往秘法大厅。他的态度透露出好消息；立刻前往铁炉堡找米姆。")
zh(94826,"在这一阶段，艾露恩的牧师会获得反映他们信仰的力量。你所属的教派或许也有类似教导，去找米姆继续学习。")
zh(94863,"驯服野猪后，你须学会赢得更凶猛生物的信任。乔瑟菲娜的下一课，将教你如何与森林灰狼建立联系，并尊重自然的平衡。")
zh(94864,"你已驯服野猪与灰狼，最终的考验是赢得幼熊的信任。这将加深你与野兽的羁绊，同时尊重艾尔文森林的平衡。")
zh(94872,"玛格拉的扩张令人担忧，但也可能成为潜在盟友。一袋图腾或许能赢得他们的信任，但不可忽视他们日益增长的统治力所带来的危险。")
zh(94873,"吉尔吉斯的弱点或许使他们更易接受外来援助。一袋图腾或许能促成与日渐被玛格拉压制的部族结盟的机会。")
zh(94896,"村庄开始往天上坠时，难民们逃出了班阿瑟塔尔。流亡的村民回去太过凶险，艾拉娜只好托人取回他们的家当。")
zh(94897,"雷斯安返回班阿瑟塔尔取补给，却已失踪一周。他的同伴忧心忡忡，托你寻找他，若他已逝，便找回他的传家宝。")
zh(94911,"你的德鲁伊誓言召唤你继续学习。雷霆崖的图拉克·符文图腾可教你如何抵达月光林地，并从塞纳里奥议会汲取智慧。")
zh(94912,"要拯救家园，你须深入学习德鲁伊技艺。沙德拉斯·月树可教你如何抵达月光林地——古老塞纳里奥议会的堡垒。")
zh(94913,"月光林地欢迎所有在雷穆洛斯庇护下的德鲁伊。你的新法术将带你前往那里，接受德迪利特对你艾泽拉斯旅程的第一份指引。")
zh(94914,"德鲁伊在月光林地寻找知识与慰藉。现在你可以瞬移至那片圣域，德迪利特将引导你踏上艾泽拉斯的第一步。")
zh(94946,"邪教危机让艾拉德林被困在瓦兰达尔。其他法师已在达拉然等待你的族群，趁泽弗拉斯的事务未定，你该出发探索。")
zh(94947,"高等秩序需要探索艾泽拉斯并结识盟友。肯瑞托与联盟的纽带为你开辟通往暴风城的路线，你必须以艾拉德林的名义在此与伯瓦尔相见。")
zh(94978,"你的第一场猎人试炼关乎兽与主之间的羁绊。从泽弗拉斯的水域开始，驯服一只风歌海蟹，证明你值得它的信任。")
zh(94979,"驯服海蟹后，你需在开阔地带测试自己的能力。低地的风行者将成为下一位需要你赢得信任的伙伴。")
zh(95034,"露米娜揭示，最初袭击队伍的是狼人，巴诺保护她，却被咬伤。豺狼人在他们撤退时找到他们，听她讲述，才明白他们被捕的原因。")
zh(95036,"老火眼，那个袭击露米娜的狼人，似乎借着未知魔法从死亡中归来。或许需要一把特殊武器才能阻止他；特雷凡知晓打造它的材料。")
zh(95041,"耶玛在逃离诺莫瑞根前复制了家族的档案，却因背包破洞丢失了部分卡片。没有这些卡片，设计图、公式与记忆仍无法解读。")
zh(95042,"柯尔宝石用于强化圣骑士的魔法武器与法器。若想获得一颗，需深入黑暗深渊的娜迦群中搜寻，这是一场危险的远征，需同伴与准备。")
zh(95065,"吉尔在暴风城港湾钓鱼时已缺饵，他向凯瑟琳·利兰求助，好继续享受水边的宁静时光。")
zh(95111,"奥特看似只是普通铁匠，却令幽暗城的工匠们刮目相看。你的联系人希望给予他非凡机会，遂送来材料与打造新剑的委托。")
zh(95125,"奥特认可材料的品质，也珍惜对匠艺的信任。他需要空间，以打造一把足以回应委托的利剑。")
zh(95126,"利剑已成，奥特想向特雷文致谢，将这份锻造机会的感激带回给信任他的那个人。")
zh(95140,"新剑备齐，露米娜请你前往吉尔尼斯城门附近，直面老火眼。这把特殊武器必须在攻击她的狼人身上试锋，以护全境安宁。")
zh(95161,"寻找杰里米·心织的线索，引你至暮色森林的艾瓦特·菲尔伍德——他的新养母。孤儿院仍照顾着这孩子，盼你带话，告诉他他们始终挂念着他。")
zh(95189,"斑驳的纹章上留着洛丹伦的印记。如今王国遗物寥寥无几，将它送到暴风城，或许能落入懂得珍视它历史意义的人手中。")
zh(95195,"染血的徽记似乎属于一名洛丹伦士兵。废墟中或许还藏着类似的勋章，将它们送回活着的亲人手中，或许能找回王国覆灭时遗失的过往。")
zh(95204,"这枚纹章保存着一个王国的象征，而王国遗物已所剩无几。幽暗城中或许有人珍视这份回忆，将它送去城中，或能找到真正该拥有它的人。")
zh(95212,"山羊正被送往增援奥特兰克远征队，但鞍具材料已告罄。那片严寒之地，急需大豹皮来为士兵们御寒。")
zh(95213,"空桶上的警告标志表明它曾是采石场炸药容器。它出现在地精群中，令人不安；请尽快将发现告知瑟斯丁。")
zh(95214,"被盗的炸药威力足以造成巨大破坏。瑟斯丁必须在地精弄清如何引爆之前，将它夺回，以免酿成灾难。")
zh(95216,"萨多雷正在研究一种栖息于废墟的节肢生物，据说它的毒液连亡灵都能腐蚀。他需要样本验证传言，并深入研究极端致命的毒素。")
zh(95217,"补给船迟迟未到，弗拉斯特急需材料修缮营地。若你能寻得，他将分享锻造技艺，使双方皆有所获。")
zh(95250,"图曼坚守岗位，听从上级命令，而这位上级已在别处征战许久。尽管他对你的战力存疑，仍要你去找总治安官，称他是个无可争议的英雄。")
zh(95314,"黑影谷曾酿造一种被禁仍受追捧的药剂。卡罗莱找到买家，要你去废墟村庄搜集瓶子，以满足他们的需求。")
zh(95328,"黑影谷那生物的残骸仍未散去，令人不安。将它们带给幽暗城的兰克斯特神父，让他检验残留物，看看是否能派上用场。")
zh(95349,"教派危机迫使艾耶莎留在瓦兰达尔。你与其它风行者将作为先锋前往艾泽拉斯，阿拉娜·雷暴行者已在莫高雷等待接应。")
zh(95350,"风行者要生存，必须结交新盟友。前往奥格瑞玛，代表你的族群拜会部落酋长萨尔。")
zh(95384,"卷轴上的符号你无法解读，但其中并无明显不稳定之力。一位收集奇术的收藏家，或许能用这种你未曾听闻的语言。")
zh(95494,"你的联络人因腿部伤势无法狩猎，但责任仍在。需收集最大狮子的兽皮，你被委以协助搜集之任。")
zh(95495,"兽皮要送到一位独居山脊的制革匠手中。联络人伤势未愈，无法攀登，你得送去并保证隐士无害。")
zh(95507,"弗朗恩·凝血在山谷各处设下陷阱，需你在旅途中检查。带回些小动物，同时留意此地危险的野生动物。")
zh(95508,"沃尔顿因杜隆塔尔战役中平民被处决一事辞去了库尔提拉斯海军的职务。如今有人正从山脊上逼近，他需要协助度过这场遭遇战。")
zh(95534,"一封烧焦的信件描述了风箱在无人看管时似乎自行运作，以及斯坦恩布莱德深处蕴藏着巨大能量。调查这异常现象，将揭示这究竟是谣言，还是隐藏着更深层的秘密。")
zh(95621,"库尔提拉斯士兵正在山谷中搜寻某物。调查他们驻扎在失事车队旁的营地，弄清楚他们为何而来。")
zh(95646,"腐败之气从湿地上升，影响那些对它抵抗力较弱的生物。你的联系人通过根系感知到这股污染，需要高地恐怖的核心来对抗这股危害。")
zh(95647,"阿尔丁听闻探险队提及某些稀有植物，便独自前往寻找。他已失踪太久，妻子急需消息，想知道他的草药天赋是否将他引向了危险。")
zh(95663,"风言说龙喉氏族又有了新打算，要用他们那手厉害的束缚法术。零碎的低语不足以让死亡追踪者动手；营地高处有一名探子，正需人手帮他摸清这威胁的底细。")
zh(95664,"这块复合碎片折射出奇异的光，似乎蕴含着古老的魔力。它的本质尚不明朗，长者高地上的智者或许掌握研究这类神器的知识。")
zh(95682,"龙喉氏族相信他们已找到足以重振昔日荣光之物。清理挖掘现场可让死亡猎手潜入而不被察觉，而获取的信息必须严守在指挥行动的统帅手中。")
zh(95697,"博斯坦想借大胆的家常菜吸引新顾客。挖掘现场的迅猛龙提供机会，让他的菜单超越那些他认为餐厅应超越的简陋村餐。")
zh(95737,"学者的书信里提到一支探险队寻见的上古植株，可消息到它能否到手那一节便断了。找到凯特林·格拉斯曼，既看她是否安好，也让这往来问答重新接上。")
zh(95748,"石板记载伊拉莱曾是庞大文明，与礁石上可见的残骸矛盾。复制另一聚落保存的传说，将有助于研究这差异，并更深入理解那座失落之城。")
zh(95770,"传说指的地方大致不差，只是有一处洞窟可能被漏掉了。往礁石以西去探，既找那条断掉的线索，也查清是什么把纳迦引到那里。")
zh(95772,"戴温随一支探险队进了人迹稀少的深山，没照常捎信回来。他兄弟被锻造活计绊着，脱不开身，只得托人问问他的境况——那头沉默，已让人愈发不安。")
zh(95773,"纳迦正聚集在水下遗迹附近，而守卫者已面临陆上攻击。他们无法再承受海上攻势，需将入侵者击退，并归还三叉戟以证明你的效劳。")
zh(95774,"曼科里克想为奥尔格拉立碑纪念。她的打磨骨饰从遗体上消失；从奎尔博尔处取回它们，好加入献礼之列。")
zh(95775,"洞穴之外的废墟可能属于伊拉莱，蕴藏着无价的失落知识。你的联系人年事已高无法进入，召集盟友复制石碑，让研究在他缺席后仍能继续。")
zh(95776,"娜迦的数量暗示着威胁远超海岸巡逻。金·维莱怀疑他们正在寻找沉没之城中的某物；阻止他们的首领，旨在阻止一场可能危及据点安全的发现。")
zh(95795,"矮人的遗体揭示了他远征的终结。用他的斗篷覆盖遗体后，将消息亲自带往多林处，让他得知他期待已久书信中提及的兄弟遭遇。")
zh(95803,"丹妮莎希望希尔瓦娜斯看到，她的教团会阻止攻击其他亡灵的圣骑士。你携带的指挥官首级，是为赢得政治信任而做出的姿态。")
zh(95805,"安瑟与穆沙以光赋予生命与希望。为致敬他们，携燃烧的熏香前往他们的神龛，让香火不熄，让香灰不湿。")
zh(95809,"阿尔丁需先休养，方能沿清理后的路线返回。一束由芦苇编织的心，将凯特林·格拉斯曼的消息带往远方——他尚存，期盼早日归来，而他仍在收集离别的所需之物。")
zh(95810,"自动体残骸的成分陌生，似乎属于某种装置而非碎石。维尔加或许能解释这件遗物，并协助辨识留下残骸的机械。")
zh(95816,"这份形体可申请有限权限，用于在艾泽拉斯跨区宣传交易。将它交予合约协调员，由负责该授权的商业机构开始处理。")
zh(95817,"洛特加斯以快速打造简单设计而闻名，他帮助新设立的工坊站稳脚跟。在铁炉堡的技艺，是你获取招牌的可靠途径。")
zh(95819,"宣传你的手艺需要有限且可撤销的许可。表格必须送达杜隆塔尔补给与后勤合约协调员，才能开始展示招牌的授权流程。")
zh(95883,"仓促准备的仪式仍需鲜血与被折磨的灵魂。据旁侧祭坛旁残缺的指示，附近的亡灵或许能提供这关键成分。")
zh(95884,"几乎无法辨识的笔记保留着关于供品与仪式的提及。找到笔记中提及的石头，便能循着准备步骤，发现仪式的场所。")
zh(95885,"准备已就绪，唯独缺少鲜血供品。笔记要求自愿的牺牲，其含义令你面对仪式最终要求时，感到深沉的恐惧。")
zh(95981,"奥利斯特希望阻止达拉然的古物供应，而非仅仅夺取现存的挂坠。对抗道路上的法师与守望者，或许能切断这股来源。")
zh(95998,"萨姆相信冒险者需学会在荒野中生存。他邀请你坐在他火堆旁，聆听他的建议，愿学之人，他乐于分享经验。")
zh(95999,"加里姆领导着兽人的突袭，可能正与石堡的黑石势力勾结。悬赏旨在阻止他与那些危险的法师，断其断杖交予所罗门作为证据。")
zh(96016,"维里克虽无丰厚报酬，却知一位风暴专家。将核心带往巴特拉赫，或许能让那元素之力化为你胜利的利器。")
zh(96031,"皮革工艺能为营地抵挡烈日与风雨。学会制作帐篷，便将你的职业与旅行者对庇护休息的基本需求相连。")
zh(96044,"锻造可为营中同伴提供庇护。学会打造磨刀石，能让他们的武器始终为前行之路做好准备。")
zh(96045,"炼金术可为营地提供稳定的法力源泉。待你技艺精进，沃萨·布拉克塞尔便能教你制备药剂，为治疗者与法师带来清凉解渴的慰藉。")
zh(96046,"采矿可为营地添置磁石。继续精进此技，便能为迎战险途的同伴备好武器。")
zh(96047,"冒险总会留下伤痕，营地亦需照料。你的急救知识，可化作药箱，助他人在旅途中重拾生机。")
zh(96050,"钓鱼不止于填饱肚腹，更能为休憩的同伴带来慰藉。鱼缸中的水波，是他们重战前夜的精神滋养。")
zh(96055,"你采集的草药可化为营火熏香。你的职业，正支撑着依赖魔法前行的同伴们休憩与精神。")
zh(96056,"回收的兽皮可制成火堆旁的座椅。剥皮能在旅途中助力恢复，因驱散疲惫能让同伴保持警醒。")
zh(96057,"裁缝可为营地缝制旗帜。为同伴赋予共同象征，能增强他们的士气与归属感，待重返战场前。")
zh(96058,"工程学能为法师提供所需材料。学会打造补给自动体，使营地成为众人共谋前路的据点。")
zh(96059,"附魔能提升休息与装备。一把附魔鲁特琴，可为营地带来音乐与魔法，助同伴整装待发。")
zh(96101,"拉安相信冒险者需学会在荒野中生存。你被邀请坐于火堆旁，聆听一位同行者的建议与经验。")
zh(96102,"裁缝可为营地缝制旗帜。为同伴赋予共同象征，能增强他们的士气与归属感，待重返战场前。")
zh(96130,"查库亚，一头异常凶暴的狼，威胁着石牛湖西边的旅人。将其击杀并带回皮毛作证，其他猎手或许能助你一臂之力。")
zh(96135,"图腾的腐化使昆布拉的元素生物得以召唤。维里克派遣你前往富含四元素的蒸汽池，筹备防御并直面仪式的反击。")
zh(96136,"引导艾泽拉斯的元素之力，需从泽弗拉斯所学之外汲取。你的导师更愿将你送往此世的启蒙者，而非直接赐予空气图腾。")
zh(96137,"伊拉的匕首铭刻着她守护旅人的过往。如今她的灵体仍在游荡，或许需要有人阻止那持续吞噬牺牲品的狼人。")
zh(96138,"梅里克曾以守护道路为荣，如今他的灵体仍徘徊其间。他的弓暗示未竟之事，或许牵涉威胁乌鸦岭家园的巨魔。")
zh(96139,"乌鸦岭的历史与众多居民一同湮灭。希拉希望留存守护此地者的记忆，任何有助于重建他们生平与勇气的发现，皆是助力。")
zh(96204,"露米娜虽已脱出牢笼，芬里斯堡里的凶险仍在。她要一路杀出去，让囚她的人付出代价；可出堡这一路，她仍要你守在身旁。")
zh(96222,"玛洛迪仍立于不败之地，而其他氏族正彼此争斗。赫拉塔的碎片或许能成为谈判筹码；以他们的角挑战他，或可赢得先机。")
zh(96241,"关于暗影崛起蜘蛛毒液的传闻，已引起马祖昆的兴趣。他的提取器将从被咬者尸体中采集样本，探究这毒素非凡的特性。")
zh(96243,"作为萨满，你需学会倾听大地、强化与它的羁绊。铁砧城的泰欧·重型钉锤正等待，以引导你完成这段修行。")
zh(96259,"暮光之上的蜘蛛威胁着莫高雷，更毁坏了一处古老的牛头人墓地。终结这场虫灾，既是为活人，也是为守护祖先安息的圣地。")
zh(96260,"一名侦察员从暮光之地归来，身负重伤且浑身缠满异常坚韧的晶丝。现有样本不足，获取更多将有助研究其特性，并赢得奖励。")
zh(96261,"蜘蛛的迅速蔓延暗示着一位强大的母后。终结这场虫灾，需找到并阻止她，而盟友或许能助你一臂之力——这些生物的举止绝非寻常。")
zh(96264,"元素之力曾助你磨练，如今却需你以守护回报。大地警示有魁伯兽仪式即将展开，调查其领地将收集到有关力量准备的证据。")
zh(96294,"被击败的母后竟是化为扭曲兽形的暗夜精灵德鲁伊。她衣袍间的一张纸条，或能揭示暮光之地蜘蛛虫灾的起源与目的。")
zh(96339,"客栈老板已保管好寄给你的包裹，愿交予你。其中是一把铁炉堡仿制的气枪，通过此交易便可获得。")
zh(96383,"威利又收到一位无名仰慕者寄来的包裹。他的提议让你可收集随礼物而来的幽灵熊幼崽，无需知晓是谁所送。")
zh(96390,"黑铁间谍已潜入丹莫罗，目的尚不明确。务必在铁环营地阻止他们，莫让问题越演越烈。")
zh(96391,"地图显示铁炉堡地底有隧道交汇，标记着黑铁族的符文。风中低语让你确信，法尔森必须亲眼见到这可能的地下威胁。")
zh(96392,"法尔森在丹莫罗巡视时，察觉到黑铁族的动向。他想借魔法向你展示局势，好让你明白问题所在。")
zh(96393,"法尔森认为杜尔根领导着潜伏在旧铁炉堡地下的黑铁族。集结盟友，深入下层密室，将这名可疑的指挥官头颅献给麦格尼。")
zh(96394,"泰兰大厅的墓穴已被扰动，地窖中传出异响。查明扰动之源，唤醒沉睡的亡者，还他们安宁。")
zh(96395,"旧怨折磨着这位领主，让他无法安息。幽灵侍神者恳求你的协助，为法尔德里安威玛尔带来和平。")
zh(96403,"黑铁族已借钻探机潜入密室。你的线人希望夺回矮人遗物，并承诺会妥善记录，但对战利品的热情令人存疑。")
zh(96408,"有登山者在古博拉采掘场上方山腰高处望见一堆营火。查明是谁占了营地，来客是否怀有敌意。")
zh(96604,"布拉克认为冒险者需学会在荒野中生存。你被邀请围炉而坐，聆听一位同行旅者的忠告。")
zh(96605,"卡加·迷雾行者认为，冒险者必须学会在荒野中生存。你被邀请坐在营火旁，聆听一位同行旅者的建议。")
zh(96606,"莉蕾娜认为，冒险者必须学会在荒野中生存。你被邀请坐在营火旁，聆听一位同行旅者的建议。")
zh(96607,"埃利亚诺认为，冒险者必须学会在荒野中生存。你被邀请坐在营火旁，聆听一位同行旅者的建议。")
zh(96608,"艾瑞克认为，冒险命者必须学会在荒野中生存。你被邀请坐在营火旁，聆听一位同行旅者的建议。")
zh(96626,"营火既是休憩之所，也是烹煮食物的媒介。这第一课，教你如何在外围据点之外延续旅程。")
zh(96627,"你作为守护者的职责，已证明你的能力。如今，你将接受一项不寻常的任务：前往闪金镇附近，见见那位新冒险者，了解他在做什么。")
zh(96628,"山民们报告，有冒险者在卡拉诺斯外扎营。在继续前往隧道前，你被要求带去一捆补给。")
zh(96629,"营火既是休憩之所，也是烹煮食物的媒介。这第一课，教你如何在外围据点之外延续旅程。")
zh(96630,"这本笔记记载了一位陌生人游历各地的见闻，反复提及露营，似乎自有其乐趣。将笔记本带给多兰纳尔附近的莉蕾娜·暮刃。")
zh(96634,"营火既是休憩之所，也是烹煮食物的媒介。这第一课助你在外围城镇之外维系远行。")
zh(96638,"一位冒险者曾在申达尔之路扎营。突破滕达尔的局限，需靠知识，而你的联系人认为他的经验或许能助你一臂之力。")
zh(96646,"营火既是休憩之所，也是烹煮食物的媒介。这第一课助你在外围城镇之外维系远行。")
zh(96652,"这本朴素笔记记载了一位陌生人游历的见闻，反复提及露营。将此笔记带给剃刀岭附近的布拉克·碎盾。")
zh(96655,"营火既是休憩之所，也是烹煮食物的媒介。这第一课助你在外围城镇之外维系远行。")
zh(96656,"你对抗血色十字军的行动赢得了阿伦的信任。他请你调查一位冒险者，由此打开一条超越丧钟镇军事职责的联系。")
zh(96658,"营火既是休憩之所，也是烹煮食物的媒介。这第一课助你在外围城镇之外维系远行。")
zh(96659,"卡加·野蹄曾大力协助过你的联系人。为报此恩，你需将物资送往血蹄村旁的她驻地。")
zh(96661,"营火既是歇脚之处，也是烹饪之源。这第一课教你如何在外围据点之外维持远征的体力。")
zh(96774,"马祖·孔想要研究一件与古拉巴什血魔法相关的真银雕像。与盟友深入沉没之城，或许能从牧师处寻得，并考察那些古老仪式的遗物。")
zh(96779,"拉文霍德计划以精准一击削弱辛迪加。托马斯领主是敦霍尔德运作的核心，迅速悄无声息地除掉他，或可重创整个组织。")
zh(96781,"辛迪加正在奥特兰克寻找某样东西，巴顿的报告掌握着答案。窃取情报而不杀他，能避免惊动组织，保留调查的机会。")
zh(96782,"报告揭露辛迪加正在搜寻两件匹瑞诺德家族的遗物。先夺回它们，便可阻断他们的行动；你的潜入技巧或许能让你避开兽人而顺利通过。")
zh(96783,"辛迪加一桩要紧买卖的底细，藏在激流堡里面。从堡垒外的成员身上弄一套装束，混进去不叫人起疑，再看清他们正备下什么交易。")
zh(96784,"伪装让你能更自由地接触辛迪加成员。依照米罗科斯的指示，借这身份打听激流堡内那项重要交易的详情，而不暴露你的调查目的。")
zh(96785,"你的联系人不愿向他们眼中的菜鸟透露上司的机密。唯有重要或珍贵之物，才可能说服他们，情报的获取，取决于以值得信赖的条件化解那份戒心。")
zh(96786,"法库雷斯特公爵已派遣手下在索拉丁之墙南端的秘密交接点待命。就连负责收货的人，似乎也对货物内容一无所知；调查这场会面，或许能揭开你线人勉强解释的线索。")
zh(96800,"对蛮锤部族符文大师的研究，需要一本杜安从未归还的书籍。从血色修道院取回它，将完成论文，并补全自第三次战争前便遗失的典籍。")
zh(96821,"在剃刀岭路旁筑巢的蜘蛛，让过往变得困难重重。清除部分威胁，回报这条路线已恢复安全通行。")
zh(96822,"部落在提拉加德一役中折损战士，人类增援又阻碍了遗骸的回收。他们遗弃的武器，仍可用来缅怀逝者，铭记他们的牺牲。")
zh(96825,"士兵们获得肉和鱼，却难得尝到甜食。托尔卡想要在食人魔营地附近生长的仙人掌果；采集时需格外小心，因其尖刺令人防不胜防。")
zh(96873,"扎拉赞恩借魔戒操控俘虏的意志。帕祖拉提议通过剥离那魔力来练习附魔，无需亲身佩戴魔戒，便可避免失去自由。")
zh(96874,"乌格托克相信雷霆山脊野兽的尖刺，能铸成一把强力战斧。你的锻造课，便要收集这些尖刺，搭配磨石研磨，打造锋刃。")
zh(96875,"奥格瑞玛的扩张需要皮革来铺设墙壁与屋顶。卡玛瑞提议使用雷霆山脊的蜥蜴皮，这种皮料虽厚实不适合做铠甲，却极适合建筑用途。")
zh(96876,"乌克尔的名字歪歪扭扭缝在包袱的盖布上。凭这记号便能认出失主，把丢失的物件还回杜隆塔尔南部。")
zh(96877,"你已击败哈利科尔，巨蜥的蹄子成为这场战斗的战利品。将它带往奥格瑞玛，作为你功绩的见证。")
zh(96895,"两名银色黎明的使者曾扰乱当地守卫。你需寻找一名接近幽暗城的使者，可疑的邪教活动或许能解释他的现身。")
zh(96896,"莱尼德记得曾并肩作战的战友，他们为抵御纳克萨玛斯而死于幽暗城，包括加瑞克·班达里昂。聆听丹妮莎的讲述，能让你明白为何她那些亡灵圣骑士的事业仍牵动着旧日盟友。")
zh(96897,"天灾军团的活仆从又给提瑞斯法添了一重祸患。趁邪教的事还没做绝，你要将它搅散：这片土地已受无脑的亡灵与血色狂热者侵逼，再经不起折腾。")
zh(96898,"纳克萨玛斯的袭击后，一些亡灵法术水晶碎片仍散落各处。哈德里克担心邪教将重获这些碎片，因此请你优先处理这些危险的残余。")
zh(96899,"对抗邪教让你与银色黎明及提瑞斯法的圣骑士走得更近。在城堡与莱尼德会面，能更清晰地理解你们共通的使命。")
zh(96984,"达拉然的灾难将波及幽暗城，迫使双方勉强合作。一把魔法钥匙可穿透结界，通往紫罗兰城堡。在那里，遏制危机必须凌驾于投机取巧之上。")
zh(96986,"一位亡灵巫师在达拉然之下集结军队，背叛了亡灵的信条。你的联系人希望你阻止他，不是为了拯救法师，而是为了证明无人能逃脱萨尔娜莎的掌控。")
zh(96987,"达拉然的危机让法师们分心，也给了偷取珍贵知识的机会。你的搭档提议盗取秘藏典籍，变卖所得，分享利用城市动荡所获的利益。")
zh(96988,"一位炼金术士欲借混乱研究造物核心。他梦寐以求以奥术之力造出憎恶，博取希尔瓦娜斯的青睐；你的任务，是为他的野心收集尚未完成的零件。")
zh(97003,"传闻里，卓尔·阿鲁克是一头硕大无朋的野猪人，嗜血成性，怎么也喂不饱。你的联络人亲身领教过，对此深信不疑，要你召来人手，把这东西堵死在它的巢穴里。")
zh(97005,"传言在荆棘岭有生物能吞噬兽人。你的联系人曾失去同伴于类似存在之手，如今希望卓尔·阿鲁克死；准备一支强援并肩作战的远征队。")
zh(97047,"一名探险者在丛林中遭伏击并被囚禁。他谈及老虎与头骨巫师，惊恐万分；在他弄清俘虏意图前，务必要找到钥匙或另寻脱身之法。")
zh(97048,"获救的厨师尚无力立即报恩，只能在阿兰萨斯号上服役。他请求你与藏宝海湾的船长谈谈，希望他的归来能换来对解救之恩的感激。")
zh(97065,"渔夫愿以数条美味鱼换得基佛天使鱼，视其为公平交易。")
zh(97066,"一名渔夫愿意拿鲜美的鱼，换你钓上来的布朗内尔的蓝纹快鱼。")
zh(97067,"迪森皇后鱼令买家惊讶不已，但最划算的交易仍是几条美味鱼。")
zh(97220,"码头工人短缺导致货物延误，菲尔莫尔急需一批货物秘密送至尼鲁巴尔门房仓库，位于提亚斯奶酪店楼上。")
zh(97222,"提亚斯店铺与仓库共用一层，却不负责管理存货。将木箱留在楼上门口，守卫自会前来取走。")
zh(97223,"血爪主母已杀害森金村民，威胁日益加剧。萨拉·提亚欲终结此祸，令她的幼崽成为盟友，需先取回她的蛋。")
zh(97225,"扎拉赞恩仓皇逃窜，迫使部落遗弃用于与洛阿沟通的神像。追随者们粗暴地散落这些圣物，若能寻回，或可避免严重的精神冒犯。")
zh(97234,"读书会欲以冷门书籍换取现代作品，将材料送至图书馆完成约定交换，获取新鲜阅读。")
zh(97236,"一只大型蜘蛛的新牙，是难得的标本。有人在奥达希尔研究这些生物，或许会对这个发现感兴趣。")
zh(97237,"图书馆里有罗伊要的所有书，但你得从书架上取来。作为俱乐部的信使，你可以将它们送出去，而不必负责它们的归还。")
zh(97242,"耶尔玛克想帮助他的骄傲学徒，又不让他觉得被宠坏。收集当地植物，配制一款隐秘的配方，以达成一次低调的干预。")
zh(97243,"尽管泽弗拉斯位于天空之墙，但四元素的灵体皆在那里低语。奥莉亚瑞安与火焰有特殊联系，他的神龛能指引你的学习。")
zh(97244,"法拉迪尔拿风塑者的信义换来了邪教的力量，还杀了从前的同伴。奥莉亚瑞安要用他的心脏行火之仪式——此事冷酷，却非做不可。")
zh(97245,"库拉玛亚栖身于申达高地的一棵扭曲树桩。召唤并击败那古灵，取下它的面具；火焰是克服它对魔法抵抗的关键。")
zh(97246,"米吉白天玩耍，跳过午餐后回家便饿了。他的父亲无法脱身，需要你去取博斯坦准备的餐点并送过去。")
zh(97249,"博斯坦希望米吉能规律进食，又不总吃他最爱的那道菜。他准备了一顿多样化的午餐，配上最爱的配料，鼓励男孩回来。")
zh(97250,"情报显示，人类士兵在指责部落引发酒馆火灾后，开始摧毁牛头人的标记。劳格玛不知真相是否属实，但希望在调查前阻止他们的入侵。")
zh(97253,"海盗们杀死了维尼克斯派来对付他们的敌人，并拆毁了替代他们的机械。现在他需要从他们的营地收集散落的零件。")
zh(97257,"仪式将材料献给灵体，以点燃永恒之火。用你的火把捕捉它，并尽快送往瓦兰达尔，因火焰之地的烈焰在天空之墙会迅速消散。")
zh(97263,"邮箱旁错放的包裹中，有一封紧急信件给风暴破者伊尔德伦。从鹰巢山寄往铁炉堡，如今需要完成中断的投递。")
zh(97265,"曾许诺力量与知识，却因树妖抛弃你的联络人而沦为耻辱。如今他想向怨怒萨特复仇，以暴力回应那未兑现的交易。")
zh(97275,"伍特天资不俗，却因急躁浪费稀有材料。耶尔玛克希望一瓶简单的药剂，能让他明白本地草药的价值与炼金术的用心。")
zh(97277,"一只豹子袭击了戈兹温，令他受伤。找回他的机械日志，并阻止那头野兽，以免再次发生袭击。")
zh(97279,"新兵们正耗尽训练武器的供应。回收那些被失败者丢弃的武器，不仅能补给克赞，也能展现你的主动性。")
zh(97281,"一只鹰身女妖携带的球体中封存着浓雾与细小的电光。其用途尚不明朗，但雷兹拉克或许会对这奇特的发现产生兴趣。")
zh(97282,"雷兹拉克认为这球体是被抽空而非破碎。他希望借助雷霆蜥蜴的器官，恢复其能量，这些器官能承载强烈的电荷。")
zh(97284,"玛雷姆若还活着，掳她的人多半料定会有人来寻。瓦拉里尔不愿声张，却也明白一路必遇顽抗；她要你一边搜寻，一边削弱火刃氏族——这场搜寻，想不惊动旁人是办不到的。")
zh(97286,"欧文·塔德或加里昂·温德尔可继续你的法师训练。他们的提议让你能学习研究术，并通过他们的指导拓展知识。")
zh(97287,"肯瑞托掌握的知识，甚至超越了你盟友的成果，促使他们希望获得该教团的准入。找回的光点或许能成为筹码，影响那些渴望夺回它的法师。")
zh(97288,"憎恶的头颅在身躯坠落时脱落，显示出多次重新连接的痕迹，而每次连接都比前次更薄弱。幽暗城中或许有人了解这种不寻常的生物。")
zh(97289,"法拉尼尔认出这颗头颅生前是联盟的大元帅，死在希尔瓦娜斯手里。他相信只要配上一具合适的躯体，它仍能吐出秘密，要你把它搁到一具现成的宿主身旁。")
zh(97290,"这生物几乎无法开口，却拒绝协助并要求你离开。将此抵抗情况报告给法拉尼尔，让他知晓他在获取情报时所遭遇的回应。")
zh(97291,"头颅已断，但法拉尼尔仍想将其与萨尔瓦娜意志相连。他需毒草与苦楚精华炼制药剂，以迫使新俘虏臣服。")
zh(97292,"法拉尼尔已制好药剂，可迫使俘虏效忠。将之注入上方滴落的装置，切勿让自身接触这危险的混合物。")
zh(97326,"孩童们常在格罗玛什要塞后方玩耍，却缺少桌椅。他们需中等大小的圆石，以布置空间并休憩。")
zh(97328,"飞艇残骸显示，与藏宝海湾有关的货物遭劫。两趾足迹指向遗迹，循此可查明劫货者身份。")
zh(97329,"地精信使因飞艇坠毁与巨魔掳走而失去首条商路。他坚持若你取得笼子钥匙，他可独自脱困，挽回惨败。")
zh(97331,"齐姆基忆起曾被巨魔捕获，信心动摇。即便钥匙在手，仍需护卫以防重捕，且需留一地让敌人围剿。")
zh(97420,"工匠正为千针石林赛事调试新座驾，需更多动力。风行公司燃料或可助其一臂之力，遂提议秘密获取。")
zh(97485,"牛头人遵循散香于风的传统。你可参与，以城中商贩之香料调制，于猎手岭焚之。")
zh(97538,"塔赫的朱砂颜料已告罄，需你协助前往石爪峰。暗色湖的迷蕨荚干枯后会呈现此色，可补足物资。")
zh(97539,"医疗所必须维持运作，即使营地遭忽视与围攻破坏。蜘蛛丝可制成临时缝合线，为工人与守卫补给物资。")
zh(97558,"亡灵的皮肤受损后需更换，而非如活体般自愈。舍伦尼需要材料修复躯体，揭示你新生活的日常所需。")
zh(97583,"那团小黏液试图模仿你的舞步却力竭而终。淤泥能恢复其能量；在幽暗城的运河中寻找更多，可喂养你的新伙伴。")
zh(97891,"亚历山德罗的药剂保鲜期极短。他的膝盖无法奔跑，故需你迅速将它送往对岸的费尔本医生。")
zh(97894,"博古斯与弟弟断了音讯，自从高尔博德成为奥伯丁商人。探望他，将贸易任务转化为对家人的牵挂回应。")
zh(97899,"炼金术可为营地提供法力源泉。你将被引荐给导师，随着技能提升学习制作法力药剂，为治疗者与法师提供清凉解渴之饮。")
zh(97900,"锻造技艺能支持营地休憩的同伴。学会打造磨刀石，可确保他们的武器始终锋利，迎接前方挑战。")
zh(97901,"附魔不仅能提升装备，也能助人安眠。一把施法的鲁特琴，能为营地带来音乐与魔法，助同伴们为下一段旅程做好准备。")
zh(97902,"工程学能为施法者提供所需物资。学会打造补给自动体，让营地成为众人共同准备的据点。")
zh(97903,"冒险难免受伤，营地也需照料。你的急救知识可化为药箱，助同伴在旅途中恢复元气。")
zh(97904,"钓鱼不止能带来食物，更能为营地增添慰藉。准备一个鱼缸，让休憩的同伴安心，他们的精神是面对危险时的底气。")
zh(97905,"你采集的草药可制成熏香，为依赖魔法的同伴提供庇护。你的职业，支撑着他们旅程中的安宁与灵体。")
zh(97906,"皮革工艺能为你打造遮风挡雨的庇护所。学会制作帐篷，让职业与旅者对安全休憩的基本需求紧密相连。")
zh(97907,"采矿可为营地提供磁石，指引方向。持续精进，助同伴以武器迎战旅途的险阻。")
zh(97908,"回收的皮革可制成火边的座椅，剥皮技艺助旅途恢复元气，缓解疲劳方能让同伴始终备战。")
zh(97914,"桑迪斯·织风希望奥伯丁的技艺被铭记，而非被失落之城的传说掩盖。新航路让他的书信得以抵达暴风城的巴隆斯·阿历克斯顿。")
zh(97915,"炼金术能为营地提供稳定的法力源泉。你将遇见一位导师，随着技能提升，教你制作法力药剂，为治疗者与法师带来清凉的慰藉。")
zh(97916,"锻造能为休憩的同伴提供支持。学会打造磨刀石，让他们的武器始终锋利，迎接前方的征途。")
zh(97917,"附魔不仅能强化装备，也能提升休息品质。一把魔音琴将音乐与魔法带入营地，助同伴们为下一段旅程做好准备。")
zh(97918,"工程学能为法师提供所需物资。学会打造自动体，让营地成为团队协作、准备物资的据点。")
zh(97919,"冒险常伴伤痛，营地亦需疗愈。你的急救知识可化为药箱，助同伴们在旅途中恢复元气。")
zh(97920,"钓鱼不止于填饱肚子。准备一个鱼缸，为休憩的同伴带来慰藉，他们的精神，是再度面对危险时的底气。")
zh(97921,"你采集的草药可制成熏香。你的职业，为依赖魔法的同伴提供休憩与精神的庇护。")
zh(97922,"鞣制皮革可为你遮挡烈日与风雨。学会制作帐篷，将你的职业与旅者对庇护休憩的基本需求相连。")
zh(97923,"采矿可为营地提供磁铁矿。继续训练，能培养出手持武器、应对旅途险阻的同伴。")
zh(97924,"回收的皮革可成为火堆旁的座椅。剥皮能助你在旅途中恢复体力，让同伴始终备好应对挑战。")
zh(97925,"裁缝可为营地制作旗帜。给予同伴一个共同的象征，能在他们重返战场前，提升士气与归属感。")
zh(97926,"巴隆斯无法满足奥伯丁所有的期待：暴风城的金库已空，许多人正陷入困境。将他有限的回信带回桑迪斯。")
zh(97927,"炼金术可为营地提供魔力之泉。你将被引向一位导师，他能教你制作魔力之泉，为治疗者与法术施放者提供清凉解渴的饮品。")
zh(97928,"锻造能为休憩的同伴提供支持。学习打造磨刀石，能确保他们的武器始终为旅途所备。")
zh(97929,"附魔不仅能提升装备，也能改善休憩。一把附魔鲁特琴将音乐与魔法带入营地，助同伴为更远的旅程做好准备。")
