zh(97952,"锻造可助营地中的同伴重装武器，学会打造磨刀石，方能为前路做好准备。")
zh(97953,"附魔可提升休憩与装备，一把魔音琴可为营地带来旋律与魔力，助同伴踏上新征途。")
