zh(97967,"垂钓不止于填饱肚腹，鱼缸亦能抚慰歇息的同伴。他们的灵体在再度迎战前，需得慰藉。")
zh(97968,"你采集的草药可化作熏香，为依赖魔法前行的同伴带来安宁，守护他们的精神。")
zh(97969,"皮革工艺能遮风挡雨，学习制帐篷，让旅人得以安心休憩，满足最原始的庇护之需。")
zh(97970,"采矿可为营地添一罗盘，持续精进，助同伴手持武器，迎战旅途中的险阻。")
zh(97971,"重获的皮毛可制成火边座椅，剥皮不仅助同伴缓解疲惫，更令他们始终备战。")
zh(97972,"裁缝可为营地织一面旗帜，赋予同伴共同象征，提振士气，凝聚归属感，再战前夜。")
zh(97973,"裁缝可为营地织一面旗帜，赋予同伴共同象征，提振士气，凝聚归属感，再战前夜。")
zh(97977,"古树的敌意需要解释。他们离开家园时留下的图腾上，或许刻着他们遭遇的真相。")
zh(97979,"身为暗夜精灵，你继承了露娜的恩赐，既能攻击，也能隐匿。踏上泰达希尔的枝叶之下，先练习这些祝福。")
zh(97985,"制造憎恶的笔记需要一颗庞大的心。风暴之心看似合适，但它的体积与暴躁性格，需要协助取得你联络人继续实验所需的材料。")
zh(98013,"曾经的上层精灵，如今化作娜迦，占据着废墟，可能协助暮光之锤。他们的存在，威胁着森林的未来，你必须直面他们的力量。")
zh(98021,"从异界抵达后，你可协助解决看似微小却深具意义的麻烦。格里安与哨兵岭的人民，正需要你的支持。")
zh(98024,"即使威胁与元素界不同，部落仍面临真实危险。十字路口的人民需要援助，而服务他们，将考验你在艾泽拉斯的能力。")
zh(98025,"贾伊·瓦纳尔开始袭击奥伯丁附近的旅人。理事会需要擒获那只猫头鹰，带回她的一根黑羽作为证据，以证明道路安全。")
zh(98027,"一条银项链上挂着新月，铭文是写给玛琳的。它与别的暗夜精灵信物如出一辙，该去阿斯特兰纳寻她，问明这项链是否归她所有。")
zh(98028,"元素生物留下的水晶球内封存着浑浊的水，某种物质似乎阻止了窥视。这种影响与遗迹仍持续作用；奥努或许能理解这令人不安的现象。")
zh(98042,"撕下暮光之书一页，会有一道声音入侵你的思绪，威胁要夺去你的眼珠。搜寻继续，需寻找一名教派信徒的眼珠，以及愿意接收它的人，地点在奥伯丁。")
zh(98046,"范达尔在水域未找到所求答案，拒绝进一步调查。他遣你前往月光神殿，让女牧师取走容器。")
zh(98059,"希尔斯布莱德的议会无视增援请求，尽管仍保有攻城武器。将请求留在议政厅内，避开怀疑目光，以应对那令人费解的沉默。")
zh(98065,"圣水必须立刻呈献给泰兰德。你的联系人准备了仪式容器，相信高等女祭司会接纳这份发现。")
zh(98067,"达利将艾露恩的恩赐与达纳苏斯的日常守望结合。由于泰达希尔发生了一些令人不安的事，她需要在城中关键地点布置警戒猫头鹰。")
zh(98069,"鹰身人盗走了供应乱风岗的货物。目前剩余物资尚可支撑，但短缺势必接踵而至，除非你从他们西部巢穴夺回那些包裹。")
zh(98070,"鹰身人伏击威胁着乱风岗的商队通行。削弱他们的势力，旨在防止恐惧封锁道路，使定居点失去愿意为其供货的运输者。")
zh(98071,"丹加洛克的酿酒师也想念法尔洛克葡萄酒。一项安排好的交易将把仍存放在地窖中的酒瓶运出，并带回酒花，维系着乡民们的情谊。")
zh(98072,"巨龙幼崽的鳞片比鳄龙贸易更具利润。詹姆斯无法派遣学徒从事这般危险的工作，因此提议你前往东部山丘收集它们。")
zh(98093,"苏拉萨出门走走，土狼与蜥蜴却截断了归路，把她逼上了树。清掉这片地上的野兽，好让她平安回到陶拉祖。")
zh(98094,"你作为信使的可靠赢得了一次新的密令传递任务。将它们送到马索吉手中，能维持被遗忘者夺取这片土地的计划协调。")
zh(98095,"蝙蝠骑手失去指引部队降落的信号。在高处重新装填药剂瓶，让蒸气能再次引导坐骑抵达战略投送点。")
zh(98155,"杂毛土狼的毛色启发了你的联系人，她希望将皮毛寄往暴风城的姐妹们。她本人缺乏战斗经验，需你代为获取制作材料。")
zh(98156,"你的联系人短期内不会返回暴风城，但皮毛如今可寄往她的姐妹手中。将包裹交给凯利与金伯利，完成这份礼物，无需等待那趟旅程。")
zh(98189,"盲眼公主的悲剧打断了珍贵雕像送往米奈希尔的行程。斯托菲本应在此堡接收它；将雕像交给他，才能完成那些运送者未能完成的使命。")
zh(98190,"雕像无法在敌军环伺的港湾中安然无恙，尤其是龙喉氏族。斯托菲队长直接派遣你前往伯瓦尔，由有权威的人决定如何保护这件珍宝。")
zh(98191,"这尊雕像保存着泰瑞纳斯的罕见纪念物，似乎凝聚了圣光之力。伯瓦尔认为大教堂是它最安全的避难所，请求葛瑞森船长代为保管。")
zh(98197,"旧部落舰队曾盗取卡兹莫丹的资源进攻希尔斯布莱德，部分残余仍盘踞在港湾。你可以回收它们，以增强米奈希尔对抗龙喉氏族的势力。")
zh(98208,"诺德·艾尔在海加尔山的月光下绽放，对夜精灵而言意义非凡。一场船难让它遗落在鱼人占领的遗迹中，西莱萨需要从那片危险水域中将其寻回。")
zh(98209,"西莱萨因旅途与初次尝试从鱼人手中夺回诺德·艾尔而筋疲力尽。将诺德·艾尔带到奥伯丁的桑迪斯处，完成这朵圣花的传递。")
zh(98216,"铭文提及一位与石块相连的守护者，提及旧神的字句令人警觉。找到一座大型造物并解读最后的段落，或许能揭示更多，但保全证据可能需要与之战斗。")
zh(98219,"法伦被调往南海镇接受教训，但他的父亲旧友仍希望他能成功。在新岗位上协助他，同时不要忽视那番矫正的必要性。")
zh(98221,"龙喉氏族几番败退之后，又露出重开战端的迹象。斯托菲要查明他们下一个目标：翻看那些进攻图样，看罢便烧，既探得军情，也叫他们动弹不得。")
zh(98223,"这本烧焦的书保存着恶魔灵魂仪式的残页，另添的页面似乎与奈克罗什的行动有关。最近提及暗影议会的记载，必须传递给斯托菲，让他知晓这项发现。")
zh(98230,"蛮锤部族在三锤之战后在此地建立了格瑞姆巴托，但他们的家园未能持久。霍文是首批返回者之一，如今寄居米奈希尔外，或许需要协助。")
zh(98240,"幼龙鳞片的交易已觅得买家。霍文派他的狮鹫送来订单，你须将准备好的补给箱送至东部道路旁，方能完成交易。")
zh(98245,"霍文需编织能抵御龙焰的鳞片，但其坚韧让加工困难。刺喉龙迅猛龙的犬齿或可作工具，穿透鳞片并制备装备。")
zh(98246,"霍文的计划需要他的狮鹫巴斯比克吃饱且性情良好。他须先获得完整且蛋黄饱满的迅猛龙蛋，才能驾驭饥饿暴躁的生物。")
zh(98247,"标签保存着补给箱的来源，却遗失了收件人。商贸当局要求空箱或未完成的货物返回三角路口，并为旅程提供补偿。")
zh(98248,"破损的标签指引受损货物与空箱送往十字路口西边的驿站。杜隆塔尔补给与后勤提供补偿，以酬劳处理其返程之人。")
zh(98251,"瓦克斯在采集草药时被困峡谷，挫败感令他的魔法失控。他请求你清理附近的野生动物，它们的动静只会加剧他的烦躁，阻碍他逃离森林。")
zh(98252,"瓦克斯将借助基尔罗格之眼寻找离开峡谷的路线。引导它抵达道路，趁他尚能维持方向，让幻象持续到尽头。")
zh(98282,"凯特林需在重返毒沼之前获取解毒剂。蜘蛛腺体能提供所需成分，但必须完整无损，以防其内容物外泄。")
zh(98283,"杀戮似乎被疾病侵蚀，连迅猛龙也感到恐惧。雷希耶尔希望终结这种自然秩序的混乱；病态熊肉能引动比斯巨兽现身巢穴。")
zh(98284,"附魔不仅能强化装备，也能提升休憩效果。一把附魔鲁特琴可为营地带来音乐与魔法，助同伴为远行做好准备。")
zh(98285,"隐士认为工程师的巧思也应运用于荒野。他待你积累经验后，再传授进阶技巧，助你打造实用造物，让旅途更添助力。")
zh(98286,"附魔不仅能强化装备，也能提升休憩效果。一把附魔鲁特琴可为营地带来音乐与魔法，助同伴为远行做好准备。")
zh(98287,"工程学可助法师获取所需材料。学会打造补给自动体，让营地成为众人协作准备的据点。")
zh(98291,"霍文欲重返格瑞姆巴托，夺回家园或探查其现状。龙喉士兵封锁所有通路，他需先削弱敌军，方能推进此计划。")
zh(98293,"龙喉氏族正囤积兵器，这些家伙足以再武装一批兵卒。趁尚未分发便夺了过来，既能削他们的备战，东西也落到斯托菲手里，尽可派上用场。")
zh(98297,"霍文目睹龙喉氏族将红色龙人束缚起来，拒绝再经历一次奴役轮回。需要盟友阻止术士，终结他们囚禁的生物所承受的苦难。")
zh(98298,"锁链表明阿鲁高掌控着狼人，却未能解释诅咒如何蔓延。达拉尔需收集靠近格雷迈恩之墙的野兽残骸，以研究传播方式。")
zh(98299,"研究如何阻止诅咒的同时，达拉尔也想遏制其在格雷迈恩之墙人类中的扩散。他下令屠杀难民，以免他们被阿鲁高利用。")
zh(98300,"霍文仍忙于蛮锤部族事务，但麦格尼必须了解近来发生在自己领地上的事。这封信将警告铁炉堡的国王，无需等待湿地未完成的调查。")
zh(98310,"四尊大型石像鬼的名字，恰好对应戈兹石缺失的部分。若能从这些造物身上取得碎片，或可揭示更多铭文，使调查线索散落在湿地各处。")
zh(98313,"你的联系人无法独自解决这些发现。将它们带到卡尼克手中，便能借助探险者大厅的专业知识，展开一场需要更大规模研究的探索。")
zh(98319,"雪怪已攻占灰色洞穴，康拉德冲了进去。格雷彻需要找到搭档，以掌握洞穴的状况，并继续报告这日益增长的威胁。")
zh(98321,"矿工们在逃亡时丢下了矿石，躲避占据洞穴的雪怪。托格斯的补给已告罄，急需从灰色洞穴夺回物资。")
zh(98322,"森内尔尚未收到派往山地调查雪怪的探子消息，报告也积压已久。他需要你去查看格雷彻·沃格尔在卡拉诺斯西边的近况。")
zh(98323,"洞穴太过危险，无法再派更多人进入，而关于柯内利乌斯的消息也令人沮丧。格雷彻必须在坚守岗位的同时，将这份评估送交白须。")
zh(98326,"霜嚎洞穴偷走了格雷塔与丈夫在冰湖上苦寻数日的鱼获。他们需要夺回渔获，而非耗费数周艰难垂钓来弥补。")
zh(98340,"你的进展使进一步的德鲁伊训练成为可能。德迪利特已在月光林地等待，将引导你学习的下个阶段。")
zh(98341,"来自你故乡的猫科灵体现身，将教导泽弗拉斯自身的形态。前往月光林地寻找它，并接受德鲁伊试炼，方能习得此种形貌。")
zh(98342,"化为巨豹之灵需机敏、隐匿与凶猛。三件由暴怒灵体守护的圣物将考验这些特质；一座雕像可助你悄然通过。")
zh(98362,"你所学的技艺，如今必须付诸实践与图拉克。返回你的导师，继续向巨豹之灵的形态迈进。")
zh(98372,"一名夜巡哨兵死于巨兽的袭击，手中握着一支未点燃的火把。拾取它，或许能助你揭开黑暗中隐藏的秘密。")
zh(98386,"狼蛛的侵袭阻碍了工人抵达奥瑟尔伐木场，也加剧了桥梁工程的延误。奥斯洛需要尽快恢复安全的木材供应，否则下一个障碍将毁掉他的期限。")
zh(98387,"黑石氏族需要武器与补给以维持攻势。马瑞斯想趁虚而入，袭击他们的营地，夺取支撑战争的资源。")
zh(98389,"阿拉米斯希望亡灵圣骑士通过保护赢得信任。解放被蜘蛛困住的新近亡灵，将这份承诺转化为那些畏惧你秩序者的实际援助。")
zh(98391,"月神教派引导与治愈卡多雷千年，如今需要你的协助处理一件要事，指引你前往达纳苏斯的艾奎恩妮。")
zh(98392,"腰带的皮革上沾着来路可疑的污秽。鹰身人首领的护身符或许能指认源头，把那些护符取回来，比一比各自带着的黑暗。")
zh(98393,"另一道召唤将你引向月光林地。既然已掌握抵达此处的魔法，便可继续德纳特里亚的德鲁伊教学下一阶段。")
zh(98394,"化为猎豹形态，需向灵体学习，也需掌握魔法。追寻那伟大的猫科灵体，延续德鲁伊对动物的深层理解。")
zh(98396,"单凭遇见灵体尚不足以化形，须以隐忍、机智与狠厉证明自身，从怒目相向的守护者手中夺回三件圣物，暂借雕像之力方能成事。")
zh(98397,"德迪利特认为你的准备已足够，可返回玛斯雷处继续修行。归返达纳苏斯，将所学化作通向猎豹形态的下一步。")
zh(98398,"先知之树刚剥落一段树皮，这是它赋予使命的征兆。你先前的作为已证明，你足以面对接下来的试炼。")
zh(98403,"西索尔似乎引导迈雷纳斯，并操控蜘蛛以毒液为刃。击败他的族群，寻觅能解释萨特所为的证据。")
zh(98404,"化身需经试炼方能显现猫形，墓冢中的圣物需以隐忍、机智与狠厉应对敌对灵体方能得手。")
zh(98405,"巨豹之灵指引渴望化形的德鲁伊，前往南方月光林地寻求其智慧，方能更进一步。")
zh(98407,"豺狼人日益逼近人类聚居地，菲尔顿副队长认为展示力量并夺取其最强战士的战利品，或可阻止他们继续前进。")
zh(98417,"萨特的屠杀与亵渎激怒了库罗瑟，他随德鲁伊踏入战场。玛赛拉感知丈夫仍驻足西方，亟需他的下落。")
zh(98418,"库罗泰尔的话语揭示了一场与痛苦变形交织的挣扎。玛赛拉认为，若能削弱驱使他暴怒的恶魔，或许能缓解他的痛苦，因此请你去面对萨维亚的山羊人。")
zh(98423,"一块石板记载了青铜须与野锤之间缔结的盟约，似乎可追溯至三锤之战之后。这份可能具有历史意义的文献，让麦格尼·铜须成为接收它的合适人选。")
zh(98424,"菲兹普罗克分别保管的书页似乎包含对抗风险湾公司的有用情报。在返回摩林之前，务必要寻回其余部分，让这次发现发挥最大价值。")
zh(98427,"一台切割机能在数日内摧毁庇护大地之母子民的森林。摩林必须在它摧毁家园之前，阻止这台机器。")
zh(98430,"佩里思被卡恩恩派来作为斥候，与豺狼人交涉，却遭到暴力回应。他如今害怕成为他们的猎物，急需援助脱身。")
zh(98435,"雷霆崖的长老们需要知道你在协助下取得的进展。雷角族将一份报告送往哈穆尔，让消息传达到人民的领袖们。")
zh(98459,"汤姆咬定巴特假冒船长、在牌桌上出千。他托你把这份礼物送去米奈希尔，并亮明送礼人的身份——算是捎去一句提醒，他的怨气未消。")
zh(98461,"霍莉与塔雷尔曾一同求学，后各自踏上不同道路。即便他已成家，她仍对他心存眷恋，托你带去书信并探望他，地点在湿地。")
zh(98463,"酒馆里的传闻指向藏宝海湾一场热闹的聚会。你的线人建议前往咸鱼水手与尼克拉克斯，亲身体验这座城市社交生活的另一面。")
zh(98471,"首席魔导师下达了最高优先级的召见，要求你严守秘密。独自前往奥特兰克山脉，那里的秘密会议将揭示尚未解释的任务。")
zh(98512,"巡逻队发现阿尔·阿凯斯正徘徊于边境屋舍附近。他们的计划尚不清楚，但你必须在盟友掩护下阻止他们。")
zh(98517,"灵体认为你已准备好回应烈焰的召唤。那训练属于你的故土导师，所以返回泽弗拉斯，开始你的旅程。")
zh(98545,"莱尼德希望将一封信交给幽暗城的老友，却不愿触怒那里的官僚。你作为中间人，让他的过往与希尔瓦娜斯无涉。")
zh(98574,"你在此地奔走相助时，有人送来一封便笺。看笔迹，是牧师训练师布兰斯托克所书——读罢，去寻他，听他亲口把话说尽。")
zh(98575,"一块石板抵达，似乎来自你的新任术士导师纳托克。读信后，当他召唤你时，与他交谈。")
zh(98576,"魔法导师梅娅似乎在你外出时寄来了一张羊皮纸。读信后，去找你的导师，回应她想与你交谈的意愿。")
zh(98581,"交付的符文刻有野锤族风格的铭文，似乎来自萨满导师提奥。解读其中讯息，前往安威玛尔寻找他回应召唤。")
zh(98601,"萨维斯将你送往阿拉米斯，开始亡灵圣骑士的训练。他对光的戒备，揭示了你在重拾使命途中必须面对的不信任。")
zh(98731,"巨豹之灵的祝福标志着这堂课的终结。返回德迪利特，他将指引你成为德鲁伊的下一步。")
zh(98738,"萨埃莱娜的化身已结束你的教学，遣送你回德迪利特。待接受祝福后，再向他寻求进一步指引。")
zh(98739,"你已获得灵体的祝福，其教导暂告一段落。德迪利，必须由他指引你德鲁伊之路的下一步。")
zh(98815,"一支探险队正在调查高原遗迹，那里也栖息着皮毛珍贵的野兽。你的联系人提议与装备精良的同伴一同深入，换取猎取迅猛龙皮的报酬。")
zh(98823,"这件神器似乎远不止是一件雕塑。大地之环或许能理解它与埋藏遗迹及失落之地的关联，将它带往穆恩处研究，以匹配这次发现的重要性。")
zh(98824,"棱镜上看似庞大的铭文使其值得探险者大厅收藏。将其带往麦格拉斯处，让博物馆研究并保存这件维尔加视作非凡的发现。")
zh(98887,"塞拉摩持续派遣援军巩固其在黑暗之矛群岛的据点。部落要求以战场功勋回应这股坚持，并以此证明你的努力才值得嘉奖。")
zh(98888,"部落通过你在那片战场上的荣誉印记，认可你在黑暗之矛群岛的贡献。")
zh(98889,"塞拉摩的援军不断加固其在黑暗之矛群岛的阵地。部落召唤已证明的胜利，以回应这股压力，并嘉奖在此战场上的功绩。")
zh(98891,"塞拉摩仍在持续派遣援军，巩固其在黑暗之矛群岛的据点。为部落而战，并呈上胜利的证据，方能回应这股压力，于关键战场立下功勋。")
zh(98893,"塞拉摩仍在持续派遣援军，巩固其在黑暗之矛群岛的据点。为部落而战，并呈上胜利的证据，方能回应这股压力，于关键战场立下功勋。")
zh(98895,"对抗黑暗之矛突袭队的战斗愈演愈烈，塞拉摩担忧会失去海岛。联盟亟需援助与前线贡献的证明，以维系它不愿放弃的阵地。")
zh(98896,"联盟准将接受你在黑暗之矛群岛战场上获得的荣誉印记，作为你参与这场战役的证明。")
zh(98897,"黑暗之矛突袭队的威胁正动摇联盟在海岛的据点。急需援军与前线功绩的证明，以表彰那些坚守此地的人。")
zh(98899,"对抗黑暗之矛突袭队的战斗威胁着联盟在海岛上的立足之地。急需援助与前线服务的证据，以表彰那些维系此地安全的战士。")
zh(98901,"对抗黑暗之矛突袭队的战斗威胁着联盟在海岛上的立足之地。急需援助与前线服务的证据，以表彰那些维系此地安全的战士。")
zh(98903,"塞拉摩远征队请求你代表他们出征黑暗之矛群岛。他们的诉求是为联盟赢得胜利，展现部队对抗部落存在的力量。")
zh(98904,"塞拉摩远征队以你的名义在黑暗之矛群岛发起战斗。胜利的意义在于彰显联盟对抗部落存在的力量。")
zh(98905,"塞拉摩远征队以你的名义在黑暗之矛群岛发起战斗。胜利的意义在于彰显联盟对抗部落存在的力量。")
zh(98906,"黑暗之矛群岛的战斗陷入僵局。黑暗之矛请求你捍卫他们的立场，以胜利打破平衡，借你服务展现力量，于洛阿众神注视之下。")
zh(98907,"黑暗之矛群岛的战斗陷入僵局。部落需要一场胜利打破僵局，彰显那些在黑暗之矛麾下奋战之人的力量。")
zh(98908,"黑暗之矛群岛的战斗陷入僵局。部落需要一场胜利打破僵局，彰显那些在黑暗之矛麾下奋战之人的力量。")
zh(98910,"你赢得黑暗之矛突袭队的信任，得以获得一份基础补给包，支持你在他们战役中的行动。")
zh(98913,"你与塞拉摩远征队保持友好关系，得以获得一份基础补给包，支持你在他们战役中的行动。")
zh(98977,"拜访齐长老莫斯心，可参与庆典的致敬仪式，并获得一枚先祖硬币。这份馈赠象征着对先祖之魂的敬意。")
zh(98983,"与齐长老福斯特寒暄，可参与庆典的致敬仪式。这份馈赠是对你拜访先祖之魂的回报。")
zh(99046,"哨兵们将神谕者之树的讯息送往达纳苏斯，但最新传信人尚未抵达。埃拉莉亚仍在训练，你必须查明她去了何处。")
zh(99047,"埃拉莉亚在执行任务时遭遇了夜枭，血肉模糊仍强撑着说话，唯恐时日无多，她恳求你去找拜恩希。")
zh(99048,"一名碎手高地的特工在监视提拉加德时停止了汇报，沉默或许预示着更大威胁，也可能只是消息延迟；你必须调查究竟发生了什么。")
zh(99049,"赫格兰周围留有搏斗痕迹，显然袭击者也受了伤。寻找他们留下的踪迹，让奥戈尼尔辨明威胁来源。")
zh(99050,"拜恩希需要暂时控制艾拉雅的病状，等她回来接受治疗。泰达希尔的嫩叶、清水和一个药瓶，就能制成解药。")
zh(99051,"纳迦斥候再度威胁此地。奥戈尼尔希望他们的营地被摧毁，并要求用鱼鳍证明行动迅速，表明他们不受欢迎。")
zh(99052,"一只海巨人跟随纳迦来到海岸。虽年幼，却能轻易致命；集结援手，阻止这个新威胁。")
zh(99053,"林莎在传递神谕者之树的信息途中，被熊怪俘虏。她被困地下，性命堪忧，亟需援手脱困。")
zh(99073,"药膏已备齐，但拜恩希不知它能否治愈艾拉雅蔓延的腐烂。即使只能缓解痛苦，也必须尽快送到她手中。")
zh(99079,"马拉赫被派往东部边境，却未能如期返回。为保护村庄，你必须调查卡恩的信使现状。")
zh(99080,"贝恩希望在盗贼团伙休整、袭击村庄或召唤援军之前将其摧毁。斩下首领的头颅，以警告其他觊觎祖先领地的家伙。")
zh(99081,"马拉赫背上的箭头指向莫高雷的一处新兽人营地。她的报告仍握在手中；野蹄必须查明她的命运与杀她者带来的威胁。")
zh(99082,"你为百姓而战，理应得到肯定。贝恩·布勒勒格鳍派你前往凯恩·血蹄处，他当年协助人类夺回这片平原，如今要亲自表彰你的功绩。")
zh(99101,"贝恩正领导村庄，必须立刻得知半人马的入侵。马拉的报告包含你需要尽快传达的重要消息。")
zh(99108,"唐认为实战能教化任何非战士之人。他的角斗场让新手或愿意切磋的对手同台竞技，公平决斗。")
zh(99123,"帕朱赫独自侦查科卡尔峭壁，却在最危急时刻魔力尽失。他自此隐匿不出，亟需援手脱困。")
zh(99127,"水中的鱼踪全无，钓钩空悬。夜间布下的陷阱或许能揭示真相，检查后上报异常情况。")
zh(99128,"杰森归咎鱼人导致鱼群枯竭。他希望减少湖中鱼人数量，否则渔业将彻底消失。")
zh(99129,"杰森认为雷米同样憎恶鱼人，或许知晓驱逐之法。向他请教，或能找到阻止冲突的途径。")
zh(99130,"雷米提议用毒性花瓣的野草作饵。既可驱离鱼人，又能清理农夫田间的杂草。")
zh(99131,"雷米已备好杰森的诱饵，并会说明正确用法。将消息带去，让渔夫重振生意，减少鱼人麻烦。")
zh(99134,"塞加德认为数名死亡守卫表现令人无法容忍。他指派你惩戒他们，因你尚未令他失望，若行动迟缓，他便将你的名字记入账簿。")
zh(99141,"执行官已对拖延的死亡守卫报告失去耐心。巡视哨站能获取他所需情报，以监督众人是否遵从黑影女领主的命令。")
zh(99142,"霍兰德在巴尼尔农场改种并重新栽种末日草。你需回收他新培育的植物样本，其对天灾的莫名吸引力，使这场实验令人担忧。")
zh(99143,"你的线人认为鱼人与鱼类同样被某些事物吸引。计划是用他们营地的闪亮物品作诱饵，验证这一假设。")
zh(99144,"巴雷斯携带班达里昂要塞送往布瑞尔的信上路，半途被擒。掳他之人以圣光为名，行仇恨之实，他不肯附从，只求有人助他脱身、续完这趟路，并带句话给沙莉，报一声平安。")
zh(99152,"影谷的地窖可能成为天灾进攻要塞的起点。希尔达需要带有魔力的骨头，以研究威胁并训练她的追随者。")
zh(99153,"一名狂热者携带着尚有力量的纳克萨玛斯水晶逃走。艾弗拉姆怀疑水晶藏于影谷之下，正强化亡灵；若能找回，便可避免另一场危机。")
zh(99156,"憎恶突破亡灵壁垒，悄然抵达东部提瑞斯法。林奈需秘密摧毁它，因其存在暗示了对抗天灾军团的防线存在严重漏洞。")
zh(99158,"伽文神父将一座建筑改造成旅人庇护所，更倾向疗愈而非战斗。圣洁蜡烛需送达那座山中的静息之所。")
zh(99159,"伽文神父的炉火始终为需要者敞开，但其他职责使他无法亲自采柴。助他维持这盏温暖庇护所的火光。")
zh(99160,"岩与冰的崩落惊扰了元素生物。山道本已险峻，伽文需将这新威胁化解，方能令道路重归安全。")
zh(99161,"阿瓦拉是岩崩后首个现身的元素生物，似乎能引发天气变化与更多崩落。制止它，并取回其核心作为证据。")
zh(99162,"雪与冰吞噬了登山者的性命，但元素生物阻止搜寻遗体。伽文需取回他们的步枪，好送回铁炉堡。")
zh(99191,"高阶议会现急需六十件羊毛。这份捐赠是慷慨之举，可赢得成员的认可与尊重。")
zh(99192,"装备法师严重消耗了议会的丝绸储备。捐赠六十件丝绸，可补足库存，亦能提升你在成员中的声望。")
zh(99196,"风塑者接受六十份羊毛的捐赠。这项提议让你能通过运送布料来满足他们的需求，并为你的慷慨赢得认可。")
zh(99197,"奥拉为风塑者提供六十份丝绸的捐赠。这项任务让你能将布料献出，并在组织成员中赢得声誉。")
zh(99260,"菲利翁失去了指引船只往返天空之墙与艾泽拉斯的元素能量数据。无法找回它，他将你送往艾拉德林，他希望在营救之后与你相见。")
zh(99267,"夜守者的伤口显示他曾遭遇大型野兽的袭击。他指间的火把仍未点燃，若能取来，便能揭开森林黑暗中隐藏的秘密。")
zh(99411,"凯雷逃走了，阿哈布担心他在村中迷路且饥饿。他最爱的陆行鸟肉能安抚小狗，鼓励它重返家园。")
